pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear shaping (favor tight fits, penalize mid residuals)
    let mut score = pr - 18.0 * (1.0 - norm_pr) * norm_pr * cap;

    // Polynomial coupling with stream progress: tighter packing valued more later
    let tightness = 1.0 - norm_pr;
    score -= (14.0 + 22.0 * progress * progress) * tightness * tightness;

    // Smooth penalty on residual relative to next item lookahead
    if next_item_size > 0 {
        let fit_next = (pr >= next_item_size as f64) as f64;
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * fit_next * (1.0 - gap / cap);
        score += 6.0 * (1.0 - fit_next) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild regularization toward mean residual state
    score += 0.08 * (pr - mean_residual).abs();

    // Slight preference to fill existing bins over opening new ones
    score += 0.5 * (bin_residual as f64 - pr) * 0.0; // no-op guard
    score += 4.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.6 * open_bins_count as f64;

    // If the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item.
        score += 10.0;
    }

    // Compare against mean residual: bins with much less residual than average are tighter fits.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when residuals are fragmented / item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 10.0 || fitting_bins_count == 0 {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately useful gap: mild penalty relative to raw residual ordering
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    } else if post_residual > 20 && post_residual <= 40 {
        // Usable gap for mid-size items: slight reward
        score -= 5.0;
    }

    // If the bin can still fit the lookahead item after placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If placement leaves a gap just below the next item (near-dead space), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly discourage opening yet another bin unless fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // New-bin candidate: only attractive when this bin's residual is very
    // tight (item barely fits) or dead space would be created.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).min(1.0);
        // Large items prefer a fresh bin; small items should reuse open bins.
        score = score * 0.0 + 25.0 - 30.0 * tightness;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // lookahead pairs well with a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative exists
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (compact packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_frac * fit_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below mean (fragmented bins),
    // unless this placement improves them.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item exactly consumes post_residual.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Mild penalty: this placement strands the lookahead item here.
            score += 5.0;
        }
        // Penalize leaving a residual just below the next item size (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // few bins fit the item or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let mut new_bin_score = 30.0;
        // Discourage opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= 20.0 * progress;
        // More attractive when many open bins but few can fit the item.
        new_bin_score -= 2.0 * (open_bins_count as f64 - fitting_bins_count as f64);
        // Discourage when mean residual is large (plenty of room exists).
        new_bin_score += 0.25 * mean_residual;
        // Large items justify new bins more.
        new_bin_score -= 0.2 * item_size as f64;
        score = score.max(new_bin_score.min(score)) ;
        score = new_bin_score + (score - new_bin_score) * 0.0 + 0.0;
        score = new_bin_score;
    }

    // Small tie-breaker toward bins with lower residual (fill emptier bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 * (-tightness).exp();

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or mean residual is tiny.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64) * 0.2;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: favor bins leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Mild stream progression coupling: prefer consolidation early, allow new bins late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover dead space after both placements
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - two_step_waste as f64;
        } else {
            // next item cannot use the remaining space: penalize tight leftovers
            let slack = (next_item_size - post_residual) as f64;
            score += slack * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space) relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Reward filling bins that are already below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if next item is large and current residuals are small, new bin is fine
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 90.0;
        }
    }

    // Late in stream: slightly favor compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable by items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }
    // Moderately small gaps are risky too (most items 10..80 won't fit).
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would not fit post-residual, mild penalty unless gap is tiny.
    if next_item_size > post_residual && post_residual >= 25 {
        score += 8.0;
    }

    // New-bin candidate: attractive when open bins are fragmented or fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score -= 20.0 + fragmentation * 0.5 + open_bins_count as f64 * 0.8;
        // But discourage new bins when a tight fit exists.
        if post_residual == 0 { score -= 0.0; }
        if fitting_bins_count <= 2 && item_size >= bin_capacity / 2 {
            score += 25.0; // big item: better to use an existing fitting bin
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that could fit the lookahead item exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            score -= 6.0 * (1.0 - (pr - nr) / bin_capacity as f64);
        } else if pr > 0.0 {
            score += 4.0 * (nr - pr); // wasted potential vs lookahead
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += pressure * 0.5;

    // Prefer bins tighter than the mean residual (better packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for filling fuller bins.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item-size divisors are more likely to be filled by later items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        40.0 // perfect fit
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else if pr % 2 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: tiny unusable remainders are worse than mid ones.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize lightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // New-bin candidate: make it moderately attractive only when the stream
    // is early or current bin fits are poor; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 18.0 + 25.0 * (1.0 - progress) - 2.0 * openness;
        if mean_residual > 30.0 {
            score -= 8.0; // open bins are roomy, reuse them
        }
    }

    // Mild mean-residual alignment: bins close to the mean are "typical"
    // targets; keep them attractive to consolidate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold on next_item_size class.
    if next_item_size >= 50 {
        score += 2.0; // big next item: keep small residuals for it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 10.0; // gaps below the minimum item size are pure waste
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 30.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Non-linear penalty: convex in wasted fraction of the gap.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize more if it's below min size.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost, modulated by how bad existing options are.
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100),
    // but practically we treat gaps < 25 as hard to reuse.
    if post_residual > 0 && post_residual < 25 {
        score += 60.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling: dead space penalty amplified when many bins are open (pressure to consolidate).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if post_residual > 0 && post_residual < 25 {
        score += 15.0 * pressure;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item does NOT fit post residual, mild penalty for wasting the lookahead slot.
    else if next_item_size > 0 && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading into new bins when few remain to place,
    // mild bonus for using already-open bins generally.
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New bin candidate: penalize unless current bins are quite full.
        score += 10.0 + 5.0 * pressure * (mean_residual / bin_capacity as f64);
    }

    // Progress: as stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but modulate by harmonic classes.
    if post_residual == 0 {
        score -= 200.0; // perfect fit is always best
    } else {
        // Class of post_residual by integer division thresholds (dead-space classes).
        let pr = post_residual as f64;
        let pr_class = post_residual / 10; // 0..=9 harmonic class
        // Penalize dead space non-linearly: residuals in "unusable" ranges
        // (too small for typical items 1..100) are worse.
        if post_residual < 10 {
            score -= 60.0; // dead space, unusable
        } else if post_residual < 25 {
            score -= 25.0;
        } else if post_residual < 50 {
            score += 5.0;
        } else {
            score -= 10.0; // roomy residual still useful
        }
        // Modulo coupling: residuals divisible by common item sizes pair well
        // with a lookahead item of matching residue.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 150.0; // sets up a perfect fit next step
            } else if next_item_size <= post_residual {
                score -= 10.0;
                // harmonic alignment: post_residual % next_item_size small
                let m = post_residual % next_item_size;
                if m < 10 {
                    score -= (10 - m) as f64;
                }
            } else {
                score += 15.0; // next item won't fit here either; residual likely wasted
            }
        }
        // Fraction-of-capacity classes for the item itself.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.8 {
            score -= 20.0; // large items: place them, close bins fast
        } else if frac < 0.2 {
            score += 10.0 * (1.0 - frac); // tiny items: prefer bins with little room
        }
        // Last-chance bin: strongly reward using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        } else {
            // spread across bins: prefer bins with residual below mean (consolidation)
            score += (mean_residual - pr) * 0.3;
        }
        // Late in stream: consolidate harder, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins: favor filling existing ones over new-bin candidate.
        score += open_bins_count as f64 * 2.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only attractive if item is large or no good existing fit exists.
        score = 100.0
            - (item_size as f64) * 0.5
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= ~15) are "dead". Penalize heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 30 {
        // Small gap zone: moderate penalty, worse the smaller the gap.
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Perfect fit: nearly zero residual.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading; prefer
    // filling existing bins, penalize opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + progress);

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else or residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened by how bad the current
        // mean residual situation is and by open-bin pressure.
        let fragmentation = 1.0 - (mean_residual / (bin_capacity as f64)).max(0.0).min(1.0);
        score = bin_capacity as f64 * 0.5
            + post_residual as f64 * 0.3
            - fragmentation * 30.0
            - pressure * 0.4
            + 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score += 100.0;
        }
    } else {
        // Lookahead: if next item fits exactly in the post-residual, reward.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps in [10,20) can only accept tiny items; penalize proportionally.
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already below average (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Lookahead: if next item fits exactly in the post residual, bonus; if post residual
    // is large and next item leaves another dead gap, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0;
        }
    }

    // Late in the stream, be more conservative: avoid creating any new dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && post_residual > 0 && post_residual < 15 {
        score += 20.0 * progress;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when all open bins look bad.
    if bin_residual == bin_capacity {
        score = 70.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when exactly one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a chain fit — strongly favor it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space
            // scaled by how small the unusable gap is relative to the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 30.0 * (1.0 - dead / bin_capacity as f64).max(0.0);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual well below the mean creates an outlier bin that
    // is hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 0.5 * item_size as f64;
    }

    // Penalize using a nearly-full bin for a tiny item (waste of a scarce slot).
    if item_size < 20 && bin_residual < 40 && bin_residual != bin_capacity {
        score += 40.0;
    }

    // Early in the stream, be slightly more willing to open new bins
    // to build a diverse residual pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: its base score is the capacity; adjust.
        score -= 200.0 * (1.0 - progress);
        // If no open bin fits well, new bin is attractive.
        if post_residual == bin_capacity {
            score -= 0.0;
        }
    }

    // Slight preference for filling bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // penalize leftover that doesn't serve the next item proportionally
            let waste = (post_residual - next_item_size) as f64;
            score += 0.35 * waste;
            // reward if next item leaves a tiny residual too (chained fits)
            let post2 = post_residual as f64 - nxt;
            if post2 < 10.0 {
                score -= 12.0 * (10.0 - post2);
            }
        } else {
            // next item cannot use this bin's remainder: dead-space risk
            score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize very small unusable residuals (dead space), unless it's a perfect fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfectly closed bin is excellent
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        let poor_fit = post_residual as f64 > mean_residual * 1.5;
        if crowded || poor_fit || open_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 40.0; // discourage spreading items across fresh bins
        }
    }

    // Early in stream: slightly favor consolidation; late: avoid tiny leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // exactly into the post-residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect match: next item seals this bin
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a leftover; penalize leftover dead space
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.25 * leftover;
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins whose residual is already below mean residual (denser bins),
    // i.e. reward placing into tight bins, penalize sparse ones.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (dead space below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else. An empty bin starts with full residual, so its raw
    // score is high; give it a bonus so it wins when fits are bad, but not
    // when a good fit exists (good fits already get large subtractions).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 + 10.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins when item is small.
    if item_size <= 30 && open_bins_count > 5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit classes (residual divisible by
    // small harmonics) are more likely to be filled by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit is ideal
    } else {
        // harmonic divisibility ladder
        let mut div_bonus = 0.0;
        if pr % 10 == 0 { div_bonus += 40.0; }
        if pr % 20 == 0 { div_bonus += 30.0; }
        if pr % 25 == 0 { div_bonus += 25.0; }
        if pr % 50 == 0 { div_bonus += 35.0; }
        score -= div_bonus;

        // dead-space penalty for tiny unusable residuals
        if pr < 10 {
            score += 120.0;
        } else if pr < 20 {
            score += 40.0;
        }

        // lookahead coupling: if next item fits exactly in the post residual,
        // strongly reward this bin
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                let pair_waste = pr - next_item_size;
                score -= 60.0_f64.max(0.0);
                score += pair_waste as f64 * 0.8;
                // harmonic class of the pair
                if pair_waste % 10 == 0 { score -= 25.0; }
            } else {
                // next item cannot follow here; penalize slightly if this bin
                // would then be stranded
                score += 15.0;
            }
        } else {
            // last item: prefer minimal residual
            score += (pr as f64) * 0.5;
        }
    }

    // last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // new-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - 0.3 * progress);
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 30.0; // new bin can host current + next
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin
        }
    }

    // mild preference for tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // discourage scattering across many open bins when residuals are large
    if open_bins_count > 3 && bin_residual >= item_size * 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual shaped by stream progress.
    let shape = 1.0 + 0.6 * progress - 0.8 * progress * progress;
    score *= shape;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (norm_pr * (1.0 - norm_pr)) * cap * (0.15 + 0.35 * progress);

    // Penalize dead space quadratically when residual cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.5 * progress) + 0.25 * (nxt - pr) * (nxt - pr) / cap;
        } else {
            // Smooth reward for leaving room exactly usable by the next item.
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 2.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Deviation from mean residual: prefer bins below mean (consolidating large gaps).
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev - 0.5 * dev;

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += 0.1 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: prefer opening a fresh bin only when it wastes little
    // relative to item size and few bins fit the item.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score = cap * waste * waste + 4.0 * waste;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by item size
    // so that big items get placed preferentially into tight spots.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item's size (perfect chaining), punish large mismatches.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        // Perfect match bonus: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item fits in the post residual, mild reward (keeps chain going).
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // If next item won't fit here but would fit elsewhere, penalize leaving
        // a small awkward residue.
        if post_residual < next_item_size && post_residual < 10 {
            score += 12.0;
        }
    }

    // Relative to mean residual: bins with residual below mean are more
    // "prime" for filling; placing here consolidates space.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.6 * (resid_f - mean_residual);
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.2 * (item_size as f64);
        if post_residual > 40 {
            score += 20.0; // terrible fit, maybe new bin is better
        }
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit in any open bin would be poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; becomes attractive when many bins
        // are open but residuals are small/fragmented.
        score = 55.0 - 0.5 * (open_bins_count as f64) + 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can always serve the next item too
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // don't open new bin if only one fitting bin exists
        }
    }

    // Late in the stream, tighten up: avoid leaving many near-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match leaves zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize post_residual that is large enough to fit the next item but wastefully so
        // (item would float in a big gap), and penalize leaving a gap the next item cannot use.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.8 * slack;
        } else {
            // Gap unusable by next item: penalize proportionally to how "dead" it is.
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins fill up,
    // keeping loose bins available for awkward future items).
    score += 1.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the current fit is bad
    // (large post_residual) and there are many open bins.
    if bin_residual == bin_capacity {
        // Fresh bin score: moderate baseline, better than a very poor fit, worse than decent fit.
        score = 55.0 - 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 10.0; // discourage new bin if next item is smaller (could pair in old bin)
        }
    }

    // Early stream: be slightly more willing to open bins (build structure), later: tighten.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps that nothing can use are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range unusable gaps (below min item size 1..=100 -> anything < ~10 is risky)
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading when many bins open
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let lookahead_waste = if next_item_size > 0 && next_item_size > poor_fit as u32 { 30.0 } else { 0.0 };
        score = 25.0 + poor_fit * 0.3 + lookahead_waste
            + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a new bin is fine when alternatives are scarce... but keep bias to reuse
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits in post_residual, mild reward
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot use post_residual, penalize leaving that gap
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: post_residual too small for any realistic item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize medium-small gaps that likely can't fit future items
    if post_residual >= 10 && post_residual < 40 {
        score += 0.5 * (40.0 - post_residual as f64);
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // New-bin candidate: neutral baseline with mild penalty, only preferred when fits are bad
    if bin_residual == bin_capacity {
        score = 45.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mild penalty scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.15 * miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: bins far below mean are good targets.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.1 * dev;

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, be greedy and fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * tightness;

    // New-bin candidate: only attractive when it beats chaining potential,
    // i.e., when existing residuals are all poor fits for current + next item.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let next_bonus = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        // Prefer new bin when open bins are nearly full on average and next item is large.
        score += 45.0 - 0.5 * open_pressure - 0.2 * next_bonus - 40.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // item (1..=MIN_USEFUL) are pure waste; penalize them hard.
    let min_useful: f64 = 12.0;
    if (post_residual as f64) < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual as f64);
    } else {
        // Gradually reward leaving a gap that can still serve a future item.
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.5));
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose current residual was already small (tight packing).
    score += 0.6 * (bin_residual as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few
    // are open, filling them well is fine.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; leftover gap likely dead space.
            score += 12.0;
        }
    }

    // New-bin candidate: attractive early / when open bins are poor fits,
    // unattractive when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        let pressure = 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        score = bin_capacity as f64 * 0.55 + pressure - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which eighth of capacity remains
    let class = (post_residual * 8) / bin_capacity.max(1); // 0..=7
    // Dead-space penalty grows superlinearly for small unusable residuals
    let dead_threshold = bin_capacity / 10; // residuals < 10% are near-dead
    if post_residual < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 100.0; // perfect fit is best
    }

    // Lookahead compatibility: does next_item_size fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability bonus scaled by how snugly the next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 25.0 + 30.0 * snug;
            // Harmonic match: next item lands in the same residual class
            let next_class = ((post_residual - next_item_size) * 8) / bin_capacity.max(1);
            if next_class == class {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we don't place current item here:
            // mild penalty for stealing that opportunity
            score += 8.0;
        } else {
            // Next item won't fit either way; prefer conserving residual space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fills
        score += 3.0 * (fitting_bins_count.min(8) as f64);
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow opening fresh bins less reluctantly;
    // late in the stream, squeeze existing bins harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / cap_f);

    // New-bin candidate (empty bin): penalize unless residual would be huge waste
    if bin_residual == bin_capacity {
        score += 35.0 - 0.1 * item_size as f64;
        // Opening a new bin is attractive when few bins are open and item is large
        score -= (open_bins_count.min(20) as f64) * 1.2;
    }

    // Modulo harmonic classes on post_residual: reward residuals that are
    // multiples of common item sizes (likely reusable chunks)
    let pr = post_residual;
    if pr >= 20 && (pr % 20 == 0 || pr % 25 == 0 || pr % 30 == 0) {
        score -= 6.0;
    }
    // Odd, awkward residuals are penalized slightly
    if pr % 2 == 1 && pr < bin_capacity / 4 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit exactly in the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // next item fits here after this placement: strong reward,
            // stronger the tighter the combined fit
            let slack = post - nxt;
            score -= 60.0 + 40.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize large dead space
            let dead = post / cap;
            score += 25.0 * dead;
        }
    }

    // Prefer bins whose residual is already below mean (consolidating small gaps)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New empty bin candidate: only attractive when current item is huge
    // (large post_residual is naturally bad, but add explicit bias)
    if bin_residual == bin_capacity {
        score += 15.0 - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.0; // tighter match to next item => lower score
    } else if next_item_size > 0 {
        // next item cannot fit here after placement: penalize dead space
        score += (next_item_size as f64) * 1.5;
    }

    // Relative residual vs mean residual: prefer filling below-average-residual bins
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin early in stream or when item is huge
        if item_size > 70 || (step_index as f64) / (total_items.max(1) as f64) < 0.05 {
            score -= 200.0;
        }
    }

    // Small penalty for leaving awkward small residuals (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // next item fits; penalize leftover dead space after the pair
            let pair_left = post_residual - next_item_size;
            score -= 300.0 - pair_left as f64 * 1.5;
        } else {
            // next item does NOT fit here; penalize wasting residual capacity
            let waste = post_residual as f64;
            score += waste * 0.8;
            // extra penalty if residual is too small to ever be useful (below min item size)
            if post_residual < 10 {
                score += 200.0;
            }
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative to mean residual: favor bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are hopeless fits
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 150.0;
        // but if item fits poorly everywhere (post_residual small relative to item), new bin is fine
        // if open_bins_count == 0 it's the only option
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // early in stream, be more willing to open bins for flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Tightness preference: smaller post_residual is better overall (already base), amplify slightly
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Non-linear penalty: squared waste scaled by how much of the bin it strands.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 8.0 / (1.0 + tightness);
    }

    // Open-bin pressure: discourage spreading across many bins, but
    // relax near the end of the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - 0.5 * progress) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins) for small items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call happens with a fresh bin and current fit is poor).
    if bin_residual == bin_capacity {
        // Base new-bin score: modest, so poor fits in open bins lose to it,
        // but good fits in open bins beat it.
        score = 45.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits; new bin is fine
        }
        if item_size >= 80 {
            score -= 10.0; // huge items: fresh bin natural
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight fits via smooth polynomial decay of post_residual.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = 4.0 * x * x - 4.0 * x; // negative valley at x=0 (perfect fit), rises toward x=1

    // Non-linear coupling with stream progress: waste matters more later in the stream.
    score += 2.0 * x * x * progress;

    // Penalize bins whose post residual deviates from the mean residual (dead-space dispersion).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Smooth interaction: post residual vs next item size fit (lookahead coupling).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (post - nxt) / cap;
        score -= 2.0 * (-(gap * gap * 40.0)).exp(); // reward post residual close to next item size
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 * (1.0 - x) * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Progress-weighted polynomial penalty: small residuals matter more late in stream.
    let prog_term = (0.5 + 0.5 * progress) * (x * x) * cap;
    score += 0.8 * prog_term;

    // Reward tight fits (small post_residual) with smooth non-linear bonus.
    score -= (1.0 - x) * (1.0 - x) * (item_size as f64);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) * (0.5 + progress);
        } else {
            // Smoothly reward residual that can still host the next item.
            score -= 2.0 * (1.0 - ((pr - nxt) / cap)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins
    // fit the item and residuals elsewhere are large.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0 && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let avg_fit = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        let openness = (fitting_bins_count as f64).ln().max(0.0);
        score += 15.0 + 8.0 * openness + 0.3 * avg_fit * (0.5 + progress);
    }

    // Mild penalty for bin much emptier than the mean (keeps residuals balanced).
    score += 0.15 * ((mean_residual - pr).abs() / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep-like: penalizes mid residuals more

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate slack (keep bins flexible); late, crush residual aggressively
    let progress_coupling = x * (1.0 - progress) * 4.0 - x * x * progress * 8.0;
    score += progress_coupling;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted
    let dead = (x * (1.0 - x)).sqrt(); // peaks at x=0.5, zero at extremes
    score += 2.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits in post residual, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx <= x {
            score -= 3.0 * (x - nx) * (1.0 + progress);
        } else {
            score += 1.5 * (nx - x) * (1.0 - x);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Slight preference to fill bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.1 * x;

    // Alignment with mean residual: prefer bins below mean residual (tighter than average)
    score += 0.5 * ((mean_residual - pr) / cap).max(-1.0).min(1.0);

    score
}

