        score -= 5.0;
    }

    // Reward tight packing relative to mean residual.
    score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: the smaller the post-residual relative to capacity, the better.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are in [1,100]; a residual < next_item_size is likely wasted if it's small.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // Dead space for the known next item: penalize proportionally.
            score += 6.0 * (1.0 - post / cap);
        } else {
            // Reward bins whose residual lands close to the next item size (good chaining).
            let chain = 1.0 - ((post - nxt) / cap).abs().min(1.0);
            score -= 5.0 * chain;
        }
    } else {
        // Last item: prefer filling any bin as much as possible.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let waste = post / cap;
        score -= 15.0 * (1.0 - waste * waste);
    }

    // Penalize opening new bins when plenty of bins already fit the item
    // and global residual space is abundant.
    let open_f = open_bins_count as f64;
    let surplus = mean_residual - item_size as f64;
    if surplus > 0.0 {
        score += 3.0 * (1.0 - (surplus / cap).min(1.0));
    } else {
        score -= 2.0 * (surplus.abs() / cap).min(1.0);
    }

    // Time-horizon coupling: early in the stream, be more willing to open bins
    // (spread items); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 8.0 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Mild penalty for bins that are already very full but leave awkward slivers.
    if post > 0.0 && post < 10.0 {
        score += 4.0;
    }

    // Slight preference for balancing load across bins early on.
    score += 0.5 * ((bin_residual as f64) - mean_residual).abs() / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Early stream: prefer tight fits (low post_residual) mildly; late stream: punish waste quadratically.
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += waste_weight * norm_pr * pr * 0.01;

    // Interaction: perfect-fit reward scaled by progress via cubic term.
    let perfect = (cap - pr) / cap; // fraction filled after placement
    score -= 8.0 * perfect * perfect * perfect * (0.5 + progress);

    // Lookahead coupling: reward residual that can host the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strong smooth reward to avoid opening a bin.
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Penalize fragmenting many open bins; smooth in open_bins_count and mean_residual.
    let mr = mean_residual / cap;
    score += 0.8 * (open_bins_count as f64).sqrt() * mr * (0.3 + progress);

    // Mild new-bin penalty: keep score of empty bin slightly above tight fits early, competitive late.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Reward residuals that fall into "reusable" harmonic classes (1/2, 1/3, 1/4, 3/4).
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;
    let three_quarter = cap * 0.75;

    let dist_half = (post - half).abs();
    let dist_third = (post - third).abs();
    let dist_quarter = (post - quarter).abs();
    let dist_three_quarter = (post - three_quarter).abs();
    let harmonic_bonus = dist_half.min(dist_third).min(dist_quarter).min(dist_three_quarter);
    score += 1.2 * harmonic_bonus; // exact class hits get big reward

    // Integer-division threshold: residuals divisible by common item sizes are more usable.
    if post_residual > 0 {
        let divisible = (post_residual % 10 == 0) as i32 as f64
            + (post_residual % 20 == 0) as i32 as f64
            + (post_residual % 25 == 0) as i32 as f64;
        score -= 3.0 * divisible;
    } else {
        // Perfect fill: best possible outcome.
        score -= 25.0;
    }

    // Dead-space penalty: tiny residuals that no item (min size ~1..10) can exploit well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: slight penalty scaled by waste
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 10.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: must open
        }
    }

    // Stream progression: tighten packing later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect-fill potential: if the lookahead item can exactly consume post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Prefer bins whose residual is already small relative to mean (consolidate waste).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Open-bin pressure: discourage spreading when many bins are open,
    // but allow opening a new bin when few are open and fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when the item fits badly elsewhere
    // (large post_residual relative to item) — otherwise keep it slightly unattractive.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 12.0 - 18.0 * waste_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (chain-fill), penalize mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect chain match: strong bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Gradual penalty scaled by relative mismatch.
            score += diff * 0.8;
            // If next item fits snugly (waste < 10), mild reward.
            if post >= nxt && post - nxt <= 10.0 {
                score -= 20.0;
            }
        }
        // Next item cannot fit here at all: penalize dead space creation.
        if post < nxt && post > 0.0 {
            score += 15.0;
        }
    } else {
        // Last item: minimize leftover directly (already does via base).
        score -= 5.0;
    }

    // Compare against mean residual: bins tighter than average are precious.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize tiny unusable dead space (< 10 is dead given item range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer placing into already-open bins over opening new ones,
    // especially early/mid stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + penalty that grows with progress
        // (later in stream, opening bins is more wasteful).
        score += 10.0 + 40.0 * progress;
    } else {
        score -= 5.0;
    }

    // Many open bins: encourage consolidation into fewer bins.
    if open_bins_count > 4 {
        score += 1.5 * open_bins_count as f64 * (post_f / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        };
        score = bin_capacity as f64 - 25.0 * pressure - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if fitting_bins_count == 1 {
            score += 50.0; // keep last-chance bin preferred over new bin
        }
    }

    // Mild preference for bins below mean residual (consolidating slack).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: slightly more greedy late in the stream.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial in x, modulated by stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like shape
    let coupling = x * (1.0 + poly * (0.5 + progress));

    let mut score = 100.0 * coupling;

    // Reward tight fits via smooth penalty on waste relative to item
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post residual still fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild preference to fill existing bins as stream progresses
    score += progress * 5.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions (1/2, 1/3, 1/4)
    let cap = bin_capacity as f64;
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;

    // Reward hitting harmonic boundaries: post_residual near 0, 25, 33, 50
    let pr = post_residual as f64;
    for (h, w) in [(0.0, 6.0), (quarter, 3.0), (third, 3.0), (half, 4.0)] {
        let d = (pr - h).abs();
        if d < 4.0 {
            score -= w * (1.0 - d / 4.0);
        }
    }

    // Penalize dead space in the "awkward" band: just above half (51..70) is hard to fill
    if pr > half && pr < 70.0 {
        score += (pr - half) * 0.35;
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes (10,20,25) are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            score -= (next_item_size as f64 / cap) * 6.0;
        } else {
            // next item won't fit here: penalize leaving large leftover
            score += (pr / cap) * 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer filling nearly-full bins as stream progresses (first-fit-decreasing flavor)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - pr / cap) * (4.0 + 6.0 * progress);

    // When many bins are open, tighten: penalize spreading into loose bins
    if open_bins_count > 3 {
        score += (pr / cap) * (open_bins_count as f64).min(10.0) * 0.4;
    }

    // Mean residual coupling: bins far from the mean residual are less predictable
    score += ((pr - mean_residual).abs()) * 0.15;

    // New-bin candidate handling: empty bin gets neutral-ish score so it's chosen
    // only when no open bin offers a good (low) score
    if bin_residual == bin_capacity {
        score = cap * 0.75 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;

    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let progress = if total_items == 0 {
        0.0
    } else {
        ((step_index as f64) / (total_items as f64)).clamp(0.0, 1.0)
    };

    let open_sat = open / (open + 5.0);
    let mean_sat = (mean / cap).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        let mut score = post;

        let opening_pressure = 0.08 * cap
            + (0.30 * cap + 0.012 * cap * open) * open_sat
            + 0.25 * cap * mean_sat * open_sat
            + 0.05 * cap * progress;

        score += opening_pressure;

        if next > 0.0 && post + 0.5 >= next {
            score -= 0.05 * cap + 0.08 * next;
        }

        if fitting_bins_count == 0 {
            score -= 10.0 * cap;
        }

        return score;
    }

    let mut score = post;

    let fits_next_here = next <= 0.0 || post + 0.5 >= next;
    let unsafe_kill = next > 0.0 && !fits_next_here && residual + 0.5 >= next;

    if fitting_bins_count == 1 {
        let last_chance_bonus = if unsafe_kill {
            0.04 * cap
        } else {
            0.26 * cap + 0.10 * cap * open_sat + 0.06 * cap * progress
        };
        score -= last_chance_bonus;
    }

    if next > 0.0 && post > 0.5 && post + 0.5 < next {
        let gap = next - post;
        let rel = (gap / next).clamp(0.0, 1.0);

        if residual + 0.5 >= next {
            let next_frac = (next / cap).clamp(0.0, 1.0);
            let next_strength = 0.35 + 0.65 * next_frac;
            let item_next_gap = ((item - next).abs() / cap).clamp(0.0, 1.0);
            let swap_gain = 0.25 + 0.75 * item_next_gap;

            let dead_base = 0.55 * cap * next_strength
                + 1.10 * cap * rel * next_strength
                + 0.0035 * cap * (residual - next).max(0.0)
                + 0.15 * (cap - post).max(0.0);

            let coupling = (0.75 + 0.45 * open_sat)
                * (1.15 - 0.55 * mean_sat)
                * (0.85 + 0.45 * progress)
                * swap_gain;

            score += dead_base * coupling;
        } else {
            score += (0.02 * cap + 0.10 * cap * rel)
                * (1.0 - post / cap).clamp(0.0, 1.0)
                * (0.8 + 0.4 * progress);
        }
    } else if next > 0.0 && post + 0.5 >= next {
        score -= 0.03 * cap
            * (1.0 - post / cap).clamp(0.0, 1.0)
            * (0.6 + 0.6 * progress);
    }

    let tiny_zone = 0.05 * cap;
    if post > 0.5 && post < tiny_zone {
        let tiny_rel = 1.0 - (post / tiny_zone);
        score += (0.03 * cap + 0.05 * cap * tiny_rel)
            * (0.6 + 0.6 * progress)
            * (0.7 + 0.6 * open_sat);
    }

    if post <= 0.5 {
        score -= 0.04 * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the next item also fits (2-step lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        // Reward tight two-item packing: small leftover after both items is best.
        score -= 30.0 + (bin_capacity as f64 - leftover_after_next as f64) * 0.2;
        // Extra bonus if the pair nearly fills the bin.
        if leftover_after_next <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space that is too small to be useful.
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += (10.0 - waste) * 2.0; // tiny unusable slivers are bad
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average is wasteful; leaving much less tightens packing.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when reasonable fitting bins exist,
    // unless the item fits almost perfectly in a fresh bin.
    if bin_residual == bin_capacity {
        let perfect_fit = (bin_capacity - item_size) <= 5;
        if !perfect_fit && fitting_bins_count > 0 {
            score += 25.0;
        }
        // Prefer new bins early in the stream (plenty of items left to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            // Next item won't fit here; mild penalty scaled by wasted potential.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.05 * waste;
        }
    } else {
        // Last item: prefer filling a bin completely.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: discourage spreading, prefer consolidating into fuller bins.
    let load_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += load_pressure * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Compare residual to mean residual across open bins: prefer bins fuller than average.
    let diff = mean_residual - bin_residual as f64;
    score += 0.08 * diff;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus exploration bonus early on.
        score = bin_capacity as f64 - 10.0 * (1.0 - progress);
        // Opening a new bin is good if no existing bin gives a tight fit.
        if post_residual == 0 { score -= 5.0; }
        if fitting_bins_count == 0 { score -= 30.0; }
    } else if progress > 0.7 {
        // Late stream: penalize leaving large residuals.
        score += 0.10 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress.
    // Early stream: prefer tight fills (low post_residual) mildly.
    // Late stream: penalize residual waste more strongly (quadratic growth).
    let w = 1.0 + 2.0 * progress * progress;
    score += w * (x * x) * cap * 0.5;

    // Interaction: residual waste is worse when mean residual across bins is low
    // (space is globally scarce), smoothed via sigmoid-like factor.
    let scarcity = 1.0 / (1.0 + mean_residual / cap);
    score += 10.0 * x * scarcity;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Lookahead coupling: reward if next item fits in post residual (smooth bell).
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tightness = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 15.0 * fits * tightness;
        // Penalize leaving residual that is too large relative to next item (wasted cushion)
        score += 5.0 * (pr / cap).max(0.0) * (1.0 - fits);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: exact fits and residual classes divisible by common item sizes
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else {
        // Residual class buckets via integer division thresholds
        let pr = post_residual;
        if pr <= 10 {
            score -= 25.0; // small dead space, still usable by small items
        } else if pr <= 25 {
            score += 5.0; // awkward mid gap
        } else if pr <= 50 {
            score -= 10.0; // half-ish space, reusable
        } else {
            score += 8.0; // large leftover: wasteful placement of a big item
        }

        // Modulo harmony: residual divisible by 10 or 25 aligns with typical sizes
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 2.0; }
        // Odd primes create dead zones
        if pr % 3 == 1 { score += 1.5; }
    }

    // Lookahead: reward residual that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chains into a perfect fit next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 6.0 * (slack / cap);
            if (post_residual - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            score += 4.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        // Penalize new bins mildly; escalate if current bins are fragmented
        score += 35.0 + 5.0 * pressure * (1.0 - progress) - 10.0 * (mean_residual / cap);
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) {
            score -= 5.0;
        }
        if post_residual == bin_capacity && item_size > 70 {
            score -= 20.0; // big item into fresh bin is fine
        }
    }

    // Fragmentation guard: placing into bin far below mean residual worsens spread
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if dev < -0.2 { score += 6.0; }
    else if dev > 0.2 { score -= 3.0; }

    // Mild encouragement to fill bins tightly as stream progresses
    score -= 12.0 * (1.0 - (post_residual as f64) / cap) * (0.5 + 0.5 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= ~15) are "dead". Penalize heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 30 {
        // Small gap zone: moderate penalty, worse the smaller the gap.
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Perfect fit: nearly zero residual.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading; prefer
    // filling existing bins, penalize opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + progress);

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else or residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened by how bad the current
        // mean residual situation is and by open-bin pressure.
        let fragmentation = 1.0 - (mean_residual / (bin_capacity as f64)).max(0.0).min(1.0);
        score = bin_capacity as f64 * 0.5
            + post_residual as f64 * 0.3
            - fragmentation * 30.0
            - pressure * 0.4
            + 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score += 100.0;
        }
    } else {
        // Lookahead: if next item fits exactly in the post-residual, reward.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / 100.0).max(0.0);
        if post_residual == next_item_size {
            score -= 400.0; // chain fit: item now, next item fills bin exactly
        }
        // Penalize post_residual too small to ever be useful
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Tight fit reward relative to capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Penalize wasting a large residual on a small item (dead space creation)
    let waste = post_residual as f64 - item_size as f64;
    if waste > 40.0 {
        score += 0.4 * waste;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer denser packing when many bins are open
    if open_bins_count > 0 {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs().min(50.0);
    }

    // Late in stream: be conservative, prefer filling existing bins over new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 120.0 + 200.0 * progress; // new-bin candidate penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's minimum footprint.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) < nr {
            // next item won't fit here: wasted space penalty, scaled by how wasted it is
            score += 0.6 * (post_residual as f64) + 8.0;
        } else {
            // next item fits: reward leaving exactly-compatible space
            let gap = (post_residual as f64) - nr;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: reward filling bins as fully as possible
        score += 0.3 * (post_residual as f64);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 25.0 * fit_quality;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins
    // are congested or mean residual is small relative to item size.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let scarcity = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        // Default mild penalty so we prefer existing bins; relax when many bins are nearly full.
        let mut new_bin_score = 30.0 - 4.0 * congestion;
        if scarcity < 0.0 {
            new_bin_score -= 2.0 * (-scarcity);
        }
        // Late in the stream, opening fresh bins is less valuable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 20.0 * progress;
        score += new_bin_score;
    } else {
        // Mild preference for fuller bins among open candidates (best-fit flavor),
        // modulated by global mean residual to avoid over-fragmentation.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
        // Penalize bins whose residual deviates far above the mean (hoarding space).
        let dev = (bin_residual as f64) - mean_residual;
        if dev > 0.0 {
            score += 0.15 * dev;
        }
    }

    // Time-horizon coupling: early in the stream, keep bins balanced for future
    // flexibility; later, greedily fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let balance_weight = 0.4 * (1.0 - progress);
    let dev = (bin_residual as f64) - mean_residual;
    score += balance_weight * dev;

    // Small penalty on opening bins when many are already open (fragmentation control).
    if bin_residual == bin_capacity {
        score += 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual value decays with stream progress
    // (late in the stream, leftover space matters less; early on, preserve flexibility)
    let decay = 1.0 - 0.6 * progress * progress;
    score *= decay;

    // Quadratic penalty for small-but-nonzero dead space (unusable slivers),
    // scaled by progress so late-stream slivers are penalized more strongly
    let sliver = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += (1.0 - sliver) * (10.0 + 30.0 * progress * progress);

    // Reward near-perfect fits with a smooth bump centered at norm_pr ~ 0
    score -= 15.0 * (-norm_pr * norm_pr / 0.02).exp();

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward strongly (smooth polynomial interaction with progress)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_quality = (-diff * diff / 50.0).exp();
        score -= 12.0 * fit_quality * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize so it only wins when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "usable" classes (multiples of common small sizes) are more valuable.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted if closed here

    // Penalize residuals that are awkward (not expressible as sum of typical item sizes)
    let r = post_residual;
    let mut usable = 0.0f64;
    for s in [10u32, 20, 25, 30, 40, 50] {
        if s <= r { usable += 1.0; }
    }
    // harmonic class via modulo: residual divisible by common divisors is friendlier
    let mut harm = 0.0f64;
    if r > 0 {
        if r % 10 == 0 { harm -= 6.0; }
        if r % 5 == 0 { harm -= 2.0; }
        if r % 25 == 0 { harm -= 2.0; }
        if r % 3 == 0 { harm -= 1.0; }
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // small dead space is good; large dead space is bad
        score += frac * 30.0;
        // dead space smaller than the minimum item size is truly dead
        if r < 10 && r > 0 {
            score += 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here afterwards; slight penalty for tight fills
            score += 5.0;
        }
    }

    // Many open bins with high mean residual: encourage consolidation into
    // emptier bins rather than spreading.
    if open_bins_count > 2 && (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score += harm;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
