    let progress = step_index as f64 / total_items.max(1) as f64;
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: mildly discourage opening a new bin so we
    // consolidate into existing bins, but relax the penalty as the stream
    // progresses and when open bins are already crowded (low mean residual).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 14.0;
        new_bin_penalty -= 6.0 * progress;
        if mean_residual < 25.0 {
            new_bin_penalty -= 6.0;
        }
        // Large items leave little room anyway; opening fresh is less wasteful.
        new_bin_penalty -= 0.05 * item_size as f64;
        score += new_bin_penalty.max(0.0);
    }

    // Global balance: prefer bins whose residual is below the mean (fill the
    // emptier-relative bins less, keep tight bins tight).
    score += 0.03 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.3 + 0.7 * progress);

    // Penalize residual far from mean (fragmentation pressure)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Reward tight fits
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 10.0 * tightness * tightness;

    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > post_residual {
        score += 6.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer opening new bins only when fits are poor or stream is early
    if bin_residual == bin_capacity {
        score = pr + 25.0 * (1.0 - progress) * (1.0 - norm_pr) + 15.0 * (fitting_bins_count as f64 / (fitting_bins_count as f64 + 1.0));
    }

    // Mild penalty for many open bins
    score += 0.05 * open_bins_count as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction band it falls in.
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 0..8 harmonic band of post residual

    // Reward tight fits strongly (low post_residual classes).
    match class as u32 {
        0 => score -= 30.0,          // post_residual < 12.5% : near-perfect fill
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score -= 0.0,
        5 => score += 3.0,
        6 => score += 6.0,
        _ => score += 2.0,           // nearly empty bin used partially
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_ratio = nxt / pr;
            if fill_ratio > 0.9 {
                score -= 25.0;
            } else if fill_ratio > 0.6 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
            // harmonic bonus: next item leaves another tight class
            let next_post = pr - nxt;
            if (next_post / cap * 8.0).floor() as u32 <= 1 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large dead space
            score += pr * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when good open bins exist (empty-bin candidate handling).
    if bin_residual == bin_capacity {
        // new bin: base score is cap (residual stays cap). Make it unattractive unless
        // nothing fits well or stream is early with few bins.
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score += 45.0 - 25.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open
        }
    }

    // Slight preference for bins below mean residual (balance/consolidation).
    score += (pr - mean_residual) * 0.1;

    // Modulo-style tie-break: prefer post residuals that are multiples of common sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps in [10,20) can only accept tiny items; penalize proportionally.
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already below average (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Lookahead: if next item fits exactly in the post residual, bonus; if post residual
    // is large and next item leaves another dead gap, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0;
        }
    }

    // Late in the stream, be more conservative: avoid creating any new dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && post_residual > 0 && post_residual < 15 {
        score += 20.0 * progress;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when all open bins look bad.
    if bin_residual == bin_capacity {
        score = 70.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when exactly one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chain-fitting), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact-match bonus: residual perfectly consumed by next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 - gap.min(60.0);
        } else {
            // Near-miss penalty scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    }

    // Penalize creating dead space: residual too small for typical future items.
    if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 30 {
        // small residuals are risky unless next item fits (handled above)
        score += 8.0;
    }

    // Tight fits are good: reward when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // a decent existing fit exists; make new bin attractive only for
    // very large items or when all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        // New bin: its post_residual is huge, so add a fixed opening cost.
        score += 55.0;
        // Large items benefit from a fresh bin.
        score -= 0.5 * item_size as f64;
        // If many bins are open, mildly discourage adding more.
        score += 1.5 * open_bins_count as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; placing here wastes less global slack.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Slight preference to fill older bins as the stream progresses.
    score -= 0.05 * (step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward residuals that can still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot fit next item: penalize proportionally
        score += 0.3 * (post_residual as f64) * (next_item_size as f64) / (bin_capacity as f64);
    }

    // Last chance: strongly favor using this bin if it's the only one that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when open bins have poor fits or few bins exist
    if bin_residual == bin_capacity {
        // Neutral baseline; penalize opening new bins when existing fits are decent
        score += 20.0;
        if fitting_bins_count > 0 {
            // discourage new bin if any open bin fits, scaled by how good the best fit likely is
            score += 15.0 * (1.0 - (mean_residual / (bin_capacity as f64)).min(1.0));
        }
        // Early in stream: opening bins is cheap
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 10.0 * (1.0 - progress);
        // Few open bins: opening is fine
        if open_bins_count < 3 {
            score -= 10.0;
        }
        // Large next item: fresh bin preserves flexibility
        if next_item_size > 60 {
            score -= 12.0;
        }
    } else {
        // Using an existing bin: reward consolidation when many bins are open
        if open_bins_count > 5 {
            score -= 5.0;
        }
        // Prefer bins whose residual deviates favorably from mean (below-mean residual = tighter bin)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time-varying exploration: mild non-linear coupling with progress
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Base: post residual, mildly convex so small leftovers are penalized more than linearly
    let mut score = pr + 30.0 * fit * fit;

    // Non-linear coupling: as stream progresses, prefer tighter fits more aggressively
    let tightness = 1.0 - fit;
    score -= 60.0 * progress * tightness * tightness * tightness;

    // Dead-space penalty grows with progress: unusable residual (< next item) is worse late
    let unusable = if (next_item_size > 0 && post_residual < next_item_size) || next_item_size == 0 {
        pr
    } else {
        0.0
    };
    score += 25.0 * (unusable / cap) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits post residual (smooth)
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / cap);
        score -= 18.0 * fits_next * closeness * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - fit * fit);
    }

    // Many open bins: discourage spreading; prefer filling existing bins more
    let spread = (open_bins_count as f64).ln() / 10.0;
    score += spread * fit;

    // Mean residual context: bins far below mean residual are less attractive late
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * progress;

    // New-bin candidate handling: penalize fresh bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 35.0 * (1.0 - big * big) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (dead-space severity classes).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..7 harmonic class of leftover

    // Penalize leftovers in "awkward" classes (small unusable slivers).
    // Class 0 (exact fit) is best; classes 1..3 (tiny leftovers) are worst.
    match class as u32 {
        0 => score -= 12.0,
        1 => score += 18.0,
        2 => score += 10.0,
        3 => score += 6.0,
        4 => score -= 2.0,
        5 => score -= 4.0,
        _ => {}
    }

    // Integer-division threshold: post_residual divisible by common item
    // sizes (10, 20, 25, 50) means leftover is reusable -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how tight the next fit is
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use the leftover: mild penalty scaled by
            // how much dead space is stranded
            score += 0.05 * post;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave tiny stranded slivers and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // base new-bin cost keeps open bins preferred when fits are decent
        score += 20.0;
        // but if the best possible leftover across open bins is tiny,
        // opening fresh is attractive: approximate via mean residual
        if mean_residual < item_size as f64 * 1.3 {
            score -= 18.0;
        }
        // early in stream, allow more bins; late, consolidate
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
        let _ = open_pressure;
    }

    // Slight preference for tighter existing bins (smaller residual before
    // placement) when ties occur.
    score += 0.02 * (bin_residual as f64 - post);

    // Mean residual alignment: bins far from the mean residual get a mild
    // nudge toward consolidation.
    score += 0.03 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range
    // means < 10 is almost dead; treat gaps below a conservative usable threshold harshly).
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if (post_residual as f64) < min_item * 2.0 {
        score += 18.0; // nearly dead gap
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Penalize if the leftover cannot fit the next item (lookahead dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins
    // and encourage consolidation into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Encourage bins whose residual is near the mean (balanced packing),
    // discourage outliers that would strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when few bins are open
        // or the item is large (big items deserve fresh space).
        score = 100.0 - 20.0 * tightness - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // next item also large: fresh bin may serve both
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match within a small tolerance.
    else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 400.0 - gap * 40.0;
        }
        // Penalize residuals that are too small for the next item (dead space risk),
        // but only mildly if they are still generally usable.
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward bins whose residual is small relative to the mean (tight fits).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize leaving very large residuals only when many bins are open
    // (fragmentation control), less so early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * (0.3 + 0.7 * progress);
    }

    // Discourage opening new bins when open bins can reasonably absorb the item.
    if bin_residual == bin_capacity {
        let new_bin_penalty = if next_item_size > 0 && post_residual == next_item_size {
            -1000.0 // new bin is a perfect match for the next item too
        } else {
            120.0 + open_bins_count as f64 * 5.0
        };
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if bin_residual > 0 {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_quality * fit_quality;
    }

    // Penalize dead space: post_residual that is too small to hold a future item
    let min_item = 1.0f64;
    if (post_residual as f64) < 10.0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; penalize wasting space
        score += 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate handling: slightly penalize so we prefer reusing bins,
    // but relax penalty late in the stream or when open bins are mostly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 18.0
            - 10.0 * avg_fullness
            - 6.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * consolidation;
    }

    // Time horizon: early in stream, be picky about fits; late, accept decent fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / c;

    // Base: prefer tight fits (small post_residual), with slight convexity
    let mut score = pr + 6.0 * norm_pr * norm_pr * c;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (less chance to fill it)
    let coupling = (pr / c).powi(2) * (0.5 + 2.5 * progress * progress);
    score += 40.0 * coupling;

    // Smooth interaction with mean residual: if bin residual deviates from the mean,
    // normalize toward keeping residual diversity (helps future items fit)
    let dev = (bin_residual as f64 - mean_residual) / c;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress) * (0.5 + 0.5 * (item_size as f64 / c));
    }

    // Lookahead: reward bins whose post_residual can still hold the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / c;
        score -= 12.0 * fit_frac * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize residuals just below next item size (awkward dead space)
        let gap = (next_item_size as f64 - pr) / c;
        score += 8.0 * gap * gap * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage opening new bins early,
    // encourage it late when residual is small and fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 15.0 * progress * (pr / c);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Density reward: fraction of bin used by this item
    score -= 10.0 * (item_size as f64 / c) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    let mut score = post_residual as f64;

    // Harmonic class logic: prefer residuals that are "clean" multiples of 10
    // (likely reusable by common item sizes); penalize awkward classes.
    let class = post_residual % 10;
    if post_residual > 0 {
        score += 2.5 * (10 - class) as f64 * (class as f64 / 10.0);
    }

    // Lookahead: reward leaving room for the next item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 4.0 * (next_item_size as f64 / 100.0);
        // extra bonus if next item fits almost exactly (harmonic pairing)
        let gap = post_residual - next_item_size;
        if gap % 10 == 0 {
            score -= 2.0;
        }
    }

    // Dead-space penalty: residual too small for the incoming next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 4.0 * progress;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 8.0;
    }

    // New-bin candidate baseline cost: opening bins is expensive by default.
    score += is_new_bin * 12.0;

    // Relax new-bin cost when existing bins are fragmented (high mean residual
    // relative to capacity) or many bins are already open late in the stream.
    let fragmentation = mean_residual / cap;
    score -= is_new_bin * 10.0 * fragmentation * (0.5 + 0.5 * progress);
    score -= is_new_bin * (open_bins_count.min(20) as f64) * 0.3 * progress;

    // Mild preference for tight fits overall (small post_residual dominates).
    score += 0.02 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item (size 1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (1.0 / (1.0 + tightness)) * 12.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty scaled by how far post_residual is from the
    // next item size (lookahead coupling): a residual that exactly fits
    // the next item is valuable.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += gap * 0.5;
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // If next item can't use the leftover, it's likely dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new empty bin candidate gets penalized via its full residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // Early in the stream, opening a bin is cheaper.
        score -= (1.0 - progress) * 12.0;
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean-residual coupling: prefer bins whose resulting residual stays
    // near the open-bin mean (keeps residuals balanced and usable).
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled relative to mean residual.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // 2-step lookahead: reward if next item exactly fills the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain: strong reward
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to how much of post residual is consumed
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * frac;
        } else {
            // next item cannot fit here: penalize leaving large dead space
            let waste = next_item_size - post_residual;
            score += 0.6 * waste as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // New bin acceptable only if no open bin gives a near-perfect fit.
        let tightness = item_size as f64 / bin_capacity as f64;
        if (post_residual as f64) < 10.0 {
            score -= 45.0;
        }
        let _ = tightness;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in stream: be more frugal with opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear discount.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item exactly fits the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize proportional waste.
            score += 8.0 * (1.0 - (next_item_size as f64 / (bin_capacity as f64)));
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * crowding * (1.0 - progress);

    // Penalize bins far from mean residual (prefer balanced residual portfolio),
    // unless it's a fresh empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    } else {
        // Opening a new bin is costly early; acceptable when open bins are crowded/tight.
        score += 35.0 - 20.0 * progress - (mean_residual / 20.0);
    }

    // Mild reward for filling bins close to full.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]
    let fit_ratio = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream: value tight fits more aggressively (post residual penalized harder).
    let t = progress.clamp(0.0, 1.0);
    let coupling = 1.0 + 1.5 * t * t + 0.8 * t * t * t;
    score += coupling * (x * x) * cap * 0.35;

    // Reward near-perfect fits smoothly: subtract a bump centered at x=0.
    let tight_bonus = (-x * x * 12.0).exp();
    score -= tight_bonus * cap * (0.25 + 0.35 * t);

    // Penalize dead space that no plausible item (>=1) can use: mild quadratic in x.
    score += 0.15 * cap * x * (1.0 - fit_ratio);

    // Lookahead: if next item fits in the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = (post - next_item_size as f64).max(0.0) / cap;
        let reward = (1.0 - (fits_next * 4.0)).max(0.0) * nx;
        score -= 20.0 * reward;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Many open bins: prefer consolidating into existing bins.
    let ob = open_bins_count as f64;
    score += 0.02 * ob * x * cap * (1.0 - t);

    // New-bin candidate bias: slightly penalize the empty bin so it's chosen only when
    // open bins score poorly (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 250.0;
    }

    // Harmonic classes of residual space: which standard item sizes could still fit
    // Classes: 0 (dead), 1..=10, 11..=20, 21..=35, 36..=50, 51..=100
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 35 { 3 }
        else if post_residual <= 50 { 4 }
        else { 5 };

    // Penalize by dead-space class (waste small residuals)
    score += match class {
        0 => -250.0,
        1 => 45.0,
        2 => 25.0,
        3 => 8.0,
        4 => -5.0,
        _ => -15.0,
    };

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by how well it fills
            let tight = (next_item_size as f64 / pr).min(1.0);
            score -= 30.0 * tight;
        } else {
            // Residual too small for next item: penalize proportionally to wasted class
            score += 12.0;
        }
        // Harmonic modulo check: next item matches residual class divisor
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets baseline; prefer it only when
    // existing residuals are heavily fragmented (low mean_residual relative to item)
    if bin_residual == bin_capacity {
        score = 55.0
            - (mean_residual / cap) * 40.0
            + (open_bins_count as f64) * 0.8
            + (post_residual as f64) * 0.15;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Tightness reward: item fills a good fraction of the bin residual
        let fill = item_size as f64 / bin_residual as f64;
        score -= 35.0 * fill * fill;
    }

    // Progress: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - pr / cap);

    // Fragmentation pressure: many open bins with high mean residual -> prefer filling
    score += (mean_residual - pr) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item are heavily penalized. Anything below the minimum plausible
    // item size (conservatively ~10, with a soft ramp up to ~25) is "dead".
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    } else if (post_residual as f64) < 25.0 {
        // Soft penalty for marginal gaps that most items cannot use.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: fraction of the residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Reward exact/near-exact closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer placing here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, favor
    // consolidating into existing bins (penalize the new-bin candidate).
    let pressure = open_bins_count as f64 * 1.2;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but allow it when the
        // item would leave a huge unusable gap in every open bin.
        score += 25.0 + pressure;
        if post_residual == 0 {
            score -= 10.0; // perfect-fit item justifies a fresh bin
        }
    } else {
        // Existing bin: slight reward proportional to pressure to consolidate.
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits the post_residual exactly, this
    // placement is excellent; if next item cannot fit anywhere, less so.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 3.0; // gap likely wasted for the immediate future
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the
    // mean in a useful way (large residual bins absorb big items well).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.2;

    // Stream progression: late in the stream, be more aggressive about
    // closing bins tightly (dead space matters more near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves another residual: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + gap);
        } else {
            // Next item does NOT fit: penalize dead space more aggressively when it's small.
            let dead = (next_item_size - post_residual) as f64;
            score += 15.0 + 30.0 / (1.0 + dead);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize creating tiny unusable residuals (relative to typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if mean_residual < 0.25 * bin_capacity as f64 {
            score -= 30.0; // open bins nearly full -> new bin is fine
        } else {
            score += 20.0 + crowded * 10.0; // discourage wasting open capacity
        }
    }

    // Mild tie-break: prefer bins whose residual deviates below the mean (tighter bins first).
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(-5.0);

    // Early in stream, be slightly more willing to consolidate (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placing large items (they consume big chunks; tight packing matters most).
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Penalize tiny unusable dead space (below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // leftover likely wasted
        }
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: generally discourage opening new bins,
    // but soften for large items or when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0
            - 6.0 * (item_size as f64 / bin_capacity as f64)
            + 3.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && item_size < next_item_size {
            score += 3.0; // opening fresh space for a bigger successor can pay off
        }
    }

    // Fragmentation coupling: leaving more than the mean residual adds to waste.
    if post_residual as f64 > mean_residual {
        score += 1.5;
    }

    // Dynamic time horizon: late in the stream, be slightly more tolerant
    // (future recovery opportunities shrink).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post-residual waste, with a mildly super-linear penalty on dead space.
    let mut score = post * (1.0 + 0.35 * (post / cap).powi(2));

    // Smooth coupling of waste with stream progress: late in the stream,
    // waste is more costly (fewer chances to fill gaps), so amplify it.
    score += post * progress * 1.2;

    // Interaction between post-residual and mean residual across open bins:
    // prefer bins whose resulting residual deviates below the mean (tightening the fleet).
    score += 0.8 * (post - mean_residual) * (post / cap);

    // Lookahead coupling: if the next item fits the post-residual well, reward;
    // if the next item barely misses, penalize leaving a near-useless gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 2.5 * nxt * (1.0 - (post - nxt) / cap);
        } else {
            let miss = (nxt - post) / cap;
            score += 3.0 * post * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (scaled smoothly by progress).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate (empty bin): make it moderately unattractive so that
    // any reasonable existing fit wins, but attractive when all fits are awful.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress - 0.05 * open_bins_count as f64;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions (deciles)
    let post_frac = post_residual as f64 / cap; // 0.0 .. 1.0
    let class = (post_frac * 10.0).floor() as i64; // 0..10 harmonic class

    // Dead-space penalty: small non-zero residuals (class 1..3) are hard to fill.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if class >= 1 && class <= 3 {
        score += 12.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or nearly exactly -> strong reward
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0;
            } else if gap <= 10 {
                score -= 30.0;
            } else {
                score -= (gap as f64) * 0.3;
            }
        } else {
            // Next item cannot use this residual: penalize by leftover fraction
            score += post_frac * 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        // If fit is poor (large post residual relative to capacity), penalize less
        // so we still use it, but reward tight fits strongly.
        if post_frac < 0.25 {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals divisible by 5/10 align with
    // common item-size classes, making them more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer filling bins below mean residual (tighter bins first) to consolidate.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // New-bin candidate: brand-new empty bin should only win when no open bin
    // offers a decent fit. Penalize it increasingly as fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins with tight fits beat the new bin.
        score += 40.0 + 20.0 * progress;
        // But if many open bins exist and none fit well (this call is the fallback),
        // a large item justifies a fresh bin: soften penalty for large items.
        if item_size > 60 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to keep open-bin count low early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into post_residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 25.0;
        } else if leftover < 10 {
            score += 5.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: dead space penalty scaled by gap size.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 0.1 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 1000.0;
        } else if diff <= 10.0 {
            score -= 200.0 - 20.0 * diff;
        } else {
            score += diff * 0.5;
        }
    } else {
        // Last item: minimize post residual directly (tight packing).
        score -= 50.0;
    }

    // Penalize small unusable dead space relative to smallest possible item.
    if post_residual < 10 && post_residual > 0 {
        score += 150.0;
    }

    // Compare residual to mean residual of open bins: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge / no good fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count <= 1 { 0.0 } else { 200.0 };
        score += 250.0 + pressure + (open_bins_count as f64) * 2.0;
        // If item fills a fresh bin substantially, opening is more acceptable.
        score -= item_size as f64 * 1.5;
    }

    // Mild progression bias: late in stream, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count >= 2 {
        // Multiple options: prefer bins that keep other bins flexible.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin is expensive; make it
    // unattractive unless it enables a perfect fit or no bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        if post_residual == 0 {
            score -= 100.0; // perfect fit in a fresh bin is fine
        } else if fitting_bins_count == 0 {
            score -= 40.0; // forced opening
        } else {
            // discourage wasting a fresh bin when decent fits exist
            score += 55.0 + 0.25 * (post_residual as f64);
        }
    }

    // Lookahead: if the next item would exactly fill this bin's post_residual,
    // reward placing current item here (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: slight penalty for wasteful gaps
            score += 5.0;
        }
    }

    // Global state coupling: when many bins are open with slack, tighten selection.
    if open_bins_count > 0 {
        let pressure = mean_residual / (bin_capacity as f64);
        // High mean residual -> be picky: penalize bins far from mean fit.
        score += 12.0 * pressure * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
        // Encourage closing nearly-full bins to reduce open-bin slack.
        if post_residual < 15 {
            score -= 10.0 * pressure;
        }
    }

    // Time horizon: early in the stream, be conservative (avoid fragmentation);
    // late in the stream, prioritize filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (bigger leftover = better fit), with non-linear shaping
    let mut score = pr
        - 40.0 * norm_pr * (1.0 - norm_pr)          // reward near-perfect fits (post_residual small)
        - 25.0 * norm_pr * norm_pr * progress;      // late stream: tighter packing more valuable

    // Penalize dead space relative to capacity, amplified by progress
    score += 15.0 * norm_pr * norm_pr * (1.0 - progress);

    // Lookahead: bonus if next item fits in post_residual (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = (pr - nx) / cap;
        score -= 20.0 * (1.0 / (1.0 + (-8.0 * fit_margin).exp())) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Slight preference for bins deviating from mean residual (diversity of sizes)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Early stream: mildly prefer opening/keeping bins with large residuals
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10 (dead-space granularity)
    let pr = post_residual as u32;
    let class = pr % 10;
    // Reward exact-fill classes heavily
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space unusable for min-size items
    } else {
        // penalize residual classes that are hard to fill later
        score += match class {
            0 => -10.0,          // round residual, easy to reuse
            1 | 2 | 3 => 8.0,    // awkward slivers
            _ => 0.0,
        };
    }

    // Fractional capacity coupling: how full the bin becomes
    let fill_frac = item_size as f64 / cap;
    score -= 30.0 * fill_frac * fill_frac; // prefer filling bins deeply

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // harmonic class match on tens digit
            if (next_item_size / 10) == (pr / 10) {
                score -= 15.0;
            }
            score -= 5.0;
        } else {
            score += 10.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0
            + 0.15 * open_bins_count as f64
            + (pr as f64 - item_size as f64) * 0.2;
    } else {
        // reward using already-open bins, scaled by how "tight" the stream is
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 + 4.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good consolidation)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 10.0; // gaps below the minimum item size are pure waste
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 30.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Non-linear penalty: convex in wasted fraction of the gap.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize more if it's below min size.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost, modulated by how bad existing options are.
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a chain fit
    // (next item exactly fills or nearly fills the post-residual).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            // Perfect chain match is highly desirable.
            score -= 30.0 * (1.0 - chain_waste / (bin_capacity as f64 * 0.5)).max(0.0);
            // If the chain leaves almost nothing behind, extra bonus.
            if chain_waste <= 5.0 {
                score -= 20.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Next item would have fit before this placement but not after:
            // we are destroying a chain opportunity -> penalize.
            score += 25.0;
        }
        // If next item cannot fit this bin either way, mild bonus for
        // dumping a big item here (bin becomes "closed" cleanly).
        if next_item_size > bin_residual {
            score -= 5.0;
        }
    } else {
        // Last item: prefer the tightest fit, nothing to save space for.
        score -= 10.0;
    }

    // Penalize dead space relative to the fleet's mean residual:
    // leaving more slack than average is wasteful.
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += 0.5 * (dead - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - dead);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Reward packing into nearly-full bins (small residuals get priority).
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Discourage opening new bins when a decent fit exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item leaves a big hole
        // everywhere else; make new bin slightly costly.
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but avoid near-zero dead space
    // that can't serve the next item. Reward post_residuals that exactly fit lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        // This bin remains useful for the next item: reward proportionally to fit quality
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual too small for lookahead: penalize dead space harder
        score += 0.35 * post_residual as f64;
    }

    // Perfect-fill bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin,
    // but only if the fit is reasonably tight.
    if fitting_bins_count == 1 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 8.0 + 6.0 * fit_ratio;
    }

    // Prefer bins whose residual is close to the item (best-fit coupling)
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 4.0 * tightness;

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bias = 3.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early, or when existing fit is terrible
        score -= new_bin_bias;
        if post_residual as f64 > mean_residual * 1.1 && fitting_bins_count > 0 {
            score += 5.0; // existing bins would be left very fragmented
        }
    } else {
        // Late stream: extra reward for using open bins
        score -= 2.0 * progress;
        // Many open bins: encourage consolidation
        score -= 0.05 * open_bins_count as f64;
    }

    // Squared post-residual penalty: large leftover space is costly
    score += 0.004 * (post_residual as f64).powi(2) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual (waste), modulated by progress
    let mut score = norm_pr * norm_pr * (1.0 + progress) * cap * 0.5 + norm_pr * cap * 0.5;

    // Smooth cubic coupling of post_residual with stream progress
    score += (pr * pr * pr) / (cap * cap) * (0.1 + 0.9 * progress);

    // Reward tight fits: subtract smooth term shrinking with post_residual
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Smooth penalty relative to mean residual: prefer bins below mean (consolidating waste)
    score += (mean_residual - pr) * 0.15 * (1.0 - progress);

    // Lookahead coupling: penalize if post_residual can't fit next item (smoothly)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += (gap / cap) * 20.0 * (1.0 - progress * 0.5);
        // Reward if next item fits exactly-ish
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - fit_gap / cap) * 10.0 * progress;
    }

    // Slight preference for fewer open bins when stream is ending
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // ---- Tight-fit reward: fraction of the bin's residual consumed ----
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // ---- Harmonic classes of post_residual (modulo arithmetic on capacity deciles) ----
    let class = post_residual % 10;
    match class {
        0 => score -= 4.0,                 // perfectly aligned residual -> reusable class
        1 | 2 => score -= 1.5,             // near-aligned, still decent
        8 | 9 => score += 3.0,             // awkward sliver class -> dead space risk
        _ => {}
    }

    // Integer-division threshold: residual usable in halves/quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual % quarter == 0 {
        score -= 3.0;
    }

    // ---- Lookahead coupling: does next_item_size fit into post_residual? ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item chains perfectly into this bin
            let chain_fit = nxt / post.max(1.0);
            score -= 6.0 * chain_fit;
            // harmonic bonus when next item also lands on an aligned class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 2.5;
            }
        } else {
            // post_residual cannot host next item -> penalize more if it's a tiny sliver
            let slack = nxt - post;
            score += 0.08 * slack.min(40.0);
        }
    }

    // ---- Last-chance bin: only one open bin fits the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // opening a new bin is good for large items, bad for small ones
        score += 6.0 - 5.0 * (item / cap);
        // if no open bin fits, opening new bin is necessary-ish: soften penalty
        if fitting_bins_count == 0 {
            score -= 4.0;
        }
    }

    // ---- Dispersion pressure: keep residuals near the mean to avoid fragmentation ----
    score += 0.03 * (post - mean_residual).abs();

    // ---- Late-stream consolidation: prefer reusing bins near the end ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Perfect-fill lookahead: if the next item exactly consumes the residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap -> dead space almost certain.
        score += post_residual as f64 * 0.8;
    }

    // Pressure from many open bins: prefer reusing bins over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are large/fragmented
    // and the item is big relative to capacity.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 + fragmentation * 0.5 - (item_size as f64 / bin_capacity as f64) * 25.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression tilt: later in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, tighter packing matters more.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward if next item fits exactly / well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain fit: strongly reward.
            score -= 60.0 + 30.0 * progress;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays with leftover slack after the next item.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64) * (0.5 + 0.5 * progress);
        } else {
            // Next item cannot follow: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize creating tiny unusable dead space (dead space = post_residual too small
    // for typical items). Assume minimum item footprint relative to capacity.
    let min_item = 1u32.max(bin_capacity / 10);
    if post_residual > 0 && post_residual < min_item {
        score += 25.0 + 20.0 * progress;
    }

    // Reward tight fits: small post_residual relative to capacity is good (unless dead).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Compare against mean residual: placing into a bin with residual far below mean
    // (small residual) is good; placing into a large-residual bin is less urgent.
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // But if many open bins exist and mean residual is fragmented, opening fresh
        // is fine; scale penalty down with open_bins_count.
        score -= (open_bins_count as f64).min(10.0) * 0.8;
        // Late in the stream, prefer filling existing bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10)
    // are wasted; penalize residuals in the "dead zone" (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here; slight penalty proportional to gap.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += gap * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins exist.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins early / when open bins are roomy.
        score += 150.0 * (1.0 - avg_pressure) + 40.0 * (1.0 - progress);
        // But if many bins are open and residuals are fragmented, allow new bins.
        if open_bins_count > 8 && avg_pressure > 0.6 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (more filled than average).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 10.0;
    }

    // Mild time-horizon modulation: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream progress coupling: as stream advances, dead space becomes costlier.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score *= (1.0 + 0.6 * prog2 + 0.4 * prog3);

    // Smooth interaction: post_residual x progress cubic coupling term.
    score += 20.0 * norm_pr * norm_pr * prog3;

    // Reward filling bins tightly relative to current mean residual.
    score -= 6.0 * (mean_residual - pr).max(0.0) / cap;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - gap * gap);
        // Penalize leaving residual that is awkwardly small for the next item.
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 5.0 * (next_item_size as f64 - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.3 * (open_bins_count as f64).sqrt() * progress;

    // New-bin candidate: make empty bin attractive only when current fits are loose.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (pr / cap); // 1 for a fresh bin itself
        score += 4.0 * (1.0 - progress) + 2.0 * mean_residual / cap;
        let _ = tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 (item granularity class)
    let post = post_residual;
    let residue = (post % 10) as f64;

    // Perfect fit: zero residual is the ideal harmonic class -> heavy reward
    if post == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space, especially residues in the "dead zone" (1..10)
        if post < 10 {
            score += 40.0 * (10.0 - post as f64);
        }
        // Reward residues that align with common item classes (multiples of 10)
        if post % 10 == 0 {
            score -= 15.0 + post as f64 * 0.3;
        } else {
            score += residue * 0.8;
        }
    }

    // Integer-division thresholds: how many "typical items" of size ~20 still fit
    let slots20 = post / 20;
    let slots10 = post / 10;
    score -= (slots20 as f64) * 6.0;
    score -= (slots10 as f64) * 1.5;

    // Lookahead coupling: reward residual that exactly hosts the next item
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 220.0;
        } else if post >= next_item_size {
            let chain = post - next_item_size;
            score -= 25.0;
            // penalize leaving a tiny remainder after hosting next item
            if chain < 10 && chain > 0 {
                score += (10 - chain) as f64 * 3.0;
            }
        } else {
            // next item cannot fit here; mildly penalize tight fits that block lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it only wins
    // when open bins would create bad dead space
    if bin_residual == bin_capacity {
        score += 55.0;
        // late in the stream, opening fresh bins is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Global context: many open bins with high mean residual -> discourage waste
    if mean_residual > 0.0 {
        let waste_ratio = post as f64 / cap;
        score += waste_ratio * mean_residual * 0.4;
    }

    // Prefer consolidating into fewer bins when open bin count is high
    score += (open_bins_count as f64) * 0.15;

    // Mild reward for tight fits overall
    let tightness = 1.0 - (post as f64 / cap);
    score -= tightness * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for any plausible item (min size 1..~20) are wasted.
    let dead_threshold = 20u32;
    if post_residual < dead_threshold {
        // Fully wasted residual -> strong penalty proportional to how close to useless it is.
        let waste = (dead_threshold - post_residual) as f64;
        score += 3.0 * waste;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus if the next item fits almost exactly afterwards.
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 5.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Residual too small for the next item: mild penalty if it's also below dead_threshold.
            score += 2.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.05 + 0.05 * progress);
    // Favor using existing bins when the post-residual is still usable.
    if post_residual >= dead_threshold {
        score -= pressure;
    } else {
        // Poor fit into an open bin under pressure -> penalize, may prefer a new bin.
        score += pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity; its post_residual is
    // large, so it naturally scores high (low priority). Add a mild bias so we only open a new
    // bin when the existing fit creates dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, opening new bins is slightly less attractive.
        score += 10.0 * progress;
    }

    // Mean residual coupling: if this bin is far below the mean residual (already tight),
    // filling it further is good; if it's the loosest bin, prefer tightening it anyway.
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect match: post_residual equals next_item_size -> strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins already fragmented (below mean residual)
    // so we preserve larger residual bins for future large items.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild penalty for wasting a nearly-full bin's identity on a loose fit.
    if item_size as f64 > 0.8 * bin_residual as f64 {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open new bins (keep options open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive baseline; more attractive early, less later.
        score = bin_capacity as f64 * 0.9 - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin trivially fits the next item too.
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            // Existing last-chance bin should win over a new bin.
            score += 50.0;
        }
    }

    // Late stream: consolidate aggressively, penalize opening new bins indirectly
    // by boosting existing-bin rewards.
    if progress > 0.8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already in score.

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit is good; reward proportionally to how snugly next item fits.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack_after_next / cap);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 20.0 {
                score += 6.0 * (1.0 - dead / 20.0);
            }
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 18.0 * fill_ratio;
        } else {
            score += 10.0 * (1.0 - fill_ratio); // poor fit in last bin: discourage
        }
    }

    // Penalize opening a new bin when decent open-bin options exist.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // New bin's post_residual equals cap - item_size; add penalty scaled by
        // how many open bins could have taken the item.
        score += 4.0 + 2.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds capacity for future).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.15 * mean_residual;
    } else {
        // Slight reward for using existing bins, stronger when many bins are open.
        score -= 2.0 + 0.3 * open_bins_count as f64;
    }

    // Global balance: prefer bins with residual below the mean (tighten small bins first),
    // keeps a spread of large residuals for big future items.
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Large items: placing them is urgent; any bin taking a big item gets a bonus.
    if item_size > bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, damped by progress (later items tolerate tighter fits)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth non-linear coupling: quadratic/cubic shaping of residual vs progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * norm_pr * norm_pr * progress;
    score += 20.0 * coupling;

    // Reward tight fits (small post residual) with a smooth saturating term
    score -= 15.0 * (-norm_pr * 6.0).exp() * (0.5 + 0.5 * progress);

    // Penalize residuals that are dead space for the next item (lookahead)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let waste_ratio = (nx - pr) / cap;
            score += 12.0 * waste_ratio * (1.0 - progress);
        } else {
            // next item fits in this residual: reward preserving usable space
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize fragmenting a bin when many bins are open (encourage consolidation)
    let mean_r = mean_residual / cap;
    score += 5.0 * norm_pr * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: keep it competitive only when item is large relative to residual
    if bin_residual == bin_capacity {
        score = pr + 10.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress) - 5.0 * mean_r;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class penalty: residuals that fall into "dead zones" (small leftovers that
    // few future items can use) are penalized super-linearly.
    let class_width = 10.0;
    let class_id = (pr / class_width).floor(); // integer division threshold on post_residual
    score += 0.35 * class_id * class_id;

    // Perfect/near-perfect fit reward: tiny post_residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic coupling with the lookahead item (k=2): reward residuals that
    // still admit the next item, penalize residuals that waste exactly the
    // space the next item would need (near-miss creates dead space).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
        } else {
            // near miss: post_residual just below next_item_size is a dead zone
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 8.0 {
                score += 12.0 + 2.0 * (8.0 - miss);
            }
        }
        // modulo coupling: if post_residual mod next_item_size is small,
        // the residual can be tiled efficiently by repeated next-size items.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the current bin would leave a large, awkward residual, or when
    // many bins are already open (fragmentation pressure).
    if bin_residual == bin_capacity {
        // base cost of consuming fresh capacity
        score += 15.0;
        // more open bins -> prefer filling existing ones less rigidly
        score += 0.5 * open_bins_count as f64;
        // early in the stream, opening bins is cheaper (long horizon to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if current placement would waste more than half the bin, new bin looks good
        if post_residual > bin_capacity / 2 && item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // balances the portfolio of open bins (keeps many medium residuals alive).
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * (-dev);
    }

    // Mild tightening pressure late in the stream: prefer tightest fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual is "dead" if it is smaller than the smallest plausible item (1..100 stream)
    // and especially if it's below a mid-range threshold.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 30.0; // tiny dead space, nearly unusable
        } else if post_residual <= 25 {
            score += 12.0; // marginal gap
        } else {
            // Larger usable leftovers are rewarded relative to post_residual baseline
            score -= (post_residual as f64 - 25.0).min(40.0) * 0.35;
        }
    } else {
        score -= 20.0; // perfect fill is excellent
    }

    // Reward exact or near-exact fits relative to residual size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the new-bin candidate and low-fill bins).
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 10.0 + open_pressure;
        // But if no existing bin fits well, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25; // blocking the next item
        }
    }

    // Early in the stream, be more liberal about opening bins (less pressure);
    // late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins that are already relatively full (low residual) for tight packing
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Slight preference toward bins below mean residual (balance residuals)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly matches post_residual,
    // this is a perfect chain — strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // If next item fits into post_residual, mild reward proportional to fill.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 50.0 * (next_item_size as f64 / post_residual as f64);
    }
    // If next item cannot fit in post_residual (dead space risk), penalize
    // large leftover gaps.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are more
    // "loaded"; placing there concentrates waste. Reward small residuals
    // relative to mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin opening when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of a fresh bin.
        score += 30.0;
        // If lookahead item would fill the new bin nicely, still allow.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) < next_item_size as f64 {
            score -= 10.0;
        }
        // Late in stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 20.0;
        }
    }

    // Waste-avoidance: penalize creating residual that is too small for
    // typical future items but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize leaving residuals that are small-but-nonzero dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if the next item fits into the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }
    // Penalize if next item almost fits but not quite (blocking good residual).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 15.0 {
            score += 2.0 * (1.0 - miss / 15.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing residuals are fragmented/large mean.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0; // base cost of opening a bin
        if mean_residual > 40.0 && fragmentation < 20.0 {
            score -= 8.0; // open bins are roomy and similar; a fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 5.0 * progress;
    } else {
        // Prefer bins with larger residual generally (use up emptier bins first),
        // but tempered by mean residual to avoid starving balanced bins.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild pressure to close nearly-full bins.
    if post_residual <= 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear shaping (favor small post-residuals quadratically)
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more strongly.
    let progress_coupling = 1.0 + 3.0 * progress * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Dead-space penalty: post-residual too small for any plausible future item
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.05 } else { 0.0 };
    score += dead;

    // Lookahead: reward if next item fits into post-residual (smooth reward)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (gap / cap).exp() * 8.0 * (1.0 + progress);
        } else {
            score += (-gap / cap).exp() * 3.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward to avoid new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.3 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Prefer bins whose residual deviates from mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * (1.0 - (dev / cap).min(1.0));

    // New-bin candidate: keep it competitive only when current fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    // Small post_residuals are "good" (near-full bins); large ones waste capacity.
    let post = post_residual as u32;
    let class = post % 10;
    match class {
        0 => score -= 6.0,           // perfectly aligned residual (10/20/.../90)
        1 | 2 | 3 => score -= 3.0,   // tight residual, likely unusable anyway
        4 | 5 | 6 => score += 2.0,   // mid-band: awkward dead space
        _ => score += 4.0,           // 7..9: large awkward residual
    }

    // Integer-division threshold: does the leftover fit the lookahead item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // Lookahead fits: reward, scaled by how "complementary" it is.
            let slack = (post - next_item_size) as f64;
            score -= 8.0 - slack * 0.15;
            // Harmonic bonus: post_residual - next_item_size landing in small residue class
            let combo_class = (post - next_item_size) % 10;
            if combo_class <= 3 { score -= 3.0; }
        } else {
            // Lookahead does NOT fit: penalize proportionally to wasted opportunity.
            let deficit = (next_item_size - post) as f64;
            score += deficit * 0.25;
            // If lookahead is large (>= half capacity), prefer keeping big residuals.
            if next_item_size >= bin_capacity / 2 { score -= 2.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Multiple fits: slight penalty to prefer best-fit competition dynamics.
        score += 1.0;
    }

    // Coupling with mean residual: bins far from the mean get normalized.
    score += (post as f64 - mean_residual) * 0.1;

    // Prefer closing bins late in the stream (fewer open bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post <= 5 { score -= 4.0 * progress; }

    // New-bin candidate (empty bin): only attractive when nothing fits well
    // or residual is very tight elsewhere; penalize default new-bin usage.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post < next_item_size && fitting_bins_count == 1 {
            score -= 14.0; // still allow escape hatch for hopeless fits
        }
    }

    // Exact fill: perfect bin closure.
    if post == 0 { score -= 15.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to be useful for typical future items (unusable small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Perfect fit bonus: exact fill leaves zero residual.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins (penalize the new-bin candidate) and encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 20.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Reward using existing bins, scaled by open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // next item can still fit here
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., more filled bins), keeping emptier bins flexible.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space quadratically (small residuals are tolerable).
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: two items packed perfectly in sequence
        } else if post_residual >= next_item_size {
            score -= 50.0; // next item still fits here
        } else {
            score += 30.0; // next item would not fit; dead space risk
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Relative residual coupling: prefer bins tighter than the mean residual
    // (concentrate waste into few bins rather than spreading it).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early stream: be slightly more willing to open new bins to build a spread
    // of residual sizes; late stream: be frugal, reuse existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-dependent reluctance.
        score += 120.0 + 200.0 * progress;
        // If no open bin can fit at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted lookahead potential.
        score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation
    // (filling existing bins) over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64 / 20.0).min(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are crowded or late in stream.
        score += 6.0 + 10.0 * crowding + 8.0 * progress;
        // But if this bin is the only option, the last-chance bonus above
        // already steered away; still allow new bin when fits are terrible.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is near the mean residual (balance load).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for bins with larger residual when early in stream
    // (keep small-residual bins for small items later).
    score += 0.02 * (bin_residual as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening over time
    let mut score = pr * (1.0 + 1.5 * progress) + 200.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (post_residual near 0) more aggressively late in stream
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 25.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }

    // Prefer bins with below-mean residual (consolidate waste)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (0.4 + 0.6 * progress);

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: neutral early, penalized late
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward leftovers that are exactly representable by small item sums.
        let harmonic = (pr % 10 == 0) as i32
            + (pr % 20 == 0) as i32
            + (pr % 25 == 0) as i32
            + (pr % 50 == 0) as i32;
        score -= 6.0 * harmonic as f64;

        // Penalize dead space: leftovers too small for the minimum item (size 1
        // possible, but small leftovers < 12 are rarely reusable).
        if pr < 12 {
            score += 25.0;
        }
        // Perfect fit is ideal.
        if pr == 0 {
            score -= 40.0;
        }
    } else {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        // Extra reward if the pair leaves another harmonic leftover.
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to wasted lookahead.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is
    // terrible and many bins are open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let phase = step_index as f64 / (total_items.max(1) as f64);
        if tightness > 0.75 && open_bins_count > 3 && phase < 0.8 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (fills emptier-than-average bins first, keeping tight bins for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Integer-division threshold: bins whose residual allows two more medium
    // items (residual/25 >= 2) are attractive.
    if pr / 25 >= 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Dead-space penalty: post_residual that is too small to fit the next item
    // (or any typical item) is nearly unusable; penalize it harshly.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful {
        let gap_severity = 1.0 - (post_residual as f64 / min_useful.max(1) as f64);
        score += 25.0 * gap_severity;
    }
    // Also penalize gaps too small for even the smallest possible item (hard dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; when few bins are open, tolerate spreading.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64)).min(2.0);
    score += 5.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin is attractive only if the
    // current item is large relative to capacity or fits would waste space.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening fresh is good for very large items (they dominate a bin anyway).
        score -= 30.0 * fill_ratio * fill_ratio;
        // But discourage opening new bins when decent fitting bins exist.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidation.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for bins below mean residual (balancing load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize dead space.
            score += 30.0;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit.
    if bin_residual == bin_capacity {
        score += 50.0 + 5.0 * open_bins_count as f64;
    }

    // Late in the stream: prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed; early phase favors consolidation, late phase favors tight packing.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (small dead space), with non-linear squashing.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap).powf(1.5);
    score -= 12.0 * tightness * (1.0 + 0.5 * t);

    // Penalize leaving residuals that are too small to be useful for typical items (dead space).
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr as f64);
    }
    // Medium dead space (10..30) is mildly wasteful too.
    if pr >= 10.0 && pr < 30.0 {
        score += 0.15 * (30.0 - pr as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining placements).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // Bonus scaled by how well the next item fills what remains after.
            let chain_fill = nx / (pr + 1.0);
            score -= 8.0 * chain_fill * (1.0 - t * 0.5);
        } else {
            // Penalize bins that would strand a residual the next item cannot use.
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild preference toward fuller bins (larger item_size share).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 4.0 * fill_ratio;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when the item
    // is large and no good consolidation exists, or the global state is saturated.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 10.0;
        // Large items justify fresh bins (avoid fragmenting big items into tight bins).
        new_bin_penalty -= 14.0 * item_frac * item_frac;
        // If mean residual across open bins is low (bins nearly full), a new bin is natural.
        new_bin_penalty -= 0.08 * (cap - mean_residual);
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty += 6.0 * t;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            new_bin_penalty += 5.0 + 2.0 * fitting_bins_count as f64;
        }
        score += new_bin_penalty;
    }

    // Global consolidation pressure: when many bins are open, prefer bins below mean residual
    // (fill emptier bins) to reduce total open-bin count; early in stream allow spreading.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * (1.0 - t);
    }

    // Mild preference for bins with more residual early (keep tight bins for small items).
    if item_size <= 30 && bin_residual != bin_capacity {
        score -= 2.0 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), smoothed
    let mut score = pr * (1.0 + 0.8 * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder.
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress) - 6.0 * norm_pr * progress;

    // Coupling with mean residual: prefer bins near the mean (harmonic packing)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.1;

    // Perfect/near-perfect fit reward (smooth exponential-ish via polynomial)
    if pr == 0 {
        score -= 20.0;
    } else {
        score -= 15.0 * (1.0 - norm_pr).powi(6) * (pr as f64).min(20.0) / 20.0;
    }

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let tight = (next_item_size as f64 - pr).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - tight) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild pressure against proliferating bins early
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 residue classes
    let post_class = post_residual % 10;
    // Dead-space penalty: residuals in (0,10) are nearly unusable for min item size 10
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Reward post residuals that are perfect fits or large reusable chunks
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual >= 50 {
        score -= 5.0;
    }

    // Harmonic fraction: post_residual relative to capacity
    let frac = post_residual as f64 / cap;
    score += (frac * (frac - 0.5) * (frac - 1.0)).abs() * 10.0;

    // Integer-division thresholds on post_residual: quarters of capacity
    let quarter = bin_capacity / 4;
    match post_residual / quarter {
        0 => score += 8.0,          // tiny leftover: bad
        1 => score += 0.0,
        2 => score -= 3.0,          // half-full: good
        _ => score -= 6.0,          // still roomy: very good
    }

    // Next-item coupling: reward leaving space that matches next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_diff = post_residual - next_item_size;
            if slack_diff % 10 == 0 {
                score -= 12.0;      // harmonic alignment with next item
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0;           // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // penalize new bin mildly; it wins only if open-bin scores exceed this
        score = 0.35 * cap + 10.0 * pressure * (1.0 - progress);
        if post_residual < 10 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild dispersion penalty: avoid fragmenting when mean residual already low
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Non-linear penalty: squared waste scaled by how much of the bin it strands.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 8.0 / (1.0 + tightness);
    }

    // Open-bin pressure: discourage spreading across many bins, but
    // relax near the end of the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - 0.5 * progress) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins) for small items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call happens with a fresh bin and current fit is poor).
    if bin_residual == bin_capacity {
        // Base new-bin score: modest, so poor fits in open bins lose to it,
        // but good fits in open bins beat it.
        score = 45.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits; new bin is fine
        }
        if item_size >= 80 {
            score -= 10.0; // huge items: fresh bin natural
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // --- 2-step lookahead matching archetype ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect refill: post_residual exactly matches next item -> big reward.
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: reward proportional to closeness of match.
            let gap = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 40.0 * (1.0 - gap).max(0.0);
        } else {
            // Next item will NOT fit: penalize dead space that strands the lookahead.
            let waste = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 30.0 * waste;
        }
    } else {
        // Last item: minimize residual directly (already base), small bonus for tight fit.
        score -= 5.0;
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // below mean (already fragmented) to absorb this item.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: only bin that can fit the item -> strong reward to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin starts with high residual.
    if bin_residual == bin_capacity {
        // Prefer new bin when the item leaves a large awkward residual that
        // neither the next item nor typical residuals can use, or when few
        // fitting alternatives exist.
        let awkward = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64
        } else {
            0.0
        };
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + 20.0 * awkward - 15.0 * progress;
        // If this is the only option, make it win anyway.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly or well into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 10.0 * next_fit;
        if next_item_size == post_residual {
            score -= 15.0; // perfect pairing
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Post residual too small for next item: penalize proportionally to wasted space.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the stream
    // or when it would pair well with the next item; otherwise penalize.
    if bin_residual == bin_capacity {
        score += 18.0; // base cost of opening a new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress); // cheaper to open bins early
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // new bin can host a fresh pair
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Global state coupling: prefer bins whose residual is far from the mean residual
    // (keeps the population of residuals diverse, easing future fits).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for using more-filled bins as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear penalty on dead space, amplified by stream progress
    let dead = norm_post * norm_post;
    score += 30.0 * dead * (0.5 + progress);

    // Reward high fill ratio with a cubic coupling
    let fill = 1.0 - norm_post;
    score -= 20.0 * fill * fill * fill;

    // Interaction: post_residual vs next item lookahead
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            // next item can fit in the leftover: reward smooth quadratic
            let gap = (post - nx) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            // leftover too small for next item: penalize quadratically
            let excess = (nx - post) / cap;
            score += 10.0 * excess * excess;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post);
    } else {
        // many alternatives: mild penalty for wasting a scarce bin
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * dead;
    }

    // Coupling with mean residual of open bins: prefer bins below mean (tighter)
    let diff = (mean_residual - post) / cap;
    score += 6.0 * diff * diff - 3.0 * diff;

    // Late-stream smooth boost for consolidation
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but with harmonic (fraction-of-capacity) shaping.
    let frac = post_residual as f64 / bin_capacity as f64;
    score = frac * bin_capacity as f64;

    // Harmonic residue classes on post_residual: dead space in awkward classes is penalized.
    let r = post_residual % 10;
    let awkward = match r {
        1..=9 => 2.0 + (r as f64) * 0.1, // small unusable slivers
        _ => 0.0,
    };
    score += awkward;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally: leftover that chains well is cheap.
            score -= (next_item_size as f64) * 0.5;
            // Extra reward if post residual is "harmonically close" to next item (tight chain).
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 15.0 - gap as f64;
            }
        } else {
            // Dead space that cannot host the next item: penalize by class.
            let wasted = post_residual as f64;
            score += wasted * 0.3;
            // Integer division threshold: post_residual below half-capacity is nearly dead.
            if post_residual < bin_capacity / 2 {
                score += 10.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current bin's post
    // residual is bad relative to the next item; otherwise open bins should win.
    if bin_residual == bin_capacity {
        // Fresh bin has full residual; score it by what a fresh bin would leave after this item.
        let fresh_post = bin_capacity - item_size;
        score = fresh_post as f64;
        if next_item_size > 0 && fresh_post < next_item_size {
            score += 5.0;
        }
        // Opening a new bin is generally costly while good fits exist; add a base cost
        // that tight fits in existing bins can overcome.
        score += 25.0;
        // Late in the stream, opening new bins is less harmful (fewer future regrets).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean, it's a
    // "loose" bin; using it now is fine, but leaving it is also fine. Slight penalty
    // for using high-residual bins with big items keeps balanced bins available.
    if bin_residual as f64 > mean_residual + 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // risky small gap
    }

    // Reward tight fits (low post_residual relative to item size).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let fit_ratio = post_residual as f64 / bin_residual as f64;
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residuals below the mean (fill the emptier-toward-full bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += 30.0 + desperation;
        // Early in stream, opening a fresh bin is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            // Perfect match for next item is highly desirable.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward for near-exact match.
            if gap <= 5.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; the leftover post_residual is likely dead space.
            let unusable = next - post;
            score += 0.3 * unusable.min(40.0) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize opening a new bin, but less when current bin leaves bad leftovers.
        let leftover_waste = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 60.0 - 25.0 * scarcity - 0.5 * leftover_waste;
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Penalize creating very small unusable slivers.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to lookahead: penalize small unusable leftovers.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 8.0 * (1.0 - waste / next_item_size as f64);
            }
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 30.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // (mean residual high relative to capacity) or many bins already open.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).sqrt();
        let penalty = 55.0 + 45.0 * frag + 20.0 * pressure;
        score += penalty;
        // Rarely worth opening a new bin early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // But if the item is large and would leave tiny dead space anywhere, new bin
        // becomes competitive: reduce penalty when item is big.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Mild preference for bins with residual close to item (best-fit flavor)
    // and slight penalty for leaving residual that's too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tie-break: prefer bins with lower index-ish pressure (fewer open bins is better globally).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill level before placement
    let fill = 1.0 - (bin_residual as f64 / cap);

    // Non-linear coupling: reward tight fits more strongly as the stream progresses.
    // Tightness = how much of the bin's residual the item consumes (saturating polynomial).
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    let tight_reward = tightness.powi(3) * (1.0 + 2.0 * progress) * cap * 0.6;
    score -= tight_reward;

    // Non-linear penalty for leaving awkward dead space: residuals that are too small
    // for typical items are wasted. Penalize small post_residual with a quadratic dip.
    let pr = post_residual as f64;
    let dead = (1.0 - pr / cap).powi(2) * cap * 0.25 * (1.0 - progress);
    score -= dead;

    // Penalize post_residual that can't fit the lookahead item (smooth interaction).
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * 0.5 * (0.5 + 0.5 * (1.0 - progress));
        // Reward if lookahead fits exactly in post_residual (perfect chaining)
        let chain = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= chain.powi(2) * 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (1.2 + progress);
    }

    // Many open bins: encourage consolidation onto fuller bins (couple with mean residual).
    let mean_term = (bin_residual as f64 - mean_residual) / cap;
    score -= mean_term * mean_term * 20.0 * (open_bins_count as f64).ln().max(1.0) * (0.3 + 0.7 * progress);

    // New-bin candidate (empty bin): make it attractive only when nothing else fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Slight opening cost that grows with progress (prefer packing into existing bins early)
        score = cap + 5.0 + 15.0 * progress + (open_bins_count as f64) * 0.5;
        // If the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / cap).powi(2) * 30.0;
        // If this is the only fitting option, allow it
        if fitting_bins_count == 1 {
            score -= cap * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into residue classes modulo 10.
    // Small post_residuals are "dead space" of low harmonic order -> reward them.
    let cls = post_residual % 10;
    let harmonic_reward = match cls {
        0 => 12.0, // perfect class: residual divisible by 10, highly reusable
        1..=3 => 8.0,
        4..=6 => 4.0,
        _ => 0.0,
    };
    score -= harmonic_reward;

    // Integer-division threshold: post_residual / item_size ratio
    // (how many copies of the current item still fit) — better packing potential.
    if item_size > 0 {
        let copies = post_residual / item_size;
        score -= (copies as f64) * 6.0;
    }

    // Capacity-fraction coupling: reward filling a bin past half capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 20.0;

    // Penalize near-full-but-wasteful residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead harmonic coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // modulo harmony: post_residual % next_item_size small => chain fits
            if next_item_size > 0 {
                let m = post_residual % next_item_size;
                score -= (10 - m.min(10)) as f64 * 0.5;
            }
        } else if next_item_size <= post_residual + 10 {
            score += 6.0; // next item nearly fits — wasted opportunity
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 30.0;
        // But if open bins are fragmented (high mean residual, many bins),
        // a fresh bin becomes attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= (mean_residual - 40.0).min(40.0) * 0.8;
        }
        if progress > 0.9 {
            score += 10.0; // late stream: consolidate rather than open
        }
    }

    // Mild pressure against spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are the worst outcome.
    // A residual that no plausible future item (>=1) can use is pure waste.
    if post_residual > 0 && post_residual < 12 {
        // The smaller the dead gap, the more expensive it is per unit wasted.
        let dead = (12 - post_residual) as f64;
        score += dead * dead * 1.5;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // This placement strands the lookahead item: penalize.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, strongly prefer reusing
    // existing capacity rather than fragmenting across bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 4.0;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing bins are nearly full or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin, reduced when mean residual across open bins
        // is small (open bins are crowded) or late in the stream.
        let mut new_cost = 55.0
            - mean_residual * 0.35
            - stream_progress * 15.0
            - (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if new_cost < 5.0 { new_cost = 5.0; }
        score += new_cost;
        // A new bin has no dead space, so strip the small-gap penalty logic's
        // effect by ensuring its score is dominated by new_cost.
        score = score.max(new_cost);
    }

    // Mild preference for bins whose residual is close to the item (tight fit
    // ranking among multiple fitting bins).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly or nearly
    // fills the residual left behind by this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: post_residual == next_item_size -> strong reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
        // Next item fits with a tiny leftover -> near-perfect 2-step packing.
        if next_item_size <= post_residual {
            let two_step_left = post_residual - next_item_size;
            score -= 4.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // resources; discourage wasting them on loose fits, encourage tight fits.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * mean_gap * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless nothing else
    // fits well — i.e. only win when all open bins leave bad post-residuals.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large and current item small, a fresh bin pairs well.
        if next_item_size >= 50 && item_size <= 50 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild preference for keeping fewer open bins when this bin is nearly full.
    if post_residual <= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    if post_residual > 0 && post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 2.5; // residual likely wasted relative to lookahead
    }

    // Lookahead coupling: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when few bins fit the item or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let pressure = if fitting_bins_count == 0 { 25.0 } else { (fitting_bins_count as f64).recip() * 6.0 };
        score += 10.0 + crowd * 0.5 - pressure;
        // Late in the stream, slightly discourage opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
    }

    // Mild preference for bins below mean residual (keeps large residuals available).
    score += (bin_residual as f64 - mean_residual) * 0.03;

    // Early stream: encourage filling bins fully; late stream: avoid fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual polynomial in progress.
    // Early in stream, prefer tight fills (low post_residual) less aggressively;
    // late in stream, weight wasted space more.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.3;

    // Penalty for opening a new bin when fitting bins exist (smooth cubic ramp in progress).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let fitting_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 25.0 * (1.0 - progress * progress * progress) * (1.0 + fitting_pressure);
    }

    // Reward bins whose post_residual cannot fit the next item (dead space avoided),
    // or that fit next item exactly (smooth quadratic term).
    if next_item_size > 0 && !is_new_bin {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item still fits here: mild reward for tight double-fit
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item won't fit: reward using up space fully
            score -= 2.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins below mean residual (consolidation), smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev - 0.5 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/8, 1/4, 1/2)
    let item_class = item_size / (bin_capacity / 8).max(1);
    let next_class = next_item_size / (bin_capacity / 8).max(1);

    // Reward near-perfect fits: post_residual small relative to capacity
    if post_residual == 0 {
        score -= bin_capacity as f64 * 1.5;
    } else if post_residual <= 5 {
        score -= bin_capacity as f64 * 0.8;
    }

    // Penalize dead space: post_residual too small to fit the smallest plausible item class
    let min_class = (bin_capacity / 8).max(1);
    if post_residual > 0 && post_residual < min_class {
        score += bin_capacity as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= bin_capacity as f64 * 1.2;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= bin_capacity as f64 * 1.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize proportionally to wasted pairing potential
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
        // Harmonic class match: same coarse class items pair well
        if item_class == next_class && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Modulo harmonic structure on post_residual: multiples of quarter-capacity are reusable slots
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer bins with low residual relative to mean (fill fuller bins first)
    let residual_gap = post_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Slight preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Late-stream tightening: as stream progresses, penalize leaving large residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: opening a new bin is only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; discount if item is large (hard to place later)
        let base = bin_capacity as f64 * 0.6;
        if item_size > bin_capacity / 2 {
            score = base - 10.0;
        } else {
            score = base + post_residual as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let mut new_score = dead;
        if dead > 0.0 && dead < 10.0 {
            new_score += 60.0 - 5.0 * dead;
        }
        if fitting_bins_count > 0 {
            new_score += 15.0; // discourage opening when a bin fits
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/near-exact fits: small post_residual is the core signal.
    score += (post_residual as f64 / bin_capacity as f64).powf(3.0) * 40.0;

    // 2-step lookahead: reward when next item fits into this bin's post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here: penalize proportionally to wasted potential.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is tighter than the mean (good fit relative to fleet).
    score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If many bins are open and mean residual is large, discourage new bins more.
        score += 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in stream: be conservative, keep bins open; late: allow tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally to wasted gap.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
        } else {
            // Reward bins that can still host the next item after this placement.
            score -= 4.0;
        }
        // Bonus if item + next item pack perfectly into this bin.
        let pair = item_size as u32 + next_item_size;
        if pair == bin_residual {
            score -= 10.0;
        }
    } else {
        // Last item: only tightness matters; strongly reward near-perfect fills.
        score -= 6.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }
    // Many fitting bins: mildly discourage spreading, prefer the tightest anyway.
    if fitting_bins_count > 2 {
        score += 0.35 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins
    // rather than fragmenting; when low, opening fresh bins is less costly.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.12 * mean_gap;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    // New-bin candidate handling: it is only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by how bad the best existing
        // option would be (approximated via mean residual vs item size).
        let poor_fit_pressure = if post_residual_of_best_unavailable() { 0.0 } else { 0.0 };
        let _ = poor_fit_pressure;
        let open_cost = 28.0
            - 6.0 * (1.0 - tightness) // empty bin has zero tightness; negligible
            + 0.25 * open_bins_count as f64
            - 10.0 * (1.0 - progress); // early stream: new bins cheaper
        // If item fits almost perfectly in an existing bin elsewhere, new bin loses;
        // if item is huge relative to mean residual, new bin becomes attractive.
        let squeeze = (item_size as f64 - mean_residual).max(0.0);
        score = open_cost - 0.4 * squeeze;
    }

    // Small stochastic-free tie-break: prefer bins with more residual after placement
    // only when residuals are tiny (avoid leaving 1-2 unit slivers unusable).
    if post_residual > 0 && post_residual < 4 {
        score += 2.5;
    }

    score
}

// Helper kept inline-free: placeholder that always returns false (no external state allowed).
fn post_residual_of_best_unavailable() -> bool { false }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer balanced fills; Late: strongly prefer tight fills.
    let pr_norm = pr / cap;
    let poly = pr_norm.powf(1.6 + 1.4 * progress) * (1.0 + 2.0 * progress * progress);

    // Reward tight fit (small post_residual), stronger later in stream.
    let tightness = (1.0 - fit_ratio).powi(2) * (3.0 + 4.0 * progress);

    // Lookahead: penalize if post_residual cannot hold the next item.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt { 8.0 + 6.0 * progress } else { -0.5 * (pr - nxt) / cap }
    } else { 0.0 };

    // Last-chance bin: reward strongly to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -6.0 - 4.0 * progress } else { 0.0 };

    // Penalize deviation from mean residual (fragmentation spreading).
    let mean_dev = ((pr - mean_residual) / cap).abs() * (1.0 + progress);

    // New empty bin candidate: mild default cost so it wins only when fits are bad.
    let new_bin_penalty = if bin_residual == bin_capacity { 4.0 + pr * 0.02 } else { 0.0 };

    let mut score = poly + tightness + mean_dev + new_bin_penalty + lookahead + last_chance;
    score -= fit_ratio * 2.0; // reward larger items filling bins
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Residuals divisible by 10 are "clean" classes (likely reusable by future items).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal closure
    } else if pr % 10 == 0 {
        score -= 12.0; // clean harmonic class, highly reusable
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 4.0; // dirty residual class
    }

    // Integer-division thresholds: small residuals are dead space.
    if pr < 10 {
        score += 25.0; // unusable for any item (min size 1..100 but typical classes)
    } else if pr < 20 {
        score += 10.0;
    }

    // Fraction-of-capacity coupling: how full the bin becomes.
    let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // --- Lookahead coupling with next item size (harmonic match) ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // next item exactly fills this bin
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 15.0; // next item leaves a clean class again
            } else if gap < 10 {
                score += 6.0; // next item creates dead space
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 5.0 + 0.1 * (next_item_size - pr) as f64;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // strongly prefer using the only fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer a fresh bin only if existing bins would leave dirty tiny residuals
        // and the item is large; otherwise discourage waste of capacity.
        let dirty_penalty = if pr % 10 != 0 { 18.0 } else { 0.0 };
        score += 35.0 - dirty_penalty + 0.3 * open_bins_count as f64;
    }

    // --- Stream progression: early on, be conservative; late, close bins aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    // --- Mean residual context: spread load away from bins near mean residual ---
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // tiny dead space is very bad
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.5;
        }
        // Reward exact fits strongly
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Penalize bins with large residual only if the gap left is unusable for typical items
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 8.0; // this bin's leftover won't fit the lookahead item
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress
        score += 40.0 + 3.0 * open_bins_count as f64 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if existing fits are all poor (large post_residual), new bin looks better:
        // handled naturally since poor fits carry dead-space penalties.
    } else {
        // Mild reward for keeping bins tight relative to mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Lookahead synergy: reward leaving space exactly usable by next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already in base).

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // reward proportional to how little would remain after the next item
            score -= 30.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize large dead space slightly
            let gap = (next_item_size - post_residual) as f64;
            score += 0.1 * gap;
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score -= 20.0;
    }

    // Relative-to-mean-residual term: prefer bins whose residual is below average
    // (i.e., already well-filled bins) to consolidate waste.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the fit is bad
    // or no lookahead chaining is possible.
    if bin_residual == bin_capacity {
        // neutral base for empty bin; add penalty that shrinks if item is large
        score += 10.0 - 0.05 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain with next item
        }
    }

    // Early in the stream, allow slightly more bin opening (build diversity of residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins: encourage consolidation late in stream.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (low post residual) super-linearly
    score -= 40.0 * (1.0 - post_frac) * (1.0 - post_frac) * fill;

    // Penalize leaving dead space that no future item can plausibly use.
    // Smallest item is 1, so residual < ~threshold is dead space.
    let dead_threshold = 12.0f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold {
        score += 8.0 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = next_item_size as f64 / bin_capacity as f64;
            score -= 15.0 * chain + 6.0;
            // extra bonus when the chain leaves almost nothing
            let chain_post = post_residual as f64 - next_item_size as f64;
            if chain_post < dead_threshold {
                score -= 5.0;
            }
        } else {
            // gap between post residual and next item: wasted opportunity
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < dead_threshold {
                score += 4.0 * (dead_threshold - gap) / dead_threshold;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild competition pressure toward best fit
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: prefer consolidating into fewer bins when mean residual is tight
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 10.0 * tightness * (1.0 - t);

    // Late in the stream: discourage opening new bins even more
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 + 4.0 * open_pressure + 20.0 * t;
        // new bin is attractive only if item is large and no tight option exists
        score -= 18.0 * fill;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Small per-bin load balancing nudge: prefer bins with residual near mean
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize leftover residual, with a super-linear term to
    // strongly discourage large unusable gaps.
    let mut score = norm_pr * 10.0 + norm_pr * norm_pr * 20.0;

    // Smooth polynomial coupling: residual usefulness depends on stream progress.
    // Early in the stream, waste is cheaper; later, waste is costly.
    let progress_coupling = (norm_pr * norm_pr) * (1.0 + 3.0 * progress * progress);
    score += progress_coupling * 15.0;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = norm_item * (1.0 - norm_pr);
    score -= tightness * 12.0;

    // Lookahead coupling: if the next item fits in the post residual,
    // reward; otherwise penalize proportionally to the mismatch.
    if next_item_size > 0 {
        let gap = norm_next - norm_pr;
        if gap <= 0.0 {
            // next item fits: smooth reward scaled by how well it fills
            let fill = (-gap) / norm_pr.max(1e-6);
            score -= fill * fill * 8.0;
        } else {
            // next item does not fit: penalize wasted opportunity,
            // stronger as stream progresses.
            score += gap * gap * (10.0 + 20.0 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins to
        // encourage consolidation onto the best-fit candidate.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Mean-residual coupling: prefer bins whose residual deviates
    // favorably (smaller) from the fleet mean, smoothly.
    let mean_norm = mean_residual / cap;
    let deviation = mean_norm - norm_pr;
    score -= deviation * 4.0;

    // Open-bin pressure: with many open bins, prefer filling existing
    // ones; the new-bin candidate (norm_pr large) is naturally penalized
    // by the base terms, but add smooth extra pressure.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += norm_pr * pressure * 10.0;

    // Exact-fill celebration: smooth steep reward as post_residual -> 0.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonic"
    // (item sizes / common sizes divide into them well).
    let cap = bin_capacity as f64;

    // Fractional class of post_residual relative to capacity.
    let frac = post_residual as f64 / cap;
    if frac > 0.9 {
        // Nearly empty bin after placement: wasteful, penalize.
        score += 30.0 * (frac - 0.9);
    } else if frac < 0.10 {
        // Tight fit: excellent packing, strong reward.
        score -= 25.0 * (0.10 - frac);
    }

    // Integer-division harmonic classes: does next_item_size (or small items)
    // fit exactly into the post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 20.0; // perfect harmonic continuation
        } else if rem <= 10 {
            score -= 8.0; // near-perfect
        } else {
            score += 2.0; // mediocre continuation
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, stronger if residual is large.
        score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Divisibility classes of post_residual by common item sizes.
    for d in [10u32, 20, 25, 50] {
        if post_residual >= d && post_residual % d == 0 {
            score -= 5.0;
            break;
        }
    }

    // Last-chance bin: reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless current residuals are all bad.
    if bin_residual == bin_capacity {
        let bad_open = mean_residual < 15.0 || open_bins_count == 0;
        if bad_open && post_residual > 0 {
            score -= 5.0;
        } else {
            score += 40.0; // prefer reusing open bins generally
        }
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    // Small coupling: penalize leaving residual just below the smallest item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: post_residual too small for any realistic item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize medium-small gaps that likely can't fit future items
    if post_residual >= 10 && post_residual < 40 {
        score += 0.5 * (40.0 - post_residual as f64);
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // New-bin candidate: neutral baseline with mild penalty, only preferred when fits are bad
    if bin_residual == bin_capacity {
        score = 45.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already in base score).

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item,
    // with extra reward for near-perfect 2-item packing (post_residual == next_item_size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect chain: post_residual exactly equals next item size -> almost free second placement.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward decreases as leftover after the lookahead item grows (dead space).
                score -= 40.0 * (nxt / post) - 0.25 * gap;
            }
        } else {
            // Next item cannot fit here: penalize proportionally to how much dead space remains.
            score += 0.35 * post;
            // If next item would fit a fresh bin perfectly, discourage wasting this bin's space.
            if nxt >= bin_capacity as f64 - post {
                score += 5.0;
            }
        }
    }

    // Coupling with mean residual: placing into a bin with residual far below mean
    // (i.e., a well-filled bin) is good; bins with residual above mean are wasteful targets.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.20 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (pristine bin): only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain to fill it
        // and when existing bins are all poor fits (high mean residual).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 15.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            // A fresh bin trivially fits everything; neutralize some penalty if the
            // lookahead also chains well from a full bin.
            score -= 10.0;
        }
        // If few fitting bins exist, opening a new bin is less harmful.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating items into fewer bins when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when it offers a great fit or few bins fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin is attractive early or when item is large relative to capacity
        let new_bin_bonus = 20.0 * (1.0 - progress) + 0.3 * item_size as f64;
        score += (post_residual as f64) - new_bin_bonus.min(60.0);
        if fitting_bins_count <= 1 {
            score -= 35.0; // opening a fresh bin better than a bad squeeze
        }
    }

    // Mild preference for bins with residuals close to the item (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Global state coupling: many open bins with high mean residual -> consolidate
    if open_bins_count > 3 && mean_residual > 20.0 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Time horizon: late in the stream, avoid fragmenting bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual > 0 {
        score += 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * prn * prn);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; later penalize them more heavily
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * prn * prn * cap * 0.3;

    // Reward filling a bin almost completely (near-perfect fit), stronger late
    let fill_bonus = (1.0 - prn).powi(3) * (10.0 + 20.0 * progress);
    score -= fill_bonus;

    // Dead-space penalty: residual too small to ever fit typical items
    let dead_threshold = 0.1;
    if prn < dead_threshold {
        score += (dead_threshold - prn) * cap * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= bin_pressure * 3.0 * (1.0 - prn);

    // Lookahead: if next item fits in the resulting residual, reward; else penalize
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 4.0 * (1.0 - (n / pr.max(1.0)).abs() - 1.0).abs().min(1.0);
            score -= 4.0 * (pr - n) / cap * -1.0 * -1.0; // small extra reward for snug lookahead fit
            score -= 4.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 2.0 * progress * (n - pr) / cap;
        }
    }

    // Slight preference for bins with below-mean residual (tighter bins first)
    score += 0.5 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: only attractive when no good fit exists (large post_residual
    // relative to item, or very few fitting bins); otherwise discourage
    if bin_residual == bin_capacity {
        let escape_valve = (1.0 - irn) * (1.0 - prn) * (fitting_bins_count as f64).recip();
        score += 12.0 - 10.0 * escape_valve - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Harmonic class term: penalize residuals in awkward modulo classes.
    // Residuals divisible by 10 are "harmonic" with typical item scales;
    // ragged remainders are more likely to become dead space.
    let r = post_residual;
    score += ((r % 10) as f64) * 0.4;

    // Deep-dead-space class: residual in [1,9] can only host tiny items;
    // if it exists, prefer it strongly (bin is nearly closed) — but if it is
    // mid-range and cannot host the lookahead item, it is likely wasted.
    if next_item_size > 0 {
        if r >= next_item_size {
            // Lookahead fits: reward chaining placements.
            score -= 20.0 + 0.3 * (next_item_size as f64);
        } else if r >= 10 {
            // Dead space that the next item cannot use.
            score += 6.0 + 0.2 * (r as f64);
        } else {
            // Tiny residual: bin effectively closed, that is fine.
            score -= 10.0;
        }
    } else {
        // Last item of the stream: minimize leftover outright.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Coupling with mean residual: placing into a bin whose post-residual
    // stays below the mean keeps the bin spread tight.
    if (r as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: raise its baseline so it only wins when all open
    // fits are poor; relax this penalty late in the stream when closing
    // bins cleanly matters more.
    if bin_residual == bin_capacity {
        score += 18.0 - 8.0 * progress;
        // Opening a new bin is more attractive when few bins are open.
        if open_bins_count <= 2 {
            score -= 6.0;
        }
    }

    // Slight late-stream pressure to consolidate into existing bins.
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable gap penalty
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else {
        // Larger residuals are progressively more reusable: reward them.
        score -= 0.15 * post_residual as f64;
    }

    // Tight fit reward: the smaller post_residual relative to capacity, the better.
    score -= 2.5 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Dead space relative to bin capacity: quadratic penalty for mid-range gaps
    // that are too big to ignore but awkward to fill.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 0.002 * pr * pr * (1.0 - pr / bin_capacity as f64);
    }

    // Perfect fit: zero waste is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current fit is bad
    // or the item is large enough that a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // A new bin is attractive only for large items leaving small residuals,
        // or when existing bins are too full on average.
        score += 30.0;
        score -= 25.0 * fit_quality;
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        if item_size >= 70 {
            score -= 15.0; // large items benefit from fresh space
        }
    }

    // Open-bin pressure: many open bins -> consolidate; few open bins -> spreading is cheaper.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly into the resulting residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Stream progression: late in the stream, avoid leaving many fragmented bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins with residuals close to the mean (balance).
    score -= 0.5 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that can't hold the next item or typical small items.
    if post_residual > 0 {
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
            score += 8.0; // dead space for the lookahead item
        }
        if post_residual < 10 {
            score += 12.0; // very small unusable sliver
        }
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // keeps a viable slot for the next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        // Base penalty; reduced late in the stream or when few bins fit.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 20.0 - 10.0 * progress;
        if fitting_bins_count == 0 { new_bin_penalty = -5.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            // next item is huge; a fresh bin is fine
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty;
    }

    // Prefer filling bins with above-average residual (consolidate emptiness).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild pressure to use more bins when many are open (avoid fragmentation).
    score += 0.05 * open_bins_count as f64;

    // Slight preference early in stream to keep bins balanced (flexibility),
    // late in stream to pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: reward tight fits (low post residual), amplified smoothly over time
    let mut score = pr * (1.0 + 2.5 * progress * progress);

    // Non-linear coupling: quadratic penalty on mid-range wasted space
    let waste = pr_norm * pr_norm;
    score += 60.0 * waste * (0.5 + progress);

    // Reward bins that leave room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 8.0 * (-gap / 25.0) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.3 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // Prefer fuller bins via cubic fill coupling
    score -= 15.0 * fill * fill * fill * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it decomposes against capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit / near-fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic classes: post_residual mod 10 buckets. Small odd residuals are dead space.
    let class = post_residual % 10;
    match class {
        0 => score -= 60.0,                     // round residuals: highly reusable
        1 | 9 => score += 25.0,                 // awkward class
        2 | 8 => score += 10.0,
        5 => score -= 15.0,                     // half-decade class is decent
        _ => {}
    }

    // Integer-division thresholds on post_residual vs capacity quarters.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 40.0;                          // tiny leftover: dead space penalty
    } else if post_residual < 2 * quarter {
        score -= 20.0;                          // sweet spot: half-ish bin left
    }

    // Coupling with next item (lookahead k=2): reward if next item fits exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;                     // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize more if this bin is "fresh".
            let fill = (bin_capacity - post_residual) as f64 / cap;
            score += 30.0 * fill;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many bins are open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 20.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        if item_size > bin_capacity / 2 {
            score -= 25.0;                      // big items like fresh bins
        }
    }

    // Mild tie-break toward fuller bins (lower post_residual already does this;
    // add mean-residual coupling to prefer bins below mean fill).
    if pr < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item (1) but awkwardly small relative to capacity
    // are "dead". Penalize tiny-but-nonzero post residuals harshly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // unusable sliver penalty
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness coupling: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Open-bin pressure: discourage spreading across many bins; but if this
    // is the only fitting bin, strongly reward using it (last chance).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += open_bins_count as f64 * 0.8;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "poor" bin; placing here consolidates waste into one bin.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap; if the next item cannot fit any residual
    // we leave, slightly penalize wasting capacity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (post_residual as f64) * 0.4;
        }
    }

    // New-bin candidate handling: an empty bin has full residual. Opening a
    // new bin is only attractive when existing residuals are all poor fits
    // (i.e., post_residual would be tiny dead space elsewhere) or when bin
    // pressure is low. Make empty-bin score a moderate baseline.
    if bin_residual == bin_capacity {
        // Baseline: fresh bin keeps flexibility; scale with stream progress
        // (early on, opening bins is cheaper; later, prefer consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + open_bins_count as f64 * 1.5 - progress * 10.0 - fill * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // partial lookahead bonus
        } else {
