    // Relative to mean residual: bins below-average residual (tighter) are precious,
    // favor placing into them when fit is good.
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.5 * residual_gap;

    // Penalize leaving large unusable fragments (small post_residual is good,
    // but a mid-range leftover that nothing fits is bad).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // nearly-full bin is excellent
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is expensive; discourage unless
    // current bin fit is poor (large post_residual) and lookahead doesn't match.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && next_item_size != post_residual;
        score += if poor_fit { -5.0 } else { 20.0 };
        // slightly prefer new bin late in stream when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let min_item = 1.0;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer filling existing bins as fully as possible.
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    if bin_residual != bin_capacity {
        score -= 15.0 * pressure;
    }

    // Time horizon: early in stream, opening new bins is cheaper; late, avoid it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        score += 30.0 + 60.0 * progress;
        // Opening a new bin is fine if it will be well used by next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: reward being below mean residual (roomier than average).
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for larger items going into roomier bins.
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on wasted space: quadratic coupling with stream progress.
    score += 0.35 * (post / cap) * (post / cap) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as the stream advances.
    score -= (1.0 - post / cap) * 6.0 * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - ((post - nxt) / cap).abs();
            score -= 4.0 * tightness * (0.5 + 0.5 * progress);
        } else {
            // Next item cannot use the leftover: mild penalty scaled by excess.
            score += 0.02 * (nxt - post).min(cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 2.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with residuals below the mean.
    score += 0.05 * (post - mean_residual).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: reward residuals that are
    // "clean" fractions of capacity (usable by common small items).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if pr % 10 == 0 {
        -18.0 // multiple of 10: highly reusable
    } else if pr % 5 == 0 {
        -9.0
    } else if pr >= 10 && pr % 2 == 0 {
        -4.0
    } else {
        6.0 // odd, small residue: likely dead space
    };
    score += class_bonus;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (harmonic match of next item to residual).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual; penalize small residuals
            score += 5.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Integer-division threshold: residual classes by capacity quarter.
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 14.0; // tiny residual, nearly dead
    } else if pr < 2 * quarter {
        score += 4.0;
    } else if pr < 3 * quarter {
        score -= 6.0; // sweet spot: half-full bins are flexible
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer spreading across open bins when many are open (avoid bin explosion).
    score += open_bins_count as f64 * 0.35;

    // Progress-based mild pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when residual is tiny or nothing fits well.
    if bin_residual == bin_capacity {
        score = score.max(0.0) + 25.0 - 20.0 * (1.0 - (item_size as f64 / cap));
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but treat tiny leftover
    // gaps as "dead space" that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: penalize heavily, worse than a mid-size gap.
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: mild penalty.
        score += 8.0;
    } else {
        // Larger gaps: mild reward scaled by usability.
        score -= 4.0;
    }

    // Dead-space coupling: penalize if the leftover gap cannot fit the
    // lookahead item but is close to doing so (wasted potential).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Gap exactly reusable by next item: reward.
            score -= 12.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many open bins;
    // encourage filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean
    // (a "hole"), filling it is good; penalize leaving holes behind.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // New-bin candidate: only attractive late in the stream or when the
    // fit into existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    // Slight stream-progression tilt: early on, be pickier (keep bins
    // flexible); late, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit this bin's post-residual, penalize dead space
        if post_residual < next_item_size {
            score += 0.35 * (post_residual as f64);
        }
    }

    // Penalize small unusable residuals (dead space) relative to item range
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tight fit reward relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Prefer bins with residuals below mean residual (denser bins first)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but allow it late in the stream when many bins are open and fragmentation is high.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * (open_bins_count as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin keeps full flexibility for lookahead item
        }
    }

    // Stream progression: later in stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space, with non-linear penalty on mid-range residuals.
    let frag = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 25.0 * frag;

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize more when the gap is small (near-miss dead space).
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (gap / 100.0).min(1.0);
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }
    if post_residual == next_item_size && next_item_size > 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tight-fit coupling: reward small relative slack in this bin.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 10.0 * (1.0 - tightness);

    // Global state: many open bins -> prefer consolidating into existing bins.
    score += 0.6 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean residual coupling: if this bin is far from mean residual, slight penalty (keep pool uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (keep flexibility);
    // later, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 10.0 + 40.0 * t;
    if bin_residual == bin_capacity {
        // New-bin candidate score: its post_residual equals capacity - item_size.
        score += new_bin_penalty;
        // Still allow a new bin if item is large and would leave a useful chunk.
        if item_size >= 50 {
            score -= 12.0;
        }
        // If no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 0 {
        // Shouldn't happen (bin fits by construction), safety no-op.
        score += 0.0;
    }

    // Small lookahead-driven nudge: if next item is large, prefer leaving big residual bins free.
    if next_item_size >= 60 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (reward low post_residual quadratically).
    // Late: penalize leaving residuals that are hard to reuse.
    let poly = fit_norm * fit_norm * (1.0 - progress) * 40.0
             + fit_norm * progress * 25.0
             + (1.0 - fit_norm) * (1.0 - fit_norm) * progress * 15.0;
    score += poly;

    // Reward near-perfect fits smoothly.
    score -= (1.0 - fit_norm).powi(3) * 20.0;

    // Dead-space penalty: residuals too small for typical items.
    let dead = (1.0 - (pr / 30.0).min(1.0)) * (pr < 30.0) as i32 as f64;
    score += dead * (1.0 + progress) * 12.0;

    // Lookahead: reward if next item can use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr / nxt).min(1.0);
        score -= usable * usable * 18.0 * (1.0 - progress * 0.5);
        // Penalize if residual will be wasted relative to next item.
        score += (1.0 - usable) * (pr / cap) * 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty for spreading across many open bins when residuals are high.
    score += (open_bins_count as f64).ln() * mean_residual * 0.02 * progress;

    // New-bin candidate: neutral-ish baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Dead-space penalty: residuals that are too small to fit likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: residuals divisible into useful chunk classes
    // Class A: post_residual in [25, 50] -> can host a mid item
    // Class B: post_residual in (0, 25) -> risky dead space unless next item fits
    if post_residual >= 25 && post_residual <= 50 {
        score -= 15.0;
    } else if post_residual > 0 && post_residual < 25 {
        // penalize small leftovers, less if the lookahead item fits exactly
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: prefer residuals that are multiples
    // of common item-size classes (10s and 5s), hinting at reusability
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // harmonic compatibility: how well next item divides the leftover
            let nk = next_item_size as f64;
            score -= 20.0 * (nk / pr).min(1.0);
            // integer division threshold: leftover after next item
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 25.0;
            } else if after_next < 10 {
                score += 8.0; // creates dead space after chain
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding: many open bins -> prefer tight packing (low post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: neutral-ish score based on capacity fraction;
    // only attractive when no good harmonic class exists among open bins
    if bin_residual == bin_capacity {
        // opening a new bin leaves full capacity; make it mediocre but not terrible
        score = cap * 0.5 + 20.0 - (if next_item_size > 0 && next_item_size <= bin_capacity { 10.0 } else { 0.0 });
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that no plausible future item can use is pure waste.
    let min_item = 1.0f64;
    let dead = if post_residual > 0 && (post_residual as f64) < min_item * 10.0 {
        // gap too small for anything meaningful -> heavy penalty
        (10.0 - post_residual as f64).powf(2.0) * 3.0
    } else {
        0.0
    };
    score += dead;

    // Non-linear dead-space: penalize gaps below the smallest common item band
    let gap_penalty = if post_residual > 0 && post_residual < 20 {
        (20.0 - post_residual as f64) * 2.5
    } else {
        0.0
    };
    score += gap_penalty;

    // Reward tight fits (near-zero post residual) with a bonus subtraction
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to how well it chains
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit: penalize proportionally to wasted potential
            score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Open bins pressure: discourage spreading across many open bins
    // when mean residual is already low (bins nearly full).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is one of the "fuller" bins -> prefer filling it (lower score).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a big commitment.
    // Penalize it unless the current bin would leave a terrible gap.
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if item is large relative to capacity, opening fresh is fine
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Slight preference for bins whose residual is close to item size (good fit)
    let fit_quality = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
    score -= fit_quality * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

