    }
    // Penalize if next item cannot fit here (dead space likely).
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Favor bins whose residual is already below the mean (tight packing).
    let rel = (bin_residual as f64) - mean_residual;
    score += rel * 0.25;

    // Penalize new-bin opening when other bins fit decently.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64) * 40.0
                + (fitting_bins_count as f64) * 5.0
        };
        score += 20.0 + pressure;
    } else {
        // Last-chance bin bonus: only this open bin can fit the item.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward tight fits (small post residual relative to capacity).
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Slight late-stream conservatism: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize large post-residual quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 30.0;

    // Reward filling a bin nearly exactly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 100.0;
    }

    // Lookahead coupling: if next item fits into this bin's post-residual,
    // reward this placement (chaining two items in one bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // If next item would fit better elsewhere, mild penalty for wasting space now.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 40.0 + 20.0 * progress - congestion.min(30.0);
        // If the item fits poorly nowhere (no tight option), new bin is fine.
        if item_size as f64 >= mean_residual {
            score -= 15.0;
        }
    }

    // Global state: when mean residual is high, prefer bins below the mean
    // (drain the large-residual bins first to consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Slight preference to use bins with fewer siblings (consolidation pressure).
    score += open_bins_count as f64 * 0.1;

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;                       // normalized post-residual in [0,1)
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic waste penalty — tiny residuals are nearly dead space.
    let mut score = norm_pr * norm_pr * cap;

    // Smooth cubic coupling: waste matters more as the stream matures
    // (fewer future chances to consolidate fragments).
    score += 12.0 * norm_pr.powi(3) * (0.5 + progress) * cap;

    // Reward near-perfect fits with a smooth bell-shaped bonus.
    let tightness = (norm_item - (1.0 - norm_pr)).abs();
    score -= 25.0 * (-(tightness * tightness) / 0.02).exp();

    // Lookahead: reward if the next item fits snugly into post_residual,
    // penalize if it leaves a near-miss gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (pr - norm_next * cap) / cap;
        score -= 15.0 * (-(gap * gap) / 0.01).exp();
    } else if next_item_size > post_residual {
        // Smooth penalty proportional to how far the next item overshoots.
        let over = (next_item_size as f64 - pr) / cap;
        score += 8.0 * over;
    }

    // Fragmentation pressure: if the mean residual across open bins is high,
    // prefer filling existing bins rather than spreading.
    let mean_norm = mean_residual / cap;
    score -= 10.0 * mean_norm * (1.0 - norm_pr);

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a fresh bin, but relax the penalty
    // when existing residuals are badly fragmented (all small).
    if bin_residual == bin_capacity {
        let frag = mean_norm * mean_norm;
        score = 30.0 + 25.0 * (1.0 - frag) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo common size classes.
    // Residuals that are "harmonious" with typical item sizes (multiples / near
    // multiples of 10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward (perfect packing leaves no waste).
        score -= 60.0;
    } else {
        // Harmonic class reward: divisible residuals are reusable by many items.
        let mut harmonic_bonus = 0.0;
        if pr % 50 == 0 { harmonic_bonus += 18.0; }
        else if pr % 25 == 0 { harmonic_bonus += 12.0; }
        else if pr % 20 == 0 { harmonic_bonus += 10.0; }
        else if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 5 == 0 { harmonic_bonus += 3.0; }
        score -= harmonic_bonus;

        // Penalize dead space: residual too small for the smallest plausible item.
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64;
        } else if pr < 20 {
            score += 6.0;
        }

        // Non-linear penalty on large leftover that nothing typical will fill:
        // residual in awkward mid-ranges (e.g., 21..=29, 31..=39 modulo classes)
        let awkward = (pr % 10 >= 1 && pr % 10 <= 4) && (pr >= 21 && pr <= 89);
        if awkward { score += 4.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up -> big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            // Next item fits but not perfectly: mild reward scaled by tightness.
            let tightness = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - tightness / bin_capacity as f64).max(0.0);
        }
        // Harmonic lookahead: next item shares a divisor class with post_residual.
        if next_item_size > 0 && pr > 0 && next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has neutral base (post_residual
    // == capacity). Prefer it only when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        // Slight default penalty so we prefer filling existing bins when fit is good.
        score += 8.0;
        // But if many open bins are already fragmented (high mean residual),
        // opening a fresh bin is fine.
        if mean_residual > 40.0 { score -= 6.0; }
    } else {
        // Tightness reward: the smaller the leftover relative to what was used,
        // the better the fill.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Progress modulation: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual <= 10 {
        score -= 10.0 * progress;
    }

    // Mild penalty for scattering across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match leaves zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize post_residual that is large enough to fit the next item but wastefully so
        // (item would float in a big gap), and penalize leaving a gap the next item cannot use.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.8 * slack;
        } else {
            // Gap unusable by next item: penalize proportionally to how "dead" it is.
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins fill up,
    // keeping loose bins available for awkward future items).
    score += 1.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the current fit is bad
    // (large post_residual) and there are many open bins.
    if bin_residual == bin_capacity {
        // Fresh bin score: moderate baseline, better than a very poor fit, worse than decent fit.
        score = 55.0 - 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 10.0; // discourage new bin if next item is smaller (could pair in old bin)
        }
    }

    // Early stream: be slightly more willing to open bins (build structure), later: tighten.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0;
        }
        // If next item fits exactly, extra reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        score += 55.0;
        // If many bins fit the item, discourage opening a new one further.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If only this bin fits, opening a new bin is fine (remove penalty).
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
        // Late in stream, prefer reusing existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Global state coupling: high mean residual means wasted space; prefer bins
    // below mean residual (tighter bins) to consolidate.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer bins with larger residual among similar fits (pack into emptier bins
    // keeps tight bins available), mild effect.
    score -= 0.05 * bin_residual as f64;

    // Mild penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    // Small time-based jitter-free diversification: favor consolidation early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on post_residual (waste), softened by progress
    let mut score = pr * pr / cap;

    // Smooth interaction: residual waste weighted less as stream progresses
    score *= 1.0 - 0.3 * progress;

    // Penalize bins whose residual deviates from the mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * pr / cap;

    // Reward tight fits (small post_residual) with a cubic bonus
    let tight = 1.0 - pr / cap;
    score -= 12.0 * tight * tight * tight;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins compete (prefer spreading load)
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: bonus if post_residual accommodates next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let room = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - room * room);
        } else {
            // Dead space penalty scaled by how much next item misses
            let miss = (nxt - pr) / cap;
            score += 15.0 * miss * miss;
        }
    }

    // Mild preference for consolidating into fewer bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * (1.0 - tight) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it falls into.
    // Bands of capacity/8 create discrete residual classes; small odd classes
    // (dead space) are heavily penalized, large classes rewarded.
    let band = post_residual * 8 / bin_capacity;
    match band {
        0 => score += 45.0,                 // nearly full: excellent fill
        1 => score += 20.0,                 // small residual, likely dead space
        2 => score += 8.0,                  // marginal
        3 => score += 0.0,
        4 => score -= 3.0,
        5 => score -= 6.0,
        6 => score -= 9.0,
        _ => score -= 12.0,                 // nearly empty: fresh bin
    }

    // Odd/even harmonic parity: residuals that are not multiples of a common
    // item granularity (10) waste space; divisible residuals pair better.
    if post_residual % 10 != 0 {
        score += 6.0;
    } else {
        score -= 2.0;
    }

    // Perfect-fit harmonic: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit in post residual, penalize
    // proportionally to how much we strand.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: reserve it for genuinely bad fits of open bins.
    if bin_residual == bin_capacity {
        score += 30.0
            + (item_size as f64 / bin_capacity as f64) * 40.0
            - (fitting_bins_count as f64) * 4.0;
        // late in the stream, prefer reusing bins more strongly
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
    }

    // Crowd penalty: too many open bins with fat residuals -> encourage closing
    // them by filling; reward placing into bins below mean residual (tight bins).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }
    if open_bins_count > 6 && post_residual > bin_capacity / 3 {
        score += 10.0;
    }

    // Integer-division threshold: reward leaving residuals in the "usable half"
    // (residual >= 50) only when item is large, to avoid splitting big items.
    if item_size >= bin_capacity / 2 && post_residual >= bin_capacity / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for likely
    // future items (below minimum item size 1, but practically small gaps
    // under ~15) are "dead space" — penalize them quadratically.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 15 {
            score += 2.5 * (15.0 - pr) * (15.0 - pr);
        } else {
            // Mild reward for leaving a moderately reusable gap.
            score -= 0.3 * pr;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward fitting the item at all (this bin is usable).
    score -= 10.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we pay for a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading.
    let pressure = open_bins_count as f64;
    score += 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post_residual,
    // this is an excellent chain placement — big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; dead space relative to lookahead.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Progress-aware: late in the stream, avoid leaving tiny gaps since
    // fewer chances remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * progress;
    }

    // Mean residual coupling: bins with residual far below the mean are
    // nearly full — prefer filling those (small residual = good).
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: an empty bin has no dead-space cost yet,
    // but opening it should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact 2-step matches: post_residual == next_item_size (perfect pair)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize leaving residual that neither fits next item nor is tiny
        if post_residual > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
            score += 15.0; // dead space penalty
        }
        // Reward residual that can still host a mid-size future item
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual across open bins: prefer bins with below-average residual
    // (tighter bins get used first, preserving large-residual bins for large future items)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin unless the fit elsewhere is terrible
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus expected future utility of a fresh bin
        score += 20.0;
        // If item is large, a fresh bin is more attractive (keeps large contiguous space)
        score -= 0.1 * item_size as f64;
        // As stream progresses, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage opening more
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for using fuller bins (small residual before placement)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward fuller placement (smaller post_residual relative to capacity).
    score -= 0.35 * (cap - post_residual as f64);

    // Lookahead coupling: if the next item can still fit in the leftover space,
    // reward using this bin (keeps future options open).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - post_residual as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        score += 3.0 + 0.08 * post_residual as f64;
    }

    // Last-chance bonus: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with slack -> prefer consolidating into existing bins.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        score -= 0.05 * (open_bins_count as f64) * (mean_residual / cap);
    }

    // New-bin candidate: baseline moderately high so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = (cap - item_size as f64) + 8.0 + 0.1 * mean_residual
            - 5.0 * (1.0 - progress);
        // If the new bin's leftover can host the next item, it becomes more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 10.0 * poly;

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 {
        let gap = post_residual.saturating_sub(next_item_size) as f64;
        let waste = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 3.0 * waste / 10.0;
        score -= 2.0 * gap / cap;
    }

    // Reward tight fits smoothly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins vs mean residual.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score -= 4.0 + 6.0 * (1.0 - progress) - 8.0 * progress;
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4 harmonic band

    // Reward near-perfect fits (tiny post_residual) superlinearly
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space: post_residual too small for next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainability reward, stronger when post_residual is a "harmonic" multiple
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 40.0; // next item fills almost perfectly
            } else {
                score -= 12.0;
            }
        } else {
            // dead space penalty scaled by how much of the item is wasted
            let waste = next_item_size - post_residual;
            score += 10.0 + (waste as f64) * 0.8;
        }
    }

    // Harmonic class shaping: residuals in the low band (0..quarter) are hard to reuse
    match class {
        0 => score += 18.0,
        1 => score += 4.0,
        2 => score -= 3.0,
        _ => {}
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is a last resort
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else {
            // penalize opening a new bin, more so mid-stream
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 45.0 + 30.0 * (1.0 - progress);
            // but if this bin's post-residual would chain with next item better than average, soften
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 20.0;
            }
        }
    }

    // Mild preference to fill emptier bins first (balance residuals)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference to keep open-bin count low
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Large leftover space is somewhat acceptable; reward moderately.
        score -= 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.8;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Compare post_residual against mean residual: avoid making bins much worse than average.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        score += 30.0 + fragmentation * 0.4;
        // Lookahead: if next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size < 25 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let gap_eff = (post_residual - next_item_size) as f64;
        score -= 10.0 - gap_eff * 0.3;
    }

    // Mild stream progression scaling.
    score *= 1.0 + (step_index as f64 / (total_items.max(1) as f64)) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: exact match with next item is excellent
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // residual still usable by next item: mild reward, closer is better
            score -= 0.15 * (post_residual - next_item_size) as f64;
        }
    }

    // Penalize residuals far below mean (fragmented bin)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless fit is poor
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 15.0 + waste as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin will pair well with next item
        }
    }

    // Early stream: keep bins tighter; late stream: consolidate
    score -= progress * 3.0;
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but perfect fits are extra good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving dead space that no realistic item (1..=100) can usefully fill:
    // residual too small to be attractive relative to the item size scale.
    let dead_threshold = (item_size as f64 * 0.15).max(3.0) as u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 12.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if next item is large and would not fit, mildly penalize wasting this bin's space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling existing
    // bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin starts with a base cost that shrinks
    // when no good alternatives exist (few fitting bins) or early in the stream.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64) * 6.0 };
        let time_adj = 20.0 * (1.0 - progress);
        score += base + scarcity - time_adj;
    }

    // Mild penalty for opening bins when already many are open.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 4.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins with smaller residual overall (best-fit flavor) scaled by progress.
    score += (bin_residual as f64) * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Reward tight fits: quadratic coupling of (1 - norm_pr) with stream progress
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that no typical item can use: cubic term
    score += 20.0 * norm_pr * norm_pr * norm_pr;

    // Lookahead coupling: reward if the next item fits into the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Bin congestion pressure: when many bins are open, prefer filling existing ones
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += congestion * pr * 0.3;

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced packing)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 + progress);

    // New-bin candidate: penalize slightly so it only wins when open bins are truly bad fits
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
        // but if no open bin could fit tightly, the base post_residual already dominates
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Brand-new empty bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can take this item: opening a new bin is mandatory.
            score -= 1000.0;
        } else {
            // Prefer reusing open bins unless the fit would be terrible.
            let waste = pr; // same as post_residual for empty bin
            score += 30.0 + (waste as f64) * 0.5;
        }
        return score;
    }

    // Perfect fill: strongly reward closing a bin exactly.
    if pr == 0 {
        score -= 25.0;
    } else {
        // Dead space below the minimum item size is unusable: heavy penalty.
        if pr < 10 {
            score += 35.0;
        } else {
            // Harmonic class of the residual: rounder residuals are more reusable.
            let class = pr / 10;
            score += class as f64 * 2.0;
            if pr % 10 == 0 {
                score -= 3.0; // divisible-by-10 residuals match common item classes
            } else if pr % 5 == 0 {
                score -= 1.5;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor fit later.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward if the next item can also fit the leftover space.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
        } else {
            // Penalize when the leftover cannot host the next item.
            score += 4.0;
        }
    }

    // Reward larger items consuming more of the bin (tight packing tendency).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    // Slight preference for bins below the mean residual (balance residuals).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward filling a bin tightly (post_residual small relative to capacity).
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.15;

    // Last-chance bin before opening a new one: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: prefer existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 40.0 + open_bins_count as f64 * 3.0;
        // If no open bin fits, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item would fit the fresh bin's residual but not the current
        // placement elsewhere, opening a new bin can be attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Placing in an existing bin slightly favored as bins accumulate.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item exactly fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item would fit in post_residual, mildly reward keeping that space.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 50.0 / post_residual as f64;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 / (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit; penalize wasted space relative to next item.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no open bin fits and lookahead is small, new bin is fine.
        if fitting_bins_count == 0 || next_item_size == 0 {
            score -= 60.0;
        }
        // Early stream: opening bins is cheaper.
        if (step_index as f64) / (total_items as f64).max(1.0) < 0.2 {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving residual in the awkward 1..=10 dead zone (interface range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight preference to fill bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: quadratic penalty on wasted space, amplified for large items.
    let tightness = (item_size as f64 / cap).powf(1.5);
    score += post * post / cap * (0.5 + tightness);

    // Lookahead: strongly reward bins where the next item also fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Perfect chain: residual absorbed by next item.
            let chain_gap = (post - nxt).abs();
            score -= 25.0 * (1.0 - chain_gap / cap);
            if (post - nxt) as u32 == 0 {
                score -= 30.0; // exact two-item fill
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New bin only attractive if existing residuals are all small relative to item.
            let best_alt = mean_residual;
            let need = item_size as f64;
            if best_alt < need * 0.35 {
                score -= 10.0; // open new bin: existing bins too fragmented
            } else {
                score += 45.0 + open_bins_count as f64 * 2.0;
            }
        } else {
            score -= 15.0; // forced new bin anyway
        }
    } else {
        // Reusing bins: mild reward scaled by how much residual this consumes.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into bins (avoid bin proliferation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > (item_size as f64) * 1.5 && bin_residual < bin_capacity {
        score -= 6.0 * (mean_residual / cap) * (1.0 + progress);
    }

    // Late-stream: become more conservative, prefer exact fits, avoid scattering.
    score += 5.0 * progress * (post / cap);

    // Dead-space guard: residuals too small for the minimum plausible item are worthless.
    if post > 0 && post < 10.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic waste coupling, sharpened as the stream progresses.
    let mut score = pr * (1.0 + 0.9 * progress) + 0.0035 * pr * pr;

    // Normalize post_residual relative to mean residual of open bins.
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { cap };
    score += 0.6 * (pr - mr).abs() * (0.5 + 0.5 * progress);

    // Lookahead coupling: penalize residuals that can't host the next item,
    // reward residuals that snugly fit it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        score -= 8.0 * usable * (1.0 - progress);
        // dead space relative to next item (smooth ramp)
        let gap = (nx - pr).max(0.0);
        score += 0.05 * gap * gap / cap;
        // reward leaving exactly-enough room (smooth proximity term)
        let prox = (pr - nx).abs();
        score -= 4.0 * (-prox / 20.0) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or the item is small (wasteful in a fresh bin).
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 20.0 + 12.0 * waste + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // but allow new bin late in stream if it would be nearly filled
        score -= 10.0 * (item_size as f64 / cap) * progress;
    }

    // Mild penalty for many open bins (fragmentation control).
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * (1.0 - progress));

    // Tiny smooth tie-breaker on fit tightness.
    score -= 2.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill bonus and small-residue penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score += 40.0; // dead space: residue too small for any item
    } else if post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Fractional capacity classes (harmonic bins): residue in useful ranges
    let frac = post_residual as f64 / cap;
    if (0.25..=0.5).contains(&frac) {
        score -= 15.0; // residue large enough to host a wide class of items
    } else if frac > 0.8 {
        score -= 8.0; // still roomy bin
    }

    // Lookahead coupling: reward residues that can also fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            score += 8.0; // next item cannot follow here
        }
        // exact two-item packing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 45.0 + 0.05 * open_bins_count as f64;
        if post_residual + item_size as u32 <= 20 {
            score -= 30.0; // tiny item: fresh bin acceptable
        }
    }

    // Mild preference for concentrating fill when many bins open
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min item size 1, but realistically small gaps
    // below ~15) are almost unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 - (post_residual as f64) * 3.0; // up to +57 for residual 1
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        // Reward tight fits: smaller post_residual relative to capacity.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward; if next item cannot fit, mild penalty for wasted slot.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening extra bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 + progress) * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current fit is bad (large post_residual)
    // or when it enables packing for the lookahead; otherwise keep open bins.
    if bin_residual == bin_capacity {
        // Base neutrality: empty bin score = post_residual (= capacity),
        // already large; add slight pressure so it loses against decent fits.
        score += 5.0 + (open_bins_count as f64) * 2.0;
        // But if item is large relative to capacity, a fresh bin is good.
        if (item_size as f64) / (bin_capacity as f64) > 0.7 {
            score -= 40.0;
        }
    }

    // Mild mean-residual alignment: prefer bins whose residual is near mean
    // (keeps bin states balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Progress-adaptive tightening: later in the stream, be stricter about
    // leftover dead space.
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * match_quality * match_quality;
        // Perfect chain: next item fills bin completely
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: post-residual too small for the next item.
        // Penalize proportionally to how unusable it is, but small leftovers
        // (< ~15) are nearly worthless anyway.
        let dead = post_residual as f64;
        if dead < 15.0 {
            score += 10.0 * (15.0 - dead) / 15.0;
        } else {
            score += 4.0;
        }
    }

    // Reward tight fits relative to mean residual (below-mean leftover is good).
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score -= 0.5 * tightness;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the item
    // is huge relative to the bin (a fresh bin fits it best).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 15.0; // big items prefer a fresh bin
        } else {
            score += 12.0 * (1.0 - fill_frac);
        }
    }

    // Late in the stream, prefer closing out bins (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item can fit into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward for near-exact two-item packing.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    } else {
        // Last item: waste matters maximally.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= 0;
        // Penalize new bin when open bins exist and item fits reasonably well.
        if open_bins_count > 0 && good_fit_exists {
            let fit_quality = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
            let penalty = 30.0 - 20.0 * fit_quality;
            // Less penalty late in the stream (consolidation less valuable).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += penalty * (1.0 - 0.3 * progress);
        } else {
            score -= 10.0;
        }
        // Mild penalty per open bin to encourage reuse when feasible.
        score += open_bins_count as f64 * 0.5;
    }

    // Global state: if mean residual is high, prefer bins below mean (balance avoidance of fragmentation).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Prefer filling bins that are already mostly full (reduce open-bin spread).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual); later, tolerate slack less harshly.
    let tightness = post / cap;
    let coupling = (tightness * tightness) * (1.0 - progress) * cap;
    score += 0.6 * coupling;

    // Reward filling bins nearly completely, smoothly scaled by progress.
    let fill = 1.0 - tightness;
    score -= 18.0 * fill * fill * (0.5 + progress);

    // Penalize opening a new bin when existing bins fit (new-bin candidate has residual == capacity).
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
    score += is_new_bin * (14.0 + 26.0 * (1.0 - progress)) * scarcity;

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= post) as f64;
        let slack_match = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= 12.0 * fits_next * slack_match * slack_match;
    }

    // Slight preference for bins with below-average residual (concentrate slack).
    let mean_t = mean_residual / cap;
    let bin_t = bin_residual as f64 / cap;
    score += 6.0 * (bin_t - mean_t);

    // Last-chance bin: strongly encourage using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation early).
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is "harmonious"
    // with common item sizes are worth more. Residuals that are multiples of
    // small divisors (5, 10, 20, 25) are reusable; prime-ish leftovers are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 25 == 0 && pr > 0 {
        score -= 25.0;
    } else if pr % 20 == 0 && pr > 0 {
        score -= 18.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 30.0; // tiny unusable dead space
    }

    // Integer-division threshold: leftover must be able to host the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward proportionally to how well it fills the leftover
            let fill = next_item_size as f64 / pr as f64;
            score -= 15.0 + 20.0 * fill;
            // harmonic bonus if the pair (item, next) leaves a divisible residue
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // lookahead cannot use this bin's leftover: penalize mildly unless
            // leftover is in a "harmonic class" that other sizes like
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a bin should only win when the item fits
    // existing bins poorly (i.e., post_residual here would be large relative
    // to capacity fraction classes).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 15.0 * progress;
        // large items harmonize well with a fresh bin
        if item_size % 25 == 0 || item_size % 20 == 0 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins when several fit: tie-break toward small residual.
    if bin_residual != bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    // Slight penalty when many bins are open and mean residual is high:
    // encourage consolidation into existing space.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize residual that cannot host the lookahead item (k=2) when a lookahead exists.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but relax late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (2.0 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the average residual (better consolidation).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening a brand-new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.3 * slack.min(30.0);
        } else {
            // Penalize dead space the next item cannot use.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead.min(50.0);
        }
        // Perfect chain: next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Compare against mean residual across open bins: prefer tightening loose bins.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin allows a perfect pair packing with the lookahead item.
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // no reasonable alternative -> open new bin
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference to keep fewer open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0; // stranded residual that cannot host the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Discourage spreading across many bins when mean residual is high.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive if current fit is bad (large post_residual)
    // or no open bin is a genuinely good host.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        if bad_fit {
            score -= 20.0; // prefer a fresh bin over wasting a fresh bin's space? no: penalize
            score += 45.0; // net: opening a new bin for a bad fit is discouraged
        } else {
            score += 18.0; // mild penalty so existing good fits win
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear penalty on wasted residual (quartic-ish coupling)
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits: smooth Gaussian-like bump near post_residual ~ 0
    let tightness = (-norm_pr * norm_pr * 18.0).exp();
    score -= 12.0 * tightness * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let compat = (-gap * gap / (2.0 * 64.0)).exp();
        score -= 8.0 * compat;
        // penalize if post residual is just barely too small for next item
        let almost = (-((pr - nx + 5.0) * (pr - nx + 5.0)) / 40.0).exp();
        score += 4.0 * almost;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more when many bins already open and progress is late
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * open_bins_count as f64 * (0.3 + progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
