    // residue class (multiples of small divisors of capacity) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            8.0
        } else if pr % 5 == 0 {
            4.0
        } else if pr % 25 == 0 {
            6.0
        } else if pr % 2 == 0 {
            1.5
        } else {
