        };
        score -= class_bonus;
        // Dead space: residual too small for the smallest plausible item
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Fractional capacity coupling
    let frac = post_residual as f64 / cap;
    score += 10.0 * (frac - 0.5).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward;
    // if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer filling nearly-full bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - frac) * 2.0;

    // Slight preference for existing bins over opening a new bin
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to hold anything
    // (below the minimum plausible item size band) are heavily penalized.
    if post_residual > 0 {
        // small unusable gaps: quadratic blowup
        let unusable = (cap * 0.20 - post).max(0.0);
        score += 3.0 * unusable * unusable / cap;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement; if post residual can't fit next item but bin
    // residual could have, mild penalty for fragmenting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists; scale with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the mean residual (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: only attractive when current item is large relative
    // to capacity (would leave a large awkward residual elsewhere) or when
    // it's a big item and few bins fit it.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let base = 12.0 + 30.0 * size_frac;
        let relief = if fitting_bins_count <= 2 { 10.0 } else { 0.0 };
        score = base + relief - 10.0 * size_frac * size_frac;
        // late in the stream, opening new bins is fine since packing is done anyway
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (post_residual == next_item_size) gets strong bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to tightness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space more when small.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += (10.0 - dead) * 3.0;
            }
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 20.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Compare post_residual against mean residual: leaving less than average
    // is good (bin becomes well-used), leaving more is wasteful.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow opening a new bin early in the stream when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // But if next item fits perfectly in the new bin, make it attractive.
        if next_item_size > 0 && next_item_size == item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space ratio.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64 > mean_residual * 0.6);
        if poor_fit_elsewhere {
            score -= 30.0;
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Global balance: prefer bins whose residual is near the mean residual (keeps flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, greedily fill bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);
    score -= 5.0 * progress * (1.0 - waste);

    // Slight preference for fuller bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_ratio = it / cap;

    // Base: quadratic penalty on post_residual (waste), scaled by stream progress.
    let mut score = pr * pr / cap;

    // Smooth coupling: waste matters more early (keep space flexible later),
    // but late in stream tight packing is rewarded even more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Reward tight fits: cubic bonus when post_residual is small.
    let tightness = 1.0 - pr / cap;
    score -= 40.0 * tightness * tightness * tightness * (1.0 + progress);

    // Penalize bins with residual far from mean residual (imbalance) — smooth interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead coupling: if the next item fits the post-residual, reward; if it nearly
    // fits (within 10), mild reward; smooth falloff with gap.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap) * (1.0 + 0.5 * progress);
        } else {
            score += 8.0 * (-gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting
    // bins exist and early/mid stream; allow escape hatch late via smooth decay.
    if bin_residual == bin_capacity {
        let escape = 1.0 / (1.0 + (1.0 - progress) * (open_bins_count as f64));
        score += 30.0 * (1.0 + fit_ratio) * escape;
    }

    // Small penalty per open bin to discourage bin proliferation smoothly.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits, scaled by fraction of capacity.
    let post_frac = post_residual as f64 / capacity;
    score += 12.0 * post_frac * post_frac;

    // Harmonic class of post_residual: dead space is space that cannot
    // hold "typical" item sizes. Classify post_residual via integer
    // division into harmonic bands of capacity.
    let band = post_residual / 10; // 0..=10 harmonic band
    let band_penalty = match band {
        0 => -30.0, // perfect fill: extremely desirable
        1 => -8.0,  // leaves 1..9 : near-dead space, but tight is good
        2 => 14.0,  // 10..19 : fits only tiny items, poor
        3 => 10.0,
        4 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward; if it does not fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic alignment: next item leaves a class-0/1 residue again
            let chain = (post_residual - next_item_size) / 10;
            if chain <= 1 { score -= 10.0; } else { score -= 3.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // especially when the fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin offers a good fit (post_residual would be large
    // relative to usable space) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // cost of a fresh bin decreases late (when many bins already open)
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = capacity * 0.85 + 20.0 * (1.0 - progress) - 6.0 * open_pressure;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 { score -= 8.0; }
        return score;
    }

    // Prefer bins whose residual deviates from mean residual in a
    // "harmonic" way: bins with small residuals get consolidated first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference to fill older/scarce-capacity bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are poison.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // likely dead space
        } else if post_residual < 35 {
            score += 8.0; // marginal
        } else {
            score -= 5.0; // still usable chunk
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Tight fit reward relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fill_ratio >= 0.9 || post_residual == 0 {
            score -= 50.0; // opening fresh bin for a big item is fine
        }
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in the stream, be more conservative about spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chaining
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 25.0;
            } else {
                // mild penalty for leaving room next item can't fully use
                score += slack * 0.15;
            }
        } else {
            // next item cannot fit here; post_residual risks becoming dead space
            let orphan = (next_item_size - post_residual) as f64;
            score += orphan * 0.3;
        }
    }

    // Penalize large residuals relative to mean (wasteful bins).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 35.0;
        // but if current bin would leave a badly fragmented residual and
        // the new bin can chain with the next item, opening is competitive
        if next_item_size > 0 && post_residual + 10 < next_item_size {
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (waste minimization).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Penalize dead space relative to bin capacity (non-linear).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if the next item can use the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Residual after placement is unusable by the next item: dead space.
        score += 6.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits
    // are poor (post_residual large) and we already have many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 - item_size as f64) / bin_capacity as f64; // = 1 - fill
        let base = 20.0 + 45.0 * poor_fit;
        // Encourage consolidation early, allow opening bins when crowded.
        score = base - 10.0 * progress - (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global pressure: when mean residual is low, avoid wasting the last space.
    if mean_residual < item_size as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling: residual value decays with stream progress
    let residual_weight = 1.0 - 0.6 * progress * progress;
    score *= residual_weight;

    // Penalize large residuals more aggressively as the stream progresses
    score += 12.0 * pr_norm * pr_norm * (0.4 + 0.6 * progress) * cap * 0.1;

    // Reward tight fits (small post-residual) with smooth quadratic bonus
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving space for the next item (smooth cubic)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let diff = pr - nxt;
        if diff >= 0.0 {
            let d = diff / cap;
            score -= 8.0 * (1.0 - d * d * d) * (0.3 + 0.7 * progress);
        } else {
            score += 6.0 * (-diff / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Crowding: penalize mildly when many bins open and residual is wasteful
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
    score += 4.0 * crowd * pr_norm * mean_residual / cap;

    // New-bin candidate: keep neutral-ish baseline, slightly discouraged late
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 2.0 * progress * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/4, 1/2, 3/4 of C)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let item_class = if item_size <= quarter { 0 } else if item_size <= half { 1 } else if item_size <= 3 * quarter { 2 } else { 3 };

    // Harmonic class of the residual after placement
    let res_class = if post_residual <= quarter { 0 } else if post_residual <= half { 1 } else if post_residual <= 3 * quarter { 2 } else { 3 };

    // Reward placements whose post-residual falls into a useful harmonic class
    // (small residuals are dead space; residuals near half/quarter can host future items)
    match res_class {
        0 => score -= 6.0,                              // nearly full bin: excellent
        1 => score -= 2.5,                              // small-ish residual, still usable
        2 => score += 1.5,                              // half-ish residual: mediocre
        _ => score += 4.0,                              // large residual left: wasteful
    }

    // Perfect modular fits: post_residual divisible by common class sizes
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    } else {
        score += 0.5; // ragged remainder penalized
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item slots perfectly: strong reward, stronger if exact
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 - 0.05 * slack;
            if post_residual == next_item_size { score -= 8.0; }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
        // integer-division threshold: next item same harmonic class as current
        if next_item_size / quarter == item_size / quarter && next_item_size <= post_residual {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: emphasize best-fit via residual already in score
        score += 0.5;
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when no open bin fits well
        // or the item is huge (class 3) and current mean residual is small.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // how bad are the alternatives? mean residual vs item size
            (mean_residual - item_size as f64).max(0.0)
        };
        if fitting_bins_count == 0 {
            score -= 15.0; // must open a bin
        } else if item_class == 3 && mean_residual < item_size as f64 + 5.0 {
            score -= 4.0;  // big item, poor fits elsewhere
        } else if desperation > 30.0 && progress > 0.5 {
            score -= 1.0;  // late-stream mild openness to new bins
        } else {
            score += 25.0 + 0.1 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Mild pressure against bin proliferation mid-stream
    score += 0.02 * open_bins_count as f64;

    // Small tie-breaker noise-free deterministic coupling on step parity class
    if step_index % 3 == 0 && post_residual % 2 == 0 {
        score -= 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are effectively unusable
    // (min item size is 1, but tiny gaps rarely match future items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward near-perfect fits.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage scattering items across many bins.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual - next_item_size < 10 {
            score -= 25.0;
        }
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Compare against mean residual: bins with more room than average are
    // better targets for large items.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Mild stream-progression term: tighten packing as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: only open a new bin if existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when the next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_pair = post_residual - next_item_size;
        score -= 12.0 + 0.25 * next_item_size as f64 - 0.15 * slack_after_pair as f64;
    } else if next_item_size > 0 {
        // penalize when next item cannot follow into this bin
        score += 6.0 + 0.1 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else {
        // penalize dead space relative to mean residual
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 18.0 } else { 0.0 };
        score -= desperation;
        score += 5.0 * (open_bins_count as f64).max(1.0).ln();
    }

    // Late in stream: prefer filling existing bins tightly
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty scaling.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize waste relative to mean residual across open bins.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but only if we place better now.
            let slack = (bin_residual - next_item_size) as f64;
            score += 0.5 * (slack - post_residual as f64).abs();
        }
        // Perfect pair: item + next item fill bin exactly.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Open new bin if mean residual too small for future items.
        let mut new_bin_score = 15.0 + 60.0 * crowding - 20.0 * progress;
        if fitting_bins_count <= 1 {
            new_bin_score += 10.0;
        }
        // If this bin would be nearly perfectly used by current item, don't open new.
        if post_residual <= 5 {
            new_bin_score += 50.0;
        }
        score = score.min(new_bin_score + 1.0);
        // Guarantee: never prefer new bin when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score = -1000.0;
        }
    }

    // Small penalty for leaving awkward residuals (10..20) that few items fill.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }
    // Reward residual 0 exactly.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild time decay: later in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, minimize waste strongly; later, tolerate residuals to keep bins open.
    let progress_weight = 0.6 * (1.0 - progress) * (1.0 - progress) + 0.15;
    score += progress_weight * (pr * pr) / cap;

    // Penalize residuals that are too small to be useful (dead space), smoothly.
    let dead = (cap * 0.2 - pr).max(0.0);
    score += 0.35 * dead * dead / cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = 1.0 - pr / cap;
    score -= 12.0 * fit_frac * fit_frac * fit_frac * fit_frac;

    // Last-resort bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Mildly discourage scattering across many open bins early in the stream.
    score += 0.4 * open_bins_count as f64 * progress;

    // Pull score toward mean residual level to balance bin loads smoothly.
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue classes mod common item sizes.
    // Residuals that are exact multiples of small size classes are "usable" -> reward.
    let pr = post_residual;
    if pr > 0 {
        let mut usable = false;
        for m in [5u32, 10, 20, 25, 50, 100].iter() {
            if m <= &cap as &u32 && pr % m == 0 {
                usable = true;
                break;
            }
        }
        if usable {
            score -= 0.35 * (pr as f64).sqrt();
        } else {
            // dead space penalty, stronger for small awkward residues
            score += 0.25 * (cap - pr as f64).min(pr as f64);
        }
    }

    // Perfect fit: huge reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does the residual match the next item's harmonic class?
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        // next item fits leaving small or class-aligned remainder
        if diff == 0 {
            score -= 200.0;
        } else if diff % 10 == 0 || diff % 5 == 0 {
            score -= 1.5 * diff as f64;
        } else {
            score -= 0.4 * diff as f64;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this residual at all -> penalize proportionally
        score += 0.15 * pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer filling fuller bins (small post_residual) via capacity-fraction thresholds
    let frac = post_residual as f64 / cap;
    if frac < 0.20 {
        score -= 3.0;
    } else if frac < 0.40 {
        score -= 1.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit,
    // or when open bins are already very full (mean residual small).
    if bin_residual == bin_capacity {
        let tight_exists = post_residual == 0; // meaningless for new bin; use mean_residual instead
        let _ = tight_exists;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 5.0; // open bins nearly saturated -> fresh bin fine
        } else {
            score += 6.0 + 0.05 * open_bins_count as f64; // keep using open bins
        }
    }

    // Slight preference to balance residual against mean (avoid fragmentation)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Mild time decay: later in stream, be greedier about tight fits
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * t * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot host the lookahead item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + 0.3 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item.
        score -= 12.0;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last usable bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 0.5 * pressure;
    }

    // New-bin candidate: make it moderately unattractive unless residual would be
    // exactly capacity (fresh space), so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 0.4 * pressure;
    }

    // Tightness bonus: reward bins whose residual is close to item size.
    let tightness = (bin_residual - item_size) as f64;
    score -= 20.0 * (1.0 - tightness / bin_capacity as f64).abs().min(1.0);

    // Slight progression term: later in stream, prefer tighter packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: post_residual equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Reward near matches for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap * 0.15);
    }
    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Prefer bins with residuals near/below mean residual (tight packing)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: only open new bin if residual is very small
    if bin_residual == bin_capacity {
        score += 30.0 + (post_residual as f64) * 0.5;
    }

    // Late in stream, prefer tighter fits
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual) via quadratic shaping.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Lookahead: penalize post_residual that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual is reusable by next item -> reward proportionally
            score -= 0.8 * next_item_size as f64;
        } else {
            // dead space relative to next item -> penalize
            score += 0.6 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else {
            0.0
        };
        score += 30.0 + 20.0 * pressure;
        // Early in the stream, allow more bins; later, be frugal.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Global congestion: many open bins with high mean residual -> favor
    // consolidating into existing bins (reward bins below mean residual).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
        // Slight penalty per open bin to discourage sprawl.
        score += 0.05 * open_bins_count as f64;
    }

    // Coupling: if next item is large, avoid leaving medium-sized residuals
    // that neither fit it nor are easily usable.
    if next_item_size > 50 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;

    // Normalized post residual
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let pr_sq = pr_norm * pr_norm;
    let pr_cu = pr_sq * pr_norm;

    // Smooth non-linear coupling: residual waste weighted by progress
    // Early in stream, tolerate residual; late in stream, penalize dead space strongly.
    score += (0.5 + 2.5 * prog_sq) * pr_sq * cap;
    score += 1.5 * prog_cu * pr_cu * cap;

    // Perfect fit bonus (non-linear decay around zero residual)
    let fit_bonus = (-pr_norm * 12.0).exp();
    score -= 20.0 * fit_bonus * (0.5 + progress);

    // Penalize leaving a residual that next item could have used but slightly larger than needed
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item fits: mild reward proportional to tightness
            let tight = 1.0 - (pr - ni) / cap;
            score -= 4.0 * tight;
        } else {
            // next item won't fit this residual: penalize dead space
            score += 3.0 + 0.05 * (pr - ni);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation
    let ob = open_bins_count as f64;
    score += 0.3 * ob.ln() * (1.0 + pr_norm);

    // Discourage opening new bins when a good fit exists (empty-bin candidate penalty)
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress) + 0.1 * item_size as f64;
        // If current item is large, opening a fresh bin is more acceptable
        score -= 0.08 * item_size as f64 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual deviates smoothly
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small classes is worse.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else {
        // dead space penalty grows super-linearly for unusable slivers
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    }

    // Fractional fill coupling: reward bins that become well-filled
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= fill * 20.0;

    // Modulo-10 harmonic class of post_residual vs next item size:
    // if the next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 20.0;
        } else if next_item_size > pr {
            // dead space that cannot host the next item: penalize by class
            let cls = pr % 10;
            score += if cls == 0 { 0.0 } else { (10 - cls) as f64 * 0.5 };
        }
    }

    // Last-chance bin: strongly favor using it rather than opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if item is large and current bins fit poorly
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count > 0 && mean_residual < item_size as f64;
        let base = 55.0 + item_size as f64 * 0.4;
        score += if tight_elsewhere { base } else { base * 2.0 + open_bins_count as f64 * 2.0 };
    } else {
        // mild reward for preferring existing bins as stream progresses
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Penalize leaving residuals in awkward modulo classes of capacity fractions
    let half = bin_capacity / 2;
    if pr > half {
        score += (pr - half) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (post_residual near zero but not dead space).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // New-bin candidate handling: empty bin has large post residual; make it
    // attractive only when no good fit exists (its base score is high already).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Penalize opening new bins more as open count grows.
        score += (open_bins_count as f64) * 2.0;
    }

    // Prefer bins whose residual deviates favorably from mean (fill below-average residual bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let slack = post_residual as i64 - next_item_size as i64;
        if slack == 0 {
            // Perfect 2-step packing: post_residual exactly fits next item.
            score -= 60.0;
        } else if slack > 0 {
            // Next item fits: reward proportionally to how close it is to filling.
            let closeness = 1.0 - (slack as f64 / bin_capacity as f64);
            score -= 40.0 * closeness * closeness;
        } else {
            // Next item won't fit in the remainder: penalize dead space.
            score += 15.0 * ((-slack) as f64 / bin_capacity as f64);
        }
        // Exact pair-fill bonus (item + next item == bin_residual).
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0 * fit_ratio;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 + fit_ratio * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0; // next item definitely needs fresh space anyway
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins where the item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Global state: when many bins are open with slack, encourage consolidation.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation * (open_bins_count as f64).ln();
        score -= 0.5 * open_bins_count as f64;
    }

    // Time horizon: early in the stream, be conservative (favor future flexibility);
    // late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fit_ratio;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement, slightly super-linear to punish dead space.
    let mut score = pr * (1.0 + 0.004 * pr);

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space is permanent).
    let tightness = 1.0 - (pr / cap).powf(1.5);
    score -= tightness * (0.5 + 2.5 * progress) * 10.0;

    // Reward filling the bin deeply relative to capacity.
    let fill = it / cap;
    score -= fill * fill * 20.0;

    // Lookahead: favor residual that can host the next item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack).powf(2.0);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powf(2.0);
        score += 30.0 - 25.0 * frag - 5.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "usable" leftovers.
    // Class by capacity fraction (integer division on post_residual).
    let quarter = bin_capacity / 4; // 25
    let tenth = bin_capacity / 10;  // 10
    let post = post_residual;

    // Dead-space penalty: leftover that is too small for typical items.
    if post > 0 && post < tenth {
        score += 60.0 * (1.0 - post as f64 / tenth as f64);
    }

    // Harmonic bonus: post_residual that is a "nice" fraction of capacity
    // (multiples of quarter or tenth) is reusable -> subtract.
    if post % quarter == 0 && post > 0 {
        score -= 18.0;
    } else if post % tenth == 0 && post > 0 {
        score -= 9.0;
    }

    // Modulo coupling with next item: if next item fits exactly into
    // post_residual (perfect chaining), strongly reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if post >= next_item_size {
            // leftover after placing next item: small chain remainder is good
            let chain_rem = post - next_item_size;
            if chain_rem < tenth {
                score -= 20.0 * (1.0 - chain_rem as f64 / tenth as f64);
            } else {
                score -= (chain_rem as f64).log2().max(0.0) * 3.0;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled
            // by how far off it is (integer division threshold classes)
            let gap = next_item_size - post;
            let gap_class = gap / tenth;
            score += 6.0 + 4.0 * gap_class as f64;
        }
    }

    // Item size harmonic class: large items (integer division thresholds)
    let item_class = item_size / quarter; // 0..3
    score -= 5.0 * item_class as f64; // prefer filling big items into tight bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // prefer bins that are tighter (few alternatives -> pick tightest)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let waste = if post < tenth { 1.0 } else { 0.0 };
        // Base cost of a new bin; discount late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 95.0 - 25.0 * progress;
        if item_size >= 3 * quarter {
            new_bin_cost -= 30.0; // big items may justify fresh bins
        }
        if next_item_size > 0 && post >= next_item_size {
            new_bin_cost += 40.0; // fresh bin chains well with next item
        }
        if waste > 0.0 {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits proportionally.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // post residual too small for next item: penalize small leftovers more
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // allow spreading when many bins are open with high mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are few or residuals large.
        score += 25.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Slight preference for bins with residual close to item (best fit style).
        score += 0.05 * (bin_residual as f64 - item_size as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size as f64 {
            score -= 500.0;
        } else if post_residual >= next_item_size as f64 {
            // residual slack after hypothetically placing next item too
            let two_step = post_residual as f64 - next_item_size as f64;
            score -= 50.0 * (1.0 - two_step / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small leftover dead space
            score += 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score -= 10.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless the fit is terrible (large post_residual dominates naturally)
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fills (dead space is the enemy).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for small-but-nonzero residuals that few items can use.
        let small_gap_penalty = 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);
        score += small_gap_penalty;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with how many bins are already open.
        let mut new_bin_cost = 90.0 + 4.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost *= 0.6 + 0.8 * progress;
        // If this bin is the last chance, opening a new bin is often fine.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        // If the next item is large, a fresh bin keeps room for it.
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    } else {
        // Lookahead bonus: if the next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // Reward proportional to how well the next item uses the leftover.
                let lookahead_fill = next_item_size as f64 / post_residual as f64;
                score -= 80.0 * lookahead_fill * lookahead_fill;
            } else {
                // Next item won't fit here: mild penalty for leaving a gap it can't use.
                score += 10.0;
            }
        }

        // Last-chance bin: strong reward to use it rather than open a new bin.
        if fitting_bins_count == 1 && post_residual < item_size.max(next_item_size) {
            score -= 120.0;
        }

        // Prefer bins whose residual is already below average (tightening tight bins).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 8.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // Global pressure: when many bins are open, discourage creating more fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / capacity;

    // Base: smooth polynomial in post_residual (favor tight fits)
    let mut score = 2.0 * pr - 1.5 * pr * fit_ratio + 0.5 * pr * fit_ratio * fit_ratio;

    // Non-linear coupling with stream progress: tolerate residual slack early,
    // penalize it increasingly as the stream advances.
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += (1.0 - progress) * 5.0 * fit_ratio * fit_ratio;
    score -= progress_coupling * 3.0 * (1.0 - fit_ratio);

    // Dead-space penalty: residual too small to fit any plausible future item
    let dead = if pr < 10.0 { 1.0 } else { (10.0 / pr).min(1.0) };
    score += 12.0 * dead * (1.0 - progress * 0.5);

    // Lookahead: reward bins whose post-residual accommodates next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / capacity);
        } else {
            score += 4.0 * (nxt - pr) / capacity;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: prefer opening a new bin early or when fit is poor
    if br >= capacity {
        score = 20.0 - 25.0 * (1.0 - progress) - 10.0 * (1.0 - fit_ratio);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    // Mean-residual coupling: bins far from mean residual get slight penalty
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fractions
    // post_residual in (0..=bin_capacity). Penalize dead space that is too small
    // to be useful later (harmonic class: tiny leftovers).
    let frac = post / cap;
    if post > 0.0 {
        if frac < 0.10 {
            // Excellent fill: near-perfect packing, strong reward
            score -= 40.0 + (0.10 - frac) * 300.0;
        } else if frac < 0.20 {
            // Good: still usable for small items
            score -= 10.0;
        } else if frac < 0.35 {
            // Awkward zone: dead space unlikely to be filled
            score += 15.0;
        } else if frac < 0.60 {
            // Moderately usable
            score += 5.0;
        } else {
            // Large residual: bin barely used, penalize unless new bin
            score += 10.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly well
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits: reward tightness of that fit
            let nxt_fit = (post - nxt) / cap;
            score -= 12.0 * (1.0 - nxt_fit * 4.0).max(0.0);
        } else {
            // Next item won't fit here: slight penalty proportional to gap
            score += (nxt - post) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 25.0;
        // If many bins fit the item, discourage opening a new one
        score += fitting_bins_count as f64 * 20.0;
        // If item exactly fills capacity fraction nicely (e.g. half), allow new bin
        if item_size as f64 / cap > 0.5 {
            score -= 20.0;
        }
        // Few open bins with high mean residual: fresh bin fine
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (mean_residual / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward placements that leave a gap still usable by typical items.
    if post_residual >= 10 {
        score -= 8.0;
        // Perfect fit gets an extra reward.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer filling existing ones (new-bin candidate has max residual).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += (post_residual as f64) * 0.3;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += ((bin_residual - item_size) as f64 - post_residual as f64).abs() * 0.0;

    // Progress-based mild drift: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far below mean residual (fragmentation signal).
    score += ((mean_residual - bin_residual as f64).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // tighter residual fit for next item => better
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating dead space that nothing (size >= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last fitting bin: strong reward to use it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // if lookahead shows a perfect next fit in a fresh bin, slightly ease penalty
        if next_item_size > 0 && bin_capacity == next_item_size {
            score -= 35.0;
        }
    }

    // Mild progression-based tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space less if it could host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // post_residual can host the next item: bonus.
            score -= 25.0 * (post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space too small for the next item: penalize proportionally.
            score += 0.5 * post_residual as f64 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; grows with number of open bins and stream progress.
        score = bin_capacity as f64 + 30.0 + 2.0 * open_bins_count as f64
            + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item is a perfect fit for an empty bin (item_size == capacity), allow it.
        if item_size == bin_capacity {
            score -= 200.0;
        }
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 50.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
    } else {
        // Mild penalty for bins deviating from the mean residual (prefer balanced usage).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Late in the stream, consolidate: favor bins that end near-empty waste minimization.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Smooth polynomial coupling: tight fits rewarded, dead space penalized
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + 0.5 * progress);
    // Non-linear interaction between post_residual and stream progress
    score += 10.0 * norm_post * norm_post * (1.0 - progress);
    // Reward bins that can also fit the lookahead item smoothly
    let can_fit_next = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
    score -= 15.0 * can_fit_next * (0.5 + 0.5 * progress);
    // Penalize opening new bins when alternatives exist, more so late in stream
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += 25.0 * is_new_bin * (1.0 - 0.3 * norm_item);
    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 30.0;
    }
    // Mild preference toward bins below mean residual (consolidate slack)
    score += 0.1 * (post_residual as f64 - mean_residual);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class penalty: residuals in awkward "dead zones" get extra cost.
    // Classes via integer division thresholds on post_residual.
    let class = (post_residual / 10).min(10);
    let class_penalty = match class {
        0 => -40.0,                 // perfect fit, almost no waste
        1 => -25.0,                 // excellent
        2 | 3 => 5.0,               // moderate waste
        4 | 5 | 6 => 15.0,          // poor zone (20-40 left)
        7 | 8 | 9 => 8.0,           // medium zone, still usable
        _ => 0.0,                   // near-full residual (new bin / big space)
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable.
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward proportional to how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 10.0 + 15.0 * snug;
        } else {
            // Dead space relative to next item: penalize more for tiny leftovers
            let waste = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-to-slightly-high base so it wins only
    // when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.2 * mean_residual;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 0 && next_item_size > (bin_capacity as u32 / 2) {
            score -= 12.0;
        }
        // Few open bins and large mean residual -> reuse is fine, penalize new bin.
        if open_bins_count > 0 && mean_residual > 0.35 * cap {
            score += 15.0;
        }
    }

    // Tie-break: prefer bins whose residual deviates positively from the mean
    // (consume the "odd" bins first, keeping uniform residuals for future items).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for tighter bins overall.
    score += 0.03 * frac * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger residual gaps are reusable; mild reward scaled by size.
        score -= (post_residual as f64) * 0.15;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new one (unless post_residual is truly dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when the item would leave a bad gap in
    // every existing bin. Give the fresh bin a moderate baseline so tight fits win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the item fills the new bin exactly or nearly, make new bin attractive.
        if item_size >= 90 {
            score -= 80.0;
        }
    }

    // Lookahead: if next item fits the resulting post_residual well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is too big for the residual but residual is small, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Mean-residual coupling: if this bin is far below average residual, it's a
    // good candidate to absorb the item (keeps big gaps available elsewhere).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: late in the stream, be slightly more conservative with bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space penalty, super-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward leftover matching next item proportionally
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * ratio;
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit, more so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
        // but if leftover would be unusable anyway, new bin is fine
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
    }

    // Mild preference for fewer open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by fraction of bin consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical small item (<= 20).
    if post_residual < 20 {
        score -= 12.0; // small dead space is fine (bin nearly full)
    } else if post_residual < 40 {
        score += 4.0;
    } else {
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: prefer fuller bins when many bins are open.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fullness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Global residual pressure: if mean residual is high, favor filling existing bins.
    score -= 5.0 * (mean_residual / bin_capacity as f64) * fullness;

    // Time horizon: early in stream, be picky (penalize loose fits more); late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * (1.0 - fullness);

    // New-bin candidate: only attractive when no bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 14.0 };
        score += desperation + 6.0 * (1.0 - progress);
        if item_size > 60 {
            score -= 5.0; // big items are fine in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: waste grows super-linearly with residual
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Tight fits rewarded
    score -= 25.0 * (item_size as f64 / cap) * (1.0 - norm_pr);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: next item fits into post-residual -> reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - norm_pr) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * norm_pr;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;
    score -= (mean_residual / cap).max(0.0) * 5.0;

    // New-bin candidate penalty unless current residual is unusable
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * norm_pr * 0.0; // empty bin baseline
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item-size classes: 10, 20, 25, 50).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fit, best possible outcome
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space: residuals below the smallest plausible item (10)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Fractional fill: reward high utilization of the bin
    let fill = 1.0 - (post_residual as f64) / cap_f;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // harmonic class match between next item and post residual
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
            score -= 6.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; slight penalty if this bin was the only option
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make fresh bins mildly unattractive unless
    // current bin would leave a lot of dead space.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
        // but if item is huge relative to typical residual, fresh bin is fine
        if (item_size as f64) > 0.7 * cap_f {
            score -= 10.0;
        }
    }

    // Late in stream: prefer tightening existing bins (fewer open bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 4.0 * ((post_residual as f64) / cap_f);

    // Prefer bins below mean residual (tighter bins) to consolidate
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Unusable small gap: post_residual > 0 but too small for the next item
    // (or for anything meaningful when next_item_size is unknown/0).
    let min_useful = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && (post_residual as u64) < (min_useful as u64) {
        // Dead space penalty: worse the tighter the gap, amplified by stream progress
        // (late in the stream, stranded capacity can never be recovered).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 0.6 * post_residual as f64 + 8.0 * progress;
    }

    // Tiny residual that no typical item (>=1) can exploit is already handled;
    // additionally penalize "sliver" gaps <= 3 as near-dead regardless of lookahead.
    if post_residual > 0 && post_residual <= 3 {
        score += 6.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when open bins exist and have slack,
        // scaled by how many bins are already open (open-bin pressure).
        score += 8.0 + 0.35 * open_bins_count as f64 + 0.15 * mean_residual;
    } else {
        // Reward using an existing bin, more strongly if it is the last chance
        // (avoiding a brand-new bin entirely).
        if fitting_bins_count == 1 {
            score -= 7.0;
        }
        // Mild reward for tightening bins when many are open (consolidation pressure).
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual slightly larger than next item (usable next step).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap).max(0.0);
    }
    // Post residual too small for next item: dead space penalty, worse if tiny.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    if next_item_size > 0 && post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Penalize bins deviating from mean residual (prefer balanced or extreme reuse).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        if post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        // Late in the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins already: prefer reuse over opening another.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
