    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev; // larger-than-average residual => less consolidated => penalize
    }

    // Time horizon: early in stream, opening new bins is cheap (slightly favor empty-bin
    // flexibility); late in stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist.
        score += 5.0 + 25.0 * progress + (open_bins_count as f64).min(20.0);
        // But if no open bin fits well, allow new bin: handled implicitly by other scores.
        if fitting_bins_count == 0 {
            score -= 20.0; // shouldn't happen for empty bin, but guard
        }
    } else if fitting_bins_count == 0 {
        // No open bin can fit (this shouldn't occur for scored bins), neutral.
        score += 0.0;
    }

    // Late stream: extra consolidation pressure proportional to progress.
    score -= 10.0 * progress * fit_ratio;

    // Small penalty on very large residuals relative to capacity to prefer tighter bins.
    score += 0.05 * (bin_residual as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: waste penalized more as stream progresses
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Reward tight fits, amplified over time
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 12.0 * (1.0 - post / nx.max(1.0)) * (0.4 + 0.6 * progress);
        } else {
            score -= 6.0 * (post / cap);
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when open bins are quite full or many are open
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post).max(0.0);
        score += 18.0 - 10.0 * (mean_gap / cap) - 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) - 6.0 * progress;
    }

    // Mild penalty when bin deviates from mean residual (encourage balance)
    score += 4.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class boundaries via integer division thresholds on post_residual.
    let pr = post_residual;
    let class: u32 = if pr == 0 {
        0 // perfect fit
    } else if pr <= cap as u32 / 8 {
        1 // tiny dead space, nearly perfect
    } else if pr <= cap as u32 / 4 {
        2
    } else if pr <= cap as u32 / 2 {
        3
    } else {
        4 // large leftover, still flexible
    };

    // Reward low classes (perfect / tight fits), penalize mid classes.
    let class_bonus = match class {
        0 => -60.0,
        1 => -35.0,
        2 => 0.0,
        3 => 12.0,
        _ => -8.0,
    };
    score += class_bonus;

    // Modulo arithmetic on post_residual: leftovers divisible into common
    // small item sizes (10/20/25/50) remain packable.
    let small_sizes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut divisible = false;
    for s in small_sizes.iter() {
        if pr % *s == 0 && pr > 0 {
            divisible = true;
            break;
        }
    }
    if divisible {
        score -= 10.0;
    }

    // Harmonic fraction of item size relative to capacity.
    let frac = item_size as f64 / cap;
    if frac > 0.5 {
        score -= 15.0; // big items should go into tightest available space
    } else if frac < 0.2 {
        score += 5.0 * (1.0 - frac * 5.0); // tiny items prefer roomy bins
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > pr && pr > 0 {
        score += 6.0; // dead space for the known next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: fresh empty bin gets post_residual = capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when few bins are open early, or when current fit is bad.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        score += penalty;
        // But if this bin would leave a terrible mid-class residue for a big item,
        // opening fresh may be better: relax penalty for large items.
        if frac > 0.6 && class == 3 {
            score -= 35.0;
        }
    }

    // Spread pressure: when mean residual is high, favor filling laggard bins.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space penalty: gaps too small for the next item are wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 60.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        // Very small unusable gaps (below min item size 1..10 heuristic band).
        if post_residual < 10 {
            score += 40.0;
        }
        // Mild reward for leaving a gap that exactly fits the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Tightness reward: prefer bins that the item fills well.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good existing fit exists (post_residual here equals capacity - item).
    if bin_residual == bin_capacity {
        // Neutral baseline; new bins should rarely win unless existing fits are poor.
        score += 25.0;
        if item_size >= 70 {
            score -= 30.0; // large items start fresh bins happily
        }
    }

    // Late in the stream, consolidate: prefer reusing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 15.0;
    }

    // Prefer bins with residual near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize proportional to overshoot
        let over = (next_item_size - post_residual) as f64;
        score += 0.5 * over;
    }

    // Perfect closure: filling a bin completely is excellent
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave big dead space
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly, more as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;
        // but if item fits poorly in any existing bin (large dead space anyway), soften
        if post_residual < 15 {
            score -= 35.0;
        }
    }

    // Penalize leaving large unusable gaps relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny dead space is worthless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty for small leftovers.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / bin_capacity as f64;
    } else {
        score -= 20.0; // perfect fill
    }

    // Dead-space penalty: leftover too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits in this bin's post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // Chain fit: both item and next item nearly fill bin.
        if item_size + next_item_size as u32 >= bin_residual && item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Prefer fuller bins relative to mean residual (best-fit-like bias).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early on, encourage opening bins to spread load;
    // late in stream, consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: open when existing bins fit poorly or many bins open.
        score += 25.0 - 20.0 * progress;
        if post_residual as f64 > mean_residual * 1.5 {
            score += 5.0;
        }
        if fitting_bins_count <= 2 && progress > 0.5 {
            score -= 10.0; // late stream: reuse rather than open
        }
    }

    // Mild consolidation pressure as open bins grow.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Prefer bins whose residual is close to item size (minimal waste).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    let mut score = post;
    score += 40.0 * fit_ratio * fit_ratio;
    score -= 25.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 - progress);
    score += 15.0 * (post - mean_residual) / cap * (0.5 + 0.5 * progress);
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap) * (1.0 - progress);
        }
    }
    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - fit_ratio);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but harmonic-class adjustments refine it.

    // Harmonic class of post_residual: residues mod 10 and mod 20.
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;

    // Dead-space penalty: residuals that are unusable for typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space < smallest item
    }

    // Harmonic bonus: post_residual divisible by 10 or 20 is more reusable
    // (typical item sizes cluster on multiples of 5/10).
    if r10 == 0 {
        score -= 6.0;
    }
    if r20 == 0 {
        score -= 4.0;
    } else if r20 == 10 {
        score -= 2.0;
    }

    // Lookahead coupling: does next_item_size fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Exact harmonic match is excellent.
            if slack == 0 {
                score -= 25.0;
            } else if slack % 10 == 0 {
                score -= 12.0;
            } else if slack < 10 {
                score += 10.0; // leaves dead space after next item
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; mild penalty unless residual is tiny anyway.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh harmonic slate.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are fragmented
        // (mean residual low relative to what's needed) or many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Base reluctance to open a new bin when a decent fit exists.
        score += 30.0;
        score -= 20.0 * fragmentation * pressure;
        score -= 10.0 * progress; // later in stream, consolidation matters less
        // If item is large, new bin gives clean harmonic capacity.
        if item_size >= 50 {
            score -= 8.0;
        }
        // If next item is large, keep clean bins available.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Slight preference for bins whose residual class matches the item class.
    let item_class = item_size / 10;
    let bin_class = bin_residual / 10;
    if item_class == bin_class {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: heavily penalize post_residual that falls into
    // an "unusable gap" zone (small but nonzero, hard to fill by future items).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Dead space below the minimum item size is pure waste.
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Awkward gap: only small items can use it.
        score += 25.0 * (25.0 - pr) / 15.0;
    } else if post_residual >= 25 && post_residual < 45 {
        // Moderately awkward.
        score += 8.0 * (45.0 - pr) / 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // would create new tiny dead space
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins; with few open bins, tolerate spreading (new-bin candidate competes).
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or residual is small;
        // attractive when current bins would leave big awkward gaps.
        let spread = (pr - 20.0).abs();
        score += 18.0 + bin_pressure - spread.min(30.0) * 0.5;
    } else {
        score -= bin_pressure * 0.3;
    }

    // Late in stream: be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 12.0;
    }

    // Mild preference for bins below mean residual (balancing loads).
    score += 0.15 * (mean_residual - bin_residual as f64).abs().min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // Perfect chain: post_residual == next_item_size
            if slack == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap
            score += 0.25 * (post_residual as f64 - mean_residual).abs();
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 5.0;
    }

    // Penalize large dead space relative to mean residual
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight bias toward filling fuller bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (item_size as f64 / bin_capacity as f64) * 4.0;

    // Make brand-new empty bins less attractive unless the item fits poorly everywhere
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // Non-linear penalty on dead space relative to capacity.
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += dead_frac * dead_frac * 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post-residual closely matches next item (chain packing).
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < 10 {
            // Small dead space is fine if next item can't use it anyway.
            score += 2.0;
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against the new-bin candidate: an empty bin scores ~ its residual (100)
    // minus baseline. If this bin's residual is large and fit is poor, opening a new
    // bin may be better; nudge score up so new bin wins.
    let new_bin_score = bin_capacity as f64 - 15.0; // what an empty bin would roughly score
    if bin_residual >= bin_capacity {
        // This IS the new-bin candidate: make it attractive when current bins are crowded,
        // unattractive when open bins have plenty of room.
        score -= 20.0 * (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in stream, avoid spawning excess bins.
        score += (1.0 - progress) * 5.0 + open_bins_count as f64 * 1.5;
        if fitting_bins_count > 3 {
            score += 30.0; // plenty of alternatives; deprioritize new bin
        }
    } else {
        // If this bin's score would exceed the new-bin baseline anyway, tighten competition.
        if score > new_bin_score && fitting_bins_count > 1 {
            score = new_bin_score + 1.0;
        }
    }

    // Mild preference for filling fuller bins (higher fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // Slight tie-break toward bins already close to mean residual (balance avoidance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress * norm_pr);

    // Penalize large dead space more than linearly (quadratic term)
    score += 0.6 * norm_pr * norm_pr * (1.0 + progress);

    // Tight fits rewarded, scaled by progress
    let tightness = 1.0 - norm_pr;
    score -= 1.5 * tightness * tightness * (1.0 + 0.5 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = if pr >= ni { 1.0 } else { 0.0 };
        score -= 0.8 * fits_next * (ni / cap) * (1.0 + progress);
    }

    // Mild penalty proportional to open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes (5,10,20,25,50) leave "reusable" space; odd residues are dead space.
    let pr = post_residual;
    let residue_class: f64 = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 50 == 0 {
        -15.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -3.0
    } else if pr % 5 == 0 {
        0.0
    } else {
        8.0 // indivisible residue: likely dead space
    };
    score += residue_class;

    // Integer-division threshold on post_residual: small slivers are waste.
    let pr_quarter = pr / 25; // 0..=4 classes
    score += match pr_quarter {
        0 => 14.0,                 // 0 < pr < 25: unusable sliver
        1 => 4.0,
        2 => -2.0,
        3 => -5.0,
        _ => -9.0,                 // large residual: roomy bin
    };

    // Coupling with lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;         // chain placement possible
            // Harmonic match: next item exactly divides post_residual
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0;          // next item won't fit here anyway
        }
    } else {
        score -= 5.0;              // last item: fill greedily
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 4 {
        score += 2.0 * (fitting_bins_count as f64 - 4.0).min(6.0);
    }

    // New-bin candidate: only attractive when item is huge relative to
    // capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let big_item = item_size as f64 / cap;
        let pressure = (big_item - 0.5).max(0.0) * 30.0
            + (0.35 - crowded).max(0.0) * 40.0;
        score += 45.0 - pressure;  // default penalty, discounted under pressure
    }

    // Tightness reward: prefer bins where item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 15.0;

    // Mild stream-phase modulation: early phase favors consolidation.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - phase) * (mean_residual - post_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (residual below typical small item size).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave a worse gap, slight penalty.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap < 10 {
            score += 6.0;
        }
    }

    // Prefer keeping mean residual spread balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: bias slightly high so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 20.0 * chain_fit;
        // Extra bonus when chain leaves a small dead space.
        if post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating a residual that the next item cannot use (dead space).
        score += 6.0;
    }

    // Compare residual against mean residual of open bins: keeping spread balanced.
    let mean_res = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.5 * ((post_residual as f64) - mean_res);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit is bad.
    if bin_residual == bin_capacity {
        // A fresh bin has huge residual; make it attractive only when current fits are poor.
        score += 10.0;
        if post_residual as f64 > mean_res + 0.5 * (bin_capacity as f64) {
            score -= 5.0;
        }
        // Late in stream, prefer closing out open bins rather than spawning new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    }

    // Slight preference for bins with more items packed (implied by small residual early).
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post residual), stronger when few alternatives exist.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain as f64 / cap);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting space now.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open
    // and mean residual is large; encourage using existing space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / cap;
        let mut penalty = 15.0 + 30.0 * waste + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in stream, closing out bins matters more; soften new-bin penalty.
        penalty *= (1.0 - 0.5 * progress);
        score += penalty;
        // If no existing bin fits well, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for fuller bins among comparable residuals.
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = norm_pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, moderate residuals are fine; late in the stream, dead space
    // becomes increasingly costly, so penalize residual quadratically.
    let p = progress;
    let quad = norm_pr * norm_pr;
    score += quad * (0.6 + 1.4 * p);
    // Cubic coupling: extreme dead space penalized super-linearly, stronger late
    score += norm_pr * quad * (0.3 + 1.2 * p);

    // Interaction: residual relative to mean residual across open bins.
    // Leaving more than average residual is wasteful; less than average is good.
    let mr = mean_residual / cap;
    let dev = norm_pr - mr;
    score += 0.35 * dev * dev - 0.25 * dev;

    // Lookahead coupling: reward leaving space that fits the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - (pr - ns) / cap; // 1 = perfect fit for next
            score -= 0.45 * fit_quality * fit_quality * (0.5 + 0.5 * p);
        } else {
            // post residual cannot host next item: penalize proportionally to waste
            let waste = pr / cap;
            score += 0.30 * waste * (0.4 + 0.6 * p);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2;
        // even more urgent late in the stream
        score -= 0.8 * p;
    } else if fitting_bins_count > 1 {
        // slight penalty when many alternatives exist, to keep flexibility
        score += 0.05 * ((fitting_bins_count as f64).ln());
    }

    // New-bin candidate handling: an empty bin has norm_pr == 1.0; the quadratic
    // and cubic terms above already give it a high score (~2.1+). Add a mild
    // penalty that grows with open bins count so we only open when truly needed.
    if bin_residual == bin_capacity {
        score += 0.25 + 0.05 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues near multiples of small divisors
    // indicate dead space that future items (sizes 1..100) may or may not reuse.
    let pr = post_residual;
    // Perfect fit: strongly favored.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Modulo-classes: penalize residuals that are awkward (small but nonzero)
        // since items >= 10 typically can't use them.
        let m10 = pr % 10;
        let m25 = pr % 25;
        let m50 = pr % 50;
        if pr < 10 {
            score += 25.0; // unusable dead space for items 10..80
        }
        if m10 == 0 {
            score -= 6.0; // divisible by 10: reusable by many item sizes
        }
        if m25 == 0 {
            score -= 4.0;
        }
        if m50 == 0 {
            score -= 3.0;
        }
        // Harmonic decay: value of residual shrinks with its size class.
        let cls = (pr / 10) as f64;
        score -= (cls * (cls + 1.0) * 0.5) * 0.4;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty for tight bins that strand.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins below mean residual (balance toward fuller bins).
    score += 0.5 * (mean_residual - post).max(0.0) * -1.0;
    score += 0.3 * (post - mean_residual).max(0.0);

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base competitiveness: opening a new bin is moderately costly.
        score = 45.0 + post;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 20.0;
        }
        // Early in stream, new bins are cheaper (few commitments).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // Many open bins: discourage spreading.
        score += (open_bins_count as f64).min(20.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small nonzero gaps are hard to fill (sizes >= 1,
    // but tiny gaps waste capacity). Penalize gaps below a usable threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins deviating toward filling the mean.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Exact or near-exact match for the next item is highly desirable.
            let match_err = post - nxt;
            score -= 30.0 * (1.0 - match_err / 50.0).max(0.0);
            // Perfect chain (post_residual == next_item_size) gets extra reward.
            if match_err < 1.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            score += 10.0 + (nxt - post) * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average, penalize outliers.
    let post = post_residual as f64;
    score += (post - mean_residual) * 0.4;

    // Penalize dead space: small residuals that likely can't fit future items (sizes >= 10).
    if post < 10.0 && post > 0.0 {
        score += 12.0;
    } else if post < 20.0 && post >= 10.0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so that any
    // reasonable existing fit wins, but a very poor fit still opens a new bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; late, consolidate more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for keeping fewer open bins when scores are close.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(3));

    // Penalize dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
        } else {
            // next item won't fit here; mildly penalize wasting space now
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading across many open bins when mean residual is low
    // (fragmentation pressure); reward consolidating into fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 12.0 * fullness * (open_bins_count as f64).ln().max(1.0) / 3.0;

    // Compare against mean residual: prefer bins below-average residual (fuller bins).
    score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 30.0 * (1.0 - progress) * (fullness - 0.5); // early: prefer emptier bins
    score -= 20.0 * progress * fullness;                  // late: prefer fuller bins

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are bad (large post_residual) or fragmentation is severe.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin
        let _ = bad_fit;
        // Base penalty so new bins aren't opened casually.
        score += 55.0;
        // But relax penalty if item is huge and would leave near-zero residual anyway
        // (i.e., item almost fills a bin) — perfect fit in fresh bin.
        if item_size >= bin_capacity - 5 {
            score -= 70.0;
        }
        // If many open bins exist with poor residuals, new bin is fine.
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 30.0;
        }
        // Late in stream, avoid new bins more strongly.
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity
    let tightness = 1.0 - post / cap;
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, larger dead space is increasingly penalized
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits exactly in post_residual, strongly reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fill = (next_item_size as f64) / post.max(1.0);
        score -= 15.0 * fill * fill;
    }
    // If next item would be blocked by this placement, penalize slightly
    if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) <= bin_residual as f64 {
        score += 8.0 * ((next_item_size as f64) - post) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Discourage spreading across too many bins when mean residual is already low
    let mean_norm = mean_residual / cap;
    score -= 10.0 * (mean_norm - norm_post).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins give bad fits
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover space too small for the lookahead item
    // is likely wasted unless the stream is ending.
    if next_item_size == 0 {
        // Last item: just minimize post_residual (already the base).
    } else if post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.05;
    } else if post_residual >= next_item_size && post_residual > 0 {
        // Room for the next item: reward chaining placements.
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Harmonic class coupling: item sizes mod 10 create size classes.
    // Penalize bins whose residual falls into an awkward class boundary
    // (residual just barely above a multiple of 10 tends to leave slivers).
    let class = post_residual % 10;
    if post_residual > 0 && class <= 2 {
        score += 2.5; // sliver residuals (1..=2) are nearly useless
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default: mildly discourage opening a new bin when existing bins fit.
        score += 5.0;
        // But if no (or only this) existing bin truly fits, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Early in the stream, spreading large items into fresh bins helps.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0 * (item_size as f64 / bin_capacity as f64);
        // If the next item is large and current open bins are nearly full,
        // a fresh bin keeps capacity balanced.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 4.0;
        }
    }

    // Mild diversity pressure: prefer bins whose residual differs from the mean
    // (keeps a mix of large/small residuals available for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev - 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps in [10,20) can only host tiny items; moderate penalty.
        score += 15.0;
    }

    // Reward tight fits (small relative leftover).
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score -= (1.0 - tightness) * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins and a poor fit, opening a fresh bin is acceptable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if its post_residual is large and
        // usable, and the stream is early (many items still coming).
        score = post_residual as f64 + pressure * 3.0 - progress * 20.0;
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // gap won't fit the lookahead item
        }
    } else {
        // Mild penalty scaled by open-bin pressure to avoid bin proliferation.
        score += pressure * 0.05;
        // Lookahead coupling: reward a residual that can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 8.0;
        }
        // Prefer bins whose residual is below mean (compact packing).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // --- 2-step lookahead: reward bins whose post_residual matches next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            // Next item fits exactly after this placement -> big reward.
            let slack_after_next = post_residual as f64 - next;
            let match_quality = 1.0 - (slack_after_next / bin_capacity as f64);
            score -= 55.0 * match_quality.max(0.0);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            let gap = next - post_residual as f64;
            score += 18.0 * (gap / bin_capacity as f64);
        }

        // Exact 2-step chain: item + next fills bin completely.
        if item_size as f64 + next == bin_residual as f64 {
            score -= 70.0;
        }
    } else {
        // Last item: purely minimize post_residual.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Dead-space penalty: post_residual too small for any future item (1..100) ---
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // --- Relative to mean residual: prefer bins already below-average residual
    //     (consolidate waste into few bins rather than spreading it). ---
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 12.0 * rel;

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling: only attractive when no open bin is decent ---
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a perfect fit, better than bad fits.
        score = 35.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
        // Late in the stream, opening new bins is less costly (no future to serve).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    }

    // Mild preference to fill bins when many are open (limit bin proliferation).
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // Penalize creating dead space that the next item cannot use.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (explore); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 8.0 * waste_frac;

    // Global state: many open bins with large mean residual -> favor filling
    // existing bins rather than opening new ones.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // (large waste elsewhere) or stream is early with room to organize.
    if bin_residual == bin_capacity {
        let escape_valve = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += escape_valve + progress * 10.0 - (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) sharpening
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early stream -> tolerate larger residuals (explore), late stream -> punish them hard
    let coupling = 1.0 + progress * (2.0 * progress - 1.0);
    score *= coupling;

    // Interaction: post_residual vs mean residual — avoid creating outliers
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus (only one bin fits): strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 0.5 * gap * (1.0 - progress);
        } else {
            score += 0.8 * (-gap);
        }
    }

    // New-bin candidate: penalize mildly early, more when open bins are scarce
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (0.3 + progress);
    }

    // Tiny tie-break toward tighter fits
    score + 0.01 * item_size as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: strong reward for completely filling a bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling (k=2): reward bins that can also host the next item,
    // penalize bins whose leftover is just below the next item size (dead space).
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Harmonic class logic: residual modulo 10 (capacity/10 fraction class).
    // Round residuals (multiples of 10) align with common capacity fractions
    // and are slightly preferred over ragged leftovers.
    let harmonic_class = post_residual % 10;
    score += harmonic_class as f64 * 0.5;

    // Integer-division threshold on post_residual: residuals in the lowest
    // decade (1..=9) are nearly dead space; penalize them extra.
    if post_residual > 0 && (post_residual / 10) == 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Tightness coupling: prefer bins whose residual is below the mean
    // residual across open bins (already well-utilized bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; grows as the stream progresses
        // (late in the stream, consolidating is more valuable).
        score += 10.0 + 20.0 * progress;
        // Early in the stream, opening a new bin is cheap and keeps options
        // open for future large items; discount the penalty.
        score -= 25.0 * (1.0 - progress);
        // If few or no open bins fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If the next item is large and would fit better in a fresh bin,
        // make the new bin more attractive.
        if next_item_size > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1 unit interface) are penalized progressively; "almost usable" gaps
    // that can't hold the next item are also punished.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap unusable for the lookahead item: dead space risk
        let frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 40.0 * frac;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap still usable for next item: mild reward
        score -= 5.0;
    }

    // Penalize large leftover less if bin is nearly full anyway (good packing).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New empty bin candidate: make it unattractive unless the fit into open
    // bins would be terrible (huge dead space) or no bins fit well.
    if bin_residual == bin_capacity {
        let bad_fit = mean_residual < item_size as f64 * 0.5 && fitting_bins_count > 0;
        if bad_fit {
            score -= 20.0; // allow new bin when open bins waste > half their space
        } else {
            score += 150.0 + pressure * 3.0;
        }
    }

    // Tie-break: prefer bins whose residual is closest above the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next item size.
    if next_item_size > 0 {
        let match_err = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-match_err / 20.0).exp(); // strong bonus for exact 2-step fit
        // small bonus if next item fits exactly leaving zero
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // penalize leaving a gap that neither next item nor future small items can use
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // dead space below minimum item size
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Compare bin's residual to mean residual: prefer filling bins with more residual
    // (keeps tight bins available for smaller items), unless it makes a perfect fit.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            // discourage opening a new bin when open bins exist that fit
            25.0
        };
        score += poor_fit;
        // early in stream, opening new bins is cheaper; late, prefer packing tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if next item is large and post_residual would be unusable for it, opening new bin
        // with residual 100-item_size may chain better
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // mild penalty for very large leftover waste
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual shaped by stream progress
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (1.0 - progress);

    // Tight fits are rewarded more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 18.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space far from capacity, modulated by open bin count
    let congestion = (open_bins_count as f64).ln() / 3.0;
    score += 8.0 * pr_norm * pr_norm * pr_norm * congestion;

    // Lookahead: prefer bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual deviation: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize unless residuals are large and stream is early
    if bin_residual == bin_capacity {
        let newbin_bias = 20.0 * (1.0 - progress) + 14.0 * pr_norm;
        score += newbin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 120.0; // near-perfect, dead space mostly unusable anyway
    } else if post_residual <= 25 {
        score -= 40.0;
    }

    // Harmonic class: dead space in "small residue" classes is hard to reuse.
    let h = post_residual % 20;
    if h <= 3 {
        score -= 15.0; // residue nearly a multiple of 20 aligns with common item sizes
    } else if h >= 17 {
        score += 10.0;
    }

    // Penalize mid-range dead space (10..30) that is still usable but wasteful.
    if post_residual > 10 && post_residual < 30 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 30.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here anyway; prefer larger leftover for future variety
            score += 5.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Discourage opening new bins when good open bins exist and stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a decent fit.
        score += 30.0 + 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin offers flexibility
        }
    }

    // Prefer filling bins whose residual deviates from mean (consolidate waste).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Mild pressure to prefer larger residuals when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual in [1, 9] is unusable
    // dead space (min item size is 1 in interface terms, but tiny gaps
    // below ~15 waste capacity). Penalize non-linearly.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 8.0;
    }

    // Reward placements that leave a gap still usable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect lookahead fit: keep this bin ready for next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual cannot host the next item: mild penalty scaled by gap size.
        score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins are few or this placement would create bad dead space.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins (pressure to reuse).
        score += 25.0 + (open_bins_count as f64) * 6.0;
        // But if current placement would strand a tiny gap, new bin becomes
        // relatively attractive: subtract when post_residual here is 0 anyway.
        // (post_residual == bin_capacity for the new bin, so exact-fit bonus
        // won't fire; rely on the dead-space penalty of competitors.)
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, prefer consolidating: extra pressure.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
    }

    // Prefer tighter bins overall: bias toward bins below mean residual
    // (i.e., well-filled bins) when residual is large.
    if (bin_residual as f64) > mean_residual + 30.0 && bin_residual < bin_capacity {
        score += 10.0; // this bin is relatively empty; deprioritize slightly
    } else if (bin_residual as f64) < mean_residual {
        score -= 5.0; // tighter than average bin: slight preference
    }

    // Open-bin pressure: with many open bins, discourage leaving mid-size gaps.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 30 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    // (chain packing), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack left after hypothetically placing next item too
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 + slack_after_next as f64 * 0.3;
        } else {
            // dead space the next item cannot use
            let waste = post_residual as f64;
            score += waste * 0.5;
            // extra penalty if post_residual is a small unusable sliver
            if post_residual < 10 {
                score += 40.0;
            }
        }
    } else {
        // last item: just minimize residual
        score -= 50.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tighter bin) is preferred to keep loose bins flexible.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit is poor
    // or lookahead suggests better use of a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0 && next_item_size > 0 && post_residual < next_item_size;
        if poor_fit {
            score -= 30.0; // allow opening a fresh bin for bad fits
        } else {
            score += 120.0; // discourage wasting a fresh bin on decent fits
        }
    }

    // Early in stream, slightly prefer consolidating (fewer bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (below min item size 1..100, use 20 as soft threshold).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward; if not, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.2 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the tightest one; slight penalty to keep competition meaningful.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below the mean (already well-utilized).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // New-bin candidate: penalize opening a new bin, more so late in the stream or when few bins fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Opening a new bin is attractive if the item is large and would leave awkward residue elsewhere.
        if item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mild penalty on spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post residual, weighted non-linearly by stream progress
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let poly = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 2.0 * poly * (0.3 + 0.7 * progress);

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            score += 1.2 * (ni - pr) / cap;
        } else {
            score -= 0.8 * (ni / cap) * (1.0 - norm_pr);
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.9 + 0.6 * progress;
    }

    // Slight penalty relative to mean residual spread
    score += 0.3 * (mean_residual - pr / cap).abs();

    // Discourage opening new bins early when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 0.5 + 0.8 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Harmonic class of the leftover: classify post_residual into modulo bands.
    let class = post_residual % 10;
    match class {
        0 => score -= 6.0,          // round leftover, reusable by many item sizes
        1 | 2 => score += 3.0,      // awkward sliver
        3 | 4 | 5 => score -= 2.0,  // mid-range usable
        6 | 7 => score += 1.5,
        _ => score -= 0.5,
    }

    // Penalize large dead space relative to capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 8.0 * frac; // half-empty bin wasted on a small item
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // leftover too small for next item: penalize proportionally to dead space
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Prefer new bin when existing bins are mostly full / fragmented.
        score = 50.0 - 30.0 * mean_tightness - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for the next item too
        }
        return score;
    }

    // Slight preference for filling fuller bins earlier in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: post_residual in "unusable" small gaps
    if post_residual > 0 {
        let dead_threshold = 12.0; // gaps below this are unlikely to fit typical items
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Non-linear penalty for mid-range wasted space
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // Reward tight fits (exact fill is ideal)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if next item almost fits but not quite (creates blocking gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, favor consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.2;
    }

    // Mean-residual coupling: prefer bins with below-mean residual (denser bins)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate handling: make opening a new bin moderately costly,
    // but acceptable when residuals are tight (nothing would fit well anyway)
    if bin_residual == bin_capacity {
        score += 10.0;
        // If existing bins are very full / mean residual small, new bin is fine
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 5.0;
        // Late in the stream, prefer closing out bins
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep some usable space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward closeness.
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
            if gap == 0.0 {
                score -= 40.0; // perfect chain
            }
        } else {
            // Next item cannot fit in the leftover: penalize dead space,
            // especially if the dead space is small (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0; // tiny dead space is nearly worthless
            }
            score += 0.3 * dead;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average residual is good (compact packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > bin_capacity / 2 {
            score -= 30.0; // large items are fine in a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin supports the chain too
        }
    }

    // Early in the stream, be slightly more willing to open bins
    // (keeps flexibility); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * item_size as f64;

    // Reward exact-ish fills (post_residual very small).
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that few future items can use:
    // residual below the minimum item size (1) is impossible, but small
    // unusable slivers relative to typical item sizes are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // awkward sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item can still go here; mild bonus proportional to fit quality
            let nl_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * nl_fit;
        } else {
            // next item won't fit here; penalize slightly more if post_residual is large-ish
            score += 3.0 + (post_residual as f64 - next_item_size as f64).min(30.0) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // this existing bin. Penalize new bins unless existing fit is poor.
    if bin_residual == bin_capacity {
        // New bin: baseline cost of consuming fresh capacity.
        score += 12.0;
        // Early in stream, opening bins is fine (build a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins already open, prefer reusing.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Prefer bins whose residual is below the mean (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Mild time-horizon modulation: late in the stream, squeeze harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 30.0 * norm_pr * (1.0 - norm_pr);

    // Penalize dead space that is too small to be useful (below typical item sizes)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 25.0 * waste * waste;
        // Reward if post-residual can still host the lookahead item
        if pr >= nx {
            score -= 6.0 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins when residuals are high
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: penalize opening a bin mid-stream unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).abs() < 0.15;
        score += 12.0 * (1.0 - progress) + if tight { 8.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small residuals (dead space) are penalized; "perfect" fits rewarded.
    let r = post_residual as u32;
    let class = r % 10;
    if r == 0 {
        score -= 60.0; // perfect fill
    } else if r <= 5 {
        score += 25.0; // nearly dead space
    } else if r <= 10 {
        score += 8.0;
    } else {
        // fraction of capacity remaining as usable band
        let frac = r as f64 / bin_capacity as f64;
        if frac > 0.4 {
            score -= 12.0; // still roomy bin
        } else if frac > 0.2 {
            score -= 4.0;
        }
        // modulo-class bonus: residual divisible by common item sizes
        if r % 20 == 0 {
            score -= 10.0;
        } else if r % 25 == 0 {
            score -= 6.0;
        } else if class == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            // next item fits: reward tight chaining
            score -= 14.0 - slack * 0.25;
            if slack == 0.0 {
                score -= 20.0; // perfect chain
            }
        } else {
            // next item won't fit: residual becomes dead space for lookahead
            score += 10.0 + (next_item_size - r) as f64 * 0.3;
        }
    }

    // Last-chance bin before opening a new bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: prefer consolidating (tight fits) over spreading
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 0.15 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early stream: keep bins roomy; late stream: prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless residuals are all bad
    if bin_residual == bin_capacity {
        let mean_bad = mean_residual < 12.0;
        if !mean_bad {
            score += 30.0 + mean_residual * 0.2;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Pressure from many open bins: prefer using existing bins.
    score += open_bins_count as f64 * 0.8;

    // If the next item fits well in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0;
        if post_residual as u32 == next_item_size {
            score -= 10.0;
        }
    }

    // New empty bin candidate: penalize slightly so it's chosen only when
    // existing bins give bad fits.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.0; // tighter match to next item => lower score
    } else if next_item_size > 0 {
        // next item cannot fit here after placement: penalize dead space
        score += (next_item_size as f64) * 1.5;
    }

    // Relative residual vs mean residual: prefer filling below-average-residual bins
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin early in stream or when item is huge
        if item_size > 70 || (step_index as f64) / (total_items.max(1) as f64) < 0.05 {
            score -= 200.0;
        }
    }

    // Small penalty for leaving awkward small residuals (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    score -= (bin_capacity as f64 - post_residual as f64).powi(3) * 0.004;

    // Penalize creating small unusable dead space (post_residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - gap * 0.4;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty for wasting the lookahead chance.
        score += 5.0;
    }

    // Last chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + progress);
    score -= pressure * 0.8;

    // Penalize opening a new bin unless current fit is bad or residual is fragmented.
    if bin_residual == bin_capacity {
        let avg_fit = (mean_residual - item_size as f64).abs();
        // New bin is attractive only if existing bins have poor fits or few bins fit.
        if fitting_bins_count > 1 && mean_residual >= item_size as f64 {
            score += 35.0 + avg_fit * 0.5;
        } else if mean_residual < item_size as f64 {
            score -= 20.0; // no bin can hold it well -> open new bin
        }
        // Early stream: slightly prefer consolidating, later: allow spreading.
        score += progress * 10.0;
    }

    // Mild penalty for leaving residual far from common item sizes (multiples of 10).
    let mod10 = post_residual % 10;
    if mod10 != 0 {
        score += mod10 as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Quadratic dead-space penalty: small residuals are near-useless.
    let dead = pr / cap; // normalized post residual
    score += 30.0 * (1.0 - dead) * dead * dead * cap * 0.1;

    // Tight fit reward (cubic coupling of fill fraction and progress).
    let fill = (cap - pr) / cap;
    score -= 40.0 * fill * fill * fill * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 25.0 * (-gap / 20.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly prefer the only bin that can fit.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: mild penalty early, decreasing with progress,
    // so late in the stream we are more willing to open fresh bins
    // rather than fragment old ones.
    if bin_residual as f64 == cap {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
        // But if many bins are open and this is a tight item, opening is fine.
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (place into bins with less-than-average residual to consolidate).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // sizes (10,20,25,50) are reusable "harmonics"; odd/prime-ish residues are dead space.
    let r = post_residual;
    let harmonic = if r == 0 { 3.0 }
        else if r % 50 == 0 { 2.5 }
        else if r % 25 == 0 { 2.0 }
        else if r % 20 == 0 { 1.8 }
        else if r % 10 == 0 { 1.5 }
        else if r % 5 == 0 { 0.8 }
        else { 0.0 };
    score -= harmonic * 6.0;

    // Penalize small dead residues that no item can pair with.
    if r > 0 && r < 10 {
        score += 25.0;
    }
    // Sweet-spot residues (10..=30) are highly reusable.
    if r >= 10 && r <= 30 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let nr = r - next_item_size;
            score -= 8.0 + (nr as f64).min(30.0) * 0.3;
            if nr == 0 { score -= 15.0; }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or stream is early and we want spread capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (bin_residual - item_size) as f64;
        score = 60.0 - 30.0 * progress + bad_fit * 0.5
            - if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        // Prefer new bin when open bins are crowded.
        score -= (mean_residual - 50.0) * 0.2;
    }

    // Mild tie-break: prefer fuller bins (lower residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Prefer keeping number of open bins low early on.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(bin_residual)) {
        // gap too small even for the next item -> dead space
        score += 30.0 + post_residual as f64;
    }
    // Classic small-gap zone (unusable for typical items)
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; gap likely wasted
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty grows with open bins and mean residual space
        score += 60.0 + 8.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // but if item is large and would leave big gap elsewhere, new bin is fine
        if item_size >= 50 {
            score -= 30.0;
        }
    } else {
        // using an existing bin relieves pressure slightly
        score -= 0.3 * open_bins_count as f64;
        // prefer bins with less residual (best-fit style) via mean comparison
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: strongly reward bins where the NEXT item fits the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: chain placement is great.
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 + slack_after_next as f64 * 0.5;
        } else {
            // Next item won't fit here: penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving dead space that nothing (min size 1..10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // More open bins => prefer reusing one of them.
        score += open_bins_count as f64 * 2.0;
        // If this is a last-chance situation, opening a bin is less bad.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize small post-residuals that are still too large to be "dead" but too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly perfect fit, slight bonus actually
        score -= 20.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; mild penalty scaled by how much it overflows
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / 100.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // But if many open bins are fragmented (high mean residual spread), a fresh bin is fine.
        let frag = (mean_residual - post_residual as f64).abs();
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If item is large relative to capacity, fresh bin avoids fragmentation.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        let _ = frag;
    }

    // Prefer bins with below-average residual (consolidate fullness).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild penalty for proliferating open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * x * x) + 20.0 * x * x * x;

    // Stream-progress coupling: as stream advances, tolerate dead space less
    let p = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += pr * 0.6 * p * x;

    // Last-chance bin: strongly reward using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (pr - n) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Crowd effect: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln1p();
    score -= 5.0 * crowd * (1.0 - x);

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * x;
    }

    // Mean residual alignment: prefer bins close to the mean residual
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit classes (residual divisible by
    // small harmonics) are more likely to be filled by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit is ideal
    } else {
        // harmonic divisibility ladder
        let mut div_bonus = 0.0;
        if pr % 10 == 0 { div_bonus += 40.0; }
        if pr % 20 == 0 { div_bonus += 30.0; }
        if pr % 25 == 0 { div_bonus += 25.0; }
        if pr % 50 == 0 { div_bonus += 35.0; }
        score -= div_bonus;

        // dead-space penalty for tiny unusable residuals
        if pr < 10 {
            score += 120.0;
        } else if pr < 20 {
            score += 40.0;
        }

        // lookahead coupling: if next item fits exactly in the post residual,
        // strongly reward this bin
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                let pair_waste = pr - next_item_size;
                score -= 60.0_f64.max(0.0);
                score += pair_waste as f64 * 0.8;
                // harmonic class of the pair
                if pair_waste % 10 == 0 { score -= 25.0; }
            } else {
                // next item cannot follow here; penalize slightly if this bin
                // would then be stranded
                score += 15.0;
            }
        } else {
            // last item: prefer minimal residual
            score += (pr as f64) * 0.5;
        }
    }

    // last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // new-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - 0.3 * progress);
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 30.0; // new bin can host current + next
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin
        }
    }

    // mild preference for tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // discourage scattering across many open bins when residuals are large
    if open_bins_count > 3 && bin_residual >= item_size * 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (1..=100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by post_residual being tiny, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (better packing)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, prefer closing bins tightly (less waste to carry)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after that hypothetical placement
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.5;
            score -= 50.0; // mild bonus for keeping chain alive
        } else {
            // next item won't fit here: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin bonus: avoid opening new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize tiny dead space (< 10 unusable) unless perfect fit
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.1 * (1.0 - progress);

    // New-bin candidate: only attractive when current bin would leave bad leftover
    if bin_residual == bin_capacity {
        // neutral-ish baseline; discourage early opening
        score += 50.0 + 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.9;
        } else {
            score -= 3.0; // bin stays usable for next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when it truly helps.
    if bin_residual == bin_capacity {
        // Base mild penalty so existing reasonable fits win.
        score += 8.0;
        // But if the item is large and fits poorly anywhere, opening is fine.
        if item_size >= 60 {
            score -= 10.0;
        }
        // When many bins are open and fragmented, prefer consolidating into
        // an existing bin rather than adding another.
        score += open_bins_count as f64 * 1.2;
        // Late in the stream, avoid opening new bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
        // If the mean residual across open bins is small, open bins are tight;
        // a fresh bin may be warranted.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Prefer bins with residual close to item size (minimize waste).
        let waste = (bin_residual - item_size) as f64;
        score += 0.15 * waste;
        // Slightly prefer bins below the mean residual (fill tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post_residual, with smooth polynomial coupling to stream progress.
    // Later in the stream, leftover space is more costly (less chance to fill it).
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Non-linear penalty for awkward residuals: residuals near the middle
    // of the capacity are the most reusable; extremes (0 or near cap) are fine.
    let r = pr / cap;
    let mid = (r - 0.5).abs();
    score += 12.0 * (1.0 - 4.0 * mid * mid).max(0.0) * (0.5 + 0.5 * progress);

    // Perfect fits and tight fits are strongly rewarded (subtracted).
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0 * (11.0 - pr as f64) / 10.0;
    }

    // Last-chance bin: penalize opening new bins when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Slight preference for bins with smaller residual relative to mean (tighter packing).
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: mild baseline so it loses to good fits but wins over bad ones.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and capacity-fraction bands
    let frac = post_residual as f64 / bin_capacity as f64;
    let residue = post_residual % 10;

    // Penalize small unusable slivers (< 10) heavily; reward exact fills
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 40.0;
    } else {
        // dead-space penalty scaled by harmonic class: residues 1..3 are worst
        score += match residue {
            0 => -4.0,
            1 | 2 | 3 => 12.0,
            4 | 5 | 6 => 4.0,
            _ => 0.0,
        };
        // Reward large post_residual bands (room for future items)
        if frac > 0.5 { score -= 8.0; }
        else if frac > 0.3 { score -= 2.0; }
        else if frac < 0.15 { score += 10.0; }
    }

    // Lookahead coupling: integer division of post_residual by next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits = post_residual / next_item_size;
        score -= (fits.min(3) as f64) * 6.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Progress-aware: tighter bins preferred later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small unusable gaps proportionally.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space relative to known future demand
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default is acceptable; open a fresh bin only when
    // existing bins would create bad dead space or the item fits poorly.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual = capacity - item_size.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if post_residual >= 30 {
            score -= 5.0; // fresh bin leaves a usable large gap
        }
    }

    // Mild drift: later in the stream, prefer tighter packing of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // leftover after a hypothetical next placement
            let two_step_left = post_residual - next_item_size;
            score -= 60.0 - (two_step_left as f64).min(60.0);
        } else {
            // next item can't follow here; penalize small unusable post_residual
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a nearly-empty bin on a tiny item
    if item_size < bin_capacity / 4 && post_residual > bin_capacity / 2 {
        score += 40.0;
    }

    // Mild penalty for opening new bins when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
    }

    // Early stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 * (-tightness).exp();

    // Penalize dead space that is too small to be useful later (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste; mild reward scaled by fit quality
            let nl = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-nl / 20.0).exp();
        } else {
            // next item will NOT fit here; penalize wasting space it can't use
            score += 6.0 * ((next_item_size - post_residual) as f64 / 40.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (fragmented) or we are early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins when open bins are already fairly empty on average
        score += 15.0 + 0.15 * mean_residual;
        // Slight discount early in the stream (hoarding capacity can help)
        score -= 10.0 * (1.0 - progress);
        // If many bins are open, discourage spreading further
        score += 0.3 * open_bins_count as f64;
    } else {
        // Favor filling already-open bins, more so when many bins are open
        score -= 0.2 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (above-mean residual
    // bins are more flexible; below-mean bins should be drained first).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild time-horizon shaping: late in the stream, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted residual, scaled by progress (waste matters more later)
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear polynomial coupling of normalized residual with progress
    let coupling = x * x * (1.0 - progress) + x * x * x * progress;
    score += 80.0 * coupling;

    // Reward tight fits (small x) with a smooth bowl
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Lookahead: if next item fits exactly in post residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / cap;
        score -= 30.0 * (1.0 - (fill - 0.5) * (fill - 0.5) * 4.0).max(0.0);
    }
    // Penalize if next item won't fit and residual becomes dead space
    else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0 * x * progress;
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline, cheaper early
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.6 * progress) - 10.0 * (1.0 - progress);
    }

    // Mild diversity pressure via mean residual
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes are near-perfectly packed; reward them strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual in the lowest eighth of capacity is a
    // "dead class" but small enough to be acceptable; classify via integer division.
    let residue_class = post_residual / (bin_capacity / 8); // 0..=8 classes
    score -= (8 - residue_class as f64) * 6.0; // smaller class (tighter fit) -> lower score

    // Modulo-10 harmonic: leftovers divisible by 10 pair well with typical sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or tightly,
    // this bin stays productive; reward that.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0;
            } else if gap <= 10 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - gap as f64 / cap);
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large stranded space.
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): only attractive when the current item is large
    // and would leave a big awkward residue in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Large items pair naturally with a fresh bin.
        if item_size >= bin_capacity / 2 {
            score -= 55.0;
        }
        // If existing bins are crowded (low mean residual), a new bin is fine.
        if mean_residual < cap * 0.25 && open_bins_count > 0 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Mild preference for using bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 15.0 * fill_ratio;

    // Penalize leaving residues that no plausible item (min size 10) can use,
    // i.e. dead space in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tie-break noise-free deterministic harmonic wobble.
    let wobble = ((post_residual as i64 * 31 + item_size as i64 * 17) % 7) as f64;
    score += 0.5 * wobble;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (item sizes 1..=100, so gaps < ~small threshold are "dead").
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: unusable sliver, penalize heavily.
        score += 35.0 + (10.0 - pr) * 4.0;
    } else if post_residual < 20 {
        // Marginal gap: only valuable if the lookahead item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 10.0 + (20.0 - pr) * 1.5;
        }
    } else {
        // Usable residual: mild preference for larger leftovers, but
        // reward if the next item fits well into the post space.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (post_residual as f64 - next_item_size as f64) * 0.3;
        }
        score += pr * 0.15;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; favor consolidating into already-open ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; allow opening
        // only when it escapes a large dead-space penalty above.
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.4;
    }

    // Mild tie-break toward bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item can't fit here; penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize new empty bin slightly, unless residuals elsewhere are poor
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Prefer bins with residual below mean (tighter bins get filled)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize leaving residual that next item can't use;
    // reward residual that next item exactly or nearly fills.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 12.0 / (1.0 + gap as f64);
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many open bins exist with slack.
    if bin_residual == bin_capacity {
        let slack = mean_residual / (bin_capacity as f64);
        score += 15.0 * (1.0 - slack);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score += 8.0; // big item coming, keep fresh-bin option valuable? penalize less
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Penalize wasting large residuals in existing bins on tiny items.
        let waste = (post_residual as f64) - (item_size as f64);
        if item_size < 20 && post_residual > 40 {
            score += 10.0;
        }
        let _ = waste;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 0.8 * progress) + 2.5 * base * base * (1.0 - progress);

    // Reward tight fits (near-zero post residual), smoothly
    let tight = 1.0 - base;
    score -= 1.5 * tight * tight * tight;

    // Lookahead: penalize residual that cannot hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let waste = (pr - nx) / cap;
            score += 0.4 * waste * waste;
        } else {
            score += 0.6 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Mild penalty for opening a new bin when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 1.2 + 0.3 * (open_bins_count as f64).sqrt() + 0.5 * (mean_residual / cap);
        // But discount new-bin penalty late in the stream when residual fragmentation is high
        score -= 0.8 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact small remainders are ideal.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else {
        // dead-space penalty grows superlinearly for large leftovers
        score += (pr as f64) * (pr as f64) / 40.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with items drawn in decade sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or with tiny remainder -> strong reward
            let nxt = next_item_size as f64;
            let gap = (pr - next_item_size) as f64;
            score -= 25.0 - gap * 0.5;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 10.0; // harmonic divisibility bonus
            }
        } else {
            // next item won't fit here anyway; mild penalty scaled by waste
            let overflow = (next_item_size - pr) as f64;
            score += overflow * 0.15;
        }
    } else {
        // last item: prefer tightest fill
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; accept only if existing fits are bad.
        score = cap * 0.9;
        // If item is large and would leave a harmonic (multiple of 10) residual
        // in a fresh bin, opening a new bin is more attractive.
        let new_pr = bin_capacity - item_size;
        if new_pr % 10 == 0 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size <= new_pr {
            score -= 10.0;
        }
        // Late in the stream, prefer reusing open bins more strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Mild bonus for bins below mean residual (rebalancing toward fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    } else {
        // Reward tight fits proportionally: less residual than mean is good.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.3;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse if it can't fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: keep it slightly unattractive unless residuals elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.1;
    }

    // Late in stream, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item exactly fills this bin afterwards
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer leaving just enough room for the next item
            score -= (next_item_size as f64) * 0.5 - slack * 0.15;
            if slack <= 10.0 {
                score -= 15.0; // near-perfect 2-step fit
            }
        } else {
            // next item cannot follow into this bin: penalize proportional gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // last item: prefer tightest fit only
        score -= 10.0;
    }

    // Reward tight fits relative to current bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Compare against mean residual: bins with less residual than average are
    // better candidates (they are already "small" bins, consolidate them).
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += rel * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins, but allow it when no open bin fits well
    // (large dead space would be created) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead = (bin_capacity - item_size) as f64;
        // new bin is attractive only if item is large (little dead space)
        score += 35.0 - dead * 0.4 + progress * 10.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0; // new bin can also host the next item
        }
    }

    // Mild penalty for creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Tie-break: prefer bins with fewer siblings? Prefer consolidating into
    // crowded states to keep open bin count low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < item_size.min(40) {
        score += (post_residual as f64) * 0.15;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    }
    // If next item would NOT fit after this placement, but would fit the current residual,
    // mild penalty for consuming the space the next item needs.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 8.0;
    }

    // Time horizon: early in the stream, be more conservative with tight fits;
    // late in the stream, exploit compaction more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Global state coupling: many open bins with high mean residual -> discourage new-bin opening;
    // when mean residual is low (bins are nearly full), slightly favor opening fresh bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap;

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly so we only open when existing bins are truly bad,
        // but relax this penalty when many bins are open and mean residual is small.
        let new_bin_penalty = 20.0 - 2.0 * (open_bins_count.min(20) as f64) - 0.1 * mean_residual;
        score += new_bin_penalty.max(-5.0);
    }

    // Prefer placing large items into fuller bins (best-fit flavor weighted by item size).
    score += 0.05 * item_size as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress:
    // later in the stream, waste is punished more (convex penalty).
    let waste_penalty = x * x * (0.5 + progress) * cap;
    score += 0.35 * waste_penalty;

    // Reward tight fits with a smooth saturating term (subtract).
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize leaving residual that is too small for the next item but nonzero
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += 8.0 * (nxt - pr) / nxt * (0.5 + progress);
        } else if pr >= nxt {
            // smooth reward for accommodating the lookahead item
            score -= 6.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: prefer using the only bin that fits rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild pressure against proliferating open bins, smooth in count and mean residual.
    let mb = open_bins_count as f64;
    score += 0.05 * mb * (mean_residual / cap).ln().max(0.0);

    // New-bin candidate: make it mildly unattractive unless item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 6.0 + 10.0 * (1.0 - large_item) * (1.0 - progress);
        // allow new bin when item is big relative to mean residual
        score -= 8.0 * large_item * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by common item sizes are reusable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty for small unusable residuals (below typical min item size ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward residuals in "harmonic" classes: multiples of 10, 20, 25, 50 are more reusable
    let mut harmonic_bonus = 0.0;
    if post_residual % 10 == 0 { harmonic_bonus += 8.0; }
    if post_residual % 20 == 0 { harmonic_bonus += 6.0; }
    if post_residual % 25 == 0 { harmonic_bonus += 6.0; }
    if post_residual % 50 == 0 { harmonic_bonus += 8.0; }
    score -= harmonic_bonus;

    // Penalize residuals in awkward classes (prime-ish / odd small residues)
    if post_residual % 2 == 1 && post_residual < 30 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // reward proportional closeness of next item to post_residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / cap);
            // harmonic match between next item and residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted fraction
            score += 10.0 * (pr / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening new bin is only attractive when existing fit is terrible
    if bin_residual == bin_capacity {
        // neutral base; make new bin slightly unattractive unless residuals are fragmented
        score += 25.0;
        if mean_residual < 20.0 && open_bins_count > 0 {
            // open bins are nearly full / fragmented: new bin becomes attractive
            score -= 60.0;
        }
        if post_residual as f64 > mean_residual + 40.0 {
            score -= 20.0;
        }
    } else {
        // Favor tighter fits relative to mean residual of open bins
        if pr < mean_residual {
            score -= 12.0;
        } else {
            score += 6.0 * ((pr - mean_residual) / cap);
        }
    }

    // Stream progression: late in stream, be greedier (minimize residual), avoid new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - pr / cap);
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    // Many open bins: prefer filling existing ones to consolidate
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).log2() * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 {
        score -= 60.0; // perfect (or near-perfect) fill: strongly reward
    } else if post_residual < 20 {
        // Small gap: usable only by tiny items; penalize relative to next item fit.
        if (next_item_size as u32) <= post_residual && next_item_size > 0 {
            score -= 15.0;
        } else {
            score += 25.0; // dead space penalty
        }
    } else if post_residual < 35 {
        if (next_item_size as u32) <= post_residual && next_item_size > 0 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with open bin pressure.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // If no open bin can fit the item, new bin is necessary (others got high scores anyway).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidating smaller gaps).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where next item fits exactly in the new residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer chains that leave small leftovers after two placements
            score -= 100.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // Penalize if next item would leave a tiny awkward remainder
            if next_post > 0 && next_post < 10 {
                score += 30.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean residual adjustment: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless the item is large relative to capacity
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 0.2 * item_size as f64 + 10.0 * progress;
        // Opening a new bin is fine if next item matches the fresh residual well
        if next_item_size > 0 && (bin_capacity - item_size).abs_diff(next_item_size) <= 5 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = post / (item_size as f64 + 1.0);
    score -= 8.0 / (1.0 + tightness);

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let leftover = post_residual - next_item_size;
        score -= 12.0 / (1.0 + leftover as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize dead space it can't use
        score += (next_item_size as f64) * 0.08;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Time horizon: early in stream, be conservative with open bins;
    // late in stream, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln();

    // New-bin candidate handling: empty bin should lose unless current fit is poor
    if bin_residual == bin_capacity {
        // baseline penalty; tight fits elsewhere beat it
        score += 5.0;
        // but if this bin would be nearly perfectly used by item + lookahead, allow it
        if post_residual == 0 || (next_item_size > 0 && (next_item_size as u32) == post_residual) {
            score -= 20.0;
        }
        // late in stream, prefer closing out by packing tightly
        score -= progress * 1.5;
    }

    // Global residual balance: prefer bins below mean residual (filling emptier bins)
    score += (post - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 12.0 * coupling;

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nl = next_item_size as f64;
        if pr < nl {
            score += 8.0 * (1.0 - pr / nl) * (0.5 + progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nl) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: smooth penalty that relaxes as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (harmonic weighting: smaller post_residual counts more).
    if post_residual > 0 {
        score -= 60.0 / (post_residual as f64).powf(0.6);
    } else {
        // Perfect fill: extremely desirable.
        score -= 150.0;
    }

    // Harmonic class of post_residual: dead space smaller than the minimum
    // item (1) is impossible here, but small unusable gaps (post_residual < 10)
    // are dead space; penalize modulo classes that leave awkward gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    }

    // Modulo-10 harmonic class: gaps that are multiples of 10 tend to be reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 100.0; // chains a perfect fill
        } else {
            score -= 40.0 / (slack as f64).powf(0.5);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap it almost fits.
        if next_item_size - post_residual <= 5 {
            score += 20.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by stream progress and open bins.
        score += 30.0
            + 0.15 * (open_bins_count as f64)
            + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // If item is large relative to capacity, opening fresh is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // If next item is large too, a fresh bin may pair them.
        if next_item_size > bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 45.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += 0.08 * (mean_residual - bin_residual as f64).abs();

    // Integer-division threshold: bins whose residual is in a "high" band get preference
    // for large items (large items should go into large residual bins).
    let residual_band = bin_residual / (bin_capacity / 4);
    if item_size > bin_capacity / 2 && residual_band >= 1 {
        score -= 10.0 * residual_band as f64;
    }

    // Prefer filling nearly-full bins to close them out.
    if bin_residual <= bin_capacity / 4 && bin_residual >= item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 {
        score += 40.0; // gap too small for any item (sizes >= 1... treat <10 as risky)
    } else if post_residual <= 15 {
        score += 15.0;
    } else if post_residual <= 25 {
        score += 5.0;
    } else {
        // Larger leftover space is still usable; mild reward
        score -= 2.0;
    }

    // Reward bins whose residual can still fit the next item (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item then leaves another usable gap
        let next_post = post_residual - next_item_size;
        if next_post >= 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // This bin becomes dead after next item arrives anyway
        score += 3.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure;

    // Relative fill quality: reward bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by pressure and progress
        score += 25.0 + pressure * 2.0;
        // Late in the stream, opening bins is even worse (wasted capacity)
        score += 20.0 * progress;
        // But if the only alternative is a horrible fit, allow it: the
        // dead-space penalties above already raised open-bin scores.
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item size (perfect chain), penalize large leftovers
    // that the next item cannot use.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        // Perfect match bonus
        if diff < 0.5 {
            score -= 30.0 + 0.5 * nr;
        } else {
            // Mismatch penalty grows with how "wasted" the leftover is
            score += 0.8 * diff;
            // If next item cannot fit at all, leftover is dead space
            if pr < nr {
                score += 10.0 + (nr - pr) * 0.6;
            }
        }
        // If next item fits snugly too (post_residual >= next, small slack), mild bonus
        if pr >= nr && pr - nr <= 10.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the average residual (good fits first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Penalize opening a brand-new bin unless the current bin would leave
    // a very awkward residual (near-full bins are great, don't open new).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins are mostly full
        // or the item leaves a large unusable gap everywhere.
        score += 15.0;
        if post_residual as f64 <= 0.3 * bin_capacity as f64 {
            score -= 20.0; // tight fit in a fresh bin is fine
        }
        // Late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for filling bins as full as possible.
    score += 0.2 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit the smallest plausible item (1..100 unknown dist).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // near-useless sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit or mean residuals are badly fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened when bins are scarce/fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if mean_residual > 0.0 { 1.0 - (mean_residual / bin_capacity as f64) } else { 0.0 };
        score += 15.0 - 8.0 * fragmentation - 5.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer filling bins that are already relatively empty when many bins are open.
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score += (open_bins_count as f64).ln().max(0.0) * residual_ratio * 0.8;

    // Mild global pressure: as stream progresses, discourage leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * residual_ratio;

    // Distance of post_residual from mean residual: prefer bins near the pack's typical state.
    score += 0.5 * (post_residual as f64 - mean_residual).abs().sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste shaping: small residuals are disproportionately bad
    let tightness = 1.0 - (post / cap); // 1.0 = perfect fit
    score -= 3.0 * tightness * tightness * cap * 0.1;

    // Smooth interaction of waste with stream progress: later, prefer tighter fills
    score += 2.0 * post * (0.5 + 0.5 * progress) * 0.5;

    // Lookahead coupling: reward leaving space usable by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 1.5 * (1.0 - gap / cap) * 2.0;
        if post >= nxt && post - nxt < nxt {
            score -= 2.0; // next item fits snugly here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize scattering across many open bins mildly
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Prefer bins with residuals close to the mean (keeps balance)
    score += ((post - mean_residual) / cap).abs() * 1.2;

    // New-bin candidate: make it unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
        if post < 10.0 {
            score -= 3.0; // item nearly fills a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (divisible by common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 6.0; }
        else if pr % 5 == 0 { class_bonus += 3.0; }
        if pr % 20 == 0 { class_bonus += 3.0; }
        if pr % 25 == 0 { class_bonus += 2.5; }
        if pr % 50 == 0 { class_bonus += 3.0; }
        score -= class_bonus;

        // Dead-space penalty: leftover too small for the smallest plausible item
        if pr < 10 && pr > 0 {
            score += 25.0;
        }
        // Harmonic dead zone: leftover in awkward mid-range classes
        if pr >= 11 && pr <= 14 { score += 4.0; }
        if pr >= 16 && pr <= 19 { score += 2.0; }
    } else {
        // Perfect fit: heavily reward
        score -= 40.0;
    }

    // Tight-fit reward: item fills a large fraction of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: does post_residual still admit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward leaving room for the lookahead item, scaled by how snugly it fits
            let snug = next_item_size as f64 / pr as f64;
            score -= 8.0 * snug;
            // Harmonic match: next item divides remaining space cleanly
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Penalize stranding the lookahead item
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // With many options, prefer tighter bins (already encoded) plus mild spread penalty
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it
    // wins only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - (post_residual as f64);
        // Early in the stream, opening bins is cheap; late, discourage it
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
        // Don't open a new bin when this bin is the only fitting one
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that could fit the lookahead item exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            score -= 6.0 * (1.0 - (pr - nr) / bin_capacity as f64);
        } else if pr > 0.0 {
            score += 4.0 * (nr - pr); // wasted potential vs lookahead
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += pressure * 0.5;

    // Prefer bins tighter than the mean residual (better packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for filling fuller bins.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    score = (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Strong reward if the next item exactly fills the post-residual (2-step lookahead).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect 2-chain
        } else if diff > 0 && (diff as u32) <= 20 {
            score -= 25.0 - (diff as f64) * 0.8; // next item likely fits
        } else if diff < 0 {
            score += (diff.abs() as f64) * 0.35; // next item won't fit here
        }

        // Reward residual that is at least usable by the next item.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Compare against mean residual: bins with residual close to item size are precious.
    let tightness = bin_residual as f64 - item_size as f64;
    if tightness <= mean_residual {
        score -= 6.0; // this bin is tighter than average -> use it
    } else {
        score += (tightness - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Slight penalty when many bins compete, prefer the best fit among them.
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Penalize opening a new bin when decent open options exist,
    // but allow it when open bins are all very full (small residuals).
    if bin_residual == bin_capacity {
        let avg_open = mean_residual;
        if avg_open > item_size as f64 + 15.0 {
            score += 40.0; // open bins still have room; don't open new
        } else {
            score -= 5.0; // open bins nearly exhausted; new bin is fine
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (open_bins_count as f64).sqrt().recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable residuals (dead space below the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (favor tight fits);
    // later, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (item_size as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage filling existing slack.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        if fitting_bins_count > 0 && next_item_size > 0 && item_size >= next_item_size {
            score += 10.0; // don't waste a fresh bin on a big item when others fit
        }
    } else {
        score -= 0.02 * mean_residual;
    }

    // Prefer placing larger items into fuller bins (best-fit flavor weighted by item size).
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: residual waste, with progress-dependent penalty on dead space.
    let mut score = pr * (1.0 + 0.9 * progress * norm_pr);

    // Smooth polynomial coupling: quadratic term rewarding tight fits more as stream advances.
    let tight = 1.0 - norm_pr;
    score -= cap * (0.35 + 0.55 * progress) * tight * tight;

    // Reward filling a bin completely (post_residual near zero), smoothly.
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize opening new bins when many bins are open and mean residual is large.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (30.0 + 40.0 * open_pressure / (open_pressure + 5.0)) * (0.4 + 0.6 * (1.0 - progress));

    // Lookahead: penalize leaving residual incompatible with next item unless it's near-perfect.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fit_next = (pr >= nx) as i32 as f64;
        score += fit_next * 0.25 * gap;
        score -= fit_next * 8.0 * (-gap * 0.15).exp();
        // If bin cannot fit next item, mild penalty grows with leftover dead space.
        score += (1.0 - fit_next) * 0.35 * pr * (0.5 + 0.5 * progress);
    }

    // Smooth interaction: prefer balancing residual against mean residual of open bins.
    score += 0.08 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer-division thresholds: post_residual classes (dead-space buckets)
    let class = post_residual / 10; // 0..10 harmonic class
    score -= (class as f64) * 0.8; // reward larger leftover classes slightly

    // Modulo arithmetic on post_residual: multiples of common item sizes fit next items
    if post_residual >= 10 {
        let mod10 = post_residual % 10;
        // leftover close to a "round" value (mod 10 == 0) is more reusable
        score -= (10 - mod10) as f64 * 0.15;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 12.0 - (slack as f64) * 0.5; // exact/near-exact fits rewarded
        // harmonic match: next item in same modulo class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportional to wasted potential
        score += (next_item_size as f64) * 0.25;
    }

    // Fractional capacity coupling: penalize residuals in awkward middle band (30..60)
    if frac > 0.3 && frac < 0.6 {
        score += 4.0;
    }
    // Very small residuals are near-perfect fills
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, but allow if open bins are congested
    if bin_residual == bin_capacity {
        score += 18.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / 20.0;
        score -= congestion * 10.0 * (0.5 + progress);
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight reward for tight fits overall
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1) are impossible,
    // but gaps too small for typical items are near-waste. Penalize the "unusable zone".
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
