    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // disfavor the fresh-bin candidate.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 10.0 + open_pressure * 2.0;
        // But if the next item is large and current bins are fragmented, opening
        // a fresh bin may be wise: reduce the penalty a bit.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Existing bin: mild reward proportional to how full it already is.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 10.0;
    }

    // Coupling with mean residual: if this bin's post-residual is far below the mean,
    // it is a good consolidation; penalize deviations above the mean.
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += (post_residual as f64 - mean_post) * 0.5;
    } else {
        score -= (mean_post - post_residual as f64).min(10.0) * 0.3;
    }

    // Lookahead: if the next item exactly fits the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact/near-exact fit reward (aggressive dead-space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 500.0; // perfect chain: this bin will be exactly filled next step
        } else if post_residual as u32 >= next_item_size {
            let gap = post_residual as f64 - next;
            score -= 80.0 * (1.0 - gap / bin_capacity as f64); // next item still fits
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 25.0 * (next - post_residual as f64) / 100.0;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 120.0 * fill_ratio; // fresh bin for big items
        if item_size <= 30 {
            score += 100.0; // discourage wasting a new bin on tiny items
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size as f64 <= bin_capacity as f64 {
            score -= 30.0; // pairing large consecutive items in a fresh bin
        }
    }

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 40.0 * progress;
    }

    // Many open bins: prefer filling existing ones over opening more
    score -= 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness).powi(6);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 6.0;
    } else if post_residual < next_item_size.max(1) as f64 {
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Lookahead: reward bins whose post residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            let slack = (post_residual - next_item_size as f64) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Global pressure: many open bins -> consolidate; few open bins -> spread.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if pressure > 5.0 {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual == 0;
        let t = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = mean_residual < item_size as f64 * 0.5;
        if good_fit_exists && t > 0.05 {
            score += 40.0; // discourage opening when a real fit exists
        } else if poor_alternatives {
            score -= 8.0 * (1.0 - t); // early stream: fresh bins fine
        } else {
            score += 12.0;
        }
    }

    // Mild time horizon adaptation: later in stream, favor consolidation more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * t * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighten fits more aggressively (dead space costs more)
    let progress_coupling = pr_norm * progress * (3.0 - 2.0 * progress);
    score += progress_coupling * 8.0;

    // Lookahead: reward leaving space that can still fit the next item,
    // penalize residual that is "almost but not quite" usable for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).sqrt() * 0.05;

    // Prefer bins whose residual deviates from the mean toward smaller residual
    score += 0.5 * (mean_residual - bin_residual as f64).abs() / cap;

    // New-bin candidate: penalize opening a new bin early, allow it late
    // or when the fit would leave large dead space
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress) + 3.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 bands.
    let pr = post_residual;
    let harmonic_class = (pr % 10) as f64;

    // Penalize residuals that are small but not tiny ("dead space" band 1..=9).
    if pr > 0 && pr < 10 {
        score += 25.0 - harmonic_class * 2.0; // dead space penalty, softer for pr=9
    } else if pr == 0 {
        score -= 40.0; // perfect closure reward
    } else if pr <= 20 {
        // Residuals 10..20 are "next-item friendly" if next item fits class
        if next_item_size > 0 && next_item_size <= pr {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Integer division thresholds: residual / 10 bucket coupling with next item.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // lookahead fits: reward tight coupling
            let slack_after_next = pr - nxt;
            score -= 12.0 + (slack_after_next as f64) * 0.15;
            if slack_after_next % 10 == 0 {
                score -= 6.0; // harmonic alignment after two placements
            }
        } else {
            // next item won't fit here; penalize more if this bin was the only option
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; reduced when open bins are crowded.
        let crowd = open_bins_count as f64;
        let mean_fit = if next_item_size > 0 { mean_residual } else { mean_residual };
        score = cap * 0.85
            - (crowd.ln().max(0.0)) * 3.0
            - if mean_fit < 20.0 { 15.0 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Fraction-of-capacity coupling: prefer filling large fractions of capacity.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 10.0;

    // Mean residual repulsion: avoid bins far from the mean (fragmentation control).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo-16 class on item size: align large items with large residuals.
    if item_size % 16 == 0 && post_residual % 16 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize residuals too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward a fit that leaves room for the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading and
    // prefer filling existing bins; opening new bins becomes less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 10.0 + 6.0 * pressure;
        // But if this is the only bin that can fit the item, opening a new
        // bin is actually reasonable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward choosing it, especially when it's scarce.
        score -= 3.0 + 2.0 * pressure;
    }

    // Last-chance bonus: if this is the only fitting open bin, avoid
    // forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items;
    // late in the stream, squeeze everything into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mean-residual coupling: if open bins are on average quite full,
    // filling this one further is valuable.
    if bin_residual != bin_capacity && (mean_residual - post_residual as f64) > 0.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward when post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good: next item can go here; the closer post_residual is to next_item_size, the better
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * slack;
            if post_residual == next_item_size {
                score -= 200.0; // chained perfect fit
            }
        } else {
            // bad: next item won't fit here; penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * miss;
        }
    }

    // Compare against mean residual: prefer bins already below-average residual (consolidation)
    let dev = (post_residual as f64) - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // if nothing fits well elsewhere, opening fresh is fine
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        // early stream: opening bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 50.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Lookahead: if the next item cannot fit into post_residual, penalize
    // leftover dead space, unless post_residual is already tiny (waste anyway).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // dead space for the lookahead item
            score += 6.0 * (1.0 - nxt / bin_capacity as f64);
            if post_residual <= 5 {
                score -= 4.0; // nearly perfect fill, dead space is negligible
            }
        } else {
            // next item fits: reward leaving exactly-compatible space
            let slack = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual => encourage consolidation
    // into existing space rather than fragmenting.
    if open_bins_count > 2 {
        let consolidation = mean_residual / bin_capacity as f64;
        score -= 5.0 * consolidation * (open_bins_count.min(20) as f64 / 20.0);
    }

    // Early in the stream: keep bins flexible (prefer larger post_residual);
    // late in the stream: pack aggressively (prefer smaller post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize moderately so it is only chosen when all
    // open bins would create large unusable residuals.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // Late in the stream, opening a fresh bin is cheaper (fewer items left
        // to fragment it), so reduce the penalty.
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: waste after placement, scaled non-linearly (quadratic + cubic dampening)
    let mut score = pr * (1.0 + 0.8 * (pr / cap)) - 0.5 * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits: smooth exponential decay of residual
    score -= 30.0 * (-pr / 15.0).exp();

    // Penalize residuals that can't fit plausible future items (non-linear coupling with progress)
    let next_fit = if next_item_size > 0 { (pr - next_item_size as f64).max(0.0) } else { pr };
    score += 0.15 * next_fit * next_fit / cap * (1.0 + progress);

    // Exact-fit bonus
    if post_residual == 0 { score -= 50.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins are already roomy
    if bin_residual == bin_capacity {
        let roominess = (mean_residual / cap).max(0.0);
        score += 40.0 + 30.0 * roominess * (1.0 - 0.5 * progress) + 10.0 * (1.0 - progress);
    }

    // Smooth stream-progress coupling: early on tolerate waste slightly (build diverse bins),
    // late on minimize waste aggressively
    score *= 1.0 - 0.3 * progress * (pr / cap);

    // Slight penalty proportional to number of open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "waste classes".
    let r = (post_residual % 10) as f64;
    // Residue 0 (perfect multiple of 10) is the most valuable residual; penalize others.
    score += r * 0.35;
    if r == 0.0 {
        score -= 4.0; // reward landing exactly on a decade boundary
    }

    // Integer-division thresholds on post_residual: small leftovers are dead space.
    if post_residual <= 10 {
        score += 6.0; // nearly-full bin is fine, but tiny slivers are wasted
        score -= 3.0; // but closing a bin is good; net small bonus
    } else if post_residual <= 20 {
        score += 2.5;
    } else if post_residual > 50 {
        score += 1.0; // half-empty bin kept open: mild penalty
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 + slack * 0.02;
            if (next_item_size + post_residual) % 10 == 0 {
                score -= 2.0; // chain lands on decade boundary again
            }
        } else {
            // Next item cannot follow: penalize more if gap is small (teasing waste).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is bad.
    if bin_residual == bin_capacity {
        // Base neutral score: slightly worse than a good fit, better than awful ones.
        score = 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // With lookahead, opening a bin sized for the next pair can pay off.
            if item_size + next_item_size > bin_capacity {
                score -= 5.0; // item + next won't share anyway; fresh bin is fine
            }
        }
        if post_residual == 0 { score = 55.0; } // unreachable, keep signature-safe
    }

    // Late-stream pressure: consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;
    // Many open bins: encourage filling existing ones rather than spreading.
    score += (open_bins_count as f64) * 0.05;

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // leftover bin; filling it is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        let dead = post_residual < 10;
        if dead {
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else {
            // Larger gaps are less wasteful; mild superlinear penalty.
            score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) / (bin_capacity as f64) * 5.0;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmented bin).
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    // New-bin candidate: only attractive when current fit is bad and few bins open.
    if bin_residual == bin_capacity {
        score = 20.0 + (open_bins_count as f64) * 2.0;
        if post_residual >= 10 {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

