            score -= 450.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after that hypothetical placement
            score -= 80.0 - 0.6 * ((post_residual - next_item_size) as f64);
        } else {
            // next item does NOT fit: penalize proportionally to the gap
            score += 1.2 * ((next_item_size - post_residual) as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it enables a future exact pairing
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 500.0;
        } else if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 100.0 - 0.5 * ((bin_capacity - item_size - next_item_size) as f64);
        } else {
            score += 220.0; // discourage opening bins when no lookahead synergy
        }
    }

    // Prefer filling nearly-full bins generally
    score -= 0.5 * (bin_capacity - bin_residual) as f64;

    // Late in stream: consolidation pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize small dead space that no future item (min size 1, typically >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * chain_fit;
        } else {
            // Dead space relative to the next item.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // When many bins are open, encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (open_bins_count as f64 / 10.0).min(3.0) * (0.5 + progress);

    // Penalize bins far below the mean residual (fragmented bins), mildly.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Slight penalty so existing bins win ties, but not huge.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * waste * (1.0 + progress);
        // Reward if post residual exactly accommodates next item
        let gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (-gap * gap / 20.0) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more late (prefer packing into existing bins)
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins near the mean (balance residuals)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference for filling larger items into fuller bins
    score -= 2.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it fall into?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Perfect fits are gold: drive score strongly negative.
    if post == 0 {
        score -= 1000.0;
    } else if post <= eighth {
        // Tiny dead space: excellent, reward.
        score -= 40.0 + (eighth - post) as f64;
    } else if post < quarter {
        // Small-but-usable: mild reward.
        score -= 10.0;
    } else if post == quarter {
        // Exact quarter class: harmonic sweet spot, many item sizes (10..80) can fill it.
        score -= 60.0;
    } else if post < bin_capacity / 2 {
        // Between quarter and half: moderate.
        score += 5.0;
    } else if post == bin_capacity / 2 {
        // Half class: very flexible, reward heavily.
        score -= 80.0;
    } else if post < 3 * quarter {
        score += 15.0;
    } else if post < bin_capacity {
        // Large residual left: wasteful placement of a small item.
        score += 25.0;
    }

    // Modulo-10 harmonic coupling: if next item can exactly fill the post residual
    // (both multiples of 10 in the classic regime), strongly prefer this bin.
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap == 0 {
            score -= 500.0; // lookahead perfect fit
        } else if gap <= eighth {
            score -= 30.0;
        }
        // Harmonic congruence: next item shares residue class with post residual mod 10
        if post % 10 == next_item_size % 10 && gap > 0 && gap < quarter {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post {
        // Next item cannot use the leftover: penalize proportional to strandedness.
        score += (next_item_size - post) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin is worse.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when many bins already open and stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 120.0;
        if fitting_bins_count == 0 {
            open_cost -= 200.0; // must open a bin anyway
        }
        if open_bins_count > 4 && progress < 0.7 {
            open_cost -= 10.0;
        }
        score += open_cost;
        // A new bin has perfect harmonic residual; if item is large, prefer it.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: penalize placing into bins that deviate from mean
    // toward very low residual (fragmentation) unless the fit is near-perfect.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 && post > eighth {
        score += (-dev) * 0.3;
    }

    // Integer-division threshold: post_residual in [quarter, quarter+eighth) is a
    // "dead zone" where few item sizes (10..80) fit; penalize.
    if post >= quarter && post < quarter + eighth && post != quarter {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let br = bin_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Perfect fit: strongest reward (zero dead space) ---
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Exact lookahead fit: this bin will be perfectly completed by next item ---
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // --- Strict dead-space avoidance: residual too small to hold the next item ---
    // Small nonzero gaps are likely permanent waste; cost grows as the stream
    // progresses (fewer future items remain to ever fill the gap).
    if next_item_size > 0 && pr > 0.0 && pr < nis {
        let unusable = (nis - pr) / nis.max(1.0);
        score += 15.0 + 40.0 * unusable * (0.6 + 0.8 * progress);
    }

    // --- Tiny-gap penalty: residuals below ~20 units rarely absorb future items ---
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 0.5 * (0.5 + progress);
    }

    // --- Lookahead destruction penalty: this placement breaks a bin that could
    // have accommodated the next item, wasting its remaining capacity ---
    if next_item_size > 0 && br >= nis && pr < nis && pr > 0.0 {
        score += 0.4 * (nis - pr);
    }

    // --- Last-chance bin: the only open bin that fits; using it avoids opening
    // a fresh bin, so strongly favor it ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    if is_new_bin {
        // --- New-bin candidate: fixed opening cost plus pressure from the number
        // of already-open bins (more open bins => harder to justify another) ---
        score += 25.0 + 2.0 * open_bins_count.min(25) as f64;
    } else {
        // --- open_bins_count pressure: reward consolidation into existing bins,
        // scaling with how many bins are already open ---
        score -= open_bins_count.min(20) as f64 * 0.8;
    }

    // --- Mean-residual coupling: reward leaving less residual than the current
    // average (tighter than typical), penalize leaving more ---
    score -= 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Lookahead: reward placements where the next item also fits the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize proportionally to wasted space.
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete: encourage diversification of residuals.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when open bins have poor residuals
    // or the stream is early and future items are likely large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual / item_size.max(1) as f64;
        let poor_state = if mean_residual < item_size as f64 { 1.0 } else { 0.5 * avg_fit };
        let early_bias = 1.0 - progress;
        score = bin_capacity as f64 - 55.0 * poor_state * (0.5 + early_bias);
        // Discourage hoarding bins when many are already open.
        score += 6.0 * (open_bins_count as f64).sqrt();
        // If the current bin is a good fit, a new bin should lose.
        if fit_ratio > 0.8 {
            score += 30.0;
        }
    }

    // Global balance: prefer bins whose residual is below the mean (compact them first),
    // keeping high-residual bins for larger future items.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild time horizon term: late in the stream, tighten packing aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep-like: penalizes mid residuals more

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate slack (keep bins flexible); late, crush residual aggressively
    let progress_coupling = x * (1.0 - progress) * 4.0 - x * x * progress * 8.0;
    score += progress_coupling;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted
    let dead = (x * (1.0 - x)).sqrt(); // peaks at x=0.5, zero at extremes
    score += 2.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits in post residual, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx <= x {
            score -= 3.0 * (x - nx) * (1.0 + progress);
        } else {
            score += 1.5 * (nx - x) * (1.0 - x);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Slight preference to fill bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.1 * x;

    // Alignment with mean residual: prefer bins below mean residual (tighter than average)
    score += 0.5 * ((mean_residual - pr) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize small dead space strata (unusable leftovers)
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align
    // with common item sizes (items drawn in 1..100, often multiples of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic check: does post_residual % next_item_size leave small waste?
            let waste = post_residual % next_item_size;
            score -= 10.0 - (waste as f64) * 0.5;
        } else {
            // next item cannot fit here; penalize leaving large residual anyway
            score += (next_item_size as f64 - pr) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current bin fit is bad
    if bin_residual == bin_capacity {
        // fresh bin score: baseline capacity minus item, adjusted by stream progress
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count >= 3 {
            score += 15.0; // plenty of alternatives, discourage new bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits elsewhere: new bin is right
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * fill_ratio;
    }

    // Slight preference for bins with below-average residual (consolidate fullness)
    score += (pr - mean_residual) * 0.1;

    // Late stream: be greedier about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 % 7.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps (< 10),
    // which no future item (min size 1..100 unknown, but small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // opening a new bin is penalized implicitly by rewarding existing-bin placement.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current residuals are badly fragmented
    // (high mean residual spread) or this bin fits poorly.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - fragmentation.min(20.0);
        score += 0.5 * open_bins_count as f64;
        // If no open bin fits, new bin is the only option: make it competitive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the stream average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // exactly into the post-residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect match: next item seals this bin
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a leftover; penalize leftover dead space
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.25 * leftover;
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins whose residual is already below mean residual (denser bins),
    // i.e. reward placing into tight bins, penalize sparse ones.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (dead space below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else. An empty bin starts with full residual, so its raw
    // score is high; give it a bonus so it wins when fits are bad, but not
    // when a good fit exists (good fits already get large subtractions).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 + 10.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins when item is small.
    if item_size <= 30 && open_bins_count > 5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize leaving residual that next item can't use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0; // dead space for the next item
        } else if (post_residual as i64) >= (nxt as i64) {
            score -= 6.0; // residual is reusable by lookahead
            // Extra reward if next item exactly fills the post residual.
            if (post_residual as u32) == next_item_size {
                score -= 10.0;
            }
        }
    } else {
        // Last item: prefer zero waste strongly.
        score -= 15.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid wasting existing capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins harder.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * (post_residual as f64 / cap);

    // Mean residual coupling: if this bin is much emptier than average,
    // it is a good filler target; if much fuller than average, penalize slightly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Time horizon: early in the stream, opening new bins is cheap (explore);
    // late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score -= 10.0 * (1.0 - progress);
        score += 25.0 * progress;
    } else {
        score -= 8.0 * progress; // favor existing bins as stream matures
    }

    // Waste ratio penalty: penalize large post residuals superlinearly.
    let waste_frac = post_residual as f64 / cap;
    score += 20.0 * waste_frac * waste_frac * waste_frac;

    // Small clamp to keep scores finite and comparable.
    if score.is_nan() { score = f64::INFINITY; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let tight = 1.0 - pr / cap; // how full the bin becomes

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Reward tight fits with smooth polynomial in fill level
    score -= 30.0 * tight * tight * (0.5 + 0.5 * progress);

    // Penalize small post-residuals that can't fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        score -= 12.0 * usable * (nx / cap) * (1.0 - progress);
        score += 6.0 * (1.0 - usable) * (nx / cap);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Mild pressure from open bins and mean residual
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap - 0.5).abs();

    // New-bin candidate handling: penalize opening a fresh bin early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
