pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit any future item
    // (item sizes in 1..=100, but treat anything < 10 as effectively dead)
    if post_residual < 10 {
        score += 60.0; // unusable gap penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure is ideal
    }

    // Penalize residuals that are too small for the lookahead item but nonzero
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward exact match with the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Tight-fit reward: smaller post_residual relative to item size is better
    score -= (item_size as f64) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it unattractive unless open bins are proliferating
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Open-bins pressure: many open bins -> favor filling existing ones (low residual bins)
    score += 0.3 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (below mean residual = tighter bin)
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: good, reward proportionally to closeness
            score -= 200.0 / (1.0 + diff);
        } else {
            // post_residual too small for next item: dead space penalty
            score += diff * 1.5;
        }
    }

    // Penalize large leftover relative to bin capacity (fragmentation)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 30.0;

    // Compare against mean residual: prefer bins whose post residual is near/below mean
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = 120.0 + (open_bins_count as f64) * 5.0;
        if post_residual == bin_capacity {
            // item is the full capacity case
            score -= 500.0;
        } else {
            score += penalty;
            // soften if the leftover would still be usable by next item
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 40.0;
            }
        }
    }

    // Slight preference for tighter fits: small post_residual rewarded
    score -= 20.0 / (1.0 + post_residual as f64);

    // Mild late-stream conservatism: keep bins open longer as stream ends
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_frac;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += 12.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral base, but discouraged early in the
    // stream or when open bins have plenty of room; encouraged when open bins
    // are fragmented (low mean residual relative to item).
    if bin_residual == bin_capacity {
        score = 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        score += (open_bins_count as f64).sqrt() * 3.0;
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // roomy bin good for bigger next item
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean:
        // placing into below-average-residual bins preserves roomier bins.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 40.0 * dev;

        // Mild preference for bins with residual close to item (perfect fill).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with progress
    let waste = pr / cap;
    score += 18.0 * waste * waste * (0.5 + t);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tight = 1.0 - (pr / cap);
    score -= 25.0 * tight * tight * tight * (0.4 + 0.6 * t);

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 20.0 * fits * (1.0 - slack) * (0.3 + 0.7 * t);
        // Penalize when next item nearly fits but not exactly (creates pressure)
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 12.0 * (gap * (1.0 - gap)).max(0.0);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + t);
    }

    // New-bin candidate: penalize opening bins early, mildly late
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 15.0 + 10.0 * (1.0 - t) + 2.0 * open_f.sqrt();
    }

    // Mean residual coupling: prefer bins deviating below mean residual (packing denser bins first)
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev.abs();

    // Mild preference for filling fuller bins (smooth in residual)
    score += 6.0 * (bin_residual as f64 / cap) * (1.0 - t * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 equal classes of 20.
    let class = (post_residual / 20) as f64;
    score += class * 6.0;

    // Perfect fit bonus: residual lands exactly on common item-size divisors.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 18.0;
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Dead-space penalty: residual too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item fits with small waste.
            let waste = post_residual - next_item_size;
            if waste < 10 {
                score -= 20.0;
            } else if waste < 25 {
                score -= 8.0;
            } else {
                score += waste as f64 * 0.3;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // current open bins are fragmented (high mean residual) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - cap * 0.5).max(0.0);
        score -= 10.0 + fragmentation * 0.5 + progress * 8.0;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    } else {
        // Prefer filling already-open bins relative to how many exist.
        score += (open_bins_count as f64) * 0.4;
    }

    // Tightness reward: item consumes most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 22.0;
    } else if fill_ratio > 0.6 {
        score -= 10.0;
    }

    // Mean-residual alignment: bins far from the fleet mean get mild penalty
    // to keep residual distribution harmonized.
    score += ((post_residual as f64 - mean_residual) * 0.15).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }

    // Grace region: small-but-usable leftovers are mildly penalized so that
    // near-perfect fits win out.
    if post_residual >= min_useful && post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is excellent.
    score += open_bins_count as f64 * 1.2;

    // New-bin candidate handling: a fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are very full
        // (mean residual small) or the fit elsewhere would be terrible.
        let mean_pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // Base cost of a new bin, reduced when existing bins are nearly full.
        score += 30.0 - mean_pressure * 25.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64 / 100.0) * 8.0;
        }
        // Late in the stream, avoid leaving many nearly-empty bins around.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // Existing bin: bonus when its residual matches the upcoming item,
        // preserving good future fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leaving a residual the next item almost fits (near-miss waste).
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(5) {
            score += 12.0;
        }
    }

    // Slight preference for bins below mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 80.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit in this residual: penalize wasted space proportionally
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare residual to mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize creating small unusable dead space (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // New-bin candidate: prefer opening a new bin only when no open bin gives a tight fit
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: favor existing bins more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 + 4.0 * (nx / 100.0);
        } else {
            // Dead space relative to next item.
            score += 0.15 * (post_residual as f64 - nx).abs();
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.2 * pr;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 0 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        score -= 3.0 * fill_pressure;
        score += 0.5 * open_bins_count as f64 * 0.1;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Large items benefit from a fresh bin; small items should reuse.
        score += 15.0 - 20.0 * fit_quality;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // fresh bin pairs well with similar next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual
    let pr_norm = pr / cap;
    score += 18.0 * pr_norm * pr_norm;

    // Smooth stream-progress coupling: late in stream, tighter packing matters
    score += (6.0 + 10.0 * progress) * pr_norm * pr_norm;

    // Penalize leaving residual that cannot fit the lookahead item, reward when it can
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            // bonus shrinking as residual barely fits next item
            let snug = 1.0 - ((pr - n) / cap);
            score -= 8.0 * snug * snug;
        } else {
            let gap = (n - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a very tight fit later;
    // penalize opening bins when existing bins give decent fit
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 22.0 + 4.0 * openness + 12.0 * progress;
    }

    // Reward using bins whose residual is close to the item (smooth coupling)
    let fit_tightness = 1.0 - ((bin_residual as f64 - item_size as f64) / cap);
    score -= 6.0 * fit_tightness * fit_tightness;

    // Mild penalty if this bin is far below mean residual (wasting a full bin)
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_u = if bin_capacity == 0 { 1 } else { bin_capacity };
    let cap = cap_u as f64;

    let post_u = post_residual.min(cap_u);
    let next_u = next_item_size.min(cap_u);
    let item_u = item_size.min(cap_u);

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let mean = mean_residual.max(0.0).min(cap);

    let tenth = (cap_u / 10).max(1);
    let quarter = (cap_u / 4).max(1);
    let half = (cap_u / 2).max(1);

    let is_new = bin_residual == bin_capacity;
    let alt_factor = 1.0 / (1.0 + 0.22 * (fitting_bins_count.saturating_sub(1)) as f64);

    let mut score = post_u as f64;

    // Harmonic waste classes: exact fits are excellent, tiny nonzero residuals
    // are dead space, while quarter/half-aligned leftovers remain useful.
    if post_u == 0 {
        score -= 5.0 + 4.0 * progress;
    } else {
        if post_u <= tenth {
            score += 2.2;
        } else if post_u <= quarter {
            score += 1.1;
        } else if post_u <= half {
            score += 0.4;
        }

        let phase = (post_u % quarter) as f64 / quarter as f64;
        score += 0.8 * phase * (1.0 - phase);
    }

    let scarcity = if next_u == 0 {
        0.0
    } else {
        ((next_u as f64 - mean) / cap).clamp(0.0, 1.0)
    };

    if next_u > 0 {
        let next = next_u as f64;

        if post_u >= next_u {
            let after_u = post_u - next_u;

            // Reward bins that can absorb both the current and next item.
            let pair_bonus = next * (0.55 + 0.75 * scarcity)
                + (cap - after_u as f64) * 0.04;

            score -= pair_bonus * alt_factor;

            if after_u == 0 {
                score -= 2.0 + 3.0 * progress;
            } else if after_u <= tenth {
                score += 0.8;
            }
        } else {
            let gap = (next_u - post_u) as f64;
            let tier_gap = ((next_u - post_u) / tenth) as f64;

            score += 1.2 + gap * 0.05 + 2.0 * scarcity + 0.25 * tier_gap;

            // Strong penalty when this placement destroys a bin that could
            // otherwise have served the lookahead item.
            if bin_residual >= next_u {
                score += gap * (0.08 + 0.22 * scarcity) + 2.5 * scarcity;
            }
        }
    }

    // Mild last-chance bonus for the only open bin that can fit the item.
    if !is_new && fitting_bins_count == 1 {
        score -= 0.8;
    }

    if is_new {
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else {
            let mut penalty = 16.0
                + 3.5 * (fitting_bins_count.min(12) as f64)
                + 7.0 * progress
                + 0.9 * (open_bins_count.min(20) as f64)
                + 2.5 * (mean / cap);

            if fitting_bins_count == 1 {
                penalty += 10.0;
            }

            penalty -= (item_u as f64 / cap) * 5.0;

            if next_u > 0 && post_u >= next_u {
                penalty -= 6.0 * scarcity + 3.0 * (next_u as f64 / cap);
            }

            // Strategic new-bin case: preserve a residual class that is still
            // large enough for the next item instead of fragmenting it now.
            if fitting_bins_count == 1 && next_u > 0 && mean >= next_u as f64 {
                penalty -= 8.0 + 4.0 * (mean / cap);
            }

            score += penalty.max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // plausible future item are pure waste — penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 40.0;
    }
    // Unusable gap for the known next item: heavy penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Reward when the leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Tight-fit reward: post_residual small relative to item size is a great fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.05 * pressure * (mean_residual - post_residual as f64).abs().min(50.0);

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual.max(1.0);
        if poor_fit_elsewhere {
            score -= 10.0 + 0.2 * item_size as f64;
        } else {
            score += 15.0;
        }
    }

    // Mild bonus for leaving residuals that are multiples of common item sizes.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with distance.
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).powi(6);
        // Penalize residuals that are too small to ever be useful (dead space),
        // but exempt the perfect-match case.
        if post_residual < next_item_size && diff > 0.0 {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer the tightest fit (minimal post_residual).
        score += 0.0;
    }

    // Prefer tight fits in general: reward small post_residual relative to capacity.
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative-to-mean coupling: bins with residual near mean_residual are
    // "average" candidates; reward bins tighter than mean (good consolidation),
    // penalize bins much looser than mean (fragmented packing).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize new bins moderately, but reduce the
    // penalty when the current bin would leave a large awkward residual.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64) - pr;
        let _ = waste;
        // Base penalty for opening a new bin.
        score += 18.0;
        // If the item would leave a very small residual in an existing bin
        // (near-perfect fit exists elsewhere), opening a new bin is bad.
        // If existing bins would leave large residuals, new bin becomes viable:
        // soften penalty when item is large relative to capacity.
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 14.0 * tightness;
        // If next item matches the new bin's future residual, new bin is good.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 30.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, avoid opening
    // new bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    }

    // Slight preference to spread load when many bins are open with high mean residual.
    if bin_residual == bin_capacity && open_bins_count > 0 && mean_residual > 0.5 * bin_capacity as f64 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // wasted gap relative to lookahead
        }
        // Perfect chain: item + next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // prefer reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more items to come
        // that may fill residuals); later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many open bins with slack, discourage yet another bin.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Prefer bins with residual close to item (best-fit) but discourage
        // using very full bins when many alternatives exist.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score += 5.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Global slack pressure: if mean residual is large, push items into
    // existing bins to consolidate.
    score -= 3.0 * (mean_residual / bin_capacity as f64);

    // Mild exploration term coupling time and state.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (progress * std::f64::consts::PI).sin() * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fits preferred (low post_residual), with non-linear amplification
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth coupling: waste matters more as the stream progresses
    let waste_weight = 1.0 + 1.5 * progress * progress;
    score *= waste_weight;

    // Penalize residual that cannot fit the lookahead item (dead space creation)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = nx - pr;
            score += 4.0 * (gap / cap) * (1.0 + progress);
        } else {
            // Reward residuals that nicely accommodate the next item
            let snug = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 2.5 * snug.max(0.0) * (1.0 - progress);
        }
    }

    // Last fitting bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty for squandering choice among many fitting bins
        score += 0.15 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when current bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - cap).abs() / cap;
        score = 8.0 + 10.0 * (1.0 - progress) + 5.0 * (1.0 - mean_gap.min(1.0));
        if fitting_bins_count <= 2 {
            score -= 7.0;
        }
    }

    // Slight preference for bins already below mean residual (balancing)
    score += 0.5 * ((post_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: modulo classes over capacity fractions.
    // Residuals divisible by larger class sizes are more "usable" -> reward (subtract).
    let pr = post_residual;
    let class = if pr == 0 { 100 }
        else if pr % 50 == 0 { 50 }
        else if pr % 25 == 0 { 25 }
        else if pr % 20 == 0 { 20 }
        else if pr % 10 == 0 { 10 }
        else if pr % 5 == 0 { 5 }
        else { 1 };
    score -= class as f64 * 0.35;

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits but not perfectly: mild reward scaled by tightness
            score -= 12.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize large leftover classes less
            score += 0.15 * (pr as f64 - (pr as f64 % 10.0)) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin opening unless current bins are nearly full / bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // open new bin more readily early on or when existing bins are well filled
        score += 25.0 - 20.0 * progress - 15.0 * avg_fill;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 10.0; // next item large; fresh bin useful
        }
    }

    // Waste penalty: dead space below smallest plausible item class.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Slight preference for bins with below-average residual (keep big holes for big items).
    score += 0.25 * ((post_residual as f64) - mean_residual).clamp(-50.0, 50.0) * 0.1;

    // Fractional capacity coupling: reward residuals that are exact capacity fractions.
    for &f in &[100u32, 75, 50, 33, 25, 20, 10] {
        if pr == f {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (min size 1..10)
    // can use are pure waste. Penalize gaps in the "dead zone" (0 < post_residual < 10)
    // heavily, and mildly reward large usable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 0.25 * next_item_size as f64;
        } else {
            // Next item won't fit here; if post residual is small, this bin
            // is effectively closed anyway — slight penalty for hoarding space.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    // (A new-bin candidate has bin_residual == bin_capacity; make it less attractive
    // as open_bins_count grows.)
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        // Using an existing bin relieves pressure; reward scales with open bins.
        score -= 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., already fairly full) to consolidate space.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early stream: be slightly more willing to open bins (future items unknown);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - slack.min(60.0); // tight lookahead match is best
    } else if next_item_size > 0 {
        // Penalize creating residual that blocks the next item but is too big to waste.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 2.0;
    }

    // Relative-to-mean coupling: bins below mean residual are "sparser"; prefer
    // filling the tightest bins to preserve large residuals elsewhere.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = residual_f / mean_residual;
        if ratio < 0.5 {
            score -= 40.0 * (0.5 - ratio);
        } else if ratio > 1.5 {
            score += 30.0 * (ratio - 1.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post-residual
    // waste in existing bins) or stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = if fitting_bins_count > 0 {
            (post_residual as f64) // empty bin's post_residual == capacity - item
        } else {
            0.0
        };
        score -= waste_pressure * 0.5;
        score -= (1.0 - progress) * 60.0 * (open_bins_count as f64).sqrt().min(4.0);
        // Discard new-bin option when an existing bin achieves a tight fit.
        if post_residual <= 10 && fitting_bins_count > 0 {
            score += 800.0;
        }
        // Prefer reusing bins when the next item also fits the leftover.
        if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 100.0;
        }
    }

    // Penalize leaving large dead space that small future items can't use.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize creating dead space non-linearly
    score += (post_residual as f64).powi(2) / 100.0;

    // Reward tight fits (small post_residual)
    if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= (15.0 - waste as f64).max(0.0) * 0.5;
        }
    }

    // New bin candidate: penalize opening a new bin unless current fits are bad
    if is_new_bin {
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 40.0 / pressure;
        // Early in the stream, opening bins is cheaper (future consolidation possible)
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer reusing open bins
        score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Mildly prefer bins whose residual is close to item size (best-fit style)
    score -= (bin_residual - item_size) as f64 * 0.1;

    // Late in stream: be more conservative, avoid many nearly-empty bins
    if progress > 0.8 && !is_new_bin {
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, penalized non-linearly (dead space grows quadratically in cost)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: high residual waste is worse later in the stream
    score += 30.0 * progress * norm_pr * norm_pr * cap;

    // Tight fits rewarded (post_residual near 0), smoothly
    score -= 25.0 * (1.0 - norm_pr).powi(6) * progress;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // New bin candidate: penalize opening bins early, slightly favor late when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) - 20.0 * progress;
        if open_bins_count > 0 {
            score += 8.0 * (mean_residual / cap).ln().max(-3.0);
        }
    }

    // Prefer bins with residuals close to the item (good fit), smooth kernel
    let fit_gap = (bin_residual - item_size) as f64;
    score += 12.0 * (fit_gap / cap) * (fit_gap / cap) * cap;

    // Mild preference for bins below mean residual (consolidate emptier bins)
    score += 5.0 * ((mean_residual - bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible
    // follow-up item are pure waste; penalize them hard.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    } else {
        // Reward tight fits (small useful residual) super-linearly.
        let pr = post_residual as f64;
        score -= 12.0 * (1.0 - pr / bin_capacity as f64).powi(3);
    }

    // If the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < dead_threshold {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder: mild penalty if residual
        // is small (dead space for the lookahead).
        if (post_residual as f64) < dead_threshold {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so the empty-bin candidate should
    // remain competitive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate calibration: an empty bin gets baseline residual =
    // capacity, which is already high; nudge it so it only wins when this bin
    // would create bad dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
    } else {
        // Favor bins whose residual is above mean (consolidating space).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(30.0); // tight fit preferred, slack penalized
    }
    // Penalize if post_residual is small but nonzero relative to next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Reward tight packing relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(20.0) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual).min(20.0) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0; // base penalty for opening a new bin
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere -> new bin is fine
        }
        if next_item_size > 0 && (bin_capacity as f64 - post_residual as f64) >= next_item_size as f64 {
            // fresh bin can chain two items: modest bonus
            score -= 5.0;
        }
    }

    // Late-stream bias: keep residuals small as stream nears completion
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled by capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward perfect fill strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual usable by next item: reward proportionally to how well it matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Residual too small for next item: dead space penalty, worse when large.
            score += 15.0 * (post_residual as f64) / 100.0;
        }
    }

    // Penalize placements that fragment a large residual when many bins are open
    // and mean residual is high (plenty of room elsewhere).
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Early in the stream, be more willing to open fresh bins for large items;
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus bias that decreases with progress.
        let mut new_bin_score = 75.0 + 30.0 * (1.0 - progress);
        // Opening a new bin is more attractive when few bins fit the item.
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // If next item is large and this item is large, new bin keeps flexibility.
        if next_item_size >= item_size && item_size > 50 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    } else {
        // Late stream: extra reward for using existing bins.
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.3 * open_bins_count as f64 * (mean_residual / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;
    let res = bin_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item, amplified by progress.
    let fill_frac = fit / cap;
    score -= 45.0 * fill_frac * (1.0 + 2.0 * progress);

    // Non-linear penalty on post_residual: dead space grows super-linearly,
    // but its cost fades late in the stream (fewer future chances to reuse).
    let norm_pr = (pr / cap).clamp(0.0, 1.0);
    score += 60.0 * norm_pr * norm_pr * (1.0 - 0.5 * progress);

    // Smooth interaction: small post_residual combined with high fill is doubly good.
    score -= 25.0 * fill_frac * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Perfect fit bonus (smooth, quadratic decay away from zero residual).
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize leaving residual that cannot fit the next item;
    // reward leaving residual that exactly matches it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = (gap / cap).clamp(0.0, 1.0);
        score += 20.0 * gap_norm * gap_norm * (1.0 - progress);
        if pr >= nx {
            score -= 12.0 * (1.0 - gap_norm) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate handling: early on, opening bins is fine; late, discourage.
    if bin_residual == bin_capacity {
        score += 15.0 * progress * progress * (open_bins_count as f64).sqrt();
        score -= 8.0 * (1.0 - progress);
        // A new bin is attractive if no existing bin fits well.
        if bin_residual < item_size {
            score -= 50.0;
        }
    }

    // Mild coupling to mean residual: prefer bins whose residual deviates from mean
    // toward smaller values (consolidating large leftovers elsewhere).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev.max(0.0) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let c = bin_capacity;
    let pr = post_residual;
    let quarter = c / 4;
    let eighth = c / 8;

    // Reward residual classes that are "reusable": multiples of quarter/eighth
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % quarter == 0 {
        score -= 12.0;
    } else if pr % eighth == 0 {
        score -= 6.0;
    }

    // Penalize small dead-space classes (< eighth) that waste capacity
    if pr > 0 && pr < eighth {
        score += 25.0;
    } else if pr >= eighth && pr < quarter {
        score += 8.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // tighter next fit = better
            score -= 5.0 + 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 6.0;
            // harmonic mismatch penalty: next item leaves awkward class
            let nxt_class = next_item_size % eighth;
            if nxt_class != 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // open a new bin only late in stream with many open bins and poor mean residual
        if mean_residual < 20.0 && open_bins_count > 3 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / c as f64);

    // Small tie-breaker on open bins count
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // conceivable item are pure waste. Penalize them extra harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: post_residual smaller than item_size means the bin
    // was filled to more than half with this item; reward proportionally.
    if post_residual < item_size {
        score -= 0.5 * (item_size - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual but this bin's residual
    // could have held it, penalize wasting the opportunity.
    if next_item_size > post_residual && next_item_size <= bin_residual - item_size {
        // no extra: post_residual already captures it
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.3 * (next_item_size - post_residual).min(20) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin by giving a discount (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin should only win when the fit
    // into existing bins is poor. Penalize the fresh bin mildly, scaled
    // by how many bins are already open (bin pressure).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        // But if the current item is huge, a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual deviates far above
    // the mean, it's a laggard bin; favor consolidating into it.
    let residual = bin_residual as f64;
    if residual > mean_residual {
        score -= 0.2 * (residual - mean_residual);
    } else {
        score += 0.1 * (mean_residual - residual);
    }

    // Late in the stream, slightly prefer tighter fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual)
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, close the bin
    }

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Penalize leftover after hypothetically placing next item
            score += slack_after_next as f64 * 0.5;
            // Bonus if next item leaves another perfect/zero residual
            if slack_after_next == 0 {
                score -= 300.0;
            }
        } else {
            // Next item cannot fit here; leftover is pure dead space for lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow opening a new bin if item fits badly everywhere
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never fit a plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // New bin is attractive early (few open bins) or when current bins fit poorly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = (open_bins_count as f64).ln().max(0.0) * 8.0;
        score = 55.0 + open_penalty + 20.0 * progress;

        // If mean residual across open bins is large, prefer reusing them instead
        score += mean_residual * 0.3;

        // If next item is huge, a fresh bin may be good
        if next_item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // Favor fuller bins when many bins are open (consolidation pressure)
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(0.5);

        // Time horizon: late in stream, avoid leaving scattered residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > item_size as f64 * 0.0 + 0.0 && post_residual < item_size {
            score += 12.0 * progress; // residual smaller than current item late = dead space
        }

        // Reward bins whose residual aligns with mean residual (balanced packing)
        let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
        score -= 6.0 * align;
    }

    // Slight preference for bins with residual close to item size (perfect-ish fit)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let base = pr_norm * pr_norm * cap;
    let mut score = base;

    // reward tight fits with smooth polynomial coupling to progress
    let tight = 1.0 - pr_norm;
    score -= 40.0 * tight.powi(3) * (1.0 + progress);

    // penalize residual that matches the next item poorly (smooth interaction)
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - diff).powi(2) * (1.0 - progress);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 30.0 * gap * gap * cap;
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 2.0 * progress);
    }

    // penalize wasteful opening relative to mean residual
    score += 0.05 * (mean_residual - pr).abs() * (1.0 + progress);

    // new-bin candidate: prefer it only when residuals are all low
    if bin_residual == bin_capacity {
        score = pr_norm * cap * (1.0 - 0.5 * progress) + 0.3 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: classify leftover space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Penalize post-residuals in "dead zones" — leftovers that few item sizes can fill.
    // Classes via integer division on post_residual (capacity 100 -> classes of 12-13).
    let class = post_residual / 12;
    let class_penalty = match class {
        0 => 0.0,          // near-perfect fit, excellent
        1 => -6.0,         // small leftover, likely fillable
        2 => 3.0,          // awkward middle leftover
        3 => -2.0,         // decent leftover
        4 => 5.0,          // half-full-ish leftover, wasteful
        5 => -1.0,
        6 => 4.0,
        _ => 2.0,          // large leftover = wasted capacity
    };
    score += class_penalty;

    // Modulo-10 harmonic: multiples of 10 pair well with typical item sizes.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 4.0;
    } else if mod10 >= 7 {
        score += 2.5;
    }

    // Reward tight fits (small post_residual) superlinearly.
    score -= (1.0 - post_frac).powi(3) * 8.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / cap);
        // harmonic match: next item lands post-residual on a multiple of 10
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mildly penalize hoarding space.
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // and stream is early (many items remain to fill a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_residue = (post_frac > 0.25 && post_frac < 0.6) as f64;
        score = 60.0 + 40.0 * (1.0 - progress) - 20.0 * bad_residue;
        // If next item is large, fresh bin is safer
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (fill the emptier-relative bins first to keep a spread of large residuals).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 2.0 * (1.0 - tightness);
    }

    // Lookahead: penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 40.0 + (open_bins_count as f64) * 3.0;
        let pull = if fitting_bins_count == 1 { 80.0 } else { 0.0 };
        score += base + pull;
    }

    // Mild stream-progression adaptation: tighten criteria as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less leftover is generally better.
    score -= item_size as f64 * 0.5;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect chaining: item fits now, next item fills the remainder exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving a residual that neither fits the next item nor is a useful small remainder.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 20.0;
    }

    // Dead-space penalty: residual too small to hold anything useful (min item ~1, but tiny slivers waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins),
    // penalize dumping into bins with large residuals when alternatives exist.
    if (bin_residual as f64) > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Early in the stream, be more willing to open new bins for large items
    // to keep flexible residuals around; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it for large items or when fit is poor.
        score -= item_size as f64 * 0.4;
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) {
            score += 10.0;
        }
    }

    // If many bins fit the item, mild penalty to keep competition meaningful;
    // if few fit, favor this bin.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: how far through the stream we are.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: prefer bins where the item fills a large fraction.
    let fill_fraction = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fill_fraction * fill_fraction;

    // Perfect fit bonus: residual becomes a tiny unusable remainder.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: leaving a residual too small for the smallest item (1..100 unknown,
    // use a conservative small-item threshold) is wasteful unless it's near zero.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 15.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 18.0 * next_fit_quality;
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item cannot use this residual; penalize leaving large stranded gaps.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over
    // opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the stream
    // or when the fit into this bin is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Early in the stream, new bins are cheaper (more future items to fill them).
        score -= 45.0 * (1.0 - progress);
        // If few bins are open, spreading items is fine.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 12.0;
        }
    } else {
        // Existing bin: reward using bins that are already partially filled relative to mean.
        if mean_residual > 0.0 {
            let rel = bin_residual as f64 / mean_residual;
            // Prefer bins with residual below the mean (tighter bins get used first).
            score += 6.0 * (rel - 1.0);
        }
    }

    // Global pressure: when many bins are open, discourage opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Mild time-decay on residual importance: late in the stream, consolidate aggressively.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer minimal post residual, with non-linear waste penalty
    let mut score = post + 12.0 * (post / cap).powi(2) * cap;

    // Smooth polynomial coupling of waste with stream progress:
    // late in the stream, tight packing matters more
    score += 8.0 * progress * (post / cap).powi(3) * cap;

    // Reward filling a large fraction of the bin's current residual (smooth)
    let fill_ratio = (item_size as f64) / res.max(1.0);
    score -= 6.0 * fill_ratio * (1.0 - 0.5 * progress);

    // Lookahead: bonus if post residual can fit the next item (smooth decay)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            // penalize creating dead space the next item cannot use
            score += 3.0 * (-gap / cap).powi(2) * cap / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far from mean residual (keep residual profile homogeneous)
    score += 2.0 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: neutral-to-early attractive, penalized late / when open bins exist
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = cap * (0.55 + 0.45 * progress) + 20.0 * open_pressure * (1.0 - progress);
        // early stream: new bin is cheap; late: expensive
        score += 25.0 * progress.powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base waste penalty scaled by fraction of capacity left idle
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic class logic: post_residual modulo 10 classes.
    // Residuals in the "dead zone" (1..10, unusable by min-size items) are penalized;
    // multiples of 10 are slightly favored since they align with common item sizes.
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // dead space class
    } else {
        score += cls as f64 * 0.4;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0; // harmonic alignment with capacity fractions
    }
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 3.0; // post_residual divides capacity evenly
    }

    // Lookahead (k=2): reward if next item fits the post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual < 10 {
            // residual is dead space anyway; small penalty relief
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is penalized by default,
    // but becomes attractive when existing residuals are fragmented (high mean residual)
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5;
        // Large items into a fresh bin leave a useful symmetric residual
        if item_size >= 50 && (bin_capacity - item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Late in the stream, be more conservative with open bins (prefer tight packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (best-fit flavor beyond raw post_residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tight = next_item_size as f64 / post_residual as f64;
        if lookahead_tight > 0.7 {
            score -= 25.0 * lookahead_tight;
        }
    }
    // Penalize if next item cannot use the post residual (dead space likely).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * (1.0 + progress);
        score += 40.0 + pressure * 5.0;
        // But allow a new bin if it would be badly fragmented otherwise.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 55.0;
        }
    }

    // Mild preference for bins below mean residual (keep residuals balanced).
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but reward exactness super-linearly.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect closure is ideal
    } else if post_residual < 10 {
        score -= 25.0; // tiny dead space
    }

    // Aggressive 2-step lookahead: if next item exactly fills the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64) as f64;
        if lookahead_gap == 0.0 {
            score -= 45.0; // next item perfectly fills this bin
        } else if lookahead_gap > 0.0 && lookahead_gap <= 10.0 {
            score -= 20.0 - lookahead_gap; // near match with next item
        } else if lookahead_gap < 0.0 {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (-lookahead_gap).min(40.0) * 0.3;
        }
        // If next item is large and this bin can't hold it anyway, mild penalty for hoarding space
        if next_item_size as f64 > post_residual as f64 && post_residual > 20 {
            score += 5.0;
        }
    }

    // Relative to mean residual: prefer bins that are already "tight" (below mean residual),
    // i.e., filling up fuller bins first keeps looser bins flexible.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.4;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are large
    // (i.e., existing bins are nearly full / unusable).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let avg_tightness = mean_residual / cap; // 0 = empty-ish bins, 1 = full bins
        // Penalize new bin when open bins still have usable average space.
        score += 35.0 * (1.0 - avg_tightness) + openness * 2.0;
        // If the item is small, opening a fresh bin wastes capacity; penalize more.
        score += (100 - item_size.min(100)) as f64 * 0.15;
        // Late in the stream, avoid leaving many half-empty bins around.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild penalty for very large leftover gaps that few items could use.
    if post_residual > 60 {
        score += (post_residual - 60) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Penalize small awkward residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: fraction of residual consumed
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Lookahead: if next item fits exactly-ish in post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / 50.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this leftover: mild penalty scaled by leftover size
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // New-bin candidate handling: good for large items or late stream, bad early
    if is_new_bin {
        if item_size >= 60 || post_residual <= 40 {
            score -= 10.0;
        } else {
            score += 15.0 + 20.0 * (1.0 - progress);
        }
        // discourage hoarding too many open bins
        score += 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins below mean residual (keep big residuals available)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins as stream progresses
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate leftover space; late, punish waste harder.
    let coupling = 1.0 + progress * (norm_pr - 0.3) * (norm_pr - 0.3) * 4.0
                 - progress * norm_pr * (1.0 - norm_pr) * 2.0;
    score *= coupling;

    // Tight fit reward (smooth): low post residual gets subtracted bonus
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 8.0 * tightness * (0.5 + progress);

    // Last-chance bin: strong reward, smoothly scaled by how tight the fit is
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * tightness;
    }

    // Lookahead: reward if next item fits into post residual (smooth decay)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = 1.0 - ((pr - nxt) / cap);
            score -= 5.0 * slack * slack * (1.0 - progress * 0.5);
        } else {
            // penalize residuals that nearly-but-don't fit the next item
            let miss = (pr - nxt) / cap;
            score += 3.0 * (1.0 + miss) * (1.0 - miss).max(0.0);
        }
    }

    // Penalize opening new bins when many bins are already open and mean residual is large
    let new_bin_penalty = (mean_residual / cap).powi(2) * (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        score += 4.0 + new_bin_penalty * (1.0 - progress);
    } else {
        // mild reward for using existing bins relative to mean residual
        score -= (mean_residual - pr) / cap * 1.5;
    }

    // Penalize very fragmented open-bin pools slightly
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class logic: partition post_residual into capacity-fraction classes.
    // Residuals in [0,10) are "perfect" (near-full bin) -> strong reward.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    } else if post_residual < 35 {
        score -= 8.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item-size classes (10,20,25) are reusable; odd leftovers are dead space.
    let pr = post_residual as i64;
    if pr > 0 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
        if reusable {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Integer division thresholds: how many "average items" fit afterwards.
        let slots = pr / 30;
        score -= 6.0 * slots as f64;
    }

    // Lookahead: reward if next item fits the post-residual (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // exact chain: next item fills bin completely
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            // next item does NOT fit: this placement strands the residual
            score += 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current fit is poor and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = frac > 0.45;
        if poor_fit && open_bins_count > 3 {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 50.0; // prefer existing bins by default
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already "used up"; placing here keeps big residual bins flexible.
    let diff = mean_residual - post_residual as f64;
    score += 0.15 * diff;

    // Early stream: keep bins tight since future unknown; late stream: close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual is good, non-linearly).
    score -= 120.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 250.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 180.0;
        } else if next_item_size <= post_residual {
            // Usable leftover for the next item: mild bonus scaled by slack.
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize large wasted gaps.
            score += 0.3 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 8.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.55 * bin_capacity as f64;
        if poor_fit && next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 100.0; // keep fresh bin for the upcoming item
        } else if poor_fit {
            score -= 30.0;
        } else {
            score += 120.0; // good fit exists elsewhere: penalize opening a new bin
        }
    }

    // Mild phase pressure: later in the stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with residuals near the mean (balanced usage).
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect match: next item exactly fills this bin
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item also fits here: big reward
            score -= 25.0 + (post_residual as f64 - nxt) * 0.2;
        } else {
            // Dead space for the next item: penalize leftover
            score += (post_residual as f64) * 0.6;
        }
    }

    // Last chance bin: strongly prefer using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Reward tight fits relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize opening a new bin when good fits exist, but allow it for terrible fits
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if post_residual as f64 > 20.0 {
            score += 20.0;
        }
    }

    // Progress-based mild tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect closure reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2) coupling: reward residuals that can host the next item,
    // extra reward for near-perfect two-step packing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size < 10 {
                score -= 6.0;
            }
        } else {
            // placement kills the lookahead opportunity
            score += 6.0 + 0.1 * next_item_size as f64;
        }
    }

    // Last-chance bin before opening a new one: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base penalty: prefer filling existing bins
        score += 30.0;
        // Early in the stream, opening bins is cheap and preserves flexibility;
        // late in the stream, squeeze into existing bins.
        score -= 12.0 * (1.0 - progress);
        // If many open bins with fat residuals, opening a fresh bin is fine
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Fragmentation penalty: tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer packing into bins whose current residual is close to the item
    // (tight fit), i.e. small waste relative to bin's available space.
    if bin_residual >= item_size && bin_residual != bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
        score += 10.0 * tightness;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let base = post;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress) - norm_post * progress * 0.5;
    let mut score = base * (1.0 + poly);

    // Penalize dead space more as stream progresses (less future to fix it)
    score += 8.0 * progress * norm_post * norm_post * cap;

    // Reward tight fits
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward residual that matches next item
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0) * (1.0 - progress);
    }

    // Prefer filling bins when many are open
    score -= open_bins_count as f64 * 0.3 * (1.0 - norm_post);

    // Mild penalty if residual is far below mean residual (fragmentation)
    score += 0.2 * (mean_residual - post).abs();

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count >= 1 { 1.0 } else { 0.0 };
        score += 25.0 * tightness * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are more likely to be filled later.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes: 0..10
    match class {
        0 => score -= 30.0,           // post_residual 0..9: near-perfect fit
        1 => score -= 22.0,           // 10..19: excellent dead-space class
        2 => score -= 15.0,           // 20..29
        3 => score -= 9.0,            // 30..39
        4 => score -= 4.0,            // 40..49
        5 => score += 3.0,            // 50..59: half-empty, mediocre
        6 => score += 6.0,            // 60..69
        7 => score += 9.0,            // 70..79
        8 => score += 12.0,           // 80..89
        9 => score += 15.0,           // 90..99
        _ => score += 20.0,           // 100: untouched bin
    }

    // Modulo arithmetic on post_residual: residues divisible by common item
    // size classes (10/20/25/50) are "reusable" residues.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
    }

    // Lookahead coupling: reward bins whose post_residual class matches the
    // next item size class (so next item lands exactly).
    if next_item_size > 0 {
        let next_class = (next_item_size / 10).max(1);
        let post_class = if pr == 0 { 0 } else { ((pr - 1) / 10) + 1 };
        if post_class == next_class {
            score -= 18.0;
        } else if pr >= next_item_size {
            // next item still fits but not perfectly
            score -= ((pr - next_item_size) as f64) * 0.15;
        } else {
            // post_residual cannot host next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.10;
        }
        // Harmonic residue match: pr mod gcd-like small classes vs next item
        if next_item_size <= 20 && pr % 20 >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin fit
    // is terrible (post_residual large) or stream is early with few bins.
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the very first bin
        }
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        if progress < 0.1 {
            score -= 5.0;
        }
    }

    // Slight preference to keep mean residual low (compact packing).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Tie-break: prefer bins with more residual used so far.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving residual that can fit the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // next item can't use leftover
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones,
    // penalize opening new bins unless fit is clean.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        score += 15.0 * pressure;
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        score -= 3.0 * pressure;
    }

    // Prefer bins whose residual is close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Slight preference for bins below mean residual (fill emptier-relative bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Late in stream: be more conservative, avoid creating dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: reward proportionally to tightness of that future fit
            let future_tightness = next_item_size as f64 / post_residual as f64;
            score -= 50.0 + 80.0 * future_tightness;
        } else {
            // next item does not fit: penalize wasted space relative to next item size
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Reward bins whose residual is already small (compact bins first)
    let tight = bin_residual as f64 / bin_capacity as f64;
    score += 30.0 * (1.0 - tight);

    // Penalize bins with residual far below mean residual (fragmented outliers)
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last chance: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 150.0 + 20.0 * desperation;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Late in stream: prefer closing bins out, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item.
    if post_residual < 1 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score += 6.0; // tiny dead zone
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // post residual can't host next item; penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // or few bins are open relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 40.0 - 20.0 * progress + 5.0 * pressure;
        // If next item is large and this bin is fresh, a new bin is reasonable.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild penalty when placing into a bin whose residual deviates far above mean
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for using more-filled bins early (best-fit bias over time).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio * (0.5 + 0.5 * (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: smooth quadratic coupling of post_residual with item size.
    let tight = 1.0 - (post / cap).powf(2.0);
    score -= 12.0 * tight * (item_size as f64 / cap);

    // Prefer bins whose residual is close to the item (smooth kernel around exact fit).
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score -= 8.0 * (-diff * diff * 40.0).exp();

    // Dead-space penalty: small post-residuals that are still unusable for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 6.0 * (1.0 - post / nx.max(1.0)) * (0.5 + progress);
        } else {
            // Reward bins that can still host the lookahead item snugly.
            let gap = (post - nx) / cap;
            score -= 4.0 * (-gap * gap * 60.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, allow opening late or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 9.0 * (1.0 - progress) * (1.0 - crowding);
        score -= 3.0 * progress * crowding;
    }

    // Mild preference for bins with residuals near the mean (balance residual spread).
    score += 1.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Smooth late-stream consolidation: favor filling existing bins as stream progresses.
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Harmonic class penalty: dead space in awkward classes gets punished.
        let pr = post_residual;
        let class = match pr {
            0..=10 => 0,
            11..=25 => 1,
            26..=50 => 2,
            _ => 3,
        };
        score += class as f64 * 6.0;
        // Modulo coupling: residuals divisible by common item chunks (10, 20, 25, 50)
        // are more reusable by future items.
        let reusable = (pr % 10 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
        score -= reusable as f64 * 8.0;
        // Integer-division threshold: residual in [next_item_size ..= next_item_size+15]
        // is perfectly shaped for the lookahead item.
        if next_item_size > 0 {
            let nd = next_item_size;
            if pr >= nd && pr <= nd + 15 {
                score -= 25.0;
            } else if pr < nd {
                // dead space smaller than next item: penalize proportionally
                score += (nd - pr) as f64 * 0.5;
            }
        }
    }

    // Waste relative to capacity fraction.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Prefer reusing bins when mean residual is high; open new bin when residuals are tiny
        // and stream is early (long horizon to amortize the new bin).
        score = 55.0 + (1.0 - pressure) * 20.0 - (1.0 - late) * 10.0;
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open with low residuals.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are already counted by post_residual, but gaps
    // in the "hard-to-fill" band (1..=12) are heavily penalized since they
    // are unlikely to be filled by future items drawn from an unknown
    // distribution.  Scale the penalty sharply as the gap shrinks.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 12.0 {
            // Dead-space band: the smaller the gap, the worse the waste.
            score += (13.0 - gap) * 6.0;
        }
    }

    // Reward extremely tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open
    // without consolidating; encourage filling bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin (which would
    // strand the residual space in this bin forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // New-bin candidate logic: an empty bin should only win when existing
    // bins would leave bad dead space.  Give the empty bin a mild baseline
    // handicap so tight fits in open bins are preferred, but relax it when
    // the item is large relative to typical residuals.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_gap = mean_residual;
        // If mean residual across open bins is much larger than the item,
        // open bins are fragmented; opening a fresh bin is less costly.
        let fragmentation = (mean_gap - item_size as f64).max(0.0) / bin_capacity as f64;
        score += 10.0 - 20.0 * fragmentation - 5.0 * fill_ratio;
    }

    // Mild preference for bins whose residual is close to the item size
    // (best-fit core), layered under the dead-space penalty.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits heavily.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space penalty: small residuals are hard to reuse later.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0;
        }
    }

    // 2-step lookahead: reward residuals that match the next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            // Perfect match for the next item is excellent.
            let gap = pr - nx;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // Also reward post-residual >= next item generally (keeps future options).
            score -= 10.0;
        } else {
            // Next item won't fit in this bin's leftover: penalize proportionally.
            score += (nx - pr) * 0.5;
        }
    }

    // Compare residual against mean residual across open bins:
    // leaving this bin far below average residual concentrates waste here.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let diff = (mean_residual - pr) / mean_residual;
        if diff > 0.0 {
            score -= 15.0 * diff.min(2.0); // favor bins that keep more usable space than average
        } else {
            score += 10.0 * (-diff).min(2.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Early in the stream, prefer filling existing bins to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Discourage opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: when many bins are open, prefer consolidating (avoid sprawl).
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    // Deviation from mean residual: prefer bins near the mean (balanced packing),
    // penalize very full bins slightly less as stream progresses.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, accept decent fits to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: only attractive when no good existing option
    // is likely (item large relative to residuals, few fitting bins).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (1.2 - 0.4 * pressure - 0.3 * large_item) + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth progress-weighted penalty: residual dead space matters more late in stream
    let prog_term = norm_pr * norm_pr * (1.0 + 2.0 * progress * progress);
    score += 20.0 * prog_term;

    // Reward tight fits: small post_residual gets smooth quadratic bonus
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bin: strong smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: penalize if post_residual can't fit next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr >= nxt) as i32 as f64;
        let gap = ((nxt - pr).max(0.0)) / cap;
        score -= 10.0 * fits * (1.0 - progress);
        score += 12.0 * gap * gap * cap * 0.01;
    }

    // Mean residual coupling: penalize bins deviating from mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight penalty for many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but rescale residuals
    // into "harmonic classes" via integer division on capacity fractions.
    let residual_class = post_residual / (bin_capacity / 4); // classes: 0..3
    score += residual_class as f64 * 3.0;

    // Dead-space penalty: residuals too small for typical items (<= 9) are wasted.
    if post_residual < 10 {
        score += 25.0;
    }

    // Harmonic bonus: post_residual that is an exact divisor-friendly class
    // (mod arithmetic on small integers) is more reusable.
    let pr = post_residual as i64;
    let reuse_bonus: f64 = if pr > 0 {
        let mut b = 0.0;
        if pr % 10 == 0 { b += 6.0; }
        if pr % 20 == 0 { b += 4.0; }
        if pr % 25 == 0 { b += 3.0; }
        if pr % 50 == 0 { b += 3.0; }
        b
    } else { 0.0 };
    score -= reuse_bonus;

    // Lookahead: reward if next item fits in the post residual (chaining),
    // penalize if next item almost fits (near-miss creates pressure).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // extra reward for exact modular match of next item size class
            if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 3.0;
            }
        } else if next_item_size <= post_residual + 9 {
            score += 6.0; // near-miss: next item won't fit, dead space likely
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are quite full on average or many bins already exist.
    if bin_residual == bin_capacity {
        // new empty bin gets neutral residual cost (100) plus dynamic terms
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= mean_residual * 0.4;      // if existing bins are full, new bin ok
        score += open_bins_count as f64 * 1.5; // discourage bin proliferation early
        score -= progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin mandatory
        }
    } else {
        // Existing bin: mild bonus for keeping bins consolidated.
        score -= 5.0;
        // Prefer bins with residuals near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Progress-based tie-breaking: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (smaller than the minimum plausible next item) are heavily penalized.
    let dead_zone = 15.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Non-linear reward for tight fits (best-fit core with sharpening).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // if post residual is just barely too small for next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // favor filling existing bins when bin count is already high.
    let pressure = open_bins_count as f64;
    score += pressure * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish score so it's chosen only when
    // all open bins are poor fits; slight penalty rises with stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if no open bin can fit, opening is fine (fitting_bins_count
        // still counts this bin, so detect via mean residual mismatch).
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild mean-residual alignment: prefer bins whose residual is near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportional to overshoot
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize creating tiny dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let new_bin_base = 0.55 * bin_capacity as f64; // base reluctance
        score = new_bin_base
            - 30.0 * crowding
            - (if fitting_bins_count <= 1 { 20.0 } else { 0.0 })
            - (if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity { 15.0 } else { 0.0 });
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 12.0 * fit_ratio;
    }

    // Penalize large dead space relative to typical upcoming item sizes.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 8.0; // tiny waste is fine
    } else if dead >= 10.0 && dead < item_size as f64 {
        score += 0.05 * dead; // moderate dead space
    } else if dead >= item_size as f64 {
        score += 0.15 * dead; // big leftover that could trap future items
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize wasting residual on a bad split
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor and many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && open_bins_count > 2 {
            score -= 10.0 + 20.0 * (1.0 - progress);
        } else {
            score += 35.0; // discourage opening bins when a decent fit exists
        }
    }

    // Global state coupling: when mean residual is low, conserve space in roomy bins.
    if mean_residual < 15.0 && !is_new_bin {
        score -= 6.0;
    } else if mean_residual > 40.0 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // Time horizon: late in the stream, be conservative; avoid creating fragmented bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins with larger residuals when few bins are open (consolidation).
    if open_bins_count <= 2 && !is_new_bin {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let p = 1.0 - progress;
    // Smooth interaction: residual waste matters more as stream progresses.
    score += 8.0 * x * x * (0.5 + progress) * cap;

    // Reward near-perfect fits with a smooth cubic term.
    score -= 6.0 * (1.0 - x).powi(3) * (1.0 + progress);

    // Penalize residuals that cannot accommodate the lookahead item (smooth falloff).
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * gap * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward leaving space exactly usable by next item (smooth quadratic).
        let diff = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - diff * diff);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild preference to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    // Prefer bins with residuals close to mean residual (smooth Gaussian-like term).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: only attractive early or for large items with poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 4.0 * progress * cap * 0.1 + 2.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: partition residual space into deciles of capacity.
    let class_post = (post_residual / 10) as f64;
    let class_next = (next_item_size / 10) as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly, but reward residual classes
        // that remain "usable" (multiples of 10 align with item granularity).
        let dead = post_residual as f64;
        score += 0.02 * dead * dead / cap;

        // Harmonic-class alignment: if post residual class matches the next
        // item's class, this bin likely hosts the next item too.
        if next_item_size > 0 && class_post == class_next {
            score -= 8.0;
        }
        // Next item fits exactly into the post residual: chain placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 60.0;
        }
        // Next item fits but leaves awkward remainder (small odd class).
        if next_item_size > 0 && next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 6.0; // creates sub-10 sliver next step
            } else {
                score -= 2.0 * ((next_post / 10) as f64);
            }
        }
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when mean residual is low.
    if open_bins_count > 0 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);
    }

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // New-bin candidate: neutral-ish, only chosen when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early stream: opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // (min item size is 1, but tiny gaps rarely match future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // hard penalty for creating a sliver gap
    } else if post_residual < 20 {
        score += 8.0; // soft penalty for small gaps
    }

    // Reward tight fits (post_residual small relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 12.0 * tightness;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so it's chosen only when no good fit exists,
    // with mild relaxation as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: mildly discourage accumulating many open bins,
    // encouraging consolidation into existing bins.
    score += (open_bins_count as f64) * 0.15;

    // Dead-space coupling: if this bin's residual is far below the mean,
    // it's already fragmented; encourage filling it rather than leaving it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.05 * dev;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward, scaled by how well it uses the space.
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * usage;
        } else {
            // Next item cannot use the leftover space: penalize large dead space.
            let dead = post_residual as f64;
            score += 0.15 * dead;
            // Extra penalty if next item would need a fresh bin anyway.
            if next_item_size > bin_residual {
                score += 5.0;
            }
        }
    }

    // Compare residual against mean residual across open bins:
    // leaving this bin with less residual than average concentrates waste favorably.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.10 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize choosing a fresh bin when existing bins fit reasonably well,
    // unless the item is large and would leave a big residual anyway.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, opening bins is cheaper; late in the stream, consolidate.
        let new_bin_penalty = 20.0 + 15.0 * progress;
        score += new_bin_penalty;
        // But if the item would leave a tiny residual in any bin anyway, a fresh
        // bin is fine — soften the penalty slightly for large items.
        if item_size >= 90 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins (smaller bin_residual) when scores tie.
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that nothing can fill (min item size 1,
    // but small residuals under ~10 are hard to use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for "wasting" this bin's future.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 1 {
        score -= 6.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Late in the stream, favor filling existing bins over opening new ones.
    score -= 10.0 * progress;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if existing bins would leave large unusable gaps, new bin becomes viable.
        let waste_if_forced = (bin_residual - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if waste_if_forced > 40.0 && next_item_size > waste_if_forced as u32 {
            score -= 25.0; // poor fits everywhere and next item needs fresh space
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with residuals close to item size (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 60.0 * poly * (0.5 + progress);

    // Penalize dead space that no typical item can fill, more as stream matures
    let dead = (pr - (next_item_size as f64)).max(0.0);
    score += 0.8 * dead * (0.3 + 0.7 * progress);

    // Reward exact-ish fits smoothly
    score -= 25.0 * (-pr / 12.0).exp();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Lookahead: reward residual matching next item smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.15 * diff;
        score -= 10.0 * (-diff / 15.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: tight fits are strongly favored
    score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Harmonic classes: reward post_residual in "small" residue classes
    // that are likely fillable by typical small items (multiples of 10 and small values)
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else if pr <= 10 {
        score -= 18.0;
    } else if pr % 10 == 0 {
        score -= 10.0; // harmonic class: multiples of 10 are easy to fill
    } else if pr < 20 {
        score -= 6.0;
    } else {
        // penalize awkward dead space in awkward classes
        let awkward = pr % 10;
        score += 0.8 * awkward as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= 8.0 * (next_item_size as f64 / pr as f64);
            // harmonic match: both in same modulo-10 class
            if next_item_size % 10 == pr % 10 {
                score -= 5.0;
            }
        } else {
            score += 4.0; // next item cannot use this bin's residue
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are bad
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so good existing fits win
        score += 15.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin more attractive
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: favor filling existing ones
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit a typical future item (10..80 range) but aren't zero.
    if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when fits exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.5 * (open_bins_count as f64) * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins open.
    if open_bins_count > 2 {
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual < 10 {
            score += 50.0; // but still avoid creating dead space
        }
    }

    // Lookahead: if next item fits the post-residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Lookahead penalty: post_residual too small for next item but nonzero (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate calibration: opening a new bin should only win when all
    // open-bin options are poor. Base new-bin score = post_residual (=capacity-item).
    // Add moderate pressure so open bins with decent fits still win.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is forced
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    score *= 1.0 + 0.5 * (item_size as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - next;
            score -= 25.0 * (-gap / 20.0).exp(); // near-match bonus decaying with gap
        } else {
            // next item cannot follow here; penalize proportionally to waste
            score += 10.0 * (next - post_residual as f64) / 20.0;
        }
    }

    // Relative residual context: bins already tight vs mean residual.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if no existing bin fits well (post_residual large) the base term already helps
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual + 5.0 {
            score += 10.0; // slightly discourage new bin when an open bin chains well
        }
    }

    // Late in the stream, tighten up: prefer closing bins, avoid sprawl.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: mildly discourage adding residual-heavy placements.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how well the item fills the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 12.0;

    // Penalize very small post-residuals that are below the minimum item size
    // (dead space): residual > 0 but nothing can ever use it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 8.0;  // usable residual for the next item
        } else {
            score += 4.0;  // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be conservative (prefer compacting
    // into few bins); late in the stream, tolerate opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * fill;

    // Global state: if many open bins with large mean residual, prefer
    // filling existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let crowding = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= crowding * 5.0;
        } else {
            // New-bin candidate: penalize when existing bins are roomy,
            // reward when open bins are nearly full.
            score += crowding * 15.0 - 5.0;
            if post_residual < 20 {
                score += 10.0; // new bin would be nearly full immediately: bad
            }
        }
    }

    // Slight preference for bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_ratio = post_residual as f64 / cap;

    // Reward tight fits (small post_residual), scaled non-linearly by progress.
    let tightness = (1.0 - post_ratio).powi(2);
    score -= 18.0 * tightness * (0.5 + progress);

    // Penalize dead space that is too small for typical future items,
    // with a smooth polynomial coupling to stream progress.
    let dead = (post_ratio * (1.0 - post_ratio)).powi(2);
    score += 12.0 * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            let k = (gap / cap * std::f64::consts::PI).cos();
            score -= 6.0 * k.max(0.0) * (1.0 - progress);
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Prefer bins with residuals below the mean (consolidating fuller bins).
    score += 2.0 * ((post_residual as f64 - mean_residual) / cap).tanh();

    // New-bin candidate: penalize mildly so we reuse open bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of capacity wasted
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 30.0;

    // Harmonic classes: residual buckets by integer division thresholds
    // Residuals in (0..10] are near-perfect; large residuals are dead space unless reusable
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0; // small dead space, acceptable
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    } else if post_residual > 25 && post_residual <= 50 {
        score += 25.0;
    } else if post_residual > 50 {
        score += 35.0;
    }

    // Modulo classes on post_residual: multiples of common item sizes are reusable slots
    let common: [u32; 6] = [10, 20, 25, 30, 40, 50];
    for &c in common.iter() {
        if post_residual >= c && post_residual % c == 0 {
            score -= 20.0;
            break;
        }
    }
    // Next item fits exactly into post_residual -> strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        if leftover2 == 0 {
            score -= 300.0;
        } else if leftover2 <= 10 {
            score -= 120.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; residual becomes dead space
        score += 25.0 + post_residual as f64 * 0.2;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // many open bins with small mean residual: avoid adding another
        if mean_residual < 30.0 && open_bins_count > 3 {
            score += 80.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size <= 30 {
            score -= 50.0; // big item may deserve fresh bin
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1..=9) are pure waste — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize if the leftover cannot fit the next item but the next item
    // is large (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit would create dead space; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        if fitting_bins_count > 0 && post_residual < 10 {
            score += 20.0; // don't open a bin to make dead space
        }
        if mean_residual >= item_size as f64 * 1.5 {
            score += 25.0; // existing bins have room; keep consolidating
        }
        score += pressure * 3.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Open-bin pressure: mild penalty for scattering across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

