    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0; // opening fresh is great if it perfectly chains
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly (waste minimization core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100,
    // treat residuals < 10 as nearly dead, residuals near 100 as reusable).
    if post_residual < 10 {
        score += 25.0; // creating unusable sliver
    } else if post_residual > 80 {
        score -= 4.0; // keeps a large flexible residual
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins; discourage new bins.
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
        score += 15.0 + 3.0 * pressure + 10.0 * t;
        // new bin is fine if the item is huge relative to capacity and nothing fits well
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Slight preference for bins with residual close to item (best-fit flavor)
        let gap = (bin_residual - item_size) as f64;
        score += 0.08 * gap;
        // If this bin's residual is far below mean residual, it's a good closer.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream, be greedier: minimize immediate waste.
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: penalize post residual, smoothly warped
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth non-linear coupling: quadratic penalty on post_residual scaled by fill tightness
    let tight = (1.0 - pr / cap).clamp(0.0, 1.0);
    score -= 20.0 * tight * tight * fit_ratio;

    // Interaction of post_residual with stream progress (cubic in progress)
    let prog_term = progress * progress * (3.0 - 2.0 * progress);
    score += pr * 0.3 * prog_term;

    // Dead space avoidance: post residual just below typical item sizes is bad
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (larger residuals) slightly
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score = cap * (1.2 - 0.8 * prog_term) - 10.0 * scarcity;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that cannot fit typical small items
    let pr = post_residual;
    if pr > 0 {
        // classify residual into harmonic buckets via integer division
        let class = pr / 10; // 0..10
        match class {
            0 => score -= 25.0,          // residual < 10: nearly perfect fit, reward strongly
            1 => score -= 12.0,          // residual 10-19: fits smallest items
            2 | 3 => score += 2.0,       // mid dead space
            4 | 5 | 6 => score += 6.0,   // 40-69: awkward zone
            _ => score += 1.0,           // large residual: bin still flexible
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Fractional coupling: how well item divides the residual (harmonic fit)
    if bin_residual > 0 {
        let frac = item_size as f64 / bin_residual as f64;
        if frac > 0.9 {
            score -= 15.0;
        } else if frac > 0.5 {
            score -= 4.0;
        } else {
            score += 4.0 * (1.0 - frac);
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0; // creating dead space the lookahead cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer crowded bins when many bins are open (consolidation pressure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Penalize bins far below mean residual (fragmenting)
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: neutral baseline with slight conservatism early
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use
    // are heavily penalized (unusable small gaps become wasted capacity).
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        // tiny dead gap: nearly worthless
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot fit the lookahead item: likely dead space
        score += 15.0 + 0.25 * (post_residual as f64);
    } else if next_item_size > 0 && post_residual == next_item_size {
        // gap exactly fits the next item: excellent
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 10.0; // comfortably reusable gap
    }

    // Reward tight fits relative to item size (small waste ratio).
    score += 0.5 * (item_size as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score -= 80.0; // near-perfect last chance
        } else if waste < 0.5 {
            score -= 25.0;
        } else {
            score -= 5.0; // weak preference; new bin may be better
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and encourage consolidating into bins with larger residuals.
    if bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 0.15 * (open_bins_count as f64) * (1.0 - progress);
        // prefer bins whose residual is above the mean (more usable space left)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    } else {
        // New-bin candidate: penalize when open bins exist and mean residual
        // can still accommodate the item reasonably well.
        if open_bins_count > 0 {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let mean_can_fit = mean_residual >= item_size as f64;
            let mut new_bin_penalty = 20.0 + 3.0 * (open_bins_count as f64) * (1.0 - progress);
            if mean_can_fit {
                new_bin_penalty += 10.0;
            }
            // allow new bin late in stream when fragmentation is high
            score += new_bin_penalty;
        } else {
            score -= 100.0; // first bin ever: always open it
        }
    }

    // Slight preference for bins whose residual exceeds the next item even after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty on dead space: post_residual that is too small to hold
    // any future item (min size 1..100 stream) is waste; penalize quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // 2-step lookahead: perfect match if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 60.0; // exact 2-step chain completion
            } else {
                // reward closeness of next item to post_residual
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item can't fit: dead space confirmed for at least one step
            score += 15.0 + (nxt - pr);
        }
    } else {
        // last item: prefer tightest fit only
        score += 5.0;
    }

    // Compare post_residual against mean residual: leaving a residual near the
    // mean keeps bins homogeneous; extreme residuals (very small) are penalized.
    if pr < mean_residual {
        score += 0.8 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless almost nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no open bin fits, allow opening a new bin (soften the penalty).
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 10.0 * progress;
        }
    }

    // Slight preference for bins that are already heavily loaded (best-fit bias).
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 30.0; // perfect lookahead fit
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize bins far below mean residual (wasteful use of a full bin)
    // and reward bins near mean (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Time horizon: early on, be willing to open new bins for large items;
    // late in stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; few open bins: encourage using them.
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).ln();
    }

    // New empty bin candidate: only attractive when item is huge relative to
    // residual structure or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / bin_capacity as f64).powi(3) * 60.0;
        score += 55.0 - big_item_bonus;
        if post_residual > 0 && next_item_size > post_residual {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste matters more early, tight fits matter more late.
    let tightness = 1.0 - (pr / cap);          // 0 = full bin, 1 = empty
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score -= poly * (cap - pr) * 0.35;          // reward tight fits increasingly over time
    score += (1.0 - poly) * tightness * tightness * 4.0; // penalize large residuals early

    // Penalize dead space that no plausible item can use (items >= 1, up to 100).
    let dead = (pr * pr) / cap;
    score += dead * 0.6;

    // Perfect fit reward, smoothly scaled.
    if post_residual == 0 {
        score -= 25.0 + 15.0 * poly;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * (1.0 - tightness);
    }

    // Lookahead: bonus if next item fits the post-residual exactly or well.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= (1.0 - gap / cap) * 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: mild penalty for stranded space.
        score += (pr / cap) * 3.0;
    }

    // Discourage hoarding many open bins with large mean residual.
    score += (open_bins_count as f64).ln1p() * 0.8;
    score -= (mean_residual / cap).ln1p() * 1.5;

    // New-bin candidate: penalize opening a bin unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 6.0 + 10.0 * (1.0 - fragmentation) - 4.0 * poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item-size divisors are more likely to be filled by later items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        40.0 // perfect fit
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else if pr % 2 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: tiny unusable remainders are worse than mid ones.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize lightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // New-bin candidate: make it moderately attractive only when the stream
    // is early or current bin fits are poor; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 18.0 + 25.0 * (1.0 - progress) - 2.0 * openness;
        if mean_residual > 30.0 {
            score -= 8.0; // open bins are roomy, reuse them
        }
    }

    // Mild mean-residual alignment: bins close to the mean are "typical"
    // targets; keep them attractive to consolidate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold on next_item_size class.
    if next_item_size >= 50 {
        score += 2.0; // big next item: keep small residuals for it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (high fill ratio of the gap).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: penalize bins whose residual is far below mean
    // (they are nearly full and precious); favor bins with typical residual.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item could exactly fill the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item can't use the gap: dead space likely, penalize.
            score += (post_residual as f64) * 0.5;
        }
    }

    // New-bin candidate handling: attractive early / under pressure,
    // but penalized late in the stream to force consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        score += 35.0 * progress;
        score += open_bins_count as f64 * 0.8;
        // If a decent fit exists elsewhere (several fitting bins), new bin is less urgent.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact or near-perfect chaining with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here; prefer small leftover slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.25;
        } else {
            // Next item won't fit; penalize dead space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Penalize large unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny residual is nearly perfect packing
    } else if post_residual >= 10 {
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.20;

    // Mild pressure to close out bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0;

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual, non-linear).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 45.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residuals that no typical item (>=1) can use are bad,
    // but very small residuals (< ~10) are effectively dead.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let nx_tight = 1.0 - (post_residual as f64 - nx) / cap;
            score -= 30.0 * nx_tight;
        } else {
            // Post-residual can't host next item: penalize proportionally to how close it was.
            let gap = (next_item_size as u32 - post_residual) as f64;
            if gap < 20.0 {
                score += 0.8 * gap;
            }
        }
    }

    // New-bin candidate handling: empty bin gets baseline around cap/2,
    // adjusted by global state. Prefer new bin when open bins are fragmented
    // (mean residual low relative to item) or many bins already open.
    if bin_residual == bin_capacity {
        score = cap * 0.5;
        // Fragmentation pressure: if mean residual across open bins is small,
        // opening fresh space is attractive.
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 40.0 * (1.0 - frag);
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // Many open bins: discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is large, fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size > post_residual.max(next_item_size) {
            score -= 10.0;
        }
        // Last-chance override: never open a new bin when only one bin fits.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    // Mild preference for bins with residuals near item size (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Global waste pressure: bins with residual far from mean residual get slight
    // normalization pull.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement
    let mut score = post;

    // Smooth polynomial penalty on waste, stronger as stream progresses
    let post_norm = post / cap;
    let prog = progress.clamp(0.0, 1.0);
    score += (1.0 + 2.0 * prog) * post_norm * post_norm * cap * 0.5;

    // Perfect-fit reward: subtract when post_residual is small
    score -= (1.0 - post_norm).powi(4) * 8.0;

    // Lookahead coupling: penalize if next item can't use the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next > post {
            score += (next - post) * (0.3 + 0.7 * prog);
        } else {
            score -= 4.0 * (1.0 - (next / (post + 1.0)));
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Attractive early / when few bins or item is large
        let item_frac = item_size as f64 / cap;
        let openness = open_bins_count as f64;
        let new_bin_pull = 20.0 * (1.0 - prog) + 10.0 * item_frac
            + 5.0 * (1.0 - (openness / (openness + 4.0)));
        // But discourage when mean residual across open bins is large
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score += cap - new_bin_pull + 30.0 * mean_norm * prog;
    } else {
        // Slight preference for tighter bins among open ones
        let res_norm = (bin_residual as f64 / cap).clamp(0.0, 1.0);
        score += 3.0 * res_norm * res_norm;
    }

    // Mild coupling with mean residual: prefer bins near the mean (keeps distribution balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post-residual falls into
    // "small" residue classes are nearly sealed -> reward using them.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fill: extremely desirable.
        score -= 1000.0;
    } else if pr <= 10 {
        // Dead space below the minimum item size: bin is effectively closed.
        score -= 300.0;
    } else {
        // Classify leftover by integer division into harmonic buckets of 10.
        let bucket = pr / 10; // 1..=9 for capacity 100
        // Smaller buckets (tighter leftovers) are better: subtract by bucket size.
        score -= (10 - bucket) as f64 * 12.0;
        // Odd/even harmonic coupling: leftover matching next item's size class
        // is valuable when lookahead exists.
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Next item fits exactly in this bin's leftover: strong reward,
                // scaled by how snugly it fits.
                let snug = (pr - next_item_size) as f64;
                score -= 80.0 - snug * 2.0;
                // Harmonic resonance: same decade class between leftover and next item.
                if (pr / 10) == (next_item_size / 10) {
                    score -= 25.0;
                }
            } else {
                // Next item cannot use this leftover: mild penalty for wasting
                // potential on a bin that will strand this residual.
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin gives a good fit. Penalize opening a
    // new bin when the current item is small relative to capacity (better to
    // pack into existing slack), but reward it for very large items.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Base cost of opening a bin, discounted for large items.
        score += 120.0 - fill_ratio * 100.0;
        // If many bins are open, discourage adding more unless item is huge.
        if open_bins_count > 4 {
            score += (open_bins_count as f64) * (1.0 - fill_ratio) * 5.0;
        }
    } else {
        // Reward placing into bins whose residual is close to the item
        // (best-fit coupling beyond raw post_residual).
        let tightness = (bin_residual - item_size) as f64;
        score -= (cap - tightness) * 0.0; // no-op placeholder coupling
        // Favor bins with residual near harmonic boundaries (multiples of 25):
        // leftover at 25/50/75 aligns with common item size classes.
        let res_mod = bin_residual % 25;
        if res_mod == 0 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: when average slack across open bins is small,
    // conserve new bins (favor open bins); when large, new bins are cheaper.
    let slack = mean_residual / cap;
    if bin_residual != bin_capacity {
        score -= (1.0 - slack) * 20.0;
    }

    // Early-stream bias: keep bins open longer early, seal later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable by items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }
    // Moderately small gaps are risky too (most items 10..80 won't fit).
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would not fit post-residual, mild penalty unless gap is tiny.
    if next_item_size > post_residual && post_residual >= 25 {
        score += 8.0;
    }

    // New-bin candidate: attractive when open bins are fragmented or fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score -= 20.0 + fragmentation * 0.5 + open_bins_count as f64 * 0.8;
        // But discourage new bins when a tight fit exists.
        if post_residual == 0 { score -= 0.0; }
        if fitting_bins_count <= 2 && item_size >= bin_capacity / 2 {
            score += 25.0; // big item: better to use an existing fitting bin
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it matches
            let match_q = 1.0 - (post_residual as f64 - nxt) / cap;
            score -= 40.0 * match_q * match_q;
        } else {
            // next item cannot use the leftover: penalize small dead space
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 25.0 * (10.0 - waste);
            } else {
                score += 5.0;
            }
        }
    }

    // Tight fit reward: small post_residual is good, but avoid leaving tiny unusable slivers.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 80.0; // bin closed perfectly
    } else if pr < 10.0 {
        score += 15.0; // sliver likely wasted
    }

    // Compare against mean residual: prefer bins already "committed" (below mean residual).
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * t * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, this bin becomes very valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Penalize wasted residual that no plausible item (min 1..=100 range) can use well:
    // dead space beyond 50 is unlikely to be filled.
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.8;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is penalized when open bins could fit,
    // unless the item fits poorly everywhere (large residual waste elsewhere).
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64; // mean residual of open bins vs fresh
        score += 18.0;
        if spread > 25.0 {
            score -= spread * 0.5; // open bins are quite full -> new bin attractive
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin keeps flexibility for the lookahead item
        }
    }

    // Time horizon: early in the stream, be frugal (penalize opening bins);
    // late in the stream, tight fits dominate anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Prefer filling bins that are already well-loaded relative to the mean residual
    // (keeps many low-residual bins, leaves flexible bins open).
    if bin_residual < bin_capacity {
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 6.0;
        if (bin_residual as f64) < mean_residual {
            score -= 4.0; // tighter than average bin
        }
    }

    // Mild penalty for proliferating open bins when a fit exists elsewhere.
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 30.0 * fit * fit * (1.0 - progress);

    // Coupling: residual vs lookahead smoothness
    if nxt > 0.0 {
        let diff = norm_pr - nxt;
        score += 25.0 * diff * diff;
        score -= 15.0 * norm_pr * nxt;
    }

    // Mean residual interaction (smooth)
    let mr = mean_residual / cap;
    score += 10.0 * (norm_pr - mr) * (norm_pr - mr);

    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Open bins pressure, smooth in progress
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: tiny residuals are nearly useless
        if post_residual <= 10 {
            score += 40.0;
        } else if post_residual <= 25 {
            score += 12.0;
        }
        // Reward residual sizes in "harmonic" slots that match common item sizes
        let pr = post_residual;
        let fits_common = (10..=80).step_by(10).any(|s| s <= pr);
        if fits_common {
            score -= 15.0;
        }
        // Lookahead coupling: residual that can host the next item is valuable
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 8.0;
        }
    }

    // New-bin candidate (empty bin): discourage unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * mean_residual < 0.5 * cap;
        let poor_fit = post_residual > 0 && post_residual < 20;
        if fitting_bins_count > 1 && !poor_fit {
            score += 500.0;
        } else if fitting_bins_count == 1 && !poor_fit && !crowded && progress < 0.9 {
            score += 150.0;
        } else {
            score -= 30.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mild preference for bins tighter than the mean residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight scaling of residual penalty by stream progress
    score += 0.1 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1 in the general interface) are pure waste; penalize the "nearly
    // full but not full" zone quadratically.
    if post_residual > 0 {
        score += 30.0 / (post_residual as f64).sqrt();
        if post_residual <= 10 {
            score += 25.0; // unusable sliver
        } else if post_residual <= 25 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fit: fully closed bin
    }

    // Reward tight fits relative to the item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last usable bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins, penalize opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): only attractive if the item is large and
    // no existing bin fits well (post_residual small relative to capacity).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 18.0;                       // base cost of opening a bin
        score += 40.0 * waste * waste;       // opening with lots of leftover space is bad
        if next_item_size as f64 <= post_residual as f64 * 0.9 && next_item_size > 0 {
            score -= 8.0; // fresh bin can likely also host the next item
        }
    } else {
        // Existing bin whose leftover exactly accommodates the lookahead item.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 6.0; // leftover will be dead for the known next item
        }
    }

    // Prefer bins below the mean residual (tighter bins get filled first),
    // keeping looser bins available for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post residual) relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // 2-step lookahead: strongly reward if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial credit proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does not fit: penalize leaving a gap it almost fills
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is only chosen when open bins score worse.
        score += 40.0;
        // Early in the stream, opening bins is cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many bins are open already, discourage opening another.
        score += 2.0 * open_bins_count as f64;
    }

    // Penalize leaving large unusable dead space (small post residual is good,
    // but a large post residual that nothing can use is bad).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold any plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize leaving a large unusable gap
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: cheaper later in the stream when many bins are open.
        let open_cost = 60.0 - 30.0 * progress;
        score = open_cost + (bin_capacity - item_size) as f64;
        // If many bins can fit the item, opening new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If the only fitting option is a poor fit, opening a fresh bin becomes attractive.
        if fitting_bins_count == 1 && fit_ratio < 0.35 {
            score -= 15.0;
        }
    }

    // Global state: if mean residual is high, prefer spreading load into bins with large residual.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Mild preference for balancing number of open bins early in the stream.
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear residual shaping: penalize large residuals super-linearly,
    // but with progress-dependent curvature (late stream -> tighter packing).
    let pr_norm = pr / cap;
    let curvature = 1.0 + 1.5 * progress;
    score += 20.0 * pr_norm.powf(curvature);

    // Reward near-perfect fits with smooth polynomial bonus.
    let fit_quality = 1.0 - (pr_norm - 0.5) * (pr_norm - 0.5) * 4.0; // peaks at pr_norm=0.5
    score -= 10.0 * fit_quality * fit_quality;

    // Smooth coupling with mean residual: prefer bins deviating from the mean
    // (consolidate residual mass), scaled by stream progress.
    let dev = (pr - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress) + 5.0 * progress;
    }

    // Lookahead: penalize leaving residual just below next item (smooth valley).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score -= 12.0 * g * (1.0 - g) * (1.0 - progress);
        }
        // If next item exactly fits post-residual, strong smooth reward.
        if (gap.abs() < 1.0) {
            score -= 10.0;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.5 * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: which residue class mod common item sizes
    let pr = post_residual as u32;
    let classes = [10u32, 20, 25, 40, 50, 80];
    let mut harmonic_bonus = 0.0f64;
    for c in classes {
        if pr >= c && pr % c == 0 {
            harmonic_bonus += 6.0; // perfectly divisible residual -> reusable
        }
    }
    score -= harmonic_bonus;

    // Fraction of capacity used after placement
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 12.0 * fill * fill;

    // Penalize small dead space (unusable slivers)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
    } else if next_item_size > pr && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a bin when a good fit exists
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap)).max(1.0);
        score += 30.0 + 10.0 * pressure;
        if pr == bin_capacity {
            score -= 45.0; // no alternative: new bin must win
        }
    }

    // Stream progression: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill;

    // Prefer bins with residual far from mean residual (diversity of classes)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold typical future items are waste.
    // Treat post_residual < 10 as fully dead; taper up to a "usable" threshold.
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 3.0; // small gap => heavy extra penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item can still fit after this placement
        score -= 5.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer
    // filling existing bins, but when very few bins are open, allow new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave a large unusable residual or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted if item is large (hard to place later)
        score = 60.0 - (item_size as f64) * 0.4;
        if fitting_bins_count <= 1 {
            score += 10.0; // opening new bin while another fits is wasteful
        }
        if item_size > 70 {
            score -= 15.0; // big items: better to start fresh bin
        }
    }

    // Prefer bins with residuals close to the item (minimizes leftover spread).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Mean residual coupling: placing into a bin far above mean residual
    // (an outlier gap) is good if the fit is tight.
    if (bin_residual as f64) > mean_residual + 20.0 && fill_ratio > 0.7 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (chain packing), penalize when next item would
    // leave a large dead gap.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 300.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much it consumes
            let consumed_ratio = ni / pr;
            score -= 60.0 * consumed_ratio;
            // extra bonus if the pair nearly fills the bin
            if post_residual - next_item_size <= 10 {
                score -= 60.0;
            }
        } else {
            // next item won't fit here: penalize large leftover relative to next item
            let waste = (ni - pr) / ni.max(1.0);
            score += 40.0 * waste;
        }
        // Penalize post_residual that is too small for typical future items
        if post_residual < next_item_size && post_residual < 15 {
            score += 25.0;
        }
    }

    // Compare post-residual against mean residual of open bins:
    // leaving less than average waste is good, more than average is bad.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let diff = pr - mean_residual;
        score += 0.8 * diff;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open a new bin when many bins are open and residual
        // space is fragmented (high mean residual = poor fits available)
        score -= 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 40.0; // big next item benefits from a fresh bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 60.0; // existing bins can still serve the next item
        }
    }

    // Mild pressure against accumulating many open bins late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight default bias against new bins, decaying with poor-fit pressure.
        score += 8.0;
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
        // If many open bins have large mean residual, discourage a new bin.
        score += 0.3 * mean_residual;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.1 * item_size as f64;
    }

    // Prefer fuller bins overall: compare bin_residual to the mean residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0; // this bin is fuller than average -> good
        } else {
            score += 1.5; // emptier than average -> deprioritize
        }
    }

    // Mild pressure to close out bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Quadratic + cubic shaping: small residuals become exponentially more valuable
    // as the stream progresses (waste hurts more late in the stream).
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * pr_norm * pr_norm * pr_norm * (1.0 + progress * 3.0);
    score += 30.0 * poly;

    // Smooth interaction: exact-ish fits (tiny post_residual) get progressive reward.
    let tightness = (1.0 - pr_norm).powi(6);
    score -= 12.0 * tightness * (0.5 + progress);

    // Lookahead coupling: reward residuals that still fit the next item smoothly,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening a bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // Mild competition term: prefer bins where alternatives are scarce.
        score += 2.0 / fitting_bins_count as f64;
    }

    // Mean-residual coupling: placing into a bin below mean residual leaves the
    // larger residuals for future large items (smooth divergence penalty).
    score += 0.05 * (mean_residual - pr).max(0.0) * (1.0 + progress);

    // New-bin candidate handling: brand-new empty bin should only win when the
    // item fits poorly everywhere. Penalize it smoothly, with relief at high progress.
    if bin_residual == bin_capacity {
        let waste = 1.0 - (item_size as f64) / cap;
        score += 15.0 * waste * waste + 10.0 * (1.0 - progress);
        // If item is large, filling a fresh bin is less wasteful.
        score -= 8.0 * (item_size as f64 / cap);
    }

    // Slight penalty for proliferating open bins late in the stream.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Residuals in coarse classes (multiples of 10) are more reusable than odd ones.
    let post = post_residual as u32;
    let class = post % 10;
    let class_penalty = match class {
        0 => -6.0,          // perfectly aligned leftover, highly reusable
        5 => -3.0,          // half-class, still decent
        2 | 4 | 6 | 8 => 2.0, // even but misaligned
        _ => 6.0,           // odd leftover, hard to fill with typical items
    };
    score += class_penalty;

    // Integer-division threshold: does the leftover still admit a "large" item (>= 30)?
    if post >= 30 {
        score -= 5.0;
    } else if post > 0 {
        // Small dead space: penalize proportionally to how dead it is.
        score += 4.0 * (1.0 - post as f64 / 30.0);
    }

    // Perfect fit reward: harmonic alignment of item with residual.
    if post == 0 {
        score -= 25.0;
    } else if bin_residual % item_size.max(1) == 0 {
        score -= 8.0; // item divides residual evenly -> harmonious packing
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            let nxt_class = (post - next_item_size) % 10;
            if nxt_class == 0 {
                score -= 6.0;
            } else if nxt_class <= 4 {
                score -= 2.0;
            } else {
                score += 2.0;
            }
        } else {
            // Next item cannot use the leftover: mild penalty for wasted alignment.
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit would create bad dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer spreading load early / when open bins are already tight.
        let tightness = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // Large items fragment bins badly; favor fresh bin for them.
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || tightness < 0.25 {
            score -= 12.0 + 6.0 * progress;
        } else {
            score += 10.0; // keep using open bins when fit is decent
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Fractional capacity coupling: reward placements leaving residuals near
    // common item-size fractions (capacity/4, capacity/3, capacity/2).
    let cap = bin_capacity as f64;
    for frac in [cap / 4.0, cap / 3.0, cap / 2.0] {
        if (post as f64 - frac).abs() < 3.0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for the smallest plausible item, i.e. < 10) are poison.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // perfect fill is fine (post_residual == 0), tiny gaps are not
    }
    if post_residual == 0 {
        score -= 25.0; // exact fit: zero waste, heavily favored
    }

    // Non-linear penalty: quadratic growth of wasted-space cost,
    // but only for gaps that are unlikely to be filled later.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 30.0 {
        score += (30.0 - gap) * (30.0 - gap) * 0.05; // small gaps get steep extra penalty
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this bin strongly (creates a chain of fills).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item cannot use this bin's gap: gap is more likely dead space
            score += gap * 0.3;
        } else {
            // next item fits, but leaves another gap; mild penalty proportional to new gap
            let next_gap = (post_residual - next_item_size) as f64;
            if next_gap < 10.0 && next_gap > 0.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so give it a handicap).
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 1.5;
        // but late in the stream, new bins are less costly to open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 3.0;
    }

    // Prefer bins whose residual is already below average (consolidate waste)
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: mild reward proportional to tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0); // reward up to 20, decaying as slack grows
    }

    // Dead space: post_residual too small for next item -> penalize
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 15.0 * deadness;
    }

    // Zero residual = perfectly closed bin, ideal
    if post_residual == 0 {
        score -= 80.0;
    }

    // Compare residual against mean residual: prefer filling below-average bins harder
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: only one fitting bin available, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if some open bin fits tightly
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 {
            // opening new bin leaves full residual for future; slightly cheaper when
            // next item is large and current bin fit would be wasteful
            let waste = post_residual as f64; // = capacity - item_size
            if waste > 50.0 { score -= 5.0; }
        }
        // fewer open bins -> new bin is cheaper to justify
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Late in stream: consolidate, discourage new bins further
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that likely cannot be reused by typical items (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly useless
    }

    // Lookahead: reward if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if this bin becomes stranded
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; decreases as stream progresses
        // (opening early is cheaper, amortized over more future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 25.0 * progress;

        // If many open bins with large mean residual, opening new is less attractive.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward using existing bins, more so when they are already partially filled
        // and below mean residual (consolidate fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        // Encourage filling fuller bins first (best-fit with fullness bias).
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Global pressure: when many bins are open relative to stream length, pack tighter.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += pressure * 20.0 * tightness;

    // Mild stochastic-free tie-breaking by residual ordering.
    score += post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: waste grows super-linearly in post_residual, amplified by stream progress
    let norm_post = post / cap;
    score += norm_post * norm_post * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (post / (bin_residual.max(1) as f64));
    score -= tightness * tightness * (item_size as f64) * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Penalize opening a new bin when other bins fit, more so early and when mean residual is large
    if bin_residual == bin_capacity {
        let others_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += others_fit * (30.0 + 20.0 * (1.0 - progress)) + mean_residual * 0.3;
        // Still allow new bins late in stream when residuals are fragmented
        score -= (open_bins_count as f64).min(10.0) * 0.5 * progress;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let nxt = next_item_size as f64;
        let slack = 1.0 - ((post - nxt) / cap).abs();
        score -= 8.0 * slack * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize unusable dead space
        score += 4.0 + (post / cap) * 6.0 * progress;
    }

    // Mild preference to consolidate across few bins
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in [0,10) -> near-perfect fit, strong reward.
    if post_residual < 10 {
        score -= 40.0;
    }
    // Class B: dead-space band (10..=25) -> penalize unusable slivers.
    else if post_residual <= 25 {
        score += 12.0;
    }
    // Class C: post_residual exactly divisible into common item-size blocks
    // (residual usable by typical small items 10..80 in whole chunks).
    else {
        let div10 = post_residual % 10 == 0;
        let div5 = post_residual % 5 == 0;
        if div10 { score -= 8.0; }
        else if div5 { score -= 3.0; }
        // Fractional capacity classes: residual >= 3/4 cap -> still roomy.
        if pr >= 0.75 * cap { score -= 4.0; }
        else if pr < 0.25 * cap { score += 6.0; }
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly
    // or within a harmonic class boundary.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = next_item_size == post_residual;
        let near = post_residual - next_item_size <= 10;
        if exact { score -= 25.0; }
        else if near { score -= 10.0; }
        // next item leaves a divisible residual too (double-harmonic chain)
        if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting capacity.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening penalty so we
    // prefer existing bins unless their scores are bad; penalty shrinks as the
    // stream progresses (early on, fresh bins are cheap).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        score += 20.0; // base cost of opening a new bin
    }

    // Prefer bins whose residual is below the mean (fill tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger gaps that remain usable: mild reward proportional to tightness.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness;
    }

    // Coupling: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item would not fit: penalize proportionally to how much it misses.
        let miss = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
        score += 0.5 * miss;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += 0.02 * pressure * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave
    // bad dead space or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 20.0 };
        score += 15.0 + bad_fit_penalty - 0.1 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Penalize wasting a large bin residual on a small item when other bins exist.
    if bin_residual >= bin_capacity && item_size < 20 && open_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward: post_residual close to 0 is great.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 20.0;
            } else {
                // penalize leftover dead space after hypothetical next placement
                score += slack as f64 * 0.15;
            }
        } else {
            // next item won't fit here; leftover post_residual is dead space
            score += post_residual as f64 * 0.1;
        }
    }

    // Relative to mean residual: prefer bins that are already well filled
    // (low residual relative to mean) to consolidate waste.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and few bins are open.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 25.0 * fill_frac - 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins overall as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space relative to the mean residual across open bins:
    // if this bin's post residual is much larger than the mean, it is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: reward bins whose post residual could host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use (dead space risk),
        // scaled by how close we are to the end of the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a bin when the item is large relative to capacity
        // (large items pack cleanly into fresh bins).
        score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // Opening a bin is more attractive when open bins are crowded with residuals
        // unlikely to fit future items.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        // If this is the only fitting bin, opening a fresh bin is fine.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for keeping the number of open bins low when fits are decent.
    if post_residual < 20 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fits (low post residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate waste, late in stream penalize it strongly
    let coupling = pr_norm * (1.0 - progress) * (progress * progress + 0.5 * progress);
    score += 40.0 * coupling;

    // Penalize creating dead space smaller than the next item's needs
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * gap;
        // reward if next item fits exactly in the residual left behind
        if next_item_size as f64 <= pr {
            score -= 2.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0));
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // New-bin candidate: mildly discourage opening bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Discourage bins whose residual deviates far from the mean (fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), but only if the leftover is
    // "dead space" — i.e. the lookahead item cannot use it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fits_next = next_item_size > 0 && next_item_size <= post_residual;

    if !fits_next {
        // Dead-space penalty: tiny leftovers below the minimum item size (1)
        // are perfect fits; moderately small leftovers are wasted.
        if post_residual == 0 {
            score -= 25.0; // perfect closure
        } else if post_residual < 10 {
            score -= 12.0;
        } else if post_residual <= 20 {
            score -= 6.0;
        }
    } else {
        // Lookahead synergy: leftover exactly hosts the next item.
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }

    // Harmonic class logic: classify post_residual by capacity fractions
    // (capacity / 4, /3, /2). Residuals near these fractions are more
    // likely to be fillable by future items.
    let quarters = post_residual % (bin_capacity / 4).max(1);
    if quarters == 0 {
        score -= 4.0;
    }
    let thirds = post_residual % (bin_capacity / 3).max(1);
    if thirds == 0 {
        score -= 3.0;
    }
    let halves = post_residual % 2;
    if halves == 0 {
        score -= 1.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fullness),
    // scaled by stream progress.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * (0.3 + 0.4 * progress);

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless the item is huge relative to
    // every residual (poor fit elsewhere). The base post_residual of an
    // empty bin is already large; add an adaptive surcharge that shrinks
    // when the item is large and no good home exists.
    if bin_residual == bin_capacity {
        let surcharge = 18.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - if fitting_bins_count == 0 { 12.0 } else { 0.0 };
        score += surcharge.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum plausible
    // item size (1..=100 domain, but tiny gaps are near-wasted) are heavily
    // penalized non-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 5.0 {
            score += 60.0 * (6.0 - pr); // near-total waste penalty
        } else if pr <= 15.0 {
            score += 25.0 * (1.0 + (15.0 - pr) / 10.0);
        }
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits generally: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * pr;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // placement would create bad dead space.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Base cost of a new bin, discounted by pressure and stream progress.
        score += 70.0 - 12.0 * pressure.min(5.0) - 15.0 * progress;
        // Lookahead: opening a bin is good if the next item can use leftovers
        // of existing bins anyway.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 20.0; // existing bins likely absorb next item; don't hoard capacity
        }
    } else {
        // Placing into an existing bin: mild reward scaled by open-bin pressure
        score -= 4.0 * (open_bins_count as f64).sqrt();
        // Lookahead synergy: leftover after placement should fit next item
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                score -= 15.0;
            } else if post_residual > 0 {
                score += 8.0; // leftover likely wasted
            }
        }
        // Prefer bins whose residual is already below average (consolidate waste)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(8);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = pr - ns;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.5 * (ns - pr).min(80.0);
        }
    }

    // Compare residual against mean residual across open bins:
    // a bin with residual far below mean is "tighter" -> good target.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit,
    // unless the current bin is nearly full (small post_residual).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0
            + 0.8 * mean_residual
            + (open_bins_count as f64).sqrt() * 6.0;
        score += new_bin_penalty;
        // but if next item is large and post_residual small, new bin is fine
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 30.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes even more valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // penalize leaving a residual that is awkwardly large but still
            // barely consumed by the next item
            score += 0.05 * slack_after_next as f64;
        } else {
            // next item won't fit here; mild penalty for wasting lookahead space
            score += 0.5;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual > 30 {
            // but if it creates lots of dead space, soften the last-chance reward
            score += 0.2 * (post_residual as f64 - 30.0);
        }
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.01);
    score += 1.5 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (balances residuals across bins, keeping mid-size gaps usable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: late in the stream, tighten up more aggressively
    // (less room to recover from fragmentation).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.6 * t;

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a decent fit, or the item is large relative to capacity.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // base penalty so existing bins are preferred unless they fit badly
        score += 18.0;
        // large items justify opening a fresh bin more readily
        score -= 0.15 * item_size as f64;
        // if many bins are open and fragmented, fresh bin is more acceptable
        score -= 2.0 * open_pressure;
        // if the only alternative leaves huge dead space, new bin looks better
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    score += 12.0 * (x * x) * (1.0 + t);
    score -= 20.0 * x * (1.0 - x) * (1.0 - t);

    // Perfect-fit reward (smooth)
    score -= 15.0 * (1.0 - x).max(0.0) * x.max(0.0);

    // Penalize residuals that cannot fit the lookahead item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (nx - pr) as f64;
        let s = 1.0 / (1.0 + (-0.3 * gap).exp());
        score += 8.0 * s;
        // Reward leaving exactly enough space for the next item
        score -= 10.0 * (-0.5 * (pr - nx).abs()).exp();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - t);
    }

    // Pull toward mean residual (balance bins smoothly)
    score += 0.05 * (pr - mean_residual) * (1.0 - x);

    // Discourage opening new bins late when bins are available
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group dead space quality.
    let pr = post_residual;
    let class = pr % 10;
    // Class 0 residuals are "harmonic" slots (likely to fit future items exactly).
    score -= if class == 0 { 12.0 } else { 0.0 };
    // Small odd dead space (1..=9) is nearly unusable: penalize.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }
    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr <= quarter {
        score += 6.0; // tight but awkward
    } else if pr <= half {
        score -= 4.0; // usable half-ish space
    }

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic if slack lands on a class-0 multiple
            if slack % 10 == 0 { score -= 8.0; } else { score += slack as f64 * 0.15; }
        } else {
            score += 5.0; // next item cannot use this bin's leftover anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual small) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 30.0 + 40.0 * crowd * (1.0 - progress) - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        return score;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Early stream: consolidate into few bins; late: fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    // Items are 1..100; a residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Coupling: prefer bins whose residual is close to the item (tight fit),
    // measured relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the new-bin candidate and mildly reward reusing open bins).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure-scaled cost.
        score += 15.0 + 70.0 * pressure;
        // If this is the only fitting option, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it over opening a new bin.
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual - next_item_size < 10 {
            score -= 35.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // Next item cannot use this tiny gap; penalize.
        score += 20.0;
    }

    // Stream progression: late in the stream, waste matters more (no future
    // to amortize), so push toward tightest fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if this bin's residual is far below the mean,
    // it's a "small" bin already; using it consolidates waste.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact chain match is heavily rewarded; near matches decay quadratically.
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        if gap == 0.0 {
            score -= 25.0; // exact 2-step chain closure
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportional to wasted chain potential.
        let waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        score += 4.0 * waste / 100.0;
    }

    // Penalize residuals too small for typical future items (dead space), scaled by stream position.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 10.0 * progress;
    }

    // Compare against mean residual: bins already below mean should absorb the item
    // (keeps large residual bins available for large future items).
    score -= 3.0 * (mean_residual - post_residual as f64) / 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would be badly fragmented.
    let bad_fit = (post_residual as f64) > 0.5 * (bin_capacity as f64)
        && next_item_size > 0
        && post_residual < next_item_size;
    if bin_residual == bin_capacity {
        if bad_fit || (fitting_bins_count > 0 && (post_residual as f64) < mean_residual * 0.5) {
            score -= 8.0; // opening fresh bin is fine when fits are poor
        } else {
            score += 30.0; // discourage opening new bins when good fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is exponentially good).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0 / post_residual as f64;
    } else {
        // Penalize large post residuals quadratically (wasted capacity).
        score += (post_residual as f64).powi(2) / 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let post = post_residual as f64;
            // Prefer leaving a residual that pairs well with next item.
            let pair_waste = post - nxt;
            score -= 40.0 / (1.0 + pair_waste);
        } else {
            // Next item won't fit here: slight penalty for creating a stranded small gap.
            if post_residual < next_item_size {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: discourage opening a new bin when the item
    // fits reasonably in an existing bin; encourage when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If open bins are fragmented (high mean residual spread vs item),
        // opening fresh is more attractive.
        if mean_residual > (bin_capacity as f64) * 0.6 && open_bins_count > 0 {
            score -= 60.0;
        }
        // Big items prefer a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 70.0;
        }
        // Early in stream, prefer consolidating into open bins less strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 80.0;

    // Slightly prefer bins with below-mean residual (consolidate fragmented bins).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Mild penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial core: penalize large leftover, reward tight fits
    let mut score = 3.0 * x * x + 1.5 * x * x * x;

    // Smooth interaction with stream progress: late in stream, prefer tighter packing
    score += (0.5 + 2.0 * progress) * x * x;

    // Coupling with mean residual: penalize deviating from fleet mean smoothly
    let mean_x = mean_residual / cap;
    score += 0.8 * (x - mean_x) * (x - mean_x);

    // Lookahead coupling: smooth quadratic reward if next item fits the post residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        let gap = pr - nxs;
        if gap >= 0.0 {
            score -= 1.2 * (1.0 - (gap / cap) * (gap / cap));
        } else {
            score += 0.6 * (-gap / cap);
        }
    }

    // Last-chance bonus: smooth penalty when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 2.0;
    } else {
        score += 0.3 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for opening new bins when many exist (new-bin candidate has x == 1)
    if open_bins_count > 0 {
        score += 0.05 * (open_bins_count as f64).ln() * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are
    // "harmonically aligned" with typical item sizes (divisible into nice chunks).
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that split evenly into small harmonic classes
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 1.5 + (d as f64) * 0.02;
                break;
            }
        }
        // Penalize tiny unusable dead space (nonzero small residuals)
        if pr < 10 {
            score += 6.0;
        } else if pr < 20 {
            score += 2.5;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 4.0;
            } else {
                score += slack * 0.05;
            }
        } else {
            // next item won't fit here; mildly reward keeping bigger residual bins free
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (waste of the whole capacity concept)
        score += 30.0;
        // Attractive if item is large relative to capacity and open bins are fragmented
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        if frag < 0.35 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 5.0;
        // Large items justify fresh bins
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Prefer tightest existing fit: reward small bin_residual minus item
        score -= (bin_capacity - bin_residual) as f64 * 0.02;
        // Prefer bins with residual close to item (best-fit coupling)
        let diff = (bin_residual - item_size) as f64;
        score += diff * 0.10;
    }

    // Slight preference to fill bins with larger existing fill (fewer open bins)
    if open_bins_count > 4 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }
    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: reward bins that become well-filled.
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fill * fill;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && bin_capacity >= post_residual;
    if new_bin {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // But allow a new bin if the item would leave a huge unusable gap in any bin anyway.
        if post_residual as f64 > mean_residual * 0.6 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nx = next_item_size as f64;
        if nx <= gap {
            score -= 18.0 * (1.0 - nx / (gap + 1.0));
        } else {
            score += 10.0 * ((nx - gap) / 100.0);
        }
    }

    // Mild alignment with mean residual: prefer bins near the mean to keep balance.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Stream progression: early on, be more tolerant of opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
