pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio * fill_ratio;
        // Penalize large dead space that few items could ever use.
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // Lookahead: bonus if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0;
            // Extra reward for near-perfect two-item packing.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap <= 5.0 {
                score -= 10.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only mildly, so tight-fit logic dominates.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: late in stream, be conservative — fill bins tighter,
    // avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive if
    // no open bin fits well. Default new-bin score slightly above a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If item is large, a fresh bin wastes little, so soften the penalty.
        score -= 0.1 * item_size as f64;
        // Late stream: new bins are expensive.
        score += 10.0 * progress;
        // If only one bin fits, opening a new bin is wasteful.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post_residual, but with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate waste; later, demand tight fits.
    let progress_weight = 2.0 + 6.0 * progress * progress;
    score += progress_weight * norm_pr * pr * 0.1;

    // Smooth reward for near-perfect fits (small post_residual), stronger late
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 4.0 * tightness * (0.5 + progress);

    // Lookahead coupling: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.6 * (diff / cap) * (1.0 - progress);
        // bonus if next item fits exactly in post_residual
        if next_item_size as f64 <= pr {
            score -= 1.5 * (1.0 - diff / cap) * (0.3 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress + 0.02 * open_bins_count as f64;
        // but late in stream with many open bins of high residual, opening is fine
        if pr / cap > mean_residual / cap {
            score -= 1.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (keeps spread balanced)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Slight preference for fuller bins overall
    score -= 0.5 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: opening a bin is a last resort.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.15 * open_bins_count as f64;
        // Opening a bin is fine if it creates a near-perfect fit and future items are large.
        if post_residual <= 10 && next_item_size >= 40 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins with large leftover space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * post_residual as f64 * 0.5;
        return score;
    }

    // Harmonic class of the post-residual: reward residuals that are
    // "nice" fractions of capacity (multiples of 10, 25, 50) since future
    // items in the 1..100 range more often complement them.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 50 == 0 { score -= 8.0; }
        // Integer-division threshold classes: small residuals are dead space.
        let class = post_residual / 10; // 0..=9
        score += class as f64 * 2.0;    // bigger leftover -> worse
        if post_residual < 10 { score += 15.0; } // unusable dead space penalty
        if post_residual < 5 { score += 20.0; }
    }

    // Lookahead coupling: if the next item exactly complements this residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let new_res = post_residual - next_item_size;
            if new_res % 10 == 0 { score -= 10.0; }
            if new_res < 5 { score += 8.0; } else { score -= 4.0; }
        } else {
            // Next item won't fit here; residual becomes stranded for lookahead.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for fewer open bins: filling any existing bin is good.
    score -= 1.0;

    // Progress calibration: late in the stream, squeeze bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 12.0; // tiny slivers are worst outcome
    } else if pr >= 10.0 && pr < 25.0 {
        score += (25.0 - pr) * 3.0; // moderate dead space penalty
    }

    // Reward near-perfect fills strongly.
    if pr == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Open-bin pressure: prefer spreading when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 90.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a new bin is fine early in the stream or when few bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin mandatory
        }
    }

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0;
        } else {
            // next item cannot use leftover; penalize dead space scaled by gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than the mean residual
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great chain start
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // new bin could host item + next item comfortably
            if item_size + next_item_size >= (bin_capacity as f64 * 0.9) as u32 {
                score -= 120.0;
            }
        }
        if item_size > 70 {
            score -= 60.0; // big items are fine to start fresh
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    // Mild penalty for many open bins already
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small for the smallest possible item is wasted.
    if post_residual < 1 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        // residual below the historical minimum item size -> dead space
        score += 25.0 + 5.0 * (10 - post_residual) as f64;
    }

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // extra reward if leftover fits next item almost exactly
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (-slack / 15.0).exp();
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Fit-quality: prefer tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Prefer filling bins that are already low on residual (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: neutral-to-slightly-high baseline so it wins
    // only when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 45.0
            + 10.0 * (step_index as f64 / total_items.max(1) as f64)
            - 3.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild scaling with number of open bins: encourage using existing bins
    // when many are open, but allow new bins when few are open.
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr;

    // Polynomial coupling: residual value modulated by progress curve
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: mild quadratic shaping; late stream: stronger cubic penalty on large residuals
    score += norm_pr * (1.5 + 6.0 * p2 + 10.0 * p3) * 10.0;

    // Reward tight fits: subtract smooth function of normalized post residual
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap > 0.0 {
            let waste = gap / cap;
            score += waste * waste * 30.0 * (1.0 + progress);
        } else {
            // Next item fits exactly-ish: reward
            score -= 8.0 * (1.0 - gap.abs() / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate shaping: empty bin gets a smooth penalty that grows with progress
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * p2 + 15.0 * p3;
    }

    // Slight preference for bins with residuals near the mean (keeps spread tight)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets and reward "usable" leftover classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Reward residuals that land in "harmonically useful" classes:
    // exact multiples of small divisions are easier to fill later.
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post < eighth {
        score -= 25.0; // tiny dead space, acceptable
    } else if post % quarter == 0 {
        score -= 20.0; // quarter-aligned leftover
    } else if post % eighth == 0 {
        score -= 12.0; // eighth-aligned leftover
    } else if post <= quarter {
        score -= 8.0;  // small but not aligned
    } else if post >= 3 * quarter {
        score -= 5.0;  // large residual: bin still very usable
    } else {
        score += 10.0; // awkward middle zone: penalize
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post && post - next_item_size < eighth {
            score -= 18.0;
        } else if next_item_size > post {
            // next item won't fit here: mild penalty scaled by wasted fraction
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post <= eighth {
            score -= 10.0; // good fit in last-chance bin
        }
    }

    // New-bin candidate handling: make a fresh bin attractive only when
    // existing fits are poor (large awkward residual) or bins are many.
    if bin_residual == bin_capacity {
        score = 0.5 * cap - 0.3 * cap * (post_residual as f64 / cap);
        // open new bin more readily early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter packing pressure on emptier bins).
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Slight preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (sizes >= 1, but
    // realistically tiny gaps below 10 are near-unusable) are heavily punished.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward filling bins tightly relative to the residual used.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: many open bins -> prefer using existing ones
    // (penalize opening new bins).
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large or no good fit exists;
    // otherwise make it unattractive so existing bins get used.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.7 {
            score -= 15.0; // large items are fine to start a fresh bin
        } else {
            score += 35.0; // small/medium items should use existing space
        }
        // Extra penalty for opening bins when few items remain to place.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (chaining fits).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap
        // that nothing else can use.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to consolidate space into fewer bins.
    let diff = mean_residual - post_residual as f64;
    score += diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on leftover space (dead space is bad).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: leftover after next item determines quality.
            let second_left = post_residual - next_item_size;
            score -= 25.0 - (second_left as f64) * 0.3;
        } else {
            // Next item does NOT fit: this bin will be dead for next item.
            score += 15.0;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is close to item_size (tight fit) relative to fleet.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if item is small and stream is early, a fresh bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    // Mild preference to fill existing bins as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving small dead space (< 10, unusable for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in the post-residual, reward preserving this bin's usefulness.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin can't serve the next item but another placement might; mild penalty.
            score += 8.0;
        }
        // If next item exactly matches post_residual, big bonus (chained packing).
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalty grows with crowding and mean tightness; shrinks late in stream.
        score += 55.0 * crowding * (0.5 + mean_tight) * (1.0 - 0.4 * progress);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // fresh bin can host the next item too
        }
    } else {
        // Mild preference for reusing existing bins over opening new ones.
        score -= 5.0;
    }

    // Prefer filling bins with larger residual gaps when many bins are open (consolidation).
    if open_bins_count > 3 {
        let gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let prn = pr / cap;
    score += (prn * prn) * (1.0 + 2.0 * prog3) * 10.0;

    // Perfect-fit reward, strengthened as stream progresses
    if post_residual == 0 {
        score -= 50.0 + 30.0 * progress;
    }

    // Penalize large dead space quadratically with progress
    score += (prn * prn * prn) * 20.0 * (0.5 + progress);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * prog2;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - prn);
        } else if post_residual > 0 && nxt > pr {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Discourage scattering residual mass relative to mean residual
    score += (pr - mean_residual) * (0.2 + 0.4 * progress);

    // New-bin candidate: mildly penalize early, allow later
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals near capacity fractions
    // that are reusable by typical item sizes (multiples of 10 classes).
    let pr = post_residual as u32;
    let class = pr % 10;
    let class_bonus = match class {
        0 => 6.0,                 // perfectly reusable residual (e.g. 10,20,...)
        5 => 4.0,                 // half-class, still very usable
        1 | 9 => 2.0,
        2 | 8 => 0.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Reward tight fits: post_residual small relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residual too small for smallest plausible item
    if pr > 0 && pr < 10 {
        score += 15.0; // dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // how well next item harmonically divides the residual
            let k = pr / next_item_size.max(1);
            let leftover = pr - k * next_item_size;
            score -= 10.0 / (1.0 + leftover as f64);
        } else {
            // next item won't fit here; mild penalty scaled by gap
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly more when
    // existing bins have plenty of room (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 25.0
            - 3.0 * (open_bins_count as f64).sqrt()
            + 0.1 * (mean_residual - cap * 0.5).max(0.0);
        // Opening a new bin is fine if current item is huge and next is small
        if next_item_size > 0 && next_item_size < item_size / 2 {
            score -= 8.0;
        }
    }

    // Early stream: be greedy with tight fits; late stream: consolidate
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 2.0 * tightness;
    score += t * (post_residual as f64 / cap) * 3.0;

    // Prefer filling bins whose residual is close to the mean (balance classes)
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to ever hold a future item are "dead space".
    // Penalize them heavily; moderate residuals are useful and slightly rewarded.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // should not happen, but guard
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else {
        // Dead-space zone: residual too small for anything meaningful.
        // Treat residuals < 10 as almost-dead (items >= 10 in classic case, but
        // sizes go down to 1 here, so weight by how "hard to reuse" it is).
        let dead_threshold = 12u32;
        if post_residual <= dead_threshold {
            // The smaller the leftover, the more dead it is relative to use.
            score += (dead_threshold - post_residual + 1) as f64 * 8.0;
        } else {
            // Usable residual: mild reward proportional to future packing room.
            score -= (post_residual as f64).ln() * 6.0;
        }
    }

    // Reward tightness: how well the item fills the bin relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // --- Open bins pressure ---
    // Too many open bins: discourage spreading; favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += bin_pressure * 4.0;

    // Deviation from mean residual: prefer bins whose residual is near/below
    // the mean (i.e., bins that are already fairly full get priority).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.15;

    // --- Last-chance bin ---
    // If this is the only bin that fits the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post-residual, big reward;
    // if the next item cannot fit in post-residual but fits elsewhere,
    // mild penalty for leaving a mismatched gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin has bin_residual == bin_capacity. Opening a new
    // bin is only attractive when the current item is large and no good fit
    // exists elsewhere. Make the new-bin score unattractive by default, but
    // let it win when the item nearly fills a fresh bin and other bins are tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 60.0 + 3.0 * open_bins_count as f64;
        // But if the item fills most of a fresh bin, opening is good.
        if fill_ratio > 0.8 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating rather than opening.
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: item + next fills bin exactly
        } else if post_residual as u32 >= next_item_size {
            // next item fits here too: mild reward proportional to tightness
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit after placing here: penalize leaving awkward gap
            score += 0.5 * (post_residual as f64 - nxt).max(0.0).min(20.0);
        }
    }

    // Prefer tight fits: small post_residual relative to capacity
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Compare against mean residual across open bins
    score += 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for keeping number of open bins low
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small to be useful for typical items.
        if post_residual < 10 {
            score += 12.0;
        } else if post_residual < item_size.min(20) {
            score += 4.0;
        }
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // If next item fits exactly after this placement, big bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins are open and fragmented, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Prefer bins with residual below mean (fuller bins) to keep large residuals concentrated.
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs() - (bin_residual as f64 - mean_residual)) * 0.1;

    // New-bin candidate: penalize opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual < 10 && fitting_bins_count <= 2);
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 25.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score -= poly * 60.0 * (0.5 + progress);

    // Penalize residual that is too small to be useful later, more so early on
    let dead = if prn < 0.1 { (0.1 - prn) * (0.1 - prn) * 10.0 } else { 0.0 };
    score += dead * (1.5 - progress);

    // Reward tight fits relative to mean residual of open bins
    let tight = (mean_residual - pr).max(0.0) / cap;
    score -= tight * 20.0 * (1.0 - progress);

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead coupling: prefer leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += (nx - pr) * 0.15;
        } else {
            score -= (gap / cap) * 6.0 * (1.0 - progress * 0.5);
        }
    }

    // Mild penalty for opening many bins
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make it unattractive unless residual would be very tight
    if bin_residual == bin_capacity {
        score += 5.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual;
    let class_small = if pr < 10 { 0 } else if pr < 20 { 1 } else { 2 };
    // Dead space penalty: residual that no typical item can use
    if pr > 0 {
        let dead = ((10u32).saturating_sub(pr.min(10))) as f64;
        score += dead * 4.0;
    }
    // Perfect-fit harmonic classes: post_residual divisible by common item sizes
    if pr > 0 {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50, 80] {
            if pr % d == 0 { bonus += 6.0; }
        }
        score -= bonus;
    }
    // Integer-division thresholds on post_residual
    let q = pr / 10;
    score -= (q as f64) * 1.5; // prefer bins with more usable leftover granularity

    // Lookahead coupling: does post_residual fit next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect lookahead fit
        } else if next_item_size <= pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= fit_frac * 8.0;
            // harmonic match: next_item_size and post_residual share a divisor class
            if pr % next_item_size == 0 { score -= 5.0; }
        } else {
            score += 6.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (pr as f64) / cap; // = 1.0 for empty bin
        score += 30.0 - 20.0 * progress; // early: prefer filling open bins
        if item_size as f64 / cap > 0.8 { score -= 35.0; } // huge item: fresh bin is fine
        let _ = waste;
    } else {
        // tightness reward: fraction of bin used
        let tight = item_size as f64 / bin_residual.max(1) as f64;
        score -= tight * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a scarce small bin
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Many open bins: encourage consolidation
    score += (open_bins_count as f64) * 0.05;

    // class_small tiebreak: prefer leaving mid-range residuals over tiny dead space
    score += class_small as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize "unusable" small gaps: post_residual in [1, 15] is dead space
    // that few future items (min size 1..100 unknown, but small gaps rarely reusable).
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 12.0;
    }
    // Zero waste is the ideal: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect-fit style: residual just below typical small item threshold is bad.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    }

    // Open bins pressure: discourage spreading across many bins when residual is loose.
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // (large post_residual) or bin is nearly empty already.
    if bin_residual == bin_capacity {
        // A fresh bin has huge residual: penalize mildly so it loses to decent fits,
        // but it will win against very poor fits due to the dead-space penalties above.
        score += 30.0;
        // If the next item is large and this item leaves a bad gap, opening a new
        // bin keeps flexibility: reward new bin when lookahead is big.
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if post_residual is smaller than next item AND nonzero (blocked gap).
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 4.0;
    }

    // Mean residual coupling: when mean residual across bins is low, conserve bins.
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Slight preference for filling fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: strong bonus (subtraction).
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            // Next item fits: bonus proportional to closeness of match.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving a dead residual smaller than next item.
            score += 15.0 + diff * 0.3;
        }
        // Small dead space (<10) is nearly unusable: extra penalty.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average (best-fit flavor).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate logic: an empty bin gets a baseline score of full capacity.
    // Make opening a new bin attractive only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a decent fit, below a wasteful fit.
        score = bin_capacity as f64 * 0.75 + 0.5 * mean_residual;
        // If many bins are open, prefer consolidating (penalize new bins mildly).
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheap.
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - t);
        }
        // If lookahead item is large relative to item, a fresh bin may serve both.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Waste ratio term: penalize bins where the item fills a small fraction of residual.
    if bin_residual > 0 {
        let waste = 1.0 - (item_size as f64 / bin_residual as f64);
        score += 8.0 * waste * waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Bonus for near-exact two-item chaining.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; mildly penalize large leftover.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins: competition high, prefer the best fit (tightness already does this),
    // but slightly penalize spreading across many bins when few are open.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be conservative (avoid wasting big residual bins);
    // late in the stream, be aggressive at filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global residual state: if mean residual is high, prefer bins far from the mean
    // that would be brought close to the mean (balance), otherwise prefer tight fits.
    let post_f = post_residual as f64;
    let mean_gap = (post_f - mean_residual).abs();
    score += 0.05 * mean_gap * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item is large relative to capacity, opening a fresh bin is more attractive.
        score -= 0.15 * item_size as f64;
        // If next item is also large, a fresh bin is useful for it too.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score += 0.03 * open_bins_count as f64 * (post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 90.0 * norm_pr * norm_pr + 40.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: early on, waste tolerance is higher; late, be stricter.
    score *= 1.0 + 0.8 * progress * norm_pr - 0.3 * (1.0 - progress) * norm_pr;

    // Lookahead: reward if next item fits exactly into post_residual (perfect chaining).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let chain_fit = 1.0 - (pr - nx) / cap;
            score -= 25.0 * chain_fit * chain_fit;
        } else {
            // Next item cannot follow here: penalize blocking large residuals.
            score += 6.0 * (1.0 - progress) * norm_pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Competition: mild tie-breaking toward tighter fits.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or many bins are already open with high mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        let bad_fit_pressure = (mean_residual / cap - norm_pr).max(0.0);
        score += 60.0
            - 45.0 * fit_quality * fit_quality
            - 15.0 * progress
            - 8.0 * bad_fit_pressure
            - 2.0 * open_bins_count as f64;
    } else {
        // Existing bin: slight reward relative to mean residual state.
        score -= (mean_residual - pr) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals that no typical item can fill.
    // Sizes in 1..100, so any residual >= 1 is technically fillable, but
    // large-but-awkward residuals (just above common item sizes) are dead zones.
    let awkward = (10..=80).step_by(10)
        .map(|s| (post_residual as i64 - s as i64).abs())
        .min().unwrap() as f64;
    if post_residual > 0 {
        score += (20.0 - awkward.min(20.0)) * 2.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    // Residuals in (0,25] are "quarter-class", (25,50] "half-class", etc.
    let class = post_residual / 25; // 0..4
    score += class as f64 * 15.0;   // prefer bins whose leftover is in a lower class

    // Modulo arithmetic: residuals that are multiples of common item sizes are reusable.
    let reusable = [10u32, 20, 25, 30, 40, 50].iter().any(|&s| post_residual % s == 0 && post_residual > 0);
    if reusable {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 100.0 * (1.0 - gap as f64 / cap);
            // bonus if next item also lands in a good harmonic class after placement
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; penalize slightly more when this bin is the last chance
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // (avoid opening a new bin for a small item).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: an empty bin gets a moderate baseline so that
    // poor fits into open bins are beaten by opening a fresh bin.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // opening a bin for a large item with a large follower is okay
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        // late in the stream, prefer consolidating rather than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild tie-break toward balancing residuals across bins.
    score -= (mean_residual - frac * cap) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small gaps (< 10, or gaps below the minimum plausible item size) are worthless.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score -= 60.0; // perfect fill: this gap is dead anyway, so prefer consuming it
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Gap in 10..20 is only usable by small items; mild penalty for creating it
        score += 8.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a residual that no typical item can use well:
    // residuals just above small-item sizes are awkward.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 15.0 {
        score += 12.0 * (1.0 - pr / 15.0);
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; strongly prefer it over opening a new bin
        score -= 45.0;
    }

    // --- Open-bin pressure: keep bin count low ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);
    score += pressure * 0.5;

    // New-bin candidate (empty bin): make it moderately attractive only when
    // open bins are crowded or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by lookahead utility
        let mut new_bin_score = 70.0 + pressure;
        if next_item_size > 0 {
            // If the next item is large, a fresh bin is more valuable
            let lookahead_utility = (next_item_size as f64 / bin_capacity as f64) * 40.0;
            new_bin_score -= lookahead_utility;
            // If this item plus next item could share a fresh bin, boost new bin
            if next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
                new_bin_score -= 20.0;
            }
        }
        // If many bins already fit the item, opening new is wasteful
        if fitting_bins_count > 2 {
            new_bin_score += 15.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Late in the stream, prefer consolidating into open bins
        new_bin_score += 25.0 * progress;
        return new_bin_score;
    }

    // Lookahead: if the residual left exactly matches the next item, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // residual can still host next item: mild reward
        score -= 6.0;
    }

    // Slight preference for bins already below mean residual (balance avoidance of fragmentation)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match is ideal
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 20.0;
    }

    // Penalize very small unusable residuals (dead space)
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual near mean are neutral,
    // prefer filling bins with larger-than-mean residuals (consolidation)
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score -= 10.0 * rel;
    } else {
        // New empty bin candidate: only attractive when open bins are nearly full
        // or item doesn't fit well elsewhere
        let tightness = mean_residual / bin_capacity as f64;
        score += 45.0 * (1.0 - tightness);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin when lookahead item is large and current item leaves awkward gap
        if next_item_size > 0 && post_residual < next_item_size / 2 {
            score -= 15.0;
        }
    }

    // Early in stream: consolidation matters more; late: avoid many open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

    // Nonlinear reward for very tight fits (near-perfect packing).
    score -= 18.0 * (-post / 12.0).exp();

    // Slight extra reward when the resulting residual is much tighter than average.
    if post < mean_residual * 0.5 {
        score -= 3.0;
    }

    // Lookahead (k=2): reward bins whose residual can host the next item (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 + 4.0 * (1.0 - post / cap);
        } else if nxt > post && (bin_capacity - item_size) as f64 >= nxt && bin_residual == bin_capacity {
            // New bin would leave room for the next item; mild incentive.
            score -= 3.0;
        } else {
            // Residual likely wasted relative to the incoming item.
            score += 1.5;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Large items open bins cheaply (small leftover), small items should reuse bins.
        score -= 22.0 * frac * frac;
        if item_size <= 30 {
            score += 12.0;
        }
        // Don't open a new bin when many alternatives exist.
        if fitting_bins_count > 2 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Early in the stream, opening bins is more acceptable; late, consolidate.
        score += 6.0 * progress;
        // Many open bins already: discourage further fragmentation.
        score += 0.25 * open_bins_count as f64;
    } else {
        // Last-chance bin: using it avoids opening a new bin.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Penalize awkward mid-sized dead space that few items can fill.
    if post > 0.0 && post < 20.0 && next_item_size > post_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual and couple polynomially with progress
    let x = pr / cap; // in [0,1]
    let t = progress.clamp(0.0, 1.0);

    // Early on, prefer tight fits less aggressively; later, strongly prefer low post-residual
    let tightness_bonus = x * (1.0 - x) * (1.0 - 2.0 * t); // rewards mid residuals early, penalizes late
    score += 8.0 * tightness_bonus;

    // Strong quadratic penalty on wasted space weighted by stream progress
    score += 20.0 * t * x * x;

    // Last-chance bin: reward heavily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill = next_item_size as f64 / cap;
        score -= 10.0 * fill * (1.0 - x);
    } else if next_item_size > 0 {
        // next item won't fit: penalize residual that is close to next item size
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 6.0 * (1.0 - gap) * x;
    }

    // Mild penalty if this bin's residual deviates from mean (encourage balanced bins)
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer filling existing bins when many are open
    score += 0.5 * (open_bins_count as f64).ln() * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: tiny residues are near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    }

    // Dead-space penalty grows superlinearly for mid-range waste.
    if post_residual > 30 {
        score += (post_residual as f64 - 30.0) * 0.8;
    }

    // Lookahead harmony: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 5 {
                score -= 90.0;
            } else if leftover <= 15 {
                score -= 30.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residue: mild penalty, stronger if residue is large.
            score += (post_residual as f64) * 0.25;
        }
    }

    // Modular / integer-division class thresholds on post_residual.
    // Residues in [50,99] are half-bin class: least attractive unless lookahead helps.
    if post_residual >= 50 {
        score += 25.0 + (post_residual - 50) as f64 * 0.3;
    }
    // Residues divisible by small harmonics (10/20/25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual <= 10 || (next_item_size > 0 && next_item_size == post_residual);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 180.0 };
        score += 200.0 + scarcity;
        if good_fit_exists {
            score += 150.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
        // Many open bins with high mean residual: discourage new bins.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 60.0;
        }
    }

    // Prefer filling bins with smaller residuals (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are costly.
    // Treat residual < 10 (or below typical small item size) as nearly dead space.
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Non-linear penalty on small-but-not-dead residuals (hard to fill later)
        let r = post_residual as f64;
        score += 40.0 / (r + 5.0);
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New bin: penalize slightly more when many bins already open
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0;
    }

    // Tightness coupling: prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Progress: as stream advances, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Two-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 300.0; // perfect two-item fill
        } else {
            let diff = (post_residual as f64 - nxt).abs();
            score += diff * 1.5; // penalize mismatch with lookahead
            if diff <= 10.0 {
                score -= 60.0; // near-match bonus
            }
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual * 1.5 {
        score += (pr - mean_residual) * 0.5; // wasteful leftover vs average
    } else if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3; // tighter than average is good
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin if lookahead suggests a good fit chain elsewhere is unlikely
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 40.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - pr / bin_capacity as f64);

    // Many open bins: prefer filling existing ones.
    score += open_bins_count as f64 * 2.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: perfect fit strongly rewarded.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post-residuals that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize more when post_residual is wasted
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer filling bins when many are open (reduce sprawl).
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.5 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below mean, filling it
    // harmonizes residuals (desirable); if far above mean, penalize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be pickier (prefer tight fits, allow new bins);
    // late in the stream, consolidate aggressively into existing bins.
    let consolidation = progress * 50.0;
    score -= consolidation * (post_residual as f64 / bin_capacity as f64);
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin starts at full residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly existing bins fit
        // and how much room the new bin leaves for the lookahead item.
        let mut new_bin_cost = 35.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 50.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            new_bin_cost += 30.0; // an existing last-chance bin exists, prefer it
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_cost -= 10.0; // fresh bin accommodates lookahead
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows as stream progresses
    let norm_pr = pr / cap;
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= dead * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (post residual near zero), stronger late in stream
    let tight = (1.0 - norm_pr).powi(3);
    score -= tight * 12.0 * (0.4 + 0.6 * progress);

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
    }

    // Lookahead: favor bins that could still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0;
        }
    }

    // Mean-residual deviation: prefer bins whose residual deviates from mean
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = (cap - pr) / cap; // fraction of bin used after placement

    let mut score = pr;

    // Reward dense fills non-linearly (harmonic-ish decay on fill fraction).
    score -= 14.0 * fill.powi(4);

    // Dead-space penalty: leftover too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 9.0 + 0.35 * gap;
    }

    // Perfect close is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin before opening a new one gets priority.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New empty bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.08 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Prefer bins with below-average residual (consolidation).
        score -= 0.10 * (mean_residual - pr);
    }

    // Harmonic class of leftover: residuals in coarse decade classes,
    // small class index (tight leftover) slightly favored, plus a
    // modulo-based tie-breaker to diversify class exploration.
    let class = post_residual / 10;
    score -= (class as f64).recip().max(0.0) * 2.0;
    score += ((post_residual % 10) as f64) * 0.12;

    // Late-stream tightening: as the stream progresses, avoid leaving scraps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Dead-space penalty: small post_residual gaps are "wasted" unless the
    // next item can potentially fill them. Penalize gaps that are too small
    // to hold anything useful (assume minimum useful item chunk ~ 10% of capacity).
    let min_useful = (bin_capacity as f64 * 0.1).max(1.0);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // Unusable sliver: strong penalty proportional to its uselessness.
        score += (min_useful - post_residual as f64) * 2.0;
    }

    // Reward tight fits: the closer post_residual is to 0 (without being a
    // useless sliver), the better the packing efficiency.
    if post_residual == 0 {
        score -= 25.0; // perfect fill bonus
    } else if (post_residual as f64) >= min_useful {
        // Gradient: reward small-but-usable gaps mildly.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // --- Lookahead coupling: if the next item fits exactly in the post_residual,
    // this is a great chain placement; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but not perfectly: mild reward scaled by how well it fills.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fill;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a gap the
        // lookahead cannot exploit.
        score += 5.0;
    }

    // --- Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Open-bin pressure: when many bins are open, discourage opening more.
    // For the new-bin candidate (bin_residual == bin_capacity), add pressure
    // proportional to open_bins_count so new bins are only chosen when
    // existing fits are truly poor.
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (bins will fill over time).
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits, opening a new bin is necessary: relax pressure.
        if fitting_bins_count == 0 {
            score -= 8.0 * open_bins_count as f64;
        }
    } else {
        // Existing-bin placements reduce fragmentation pressure slightly
        // when open_bins_count is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // --- Mean residual coupling: prefer placing into bins whose residual is
    // below average (tightening already-loose bins first keeps the residual
    // distribution compact).
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 3.0;
    } else if bin_residual_f > mean_residual * 1.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fits (next item fills post_residual)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Chain fit possible: reward closeness of next item to post_residual
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; penalize wasted potential
            score += 5.0 + gap * 0.15;
        }
        // Exact chain match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize post_residual
        score -= 10.0;
    }

    // Prefer bins whose residual deviates favorably from mean residual
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for reusing open bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Early-stream: be slightly greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space: residuals too small for typical items
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 60.0;

        // Lookahead: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size <= post_residual {
                // next item fits, but measure slack left after
                let next_post = post_residual as i64 - next_item_size as i64;
                score -= 50.0 + (next_post.max(0) as f64).min(40.0);
            } else {
                // next item won't fit here; slight penalty proportional to gap
                let gap = (next_item_size - post_residual) as f64;
                score += (gap * 0.4).min(30.0);
            }
        }

        // Tight fit reward: fraction of bin filled now
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 20.0;

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 80.0;
        }

        // Many open bins: prefer consolidation, penalize spreading residual thin
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;

        // If this bin's residual is far above mean, it's roomy; slight preference
        score -= (bin_residual as f64 - mean_residual) * 0.15;

        // Early in stream: be a bit conservative (favor roomy bins), late: pack tight
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - t) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New empty bin candidate: penalize moderately so it's chosen only when
    // no open bin gives a decent fit (its post_residual is large).
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64).ln().max(0.0) * 8.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: wasted space, non-linearly scaled
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, compacting residual space matters more
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Reward near-perfect fits (small post_residual) with a smooth dip
    score -= 40.0 * (-norm_pr * 12.0).exp() * (1.0 + progress);

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let dead = 1.0 - (-gap / cap * 6.0).exp();
        score += 18.0 * dead * norm_next * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Prefer filling bins with smaller residuals relative to mean
    score -= 6.0 * (mean_residual - pr) / cap;

    // Mild penalty for proliferation of open bins early in the stream
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Smooth preference for moderate fill levels
    let fill = 1.0 - norm_pr;
    score += 10.0 * (fill - 0.85) * (fill - 0.85);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual mod 10 buckets (residuals divisible by 10 pair well
    // with items drawn from a 1..100 stream).
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.8; // reward residuals near a multiple of 10

    // Integer-division thresholds on post_residual: small dead zones are bad.
    let q = post_residual / 10;
    if q <= 1 { score += 25.0; }        // dead space <= 19 nearly useless
    else if q <= 3 { score += 8.0; }    // marginal zone
    else { score -= 6.0; }              // roomy leftovers are good

    // Perfect-fit harmonic bonus: post_residual in {0, 10, 20, ...}
    if class == 0 && post_residual > 0 { score -= 12.0; }
    if post_residual == 0 { score -= 40.0; } // exact fill is ideal

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item size shares class structure with post_residual
            let nclass = next_item_size % 10;
            if nclass == class { score -= 15.0; }
            else if next_item_size <= post_residual - (post_residual % 10) { score -= 5.0; }
        } else {
            // Next item won't fit here; penalize proportionally to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 30.0; }

    // New-bin candidate handling: only attractive when open bins are congested
    // or this bin is fresh (avoid hoarding many nearly-empty bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 20.0 - 15.0 * congestion.min(2.0) - 10.0 * progress;
        if fitting_bins_count == 0 { score -= 60.0; } // must open a bin
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to the mean (keeps fleet homogeneous,
    // leaving big residuals concentrated for big future items).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps below the smallest plausible item (1) are fine (perfect fit),
    // but small nonzero gaps that can't host typical items are dead space.
    if post_residual > 0 {
        // Dead-space zone: gap too small to be useful for most items.
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits generally.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 4.0 * progress);

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item barely misses the post residual, mild penalty (dead end).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 4.0;
    }

    // Prefer bins with residuals close to the mean (balanced usage),
    // penalize extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make empty bins moderately attractive only when
    // no good fit exists; baseline penalty keeps consolidation preferred.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * pressure;
        // If nothing else fits well, allow new bin (reduced penalty).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead matching: closer gap is better.
        score -= 20.0 * (-gap / 15.0).exp();
    }

    // Penalize tiny unusable dead space (fragmentation), but allow exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward filling a bin tighter than the current mean residual.
    score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
        // Base cost of opening a bin; reduced when lookahead can't fit anywhere well.
        let mut new_bin_cost = 30.0 + 20.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly fits the next item too; slight discount.
            if item_size + next_item_size <= bin_capacity {
                new_bin_cost -= 10.0;
            }
        }
        // Late in the stream, avoid opening bins with large residual waste.
        new_bin_cost += 10.0 * early;
        score += new_bin_cost;
    }

    // Mild preference for bins already partially filled (tight packing).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (small residuals are fine, big ones waste capacity)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_residual as f64) * 25.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 5.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits) to keep bins flexible;
    // late in stream, accept fills to avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 12.0 * dead;
    score -= progress * 15.0 * (item_size as f64 / bin_capacity as f64);

    // Crowding: many open bins -> prefer filling existing ones over opening new
    if bin_residual == bin_capacity {
        // candidate new bin: penalize when many bins open or mean residual is high
        score += 20.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // but if no open bin fits (fitting count 0 among open handled by caller), allow opening
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // existing bin: reward slightly when many bins are open
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: if this bin is much tighter than average, prefer it
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Quadratic reward for tight fits (small post_residual), scaled by fill ratio
    score -= 24.0 * (1.0 - (pr / cap).powi(2)) * fill;

    // Cubic coupling of post_residual with stream progress: late in stream,
    // prefer tighter packing more aggressively
    let prog_term = progress.powi(3);
    score += 30.0 * prog_term * pr / cap;
    score -= 18.0 * prog_term * fill * fill;

    // Penalize dead space relative to mean residual of open bins
    score += 0.35 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).powi(2));
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - fill) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are "clean"
    let r_mod = post_residual % 10;
    let r_div = post_residual / 10;
    // Penalize awkward residues (dead space that rarely fits future items 10..80)
    let residue_penalty: f64 = match r_mod {
