    score += residue_penalty;

    // Reward near-perfect fills (post_residual small but nonzero)
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 12.0; // exact fit: ideal
    }

    // Integer-division thresholds: post_residual in low harmonic band is usable
    if r_div <= 1 && post_residual > 0 {
        score += 2.5; // tiny leftover < 20 is nearly dead space unless exact
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportionally to how well the next item would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 5.0; // chain of exact fits
            }
        } else {
            score += 3.0; // next item won't fit here: this bin likely closes
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer fullest bins (best-fit flavor) scaled by stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * (2.0 + 3.0 * progress);

    // Mean-residual coupling: penalize bins far below mean residual (they're already tight)
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    if bin_residual == bin_capacity {
        let early = progress < 0.2;
        let desperate = fitting_bins_count == 0;
        if early || desperate || open_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 4.0; // discourage wasting a fresh bin mid-stream
        }
    }

    // Mild penalty on very large leftovers that straddle harmonic classes (>50)
    if post_residual > 50 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fills that still leave room for a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize when the leftover gap can't host the lookahead item (wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (tight fit) over loose ones.
    score += 0.3 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or open bins are few; otherwise make opening a new bin expensive.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 55.0 * (1.0 - item_frac) * (1.0 - scarcity) - 10.0 * scarcity;
    }

    // Mild bonus for using bins with below-mean residual (keeps residuals balanced).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a chain fit — strongly favor it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space
            // scaled by how small the unusable gap is relative to the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 30.0 * (1.0 - dead / bin_capacity as f64).max(0.0);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual well below the mean creates an outlier bin that
    // is hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 0.5 * item_size as f64;
    }

    // Penalize using a nearly-full bin for a tiny item (waste of a scarce slot).
    if item_size < 20 && bin_residual < 40 && bin_residual != bin_capacity {
        score += 40.0;
    }

    // Early in the stream, be slightly more willing to open new bins
    // to build a diverse residual pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: its base score is the capacity; adjust.
        score -= 200.0 * (1.0 - progress);
        // If no open bin fits well, new bin is attractive.
        if post_residual == bin_capacity {
            score -= 0.0;
        }
    }

    // Slight preference for filling bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty for leftover space, normalized.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - t);
    }

    // Lookahead: penalize if next item fits better in the leftover space we'd waste,
    // reward when post_residual can host the next item snugly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 8.0 * snug;
        } else {
            // leftover too small for next item: dead-space risk grows with tightness
            let waste = (post_residual as f64 / nx).min(1.0);
            score += 6.0 * waste;
        }
        // If next item is large, prefer conserving big-residual bins for it.
        if nx > bin_residual as f64 - item_size as f64 && bin_residual as f64 > nx {
            score += 5.0;
        }
    }

    // Global state coupling: when open bins already have small mean residual,
    // discourage spreading into fresh space; when mean residual is large and
    // this bin is near-empty, mild bonus to consolidate.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 2.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Many open bins: encourage closing them out (filling small residuals).
    if open_bins_count > 4 {
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early stream: slight preference for opening/using fresh bins to build structure.
    if t < 0.2 && bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - t);
    }

    // New-bin candidate: baseline cost of opening a bin; allow it only when the
    // item is large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base = 18.0;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 14.0;
        let scarcity = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += base - large_item_bonus - scarcity;
        // Late stream: opening new bins is more acceptable (less future to plan).
        score -= 6.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize mid-range dead space (smooth quadratic trough)
    score += 18.0 * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits (smooth exponential term)
    score -= 22.0 * (-(pr / 8.0) * (pr / 8.0)).exp();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            score += 4.0 * ((next_item_size as f64) - pr) / cap;
        }
    }

    // Mild pressure toward consolidation as bins accumulate
    score += (open_bins_count as f64).sqrt() * norm_pr * 2.0;

    // New-bin candidate should be penalized when decent fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward (harmonic class 0 on capacity fractions)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 - (post_residual as f64) * 20.0;
    }

    // Harmonic class of the dead space: residuals divisible by common item
    // classes (multiples of 10 / 20 / 25) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
        score -= 15.0 * reusable as f64;
        // Dead space in the awkward middle band (pr in 1..10) is hard to fill
        if pr < 10 {
            score += (10 - pr) as f64 * 8.0;
        }
    }

    // Tightness ratio: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit (or bin is nearly full elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open fits are bad
        score += 120.0;
        // Early in the stream, keeping bins consolidated matters less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
        // If open bins are on average quite full, a new bin is reasonable
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        // Prefer placing into bins whose residual is closest to the item
        let slack = (bin_residual - item_size) as f64;
        score += 10.0 * (slack as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt_fill = next_item_size as f64 / post_residual.max(1) as f64;
            // reward when next item would nicely fill the remainder
            if nxt_fill > 0.7 {
                score -= 60.0 * nxt_fill;
            } else {
                score += 20.0 * (1.0 - nxt_fill);
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 10.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller bins)
    score += 25.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Integer-division threshold on post_residual: class the leftover falls in
    let class = pr / 10; // 0..10 harmonic decile of leftover space
    score += match class {
        0 => -20.0,           // leftover < 10: nearly sealed bin, great
        1 => 5.0,             // 10..19: usable but mediocre
        2 => 0.0,             // 20..29: decent slot
        3 => -5.0,            // 30..39
        4 => -10.0,           // 40..49: very reusable
        5 => -12.0,           // 50..59
        6 => -8.0,
        7 => -4.0,
        8 => 0.0,
        _ => 10.0,            // huge leftover: wasteful placement
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small gaps are risky: only next items of size <= gap can use them.
        score += 18.0 - (post_residual - 10) as f64 * 0.5;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains nicely; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Dead space locked relative to the known next demand.
            let waste = (post_residual as f64 - if post_residual >= 10 { 0.0 } else { post_residual as f64 });
            let _ = waste;
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> opening a new bin is cheaper.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are crowded
        // (high mean residual spread) or few bins are open.
        score += 12.0 + open_bins_count as f64 * 2.0;
        // But if this is a last-chance fit elsewhere, opening loses; handled
        // implicitly since that branch subtracts from other candidates.
        // Discourage opening when a near-perfect fit exists: estimate via
        // mean_residual being small (bins already nearly full).
        if mean_residual < item_size as f64 * 1.2 {
            score += 15.0;
        }
        // Late in the stream, keep open bins tight instead of spawning more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Slight preference for bins whose residual is close to mean
        // (balanced consolidation), penalizing outliers.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            // next item fits: reward closeness to exact match
            score -= 60.0 * (1.0 - gap / 100.0);
        } else {
            // next item cannot fit: penalize residual that wastes capacity
            score += 0.35 * (pr - nxt);
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 120.0 - 100.0 * fill_ratio;
    }

    // Slight phase bias: early in stream, prefer keeping residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let item_f = item_size as f64;
    let post_f = post_residual as f64;
    let cap_f = bin_capacity as f64;

    let mut score = post_f * (1.0 + 0.25 * progress);

    // Reward placing large items into bins (fills space efficiently)
    score -= 18.0 * (item_f / cap_f);

    // Tight-fit reward: squared residual pressure
    score -= 8.0 * (1.0 - post_f / cap_f) * (item_f / cap_f);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead (k=2): if the next item fits in the post-residual, reward; else penalize dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_f >= nxt {
            score -= 6.0 * (nxt / cap_f);
        } else {
            score += 0.45 * post_f;
        }
    }

    // Global state coupling: fragmented bins -> prefer consolidation
    score += 0.06 * mean_residual;
    score -= 2.5 * open_bins_count as f64;

    // New empty bin candidate: only attractive when it clearly beats poor fits
    if bin_residual == bin_capacity {
        score = item_f * 0.6 + post_f + 6.0;
        if fitting_bins_count <= 1 {
            score += 12.0; // opening new bin is justified when no alternative exists
        }
        if progress > 0.7 {
            score -= 3.0 * progress; // late stream: slightly more willing to open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits via smooth coupling of item size and post-residual
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space far from capacity boundaries (smooth bump around mid-residuals)
    let mid = (norm_pr - 0.35) * (norm_pr - 0.35);
    score += 30.0 * mid * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_pr * norm_pr);
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fit_next * 20.0 * nxt * (1.0 - norm_pr);
        // penalize leaving residual that no plausible next item uses
        score += (1.0 - fit_next) * 15.0 * norm_pr * (1.0 - norm_item);
    }

    // Stream-progress coupling: later in stream, prefer filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 45.0 * (0.3 + 0.7 * progress);
        // new bin more acceptable early when many items remain
        score -= 30.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Mild penalty proportional to congestion of open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Smooth interaction with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new = bin_residual == bin_capacity;
    let pr = post_residual;
    let mut score = pr as f64;

    // Harmonic waste classes on post_residual: small dead space is cheap,
    // mid-range dead space (11..40) is the most damaging class.
    let cls: f64 = match pr {
        0 => 0.0,
        1..=5 => 0.5,
        6..=10 => 1.5,
        11..=20 => 4.0,
        21..=40 => 3.0,
        _ => 2.0,
    };
    score += cls * 2.5;

    // Perfect closure bonus: bin exactly filled.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead compatibility: reward if next item nests into the remainder,
    // scaled by how snugly it nests (integer-division harmonic coupling).
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            let nest_quality = 1.0 - (slack / pr.max(1) as f64) * 0.5;
            score -= 8.0 * nest_quality;
        } else {
            // next item cannot use this remainder: mild penalty proportional to overshoot class
            let over = (next_item_size - pr) as f64;
            score += 0.05 * over.min(30.0);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new {
        score -= 18.0;
    }

    // New-bin candidate handling.
    if is_new {
        // Base reluctance to open a new bin when open bins exist.
        score += 12.0 + (open_bins_count as f64).min(12.0);
        // If no open bin can fit the item, opening is necessary: strong reward.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            // An existing bin fits but barely competes; allow opening only for large items.
            if item_size > bin_capacity / 2 {
                score -= 20.0;
            }
        }
    }

    // Progress modulation: become more conservative (prefer closing bins well)
    // as the stream advances.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * prog;

    // Coupling with fleet state: bins deviating from the mean residual are
    // slightly less attractive (keeps residual distribution harmonized).
    score += 0.04 * (mean_residual - pr as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, best possible
    } else {
        // Penalize unusable small gaps (dead space) with a steep non-linear term.
        if post_residual <= 12 {
            score += (13.0 - post_residual as f64) * 40.0;
        }
        // Reward tight fits: small post_residual relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * tightness * 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive if the item leaves a large residual
        // AND no existing bin fits well (few fitting bins or large dead space elsewhere).
        let leaves_good_space = post_residual as f64 >= mean_residual.max(20.0);
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && !leaves_good_space) {
            score -= 150.0; // last-chance: open a new bin
        } else {
            score += 120.0 + open_bins_count as f64 * 3.0; // prefer existing bins
        }
    } else {
        // Last-chance bin before being forced to open a new one: strong reward.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }
        // Reward bins whose residual stays close to the mean (balanced packing),
        // unless it creates dead space.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.5;
    }

    // Lookahead: if the next item fits the post_residual exactly-ish, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 60.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual as u32 {
        // Next item cannot use leftover: mild penalty proportional to leftover.
        score += post_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_frac = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect single-item fit: overwhelming preference, zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Aggressive 2-step match: this bin becomes exactly full after the next item.
            // Zero waste across two placements — huge reward, slightly damped as the stream matures.
            score -= 500.0 * (1.0 - 0.3 * progress);
        } else if (next_item_size as u32) <= post_residual {
            // Residual remains usable by the next item: reward tight chaining,
            // bonus decays as leftover slack grows; worth more when the fleet is loose.
            let slack = post_residual as f64 - nxt;
            let bonus = (45.0 - slack.min(45.0)) * (0.6 + 0.4 * mean_frac);
            score -= bonus;
        } else if post_residual > 0 {
            // Dead space relative to the lookahead item: penalize proportionally to waste,
            // more severely when the fleet is already tight (residuals are scarce).
            score += post_residual as f64 * (1.3 - 0.5 * mean_frac);
        }
    }

    // Last-chance bin: the only open bin that can host this item. Prefer using it
    // over opening a new bin; extra discount when the outcome stays lookahead-friendly.
    if fitting_bins_count == 1 && !is_new_bin {
        let good = post_residual == 0
            || (next_item_size > 0 && (next_item_size as u32) <= post_residual);
        score -= if good { 300.0 } else { 120.0 };
    }

    // New-bin candidate: penalize bin sprawl, especially when many bins are already open.
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize residuals that block the next item but waste space.
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Prefer filling bins with larger mean residual (reduce fragmentation) slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, mildly favor opening new bins to build diversity;
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less so early on.
        score += 18.0 - 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Many open bins: encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_post * (1.0 + 2.5 * p * (1.0 - p) * 4.0);

    let mut score = coupling;

    // Reward tight fits: post_residual near zero gets a smooth quadratic bonus
    score -= (1.0 - norm_post).powi(6) * (8.0 + 6.0 * p);

    // Penalize dead space that can't hold the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let waste = (norm_post - nxt).max(0.0) / cap;
        score += waste * waste * 12.0 * (1.0 - p);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * p;
    }

    // Mild penalty when many bins are open relative to progress
    score += open_bins_count as f64 * 0.05 * (0.5 + p);

    // Prefer bins with residual near the mean (balance residuals smoothly)
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 3.0;

    // New-bin candidate: make it attractive only when the fit is poor
    if bin_residual == bin_capacity {
        score = 20.0 - 14.0 * (1.0 - norm_post) - 6.0 * p - 3.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: integer division into deciles of capacity.
    let post_class = post_residual / (bin_capacity / 10);
    match post_class {
        0 => score -= 25.0, // near-perfect fit, tiny dead space
        1 => score -= 12.0,
        2 => score -= 4.0,
        3 => score += 2.0,
        4 => score += 6.0, // half-full: mediocre
        5 => score += 8.0,
        6 => score += 5.0,
        7 => score -= 3.0, // leaves room for mid-size items
        8 => score -= 6.0,
        _ => score -= 10.0, // almost untouched bin, plenty of flexibility
    }

    // Modulo arithmetic on post_residual: residues that align with common item sizes (1..100)
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0; // round residual, likely reusable exactly
    } else if r <= 2 {
        score += 3.0; // sliver residue, near-dead space
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or harmonic match between next item and post-residual class
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 30.0; // perfect chain
            } else if diff <= 5 {
                score -= 18.0;
            } else {
                let ndiff_class = diff / (bin_capacity / 10);
                score -= (10 - ndiff_class.min(9)) as f64 * 1.5;
            }
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            let slack = (next_item_size - post_residual) as f64;
            score += slack * 0.15;
            if fitting_bins_count == 1 {
                score += 10.0; // last-chance bin wasted
            }
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // baseline cost of a new bin, softened late in the stream or when bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 45.0;
        new_bin_cost -= progress * 10.0;
        if mean_residual < cap * 0.25 {
            new_bin_cost -= 15.0; // open bins are nearly full anyway
        }
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        // if the item is large relative to capacity, new bin is attractive
        if (item_size as f64) > cap * 0.7 {
            new_bin_cost -= 12.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving gaps that can still fit typical items (>= next item if known).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream, be more conservative (favor tighter fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but discount tiny dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, dead space likely unusable anyway
    }

    // Two-step lookahead: reward if the NEXT item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // chain of perfect fits
        } else if post_residual > next_item_size {
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 20.0; // two items fill bin almost perfectly
            } else {
                score -= 8.0 * (1.0 - post2 as f64 / bin_capacity as f64);
            }
        } else {
            // next item does not fit here; penalize leaving a gap that tempts misfit
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // last item in stream: just minimize waste
        score = post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them further is good if it works, bad if it creates odd gaps.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 0 && post_residual < 15 {
            score -= 15.0; // still leaves a nearly-unusable sliver, but bin is consumed
        }
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier, avoid sloppy fits
        score += 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly, more so late in the stream.
    if bin_residual == bin_capacity && item_size > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0 + 40.0 * progress;
        // If the item is huge, a fresh bin may genuinely be the best home.
        if item_size > bin_capacity * 3 / 4 {
            new_bin_penalty -= 35.0;
        }
        // If few bins fit the item, opening fresh is more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual relative to capacity
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize unusable dead space: if post_residual is tiny but nonzero, it's wasted
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how many bins already fit
        score += 20.0 + 8.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds inventory for future items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is high, prefer reusing them
        score += (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item (k=2 chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: leftover space exactly serves next item
            score -= 12.0;
            let leftover = post_residual - next_item_size;
            // Reward chains that end near-perfectly
            if leftover < 10 {
                score -= 8.0;
            }
        } else {
            // Post-residual too small for next item: penalize proportional to waste
            let waste = next_item_size as f64 - post_residual as f64;
            score += (waste / 100.0) * 10.0;
        }
    } else {
        // Last item: just minimize post_residual (already base score)
        score -= 5.0;
    }

    // Mild penalty when many bins are open and this bin's residual deviates from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for fuller bins (smaller residual) as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog = progress.clamp(0.0, 1.0);

    // Early on, prefer filling bins tightly (low post_residual);
    // later, tolerate larger residuals to keep bins reusable.
    let tightness = 1.0 + 2.0 * prog * prog;
    score += 4.0 * prn * prn * tightness;

    // Penalize residual that is too small to be useful (dead space),
    // smoothly via a cubic bump around small residuals.
    let dead = (1.0 - prn).clamp(0.0, 1.0);
    score += 6.0 * dead * dead * dead * (1.0 - 0.5 * prog);

    // Lookahead: reward residual that can fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 3.0 * (1.0 - slack * slack) * (1.0 - 0.5 * prog);
        } else {
            let miss = (ni - pr) / cap;
            score += 2.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - prn);
    }

    // Mild preference for bins with below-mean residual (consolidation).
    let mean_r = mean_residual / cap;
    score += 1.5 * (prn - mean_r) * (prn - mean_r);

    // Slight bias toward existing bins as stream progresses.
    score -= 0.5 * prog;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "clean" slots
    let pr = post_residual;
    let clean = (pr % 10 == 0) as f64;
    score -= 12.0 * clean;

    // Penalize dead space in (0,10) — unusable for minimum item size 1..100 unknown, but
    // treat small odd residuals as risky
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 50.0;
    }

    // Coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how cleanly it divides
            let after2 = pr - next_item_size;
            if after2 % 10 == 0 { score -= 10.0; }
            score -= 6.0 * (1.0 - (after2 as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here: slight penalty for tight residual
            score += 4.0;
        }
    }

    // Integer-division threshold on post_residual (harmonic bands)
    let band = pr / 25; // 0..4
    score -= band as f64 * 3.0;

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current residual is poor
    if bin_residual == bin_capacity {
        score += 15.0 - 0.15 * (mean_residual / bin_capacity as f64) * 100.0;
        // If no existing bin is a clean fit, opening fresh is attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: early on, keep bins tight; later, allow slack
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to mean (balance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small unusable gaps are heavily penalized.
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // Unusable dead space (min item size assumed ~10): very bad.
            score += (10.0 - gap) * 40.0;
        } else if gap <= 20.0 {
            // Marginal gap: risky, only fits tiny items.
            score += (20.0 - gap) * 8.0;
        }
    }

    // Reward bins whose residual matches the next item size well (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes dead after placement and can't serve next item.
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid creating new ones;
    // this makes the empty-bin candidate less attractive unless fits are poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure and by mean residual waste.
        score += pressure + mean_residual * 0.5 + 50.0;
    } else {
        // Slight preference for tighter existing bins (smaller residual before placement).
        score += bin_residual as f64 * 0.05;
        // Reward using existing bins mildly, scaled by pressure.
        score -= pressure * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus: post_residual near zero is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover space
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * chain_fit;
        } else {
            // next item would NOT fit here: penalize leaving a gap next item can't use
            let gap_waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap_waste / 100.0).min(1.0);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // A bin left with residual near the mean keeps options balanced; extreme
    // small residuals create dead space, extreme large ones waste capacity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64;
        // new bin is fine early or when few bins open; penalize later with many open bins
        score += 10.0 + 15.0 * progress + 0.5 * open_pressure;
        // but if no open bin fits well (post_residual of best alternative unknown),
        // the base post_residual comparison still lets new bin win when others are bad.
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // awkward tiny gap unusable by most items (sizes >= 1 though)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 0.6 * tightness * tightness * cap;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    let dead_threshold = 10.0f64.min(cap * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; penalize leaving a large awkward residual.
            score += 6.0 * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state: many open bins -> discourage spreading, favor filling existing bins.
    let open_frac = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 4.0 * open_frac * (bin_residual as f64 / cap);

    // Mean residual coupling: if this bin is much emptier than average, mild penalty
    // (prefer filling fuller bins, keep uniform residuals for future items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev;

    // Time horizon: late in the stream, be more conservative (favor tight packing now).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: baseline cost of opening a fresh bin, adjusted by state.
    if bin_residual == bin_capacity {
        let opening_penalty = 55.0
            - 15.0 * (1.0 - tightness)
            - (if fitting_bins_count == 1 { 20.0 } else { 0.0 })
            + 10.0 * open_frac;
        score += opening_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 40.0 * fit_norm * fit_norm * (0.5 + progress);

    // Penalize dead space that is too small for typical future items (smooth coupling)
    let dead = 1.0 - (pr / 10.0).min(1.0);
    score += 15.0 * dead * dead * (1.0 - progress);

    // Reward tight fits more strongly as the stream matures
    let tightness = 1.0 - fit_norm;
    score -= 20.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: bonus if next item fits the post-residual (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - (gap / cap).min(1.0));
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate: neutral-to-mild penalty, decreasing with progress
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0 * fit_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Perfect fit: best possible outcome.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Lookahead coupling: reward residuals that can host the next item.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if next_item_size <= post_residual {
                score -= 12.0 + 0.25 * nxt;
            } else {
                score += 8.0 + 0.5 * (nxt - post);
            }
        }
        // Dead-space penalty: tiny residuals are nearly unusable (min item 10 in classic regime,
        // but sizes can be as small as 1, so weight by magnitude).
        if post_residual < 10 {
            score += 12.0 - 0.5 * post;
        }
    }

    // Harmonic class logic: residuals that are exact multiples of 10 form reusable
    // "harmonic classes" (10,20,...,90); prefer landing on them.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        // Within a class, prefer the low end of the remainder band (closer to a harmonic level).
        let cls = (post_residual % 10) as f64;
        score += 0.4 * cls;
    }

    // Integer-division threshold: residual in the top harmonic band (>= 50) is very flexible.
    if post_residual >= 50 {
        score -= 0.1 * post;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into tighter fits.
    if open_bins_count > 3 {
        score -= 0.05 * (open_bins_count.min(20) as f64) * (cap - post) / cap;
    }

    // Mean-residual coupling: if this bin's post-residual deviates favorably from the mean,
    // it indicates a balanced or better-than-average split.
    score += 0.05 * (mean_residual - post);

    // New-bin candidate handling: a fresh bin leaves residual = cap - item.
    if bin_residual == bin_capacity {
        score = cap - item + 30.0;
        // If no open bin can fit, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items are best placed in a fresh bin (avoid fragmenting partial bins).
        if item >= 60.0 {
            score -= 20.0;
        } else if item >= 40.0 {
            score -= 8.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small for the smallest plausible follow-up item.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Reward exact fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item cannot fit but residual is nonzero (dead space trap).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: make empty bin mildly unattractive unless it promises a perfect fill.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Next item fits; penalize proportionally to wasted space left after it.
            let after_next = post_residual - next_item_size;
            score -= 20.0 - (after_next as f64).min(20.0);
        } else {
            // Next item does not fit; penalize dead space relative to next item size.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and early in the stream where open bins are cheap to use.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 25.0 * (1.0 - progress);
        // But if the item is huge relative to typical residual, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // If next item is large and won't fit anywhere anyway, new bin is attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0;
        }
    }

    // Mild preference for filling fuller bins as stream progresses.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * item_size as f64 * 0.5;

    // Lookahead: if next item can fit into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space risk: post_residual too small for the known next item.
            score += (post_residual as f64) * 0.6;
        }
    }

    // Last-chance bin: penalize opening a new bin; favor using this one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize new empty bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5
            && (fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.5);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 0.3;
        }
    }

    // Prefer bins below mean residual (consolidate waste into emptier bins).
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Time horizon: early stream -> be conservative with new bins; late -> allow slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 - progress) + fit_norm * progress * progress;
    score += 40.0 * poly;

    // Tight fit bonus (low post residual is good), smoothly scaled
    score -= 25.0 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Penalize bins whose residual deviates from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - next_item_size as f64 / cap);
    }

    // Slight pressure to reuse open bins as stream progresses
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (small gaps that future items can still fill) get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post / cap;

    // Penalize mid-range dead space (hard to fill), reward near-zero or
    // harmonically "divisible" leftovers (e.g. multiples of 25, 20, 10).
    let dead_zone = (post_frac - 0.5).abs(); // 0.5 fraction is worst leftover
    score += dead_zone * 18.0;

    // Harmonic divisibility bonus: leftovers that are multiples of common
    // item granularities are more likely reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        30.0 // perfect fit
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 20 == 0 {
        9.0
    } else if pr % 10 == 0 {
        6.0
    } else if pr % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - post).abs() < 1.0 {
            score -= 25.0;
        } else if n <= post {
            // next item fits with some slack; reward proportional to tightness
            score -= 10.0 * (1.0 - (post - n) / cap);
        } else {
            // next item won't fit here: mild penalty scaled by how much it overflows
            score += 4.0 * ((n - post) / cap).min(1.0);
        }
        // Harmonic class of next item: sizes that are multiples of 10 pair
        // well with leftovers that are multiples of 10.
        if next_item_size % 10 == 0 && pr % 10 == 0 && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0 * (1.0 - post_frac);
    }

    // New-bin candidate: opening a new bin is only attractive when current
    // item is large and few bins are open; otherwise penalize slightly so we
    // prefer filling existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // New bin attractive for big items early, or when mean residual is fragmented.
        let fragmentation = (mean_residual / cap - post_frac).abs();
        score += 8.0 - 10.0 * item_frac - 4.0 * (1.0 - progress) + 3.0 * fragmentation;
    }

    // Mild encouragement to balance load across open bins.
    score += 0.02 * open_bins_count as f64;

    // Prefer tighter fits overall: smaller post_residual wins (already base),
    // add slight nonlinearity to sharpen preference for very small leftovers.
    score -= 6.0 * (-(post / 20.0)).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
