    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    }
    // "Awkward gap" band: residual in [12, 30) is hard to fill for many
    // distributions; penalize proportionally with a soft ramp.
    if post_residual >= 12 && post_residual < 30 {
        score += 0.8 * (30.0 - post_residual as f64);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness reward scaled by fill ratio of the bin.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        // But if the leftover would be dead space AND the next item could
        // not use it, soften the last-chance bonus.
        if post_residual < 12 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
