        if slack == 0 {
            score -= 30.0;
        } else if slack < 12 {
            score -= 12.0;
        }
    }
    // If next item is large and this bin would leave it no room, mild penalty.
    if next_item_size > post_residual && next_item_size >= 60 && post_residual > 0 {
