    // (favor consolidation); the new-bin candidate gets this penalty too.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists elsewhere. Base cost of
    // opening a bin:
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening bins is cheaper than fragmenting.
        score -= 20.0 * progress;
        // If many bins are open, prefer reusing one.
        score += 0.5 * open_bins_count as f64;
        // If the current item is large relative to mean residual, a fresh
        // bin is more reasonable.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Mild preference for bins whose residual is close to the mean
    // (balanced packing keeps options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual already lowers score via base term.
    // Penalize dead space relative to smallest plausible item (1 unit interface).
    if post_residual > 0 {
        score += 4.0 * (post_residual as f64).powf(0.5);
    } else {
        score -= 15.0; // perfect fit bonus
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 12.0; // exact 2-step chain
        }
        // Penalize leaving a residual that can never fit the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item chains well with current into a fresh bin, soften penalty
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Early in stream, be more willing to open bins for good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size as u32 {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.8 * waste;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 6.0;
            if post_residual >= next_item_size as u32 + 10 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a fresh bin is attractive only when
    // existing residuals are poor and many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_open = (mean_residual - item_size as f64).max(0.0);
        let pressure = open_bins_count as f64;
        // Base cost of a new bin, discounted by stream pressure and bad fits.
        score += 55.0 - 12.0 * pressure.min(8.0) - 0.5 * poor_open - 15.0 * progress;
        if next_item_size > 0 && next_item_size as u32 <= bin_capacity {
            score -= 8.0; // fresh bin can host lookahead item
        }
    }

    // Prefer bins whose residual is close to the mean (avoid extreme outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for filling bins with larger residual first as
    // stream progresses (keeps small residuals for small items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalize large residuals non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more
    let coupling = norm_pr * progress * (1.0 - progress * 0.5);
    score += 40.0 * coupling * coupling;

    // Reward near-perfect fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let diff = pr - next_item_size as f64;
        score -= 25.0 * (1.0 - diff / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by wasted potential
        score += 8.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize bins far from mean residual (encourage consolidation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 + progress);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // opening a new bin is neutral-ish; slightly worse late in stream
        // unless current item is large relative to typical residuals
        score = cap as f64 * (0.9 + 0.1 * progress)
            - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Dead-space penalty: post_residual too small to host the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class logic: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor(); // quarters of the bin
    score -= class * 4.0;

    // Integer-division thresholds: post_residual divisible by item_size is ideal
    // (future items of same size can tile it perfectly).
    if item_size > 0 && post_residual % item_size == 0 {
        score -= 12.0;
    }
    // Next item harmonics: post_residual exactly fits next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }
    // Penalize if post_residual cannot host next item (wasted lookahead opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Favor bins below mean residual (consolidate emptiness elsewhere).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when it enables a perfect harmonic pairing.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity - item_size) % next_item_size.max(1) == 0 {
            score = base - 20.0; // pairing synergy justifies a fresh bin
        } else {
            score = base; // discourage needless bin proliferation
        }
    }

    // Mild stream-progression regularization.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 30.0 * (1.0 - slack);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for creating a stranded bin.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0)) * (0.5 + 0.5 * progress);
    if bin_residual < bin_capacity {
        score -= pressure.min(25.0);
    }

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or no open bin fits well. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If item is large, a fresh bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 45.0;
        // If next item is small and current fit leaves a tiny gap, opening new bin less bad.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Slack after the next item would also fit; mild bonus scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }
    }

    // Penalize small nonzero dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (tighter bins)
    // when the fit is good, but avoid draining bins that are already very tight.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid);
    } else {
        score += 0.3 * (resid - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 15;
        if poor_fit {
            score += 50.0; // allow new bin when this fit would be wasteful
        } else {
            score += 300.0; // prefer existing bins otherwise
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 80.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild bonus for larger items filling big holes now.
    score -= 0.2 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (waste grows quadratically for small leftovers)
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Exact chain fit is excellent
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space the next item cannot use
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer fullest packing
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins over new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15;
    score += progress * 3.0;

    // New-bin candidate: penalize unless current fits are poor
    if bin_residual == bin_capacity {
        score += 10.0;
        // But early in stream or when open bins are crowded, new bin is cheaper
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Prefer bins tighter than the mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Progress-weighted polynomial penalty: small residuals matter more late in stream.
    let prog_term = (0.5 + 0.5 * progress) * (x * x) * cap;
    score += 0.8 * prog_term;

    // Reward tight fits (small post_residual) with smooth non-linear bonus.
    score -= (1.0 - x) * (1.0 - x) * (item_size as f64);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) * (0.5 + progress);
        } else {
            // Smoothly reward residual that can still host the next item.
            score -= 2.0 * (1.0 - ((pr - nxt) / cap)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins
    // fit the item and residuals elsewhere are large.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0 && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let avg_fit = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        let openness = (fitting_bins_count as f64).ln().max(0.0);
        score += 15.0 + 8.0 * openness + 0.3 * avg_fit * (0.5 + progress);
    }

    // Mild penalty for bin much emptier than the mean (keeps residuals balanced).
    score += 0.15 * ((mean_residual - pr).abs() / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify leftover space into
    // coarse integer-division bands; perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, dead space is small
    } else if post_residual <= 25 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 6.0;
    } else {
        score += 14.0; // large leftover: likely reusable, but wasteful now
    }

    // Modulo arithmetic on post_residual: residuals that are harmonically
    // aligned with common item sizes (multiples of 10/20) are more likely
    // to be filled exactly by future items.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 6.0; // divisible by 10 -> future item can fill exactly
    } else if m10 >= 8 {
        score += 3.0; // awkward sliver class
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chaining perfect pairs).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 18.0;
            } else {
                score += (chain_left as f64) * 0.25;
            }
        } else {
            // next item cannot follow here; slight penalty unless this
            // closes the bin anyway
            if post_residual > 0 {
                score += 4.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is truly terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual > 60 {
            score += 20.0; // but a very bad fit still loses to a fresh bin
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it over open bins when open bins would leave bad classes.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream
        // when average occupancy statistics suggest poor fits abound.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 30.0 - 10.0 * progress;
        if mean_residual < 25.0 {
            open_cost -= 8.0; // open bins are nearly full; new bin is fine
        }
        if open_bins_count == 0 {
            open_cost = -100.0; // must open a bin
        }
        score += open_cost;
    }

    // Slight preference for filling fuller bins (best-fit flavor) via
    // capacity-fraction thresholds.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac > 0.7 {
        score -= 5.0;
    } else if fill_frac < 0.3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
