    // Treat residual < 10 as dead space (minimum item size assumption; below that, gap is unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating unusable slivers
    }

    // Non-linear penalty on small-but-usable gaps: a gap that only fits tiny items is low utility.
    let gap_utility = (post_residual as f64 / bin_capacity as f64).powf(0.5);
    score -= 25.0 * gap_utility;

    // Reward tight fits: post_residual close to zero relative to capacity.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well (fitting bins exist but fit is bad), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Lookahead: if the next item can fill this bin's post_residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize leaving a gap the next item can't use
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean toward tight fits.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight late-stream tightening: as the stream progresses, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

