    // the post-residual (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;
        if next_item_size == post_residual {
            score -= 120.0; // perfect two-item chain
        }
        // Penalize if next item would be forced to a new bin due to large post_residual
        if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates
    // favorably (below-mean residual = tighter bin, use it first).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.6 * mean_residual;
        score += base;
        if next_item_size > 0 && next_item_size <= post_residual {
            // keeping item in an open bin still fine; discourage new bin mildly
            score += 10.0;
        }
        if next_item_size > item_size && next_item_size > 50 {
            // large next item: fresh bin may be valuable
            score -= 25.0;
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual == 0 as u32 as u32) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating dead space that cannot fit a typical item (<= 100 cap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits in post_residual, this is a great chain placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            // Extra reward if next item fills the bin nearly exactly after.
            let chain_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // If current item is large, opening a fresh bin is fine.
        if item_size >= 50 {
            score -= 8.0;
        }
        // If many bins are open and mean residual is small (fragmented state),
        // opening a fresh bin is more attractive.
        let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let frag = (mean_residual - post_residual as f64).abs();
        score += frag * 0.15;
        score -= prog * 3.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // Slight preference for filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Mild penalty for very large post-residual waste (encourage compact packing).
    if post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), non-linearly
    let mut score = post * post / cap;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, waste matters less; later, tight packing is critical
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_post * 40.0;

    // Cubic interaction: dead space penalized more as stream progresses
    score += progress * norm_post.powi(3) * 60.0;

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post) * 0.3;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 5.0 * (1.0 - progress);

    // Slight preference for using existing bins over opening new ones early
    score += (open_bins_count as f64).ln() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that cannot host common small items
    let small = post_residual.min(30);
    if small > 0 {
        // penalize residuals in awkward classes (not divisible nicely, odd, prime-ish)
        let class = post_residual % 10;
        score += match class {
            0 => -8.0,          // nicely divisible residual, likely reusable
            5 => 2.0,
            2 | 4 | 6 | 8 => 1.0,
            _ => 6.0,           // odd residuals harder to fill
        };
        // very small dead space is bad
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // Can next item fit in post_residual? Big reward for chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // harmonic pairing: next item exactly fills remainder
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Prefer tighter bins when many bins are open
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Integer division threshold: residual that fits half-items is reusable
    if post_residual >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 interface)
    // are effectively dead. Penalize any post_residual below the smallest plausible item size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Small gap that is hard to fill: heavy penalty proportional to wasted capacity.
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual < 20 {
        // Moderately awkward gap.
        score += 8.0;
    }

    // Reward tight fits: how much of the bin's usable space the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across too many bins when
    // there are already many open bins; encourage consolidation.
    score += 1.5 * open_bins_count as f64;

    // If this bin is the ONLY fitting bin, strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    // (mean residual low relative to item) or item is large.
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual < item_size as f64 * 1.2;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 12.0;
        } else {
            // Prefer existing bins by default.
            score += 20.0;
        }
    }

    // Lookahead coupling: if the next item would fit in the post_residual,
    // reward leaving exactly that much space (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Gap can't hold the next item: slight penalty.
            score += 5.0;
        }
    }

    // Slight consolidation pressure as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward near-exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item exactly fills the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= (50.0 * (1.0 - slack_after_next / bin_capacity as f64)).max(0.0);
        } else {
            // next item does NOT fit in this bin after placement: penalize
            let overshoot = (next_item_size - post_residual) as f64;
            score += 30.0 + 0.5 * overshoot.min(100.0);
        }
    }

    // Compare post_residual relative to mean residual: creating a small residual
    // vs the average is good (tight packing); large residual is wasteful.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr < mean_residual * 0.5 {
            score -= 20.0;
        } else if pr > mean_residual * 1.5 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (big items pack best in fresh bins).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 60.0 * frac;
        // if no open bin fits well anyway, ease opening new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild late-stream tightening: as stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that can never be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: bonus if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below the mean residual (tighter bins first).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 6.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        // But open a new bin if the item fits perfectly.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Time-horizon shaping: slightly more greedy early, more space-conscious late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize key quantities into [0,1]-ish scales.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0); // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (convex penalty on wasted space);
    // later, tolerate residual slack slightly (open-bin reuse dominates).
    let poly = x * x * (1.0 - 0.5 * progress) + x * x * x * (0.5 + 0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits with a smooth saturating bonus.
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete, scaled by competition.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_frac = next_item_size as f64 / cap;
        score -= 10.0 * fit_frac * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Smooth penalty for dead space that cannot host the next item.
        let waste = 1.0 - ((next_item_size as f64) / (pr + 1.0)).min(1.0);
        score += 8.0 * waste * waste;
    }

    // Penalize bins far above/below mean residual to keep the pool homogeneous,
    // with a smooth quadratic coupling.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate handling: make empty bin attractive only when the item
    // fits poorly everywhere else (few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let early = 1.0 - progress;
        score = score.min(0.0) * 0.0 + 25.0 - 45.0 * scarcity - 20.0 * early * (1.0 - x);
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // residue classes (multiples of small divisors) are rewarded.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Dead-space penalty grows superlinearly for tiny residuals that are
    // hard to fill (residual in 1..10 wastes capacity).
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Reward residuals that are "harmonic": divisible by common item sizes.
    let harmony: f64 = if pr == 0 {
        -60.0 // perfect fill is best
    } else {
        let mut h = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                h -= 12.0;
            }
        }
        h
    };
    score += harmony;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor. Penalize fresh empty bin unless residuals are tight.
    if bin_residual == bin_capacity {
        // baseline cost of consuming fresh capacity
        score += cap * 0.15;
        // but if existing bins are fragmented, new bin is attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= mean_residual * 0.25 * (1.0 - progress);
        // large items early: prefer a fresh bin to avoid fragmenting
        if item_size >= bin_capacity / 2 && open_bins_count > 2 {
            score -= 20.0;
        }
    }

    // Fractional capacity alignment: reward placing item that fills a clean
    // fraction of the bin (1/2, 1/4, 3/4 boundaries).
    let frac = item_size as f64 / cap;
    if (frac * 4.0).round() == frac * 4.0 {
        score -= 6.0;
    }

    // Mild preference to keep mean residual balanced (avoid hoarding space).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps that nothing can use are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range unusable gaps (below min item size 1..=100 -> anything < ~10 is risky)
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading when many bins open
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let lookahead_waste = if next_item_size > 0 && next_item_size > poor_fit as u32 { 30.0 } else { 0.0 };
        score = 25.0 + poor_fit * 0.3 + lookahead_waste
            + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a new bin is fine when alternatives are scarce... but keep bias to reuse
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits in post_residual, mild reward
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot use post_residual, penalize leaving that gap
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual waste is better.
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_frac;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin is an ideal two-item match.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here later; mild reward proportional to slack.
            score -= 4.0;
        } else {
            // Next item cannot use this leftover; penalize dead space relative to next item.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post-residual against mean residual across open bins:
    // leaving below-average residual concentrates waste, which is good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin (only fitting bin): strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins already exist and fit is loose,
    // more strongly early in the stream when consolidation matters.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress) + 0.2 * (post_residual as f64 - item_size as f64);
    }

    // Slight penalty for leaving residuals that are too small for typical items (1..100).
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward small dead space nonlinearly
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64).powi(3) * 120.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item fits well in the leftover space,
    // reward if leftover space is a bad host for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 4.0;

    // Relative tightness vs. mean residual of open bins
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive early in the stream or when the fit
    // in any open bin would be terrible (large post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let escape_penalty = if fitting_bins_count == 0 { -1000.0 } else {
            35.0 + 40.0 * progress - (pr.min(60.0) * 0.5)
        };
        score += escape_penalty;
    }

    // Mild time pressure: later in stream, be greedier about tight fits
    score -= fill_ratio * progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual shaped by stream progress.
    let shape = 1.0 + 0.6 * progress - 0.8 * progress * progress;
    score *= shape;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (norm_pr * (1.0 - norm_pr)) * cap * (0.15 + 0.35 * progress);

    // Penalize dead space quadratically when residual cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.5 * progress) + 0.25 * (nxt - pr) * (nxt - pr) / cap;
        } else {
            // Smooth reward for leaving room exactly usable by the next item.
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 2.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Deviation from mean residual: prefer bins below mean (consolidating large gaps).
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev - 0.5 * dev;

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += 0.1 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: prefer opening a fresh bin only when it wastes little
    // relative to item size and few bins fit the item.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score = cap * waste * waste + 4.0 * waste;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 as "usable slots"
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -30.0,               // clean class boundary, very reusable
        1..=5 => r as f64 * 2.0,  // small slivers: mild penalty
        _ => 10.0 + (10 - r) as f64 * 1.5, // awkward residues
    };
    score += dead_penalty;

    // Integer-division thresholds: post_residual in [1,10] is nearly dead space
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Large residual is valuable: reward thirds/quarters of capacity
    if post_residual >= bin_capacity / 3 {
        score -= 15.0;
    }
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item complements this bin
            let complement = (next_item_size + post_residual) % 10;
            let bonus = if complement == 0 { 40.0 } else { 25.0 };
            score -= bonus;
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap_f) * 50.0;
        }
    } else {
        // last item: residual is pure waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if no open bin fits well, new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early stream: opening bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= (1.0 - progress) * 15.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100 range,
    // but typical small items ~10) create unusable gaps. Penalize gaps < 10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage opening new bins when many are already open
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if few bins open or item is large
        score += open_bins_count as f64 * 8.0;
        score -= 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score += 20.0; // next item won't fit a fresh bin anyway after this placement
        }
    } else {
        // Reusing an existing bin is good; extra reward when it's the last fitting bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Slight bonus for keeping mean residual low (packing efficiency)
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // Late-stream: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large dead space nonlinearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fits the post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the remaining space: penalize dead space creation
            score += 6.0;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference to fill existing bins when many are open (avoid bin proliferation)
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer placing large items into bins with plenty of residual
    if item_size > bin_capacity / 2 {
        score -= 0.2 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Global state: many open bins with large mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 2.0 {
        score -= 3.0;
    }

    // New-bin candidate: empty bin should only win when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when good fitting options exist.
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
        // But late in the stream with fragmented bins, allow new bins more readily.
        score -= progress * 10.0;
        // If the item is large relative to mean residual, a fresh bin is attractive.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Mild penalty for very large items going into nearly-full bins (waste risk).
    if item_size >= 70 && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer smaller post-residual (tighter packing).
    let mut score = post;

    // Non-linear normalized tightness: reward near-full fills super-linearly.
    let fill_ratio = 1.0 - post / cap;
    score -= 40.0 * fill_ratio * fill_ratio * fill_ratio;

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, dead space is heavily penalized.
    let p1 = progress;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post * (0.6 * p1 + 0.9 * p2 + 0.5 * p3);

    // Fit ratio: relative tightness of the placement within the bin.
    let fit = item / resid.max(1.0);
    score -= 25.0 * fit * fit;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * p1;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty for consuming a scarce-large residual.
        score += 8.0 * (1.0 - fit);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is too small for the next item, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_fit = nxt / post.max(1.0);
            score -= 20.0 * nxt_fit * nxt_fit;
        } else {
            score += 0.35 * (nxt - post);
        }
    } else {
        // Last item: fill as much as possible.
        score -= 30.0 * fill_ratio;
    }

    // Mean-residual coupling: when average residual is low, conserve large
    // remaining spaces (penalize using a big-residual bin for a small item).
    let mean_r = mean_residual.max(0.0);
    score += 0.25 * (resid - mean_r) * (1.0 - fit);

    // Open-bin pressure: with many open bins, discourage new-bin-like states.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio) * (1.0 - p2);

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0 - 45.0 * p1;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "hard" residue classes is worse.
    let cap = bin_capacity as f64;
    let post = post_residual as u32;
    let frac = post as f64 / cap; // capacity fraction filled leftover

    // Penalize post_residuals that are "awkward": small but nonzero leftovers
    // (e.g. 1..=15) which rarely fit future items (min size 10 in classic range,
    // but sizes 1..100 allowed here). Use modulo classes to grade them.
    if post > 0 {
        let m = post % 10;
        match m {
            0 => score -= 8.0,                      // clean decade: reusable
            1..=3 => score += 12.0,                 // nearly useless sliver
            4..=6 => score += 5.0,                  // marginal
            _ => score -= 2.0,                      // 7..9: fits small items
        }
    }

    // Perfect fit reward: post_residual exactly zero or a harmonic of capacity
    if post == 0 {
        score -= 60.0;
    }
    if post > 0 && bin_capacity % post == 0 {
        score -= 10.0; // post divides capacity evenly: harmonically reusable
    }

    // Reward tight fills (small post_residual relative to capacity)
    score += 25.0 * frac * frac;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size < post {
            let slack = (post - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // harmonic bonus if post % next_item_size == 0
            if next_item_size > 0 && post % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here: bin likely closes
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves
    // terrible dead space or stream is early with many items remaining.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (total_items.max(1) as f64);
        // Base penalty keeps new bins from winning trivially...
        score += 55.0;
        // ...but allow new bins late in stream when mean residual is fragmented.
        score -= 40.0 * progress * (mean_residual / cap).min(1.0);
        score -= 15.0 * pressure;
        // If item is huge, a fresh bin is often best.
        if item_size * 5 >= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate waste).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer using bins that are already substantially filled.
    let used = (bin_capacity as f64) - (bin_residual as f64);
    score -= 0.05 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

