        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; leftover is likely dead space.
            score += 6.0;
        }
    }

    // Prefer bins whose residual deviates from the mean residual (specialization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev;

