        score += 8.0 * (1.0 - norm_pr) * progress;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if r == cap {
        score += 45.0 - 25.0 * progress - 2.0 * open_bins_count as f64;
    }

    // Mild pressure to consolidate as stream ends
    score -= 5.0 * progress * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 500.0;
    }

    // Non-linear penalty for small-but-not-dead gaps that waste capacity
    let gap = post_residual as f64;
    score += (gap * gap) / (bin_capacity as f64);

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 20.0;
    }

    // Open-bins pressure: encourage filling existing bins when many are open
    score += open_bins_count as f64 * 2.5;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Lookahead: penalize if the next item cannot use the post_residual
    if next_item_size > 0 && (next_item_size as f64) > gap {
        score += 15.0;
    } else if next_item_size > 0 {
        score -= 10.0;
    }

    // Prefer new bin when existing residuals are fragmented
    if bin_residual == bin_capacity {
        // brand-new bin candidate: mild baseline so it wins only when fits are bad
        score += 40.0;
    }

    // Stream progression: slightly more conservative late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base score.

    // 2-step lookahead: if next item exactly matches the post residual, heavily reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // reward proportionally to how well next item fills remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot fit here; penalize dead space a bit
            score += 5.0;
        }
    } else {
        // last item: prefer minimal post residual (waste)
        score += 0.0;
    }

    // Penalize leaving tiny unusable gaps (dead space below min item size 1..100 heuristic)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // prefer filling tighter bins to keep loose bins available for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Reward using existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        // New bin candidate: penalize unless post residual is very useful
        score += 10.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual dominates).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Reward filling bins nearly exactly (perfect fit bonus).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // New-bin candidate handling: opening a bin is expensive early,
    // cheaper late when many bins are open and fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let new_bin_penalty = 55.0
            - 25.0 * progress
            - (open_bins_count as f64).min(20.0) * 0.8
            - mean_residual * 0.15;
        score += new_bin_penalty.max(0.0);
        // If current item is large and next item is also large, opening fresh
        // bin may be fine.
        if item_size >= 60 && next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way:
    // bins tighter than average are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Mild preference for consolidating into fewer bins when few are open.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Late-stream urgency: squeeze into existing bins more aggressively.
    if progress > 0.8 {
        score -= post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: quadratic coupling of post residual with stream progress.
    let mut score = norm_pr * norm_pr * (1.0 + progress) * cap;

    // Reward tight fits more strongly as the stream advances.
    score -= fit * fit * cap * (0.5 + progress);

    // Penalize post residual that is too small to be useful later (dead space),
    // smoothly via a saturating exponential of the residual.
    score += (1.0 - (-norm_pr * 4.0).exp()) * (10.0 + 10.0 * progress);

    // Last-chance bonus: strongly favor this bin when it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits in post residual (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = ((pr - nx).abs() as f64) / cap;
        score -= fits_next * (nx / cap) * cap * 0.6 * (1.0 - gap);
    }

    // Mild penalty proportional to open bins to discourage fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Encourage bins whose residual deviates from the mean (diversity of sizes).
    score -= ((pr - mean_residual).abs() / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are nearly dead space -> penalize.
    let pr = post_residual;
    let harmonic = match pr {
        0 => 0.0,                              // perfect fit, ideal
        1..=10 => 60.0,                        // tiny unusable sliver
        11..=20 => 30.0,
        21..=40 => 10.0,
        41..=60 => -5.0,                       // reusable mid-range leftover
        _ => 0.0,
    };
    score += harmonic;

    // Modulo-based coupling: leftover congruent to common item sizes (10/20/25/50)
    // is more likely to be filled by future items -> reward.
    if pr != 0 {
        let reusable = (pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32;
        score -= 8.0 * reusable as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / 40.0).max(0.0);
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 6.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Base its score on the mean residual of open bins.
    if bin_residual == bin_capacity {
        score = 100.0 - 0.5 * mean_residual + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big upcoming item: keep a fresh bin available
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Progress scaling: later in the stream, waste matters relatively more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can no longer fit the
    // smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 * (1.0 - fit_ratio.min(1.0));

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: prefer compacting into existing bins when many are open.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the current mean (compaction).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this call is for the empty bin and residual equals capacity).
    if bin_residual == bin_capacity {
        score = 100.0 + item_size as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 120.0; // no real alternative -> open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize proportionally to wasted potential
        score += 12.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Penalize dead space far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.35 * dev;

    // Reward tight fits (small post residual relative to capacity)
    score += 0.25 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is progressing,
    // unless current fit is very poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality < 0.65 {
            score += 40.0 + 25.0 * progress;
        } else {
            score += 8.0;
        }
    }

    // Slight preference for filling bins with larger residuals as stream advances
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual exactly or well, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space if next item cannot use it: penalize proportionally to wasted chunk.
        let waste = post_residual.min(next_item_size - 1) as f64;
        score += 4.0 * waste / (bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this empty bin
    // relative to mean utilization across open bins.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins are fragmented (high mean residual spread)
        // and item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 6.0 + 10.0 * (1.0 - item_size as f64 / 100.0)
            - 4.0 * fragmentation / (bin_capacity as f64)
            - 3.0 * progress;
    } else {
        // Slight preference for fuller bins among open bins.
        score += 2.0 * (bin_residual as f64 / bin_capacity as f64);
        // If many bins are open, encourage consolidation into already-open bins.
        if open_bins_count > 4 {
            score -= 1.5;
        }
    }

    // Time-horizon modulation: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, prioritize closing bins out completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score -= 5.0 * progress; // finishing bins is good late
    } else if post_residual < 20 && progress < 0.5 {
        score += 3.0 * (1.0 - progress); // small dead space is bad early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, demand tight fits (amplify small residuals)
    let coupling = 1.0 + 3.0 * progress * progress;
    score = score / coupling + 60.0 * progress * norm_pr * norm_pr;

    // Reward filling a bin nearly exactly, more so as stream advances
    let fill = 1.0 - norm_pr;
    score -= (fill * fill * fill) * 30.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.15 * gap * gap / cap;
        // bonus if next item exactly fits the post-residual
        let exact = (next_item_size as f64 - pr).abs();
        score -= 12.0 * (1.0 - exact / cap).max(0.0) * (1.0 - exact / cap).max(0.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins vs mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Slight preference for consolidated bins when many are open
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // Discourage opening new bins when decent fits exist (smooth)
    if bin_residual == bin_capacity {
        let waste = pr; // full residual of fresh bin
        score += 20.0 + 0.5 * waste as f64 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual values that other items can reuse.
    // Class A: post_residual in [1,10] -> near-perfect fit, strong reward.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 10 (nice round leftover, likely reusable)
    else if post_residual % 10 == 0 {
        score -= 3.0;
    }
    // Class C: dead space in (10, 20) — moderately awkward
    else if post_residual < 20 {
        score += 4.0;
    }
    // Class D: large awkward leftovers (30..50) — dead space risk
    else if post_residual > 30 && post_residual < 50 {
        score += 6.0;
    }

    // Integer-division threshold: post_residual / 10 == 2 (20..29) is a sweet spot
    if post_residual / 10 == 2 {
        score -= 2.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 6.0;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            // next item won't fit here: leftover likely wasted
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Progression: late in the stream, consolidate harder (favor filling open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean-residual coupling: if this bin is below mean residual (tighter), slight bonus.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how many bins already fit.
        let mut penalty = 6.0 + (fitting_bins_count as f64) * 4.0;
        // If the item is large (harmonic class: item > 60), new bin is more acceptable.
        if item_size >= 60 {
            penalty -= 3.0;
        }
        // Late stream: penalize opening bins more.
        penalty += progress * 3.0;
        score = cap * 0.5 + penalty + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (waste-proportional quadratic penalty).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins below mean residual (consolidate space).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Lookahead: reward leaving space that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: penalize by default, but relax when fit is poor
    // or the item is large relative to the residual.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.35 * bin_capacity as f64
            && (bin_capacity - bin_residual) == 0;
        let tight_elsewhere = fitting_bins_count > 0
            && (bin_residual - item_size) as f64 > 0.6 * (bin_capacity - item_size) as f64;
        score += 45.0;
        if poor_fit { score -= 20.0; }
        if tight_elsewhere { score -= 15.0; }
    }

    // Mild stream-progression damping of the base residual term.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item, penalize near-misses.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            score -= 6.0;
        } else if (post_residual as f64) + 0.5 * n >= n {
            score += 4.0; // close but unusable for the next item
        }
        // Bonus for exact pair packing: item + next fills bin well.
        if item_size as f64 + n <= cap && (cap - item_size as f64 - n) < 5.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 1.5 * open_pressure * tightness;

    // Mean-residual coupling: if average residual is high, waste is less costly.
    score += 0.08 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate aggressively.
    score -= 5.0 * progress * tightness;

    // Mild penalty for the brand-new empty bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 12.0 - 4.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 5.0; // new bin makes sense for big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 12.0 * norm_pr * norm_pr * cap          // penalize large leftover space quadratically
        - 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr); // reward tight fits

    // Smooth coupling of post_residual with stream progress:
    // early on prefer spreading (favor big post_residual), later prefer tight packing
    let spread_weight = (1.0 - progress) * (1.0 - progress);
    score += (progress * 25.0 - spread_weight * 15.0) * norm_pr;

    // Interaction: post_residual^2 modulated by progress
    score += progress * norm_pr * norm_pr * 30.0;

    // Dead space penalty: post residual too small for smallest plausible item (1..100 range)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 6.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual (smooth)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0);
        score -= 15.0 * (1.0 - (next_item_size as f64 / (pr + next_item_size as f64 + 1.0))) * (fits / cap + 0.2);
        // penalize if next item nearly but not quite fits
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap <= 20.0 {
            score += gap * (1.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0 * (0.5 + progress);
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln() * (3.0 + 5.0 * progress) * norm_pr;

    // Align with mean residual: prefer bins near the mean (smooth)
    score += ((pr - mean_residual) / cap).abs() * 10.0 * (0.3 + progress);

    // New-bin candidate handling: empty bin gets a moderate default score
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse granularity classes (mod 10)
    let item_class = item_size % 10;
    let post_class = post_residual % 10;

    // Reward placements where post_residual is a "usable" harmonic class:
    // residuals that are multiples of 10 or small (<=5) pair well with future items.
    if post_class == 0 {
        score -= 6.0;
    } else if post_residual <= 5 {
        score -= 3.0; // dead space, but tiny dead space is fine
    } else if post_class <= 2 {
        score += 2.0; // awkward residual class
    }

    // Penalize large awkward residuals that few future items can use
    if post_residual > 20 && post_residual < 30 {
        score += 3.0;
    }
    if post_residual > 45 && post_residual < 50 {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap <= 5 {
            score -= 5.0;
        } else {
            score -= 2.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 100.0;
        // opening a new bin is attractive only if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 120.0;
        } else if fitting_bins_count == 1 {
            // keep last-chance preference for the existing bin
            score += 5.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with larger current residual less tightly when
    // mean residual is high (many bins are loose; keep flexibility)
    if mean_residual > 40.0 && post_residual > 50 {
        score += 2.0;
    }

    // Mild preference for bins tighter than average
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Integer-division threshold: post_residual / item_size ratio bands
    let ratio = post_residual / (item_size.max(1));
    if ratio >= 3 {
        score -= 1.0; // bin could hold several more like-items; fine
    } else if ratio == 0 && post_residual > 0 {
        score += 1.5; // tight squeeze leaves odd residue
    }

    // Slight tie-break noise via step parity (deterministic)
    if step_index % 2 == 0 {
        score -= 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are wasted forever -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot host the lookahead item is doubly bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // no open bin offers a good fit (i.e., best fit would leave big dead space).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by stream progress
        // (late in the stream, waste matters less; early, consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 + 40.0 * (1.0 - progress);
        // If the item would fit snugly in the fresh bin and the next item is large,
        // a new bin is a reasonable hedge.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild mean-residual coupling: prefer bins that keep average slack balanced.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or tightly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by tightness of the follow-up fit
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * tight;
        } else {
            // next item cannot fit here; penalize leftover dead space
            score += (post_residual - 0) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // late in the stream, avoid opening new bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight preference for denser packing late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    score -= 35.0 * (1.0 - post / cap).powi(3);

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead coupling: strongly reward leaving space for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 18.0 * (nxt / post.max(1.0));
        } else {
            // Dead space: next item cannot use this leftover.
            score += 12.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about tightness.
        score += 4.0;
    }

    // Penalize residuals far from the global mean (fragmentation signal).
    score += 0.08 * (post - mean_residual).abs();

    // New-bin candidate: penalize moderately, but allow it when the item is
    // large (poor fit anywhere) or early in the stream.
    if bin_residual == bin_capacity {
        score += 10.0;
        score += 25.0 * (1.0 - t);
        if item / cap > 0.55 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 + item <= cap {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 40.0 * poly;

    // Tight fits rewarded, more so late in the stream.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
        let waste = (next_item_size as f64 - post) / cap;
        score += 18.0 * waste * waste * (0.6 + 0.4 * progress);
    }

    // Reward lookahead compatibility.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for fragmenting a large-residual bin relative to fleet mean.
    let resid_gap = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * resid_gap * resid_gap * norm_post;

    // New-bin candidate: prefer early in stream, or when no good fit exists late.
    let new_bin_bonus = 25.0 * (1.0 - progress) * (1.0 - progress)
        - 20.0 * progress * progress;
    if bin_residual == bin_capacity {
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers in "small" classes are
    // nearly dead space, leftovers in "large" classes stay reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries at capacity fractions 1/6, 1/4, 1/3, 1/2.
    let class = if pr == 0.0 { 0u8 }
        else if pr <= cap / 6.0 { 1 }
        else if pr <= cap / 4.0 { 2 }
        else if pr <= cap / 3.0 { 3 }
        else if pr <= cap / 2.0 { 4 }
        else { 5 };

    // Reward large leftover classes, punish tiny dead-space classes.
    score -= match class { 0 => 40.0, 1 => -18.0, 2 => -6.0, 3 => 4.0, 4 => 12.0, _ => 20.0 };

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic compatibility: does next_item_size divide/fit the post_residual well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Exact modulo match => next item seals this bin perfectly.
            let m = post_residual % next_item_size;
            if m == 0 {
                score -= 30.0;
            } else {
                score -= 10.0 * (1.0 - (m as f64) / nxt);
            }
            // Fraction of leftover consumed by the lookahead item.
            score -= 15.0 * (nxt / pr).min(1.0);
        } else {
            // Lookahead cannot use this leftover at all: penalize.
            score += 12.0;
        }
    }

    // Integer-division threshold on post_residual: leftovers below 10 can
    // never host any item (min size 1..100 stream, but typical granularity).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits: normalize by mean residual.
        score += (mean_residual - pr) * 0.3;
    }

    // Early in the stream, keep bins flexible (favor large post_residual);
    // late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: neutral-ish baseline; only attractive when this bin
    // would create dead space.
    if bin_residual == bin_capacity {
        score += 5.0 - 15.0 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no bin fits well,
    // i.e., when residual is large but item leaves a big awkward gap elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by potential for future packing.
        score = bin_capacity as f64 - item_size as f64;
        score += open_bins_count as f64 * 2.0;
        // If mean residual of open bins is small (bins nearly full), new bin is reasonable.
        score -= mean_residual * 0.5;
        // If next item could pair with the leftover, slightly favor new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Mild progression term: later in stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how well it fills
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize dead space left behind
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Relative to mean residual: prefer bins with below-average residual (denser bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating very small unusable fragments (< 10, min item size)
    if post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (post_residual would be large relative to mean).
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 30.0;
        // but if next item is large and this item would leave a bad fragment elsewhere,
        // opening becomes more attractive when the fit is very tight
        if post_residual == 0 {
            score -= 60.0; // perfect fit in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Slight late-stream conservatism: keep bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual is already the base).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for any plausible item (min size 1,
    // but small unusable gaps below ~10 are dead weight).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if post residual can't fit the next item,
    // penalize proportionally to the wasted fraction.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            let wasted = (post_residual as f64) / (bin_capacity as f64);
            score += 10.0 * wasted;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well or the stream
    // is early with many items remaining (amortize a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0; // base cost of opening a new bin
        // Cheap to open early, expensive late.
        score -= 10.0 * (1.0 - progress);
        // Attractive when mean residual of open bins is fragmented/small.
        score -= (mean_residual / (bin_capacity as f64)) * 6.0;
        // Attractive when open bins are numerous but none fits well.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Mild pressure to fill nearly-full bins completely.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer consolidating into existing ones.
    score += 0.05 * (open_bins_count as f64) * ((post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p1 = progress;
    let p2 = p1 * p1;
    let p3 = p2 * p1;

    // Penalize wasted space more strongly as stream progresses
    score += pr * (0.5 + 1.5 * p1) * prn * (1.0 + p2);
    score += 8.0 * prn * prn * (0.3 + p3);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 12.0 * (-pr / 15.0).exp() * (0.5 + 0.5 * p1);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - p1 * 0.5);
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 10.0 * (-diff / 20.0).exp();
        // penalize leaving space that's too small for the next item
        if pr < nx {
            score += 6.0 * (1.0 - pr / nx) * (0.5 + p1);
        }
    }

    // Slight preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * 0.05 * (1.0 - p1);

    // Align with mean residual: prefer bins near the mean (smooth coupling)
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev * (0.4 + p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low residue classes
    // (1..=10) is nearly unusable; heavily penalize leaving such slivers.
    let pr = post_residual as i64;
    if pr > 0 && pr <= 10 {
        score += (11 - pr) as f64 * 8.0;
    } else if pr > 10 && pr <= 20 {
        score += (21 - pr) as f64 * 2.0;
    }

    // Perfect fit: zero residual is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: reward when next item fits exactly or well in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= (11 - slack) as f64 * 3.0;
        }
    }
    // Penalize if next item is a near-miss (would leave this bin stranded).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 12.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New empty bin candidate: baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 - 15.0;
        // Opening a new bin is attractive when few bins fit or residual is tiny.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 5.0;
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a real item (min item size 1, but tiny slivers are near-useless)
    // are heavily penalized. Gaps in [1, 10] are "dead space".
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if the post residual cannot fit the next item but is large
    // enough that it "should" have been usable (wasted potential).
    if next_item_size > 0 && post_residual >= 1 && post_residual < next_item_size {
        score += 8.0;
    }
    // Bonus if residual can still accommodate the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: only attractive when no open bin fits well.
        // Penalize opening new bins generally; the penalty scales with the
        // number of open bins and current mean residual slack.
        score += 70.0 + open_bins_count as f64 * 5.0 + mean_residual * 0.3;
    }

    // Mild preference for bins that are already relatively full
    // (smaller residual = tighter packing), non-linear coupling.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Penalize post_residual relative to mean residual: leaving more slack
    // than average wastes capacity across the fleet.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Strong reward for near-exact fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible future item
    // (items are >= 1, but "useful" residual is roughly >= 10 in typical streams).
    if post_residual < 10 {
        score += 6.0; // nearly-full bin is fine only if truly exact
    } else if post_residual < 20 {
        score += 2.5; // awkward small gap
    }

    // ---- 2-step lookahead coupling (archetype core) ----
    if next_item_size > 0 {
        // Perfect chain: this bin's leftover exactly hosts the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward proportionally to how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit in this bin's leftover; penalize gaps that
            // are large but still can't host the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: purely minimize post_residual.
        score -= 4.0 * tightness;
    }

    // ---- Mean-residual anchoring ----
    // Prefer bins whose residual deviates favorably from the fleet mean:
    // filling below-average-residual bins keeps a diverse residual portfolio.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 1.5 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 1.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    // ---- Last-chance bonus ----
    // If this is the ONLY bin that can fit the item, using it avoids opening
    // a new bin; strongly favor it unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when: no good fit exists elsewhere
        // (many fitting bins with large residuals), late in the stream where
        // leftover fragmentation is costly, or when the current bin portfolio
        // is fragmented (high mean residual spread proxy via mean_residual).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 20.0; // default handicap: prefer reusing bins
        // If the item is large relative to capacity, a fresh bin is safer.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 6.0;
        }
        // Many competing bins -> reuse is likely fine; keep handicap high.
        new_bin_score += 0.5 * fitting_bins_count as f64;
        // Late in stream, consolidation matters more -> slightly cheaper to open.
        new_bin_score -= 4.0 * progress;
        // Fragmented portfolio -> a fresh bin gives clean structure.
        new_bin_score -= 5.0 * fragmentation;
        score += new_bin_score;
    }

    // Mild penalty for leaving residuals in the "unusable zone" (1..10)
    // relative to the next item, encouraging gap-aware packing.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * dead * dead;

    // Lookahead coupling: if next item fits the post residual exactly-ish, big reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Post residual too small for next item: penalize proportionally to waste.
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented or
    // the item barely fits nowhere well. Penalize opening new bins when open
    // bins offer reasonable fits.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: prefer filling.
        score += 30.0 * (1.0 - progress) - 10.0 * (1.0 - pressure);
        // If many bins can fit the item, opening a new one is wasteful.
        score += 5.0 * fitting_bins_count as f64;
        // Large items relative to capacity justify fresh bins.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Fragmentation guard: avoid leaving residuals in the awkward 20..50 zone.
    if post_residual >= 20 && post_residual <= 50 {
        score += 10.0 * (1.0 - (post_residual as f64 - 35.0).abs() / 15.0);
    }

    // Global state: many open bins with low mean residual -> prefer consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate slack to keep bins flexible;
    // later, penalize residual more aggressively (smooth polynomial in progress)
    let progress_coupling = 1.0 + 0.8 * progress * progress + 0.5 * progress * progress * progress;
    score *= progress_coupling;

    // Penalize residual relative to the mean residual of open bins (smooth interaction)
    score += 0.35 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 12.0 * (nx / cap) * (1.0 + 0.5 * progress);
        } else {
            // dead space relative to next item: smooth penalty
            let gap = (nx - pr as f64) / cap;
            score += 20.0 * gap * gap * cap;
        }
    }

    // Mild penalty for spreading across too many bins relative to stream progress
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    // Brand-new empty bin candidate: penalize slightly unless it's a great fit
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useless" residue classes (very small, unmatchable slivers) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: dead space (0..=5) — worst outcome, big penalty.
    if post_residual <= 5 {
        score += 40.0;
    }
    // Class B: awkward mid slivers (6..=15) — hard to fill later.
    else if post_residual <= 15 {
        score += 15.0;
    }
    // Class C: perfect closure — bin exactly filled.
    else if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic division classes on capacity fractions: reward leaving residuals
    // that are multiples of common item granularities (4, 8, 16).
    if post_residual % 8 == 0 {
        score -= 6.0;
    } else if post_residual % 4 == 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            score -= 20.0 - (leftover2 as f64) * 0.5;
            if leftover2 <= 5 {
                score -= 10.0; // chain closes the bin almost fully
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is, using integer-division threshold classes.
            let gap_classes = (next_item_size - post_residual) / 10;
            score += gap_classes as f64 * 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline score equal to
    // its full residual (capacity). Prefer it only when no open bin offers a
    // tight fit — i.e., when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; slightly discourage when many bins are open with
        // large mean residual (better to consolidate).
        score += (open_bins_count as f64) * 2.0;
        // Encourage new bin early in the stream when mean residual is small.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // If mean residual across open bins is tiny, packing anywhere is bad
        // anyway; a fresh bin is attractive.
        if mean_residual < 10.0 {
            score -= 25.0;
        }
    } else {
        // Tightness reward: the smaller the relative waste, the better.
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= tightness * 10.0;
    }

    // Mild consolidation pressure: favor bins whose residual is below the
    // mean residual (they are the "fuller" ones).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately useful gap: mild penalty relative to raw residual ordering
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    } else if post_residual > 20 && post_residual <= 40 {
        // Usable gap for mid-size items: slight reward
        score -= 5.0;
    }

    // If the bin can still fit the lookahead item after placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If placement leaves a gap just below the next item (near-dead space), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly discourage opening yet another bin unless fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // New-bin candidate: only attractive when this bin's residual is very
    // tight (item barely fits) or dead space would be created.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).min(1.0);
        // Large items prefer a fresh bin; small items should reuse open bins.
        score = score * 0.0 + 25.0 - 30.0 * tightness;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // lookahead pairs well with a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative exists
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (compact packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins where the next item exactly
    // matches the post_residual (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: mild reward proportional to leftover after it.
            let double_left = post_residual - next_item_size;
            score -= 20.0;
            if double_left == 0 {
                score -= 100.0;
            }
        } else {
            // Next item would NOT fit in this bin's remainder: penalize
            // creating dead space relative to the lookahead demand.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable;
    // wasting a tight bin on a loose item is bad.
    let tightness = mean_residual - bin_residual as f64;
    score += 0.3 * tightness.max(0.0);
    score -= 0.1 * (-tightness).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate penalty: discourage opening a fresh bin unless
    // the item is large relative to capacity (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 150.0 - 100.0 * frac;
    }

    // Early-stream exploration: slightly prefer consolidating into fewer bins
    // when few bins are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream urgency: as the stream ends, minimize residual waste harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: only this bin fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual; penalize leaving medium gaps.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, be pickier about wasting space; late, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));

    // Global residual pressure: many open bins with large mean residual -> favor consolidation.
    if mean_residual > 0.0 {
        score -= 2.0 * (bin_residual as f64 / mean_residual).ln().abs().min(3.0);
    }

    // Mild penalty for opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty grows with stream progress (late dead space is costlier)
    let dead = norm_pr * norm_pr;
    score += 60.0 * progress * dead * (1.0 - norm_item);

    // Reward tight fits (small post residual) more strongly over time
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if next item fits well into post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (next_item_size as f64 / cap) / (norm_pr + 1e-6);
        score -= 15.0 * (1.0 - (fit_quality - 1.0).abs().min(1.0)) * (1.0 - progress * 0.5);
    }
    // If next item cannot fit here, penalize slightly more late in the stream
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - norm_item);
    }

    // New-bin candidate handling: attractive when this item is small relative
    // to capacity (would strand space in an open bin) or late in stream
    if bin_residual == bin_capacity {
        score += 5.0; // slight default cost of opening a new bin
        score -= 30.0 * norm_item * (1.0 - norm_item); // best for mid-size items in fresh bin
        if norm_pr > 0.6 && norm_item < 0.35 {
            score -= 25.0 * (norm_pr - 0.6) * 2.5 * (1.0 - norm_item);
        }
        if norm_item > 0.75 {
            score -= 12.0; // large items fine in fresh bin
        }
    }

    // Crowd penalty: many open bins with high mean residual -> consolidate
    score += 0.5 * (open_bins_count as f64) * (mean_residual / cap) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residual classes that are hard to fill: (0,10] and (25,50)
    if post_residual > 0 && post_residual <= 10 {
        score -= 12.0; // near-perfect fit is excellent
    } else if post_residual > quarter && post_residual <= 2 * quarter {
        score += 8.0; // awkward quarter-to-half dead space
    } else if post_residual > 2 * quarter {
        score += 15.0; // large leftover: bin barely used
    } else if post_residual > eighth {
        score += 2.0;
    }

    // Perfect fill reward via modulo structure
    if post_residual == 0 {
        score -= 25.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0; // round residuals align with typical item classes
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // harmonic coupling: prefer chains where next item's own post-residual stays in a good class
        let chain_post = post_residual - next_item_size;
        let chain_bonus = if chain_post <= 10 { 10.0 } else if chain_post <= quarter { 6.0 } else { 1.0 };
        score -= chain_bonus;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // chain breaks here
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / cap).max(0.1);
        // penalize opening new bins, more so early and when open bins are roomy
        score += 30.0 + 10.0 * (1.0 - progress) + 5.0 * (mean_residual / cap);
        let _ = pressure;
        // allow new bin when item is large and would leave a bad class everywhere
        if item_size >= 3 * quarter {
            score -= 20.0;
        }
    }

    // Mild preference for fullest bins (best-fit flavor) via mean residual contrast
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr); // unusable sliver
        } else {
            // Usable leftover: reward proportionally to how "reusable" it is
            // (residuals matching common item sizes are more valuable).
            score -= 8.0 * ((pr / 20.0).min(4.0));
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Late-stream consolidation: favor reusing existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next_item_size -> perfect pairing
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Near-match: next item leaves small unusable gap
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap < 10.0 {
            score -= 20.0 - 2.0 * gap;
        } else if gap < 0.0 {
            // next item won't fit here; dead space penalty relative to mean residual
            score += 0.3 * (-gap).min(50.0);
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 10.0 * tightness.max(0.0);

    // Penalize tiny post residuals that can't fit minimum-size items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin before opening a new bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight bias against opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residual that cannot hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0 * (1.0 - (post_residual as f64) / 25.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize creating residual just below next item size (wasted sliver).
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 12.0 {
                score += 10.0 * (1.0 - gap / 12.0);
            }
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let crowding = (open_bins_count as f64).ln().max(1.0);
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Early on, prefer filling open bins; late, allow opening more.
        score = 30.0 + 60.0 * (1.0 - late) - 40.0 * pressure + 5.0 * crowding;
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
        return score;
    }

    // Prefer bins with residual close to item size (best-fit flavor) modulated by global mean.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    // Slight preference for filling bins with below-average residual (balance avoidance).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Time horizon: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but its value is modulated by stream progress.
    // Early on, prefer tight fills; later, residual becomes less costly.
    let progress_weight = 1.0 - 0.5 * progress;
    let mut score = pr * progress_weight;

    // Non-linear polynomial coupling: quadratic penalty on small post-residual
    // (dead space) that grows as the stream progresses.
    let dead = (cap - pr) / cap; // fraction of bin used after placement
    score += (1.0 - dead) * (1.0 - dead) * 30.0 * (0.5 + progress);

    // Cubic interaction of normalized post residual with progress:
    // very small residuals (wasted slivers) penalized more strongly later.
    score += norm_pr * norm_pr * norm_pr * 40.0 * progress;

    // Lookahead: reward bins whose post-residual can fit the next item,
    // scaled smoothly by progress.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for bins far from the mean residual (fragmentation avoidance).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Slight preference for using existing bins over opening new ones,
    // weakening as stream progresses.
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class by capacity fraction: leftover in (0,10] nearly dead, (10,20] poor, etc.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        // dead space class: nearly unusable
        score += 25.0;
    } else {
        // modulo arithmetic on post_residual: residuals divisible by 10 pair
        // well with the 1..100 integer item universe
        let m = post_residual % 10;
        if m == 0 {
            score -= 12.0; // round residual: high chance a future item fits exactly
        } else if m >= 7 {
            score += 6.0; // awkward remainder
        }
        // integer-division threshold classes on post residual
        let class = post_residual / 10; // 1..=10
        // reward larger usable classes mildly, saturating
        score -= (class as f64).min(5.0) * 2.0;
    }

    // Fraction-of-capacity coupling: post_residual as fraction of capacity
    let frac = post / cap;
    score += (frac * frac) * 20.0; // penalize large leftover fraction (wasteful bins)

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge dead space)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 15 {
            score -= 40.0; // keep item here, good fit, avoid new bin
        } else {
            score -= 10.0; // mild preference still
        }
    }

    // New-bin candidate handling: an empty bin has full residual.
    // Prefer new bin only when the item would leave huge dead space everywhere.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin: its "post_residual" is large
        score += 15.0;
        if next_item_size > 0 && next_item_size as f64 >= post * 0.9 {
            // next item nearly fills a fresh bin too -> opening is attractive
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: mild penalty scaled by mismatch
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.2;
        }
    }

    // Stream progression: early on, be more willing to spread into new bins;
    // late, tighten packing (favor tight fits more strongly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post) * 0.15;

    // Crowd control: many open bins -> prefer consolidating into existing bins
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's post residual is far below the mean,
    // it is a tighter-than-average fit -> reward.
    score -= (mean_residual - post) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
