        if post_residual >= 10 {
            score -= 10.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (tighter bins) to keep spread low.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // residual can't host next item
    }

    // Late-stream consolidation: fewer new bins toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
