    }

    // Prefer filling bins that are already relatively empty (larger bin_residual)
    // to keep tighter bins available for future items — classic best-fit flavor,
    // but modulated by mean residual.
    let rel_residual = bin_residual as f64 / bin_capacity as f64;
    score += 6.0 * rel_residual;

    // Global pressure: when many bins are open relative to progress,
    // encourage consolidation (penalize spreading across bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += 0.02 * pressure * (1.0 - progress);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // If the current bin would leave a very poor fit, opening fresh is better.
        if fit_ratio > 0.5 {
            score -= 20.0;
        }
        // If few bins fit the item and the fit is bad, new bin becomes competitive.
        if fitting_bins_count <= 2 && fit_ratio > 0.35 {
            score -= 15.0;
        }
        // Perfect-fit items (item fills a fresh bin exactly) get a bonus for new bins.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Normalized post-residual and its polynomial couplings with stream progress
    let pr_norm = post_residual as f64 / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Later in the stream: waste penalized more strongly (non-linearly)
    score += (pr2 * 6.0 + pr3 * 10.0) * (0.4 + 1.2 * progress);

    // Reward tight fits: subtract proportional to fill fraction, amplified late
    let fill = item_size as f64 / cap;
    score -= fill * fill * (8.0 + 6.0 * progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: prefer leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post_residual as f64 - nxt;
        if diff < 0.0 && diff >= -20.0 {
            // near-miss waste: penalize mildly
            score += 2.0 * (1.0 - (-diff) / 20.0) * (1.0 + progress);
        } else if diff >= 0.0 && diff <= 30.0 {
            // good chain fit: reward
            score -= 3.0 * (1.0 - diff / 30.0);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Penalize many open bins slightly (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 3.0 + 2.0 * (1.0 - progress) - 0.05 * mean_gap;
        // discourage opening new bins when a tight fit exists elsewhere
        if post_residual as f64 > cap * 0.5 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // for items of size >= 10; classify via integer division thresholds.
    let dead_class = post_residual / 10; // 0..10 harmonic class
    // Penalize small unusable classes heavily (class 0 = perfect fit handled by low score).
    if post_residual > 0 {
        score += match dead_class {
            0 => 8.0,   // residual 1..9: dead space
            1 => 4.0,   // 10..19: only tiny items fit
            2 => 2.0,   // 20..29
            3 => 1.0,   // 30..39
            _ => 0.0,
        };
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 6.0; // exact pairing
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate: make it moderately unattractive unless current bin
    // would leave terrible dead space or bin is already tight.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish score; slightly prefer it only when the stream
        // is early (many items left to amortize) and item is small.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 + 4.0 * progress - 0.02 * item_size as f64;
    }

    // Prefer filling bins below mean residual (i.e., tighter-than-average bins).
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Small coupling: reward near-full placements (post_residual < 5% capacity).
    if post_residual * 20 < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are "dead". Penalize them quadratically.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64) * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Pressure from open bins: when many bins are open, prefer filling
    // existing ones rather than spreading; when few open, allow new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (0.5 + 0.5 * progress);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - gap / 80.0);
        }
    }

    // New empty bin candidate: only attractive when it enables a great
    // future fit or existing bins are nearly saturated.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) <= 5.0 {
            score -= 10.0;
        }
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    // Mild preference for bins below the mean residual (balance residuals).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact matches with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.6;
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.9;
        }
    }

    // Penalize large post_residuals relative to mean residual (wasteful big gaps)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tighter existing bins over the empty new-bin candidate
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, prefer minimizing bin count more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let dead = (post_residual as f64 / item_size.max(1) as f64).min(2.0);
        score += 12.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 {
        // Penalize creating residual too small for the next item (wasted gap).
        score += 10.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // When many bins can fit the item, prefer the tightest one; soften competition.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a new bin is only attractive if all open bins
    // have poor residuals relative to the item, or few bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        // Penalize opening new bins when existing residuals are decent.
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But discount the penalty if open bins are mostly unusable.
        score -= 2.0 * avg_waste.min(40.0);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for bins with residuals below the mean (compact them early).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post-residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial penalty for dead space (very small residuals are hard to fill)
    let dead = (1.0 - prn).powi(4);
    score += 25.0 * dead * (0.5 + progress);

    // Reward tight fits with smooth coupling to progress
    let tightness = 1.0 - (prn * 2.0 - 1.0).powi(2); // peaks at prn = 0.5
    score -= 12.0 * tightness * (1.0 - progress);

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (nxt / pr.max(1.0)).powi(2));
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize spreading across too many open bins relative to mean residual
    score += 0.3 * (open_bins_count as f64).powf(0.7) * (prn - mean_residual / cap).abs();

    // New-bin candidate: mild penalty so we prefer existing bins unless they're bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit (residual in {0}) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class 1: tiny unusable residual (<= 10) -> strongly reward.
    else if post_residual <= 10 {
        score -= 200.0;
    }
    // Class 2: residual in harmonic quarter band (11..25)
    else if post_residual <= 25 {
        score -= 60.0;
    }
    // Class 3: residual in half band (26..50)
    else if post_residual <= 50 {
        score += 30.0;
    }
    // Class 4: large residual (> 50) -> mild penalty, bin stays useful.
    else {
        score += 10.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with typical item sizes; reward those.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }

    // Integer-division threshold: residual >= next_item_size means lookahead
    // item can also land here -> reward chaining.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.25 * (next_item_size as f64);
            // exact chain: post_residual == next_item_size -> double reward
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Lookahead cannot fit here: penalize proportionally to waste.
            score += 0.15 * (next_item_size as f64);
        }
        // Harmonic pairing: residual % next_item_size small -> good future fit.
        if next_item_size > 0 && post_residual % next_item_size <= 5 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty): only attractive when item is large relative
    // to capacity and open bins are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score = 60.0 + 80.0 * large_item;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 90.0; // no open bin holds this item well -> open new bin
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Progress coupling: later in the stream, favor tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - pr / cap);

    // Fragmentation guard: penalize when this bin's residual is far below mean
    // (i.e., we would be wasting the tightest bin on a loose fit).
    if (mean_residual - pr).abs() > 0.5 * cap {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum item size of 1..100 stream, treat <15 as dead)
    // are heavily penalized, but a perfect fit (0) is rewarded.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual < 15 {
        score += 60.0; // unusable sliver -> dead space
    } else if post_residual <= 30 {
        score += 15.0; // awkward gap
    } else {
        // larger residuals remain useful: slight reward
        score -= 5.0;
    }

    // Reward tightness relative to bin capacity
    score += (bin_residual - item_size) as f64 * 0.3;

    // Pressure from number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 2.0;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (avoid wasting large-residual bins on small items when alternatives exist)
    let gap = (bin_residual as f64 - mean_residual).abs();
    score += gap * 0.2;

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score += 40.0; // next item would create dead space here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced if existing fits are poor
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 80.0; // existing last-chance bin should be used
        }
        // late in the stream, avoid opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post-residual of this bin (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Reward if next item can at least fit into the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.5;
    }
    // Penalize leftovers too small for the next item (dead space risk),
    // scaled by how close the leftover is to being useless.
    if next_item_size > 0 && post_residual < next_item_size {
        let deadness = post_residual as f64 / next_item_size as f64;
        score += (1.0 - deadness) * 25.0;
    }

    // Penalize very small unusable leftovers generally.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean
    // (tighter bins absorb items first), penalize dipping far below mean.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): penalize unless it looks genuinely better
    // than squeezing into open bins. Empty bins start with a handicap that
    // shrinks as the stream progresses (fewer wasted opportunities later).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 90.0 - 30.0 * progress;
        // Opening a new bin is more attractive when next item is large
        // and no open bin offers a good chain.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fit * fit;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prioritize consolidation of open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 0 {
        score -= (open_bins_count as f64).ln() * 2.0;
        if mean_residual > (item_size as f64) {
            score -= 5.0;
        }
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += desperation * (20.0 + 10.0 * fit);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin preserves room for a larger follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post_residual, with smooth non-linear saturation
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Tight-fit reward: quadratic coupling of fill ratio with stream progress
    let fill = item / cap;
    score -= 25.0 * fill * fill * (1.0 + progress);

    // Penalize post_residual that is too small to be useful (dead space),
    // smooth bump around very small residuals
    let dead = (1.0 - norm_post).min(1.0);
    score += 10.0 * (norm_post * (1.0 - norm_post)).abs() * (norm_post - 0.5).abs() * 40.0;

    // Lookahead: reward if next item fits into resulting post_residual
    if nxt > 0.0 && nxt <= post {
        score -= 12.0 * (nxt / cap) * (1.0 - progress * 0.5);
    } else if nxt > post && nxt > 0.0 {
        score += 4.0 * (1.0 - post / cap) * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 8.0 * (1.0 - scarcity) + 6.0 * (1.0 - progress);
        // But allow new bin when mean residual across open bins is very low
        score -= (mean_residual / cap).max(0.0) * 10.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: rewards residuals that are
    // "usable" multiples / divisors of common size classes.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect fill
    } else {
        // residual divisible by common item sizes => likely reusable
        for d in [10u32, 20, 25, 50, 40, 30] {
            if pr % d == 0 {
                harmonic_bonus -= 8.0;
            }
        }
        // small dead space (< smallest item) is dead weight
        if pr < 10 {
            harmonic_bonus += 15.0;
        }
        // residual in awkward band 11..=19 often unusable
        if pr >= 11 && pr <= 19 {
            harmonic_bonus += 6.0;
        }
    }
    score += harmonic_bonus;

    // Tight fit reward: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill;

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0; // next item must go elsewhere; wasted residual
        } else if post_residual - next_item_size <= 10 {
            score -= 18.0; // next item nearly completes this bin
        }
    } else {
        // last item: strongly prefer perfect fill
        score -= 20.0 * (1.0 - (pr as f64 / cap));
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer bins with below-mean residual (concentrate fill)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so open bins are preferred unless fit is poor
        score += 30.0;
        // if item is large relative to typical residual, new bin may be better
        let waste_if_open = (mean_residual - item_size as f64).max(0.0);
        score -= 1.5 * waste_if_open;
        // late in stream, consolidating is cheaper
        score += 20.0 * (1.0 - progress);
        // many open bins: encourage spreading
        score -= 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    // Reward bins whose post_residual exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        // Exact match is heavily rewarded; near-match decays quadratically.
        let match_reward = 60.0 * (1.0 - (gap / 50.0).min(1.0)).powi(2);
        score -= match_reward;

        // If next item cannot fit in post_residual, penalize a little
        // (forces us to prefer bins leaving room for the lookahead item).
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 20.0;
    }

    // --- Dead-space penalty: very small unusable leftovers ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // --- Last-chance bonus: this is the only bin that fits the item ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when no open bin fits well
        // (poor fit: post_residual far from next item) or item is huge.
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() > 20.0
        } else {
            false
        };
        if poor_fit || item_size >= 80 || post_residual < 10 {
            score -= 30.0;
        } else {
            // Discourage wasteful bin proliferation.
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    }

    // --- Mild mean-residual coupling: prefer bins deviating toward fullness ---
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // --- Stream progression: tighten packing as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure is excellent
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin;
    // if next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else {
            score += 10.0;
        }
        // Chain fit: post_residual exactly matches next item => strong reward
        if post_residual == next_item_size {
            score -= 22.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of open bins.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins are fragmented or item is huge.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 12.0 * fragmentation / (bin_capacity as f64)
            - 15.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate into fuller bins.
    let pressure = mean_residual / (bin_capacity as f64) * (open_bins_count as f64).ln1p();
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild time-horizon modulation: early stream favors flexibility, late stream favors filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64)
        - 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty on very small residuals.
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-perfect packing: smooth polynomial dip as post_residual -> 0.
    score -= 8.0 * (1.0 - norm_pr).powi(6) * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead = ((norm_pr * 4.0 - 0.4).powi(2)).max(0.0);
    score += 10.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = (pr - nx).abs();
        let fits_next = (nx <= pr) as i32 as f64;
        score -= 15.0 * fits_next * (1.0 - fit / cap).powi(3);
        score += 6.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Stream-progress coupling: later in stream, be more aggressive about filling bins tightly.
    let open_f = open_bins_count as f64;
    score -= 4.0 * progress * (mean_residual / cap - norm_pr).abs();
    score += 3.0 * progress * norm_pr * (open_f / (open_f + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/2, 1/3, 1/4 thresholds)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Item class: 0 = tiny, 1 = small, 2 = medium, 3 = large
    let item_class = if item_size > half { 3 } else if item_size > third { 2 } else if item_size > quarter { 1 } else { 0 };
    let next_class = if next_item_size == 0 { 9 } else if next_item_size > half { 3 } else if next_item_size > third { 2 } else if next_item_size > quarter { 1 } else { 0 };

    // Reward tight fits (small post_residual), especially in low classes
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold any plausible future item
    if post_residual < quarter && post_residual > 0 {
        score += (quarter - post_residual) as f64 * 0.9;
    }

    // Harmonic pairing: reward when post_residual can host next item's class
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Bonus if post_residual mod next_item_size is small (near-exact refill)
            let r = post_residual % next_item_size.max(1);
            score -= 4.0 * (1.0 - (r as f64) / (next_item_size.max(1) as f64));
        } else {
            // Next item won't fit here: penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
        // Large item followed by large item: prefer fresh bin
        if item_class == 3 && next_class == 3 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        // But if current item is large and next is also large, opening fresh is fine
        if item_class == 3 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual > mean_residual {
        score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64 * (1.0 - progress);
    }

    // Modulo threshold on post_residual: residue classes 1..=3 are worst dead space
    if post_residual >= 1 && post_residual <= 3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any future item
    // (items in [1,100], so any residual is technically usable, but small gaps
    // under ~10 are nearly dead weight) get an extra nonlinear penalty.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0;
    }

    // Penalize moderate unusable gaps: gaps that cannot fit the next item are
    // likely dead space for the remainder of the stream.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 2.0;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using a bin whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= tightness * 0.3;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item is large and this bin would be the only full bin,
        // opening a new bin may still be attractive; soften slightly.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (keep residuals balanced).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late-stream urgency: as the stream nears its end, prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: squaring emphasizes small residuals (tight fits) as good.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward when the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot use this bin's remainder: penalize more as residual shrinks
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post residual would be tiny/dead).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 15.0; // nearly perfect fill
        }
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or open-bin residuals are poor.
    if bin_residual == bin_capacity {
        score += 10.0; // base cost of opening a new bin
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 20.0 * (tightness - 0.7) / 0.3; // large items deserve fresh bins
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0; // existing bins have plenty of room; don't open new
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size as u32 {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Mild pressure toward consolidating many open bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Tie-break toward bins below mean residual (using the "emptier" ones first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.35 * tightness * (bin_residual as f64);

    // Penalize dead space: small post_residual that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver under min item size
    } else if post_residual > 0 && post_residual < 25 {
        score += 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: bonus if next item fits the post-residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.4 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap that just misses the next item.
            let gap = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
            if post_residual > 0 && post_residual < next_item_size {
                score += 0.25 * (next_item_size - post_residual) as f64;
            }
            let _ = gap;
        }
    }

    // Time horizon: later in stream, be more conservative, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins early / when alternatives exist.
        score += 15.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Only attractive when mean residual of open bins is tiny.
        score += 0.2 * mean_residual;
    }

    // Prefer balancing load across bins when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for very large item into a nearly full bin (waste risk).
    if item_size > bin_capacity / 2 && post_residual > 0 && post_residual < item_size / 2 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * x) - 12.0 * progress * x * (1.0 - x) * cap * 0.1;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - x;
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + progress);
        } else {
            score -= 0.15 * (pr - nx).min(40.0) * (1.0 - progress);
        }
    } else {
        // Last item: strongly reward minimal post residual
        score -= 30.0 * tightness * tightness;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Discourage opening new bins when reasonable fits exist, more so late
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - progress) + 6.0 * progress;
        // But allow fresh bin if all fits would leave large dead space
        if fitting_bins_count > 0 && x < 0.2 {
            score -= 20.0;
        }
    }

    // Smooth mean-residual coupling: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs();
    score += 0.08 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue classes mod small integers
    let pr = post_residual;
    let mod4 = (pr % 4) as f64;
    let mod8 = (pr % 8) as f64;
    let mod16 = (pr % 16) as f64;

    // Penalize post-residuals that fall into "dead" classes: tiny but nonzero
    if pr > 0 && pr < 10 {
        score += 40.0 - 3.0 * pr as f64; // unusable sliver
    }

    // Reward residuals in harmonic classes likely to absorb future items
    // (multiples of common item granularities)
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Modulo coupling: post_residual vs next_item_size compatibility
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by tightness
            let tightness = (pr - next_item_size) as f64;
            score -= 25.0 - 0.3 * tightness;
            // exact fit for next item is golden
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item won't fit: penalize proportional to wasted potential
            score += 0.15 * (next_item_size - pr) as f64;
        }
        // harmonic class match: next_item_size mod 10 aligning with pr mod 10
        if pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 8.0;
        }
    }

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 10.0; // bin still half usable, good
    } else if pr >= quarter {
        score += 2.0; // moderate zone, mild penalty
    } else if pr > 0 {
        score += 8.0; // below quarter, risky dead space
    } else {
        score -= 20.0; // perfect closure
    }

    // Fine-grained modulo texture penalty on near-closed bins
    score += 0.5 * mod4 + 0.25 * mod8 + 0.125 * mod16;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad class
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.2 * open_bins_count as f64;
        // discourage new bin if item fits well in an existing harmonic slot
        let bad_fit = if pr < 10 || (next_item_size > 0 && next_item_size > pr) { 0.0 } else { 30.0 };
        score = base + bad_fit;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Progress-aware mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: prefer bins close to mean (balanced packing)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste, but very small gaps (< 10) are the worst since items
    // can be as small as 1; treat gap < 10 as dead space penalty.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize bins whose residual is barely above the item (awkward fit).
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 && slack < 15.0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin becomes more costly.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: default cost plus pressure; only attractive
        // when no open bin fits well (handled implicitly by comparison).
        score += 30.0 + pressure;
        // If the next item is large and this bin would be nearly full after
        // placing the current item, opening fresh is slightly better.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild reward scaled by how much pressure exists.
        score -= pressure * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Would leave a dead gap after next item; slight penalty.
        score += 8.0;
    }

    // Late in the stream, tighten up: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (emptier bins absorb items better,
    // keeping tight bins available for small items).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins
    if bin_residual == bin_capacity {
        score += 150.0;
        if post_residual as f64 > mean_residual {
            score += 50.0;
        }
    }

    // Progress-based mild preference to close out bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty grows superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here anyway; slightly penalize leaving
            // dead space smaller than the smallest plausible item.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item in stream: just minimize residual.
        score -= 20.0;
    }

    // Prefer bins that are already relatively full (small residual before placement)
    // to consolidate waste into few bins.
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Global pressure: when many bins are open relative to stream progress,
    // discourage opening new bins (penalize the empty-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin plus pressure scaling.
        score += 60.0 + 40.0 * progress + (open_bins_count as f64) * 2.0;
        // But if current bin fits are all loose (high mean residual vs item),
        // opening a fresh bin may be better: relax the penalty.
        if mean_residual > (item_size as f64) * 1.5 {
            score -= 45.0;
        }
    } else {
        // Existing bin: mild reward when bins are plentiful / mean residual is high.
        if mean_residual > (item_size as f64) * 2.0 {
            score -= 5.0;
        }
    }

    // Time horizon: late in the stream, be greedy about minimizing residual now.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - (post / cap); // how well item fills bin

    let mut score = post;

    // non-linear coupling: reward tight fits more as stream progresses
    score -= 12.0 * tight * tight * (0.4 + 0.6 * progress);

    // penalize dead space quadratically, scaled by stream progress
    score += 0.035 * post * post / cap * (0.5 + 0.5 * progress);

    // last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - progress * 0.4);
    } else if next_item_size > 0 {
        score += 2.0 * (post - next_item_size as f64).abs() / cap;
    }

    // mild preference for bins below mean residual (balance avoidance of fragmentation)
    score += 0.03 * (post - mean_residual).abs();

    // new-bin candidate: neutral-ish baseline with slight penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "awkward" classes (small, hard-to-fill leftovers) get penalized.
    let pr = post_residual;
    let class = pr % 10; // decade class
    // Penalize odd/awkward leftovers slightly, reward round residuals.
    score += (class as f64) * 0.35;

    // Strong penalty for tiny dead space (waste): residual < 10 is nearly unusable
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Reward perfect fits heavily
    if pr == 0 {
        score -= 200.0;
    }

    // Harmonic fraction of capacity used
    let used_frac = (bin_capacity - pr) as f64 / cap;
    score -= used_frac * 25.0;

    // Integer-division threshold: if next item fits exactly into post_residual,
    // this is a harmonic chaining opportunity -> reward.
    if next_item_size > 0 && next_item_size <= pr {
        let next_post = pr - next_item_size;
        score -= 30.0;
        // Extra reward if next item also leaves a round residual (double chain)
        if next_post % 10 == 0 {
            score -= 20.0;
        }
        // Penalize if next item barely fits (leaves near-dead space)
        if next_post > 0 && next_post < 10 {
            score += 25.0;
        }
    }
    // If next item does NOT fit this bin, residual must serve later items;
    // keep moderate residuals valuable, tiny ones worthless.
    if next_item_size > 0 && next_item_size > pr && pr > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // or all fits are poor (high mean residual waste).
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste = mean_residual / cap; // average emptiness of open bins
        // Opening a new bin is good when existing bins are nearly full
        // (low mean residual) or item fits nowhere; bad when open bins are roomy.
        score = 40.0 - poor_fits * 100.0 - (1.0 - waste) * 30.0;
        // Late in stream, mildly discourage accumulating bins
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
        return score;
    }

    // Prefer tighter bins when several fit (best-fit flavor via residual already),
    // plus slight diversity bonus: spread across many open bins is fine.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Gap too small for any item (min size 1..100, but tiny gaps waste capacity)
            score += 40.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits (high fill ratio of the residual)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate
        score += 12.0 + 20.0 * progress + 0.8 * open_bins_count as f64;
        // If this is the last chance bin, opening a new bin is bad
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strong reward to use this bin instead of opening a new one
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; leaving a large gap is worse
            score += 3.0;
        }
    }

    // Mild preference toward bins with residual below mean (consolidate space)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: keep bins tight (small post_residual wins).
    // Non-linear penalty for dead space that cannot fit typical future items.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 30.0; // near-perfect fill, tiny dead space
        } else if post_residual < 20 {
            score -= 12.0;
        } else {
            score += (post_residual as f64 - 20.0) * 0.6;
        }
    } else {
        score -= 60.0; // exact fill: ideal
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fits
    // the residual left behind.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            // next item fits; the smaller the leftover after that, the better
            let two_step_left = post_residual - next_item_size;
            score -= 20.0 - (two_step_left as f64) * 0.5;
        } else {
            // next item cannot fit: residual becomes dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Compare against mean residual: bins tighter than average are better to fill.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalate with more open bins
        // (encourages closing out existing bins first).
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the next item is huge and current item is small, a fresh bin
        // may be reserved for the big one.
        if next_item_size > 0 && next_item_size >= 70 && item_size <= 40 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild stream-progress term: early on, be more willing to spread items
    // across bins (keep flexibility), late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let nz = next_item_size as f64;
        if (post_residual as f64) < nz {
            score += 0.35 * (nz - post_residual as f64);
        } else {
            score -= 0.15 * (post_residual as f64 - nz).min(30.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Time horizon: early on, prefer filling existing bins less aggressively
    // (keep flexibility); late in stream, squeeze everything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - fit_ratio_or(post_residual, bin_capacity));

    // Global state coupling: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 3 {
        let excess = mean_residual - post_residual as f64;
        score += 0.05 * excess.max(-20.0);
        score -= 0.4 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when current bin fits are very poor.
    if bin_residual == bin_capacity {
        let best_possible = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 100.0 - 30.0 * best_possible
            + if fitting_bins_count == 0 { -40.0 } else { 10.0 * (fitting_bins_count as f64) };
        if post_residual < 20 {
            score -= 25.0; // item nearly fills a fresh bin entirely
        }
    }

    score
}

#[inline]
fn fit_ratio_or(post_residual: u32, capacity: u32) -> f64 {
    1.0 - (post_residual as f64 / capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized smoothly with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Non-linear polynomial coupling: dead space matters more as stream advances
    let dead = norm_pr * norm_pr;
    score += 25.0 * dead * (0.3 + 0.7 * progress);

    // Lookahead: reward bins whose post-residual can hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mean-residual coupling: prefer bins near the mean to keep flexibility
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for reusing open bins over opening new ones
    if bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions (1/2, 1/3, 1/4 of C)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward landing exactly on harmonic class boundaries (usable dead space)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual == half {
        score -= 40.0;
    } else if post_residual == third {
        score -= 30.0;
    } else if post_residual == quarter {
        score -= 20.0;
    }

    // Penalize post-residuals in "dead zones": too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: multiples of 10 are reusable slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize small leftover waste
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if item is large and few bins fit it, new bin is less bad
        if item_size > half && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Prefer tighter fits overall: relative fill ratio
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Stream progression: early on, be conservative (keep bins flexible)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.05 * post_residual as f64;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Spread penalty: avoid bins far from mean residual (keeps balance)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Gap too small for any item (min size 1..100, but tiny gaps are waste)
            score += (10.0 - pr) * 6.0;
        } else if pr < 20.0 {
            // Likely dead zone unless future small items arrive
            score += (20.0 - pr) * 2.5;
        } else {
            // Larger residual still usable: mild reward proportional to size
            score -= pr * 0.05;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Tight-fit reward: how well the item fills the bin relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only allow opening a new bin if current bin
    // would leave a large awkward residual or no open bins fit well.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin; becomes attractive when alternatives are bad
        score += 15.0;
        if post_residual < 20.0 {
            // Item nearly fills a fresh bin: good to open a new bin
            score -= 20.0;
        }
    }

    // Lookahead: if next item could exactly use the resulting gap, reward it
    if next_item_size > 0 && post_residual > 0 {
        let gap_diff = (post_residual as i64 - next_item_size as i64).abs();
        if gap_diff == 0 {
            score -= 35.0;
        } else if (gap_diff as f64) < 10.0 {
            score -= 10.0;
        } else {
            score += gap_diff as f64 * 0.3;
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean (consolidate emptier bins)
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Stream progression: early on, be more tolerant of spreading; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Next item exactly fills this bin: outstanding placement.
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item fits in the remaining space.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would not fit; penalize by the shortfall.
            score += 12.0 * (gap / bin_capacity as f64);
        }
        // Bonus if next item also fits tightly (gap small relative to item size).
        if gap < (next_item_size as f64) * 0.25 {
            score -= 10.0;
        }
    }

    // Relative to mean residual: prefer bins with residuals near/below the mean
    // (i.e., filling up fuller-than-average bins first).
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate penalty: discourage opening a new bin unless it enables
    // a perfect 2-step chain (item + next item exactly fill capacity).
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let slack = bin_capacity - item_size - next_item_size;
            if slack == 0 {
                score -= 100.0; // perfect 2-item new bin
            } else {
                score += slack as f64 * 0.3;
            }
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving a small, hard-to-use sliver (dead space zone).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if next item is large relative to what remains.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain;
        } else {
            // next item cannot use the leftover: waste is more likely
            score += 8.0 * (1.0 - (bin_residual - next_item_size.min(bin_residual)) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or open bins are already crowded with large residuals.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // Open new bin when existing residuals are small (crowded) or few options.
        let pressure = (avg_tightness * 2.0).min(1.0)
            + if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 45.0 * pressure;
        // Early in the stream, opening bins is cheap and builds diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the next item is huge, a fresh bin is valuable.
        if next_item_size >= 70 {
            score -= 12.0;
        }
    }

    // Slight preference to fill bins that deviate from the mean residual
    // (consolidate toward similar fill levels).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild scaling by number of open bins to encourage consolidation when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear penalty on very small post_residuals that are still unusable:
    // quadratic term rewards post_residual near 0 but punishes awkward mid-range waste
    let waste = norm_pr * norm_pr;
    score += 40.0 * waste * (1.0 + 0.5 * progress);

    // Cubic coupling: dead space matters more as the stream progresses
    score += 25.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Interaction with item size: placing large items should be prioritized
    score -= 30.0 * norm_item * (1.0 - norm_pr);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_ratio = nx / pr.max(1.0);
            score -= 20.0 * fit_ratio * (1.0 - fit_ratio + 0.5);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: penalize opening new bins when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins near the mean (balance preservation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make empty bins moderately attractive only early or for large items
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score = score * 0.5 + 30.0 * (1.0 - progress) + 50.0 * norm_item * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;
    score += frac * frac * 40.0;               // quadratic penalty on wasted fraction

    // Harmonic class of post_residual: bins whose leftover falls in "dead zones"
    // (too small for typical items) are penalized; leftovers that can still host
    // common item sizes are rewarded.
    if post_residual > 0 {
        // dead space: cannot hold even a small item
        if post_residual < 10 {
            score += 30.0;
        } else {
            // class of residual by integer division into decile bands
            let band = post_residual / 10;
            // mid bands (1..3 => 10..39) are awkward; large bands are reusable
            match band {
                1 => score += 12.0,
                2 => score += 6.0,
                3 => score += 2.0,
                _ => score -= 4.0,
            }
        }
        // exact harmonic fit: post_residual divisible by common item classes
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to how close it is
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += miss * 0.3;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let crowded = open_bins_count as f64 * mean_residual / cap;
        // new bin is expensive early; acceptable late or when residuals are tiny
        score += 45.0 - 30.0 * progress - crowded.min(20.0);
        // a new bin always leaves 100 - item_size residual
        score += (item_size as f64) * 0.2;
    } else {
        // slight preference for fuller bins among open candidates
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
        // many fitting bins: mild diversity bonus to keep options open
        if fitting_bins_count > 3 {
            score += 2.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // relatively empty; deprioritize slightly.
    let dev = mean_residual - post;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100)
    // are only usable by tiny items; treat very small gaps as wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Moderate gaps (10..30) are semi-unusable; graded penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.5;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // If the next item fits exactly into the post residual, reward heavily (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; slight penalty for stranding.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // i.e., penalize the empty new-bin candidate.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score += 20.0 + 10.0 * pressure;
        // But if nothing fits well (many fitting bins means competition), soften.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // fragmented bin — prefer filling fragmented bins to consolidate.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Slight late-stream tightening: as stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 80.0;
            } else if chain_waste <= 25 {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: post residual becomes dead space.
            let dead = post_residual as f64;
            score += dead * 0.5;
        }
    }

    // Compare against mean residual: penalize bins far below mean (tight bins),
    // reward bins above mean (loose bins absorb item better).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current fit is poor.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual <= 10 || (next_item_size > 0 && next_item_size >= post_residual && post_residual - next_item_size <= 10);
        if tight_fit {
            score += 500.0; // discourage opening new bin when fit is good
        } else {
            score += 50.0; // mild penalty; poor fits elsewhere may still lose
        }
    }

    // Late in stream: prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.10 * next_item_size as f64;
    } else {
        // Post-residual is dead space with respect to lookahead item
        score += 2.0 + 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin when alternatives exist,
    // more so early in the stream (fragmentation risk grows with open bins)
    if bin_residual == bin_capacity {
        score += 10.0 * fitting_bins_count as f64 + 5.0 * (1.0 - progress);
        if open_bins_count > 8 {
            score -= 4.0; // allow new bins when many are open (spread load)
        }
    }

    // Global-state coupling: mildly prefer bins in low-residual (well-filled) regimes
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();

    // Tight-fit bonus scaled by how full the bin already is
    let fill = (cap - bin_residual as f64) / cap;
    score -= 6.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), non-linearly amplified.
    let mut score = pr * (1.0 + 0.9 * pr / cap);

    // Dead-space penalty: residual too small to ever fit future items.
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 12.0 * dead * dead;

    // Polynomial coupling with stream progress: tighter fits matter more later.
    let t = progress;
    score += 8.0 * pr * (t * t + 2.0 * t * (1.0 - t) * 0.5) / cap;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - t);
    }

    // Prefer filling bins that are already partially filled (avoid bin sprawl).
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= 6.0 * fill_ratio * fill_ratio;

    // New-bin candidate: penalize opening a new bin, more when many open bins
    // exist and mean residual is still usable.
    if bin_residual == bin_capacity {
        score += 18.0 + 1.5 * open_bins_count as f64 + 0.25 * mean_residual;
        // But if lookahead item fits the fresh bin nicely, soften the penalty.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= pr {
                score -= 10.0 * (1.0 - ((pr - nxt) / cap).abs());
            }
        }
    }

    // Lookahead synergy: reward bins whose post residual accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - t);
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer division
    // into capacity-fraction buckets. Small leftovers (class 0: 1..=10) are near-perfect
    // fills and are heavily rewarded; large leftovers are progressively penalized.
    let post_class = post_residual / (bin_capacity / 10).max(1); // 0..=10 classes
    let class_reward = match post_class {
        0 => 60.0,
        1 => 25.0,
        2 => 8.0,
        3 => 0.0,
        4 => -6.0,
        5 => -10.0,
        6 => -14.0,
        7 => -18.0,
        8 => -24.0,
        9 => -30.0,
        _ => -36.0,
    };
    score -= class_reward;

    // Exact fill bonus: modulo arithmetic on capacity fractions.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Compatibility with the lookahead item: if the next item fits exactly into the
    // post residual, strongly reward; if the next item cannot ever use the leftover,
    // penalize proportionally to wasted capacity fraction.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let fit_frac = next_item_size as f64 / post_residual as f64;
            // harmonic-style reward: closer to full reuse -> bigger bonus
            score -= 20.0 * fit_frac * fit_frac;
        } else {
            // leftover too small for next item: dead-space penalty scaled by class
            score += (post_class as f64) * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer tighter fits: reward low post_residual more.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: an empty bin has large residual. Only allow it when
    // current bins would leave very poor fits or the stream is early/many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tightness = 1.0 - (mean_residual / cap);
        // Penalize new bin normally; discount the penalty if open bins are very full
        // on average (little room anywhere) or many bins are already open.
        let mut penalty = 70.0;
        penalty -= mean_tightness * 40.0;
        penalty -= (open_bins_count as f64).min(10.0) * 2.0;
        penalty -= progress * 15.0;
        score += penalty.max(0.0);
    }

    // Mild preference for bins whose residual deviates from the mean in a useful way:
    // a bin tighter than average is a better home for a large item.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.05;

    // Small tie-breaker against fragmentation as stream progresses.
    score += (post_residual as f64).sqrt() * (0.2 + 0.3 * (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Lookahead: reward if the leftover can host the next item, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when the stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidate small leftovers).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // New-bin candidate: make empty bins mildly attractive only when item is large
    // or current bins are crowded; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 - 15.0 * (item_size as f64 / 100.0) - 3.0 * crowded.min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted (dead) space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if the next item exactly or nearly fits the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack_after_next = post_residual as f64 - next;
            // Reward tight 2-chain packing (post_residual consumed by next item)
            score -= 30.0 * (1.0 - slack_after_next / 100.0);
            if slack_after_next == 0.0 {
                score -= 40.0; // perfect 2-item chain
            }
        } else {
            // Next item cannot follow here; mildly penalize unless bin is nearly full
            let fill_ratio = item_size as f64 / bin_capacity as f64;
            score += 10.0 * (1.0 - fill_ratio);
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residual below mean residual (compact bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are poor
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score += 5.0; // fresh bin has no chain advantage over existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver given items >= 1 but small utility
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by waste
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in stream, be pickier about wasting space; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.8 + 0.4 * progress;

    // Global state coupling: many open bins with high mean residual -> favor filling
    // existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
        score -= 0.3 * (mean_residual - post_residual as f64).abs();
    } else {
        // New-bin candidate: penalize opening a new bin, more so when open bins
        // are spacious and few fitting alternatives exist.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // new bin at least serves the next big item
        }
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    score += 0.15 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;
    let mean_res = mean_residual / cap;

    // Base: prefer small post-residual, with non-linear tightening as stream progresses
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - norm_post));

    // Polynomial coupling: dead space that is too small to be useful is penalized super-linearly
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * (10.0 - post) * 0.15 } else { 0.0 };
    score += dead;

    // Reward tight fits (post near zero) more strongly late in the stream
    score -= 12.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead: bonus if post_residual accommodates the next item smoothly
    if next > 0.0 && post >= next_item_size {
        let fit_gap = (post - next) / cap;
        score -= 6.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (1.0 - 0.5 * progress);
    } else if next > 0.0 && post > 0.0 {
        // penalize leaving a residual that just barely blocks the next item
        score += 4.0 * (next - norm_post) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer filling bins below mean residual (consolidation), smooth coupling
    score += 5.0 * (norm_post - mean_res) * (1.0 - progress);

    // New-bin candidate: penalize opening new bins mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * (open_bins_count as f64).sqrt() + 8.0 * progress;
        // but allow a new bin if current item is huge and fits would be terrible
        if item > 0.7 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty for very large residual waste relative to item, polynomial in item
    score += 2.0 * norm_post * norm_post * (1.0 - item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it pairs with typical item sizes.
    // Residuals that are multiples of 10 or leave a "fillable" remainder are preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // classify dead-space severity by integer division on capacity fractions
        let tenth = bin_capacity / 10; // 10
        let quarter = bin_capacity / 4; // 25
        if pr <= tenth {
            score += 45.0; // tiny dead space: nearly useless residue
        } else if pr <= quarter {
            score += 15.0;
        } else {
            score -= 10.0; // large residual is reusable
        }
        // harmonic bonus: residual divisible by 10 aligns with common item classes
        if pr % tenth == 0 {
            score -= 12.0;
        }
        // residual that exactly equals a plausible next item class (10..80 grid)
        if next_item_size > 0 && pr >= next_item_size {
            score -= 8.0; // lookahead fits here
        }
        if next_item_size > 0 && next_item_size > pr && next_item_size <= bin_residual {
            score += 6.0; // next item won't fit here, mild penalty
        }
    }

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // new-bin candidate: neutral-ish baseline; penalize opening bins when many exist
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // but if current item creates bad dead space in any open bin, new bin is fine
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    }

    // tightness reward: filling the bin deeply is good
    score -= (bin_residual as f64 - post_residual as f64).max(0.0) * 0.15;

    // late in stream: prefer closing bins, penalize spreading residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item (1..=100, min item 1)
    // are pure waste; penalize hard, especially mid-size unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // gap that only tiny items can fill: partial dead space
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + fit_ratio);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate penalty: opening a fresh bin is expensive when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 1.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a non-linear penalty
    let pr = post_residual as f64;
    score += 0.5 * (pr / 20.0).powi(2);

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        if pr >= ni {
            // next item fits perfectly -> strong reward
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize leaving awkward space
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins that are already below-average filled
    // (i.e. post_residual below mean_residual keeps waste concentrated)
    score += 0.4 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize opening new bins when good fits exist; new-bin candidate
    // (bin_residual == bin_capacity) gets a baseline handicap so it's chosen
    // only when open bins offer poor fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Slight preference for fewer open bins (consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if open bins have large mean residual, prefer
    // consolidating into bins below the mean to balance residuals.
    if bin_residual as f64 > mean_residual {
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when current bin is a bad fit or
    // item is large relative to residual. Discourage opening new bins early.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
        score += 15.0 - 10.0 * fill_ratio - pressure;
        // If item leaves a large unusable gap in any existing bin, new bin is fine.
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        + 30.0 * pr_norm * pr_norm * pr_norm;

    // Tight fit reward, stronger as stream progresses
    let tight = 1.0 - pr_norm;
    score -= 25.0 * tight * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual (fragmentation coupling)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + pr_norm);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by leftover size
        score += 0.1 * pr;
    }

    // Mild pressure to consolidate into fewer bins as open bins grow
    score += 2.0 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress) - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact quarters of capacity
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Reward placements whose post_residual lands on "useful" harmonic classes
    // (residuals that future items can still tile nicely).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 35.0; // near-perfect fill
    } else if post_residual == quarter {
        score -= 25.0; // exact quarter leftover is reusable
    } else if post_residual == half {
        score -= 20.0; // exact half leftover is very reusable
    } else if post_residual % 10 == 0 {
        score -= 8.0;  // multiple-of-10 leftovers match item granularity
    } else {
        // Penalize dead space in awkward classes
        score += 6.0;
        if post_residual < quarter {
            score += 10.0; // small awkward sliver
        }
    }

    // Integer-division threshold on post_residual: avoid leaving tiny unusable gaps
    let dead = post_residual / 10; // how many 10-sized items could still fit
    if dead == 0 && post_residual > 0 {
        score += 15.0; // nothing of minimum granularity fits anymore
    } else {
        score -= dead as f64 * 3.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0) * 0.5;
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        // open new bin only when mean residual across bins is small (bins nearly full)
        score += 40.0 - 55.0 * (1.0 - crowding) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Mild pressure toward tighter bins overall
    score += (bin_residual as f64 - post_residual as f64) * 0.05;
    score -= (cap - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Zero residual is a perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving space usable by the next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap that blocks the next item
    }

    // Open bins pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if existing bins are tight or none fit well
        let pressure = open_bins_count as f64 * 2.0;
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 30.0 + pressure + mean_gap * 0.3;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    } else {
        // prefer bins where item is a large fraction of residual (tight packing)
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
        // last-chance bin: strongly favor using it to avoid opening a bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // slight preference for fuller bins early vs late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
