        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large awkward residuals
            score += 0.05 * post_residual as f64;
        }
    }

    // Compare residual against mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Early stream: be more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial sharpening
    let mut score = pr + 18.0 * norm_pr * norm_pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space penalized super-linearly)
    let coupling = progress * pr * (1.0 - progress) * 0.0 + progress * norm_pr * pr * 0.35;
    score += coupling;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr as u32).saturating_sub(next_item_size) as f64;
        let ng = gap / cap;
        score -= 10.0 * (1.0 - ng.min(1.0)) * (1.0 - ng.min(1.0)) * 0.0;
        score += 6.0 * ng * ng * (1.0 + progress);
        // Reward if lookahead fits exactly-ish
        let fit_gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Smooth penalty for opening new bins when many bins are open late in stream
    let nbias = (open_bins_count as f64).ln() * 2.0;
    if bin_residual == bin_capacity {
        score += nbias * (0.5 + 0.5 * progress) + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps in "usable" classes are worth keeping.
    // Class a gap by which multiples of common item sizes it can still host.
    let mut usable = 0u32;
    for s in [10u32, 20, 25, 30, 40, 50] {
        if post_residual >= s { usable += 1; }
    }
    score -= usable as f64 * 4.0;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size: penalize hard.
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post residual (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here: mildly penalize leaving large awkward gaps
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Progress-scaled tightening: later in the stream, prefer tighter fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * (0.3 + 0.7 * progress);

    // Prefer bins already below mean residual (consolidate slack).
    score += ((mean_residual - bin_residual as f64).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;

    let mean = if mean_residual.is_finite() {
        mean_residual.max(0.0)
    } else {
        0.0
    };

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    let open_pressure = 3.0
        + 2.0 * (open_bins_count as f64 + 1.0).ln()
        + 0.05 * (open_bins_count as f64).sqrt()
        + 1.5 * progress
        + 0.03 * mean;

    let exact_fit_bonus = 10.0 + 0.08 * item;

    if is_new_bin {
        score += open_pressure;

        if post_residual == 0 {
            score -= exact_fit_bonus;
        } else {
            if next > 0.0 {
                if post >= next {
                    score -= 1.5 + 0.04 * next;
                } else if mean < next {
                    score += cap + 0.50 * (next - post);
                } else {
                    score -= 0.5;
                }
            }

            if fitting_bins_count > 0 {
                score += 1.0 + 0.02 * fitting_bins_count as f64;
            }
        }
    } else if post_residual == 0 {
        score -= exact_fit_bonus;
    } else {
        if next > 0.0 {
            if post >= next {
                score -= 2.0 + 0.08 * next;

                if post == next {
                    score -= 2.0;
                }
            } else {
                let deficit = next - post;
                let support_factor = if fitting_bins_count > 1 || mean >= next {
                    0.95
                } else {
                    1.15
                };

                score += (0.75 * cap + 0.80 * deficit + 3.0) * support_factor;
            }
        }

        let small_gap_limit = 0.12 * cap;
        if small_gap_limit > 0.0 && post < small_gap_limit {
            let severity = 1.0 - post / small_gap_limit;
            score += 2.0 + 6.0 * severity * severity;
        }

        let fragment_limit = (0.25 * mean).min(0.15 * cap);
        if fragment_limit > 0.0 && post < fragment_limit {
            score += 0.20 * (fragment_limit - post);
        }

        if fitting_bins_count == 1 {
            score -= 3.0 + 0.04 * item;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // exact chain match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize dead space too small for any plausible item
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: keep it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 100.0; // fresh bin chains perfectly with next item
        } else {
            score += 50.0; // discourage opening new bins by default
        }
    }

    // Late-stream tightness: prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit even the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large post residuals slightly
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize opening new ones
    let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are crowded and mean residual is large
        score += 15.0 + 0.5 * crowding + mean_residual * 0.3;
        // But allow new bin late in stream if mean residual is small (fragmented bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 20.0;
        }
    } else {
        score -= 8.0;
    }

    // Time horizon: early stream, be picky about perfect fits; late stream, fill anything
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Mild preference for bins below mean residual (balancing)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: post residual, with non-linear polynomial shaping over progress.
    let t = progress;
    // Polynomial coupling: quadratic + cubic terms of post_norm modulated by progress.
    let poly = post_norm * post_norm * (1.0 + 2.0 * t) - 0.5 * post_norm * post_norm * post_norm * (1.0 - t);
    let mut score = post * (1.0 + poly);

    // Reward tight fits: subtract when post_residual is small, stronger late in stream.
    let tightness = 1.0 - post_norm;
    score -= tightness * tightness * (20.0 + 40.0 * t);

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits: reward slightly, more if it fills well afterwards
            let after = (post - nxt) / cap;
            score -= (1.0 - after) * (8.0 + 12.0 * t);
        } else {
            // dead space: penalize proportionally to unusable fraction
            let waste = (nxt - post) / nxt.max(1.0);
            score += waste * (15.0 + 25.0 * t);
        }
    } else {
        // last item: strongly reward using existing bins
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * t;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize mildly early,
    // reward late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 - 15.0 * t + 10.0 * fragmentation * (1.0 - t);
    }

    // Mild penalty for too many open bins early on.
    score += (open_bins_count as f64).sqrt() * (2.0 * (1.0 - t));

    // Encourage bins with residual near mean (consolidation).
    let dev = (post - mean_residual).abs() / cap;
    score += dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on a
    // "nice" residue class (multiples of 10, small dead space) are preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is king
    } else if pr < 10 {
        score += 45.0; // tiny unusable dead space is terrible
    } else {
        // class bonus: multiples of 10 keep future medium items placeable
        let class = pr % 10;
        if class == 0 {
            score -= 18.0;
        } else if class <= 3 {
            score += 12.0; // near-dead residue
        } else {
            score += class as f64 * 0.8;
        }
    }

    // Lookahead: reward bins whose post residual can host the next item exactly
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 10 {
            score += 20.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize more if this bin becomes last-chance
        score += 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large relative to capacity or no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // penalize new bins early / for small items; reward for big items late
        score += 55.0 - 30.0 * fill_ratio - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Prefer tighter bins overall: distance from mean residual
    let tightness = (bin_residual as f64 - mean_residual).abs();
    score -= tightness * 0.15;

    // Slight preference to fill bins that are already quite full
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Harmonic threshold on next_item_size classes (integer division buckets)
    if next_item_size >= 50 {
        score += 3.0; // big next item: keep large residuals around
    } else if next_item_size >= 20 && next_item_size % 2 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // Any leftover smaller than the minimum plausible item creates dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
        // Reward exact fits and near-exact fits strongly.
        if post_residual == 0 {
            score -= 120.0;
        }
    }

    // Coupling: dead space penalty scales with how many bins are already open
    // (more open bins -> waste hurts more, prefer tight packing).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (small miss), slight penalty for tempting gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mild penalty when this bin's residual is far below the mean (already tight bin),
    // encouraging spreading across bins when residuals are comparable.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 20.0 {
        score += residual_gap * 0.3;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would create bad dead space. Give the empty bin a moderate default score.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score -= 40.0 / (post_residual as f64 + 1.0);
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next fits, penalize by wasted space after that hypothetical placement
            let after = post_residual - next_item_size;
            score -= 20.0 / (after as f64 + 1.0);
        } else {
            // next item won't fit here; penalize leaving awkward residual near next size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
    }

    // Compare residual to mean residual across open bins: prefer filling below-average
    // residual bins (tightening the distribution), avoid creating outliers.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it costly unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a fresh bin
        score += 25.0;
        // if many bins fit the item, discourage opening a new one
        score += 5.0 * fitting_bins_count as f64;
        // if the next item is large, a fresh bin may be valuable
        if next_item_size > 0 && next_item_size > (bin_capacity as f64 * 0.6) as u32 {
            score -= 20.0;
        }
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with less residual before placement (best-fit tendency) mildly.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold even the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is wasted relative to the next item's demand.
        score += 0.3 * post_residual as f64;
    }

    // Perfect-fill chase: reward when item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate bias: penalize the empty-bin call unless the item
    // is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 30.0 * size_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Late in the stream, opening new bins is more costly on average.
        score += 10.0 * progress;
    }

    // Mild exploration term: prefer bins whose residual is close to mean residual
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time-horizon modulation: early on, be greedy for tight fits; later,
    // weight balance across bins more.
    score -= 15.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * (norm_pr * norm_pr) * (1.0 + t) - 8.0 * norm_pr * t * t;

    // Penalize large dead space quadratically, more so early in the stream
    score += 20.0 * norm_pr * norm_pr * (1.0 - t) * (1.0 - t);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 15.0 * (1.0 - (norm_pr * std::f64::consts::PI / 2.0).cos()) * (1.0 - t);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Encourage spreading load when many bins are open and mean residual is high
    let open_f = open_bins_count as f64;
    score += 0.5 * (mean_residual - pr) / (open_f + 1.0);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).min(1.0)) * (0.5 + t);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Slight preference for new empty bin when item is large relative to capacity
    if bin_residual == bin_capacity {
        score -= 3.0 * (item_size as f64 / cap) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post-residual: dead space classes (integer division thresholds)
    // Residuals <= 10 are essentially dead; 11..=25 poor; 26..=50 half-class; >50 useful.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual <= 10 {
        score += 25.0; // dead space class: very undesirable
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 50 {
        score -= 2.0;
    } else {
        score -= 8.0; // large residual still reusable
    }

    // Harmonic coupling with next item (k=2 lookahead)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how snugly
            let snug = (next_item_size as f64) / cap;
            score -= 20.0 + 15.0 * snug;
        } else {
            // next item won't fit: penalize leaving mid-range residuals
            score += 6.0;
        }
        // modulo-style class match: residual and next item in same harmonic class
        let class_r = post_residual / 25;
        let class_n = next_item_size / 25;
        if class_r == class_n && post_residual >= next_item_size {
            score -= 7.0;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 10.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when fits are bad
    if bin_residual == bin_capacity {
        // opening a new bin: score = wasted potential of not filling existing bins
        score = 0.35 * cap + 0.25 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if open_bins_count > 3 {
            score += 0.5 * open_bins_count as f64;
        }
    }

    // mild tie-break: prefer bins with residual close to item (tight fit)
    score += 0.05 * ((bin_residual - item_size) as f64 - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio;

    // Open bins pressure: penalize spreading across many bins when residuals are large.
    score += 1.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space for the known next item: penalize.
        score += 6.0;
    }

    // Mild bonus for using existing bins early vs opening new ones late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, slightly penalized so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post residual exactly matches next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 40.0 * (1.0 - (diff as f64 / bin_capacity as f64).min(1.0)).powi(3);
        // Bonus if the chained item fits exactly, leaving a fresh small residual.
        if diff == 0 {
            score -= 25.0;
        }
        // Penalize dead space that neither the next item nor a small item can use.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Reward bins whose residual is below average (already "tight"), penalize loose bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when other bins fit (new-bin candidate gets residual == capacity).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + 5.0 * open_bins_count as f64;
    }
    // Slight preference for a fresh bin when few bins fit poorly (post_residual tiny).
    if bin_residual == bin_capacity {
        score -= 10.0;
    }

    // Early stream: be picky about tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver under min item size
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slightly penalize leaving large gaps
            score += 2.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Compare best possible residual among open bins via mean residual as proxy.
        let open_fit_quality = mean_residual - item_size as f64;
        if open_fit_quality >= 0.0 && mean_residual < 0.35 * bin_capacity as f64 {
            // open bins are nearly empty of usable space; opening new bin is fine
            score -= 5.0;
        } else {
            // prefer existing bins; penalize new bin
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Time horizon: late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for scattering across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress;
    score += 40.0 * coupling;
    // Penalize large dead space late in the stream
    score += 25.0 * norm_pr * norm_pr * progress * progress;
    // Reward tight fits: subtract when post_residual is small
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }
    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }
    // Mean residual deviation penalty
    score += 0.3 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect packing
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        // Large dead space penalty, modulated by residual class.
        score += 8.0 * (frac - 0.3);
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonic"
    // with common item sizes (multiples of 10, 5) are more reusable.
    let mod10 = post_residual % 10;
    let mod5 = post_residual % 5;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0; // awkward residual less reusable
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills, or close.
            let nm = post_residual - next_item_size;
            if nm == 0 {
                score -= 25.0;
            } else if nm <= 10 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; penalize more if this bin was
            // our "last chance" candidate.
            score += 4.0;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or all open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 18.0;
        // Large items pack better in a fresh bin.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no other bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early in the stream, fresh bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Mean residual context: if mean residual is high, bins are loose;
    // prefer tightening this one (low post_residual already favored).
    if mean_residual > 40.0 && post_residual < 20 {
        score -= 4.0;
    }

    // Integer-division threshold: bins whose residual is in a "good class"
    // after placement (residual / 10 small) get a bonus.
    let div_class = post_residual / 10;
    score -= match div_class {
        0 => 5.0,
        1 => 3.0,
        2 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving residuals that can accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.08 * next_item_size as f64;
        } else {
            // Dead space relative to the next item's needs.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward: fraction of the bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Penalize bins whose residual is far below the mean (fragmented bins).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 15.0;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
        // If the current item nearly fills a fresh bin, opening is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 20.0;
        }
        // If next item is large and no bin fits it, a fresh bin helps.
        if next_item_size > 0 && next_item_size > bin_capacity.saturating_sub(item_size) {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item => chain of perfect fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits after this one; mild bonus scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + slack);
        } else {
            // next item would NOT fit here afterwards: penalize dead space
            // especially if residual is small (unusable for typical items).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0;
            } else {
                score += dead * 0.3;
            }
        }
    }

    // Penalize leaving residuals that are small but nonzero (hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tightness relative to mean residual: tighter-than-average fits are good.
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the
    // current fit is poor. Empty-bin residual == capacity gets a baseline
    // penalty so it wins only via its naturally high post_residual.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.1;

    // Exact or near-exact fills get a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement;
    // if next item would NOT fit but would fit the current residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 12.0;
        }
        // If next item is large, prefer conserving big-residual bins.
        if next_item_size > 50 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Prefer filling bins with larger residual first when many bins are open
    // (reduces bin fragmentation), but keep tight-fit priority dominant.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early in the stream: be more willing to open new bins (keep flexibility),
    // late in the stream: squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize less early, more late.
        score += 10.0 + 30.0 * progress;
        // If no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If the best alternative leaves large dead space, new bin is attractive.
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 5.0;
        }
    } else {
        // Using existing bins is favored more as stream progresses.
        score -= 5.0 * progress;
    }

    // Many open bins: discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    } else {
        score -= 0.1 * open_bins_count as f64;
    }

    // Mild penalty for very loose fits regardless of everything else.
    if post_residual as f64 > 0.6 * bin_capacity as f64 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let t = progress;
    score += 12.0 * pr_norm * pr_norm * (t - 0.5) * (t - 0.5) * 4.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap) * t;
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + t);
    }

    // Mild penalty for spreading across many bins vs mean residual
    let mr = mean_residual / cap;
    score += 6.0 * (pr_norm - mr) * (pr_norm - mr) * (1.0 - t);

    // New-bin candidate: prefer it only when it keeps more usable space
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let class = pr % 10;
    // Penalize residuals in "dead" classes (small, hard-to-fill remainders)
    let dead_penalty = match class {
        1..=9 => 6.0,
        0 => -4.0, // perfectly divisible residual is reusable
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: residual halves of capacity
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 3.0; // still roomy, good bin
    } else if post_residual < bin_capacity / 10 {
        score += 5.0; // nearly dead space
    }

    // Coupling with next item lookahead: reward residual that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + (next_item_size as f64) * 0.05;
        } else {
            score += 2.0; // next item won't fit here
        }
        // harmonic match: residual mod next_item_size near zero => tight chain
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 3.0;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 5.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = mean_residual < item_size as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 2.0 + progress * 2.0;
        } else {
            score += 10.0; // discourage opening new bins when fits exist
        }
    }

    // Tightness reward relative to capacity fraction
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 4.0;

    // Mean residual divergence: penalize bins far from fleet mean
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize post_residual that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bin that can also fit the next item (chain potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open bins pressure: discourage opening new bins when stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 60.0 * (1.0 - progress);
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild penalty scaling with number of open bins for spreading items.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (consolidate larger gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio; // reward filling a large fraction of the bin

    // 2-step lookahead: reward post_residual that exactly/nearly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can follow: reward closeness of match
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
            // perfect chain (post_residual == next_item_size) is excellent
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally to wasted lookahead
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // last item: pure tightness matters
        score -= 20.0 * fit_ratio;
    }

    // Compare against mean residual: placing in a bin whose residual is below
    // average concentrates waste and preserves large residuals elsewhere.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: empty bin gets a mild handicap so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // handicap grows with how well other bins could have taken the item
        if fitting_bins_count > 0 {
            score += 18.0;
        } else {
            score += 2.0;
        }
        // opening a new bin is fine early when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Penalize creating tiny unusable dead space (1..=5 units) that likely nothing fits.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: superlinear waste for large leftover space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if next_item_size > post_residual {
            // Penalize leaving a residual too small for the next item (fragmentation).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
            }
            let _ = gap;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // in existing bins is poor (large post_residual) or stream is early.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // Early in the stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage spreading items thin.
        score += 1.5 * open_bins_count as f64;
        // If the item nearly fills the new bin, opening is actually good (tight packing).
        score -= 0.3 * item_size as f64;
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // in the direction of better consolidation (use tighter-than-average bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for fuller bins regardless.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let isn = item_size as f64 / cap;
    let nisn = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping by stream progress
    let mut score = pr * (1.0 + 0.5 * prn * prn) * (1.0 + 0.6 * progress);

    // Reward tight fits: subtract for small post_residual, coupled non-linearly with progress
    score -= 30.0 * (1.0 - prn).powi(3) * (1.0 + progress);

    // Penalize large dead space quadratically
    score += 20.0 * prn * prn * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 && nisn <= prn && nisn > 0.0 {
        let fit_quality = (prn - nisn) / prn.max(1e-9);
        score -= 15.0 * (1.0 - fit_quality * fit_quality) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 8.0 * nisn * (prn - nisn).abs() * (1.0 - progress);
    }

    // Last-chance bin: strong non-linear reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * (1.0 - prn).powi(2));
    }

    // Mean residual interaction: prefer bins deviating favorably from mean
    let mrd = (pr - mean_residual) / cap;
    score += 10.0 * mrd * mrd * (0.3 + 0.7 * progress);

    // Open bins pressure: mild penalty when many bins open late in stream
    score += 0.3 * open_bins_count as f64 * progress * (1.0 - prn);

    // Smooth item-size interaction: larger items prefer larger residuals
    score -= 5.0 * isn * prn * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: how well post_residual aligns with reusable size classes (multiples of 10)
    let post_class = post_residual % 10;
    let post_div = post_residual / 10;
    if post_class == 0 && post_residual > 0 {
        score -= 25.0; // exact multiple of 10: highly reusable slot
    } else {
        score += post_class as f64 * 1.5; // penalize off-class dead space
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // prefer leaving room for next item with minimal slack
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack % 10) as f64 * 0.8;
        } else {
            // next item cannot fit here: penalize proportionally to wasted lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: closing bins tightly is free
        score -= 10.0;
    }

    // Integer-division threshold on post_residual: tiny unusable slivers are dead space
    if post_div == 0 && post_residual > 0 {
        score += 40.0; // residual < 10 is nearly useless
    } else if post_div >= 5 {
        score -= 10.0; // residual >= 50 still very usable
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only open a new bin when current bin would leave a bad class
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if no open bin fits, opening is necessary
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // opening a new bin is attractive if the item would leave a clean class in it
        if item_size % 10 == 0 {
            score -= 35.0;
        }
    }

    // Stream progression: late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) much more than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if post-residual is too small for the next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Pressure from number of open bins: favor filling existing bins when many are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score -= pressure * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fits of the NEXT item into
    // the post-residual (aggressive 2-step lookahead matching).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect 2-step chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: minimize waste as much as possible.
        score -= 50.0;
    }

    // Reward bins that are already relatively full (low residual vs mean).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Penalize creating tiny dead space that nothing (>=1) can use later,
    // but only mildly since lookahead may exploit it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly exhausted or the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (post_residual as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward when the lookahead item exactly fills the remaining space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Mild reward if lookahead item still fits after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // Penalize leaving a dead sliver that almost nothing can use.
    if post > 0.0 && post < 10.0 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness: reward using a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open or the mean residual is large (existing space available).
    if bin_residual == bin_capacity {
        score += 18.0;
        score += 2.0 * open_bins_count as f64;
        score += 0.4 * mean_residual;
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Reward spreading into bins with residual close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin consumed by this placement
    let fill = item_size as f64 / cap;
    let tight = 1.0 - (post_residual as f64 / cap);
    // Smooth non-linear reward for tight fits (squared coupling)
    score -= 30.0 * tight * tight * (0.5 + 0.5 * progress);

    // Penalize post_residual relative to mean residual: creating dead space worse than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Non-linear coupling of post_residual with progress: late in stream, small leftovers matter more
    let pr_norm = post_residual as f64 / cap;
    score += 20.0 * pr_norm * pr_norm * (1.0 - progress) * progress * 4.0;

    // Penalize large residuals that cannot fit the next item (dead space creation)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx && post_residual > 0 {
            score += 15.0 * (nx - post_residual as f64) / cap;
        } else if post_residual as f64 >= nx {
            // reward bins that remain usable for the lookahead item
            score -= 8.0 * (1.0 - (post_residual as f64 - nx) / cap).abs().min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Smoothly discourage opening new bins as open bin count grows (non-linear saturation)
    let ob = open_bins_count as f64;
    score += 10.0 * (ob / (ob + 5.0)) * (1.0 - fill);

    // New-bin candidate: penalize unless it produces a very good immediate fill
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * (1.0 - fill) - 25.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse quartile bands (integer division thresholds).
    let post_class: u32 = post_residual / (bin_capacity / 4); // 0..=4
    let next_class: u32 = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4) };

    // Reward when the next item's class matches the leftover class
    // (perfect harmonic pairing => likely to fill the residual).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_class as i32 - next_class as i32).abs();
        score -= (4 - diff.min(4)) as f64 * 6.0;
        // Exact modulo harmony: post_residual divisible by next_item_size
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize small unusable remainders (dead space) with a threshold curve.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers via squared deviation scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = bin_residual as f64 - mean_residual;
    score += dev * dev * 0.02 * (0.5 + progress);

    // New-bin candidate handling: only attractive when existing bins are tight
    // or the fit is terrible (large dead space).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0).min(1.0);
        let bad_fit = (post_residual as f64) / cap;
        // Fresh bin baseline; subtract when open bins are congested.
        score = 100.0 - pressure * 60.0 - bad_fit * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Slight preference for tighter bins early on.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (<=10)
    // are pure waste, so penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 10.0;
    } else {
        // Gaps below 20 are rarely usable; soft penalty.
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.0;
        }
        // Reward near-perfect fits.
        if post_residual <= 5 {
            score -= 30.0;
        }
    }

    // If the next item fits exactly in the post-residual, reward heavily
    // (this bin becomes perfectly packed by the lookahead pair).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0 - slack * 2.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // already-open bins with large residuals; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (i.e., when post_residual here
    // is large and this bin is empty).
    if bin_residual == bin_capacity {
        // Baseline competitiveness for a fresh bin.
        score = (bin_capacity - item_size) as f64;
        // Prefer opening a new bin when open bins are congested.
        score -= open_bins_count as f64 * 1.0;
        // Prefer new bin if mean residual across open bins is small
        // (existing bins are nearly full anyway).
        score -= mean_residual * 0.3;
        // Last item: no need for a new bin ever.
        if next_item_size == 0 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can accommodate the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.35 * slack;
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable remainder.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.9 * dead;
    }

    // Penalize very small post_residuals that waste capacity (unless perfect fit handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to spread items (favor new bins less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 10.0;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.15 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly useful for the next item.
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance pressure: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 0.05 * fitting_bins_count as f64;
    }

    // Global state: when mean residual is high, avoid wasting big bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize poor fits less later; reward exploration early).
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score += t * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer consolidating into few bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 0.1 * mean_residual };
        score += pressure - (1.0 - t) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear penalty on residual dead space (quadratic coupling with progress)
    score += 12.0 * norm_post * norm_post * (0.4 + 0.6 * progress);

    // Reward tight fits: cubic decay of penalty as post_residual shrinks
    score -= 30.0 * (1.0 - norm_post).powi(3);

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt as f64 {
            score += 8.0 * (nxt - post) / cap;
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are open with slack
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 10.0 + 5.0 * (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0)));
        score += 20.0 * norm_item * (1.0 - progress);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    score += 3.0 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod small moduli.
    // Residues that are "harmonic" with common item sizes (multiples of 10/20)
    // are more reusable; odd/prime-ish residues create dead space.
    let r = post_residual;
    let cap = bin_capacity as f64;

    // Reward post-residuals that are exactly representable as sums of typical items
    if r % 10 == 0 {
        score -= 12.0;
    }
    if r % 20 == 0 {
        score -= 8.0;
    }
    if r % 5 == 0 && r % 10 != 0 {
        score -= 3.0;
    }
    // Penalize odd / coprime residues (hard to fill)
    if r % 2 == 1 {
        score += 6.0;
    }
    if r > 0 && r % 3 != 0 && r % 7 == 0 {
        score += 2.0;
    }

    // Capacity fraction thresholds: integer-division classes of post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if r < quarter {
        // tiny dead space: strong penalty unless bin is nearly full anyway
        score += 10.0 * (1.0 - (r as f64) / (quarter as f64));
    } else if r < half {
        score += 2.0;
    } else if r <= half + quarter {
        // sweet spot: leaves room for a medium item
        score -= 6.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // harmonic match with lookahead: reward, scaled by residue alignment
            let align = if (r % 10) == (next_item_size % 10) { 8.0 } else { 4.0 };
            score -= align + 0.05 * (next_item_size as f64);
        } else {
            // next item won't fit here; penalize wasted capacity proportionally
            score += 0.08 * (r as f64) * (next_item_size as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer tight bins (low post_residual)
    if open_bins_count > 4 {
        score += 0.03 * (open_bins_count as f64) * (r as f64 / cap);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing)
    score += 0.10 * (mean_residual - r as f64);

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: mild default preference unless it beats a bad fit
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * post_residual as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Opening a new bin: penalize more when many bins already open.
        score += 5.0 + 1.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) for large items.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step fit: post_residual exactly matches next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (chained fit) -> reward proportional to tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item almost fits but not quite: dead space penalty
    if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 10 {
        score += 25.0;
    }

    // Reward tight fills now (small post residual relative to capacity)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize bins far below the mean residual (fragmenting the stream)
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: discourage opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Early stream: be slightly conservative with open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fill is ideal: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Tight fit reward proportional to how full the bin becomes.
        let fill_ratio = (bin_residual - post_residual) as f64 / cap;
        score -= 20.0 * fill_ratio * fill_ratio;

        // Dead space that no plausible item can use is wasted.
        if post_residual < 10 {
            score += 12.0 * (10.0 - post_residual as f64);
        }

        // Lookahead (k=2): if the next item also fits here, chain placements.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = 10.0 * (1.0 - 0.5 * progress);
            score -= chain;
        } else if next_item_size > 0 && post_residual > 0 {
            // This bin becomes dead space for the next item.
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 0.0 {
        let consolidation = ((mean_residual - post_residual as f64).abs() / cap) * 8.0;
        score += consolidation;
    }

    // New-bin candidate handling: opening a fresh bin is good for large items
    // (they pair well with future small items) but wasteful for small items
    // when other bins fit.
    if is_new_bin {
        let size_ratio = item_size as f64 / cap;
        if size_ratio > 0.5 {
            score -= 18.0 * size_ratio;
        } else {
            score += 10.0 * (1.0 - size_ratio);
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        if progress > 0.7 && item_size < 40 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial coupling to progress.
    // Later in the stream, small residuals become more valuable (less chance to fill them).
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize dead space non-linearly: residuals that nothing can use are quadratic bad.
    score += 8.0 * norm_pr * norm_pr * (1.0 + progress);

    // Lookahead coupling: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (1.0 + 0.5 * progress);
        } else {
            // Residual can't host next item: penalize proportionally to overflow.
            let over = (nxt - pr) / cap;
            score += 4.0 * over * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is attractive early (flexibility)
    // but expensive late; also unattractive if plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 2.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 3.0; // fresh bin preserves lookahead flexibility
        }
    }

    // Mild penalty for deviating from mean residual: keeps bin pool balanced.
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which eighth of capacity remains
    let class = (post_residual * 8) / bin_capacity.max(1); // 0..=7
    // Dead-space penalty grows superlinearly for small unusable residuals
    let dead_threshold = bin_capacity / 10; // residuals < 10% are near-dead
    if post_residual < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 100.0; // perfect fit is best
    }

    // Lookahead compatibility: does next_item_size fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability bonus scaled by how snugly the next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 25.0 + 30.0 * snug;
            // Harmonic match: next item lands in the same residual class
            let next_class = ((post_residual - next_item_size) * 8) / bin_capacity.max(1);
            if next_class == class {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we don't place current item here:
            // mild penalty for stealing that opportunity
            score += 8.0;
        } else {
            // Next item won't fit either way; prefer conserving residual space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fills
        score += 3.0 * (fitting_bins_count.min(8) as f64);
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow opening fresh bins less reluctantly;
    // late in the stream, squeeze existing bins harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / cap_f);

    // New-bin candidate (empty bin): penalize unless residual would be huge waste
    if bin_residual == bin_capacity {
        score += 35.0 - 0.1 * item_size as f64;
        // Opening a new bin is attractive when few bins are open and item is large
        score -= (open_bins_count.min(20) as f64) * 1.2;
    }

    // Modulo harmonic classes on post_residual: reward residuals that are
    // multiples of common item sizes (likely reusable chunks)
    let pr = post_residual;
    if pr >= 20 && (pr % 20 == 0 || pr % 25 == 0 || pr % 30 == 0) {
        score -= 6.0;
    }
    // Odd, awkward residuals are penalized slightly
    if pr % 2 == 1 && pr < bin_capacity / 4 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small for the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward exact fit.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward gaps that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.1;

    // Slight late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits here afterwards: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 120.0 * tightness;
        } else {
            // next item won't fit after placement: penalize wasting large residuals
            score += 40.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.5 * dev;
    } else {
        score -= 0.3 * (-dev);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize very small unusable residuals unless it's a perfect fit
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Early in stream: encourage packing into open bins rather than spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize unless open bins are congested
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        score += 150.0 * (1.0 - congestion);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 500.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that nothing else can use: items are >= 1,
    // so residuals smaller than the smallest plausible item are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow here; slight penalty for blocking space.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state coupling: prefer bins whose residual is close to mean residual
    // (keeps bin pool balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in stream, consolidate to avoid leftover fragments.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * fit_ratio;

    // When many bins are open, favor filling existing ones rather than opening more.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline; open a new bin only when no
    // open bin offers a decent fit (their scores must be higher than this).
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 8.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 6.0 * norm_pr * (p2 + p3);
    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 + p3);
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 5.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - nx) / cap;
        }
    }
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);
    // Nudge toward bins below mean residual (consolidation)
    score += 2.0 * (mean_residual - bin_residual as f64) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable.
    let pr = post_residual;
    if pr > 0 {
        let cls: u32 = match pr {
            0 => 0,
            x if x <= 5 => 4,
            x if x <= 10 => 3,
            x if x <= 20 => 2,
            x if x <= 40 => 1,
            _ => 0,
        };
        score += cls as f64 * 3.0;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Integer-division thresholds: residual divisible by common item sizes
    // (10/20/25/50) is "harmonically reusable".
    if pr > 0 {
        let harmonious = (pr % 10 == 0) as f64 * 6.0
            + (pr % 20 == 0) as f64 * 4.0
            + (pr % 25 == 0) as f64 * 4.0
            + (pr % 50 == 0) as f64 * 3.0;
        score -= harmonious;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // next item leaves a residual in a good class?
            let nr = pr - next_item_size;
            if nr <= 10 {
                score += 5.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize tight fills slightly
            score += 4.0;
        }
    }

    // Last-chance bin: avoid wasting it on small items if it's the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += 10.0; // using last bin for a small item wastes capacity
        } else {
            score -= 5.0; // good use of the last chance
        }
    }

    // New-bin candidate: make it attractive only when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let tight_fit_penalty = if post_residual > 0 && post_residual < 10 { 15.0 } else { 0.0 };
        let base = cap * 0.55 + tight_fit_penalty;
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + progress * 10.0 - (open_bins_count as f64).sqrt() * 2.0;
        // If mean residual is large, opening new bins is less attractive.
        score += mean_residual * 0.3;
    }

    // Mild pressure to prefer fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it can't fit even the smallest plausible item (<= 1),
    // and increasingly bad in the 1..=15 range (hard to fill later).
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual <= 5 {
        // Tiny dead gap: worst outcome, penalize hard.
        score += 400.0 - 50.0 * pr;
    } else if post_residual <= 15 {
        // Small gap: risky, moderate penalty decaying with gap size.
        score += 120.0 - 6.0 * pr;
    } else if post_residual >= item_size.min(next_item_size.max(1)) {
        // Gap large enough to plausibly host the next item: mild reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Reward good tightness relative to bin fill.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate more when open_bins_count is low relative to progress).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more strongly early and when few bins open.
        score += 80.0 + 120.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Slight preference toward bins with below-mean residual (keep spread even),
    // but only mildly so tight fits still dominate.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Lookahead: if the next item exactly matches post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> extremely good
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If next item also fits after this placement, reward tight coupling
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    }

    // Penalize dead space below the smallest plausible item (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the current mean residual (well-packed bins)
    if bin_residual < bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.25;
    }

    // New empty bin candidate: penalize mildly so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is large, a fresh bin gives flexibility
        if next_item_size > 50 {
            score -= 25.0;
        }
    }

    // Late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best, but tiny slivers (1..=5) are dead space.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score += 15.0; // unusable sliver
    } else {
        // smooth decay of reward as post-residual grows
        score -= 25.0 * (-pr / 25.0);
    }

    // Penalize large waste relative to bin capacity
    score += 0.35 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 100.0;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement;
    // if next item is large and would be stranded, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 18.0 * (n / 100.0);
        } else {
            score += 8.0 * (1.0 - (bin_residual as f64 - n).max(0.0) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin when a feasible one exists).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // More open bins fitting the item => mild penalty for spreading across many bins
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Time horizon: early in the stream, be conservative (keep residuals flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - pr / bin_capacity as f64);
    score += 12.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer bins that reduce variance
    // (i.e., post_residual close to mean_residual is neutral; far from it is penalized).
    let dev = (pr - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the item fits badly in all open bins or stream is early
    // and item is large (leaves useful space for future items).
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 10.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is necessary
        }
        if next_item_size > 0 && (next_item_size as f64) <= fit_quality * bin_capacity as f64 {
            score -= 15.0 * fit_quality; // large item leaves room for next item
        }
        score -= 10.0 * (1.0 - progress) * fit_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild preference for tight fits (small post_residual).
    // Late stream: stronger penalty on wasted residual, tighter packing valued.
    let tightness = 1.0 - fit_frac; // 1 = perfect fit
    let coupling = tightness * (1.0 + progress * progress * 2.5 + progress * 0.8);

    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward near-perfect fits with smooth polynomial term.
    score -= (1.0 - fit_frac).powi(3) * (12.0 + 18.0 * progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (nx - pr).max(0.0) / cap;
        score += unusable * unusable * (20.0 + 25.0 * progress);
        // Reward leaving exactly room for the next item (smooth bump).
        let gap = (pr - nx).abs() / cap;
        score -= (1.0 - gap.min(1.0)).powi(2) * 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Slight penalty when many bins are open and this bin is far below mean residual.
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 4.0 * (1.0 - progress);

    // Smooth new-bin bias: prefer existing bins slightly, more so late in stream.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + coupling * 0.5;
    }

    score + coupling * 2.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // item sizes are "usable" classes; odd/dead residues are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Dead-space penalty grows superlinearly for small unusable residuals.
    if post_residual > 0 {
        // Harmonic class: is post_residual divisible by common small sizes?
        let mut usable = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                usable += 1.0;
            }
        }
        score -= 6.0 * usable;

        // Integer-division threshold: residual in (0,10) is nearly dead.
        if post_residual < 10 {
            score += 25.0 * (10.0 - post) / 10.0;
        } else if post_residual < 20 {
            score += 8.0 * (20.0 - post) / 10.0;
        }

        // Modulo coupling with next item: if next item fits exactly into
        // post_residual, strongly reward (perfect chaining).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 40.0;
            } else if next_item_size < post_residual {
                let next_post = post_residual - next_item_size;
                // penalize based on the class of the next-next residual
                score += (next_post % 10) as f64 * 0.4;
                if next_post < 10 && next_post > 0 {
                    score += 6.0;
                }
            } else {
                // next item cannot use this residual: mild penalty scaled
                // by how much slack would be wasted
                score += 2.0;
            }
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.05 * post;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when fits are poor and stream is early/mid.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score = 55.0;
        // More attractive when current open bins are fragmented.
        score -= 30.0 * (mean_residual / cap - 0.5).max(0.0);
        // Early in stream, opening fresh bins is cheaper.
        score -= 15.0 * (1.0 - progress);
        // If next item is large and no bin likely fits it, new bin helps.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0;
        }
        // Many open bins: discourage proliferation.
        score += (open_bins_count as f64).sqrt() * 4.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below
    // average (tighter bins) to consolidate fragmentation.
    score += 0.3 * (mean_residual - post).max(-30.0).min(30.0) * 0.1;

    // Harmonic fraction penalty: fractional residual near awkward values
    // (e.g. ~half-full but not classically divisible) gets a nudge.
    let hf = (post_residual % 7) as f64;
    score += 0.2 * hf;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically >= 10), so penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Medium gaps (11..=19) are risky: only very small items can use them.
    if post_residual >= 11 && post_residual <= 19 {
        score += 25.0;
    }

    // Reward exact fits and near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with mean residual: a bin whose post_residual is far below the
    // mean residual is a "tight" placement; reward it, since it concentrates
    // fill into already-low bins and leaves larger residual bins flexible.
    let post_f = post_residual as f64;
    score -= 0.8 * (mean_residual - post_f).max(0.0);

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins rather than spreading; when few bins are open, opening a
    // new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when few bins fit the item,
        // but penalized under high open-bin pressure.
        score = post_f + 15.0 + pressure * 8.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // last chance: opening a new bin is fine
        }
        if post_f <= 10.0 {
            score += 40.0; // never open a bin just to make dead space
        }
    } else {
        // Existing bin: reward using it, more so under open-bin pressure.
        score -= pressure * 5.0;
        // Last-chance bin: strongly prefer filling it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, this
    // placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Late in the stream, avoid creating any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_f * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect fit for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item still fits in the bin after this placement.
        let diff = post_residual as i64 - next_item_size as i64;
        if diff >= 0 {
            // Reward leaving room for the next item, tighter is better.
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportional to waste.
            score += 0.35 * (-diff) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals (< 10, minimum item size),
    // scaled by how small they are.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    }

    // Prefer bins with residual close to the mean (balanced packing),
    // penalize extreme deviations.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // New-bin candidate handling: an empty bin gets a baseline score that
    // beats very poor fits but loses to good fits in open bins.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // If the item fits poorly in every open bin, opening a new bin is fine.
        if post_residual == 0 {
            score -= 40.0; // exact fit in a fresh bin
        }
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small residuals (dead space) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    } else if post_residual < 20 {
        score += 6.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / 10.0;
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = avg_tightness * (1.0 + progress) + openness * 0.15;
        // Penalize new bin by default; relax when bins are nearly full.
        score += 20.0 - 25.0 * pressure.min(1.2);
        // Large items benefit from a fresh bin more than small ones.
        score -= (item_size as f64 / 100.0) * 8.0;
    } else {
        // Mild penalty for spreading across many bins when residuals are healthy.
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 1.5 * (open_bins_count as f64 / 20.0) * mean_tightness;
    }

    // Progress-scaled exploitation: late in the stream, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste measure, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of residual with stream progress:
    // late in stream, penalize residual more (want tight packs)
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Non-linear interaction: residual vs mean residual of open bins
    let mean_term = (mean_residual - pr) / cap;
    score += 3.0 * mean_term * mean_term * pr;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        let tightness = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= fits * (8.0 + 6.0 * tightness * tightness) * (0.5 + progress);
    } else {
        // last item: minimize waste directly
        score += 2.0 * pr;
    }

    // Slight preference against opening new bins when many open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead zones"
    // where leftover space is unlikely to fit future items (items >= 10 classically,
    // but interface allows 1..100, so weight small residues more softly).
    let pr = post_residual as u64;
    let residue = pr % 10;
    let residue_penalty = if pr == 0 {
        -30.0 // perfect fit: heavily reward
    } else if residue == 0 {
        -8.0 // leftover in a "round" class: reusable by many item sizes
    } else if residue >= 7 {
        2.0 + (residue as f64 - 6.0) * 1.5 // awkward large-in-class leftover
    } else {
        (10 - residue) as f64 * 0.4 // small dead space, mild penalty
    };
    score += residue_penalty;

    // Integer-division thresholds: can a plausible next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - snug * 0.15;
        } else {
            // lookahead cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins: tie-break by fraction of capacity consumed
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // Coupling with mean residual: bins far below mean residual are "wasted capacity"
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Early in the stream, allow new bins more freely; late in the stream,
    // consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        let mut nb = 18.0 + progress * 22.0;
        // If many bins are open already, discourage yet another one.
        nb += open_bins_count as f64 * 1.2;
        // If lookahead is large and this bin is empty, a fresh bin is attractive.
        if next_item_size > item_size {
            nb -= 5.0;
        }
        score = score.max(nb); // new-bin score floor: never look better than tight fits
    }

    // Modulo coupling between item_size and capacity thirds: harmonically aligned
    // placements (item divides capacity nicely) are preferred.
    let thirds = bin_capacity / 3;
    if item_size == thirds || item_size == thirds * 2 || bin_capacity % item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: lower score when the bin is nearly filled.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100, min item unknown, use 10 as classic floor but guard with lookahead).
    let min_next = if next_item_size > 0 { next_item_size.min(80).max(1) } else { 10 };
    if post_residual > 0 && (post_residual as f64) < (min_next as f64) * 0.9 {
        score += 25.0; // gap likely unusable by the next item
    }

    // Reward leaving room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones;
    // when few are open, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discount early in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 20.0 * pressure - 15.0 * progress;
    } else {
        // Existing bin: slight reward scaled by how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier spread evenly? no —
    // prefer bins ABOVE mean to consolidate space into fewer bins).
    if bin_residual == bin_capacity {
        score += 5.0 * pressure;
    } else if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack left over.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
    }
    // Next item does NOT fit in leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual > 0 {
        let wasted = post_residual as f64;
        let ratio = (next_item_size as f64 / post_residual as f64).min(1.0);
        score += 50.0 * wasted / 100.0 * (1.0 + ratio);
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving tiny unusable fragments (< 10) unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Slight bonus for filling bins more completely as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.3 * (0.5 + progress);

    // Mild penalty for opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0 + 20.0 * fitting_bins_count as f64;
        } else {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0;
        } else {
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let slack = (mean_residual - item_size as f64).max(0.0);
        score += 8.0 + 0.5 * open_bins_count as f64 + 4.0 * (1.0 - progress) + 0.2 * slack;
    } else {
        // Slight preference for bins below mean residual (more filled bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Time-decay: late in the stream, prefer conserving residual less aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress.
    // Early on, prefer tight fills (low post_residual); late in the stream,
    // dead space matters less since future demand declines.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 + 2.0 * progress) - pr_norm * progress;
    score += 40.0 * coupling;

    // Reward filling bins that cannot fit the next item (post_residual < next_item_size)
    if next_item_size > 0 && post_residual < next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // perfect lookahead fit
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize scattering when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.8 * pr_norm;

    // New-bin candidate: residual == capacity. Penalize so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + 30.0 * progress;
    }

    // Mild attraction toward bins with small mean residual (already tight bins)
    score += (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets of capacity/8
    let class = (post_residual * 8) / bin_capacity; // 0..=8 integer division class
    let class_penalty = match class {
        0 => -12.0, // perfect fit
        1 => -6.0,  // tiny leftover, highly reusable for small items
        2 => -2.0,
        3 => 2.0,   // mid-range dead zone
        4 => 4.0,
        5 => 5.0,
        6 => 1.0,
        7 => -4.0,  // large residual still broadly useful
        _ => 0.0,
    };
    score += class_penalty;

    // Modulo-10 harmonic: residuals divisible by 10 pair well with integer item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size exactly / well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 10.0; // chains perfectly into next item
            } else if gap <= 10 {
                score -= 5.0;
            } else if (gap * 8) / bin_capacity <= 1 {
                score -= 2.0;
            }
        } else {
            score += 1.5; // next item can't use this residual
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default
    if bin_residual == bin_capacity {
        // prefer new bin only if all open residuals are poor fits (large, awkward)
        let awkward = mean_residual > 0.45 * bin_capacity as f64 && post_residual > 20;
        if awkward && open_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Prefer tighter bins when many are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: fewer bins favored as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual usable for the lookahead item: reward that.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }
    // Dead space that cannot serve the next item: penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 0.8;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: penalize spreading across many bins mildly.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than average (best-fit-like coupling).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += 30.0 + desperation + step_index as f64 * 0.0;
        // A new bin is good if the current item is large and would leave little room.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: perfect if post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // Last item: prefer fullest bin.
        score -= 10.0;
    }

    // Compare against mean residual: bins already tight get priority.
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit well, unless item is huge.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 5.0;
        }
    }

    // Slight preference for fewer open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if placing here leaves residual that blocks the next item while another bin could host it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is cheap early / when few bins open; expensive when many open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = bin_capacity as f64 * 0.55 + progress * 20.0 + pressure * 3.0;

        // If only a new bin can fit the item, it must win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Avoid opening a new bin when an existing bin gives a near-perfect fit
        if fitting_bins_count >= 1 && post_residual_existing_hint(item_size, mean_residual) < 8.0 {
            score += 40.0;
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation)
    if !is_new_bin {
        let frag = post_residual as f64 - mean_residual;
        if frag > 0.0 {
            score += frag * 0.35;
        }
    }

    // Late in stream: prefer consolidating into existing bins
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= horizon * 5.0;

    score
}

#[inline]
fn post_residual_existing_hint(item_size: u32, mean_residual: f64) -> f64 {
    (mean_residual - item_size as f64).abs()
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    let norm_pr = pr / cap;
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) with smooth decay
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 4.0 * (gap.abs() / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: smooth sigmoid-like term
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual dispersion coupling
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: penalize mildly so open bins are preferred unless very tight
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let q = (post_residual * 10) / bin_capacity; // 0..=9 decile class
    let class_bonus: f64 = match q {
        0 => -30.0, // near-perfect fill
        1 => -22.0,
        2 => -14.0,
        3 => -6.0,
        4 => 2.0,
        5 => 6.0,
        6 => 10.0,
        7 => 14.0,
        8 => 18.0,
        _ => 25.0, // mostly-empty bin left behind
    };
    score += class_bonus;

    // Integer-division threshold: post_residual must be able to host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chains where next item fits; finer reward if it fits snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0;
            score -= 10.0 * (1.0 - slack / cap);
            // Harmonic coupling: next item in a "small class" (<=25) fits many residuals
            if next_item_size <= 25 { score -= 6.0; }
        } else {
            // Dead space for the lookahead: penalize proportionally to wasted residual.
            score += 8.0 + 0.35 * (post_residual as f64);
        }
    } else {
        // Last item: just minimize residual.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score = 55.0 + 0.5 * mean_residual - 8.0 * crowded;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // fresh bin guarantees room for lookahead
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64) * 2.0;

    // Penalize residual far from mean (fragmentation signal).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than proportionally.
    let unusable_threshold = 10.0f64.min(next_item_size as f64);
    if post_residual > 0 && (post_residual as f64) < unusable_threshold {
        score += (unusable_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual) with a bonus.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.15;

    // Open bins pressure: discourage adding load to bins when many bins are open.
    score += (open_bins_count as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins have large residuals
    // (poor fits elsewhere) or too many bins already open.
    if bin_residual == bin_capacity {
        score -= 20.0;
        score += mean_residual * 0.5;
        score += (open_bins_count as f64) * 1.2;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
        score -= 5.0;
    } else if next_item_size > 0 {
        // next item cannot fit here afterwards; slight penalty if post_residual wasted.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Stream progression: early on, be more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual), with a slight superlinear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't use leftover; penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 6.0 * (dead / bin_capacity as f64);
        }
    }

    // Relative to mean residual: bins with more room than average are cheaper to use.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a large, unusable residual.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 60.0 + waste; // default high; reduced if item is large
        score -= item_size as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space just above
    // the smallest item size (10) is the worst kind of waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: penalize if post_residual can't fit the next item but is close to it,
    // reward if post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0 * (1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64));
        } else {
            let gap = nxt - post_residual as f64;
            if gap < 20.0 {
                score += 12.0 * (1.0 - gap / 20.0); // near-miss wastes the bin
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation by penalizing spread-out residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * (mean_residual / bin_capacity as f64) * 3.0;

    // New-bin candidate handling: an empty bin should only win when no existing
    // bin gives a good fit (post_residual large relative to capacity) or late
    // in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let fit_quality = (post_residual as f64) / bin_capacity as f64;
        if fitting_bins_count > 0 && fit_quality < 0.55 {
            score += 60.0; // an existing bin fits decently; don't open a new one
        } else {
            score -= 15.0 * progress; // early on, opening bins is cheap
        }
    }

    // Mild non-linear preference for filling bins past half capacity.
    let fill = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual non-linearly (dead space grows quadratically in cost)
    let mut score = 2.0 * norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more; early, keep bins flexible.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    let coupling = (progress * std::f64::consts::PI).sin();
    score -= 0.8 * coupling * tightness * tightness;

    // Reward using a bin whose residual closely matches the item (smooth gaussian-like fit)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 0.6 * (-8.0 * fit_gap * fit_gap);

    // Lookahead: reward leaving exactly room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_next = (pr - nxt) / cap;
        score -= 0.7 * (-10.0 * match_next * match_next);
        // penalize post-residual that is uselessly small compared to next item
        if pr < nxt {
            score += 0.5 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Slight penalty for spreading across too many open bins with high mean residual
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).max(0.0);

    // New-bin candidate: only attractive when it beats poor fits (high post-residual elsewhere)
    if bin_residual == bin_capacity {
        score += 1.5 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes.
    // Small leftovers that align with typical item sizes are "usable" classes.
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= 10 { 1 }          // dead-ish but tiny
        else if pr % 10 == 0 { 2 }      // perfectly divisible class
        else if pr % 5 == 0 { 3 }
        else if pr <= 20 { 4 }
        else { 5 };

    match class {
        0 => score -= 25.0,                    // perfect fit: strong reward
        1 => score += 6.0,                     // small unusable scrap penalty
        2 => score -= 12.0,                    // divisible residual likely reusable
        3 => score -= 6.0,
        4 => score += 3.0,
        _ => {}
    }

    // Harmonic coupling: does next_item_size divide into post_residual exactly?
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if post_residual % next_item_size == 0 {
            score -= 10.0 + 3.0 * k as f64;    // chain fit reward
        } else {
            score -= 4.0;                       // next item still fits
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: residual is likely dead space
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when fit is bad and
    // the stream is early enough that open bins are still precious.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // penalty shrinks as stream progresses; opening bins late is cheaper
        score += 30.0 * (1.0 - 0.5 * progress);
    }

    // Prefer fuller bins relative to mean residual state.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild pressure toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (below the minimum item size 1, and especially
    // below ~15) are pure waste. Penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: the smaller the post_residual relative to the item,
    // the better the packing efficiency.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are large and fragmented (pressure is low).
    if bin_residual == bin_capacity {
        // Baseline mild penalty so tight fits in open bins win.
        score += 15.0;
        // But if open bins are crowded (many bins, high mean residual),
        // a fresh bin is fine to consolidate.
        if open_bins_count > 4 && mean_residual > 30.0 {
            score -= 20.0;
        }
        // If the next item would fit better in a fresh bin, encourage it.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            if next_item_size as f64 > mean_residual {
                score -= 18.0;
            }
        }
    } else {
        // Prefer placing into bins whose residual is close to the item,
        // penalize dumping a small item into a huge residual.
        let waste = (bin_residual as f64 - item_size as f64).max(0.0);
        score += waste * 0.2;
    }

    // Open-bins pressure: with many open bins, favor consolidating into
    // existing bins rather than spreading; with few bins, be pickier.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that perfect gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post residual, mildly penalize this gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early in the stream, be slightly more conservative (keep bins tidy).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward chains that keep slack small
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // last item: strongly prefer fullest packing
        score -= 50.0;
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 25.0 + 60.0 * fit_quality;
    }

    // New-bin candidate handling: make the empty bin attractive only when the
    // current item is large relative to capacity or open bins are all poor fits.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin mildly; overcome it only for big items
        // or when many bins exist but none fit well (handled via fitting count).
        score += 35.0 - 30.0 * large_item;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0; // fresh bin chains perfectly with next item
        }
        // late in the stream, discourage proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight preference to consolidate into fewer bins when many are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero or tiny post residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space that cannot hold small items (below minimum plausible size).
    let dead = post_residual as f64;
    score += 0.6 * dead;

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative (avoid fragmenting);
    // late in the stream, pack greedily into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= progress * 12.0 * (1.0 - tightness);
    score += (1.0 - progress) * 6.0 * tightness;

    // Global state: many open bins with slack -> encourage consolidation.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0).min(10.0);
    }

    // New-bin candidate: make opening a new bin costly unless the item is huge
    // or no reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size > 70 {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Penalize large dead space more as stream advances
    score += 30.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth subtraction
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = (pr - n).max(0.0) / cap;
        let usable = if pr >= n { 1.0 - (1.0 - fit_next).powf(2.0) } else { -1.0 };
        score -= 15.0 * usable;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer filling existing ones (penalize new-bin tendency)
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 2.0 * open_pressure * norm_pr;

    // Mean residual alignment: favor bins near mean residual (smooth)
    let diff = (pr - mean_residual).abs() / cap;
    score += 10.0 * diff * diff;

    // New-bin candidate: make it costly unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap);
        score += 35.0 + 50.0 * mean_fill * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post-residual: integer division into capacity octaves.
    let class = post_residual / (bin_capacity / 8 + 1); // 0..=8 class index
    match class {
        0 => score -= 45.0,                      // near-perfect fill
        1 => score -= 25.0,                      // small dead space
        2 => score -= 10.0,
        3 => score += 0.0,
        4 => score += 6.0,
        5 => score += 12.0,
        6 => score += 20.0,
        7 => score += 30.0,
        _ => score += 40.0,                      // bin left mostly empty
    }

    // Modulo arithmetic: residuals divisible by small ints pack well (future items align).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
        if post_residual % 3 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / cap);
        if post_residual == next_item_size { score -= 20.0; } // perfect two-item closure
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space proportionally
        score += 8.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or stream is early (amortization) — compare against mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 25.0 + 40.0 * (1.0 - progress) * (1.0 - bad_fit)
                 - 35.0 * bad_fit
                 - 10.0 * fit_quality;
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Tie-break toward consolidating residual mass (mean residual alignment).
    score += 0.05 * (pr - mean_residual);

    // Slight preference for tighter bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but treat < 12 as near-dead) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Non-linear tightness reward: reward small usable residuals.
    score -= 0.5 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 20.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: dead end risk.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow new bins when the fleet is small and residuals are fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = 70.0 + open_bins_count as f64 * 2.0;
        // If mean residual is large and can host future items, opening new bin is bad.
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
        // Early in stream, new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild reward for filling existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // Penalize bins whose residual deviates from mean (fragmentation control).
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits exactly into the post residual with slack tolerance.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 25.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
    }

    // Reward tight fits relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(50.0);
    } else {
        score += (post_residual as f64 - mean_residual).min(50.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving very small unusable fragments (< 10% capacity).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 40.0;
    }
    // Reward exact fills.
    if post_residual == 0 {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad waste.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = waste_if_open * 0.4 + 30.0;
        if fitting_bins_count == 1 {
            score += 150.0; // keep the last-chance bin attractive instead
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0; // fresh bin can also host next item
        }
    }

    // Mild late-stream conservatism: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 0.35 * tightness * cap;

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are waste
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / cap);
            if gap < 10 {
                score -= 10.0; // next item nearly fills the remainder
            }
        } else {
            // next item cannot fit here: slight penalty for hoarding space it can't use
            score += 5.0;
        }
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // open bins are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - cap / 2.0).abs();
        // Prefer new bin when open bins are very fragmented and item is big.
        if item_size as f64 > mean_residual {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 15.0 + fragmentation * 0.3;
        }
        // Late in the stream, consolidating into existing bins is cheaper.
        if progress > 0.85 {
            score += 25.0;
        }
    } else {
        // Reward bins whose residual is above mean (they have more room to spare).
        score += 0.1 * ((mean_residual - bin_residual as f64).max(0.0));
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Prefer filling bins with larger residual capacity when item is large.
    if item_size > 50 {
        score -= 0.15 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 + progress);

    // Dead-space penalty: small post_residual wasted is fine, large waste penalized
    let dead = 0.8 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -30.0 * (1.0 - progress) } else { 0.0 };

    // Lookahead: reward leaving room for the next item
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr { -8.0 * (1.0 - nx / cap) } else { 6.0 * (nx - pr) / cap }
    } else { 0.0 };

    // Mild pressure toward consolidating into fewer bins
    let consolidation = -0.5 * (open_bins_count as f64).ln().max(0.0);

    let mut score = pr + 20.0 * poly + dead + last_chance + lookahead + consolidation;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // item sizes are more reusable; prime/odd residuals are dead space.
    let cap = bin_capacity as f64;

    // Class A: post_residual is a multiple of common small sizes (10,20,25)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Class B: post_residual exactly matches the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover after also fitting next item
        let after_next = post_residual - next_item_size;
        score -= 6.0;
        if after_next % 10 == 0 {
            score -= 5.0;
        }
        if after_next < 10 {
            score += 12.0; // creates sub-10 dead space
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // bin can't serve the next item; penalize proportionally to gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Integer division threshold: tiny residuals are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 10.0 + 20.0 * (1.0 - progress) - if next_item_size as f64 > mean_residual { 8.0 } else { 0.0 };
        score += penalty.max(2.0);
        let _ = frag;
    } else {
        // Prefer bins with residuals below the mean (tighter packing)
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    // Harmonic capacity fraction: filling to exact quarter-marks is good
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if (fill * 4.0).fract() < 1e-9 {
        score -= 3.0;
    }

    // Modulo class of item size: odd-sized items create odd residuals,
    // slightly penalize pairing them into bins that stay odd
    if item_size % 2 == 1 && post_residual % 2 == 1 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1) are pure waste.
    // Penalize gaps that can't fit the next item either — they become unusable for lookahead.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward leaving exactly enough room for the next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Strict dead-space avoidance: small-but-nonzero gaps are worse than exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 + (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) * 0.15;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_residual as f64 - mean_residual).max(-10.0).min(10.0) * 0.1;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post residual close to 0).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 200.0; // perfect chain: item then next item fills bin
        } else if diff <= 5 {
            score -= 90.0;
        } else if diff <= 10 {
            score -= 40.0;
        } else {
            // penalize leaving a gap that next item cannot use
            score += (diff as f64).sqrt() * 6.0;
        }
        // If next item cannot fit in the post residual at all, mild penalty
        if next_item_size > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: strongly prefer tightest fit, dead space is permanent.
        score += post_residual as f64 * 1.5;
    }

    // Relative to mean residual: prefer bins with less residual (fuller bins).
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: discourage opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // If many bins already open, slight economy-of-scale nudge against new bins.
        score += open_bins_count as f64 * 2.0;
        // But if the item is large, a fresh bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 80.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    }

    // Mild penalty for wasting a large bin on a small item.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mild penalty scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.15 * miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: bins far below mean are good targets.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.1 * dev;

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, be greedy and fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * tightness;

    // New-bin candidate: only attractive when it beats chaining potential,
    // i.e., when existing residuals are all poor fits for current + next item.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let next_bonus = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        // Prefer new bin when open bins are nearly full on average and next item is large.
        score += 45.0 - 0.5 * open_pressure - 0.2 * next_bonus - 40.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Core: post-residual with smooth non-linear penalty for medium dead space
    let mut score = pr as f64;
    score += 18.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.35) * (1.0 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + progress);
    }

    // Penalize spreading across many open bins slightly
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 5.0 * (fitting_bins_count.max(1) as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group by capacity fractions (integer division)
    let post = post_residual as u32;
    let class = post / 10; // harmonic decile class
    let class_mod = (post % 20) as f64;

    // Reward placements landing in "harmonic" residual classes that pair well
    // with common item sizes (multiples of 10 and 25-ish).
    let harmonic_bonus = match class {
        0 => 25.0,                       // near-perfect fit, dead space minimal
        1 => 12.0,                       // residual 10..19: fits small items
        2 | 3 => 6.0,                    // residual 20..39: mid-small items
        4 | 5 => 0.0,                    // neutral mid zone
        6 | 7 => -4.0,                   // residual 60..79: still quite usable
        _ => -8.0,                       // residual 80+: bin barely touched
    };
    score -= harmonic_bonus;

    // Modulo coupling: if post_residual mod 20 is small, the leftover chunk
    // aligns with typical item granularities -> reward.
    score -= 0.5 * (20.0 - class_mod.min(20.0)) / 20.0 * 10.0;

    // Lookahead: reward if next item fits exactly into post_residual (perfect pairing)
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            // fits but wastes (post - next) space; penalize waste
            score += 0.3 * (post - next_item_size) as f64;
        } else {
            // next item cannot use this residual -> leftover is likely dead space
            score += 0.15 * post as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        // fresh bin: baseline score is just post_residual (= cap - item),
        // add a mild opening cost; discounted early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer filling bins that are already relatively full (small residual)
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // If many bins are open, encourage consolidation into tight fits
    if open_bins_count > 4 {
        score += 0.1 * post as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64 / (1.0 + progress * 20.0));
    } else {
        score -= 5.0;
    }

    // Lookahead coupling: favor residual that can still host the next item
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (better packing)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post residual is a tight fit; reward quadratically.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            // next item fits: residual after that placement
            let pr2 = (post_residual - next_item_size) as f64;
            score += pr2 * 0.6;
            if pr2 == 0.0 {
                score -= 30.0;
            }
        } else {
            // next item would NOT fit here: penalize leaving a gap that
            // wastes the residual relative to the upcoming item.
            score += 8.0;
            // large unusable gap is worse
            if post_residual < next_item_size && post_residual > 0 {
                score += pr * 0.25;
            }
        }
    } else {
        // Last item: prioritize zero residual even more.
        score -= pr * 0.5;
    }

    // Compare residual against mean residual: bins with residual far below
    // mean are tight bins — placing here keeps tight bins tight.
    let diff = pr - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin gives a
    // good fit. Baseline: new bin has residual = capacity, so pr = capacity
    // - item_size is large; the quadratic term already penalizes it. Add a
    // mild penalty that shrinks as the stream progresses (toward the end,
    // prefer filling open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 25.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also host the lookahead item snugly.
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // When many bins fit the item, prefer the one with the smallest residual
    // (best-fit style); add mild competition pressure.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Encourage consolidation: favor bins below mean residual (more filled).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin early in the
    // stream or when open bins are still roomy; allow it late or when the
    // item is large and fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * openness;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin is attractive for chaining large items.
            score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild time-horizon modulation: tighten threshold as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on mid-range waste
    let mut score = pr
        - 18.0 * (pr_norm * (1.0 - pr_norm) * 4.0) // penalize mid residuals, reward tight fits
        + 6.0 * pr_norm * pr_norm * cap * progress; // late stream: residual waste matters more

    // Non-linear coupling of post_residual with stream progress
    score += 10.0 * (pr_norm * progress).sin() * 2.0;

    // Reward bins that also fit the next item (smooth lookahead bonus)
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * fit_ratio * fit_ratio;
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins close to mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + progress);

    // Many open bins: mildly favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: penalize slightly so it's chosen only for good long-term use
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "usable"
    // by common item sizes (multiples of 5 / 10) via modular arithmetic.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let mod10 = (pr % 10) as f64;
        let mod5 = (pr % 5) as f64;
        score += mod10 * 1.5 + mod5 * 1.0; // penalize off-class residuals
        // Integer-division thresholds: residuals >= 50 are "half-usable",
        // residuals < 10 are near-dead.
        if pr >= 50 { score -= 10.0; }
        if pr < 10 { score += 15.0; }
        else if pr < 20 { score += 7.0; }
    }

    // Lookahead coupling: strongly favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact harmonic match: post_residual is an exact multiple-ish of next item
            let rem = (post_residual % next_item_size.max(1)) as f64;
            score -= 25.0 + (next_item_size as f64) * 0.2 - rem * 0.3;
        } else {
            // Next item won't fit here; penalize wasted near-miss space.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 { score += miss * 2.0; }
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = (item_size as f64) / cap;
    score -= fill * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when it enables a near-perfect
    // packing (item exactly divides capacity) or when existing bins are crowded.
    if bin_residual == bin_capacity {
        let exact = (bin_capacity % item_size == 0) as f64;
        let pair = (next_item_size > 0 && item_size + next_item_size == bin_capacity) as f64;
        let crowding = (open_bins_count as f64).max(1.0).ln() * 4.0;
        score = cap * 0.9 - exact * 70.0 - pair * 50.0 - crowding
              + (fitting_bins_count == 0) as i32 as f64 * 80.0;
    }

    // Mild stream-progression pressure: late in the stream, consolidate more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 3.0 * (bin_residual >= item_size) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps (< next item or < 10) are nearly unusable.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold.min(20) {
        score += (dead_threshold.min(20) - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        score += (item_size as f64 / bin_residual as f64) * -8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many open bins exist
    // or when an existing bin fits well (post_residual small).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
        if post_residual < 15 {
            score += 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual close to item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Late in stream, be greedy about closing bins (favor zero residual more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (20.0 - post_residual as f64 * 0.2).max(0.0);

    // Slight tie-break toward bins below mean residual (consolidating emptier bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If next item cannot fit in the leftover, penalize dead space proportionally
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
        // very small unusable leftover is worse
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // If next item fits with room to spare (partial match), mild reward
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 0.2 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with residuals below mean (tighter packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Reward filling bins completely as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Discourage spreading across too many bins
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin would leave big waste
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 20.0; // open new bin when leftover would be dead space
        } else {
            score += 25.0 + 0.3 * waste; // keep using existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always excellent
    } else {
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * (pr / 10.0); // quadratic dead-space penalty
    }

    // Lookahead: penalize leaving a residual that neither fits the next item well
    // nor is usefully large; reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            let slack = post_residual as f64 - n;
            if slack == 0.0 {
                score -= 120.0; // next item perfectly fills leftover
            } else {
                score += slack * 0.15; // mild penalty for awkward leftover
            }
        } else {
            // leftover too small for next item: dead space unless near zero
            let waste = post_residual as f64;
            if waste < 10.0 {
                score -= 20.0; // negligible residue is fine
            } else {
                score += waste * 0.35;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        // more open bins => prefer consolidating into existing ones
        score += open_bins_count as f64 * 5.0;
        // early in stream, opening bins is cheaper (need inventory)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 30.0;
        // if the item is large, a fresh bin keeps flexibility
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // if next item is large too, fresh bin pairs them well
        if next_item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    } else {
        // Slight preference for bins whose residual is close to the mean
        // (keeps the pool homogeneous and predictable).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (smoothly increasing penalty later)
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * progress_poly * pr_norm * pr_norm * cap;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0);
        score += 0.8 * gap + 0.4 * gap * gap / cap;
        // Reward residuals that exactly or nearly fit the next item
        let fit_gap = (pr - nx).abs();
        score -= 3.0 * (1.0 - fit_gap / cap).max(0.0);
    } else {
        // last item: strongly prefer minimal residual
        score += 2.0 * pr_norm * cap;
    }

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for scattering across many open bins; smooth in open count
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 4.0 * open_norm * pr_norm * cap;

    // Coupling with mean residual: prefer bins deviating below mean (tightening)
    score += 1.5 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are multiples of common
    // item-size classes (10/20/25/50) since future items likely fit exactly.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut h = 0.0;
        if r > 0 {
            if r % 10 == 0 { h += 6.0; }
            if r % 20 == 0 { h += 4.0; }
            if r % 25 == 0 { h += 3.0; }
            if r % 50 == 0 { h += 5.0; }
            if r == 0 { h += 12.0; } // perfect fill
        }
        h
    };

    // Reward closing bins exactly; penalize tiny dead space (1..=9) which is unusable
    // for items >= 10.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score += 12.0; // dead space penalty
    }

    score -= harmonic_bonus(post_residual);

    // Lookahead: strongly favor bins whose post_residual fits the next item exactly
    // or harmonically.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 4.0; }
            score += slack as f64 * 0.15;
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer tight fits: relative fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    // Slight pull toward mean residual to keep bin load balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: only attractive when current bins fit poorly (large post_residual)
    // or no open bin fits well; keep it moderately costly otherwise.
    if bin_residual == bin_capacity {
        score += 14.0 - fill * 0.0; // base cost of opening a new bin
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 6.0; // room for lookahead pairing
        }
        if post_residual == bin_capacity {
            // empty bin call: post_residual == capacity; judge by item size
            score += item_size as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead space avoidance: post_residual that is small but unusable
    // (cannot fit the next item and is below the minimum item size) is wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 12.0;
        }
    }

    // Perfect fit relative to capacity.
    if bin_residual == item_size {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Open bins pressure: discourage scattering across many bins slightly.
    score += 0.05 * open_bins_count as f64;

    // Progression: late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward exact closure.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual well.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let pr = post_residual as f64;
        if next_item_size as u32 <= post_residual {
            // Next item fits exactly or near-exactly: strong reward.
            score -= (1.0 - gap / (bin_capacity as f64)) * 60.0;
            if gap == 0.0 {
                score -= 200.0;
            }
        } else {
            // Next item won't fit here; penalize large stranded residuals
            // especially if they are small/unusable.
            let stranded = pr / bin_capacity as f64;
            score += stranded * 30.0;
        }
        // Nonlinear coupling: small post-residuals are good dead space.
        score += (pr / bin_capacity as f64).powi(3) * 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, unless current
    // fit is terrible (large post-residual) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Base preference to reuse existing bins.
        score += 25.0;
        // But if the best existing fit is bad, new bin becomes attractive:
        // (this call is compared against those bins' scores).
        score -= fit_quality * 0.0; // new bin post_residual == 100 handled naturally
        let _ = progress;
        // Late in stream, prefer closing existing bins over opening new ones.
        if total_items > 0 && step_index + 1 >= total_items.saturating_sub(5) {
            score += 200.0;
        }
    }

    // Prefer filling bins when many are open (bin-count control).
    if open_bins_count > 3 {
        score += (post_residual as f64) * (open_bins_count as f64).ln() * 0.05;
    }

    // Small item into large residual: fine; large item leaving tiny residual: great.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: the smaller the post-residual, the better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powf(2.0);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 80.0;
        } else {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize large dead space.
        score += 0.15 * post_residual as f64;
    }

    // Penalize creating unusable slivers (< smallest plausible item ~ 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // New-bin candidate: prefer it only when few fitting bins exist or fit elsewhere is bad.
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
        score += 40.0 * pressure;
        // Late in the stream, keep consolidating into open bins.
        score += 30.0 * progress;
        // If mean residual across open bins is high, opening a new bin wastes capacity.
        score += 0.3 * mean_residual;
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: waste term, quadratically coupled with stream progress.
    // Late in the stream, dead space becomes increasingly costly.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Non-linear coupling: post_residual interacts with normalized residual ratio.
    let fill_ratio = item_size as f64 / cap;
    let post_ratio = post / cap;
    score += 8.0 * post_ratio * post_ratio * (1.0 - fill_ratio) * cap;

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) * (1.0 - post_ratio).powi(2) * 0.5;

    // Lookahead: penalize residual that is too small to fit the next item
    // (wasted space), but reward residual that exactly accommodates it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - post / (nxt * 2.0)).max(0.0);
        } else {
            score += 3.0 * (nxt - post) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only if it beats poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress;
    }

    // Mean-residual coupling: penalize bins deviating from the mean residual
    // (keeps bin pool homogeneous, easier future packing).
    score += 0.3 * (post - mean_residual).abs();

    // Mild pressure against accumulating many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // residue classes (multiples of 10, small residues) are more valuable to keep.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Modulo-10 harmonic class: exact multiples of 10 are ideal leftover slots.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Small dead space is bad (unusable for typical items >= 10 unless exactly matched).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }
    // Perfect fit is best.
    if pr == 0 {
        score -= 30.0;
    }

    // Fractional capacity classes: post_residual / capacity thresholds.
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 5.0; // bin still half-full, flexible
    } else if frac < 0.1 && pr > 0 {
        score += 6.0; // nearly empty leftover, low utility
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chain placement possible
            // Harmonic match: next item exactly fills to a multiple of 10
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins when open bins exist,
    // unless this item is huge and open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 25.0;
        if open_bins_count == 0 {
            score -= 25.0; // nothing else available
        }
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 20.0; // item too big for fragmented open bins
        }
    }

    // Progress coupling: later in stream, prefer tighter packing (lower post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * (1.0 - progress) * 4.0;
    score -= (1.0 - frac) * progress * 3.0;

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    score += (mean_residual - pr as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are wasted.
    // Items range 1..100 (unknown dist), so treat small residuals as risky dead space.
    if post_residual < 10 {
        score += 25.0; // unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        // Reward leaving room for a mid-size follow-up item
        score -= 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new.
    // New bin candidate has bin_residual == bin_capacity; penalize it when open bins exist.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0 + 5.0;
        // late in stream, opening new bins is relatively cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Filling an open bin reduces open-bin pressure slightly
        score -= 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // keeping looser bins available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Mild penalty for very loose fits (large post_residual) when bin was nearly full
    if item_size < bin_residual as u32 / 4 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted residual quadratically (dead space is bad).
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item -> strong reward.
        score -= 25.0 / (1.0 + gap);
        // Exact fill after placing next item is ideal.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize if post_residual is too small for next item (becomes dead space soon).
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let next_fits_new = next_item_size > 0 && waste >= next_item_size as f64;
        score = waste + if next_fits_new { 5.0 } else { 20.0 };
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins -> discourage opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Small bonus for tight fits (low post residual relative to item).
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual as u32 {
            score += 3.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Compare against the average residual: placing into a bin that is already
    // below average residual (i.e., more filled) is good.
    let avg_gap = mean_residual - post_residual as f64;
    score -= 2.0 * avg_gap;

    // Early in the stream, keep bins balanced slightly; late in the stream,
    // fill existing bins aggressively to avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 6.0;

    // Discourage opening new bins when several bins are already open and fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 10.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
        // If the item fits very well into an existing bin elsewhere, new bin is bad.
        if fit_ratio > 0.7 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr;
    score += 25.0 * norm_pr * norm_pr * norm_pr;

    // Tight fits are valuable: reward small post_residual non-linearly
    let tightness = 1.0 - norm_pr;
    score -= 18.0 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 + 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0));
    }

    // Stream-progress coupling: later in stream, prefer tighter packing
    score -= 15.0 * progress * tightness;

    // Penalize bins deviating from mean residual (encourage balance)
    score += 6.0 * ((pr - mean_residual).abs() / cap);

    // Many open bins: slight preference for filling existing ones over new
    let open_f = open_bins_count as f64;
    score -= (open_f / (open_f + 5.0)) * 10.0 * tightness;

    // New-bin candidate: penalize unless residual truly unusable
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic class of the residual: residuals that are multiples of 10
        // (matching the classic item-size granularity) are more reusable.
        let m = post_residual % 10;
        score -= (10 - m) as f64 * 0.7;

        // Fractional capacity class of leftover space
        let frac = post_residual as f64 / cap;
        if frac < 0.1 {
            // tiny dead space is fine
            score -= 15.0;
        } else if frac < 0.35 {
            // medium leftover: mildly good
            score -= 5.0 * (0.35 - frac);
        } else {
            // large leftover: waste, penalize proportionally
            score += 12.0 * frac;
        }
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            score -= 10.0 * (1.0 - (pr - n) / cap); // next item fits: reward tight coupling
        } else {
            score += 0.8 * (n - pr); // dead space relative to next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.15 + (open_bins_count as f64).min(20.0);
    }

    // Late in the stream: consolidate, prefer filling bins near capacity
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 8.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that can only fit very small items relative to the known size range.
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 12.0;
    }

    // Reward tight fits (low post residual) strongly.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist and fit.
        score += 30.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by post residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Mild pressure term on open bin count for existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // next item fits; penalize leftover dead space after the pair
            let pair_left = post_residual - next_item_size;
            score -= 300.0 - pair_left as f64 * 1.5;
        } else {
            // next item does NOT fit here; penalize wasting residual capacity
            let waste = post_residual as f64;
            score += waste * 0.8;
            // extra penalty if residual is too small to ever be useful (below min item size)
            if post_residual < 10 {
                score += 200.0;
            }
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative to mean residual: favor bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are hopeless fits
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 150.0;
        // but if item fits poorly everywhere (post_residual small relative to item), new bin is fine
        // if open_bins_count == 0 it's the only option
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // early in stream, be more willing to open bins for flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Tightness preference: smaller post_residual is better overall (already base), amplify slightly
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Reward near-perfect fits strongly (post_residual small relative to item).
    let fit_ratio = post_residual as f64 / (bin_capacity as f64);
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that is too small for the smallest plausible item,
    // scaled by how late in the stream we are.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += 25.0 * (0.5 + progress);
    } else if post_residual <= 20 {
        score += 8.0 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // next item cannot use the leftover: mild penalty proportional to waste
            score += (post_residual as f64) * 0.3;
        }
    }

    // Global state coupling: prefer filling bins that already have low residual
    // (tight bins) relative to the mean residual across open bins.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Slight penalty for opening new bins when many bins are already open,
    // unless the item fits the new bin very well (post_residual small).
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if post_residual < 5 {
            score -= 20.0; // item fills the new bin almost exactly
        }
        // Early in the stream, opening bins is cheaper; later, avoid fragmentation.
        score += progress * 10.0;
    }

    // Mild reward for preferring larger residuals overall early in the stream
    // (keeps bins balanced), fading later.
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic in fill ratio, smooth non-linear coupling.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * fill * fill;

    // Dead-space penalty for small residuals that most future items can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Non-linear polynomial coupling with normalized stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer consolidating into open bins (penalize new bins).
    // Late stream: residual waste matters less, allow looser fits.
    score -= 30.0 * (1.0 - p2);           // early: extra tightness reward
    score += 20.0 * p3 * (post_residual as f64 / cap); // late: tolerate waste slightly

    // New-bin candidate handling: smooth sigmoid-like gate on mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let gate = 1.0 / (1.0 + (-8.0 * (mean_norm - 0.35)).exp());
        // If open bins are quite full on average, a new bin is reasonable.
        score = 40.0 + 60.0 * gate + 15.0 * (1.0 - p2);
        // Lookahead: if next item is large, opening a fresh bin early is worse.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score += 20.0;
        }
    } else {
        // Last-chance bin: strong reward to use it rather than open a new bin.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // Lookahead synergy: residual left should ideally fit the next item.
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            if (post_residual as f64) >= nr {
                score -= 12.0 * (1.0 - (post_residual as f64 - nr) / cap);
            } else {
                score += 8.0 * (nr - post_residual as f64) / cap;
            }
        }
        // Slight preference for bins tighter than the current mean residual.
        score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;
    }

    // Mild penalty for scattering across many open bins early on.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post-residual (integer division into bands) ---
    // Bands: [0,9] perfect, [10,19] great, [20,39] ok, [40,69] poor, [70+] bad
    let class: f64 = match post_residual {
        0..=9 => 0.0,
        10..=19 => 8.0,
        20..=39 => 20.0,
        40..=69 => 40.0,
        _ => 65.0,
    };
    score += class;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin keeps serving the next item: reward proportionally
            score -= 6.0 + 0.10 * (next_item_size as f64);
            // Harmonic bonus: next item lands in a fine band too
            if post_residual >= next_item_size && post_residual - next_item_size < 10 {
                score -= 8.0;
            }
        } else {
            // Post-residual is dead space for the next item: penalize waste
            let waste = post_residual as f64;
            score += 0.15 * waste;
            // If next item is small and we create a mid-sized hole, extra penalty
            if next_item_size < 20 && post_residual > 25 {
                score += 10.0;
            }
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline slightly worse than a good fit,
        // but better than a terrible fit into an open bin.
        // Good placements into open bins should beat this.
        score = 55.0 + 0.5 * (post_residual as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheap; late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // --- Mean residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins whose residual is close to the item (tight fits) ---
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * tightness;

    // Prefer using bins with residual near the mean (keeps bin population balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item = 1, but practically < ~10 are near-useless)
    // are heavily penalized as wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward fitting the next item exactly after this placement (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize placements that leave a gap just barely too small for the
    // next item (dead space creation with lookahead evidence).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 0.35;

    // Prefer bins whose residual is already below average (tighter bins
    // first keeps loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is large
    // and no good fit exists (its post_residual is naturally high, but add
    // a mild fixed penalty so it is only chosen on genuinely bad fits).
    if bin_residual == bin_capacity {
        score += 10.0;
        // Large items still fit reasonably in a fresh bin.
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build
    // diversity); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Residual can host next item; reward closeness of the match.
            score -= (1.0 - gap / (bin_capacity as f64)) * 25.0;
        } else {
            // Next item can't fit in the leftover; penalize proportionally to wasted gap.
            score += gap * 0.35;
        }
    }

    // Compare against mean residual of open bins: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating large dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny residual is fine (bin nearly full)
    } else if post_residual > 0 {
        // dead-space penalty grows quadratically for mid-range leftovers
        let r = post_residual as f64;
        score += 0.002 * r * r;
    }

    // Early in the stream, be slightly more willing to open new bins (spread load).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base score, discounted early, penalized late.
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
        // If no open bin fits well, new bin is attractive; if many bins fit, discourage.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference to fill bins when many are open (consolidation pressure).
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize creating dead space that is too small for typical items
    // (small residuals are hard to reuse), but only if it isn't zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin. Reward heavily unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * bin_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
        // Penalize if post residual almost-but-not-quite fits next item
        // (wasted potential), scaled by how close it is.
        if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
            score += 8.0;
        }
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 10.0 * consolidation.max(0.0);
    }

    // Time horizon: early in the stream, be more conservative about opening
    // new bins (long horizon to fill them); late in the stream, tight fits matter most.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty that grows with the
        // number of already-open bins, reduced as the stream progresses.
        let mut new_bin_score = 55.0 + 4.0 * open_bins_count as f64 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            new_bin_score -= 12.0;
        }
        // If no open bin is a good fit (large post residual elsewhere implied
        // via mean residual), new bin becomes more acceptable.
        if mean_residual < item_size as f64 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Late in the stream, slightly prefer bins with smaller residual overall
        // to close them out.
        score += progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: post residual, scaled smoothly with progress
    let mut score = pr * (0.9 + 0.4 * progress);

    // Non-linear polynomial coupling of post residual with progress
    score += 30.0 * pr_norm * pr_norm * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize large post residual when mean residual is small (wasted space relative to others)
    score += 12.0 * (pr_norm - mean_norm).abs() * (0.5 + 0.5 * progress);

    // Reward tight fits: subtract for small post residual, stronger late in stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * item_norm * (0.6 + 0.8 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: penalize if post residual cannot fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        if pr_norm < nxt {
            score += 8.0 * (nxt - pr_norm) * (0.5 + progress);
        } else {
            score -= 6.0 * (pr_norm - nxt) * (1.0 - pr_norm);
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64) * 0.3 * pr_norm;

    // Smooth sinusoidal progress modulation for fine-tuning
    score += 3.0 * (std::f64::consts::PI * progress).sin() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty: residuals that cannot host typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class rewards: residuals in classes {0, 25, 50, 75, 100} are
    // "harmonic" because future items of sizes 10..80 align with them.
    let class = post_residual % 25;
    let class_bonus = match class {
        0 => 12.0,
        5 => 4.0,
        10 => 6.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.3 * (next_item_size as f64);
        // Extra reward if next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.25 * gap.min(80.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild default cost so it
    // is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 - 0.1 * open_bins_count as f64;
        // Early in stream, prefer filling open bins less strictly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score += 10.0;
        }
    }

    // Tightness bonus: prefer bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize creating residuals that are awkward fractions of capacity.
    if frac > 0.0 && frac < 0.1 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - pr);

    // Integer division threshold: post_residual / 10 class alignment with
    // common item sizes (multiples of 10).
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate penalty for gaps that likely can't fit average future items.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: strongly favor using this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // More open bins => more pressure to fill existing ones.
        score += 2.0 * open_bins_count as f64;
        // But if the item nearly fills a fresh bin, opening new is fine.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Open-bins pressure: prefer bins below mean residual (consolidating fuller bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    // Lookahead: reward leaving a gap that fits the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap left is too small for the next item: dead space penalty.
        score += 12.0;
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by item size
    // so that big items get placed preferentially into tight spots.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item's size (perfect chaining), punish large mismatches.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        // Perfect match bonus: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item fits in the post residual, mild reward (keeps chain going).
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // If next item won't fit here but would fit elsewhere, penalize leaving
        // a small awkward residue.
        if post_residual < next_item_size && post_residual < 10 {
            score += 12.0;
        }
    }

    // Relative to mean residual: bins with residual below mean are more
    // "prime" for filling; placing here consolidates space.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.6 * (resid_f - mean_residual);
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.2 * (item_size as f64);
        if post_residual > 40 {
            score += 20.0; // terrible fit, maybe new bin is better
        }
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit in any open bin would be poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; becomes attractive when many bins
        // are open but residuals are small/fragmented.
        score = 55.0 - 0.5 * (open_bins_count as f64) + 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can always serve the next item too
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // don't open new bin if only one fitting bin exists
        }
    }

    // Late in the stream, tighten up: avoid leaving many near-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post-residual, but scale by fill ratio.
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 20.0;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead (k=2): penalize if next item fits the post-residual well
    // (we'd like to keep this space for it), reward if it doesn't fit here.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            // Next item could use leftover space: mild penalty proportional to fit quality.
            let slack = post_residual as f64 - next_item_size as f64;
            score += 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; leftover space is likely dead -> penalize leftover.
            score += 6.0;
            if post_residual < 10 {
                score -= 10.0; // but tiny dead space is fine
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 35.0;
        // More open bins with small mean residual -> avoid new bins.
        score += open_bins_count as f64 * 1.5;
        score -= mean_residual * 0.3;
        // Early in stream, new bins are cheaper; late in stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Global state: many open bins -> prefer filling existing ones tighter.
    score += open_bins_count as f64 * 0.5;
    score -= mean_residual * 0.1;

    // Time horizon coupling: as stream progresses, weight tightness more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Small nonlinear shaping on residual to break ties toward mid-range fills.
    score += (residual_ratio * std::f64::consts::PI).sin() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear emphasis
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual with stream progress:
    // late in the stream, waste is penalized more heavily (quadratic ramp)
    let late = progress * progress;
    score *= 1.0 + 2.0 * late * norm_pr;

    // Dead-space term: residuals too small for typical future items are bad,
    // penalize smoothly via interaction with progress
    let dead = if pr > 0.0 { (cap - pr) / cap } else { 1.0 };
    score += 8.0 * late * (1.0 - dead * dead);

    // Lookahead: if next item fits in post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (fill emptier bins first late, tighter bins early)
    score += 2.0 * (bin_residual as f64 - mean_residual) / cap * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins exist that fit; allow it late if residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap as f64 * (1.5 + progress) - 10.0 * fragmentation * progress;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable"
    // residues modulo common size classes (10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else {
        // dead-space penalty grows super-linearly for small unusable leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5; // tiny slivers are dead space
        }
        // reward residuals that align with likely future item sizes
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // integer-division thresholds: residual classes
        let class = pr / 20; // 0..5 harmonic class
        score -= match class {
            0 => 3.0,           // 0..19: nearly full, good
            1 => 1.0,           // 20..39
            2 => 0.0,           // 40..59
            3 => -1.0,          // 60..79: roomy
            _ => -2.0,          // 80+: very roomy
        };
    }

    // Tightness reward: fraction of bin filled by this placement
    let fill = item_size as f64 / cap;
    score -= fill * 12.0;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - pr) as f64;
            score += (over / cap).min(1.0) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create bad dead space or nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // more open bins => prefer consolidating into them
        score += open_bins_count as f64 * 1.5;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    } else {
        // prefer bins whose residual is close to the item (best-fit flavor)
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.0; // already captured by post_residual
        let _ = fit_gap;
    }

    // Mean-residual coupling: placing into a bin far from the mean residual
    // balances the portfolio of open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..=100)
    // are pure waste; the smaller the unusable gap, the harsher the penalty.
    if post_residual > 0 {
        // any leftover below ~10 can never fit an item from a 1..=100 stream
        // (items >= 10 in the classic regime; be conservative for small items too)
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 20 {
            // small gap: usable only by tiny items, still risky dead space
            score += 8.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 60.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create bad dead space or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // base cost for a fresh bin
        score += 30.0;
        // if item would leave a large usable residual, new bin is attractive
        // (keeps big residual for future big items)
        if post_residual >= item_size {
            score -= 10.0;
        }
        // more open bins -> pressure against opening yet another
        score += 2.0 * open_bins_count as f64;
    } else {
        // placing into an existing bin reduces open-bin pressure: mild reward
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            // next item won't fit here: leftover is likely dead space
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consolidating space into fewer, emptier bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: leftover exactly consumed by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Leftover still useful after next item: reward tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // Next item cannot fit in the leftover: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Penalize dead space far from mean residual (fragmentation indicator).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling already-open bins; discourage opening new bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - progress);
    } else {
        score -= 5.0 + 10.0 * progress;
    }

    // Reward near-perfect fills.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: nonlinear penalty on relative waste
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 120.0;
    }

    // Last-chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer bins that would be left with hard-to-fill residuals
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't use the leftover: penalize large unusable leftovers
            score += (post_residual as f64) * 0.35;
        }
    }

    // Global state: many open bins -> prefer filling existing ones, avoid new bins
    score += open_bins_count as f64 * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin -> favor using it
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.8;

    // Time horizon: early in stream, be conservative about dead space; later, prioritize bin consolidation
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * t;

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 200.0 + waste * 1.5;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
    }

    // Small nudge toward larger items in low-residual bins (avoid stranding capacity)
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let mean_r = mean_residual / cap;
    let next = next_item_size as f64 / cap;

    // base: post residual, mildly discounted by progress (later items prefer tighter fills)
    let mut score = pr * (1.0 - 0.3 * progress);

    // smooth polynomial coupling: penalize residual quadratically, scaled by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // reward small post-residual (tight fit) with cubic term
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // lookahead: if next item fits into post residual, reward this placement
    if next > 0.0 && next <= norm_pr {
        score -= 15.0 * (1.0 - (norm_pr - next)) * (0.5 + progress);
    }

    // penalize if post residual is a "dead zone": too small for typical items but nonzero
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr) / 10.0;
    }

    // last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // coupling with mean residual: prefer bins whose residual deviates below mean (tighter bins)
    score += 10.0 * (norm_pr - mean_r) * (0.5 + progress);

    // smooth interaction: item size vs post residual ratio
    let fill_ratio = item / (bin_residual.max(1) as f64);
    score -= 12.0 * fill_ratio * (1.0 - norm_pr);

    // slight penalty for opening new bins late in stream when alternatives exist
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo classes on capacity fractions) ---
    // Residuals divisible by 25 (quarter-capacity classes) are "harmonic" dead space:
    // easy for future items to fill exactly. Penalize non-harmonic residues.
    let quarter = bin_capacity / 4;
    let post_mod = post_residual % quarter;
    let harmonic_penalty = if post_mod == 0 {
        -6.0 // perfectly harmonic residual (0, 25, 50, 75)
    } else {
        // distance to nearest harmonic class scaled up
        let dist = post_mod.min(quarter - post_mod) as f64;
        1.5 * dist
    };
    score += harmonic_penalty;

    // --- Integer division threshold on post_residual ---
    // Small post-residuals (< 10) are dead space: strongly penalize.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 80 {
        // Large post-residual: bin barely used; mild penalty unless it's a fresh bin.
        score += 8.0;
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic pairing: post_residual matches next item exactly.
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                score -= 10.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Next item won't fit here: leftover is more likely dead space.
            score += 6.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        // This is the only bin that can take the item; using it avoids a new bin.
        score -= 25.0;
    }

    // --- Fresh-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are crowded
        // or the item is huge and fits nowhere well.
        let crowded = mean_residual < item_size as f64 * 0.5;
        let huge = item_size >= 3 * bin_capacity / 4;
        if crowded || huge {
            score -= 15.0;
        } else {
            score += 20.0; // prefer filling existing bins
        }
    }

    // --- Prefer bins whose residual is already tight (waste-minimization) ---
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // --- Slight pressure to consolidate as stream progresses ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // mildly awkward gap
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0;
        if slack < 10 && slack > 0 {
            score += 4.0; // but avoid chaining into dead space
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating (favor low post_residual relatively less on new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: only attractive when current fit is bad or bins are few.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        if bad_fit && fitting_bins_count > 1 {
            score -= 25.0; // opening fresh bin beats wasting space
        } else {
            score += 30.0; // prefer filling existing bins by default
        }
        score += mean_residual * 0.1; // existing bins have room -> avoid new bin
    }

    // Mean residual coupling: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * -0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain fill
        } else if post_residual > next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // check if next item also fits current residual (double fill)
        if bin_residual >= item_size + next_item_size {
            score -= 12.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bin early unless existing bins are poor fits
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost + scaled by stream progress
        score += 55.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if fit_ratio > 0.85 {
            score -= 40.0; // item almost fills a fresh bin: good
        }
    }

    // Slight preference to fill older/more crowded bin sets
    score -= 0.15 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong best-fit pressure on residual space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly/roughly into the post-residual,
    // this bin is a great chain target; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Compete harder when many bins fit: reward the emptiest usable one less,
        // rely on post_residual ordering already.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is expensive unless current
    // bins are very full or the item leaves terrible dead space elsewhere.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Opening is bad early and when open bins are still roomy.
        score += 30.0 * (1.0 - progress) + 20.0 * (1.0 - avg_fill);
        // But if no open bin can fit at all, new bin is forced anyway; soften.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream with high mean fill, opening may be fine.
        score -= 10.0 * progress * avg_fill;
    }

    // Prefer bins whose residual deviates favorably from the mean: placing into
    // a bin already below-average residual keeps large residuals concentrated.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Slight preference for bins with larger current residual when item is small
    // (consolidate small items into big leftover space).
    if item_size <= 30 {
        score += 0.05 * (post_residual as f64);
    }

    // Mild open-bin pressure: with many open bins, favor packing tighter overall.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer balanced fills; late, aggressively minimize dead space.
    let w_tight = 0.5 + 3.0 * progress * progress;
    score -= w_tight * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.6;

    // Penalize dead space quadratically, scaled by progress (dead space hurts more later).
    score += (0.2 + 1.4 * progress) * norm_pr * norm_pr * cap;

    // Perfect fit reward (smooth, no piecewise constants).
    score -= 6.0 * (-pr as f64 / 8.0).exp() * (0.5 + progress);

    // Last-chance bin: strong bonus, stronger as stream progresses.
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item, penalize stranding it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item fits in residual: mild reward proportional to tightness
            let slack_after_next = pr - ni;
            score -= 2.0 * (-slack_after_next / 10.0).exp() * (0.3 + progress);
        } else {
            // next item cannot use this residual: penalize wasted space, more later
            score += (0.5 + 1.5 * progress) * (ni - pr).min(40.0) * 0.15;
        }
    }

    // Slight preference to fill existing bins when many are open (fragmentation control).
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: avoid bins far from the mean (outliers create fragmentation).
    score += 0.1 * (pr - mean_residual).abs().min(50.0);

    // New-bin candidate: keep it attractive only when residual is huge and progress is low;
    // otherwise make a fresh empty bin costly so existing bins are preferred.
    if bin_residual == bin_capacity {
        let open_bonus = 1.0 / (1.0 + open_bins_count as f64);
        score = cap * (0.55 - 0.25 * progress) - 10.0 * open_bonus * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "nice" (multiples of 10, esp. small) are less dead.
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if class == 0 {
        score -= 6.0; // divisible by 10: likely reusable
    } else if pr < 10 {
        score += 25.0; // tiny dead space below smallest item
    } else {
        // penalize residuals that few future sizes can use
        score += (class as f64) * 0.4;
    }

    // Fractional capacity usage: how full the bin becomes
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 12.0;

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next size class aligns with residual
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 14.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here afterwards; slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish, penalize slightly so we prefer reuse
    // unless current bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        score = cap * 0.35 + (mean_residual * 0.5);
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0; // fresh bin good for medium next items
        }
    }

    // Late-stream consolidation: favor tight packing as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill;

    // Prefer bins below mean residual (emptier bins for big items)
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // tiny gaps are heavily penalized
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Penalize dead space relative to possible next-item fit (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // residual is reusable by the lookahead item
    }

    // Open-bin pressure: discourage spreading when many bins are already open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progress factor: as stream advances, favor tighter packing (less fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: neutral-ish base so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward an exact match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            score += gap * 0.4;
        }
        // If next item can't fit in the remainder, penalize dead space more.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize residuals too small to ever hold the smallest plausible item (<=10),
    // i.e. effectively dead space.
    if post_residual < 10 {
        score += 25.0 + post_residual as f64;
    }

    // Relative to mean residual: prefer bins whose remainder is below average
    // (consolidate fullness), penalize draining unusually full bins.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no tight fit is available:
        // make the new bin score moderate so tight existing fits win,
        // but poor fits (large post_residual with small items) lose to it.
        score = 35.0;
        // Early in the stream, slightly cheaper to open bins (build pool).
        if total_items > 0 && (step_index as f64) < 0.2 * (total_items as f64) {
            score -= 4.0;
        }
        // If next item is large and this item is small, new bin keeps flexibility.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item_f = item_size as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a small, still-usable residual.
    if bin_residual == bin_capacity {
        let waste_penalty = 20.0 + 0.25 * post_f;
        let large_item_relief = (item_f / cap_f).powi(2) * 30.0;
        score += waste_penalty - large_item_relief;
    }

    // Lookahead: reward leaving room for the next item (k=2 lookahead).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_f <= post_f {
            // Perfect chain: post_residual exactly matches next item is ideal.
            let match_bonus = if (post_f - next_f).abs() < 1.0 { 14.0 } else { 7.0 };
            score -= match_bonus * (1.0 + 0.5 * progress);
        } else {
            // Dead space the next item cannot use.
            score += 0.12 * post_f * (1.0 - 0.3 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * (item_f / cap_f);
    }

    // Tightness reward: bigger items in a bin are better packing.
    score -= 5.0 * (item_f / cap_f);

    // Global residual coupling: prefer bins whose post-residual sits below the
    // mean residual (keeps residual distribution tight and usable).
    score += 0.06 * (post_f - mean_residual);

    // Crowding: with many open bins, prefer consolidating into existing space.
    if open_bins_count > 1 {
        score -= 2.0 * (1.0 - 1.0 / open_bins_count as f64);
    }

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: penalize leftover, but with a smooth non-linear (quartic) coupling
    // so very small dead space is heavily penalized (unusable slivers).
    let mut score = pr * (1.0 + (pr / cap).powi(4) * 6.0);

    // Reward tight fits: subtract proportional to fill ratio, amplified by progress.
    let fill = 1.0 - pr / cap;
    score -= fill * fill * (10.0 + 20.0 * progress);

    // Lookahead: if the next item fits the post residual, reward this bin.
    if nx > 0.0 && nx <= pr {
        score -= 6.0 + 8.0 * (1.0 - (pr - nx) / cap);
    } else if nx > pr && nx > 0.0 {
        // Next item won't fit here; penalize leaving residual that traps it.
        score += 3.0 * (pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Late in the stream, prefer filling existing bins over opening new ones.
    score -= progress * 8.0;

    // Mild penalty when this bin is far below the mean residual (fragmenting spread).
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // Non-linear coupling: residual squared term scaled by open bins pressure.
    score += (pr * pr) / (cap * (1.0 + open_bins_count as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: capacity fractions ---
    // Residuals near capacity fractions are "harmonic" (reusable by common item classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Distance to nearest harmonic fraction of capacity (k/2, k/3, k/4, k/5, k/6).
    let mut harm_dist = cap;
    for d in [2u32, 3, 4, 5, 6] {
        let step = cap / d as f64;
        let k = (pr / step).round();
        let cand = (pr - k * step).abs();
        if cand < harm_dist {
            harm_dist = cand;
        }
    }
    // Reward harmonic residuals (subtract), scaled by how close they are.
    score -= 12.0 * (1.0 - harm_dist / (cap * 0.25)) * (pr / cap);

    // --- Integer-division threshold classes on post_residual ---
    let class = post_residual / 10; // decade class 0..=10
    match class {
        0 => score -= 8.0,          // near-perfect fill
        1 | 2 => score -= 3.0,      // small gap: still very usable for small items
        3 | 4 => {}                 // neutral zone
        5 => score += 4.0,          // awkward half-bin dead space
        6 | 7 => score -= 1.0,      // large-ish gap, moderately reusable
        _ => score -= 2.0,          // big residual, bin stays flexible
    }

    // --- Modulo coupling with next item size (k=2 lookahead) ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits exactly or harmonically into post residual -> strong reward.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 15.0; // perfect two-step packing
            } else {
                // Harmonic if combined slack is a small multiple of a common class.
                let m = slack % 10;
                let bonus = if m == 0 { 10.0 } else if m <= 3 { 6.0 } else { 2.0 };
                score -= bonus * (slack as f64 + 1.0).ln();
            }
        } else {
            // Next item won't fit here: penalize leaving a gap just under next_item_size.
            let gap_deficit = next_item_size - post_residual;
            if gap_deficit <= 10 {
                score += 6.0; // painful near-miss dead space
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0; // strongly prefer using the only bin that fits
    } else if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(4.0); // mild penalty when many alternatives
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, reduced when current open bins are congested
        // or the item is large and current residuals are poor.
        let congested = mean_residual < item_size as f64 * 0.5;
        let late = step_index as f64 / (total_items.max(1) as f64);
        score = cap - 5.0;
        if congested {
            score -= 6.0;
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 8.0 * late.max(0.3);
        }
    } else {
        // Mild preference for tighter bins as stream progresses (best-fit sharpening).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress * (1.0 - pr / cap);
    }

    // Slight tie-break noise-free deterministic nudge using modulo of step and residual.
    if (step_index + post_residual as usize) % 7 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Residuals that cannot fit the lookahead item (k=2) are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // item is large and open bins are few.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 50 { -10.0 } else { 15.0 };
        score += 30.0 + large_item_bonus + (open_bins_count as f64) * 0.5;
    }

    // Favor bins whose residual is close to the mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Lookahead synergy: if the next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills post_residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item leaves only small dead space
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 - slack * 2.0;
        } else {
            score += slack * 0.3;
        }
    }
    // Penalize blocking the next item entirely (item won't fit residual afterwards)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = post_residual as f64;
        score += wasted * 0.8;
    }
    if next_item_size == 0 {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward bins tighter than the mean residual (good consolidation)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count > 0 { 20.0 + 10.0 * (fitting_bins_count as f64).ln().max(0.0) } else { -5.0 };
        score += pressure + 10.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
