pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, smoothed by non-linear shaping
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - pr_norm;
    score -= 18.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = (pr_norm * (1.0 - pr_norm)).max(0.0); // peaks mid-range residual
    score += 6.0 * (1.0 - dead) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let snug = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 14.0 * fits_next * (1.0 - snug) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more early in the stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.2 - progress);
        // but allow new bin if all open bins are nearly full
        score -= (mean_residual / cap).max(0.0) * 8.0;
    }

    // Mild penalty when many bins open and this placement keeps residual fragmented
    let frag = (pr_norm - mean_residual / cap).abs();
    score += 4.0 * frag * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fractions).
    let residual_frac = post_residual as f64 / cap;
    // Penalize residuals that fall into "dead" classes: too small to be useful
    // for typical items (1..100). Dead zone: post_residual < 10 (min item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }
    // Harmonic classes via integer division thresholds on post_residual
    let cls = post_residual / 10; // 0..10 classes
    score += match cls {
        0 => 25.0,          // 0..9 : dead
        1 => 8.0,           // 10..19: only tiny items fit
        2 => 2.0,           // 20..29
        3 => 0.0,           // 30..39 sweet-ish
        4 => -1.0,          // 40..49
        5 => -2.0,          // 50..59 good
        6 => -1.0,
        7 => 0.0,
        8 => 1.0,
        9 => 2.0,
        _ => 3.0,           // nearly full bin: excellent fit, small extra reward
    };

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 60.0;
            } else if slack < 10 {
                score -= 25.0;
            } else {
                score -= (slack as f64).ln() * 4.0;
            }
        } else {
            // next item cannot fit here: mild penalty scaled by how much it overflows
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // open bins have large mean residual (poor fits available) or few bins.
    if bin_residual == bin_capacity {
        // Opening fresh bin baseline: its post_residual is cap - item_size.
        // Discourage opening when there are fitting bins with tight residuals.
        score += 15.0
            + mean_residual * 0.3
            - (open_bins_count as f64) * 1.5
            + (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
    } else {
        // Prefer bins whose residual is close to mean (spread work evenly).
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // Slight preference for tighter fits overall (best-fit core).
    score += residual_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, the minimum item size)
    // are pure waste -> heavy penalty pushing tight fits to the top.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that is just barely above the smallest item:
    // it looks usable but is likely to remain dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent
    // residual capacity exists across open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64 + mean_residual * 0.2;
        // If the next item is large, a fresh bin is somewhat more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Open-bins pressure: prefer placing into existing bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the post-residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If post-residual cannot host the next item but is large-ish, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 3.0;
    }

    // Progression: early in the stream be slightly more willing to open bins
    // (spread), late in the stream consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
