pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize large dead space that can't fit a typical next item.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste * waste;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: prefer zero residual absolutely.
        if post_residual == 0 { score -= 100.0; }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we only open
    // when existing fits are poor; penalty shrinks as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 6.0 * progress;
        // If many open bins already, discourage yet another one.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins more when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (tighter bins), gently steer toward balancing residuals.
    let resid = post_residual as f64;
    score += 0.15 * (resid - mean_residual);

    // Mild time-horizon modulation: early on, be greedy (tight fits);
    // later, allow more exploration of residual balance.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 12.0 * coupling;

    // Reward tight fits more strongly later in the stream (smooth quadratic)
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (2.0 + 4.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth falloff)
    if next_item_size > 0 {
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score += 8.0 * waste * waste;
        // Reward leaving room exactly for next item
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score -= 3.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Prefer bins below mean residual (consolidating space)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 0.6 * tight * (item_size as f64);

    // Penalize dead space: small nonzero post_residual that cannot fit
    // a typical item (min size 1, but useful classes at multiples of 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class logic: bucket post_residual into capacity fractions.
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    let class_penalty = if post_residual == 0 {
        -40.0 // perfect closure
    } else if post_residual <= quarter / 2 {
        -15.0
    } else if post_residual <= quarter {
        0.0
    } else if post_residual <= half {
        8.0
    } else {
        15.0
    };
    score += class_penalty;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for leaving gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer filling bins with large residuals when many bins are open.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to reuse bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (smallest item is 1, but practical dead zone is < 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium gaps: partially penalize, scaled by gap smallness.
        score += (25.0 - post_residual as f64) * 1.2;
    }

    // Reward exact / near-exhausting fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit of the residual by the item (bin fully consumed) gets extra reward.
    if item_size == bin_residual {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item can fit into the post-residual,
    // reward this placement (keeps chains going); otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid waste of nearly-empty bins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making new bins (bin_residual == bin_capacity) less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins and progress.
        score += 20.0 + 4.0 * open_bins_count as f64 + 30.0 * progress;
        // If no open bin fits well (this is the only "fitting" candidate being a new bin),
        // the penalty stands; if other bins fit, they will naturally score lower.
    } else {
        // Existing bin: mild reward for using bins, decreasing with many open bins.
        score -= 2.0 + (open_bins_count as f64).min(10.0);
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers to keep residual distribution tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
