pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual super-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize dead space that the next item cannot use.
            score += 0.35 * post_residual as f64;
        }
        // Perfect pairing: item + next item nearly fills the bin.
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_capacity as f64 - pair).abs() <= 5.0 && bin_residual >= pair {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins.
        let waste = mean_residual * open_bins_count as f64;
        score += 25.0 + 0.05 * waste;
        // Early in stream, new bins are cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If item leaves a large residual in a fresh bin and next item fits it, soften.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // If no open bin fits, new bin is mandatory-ish; reduce penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Prefer bins with residuals close to item size (global state coupling).
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.15 * dev;
        // Late in the stream, be greedier about tight fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress * fit_ratio;
        // Penalize leaving awkward residuals (small unusable gaps).
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Many open bins: discourage spreading items thin.
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening of small residuals.
    let mut score = pr as f64 - 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr / cap;

    // Dead-space penalty: quadratic in normalized post-residual, scaled by stream progress.
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.5 + 0.5 * progress);

    // Cubic coupling: residuals that are awkwardly large get progressively worse.
    score += 25.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Last-chance bonus: strongly favor the single fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space for the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - nxt).abs() / cap);
        score -= 20.0 * fit_next * closeness * closeness;
        // Penalize near-miss: post-residual just below next item size.
        let miss = if pr < nxt { (nxt - pr) / cap } else { 0.0 };
        score += 15.0 * miss * miss * (1.0 - progress);
    }

    // Crowd the mean: prefer bins whose residual deviates below mean residual.
    score += 5.0 * (pr - mean_residual) / cap;

    // Mild pressure to reuse open bins as stream progresses.
    score -= 8.0 * progress * (1.0 - norm_pr);

    // New-bin candidate: make empty bins attractive only when the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    let class = post_residual % 10;
    // "Perfect" harmonic classes: residuals that combine well with common sizes (10,20,...,100).
    let harmonic_bonus = match class {
        0 => -18.0,          // exact multiple of 10: highly reusable
        5 => -6.0,           // half-class: moderately reusable
        1 | 9 => 4.0,        // near-multiple: slightly awkward
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: how many "small" items (<=10) still fit.
    let small_slots = post_residual / 10;
    score -= small_slots as f64 * 3.0;

    // Coupling with lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // harmonic check on the resulting gap
            if gap % 10 == 0 {
                score -= 12.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item cannot use this bin's residual: penalize dead space mildly
            score += post_residual as f64 * 0.15;
        }
    } else {
        // last item: prefer tightest fit, residual value already does this.
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize so it's chosen only when no good fit exists,
    // scaled by how many open bins already exist and stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: penalize bins far above the mean residual (fragmented outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Exact fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size (1)
    // are pure waste; penalize heavily, and even more for mid-size gaps that
    // are unlikely to be filled.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 15.0; // risky small gap
    } else {
        // large residual is fine; mild superlinear growth to prefer tighter fits
        score += (post_residual as f64).powf(1.15) * 0.05;
    }

    // Reward tight packing relative to bin fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already low on average.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 18.0;
        } else if slack < 10 {
            score += 10.0; // next item would leave a sliver
        } else {
            score -= 6.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // late in the stream, opening new bins is wasteful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        // base penalty for opening a new bin
        score += 20.0;
        // but if no open bin fits well (high mean residual spread / many bins), allow it
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if poor_fit && mean_residual > 40.0 {
            score -= 10.0;
        }
        // late in stream, prefer consolidating into open bins
        score += 10.0 * progress;
        // many open bins already: mild extra cost to open another
        score += 0.3 * (open_bins_count as f64).sqrt();
    } else {
        // Prefer bins whose residual is close to item_size (best-fit style)
        let diff = (bin_residual - item_size) as f64;
        score += 0.02 * diff * diff / bin_capacity as f64;
        // Prefer fuller bins (small residual) slightly
        score += 0.05 * (bin_residual as f64 / bin_capacity as f64);
        // Coupling with global mean residual: bins below mean residual are "fuller", favor them
        score += 0.03 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + 2.0 * progress) + prn * (1.0 - progress) * (1.0 - progress);

    let mut score = poly * cap;

    // Reward tight fits smoothly (small post residual), stronger late in stream
    score -= (1.0 - prn) * (1.0 - prn) * cap * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + progress);
        } else {
            score -= 0.25 * progress * (pr - nx).min(nx);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mrn = mean_residual / cap;
    score += 0.1 * open_bins_count as f64 * mrn * progress;

    // New-bin candidate: only attractive when existing residuals are fragmented
    if bin_residual == bin_capacity {
        score += cap * (0.3 + 0.7 * mrn) * (0.5 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes are highly reusable; large leftovers waste space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of leftover

    // Reward tight fits (post_residual near 0 or a perfect harmonic fraction).
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else {
        // Modulo-classes of post_residual: leftovers divisible by common item
        // granularities are more likely to be filled later.
        let gran: [u32; 5] = [10, 20, 25, 50, 5];
        let mut harmony = 0.0;
        for (k, &g) in gran.iter().enumerate() {
            if post_residual % g == 0 {
                harmony += 30.0 - (k as f64) * 4.0;
            }
        }
        score -= harmony;

        // Penalize dead space in the awkward band (just above typical item sizes).
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // tiny sliver is fine, nearly full bin
        } else if post_residual >= 10 && post_residual <= 19 {
            score += 25.0; // dead zone: too small for min item
        }
    }

    // Fractional thresholds on leftover fraction.
    if frac > 0.5 {
        score += 15.0 * frac; // half-empty bins are wasteful targets
    } else if frac < 0.1 {
        score -= 12.0; // compact bins preferred
    }

    // Lookahead coupling: integer-division thresholds on next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward.
            let chain = post_residual / next_item_size.max(1); // how many next items chain
            score -= 20.0 + 10.0 * (chain.min(4) as f64);
            if post_residual == next_item_size {
                score -= 60.0; // exact two-item fill
            }
        } else {
            // Leftover can't fit next item: penalize proportionally to mismatch.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
            // Modulo harmony between leftover and next item granularity
            if next_item_size % 10 == 0 && post_residual % 10 == 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Default penalty so we prefer existing bins; relax when bins are full-ish.
        score += 60.0 - 40.0 * progress - 3.0 * crowding.min(10.0);
        if item_size > 60 {
            score -= 25.0; // large items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can absorb item + next item
        }
    }

    // Mild preference for bins below mean residual (keeps balance, saves big gaps).
    let diff = mean_residual - pr;
    score += 0.15 * diff;

    // Late-stream urgency: squeeze into existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small to ever fit a realistic item (1..100).
    if post_residual > 0 {
        // unusable if smaller than the smallest possible next item (size 1),
        // but practically penalize gaps < 20 as near-dead.
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 3.0;
        } else {
            // smooth decay of usefulness for larger gaps
            score -= (post_residual as f64).ln() * 4.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Exact-fit style reward: post_residual matches next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item fits into post_residual, mild reward; if not, mild penalty
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing bins over new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Its post_residual = capacity - item_size is large, so base score is already
    // high; add extra penalty scaled by how many open bins could fit the item,
    // but relax the penalty if open bins have poor residual structure.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        // if mean residual of open bins is large, opening new bins is wasteful
        score += 25.0 + mean_r * 0.5;
        // but if few fitting bins, allow opening a new bin more readily
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // existing bin with residual far above item: wasteful large-bin use
        let waste = (bin_residual - item_size) as f64;
        if waste > 60.0 {
            score += (waste - 60.0) * 0.4;
        }
        // coupling with mean residual: prefer bins below mean residual (tighter bins)
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization)
    let pr = post_residual as f64;
    score -= 12.0 * (1.0 - pr / bin_capacity as f64).powi(8);
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (pr - next).abs();
        if pr >= next {
            // next item can follow in this bin: reward closeness of match
            score -= 15.0 * (1.0 - gap / bin_capacity as f64).powi(3);
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here; slight penalty scaled by shortfall
            score += 0.15 * gap;
        }
    } else {
        // last item: prefer minimal residual strongly
        score += 0.5 * pr;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin baseline: residual after placement is large; discourage mildly
        score += 20.0 + 10.0 * (1.0 - progress);
        // but if many open bins are fragmented (high mean residual, none tight),
        // opening fresh is preferable to stuffing
        if mean_residual > 45.0 {
            score -= 22.0;
        }
        // if next item is large and current item is small, fresh bin keeps room
        if next_item_size > 60 && item_size <= 40 {
            score -= 12.0;
        }
    }

    // Mild pressure against hoarding many open bins with poor fits
    if open_bins_count > 4 && post_residual > 50 && !is_new_bin {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post_residual becomes dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize creating dead space.
        score += 0.4 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins that deviate from the mean residual (prefer uniform packing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation;

    // Dynamic time horizon: early in the stream, be conservative (prefer filling
    // existing bins tightly); late in the stream, allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 25.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: baseline cost plus scaling bonus.
        score += 15.0 - new_bin_bonus;
        // A new bin is attractive if the item is large relative to capacity.
        score -= 0.2 * item_size as f64;
        // A new bin is attractive if open bins are crowded on average.
        score -= 0.1 * mean_residual;
        // Few fitting bins also favors a new bin.
        score -= 2.0 * fitting_bins_count as f64;
    } else {
        // Existing bins get a mild preference discount that grows with progress.
        score -= 5.0 * progress;
        // Penalize opening pressure on already-crowded fleets.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, keep bins flexible (penalize small post residuals mildly);
    // late in the stream, reward tight packing aggressively.
    let early_weight = (1.0 - progress).powi(2);
    let late_weight = progress.powi(3);

    // Dead-space penalty: quadratic in normalized post residual.
    score += 2.5 * norm_post * norm_post * (1.0 + late_weight * 3.0);

    // Perfect-fit reward: smooth bump near zero post residual.
    let fit_bump = (-norm_post * 8.0).exp();
    score -= 6.0 * fit_bump * (0.4 + 0.6 * progress);

    // Cubic interaction: small residuals late are very costly (wasted capacity).
    score += 4.0 * norm_post.powi(3) * late_weight;

    // Penalize bins that are much worse than the average residual (smooth).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev * open_bins_count as f64 / (open_bins_count as f64 + 2.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: reward leaving room close to the next item's size
    // (smooth Gaussian around the exact match).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64) / cap;
        score -= 5.0 * (-gap * gap * 40.0).exp() * (0.5 + 0.5 * progress);
    }

    // Mild penalty for opening new bins early (smooth in progress).
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (capacity / k)
    let item_class = (bin_capacity / item_size.max(1)) % 8;
    let next_class = if next_item_size > 0 { (bin_capacity / next_item_size.max(1)) % 8 } else { 0 };

    // Reward placements where post_residual matches a harmonic class of the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits after this placement: strong reward
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        // extra reward if post_residual is an exact harmonic multiple of next_item_size
        if post_residual % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit in the dead space left behind: penalize
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Integer-division thresholds on post_residual: small dead space is bad
    let dead_zone = post_residual / 10; // 0..10 buckets
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if dead_zone <= 2 && post_residual > 0 {
        score += 3.0;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive for large items or when open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_residual = mean_residual;
        // penalize new bins mildly; relax if item is big relative to mean residual
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * size_pressure - 10.0 * progress
            - if avg_open_residual < item_size as f64 { 8.0 } else { 0.0 };
    }

    // Harmonic coupling: bins whose residual is close to a capacity fraction fit "classy" items
    let residual_class = (bin_capacity / bin_residual.max(1)) % 8;
    if residual_class == item_class {
        score -= 2.0;
    }

    // Modulo threshold: post_residual in [10,30) is a sweet spot for medium next items
    if post_residual >= 10 && post_residual < 30 && next_item_size >= 10 && next_item_size <= 30 {
        score -= 3.0;
    }

    // Mild preference for filling already-open bins when many are open
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Dead space below the minimum item size is pure waste.
        score += (10.0 - pr) * 12.0;
    } else if pr >= 10.0 && pr < 25.0 {
        // Awkward small gap: partially wasted, penalize proportionally harder.
        score += (25.0 - pr) * 4.0;
    } else if pr >= 25.0 && pr < 50.0 {
        // Moderate gap: mild penalty.
        score += (50.0 - pr) * 1.2;
    }

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open
    // when a fresh bin would consolidate load.
    let pressure = (open_bins_count as f64).powf(1.35) * 1.8;
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 + next_item_size as f64 * 0.15;
    }

    // Mean residual coupling: placing into a bin below mean residual tightens
    // the residual distribution; slightly reward it.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Slight preference to fill older/tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // New-bin candidate (empty bin): give it a baseline so it only wins
    // when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use
        score += (post_residual as f64) * 0.5;
    }

    // Relative to mean residual: prefer bins with residuals below average (tighter packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins fit well (new-bin candidate guard)
    if bin_residual == bin_capacity {
        score += 60.0;
        // But allow new bin if post_residual would be tiny (near-perfect use of fresh bin)
        if item_size >= 90 {
            score -= 200.0;
        }
    }

    // Early in stream: be more liberal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Slight preference for larger bins when many bins are open (consolidation)
    score += open_bins_count as f64 * 0.01 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well. Penalize opening a new bin mildly, more when many bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 22.0 + 0.6 * open_bins_count as f64 + 10.0 * (1.0 - progress);
    }

    // Global state coupling: prefer bins with residual below mean residual
    // (consolidate small leftovers), avoid bins already above mean.
    score += 0.08 * (post_residual as f64 - mean_residual);

    // Mild pressure to fill bins more aggressively as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = norm_post * (1.0 + 0.6 * norm_post * (1.0 - norm_post));

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; dead space is penalized super-linearly
    score += 3.0 * progress * norm_post * norm_post;

    // Reward filling bins tightly relative to current mean residual
    score -= 0.5 * (mean_residual / cap - norm_post).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 2.0 * progress;
    }

    // Lookahead: bonus if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        } else {
            score += 0.5 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * norm_post;

    // New-bin candidate: neutral-ish baseline, only attractive when it beats poor fits
    if bin_residual == bin_capacity {
        score += 0.75 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let pr = post_residual;
    let residue = pr % 10;
    let tier = pr / 10; // 0..10

    // Reward low dead space: subtract for small post_residual
    score -= (10 - tier.min(10)) as f64 * 2.0;

    // Perfect fit reward
    if pr == 0 {
        score -= 50.0;
    } else if residue == 0 {
        // post_residual is a "round" size, likely reusable by future items
        score -= 5.0;
    } else {
        // penalize awkward residues (dead space)
        score += residue as f64 * 0.8;
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // great: bin stays usable for next item
            let slack = pr - next_item_size;
            score -= 8.0 + (10 - slack.min(10)) as f64;
            // harmonic match: next item aligns with residual class
            if (next_item_size % 10) == residue && residue > 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit; penalize more if leftover is small (dead space)
            score += (next_item_size - pr) as f64 * 0.3;
            if pr < 10 {
                score += 12.0; // tiny unusable remainder
            }
        }
    }

    // Last chance: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin when current open bins are fragmented and item is large
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        if item_size > 60 {
            score += 20.0; // large items often better in fresh bin
        }
        if fragmentation < 0.35 && open_bins_count > 2 {
            score += 10.0 * (1.0 - progress);
        } else {
            score += 30.0; // default: prefer reusing open bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room for pairing in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to hold
    // the smallest plausible item (1..100 range) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere else. Base cost plus pressure from many open bins.
    if bin_residual == bin_capacity {
        let mut nb = 25.0;
        nb += open_bins_count as f64;
        // If next item is large and this bin would be nearly full after
        // placement, opening new bin is fine; otherwise discourage.
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > post_residual as f64 {
            nb -= 15.0;
        }
        // Early in stream, opening bins is cheaper (more future freedom).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 20.0 * (1.0 - progress);
        score += nb;
    }

    // Coupling with mean residual: bins far below mean residual have more
    // slack; prefer filling those to consolidate space.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild open-bins pressure: prefer fewer open bins, i.e. filling existing
    // ones rather than spreading out.
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space confirmed by lookahead
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or nearly
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if gap <= 1.0 {
            score -= 60.0; // exact chain fit: strong reward
        } else if post_residual as f64 >= next {
            // next item fits after this one: reward proportional to closeness
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted lookahead potential
            score += 10.0 * (1.0 - (post_residual as f64) / next);
        }
    } else {
        // Last item: just minimize post_residual, already done.
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    // tight bins; penalize dumping into them unless it's a great fit.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= rel * 5.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the fit
    // is poor (large post_residual) or when no open bin chains with the next item.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        let no_chain = next_item_size > 0
            && (post_residual as f64 >= next_item_size as f64);
        if poor_fit || no_chain {
            score -= 40.0;
        } else {
            score += 30.0; // discourage opening new bins for decent fits
        }
    }

    // Mild stream-position adaptation: early on, be more willing to open bins
    // (explore); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize small post-residuals that are still too large to be "dead" but waste space:
    // a post_residual that cannot fit the next item is less useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // bin can still serve the lookahead item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15; // dead space penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
        score += 30.0 - 10.0 * progress - crowd.min(15.0);
        if post_residual < next_item_size && next_item_size > 0 {
            score -= 5.0; // fresh bin accommodates lookahead fully
        }
    }

    // Prefer bins with residual below mean (consolidate fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Slight preference for exact power-of-friendly residuals (multiples of 10)
    if post_residual % 10 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress
    let mut score = pr;

    // Quadratic dead-space penalty: small residuals become progressively worse later in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item), amplified by progress
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 10.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty proportional to open bins count to prefer consolidation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is close to mean (balanced packing)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize slightly so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 8.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction does it fall into?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals that are awkward (small but nonzero) — dead space.
    if post_residual > 0 && post_residual < eighth {
        score += 25.0;
    }

    // Reward residuals in harmonic classes that combine well with typical items.
    let class = post_residual / eighth;
    match class {
        0 => { score += 20.0; }                    // 0..8: dead space
        1 => { score -= 2.0; }                     // 8..25: fits small items
        2 => { score -= 6.0; }                     // 25..50: fits medium items
        3 => { score -= 4.0; }                     // 50..75
        _ => { score -= 1.0; }                     // 75..100: nearly empty
    }

    // Perfect-fit harmonic classes: post residual that is a multiple of 10 or 25.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < eighth {
                score -= 12.0; // near-perfect two-item packing
            } else {
                score -= slack as f64 * 0.1;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it mildly attractive only when current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if pressure < 0.35 || open_bins_count == 0 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 12.0;
        }
    }

    // Discourage spreading across too many bins when mean residual is high.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 2.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, or below
    // the smallest plausible item). A post_residual in (0,10] is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small to fit the lookahead item (dead space w.r.t. future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (enables a chain of tight fits).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open when
    // few bins would suffice; encourages consolidation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mean residual deviation: prefer bins whose residual is close to (or below)
    // the mean, i.e., avoid spreading waste across bins.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.4;
    }

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so consolidation wins unless fits are bad.
        score += 30.0 + open_bins_count as f64 * 0.5;
        // But if all open bins would leave big dead space, new bin is fine.
        if post_residual == bin_capacity - item_size {
            score -= 15.0;
        }
    }

    // Early stream: be more permissive with new bins to build a good pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead-space elimination).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits in the post residual,
    // this bin remains useful; penalize residuals that strand the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly consumes what's left.
            if next_item_size == post_residual {
                score -= 150.0;
            } else {
                // Chain fit bonus scaled by tightness of the chain.
                let chain_tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
                score -= 40.0 + 40.0 * chain_tightness;
            }
        } else {
            // Next item cannot use the leftover: dead space unless post_residual tiny.
            let waste = next_item_size - post_residual;
            score += (waste as f64).sqrt() * 8.0;
        }
    }

    // Compare post_residual against mean residual: keeping residuals homogeneous
    // is good; creating an outlier residual (much smaller than mean) is risky.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (pr - mean_residual).abs();
        if pr < mean_residual {
            // This bin becomes the tightest: it will likely close out soon, fine
            // only if post_residual is small.
            score += deviation * 0.15;
        } else {
            // Creating a much looser bin than average wastes capacity.
            score += deviation * 0.10;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin — reward heavily.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // Prefer filling bins that are already partially committed (larger fill ratio)
    // to consolidate; mild best-fit style pressure.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0;

    // New-bin candidate handling: opening a fresh bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin loses to any reasonable fit...
        score += 45.0;
        // ...but if many open bins are crowded (low mean residual) and this is
        // late in the stream, a new bin may be preferable; relax the penalty.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score -= progress * 10.0;
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 30.0;
        }
    }

    // Slight consolidation pressure: fewer open bins -> prefer reusing them.
    if open_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (waste minimization).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: penalize if leftover space cannot host the next item (dead space),
    // reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 0.6 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (tighter bins) to keep large residuals available for large future items.
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for big items to keep flexibility); later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, but discount when item is large
        // or stream is early (flexibility preserved).
        let mut new_bin_penalty = 12.0;
        new_bin_penalty -= 10.0 * (1.0 - progress);
        new_bin_penalty -= 0.08 * item_size as f64;
        score += new_bin_penalty.max(0.0);
    } else {
        // Late stream: tighten packing more aggressively.
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 + 2.0 * progress) + 3.0 * pr * progress * (1.0 - progress);
    score += 20.0 * poly;

    // Penalize dead space more as stream progresses (bins must be consolidated).
    score += progress * (post_residual as f64).powi(2) / 50.0;

    // Reward tight fits (small post_residual) with smooth exponential bonus.
    score -= 8.0 * (-(post_residual as f64) / 12.0).exp();

    // Last-chance bin bonus (smooth, scaled by how tight the fit is).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.05 * post_residual as f64;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64).max(0.0);
        score -= 10.0 * fits_next * (1.0 - slack).max(0.0) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize slightly, unless existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 12.0 - 15.0 * fragmentation.min(1.0) * (0.3 + 0.7 * progress);
    }

    // Mild penalty for contributing to bin sprawl late in the stream.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create dead-space classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35; // penalize residuals in awkward residue classes

    // Fractional fill of the bin after placement
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * 12.0; // reward tighter packing

    // Perfect / near-perfect fits get strong rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic lookahead: does next item fit into post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // exact chain fit
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            score -= 10.0;
            score += (chain_post % 10) as f64 * 0.25;
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot class
            score += ((next_item_size - post_residual) % 10) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // early in the stream, opening bins is cheaper (exploration)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // if many open bins already, discourage more
        score += open_bins_count as f64 * 1.5;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (post - mean_residual) * 0.05;

    // Integer-division threshold: bins whose residual can host half-capacity chunks
    if post_residual / 25 >= 2 {
        score -= 3.0; // residual keeps flexibility for medium items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    } else if post_residual < 45 {
        score += 4.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to pressure and mean residual waste.
        score += 25.0 + bin_pressure * 3.0 + mean_residual * 0.5;
        // Opening a fresh bin is acceptable when it promises good future use
        // (large item arriving with lookahead that could also fit).
        if next_item_size > 0 && next_item_size <= bin_capacity && (bin_capacity - next_item_size as u32) >= item_size {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward for filling it deeply relative to mean residual.
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        }
        // Favor bins whose residual after placement can still host the lookahead item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 10.0; // blocks the lookahead item -> dead space risk
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // strong bonus when post_residual ~= next_item_size
        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that is too small for anything useful
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: any residual is dead space; prefer tightest fit
        score += 10.0;
    }

    // Reward bins tighter than the mean residual (good fills), penalize loose bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect lookahead chain.
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity
            && (bin_capacity - item_size - next_item_size) < 10 {
            score -= 65.0; // packing a perfect pair into a fresh bin is worthwhile
        }
        // Late in the stream, avoid opening new bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // next item can still use this bin
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation onto existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * pressure;

    // Slightly prefer bins below mean residual (balance load) early; later, prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let diff = bin_residual as f64 - mean_residual;
    score += (1.0 - progress) * 0.05 * diff - progress * 0.05 * diff;

    // New-bin candidate: only attractive when existing fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual == 0 { 0.0 } else { post_residual as f64 / bin_capacity as f64 };
        score += 60.0 - 50.0 * bad_fit;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate large residuals less (waste matters); late: prefer tight fits even more.
    let coupling = norm_pr * norm_pr * (1.0 + progress) * cap;
    score += 0.35 * coupling;

    // Smooth reward for very tight fits, modulated by progress.
    let tightness = 1.0 - norm_pr;
    score -= 0.5 * tightness * tightness * cap * (0.5 + 0.5 * progress);

    // Penalize residual that cannot fit the lookahead item (dead space), smoothly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += 20.0 * gap * (1.0 + progress);
        } else {
            // Reward bins that can still host the next item, quadratically in leftover.
            let after_next = (pr - ni) / cap;
            score -= 8.0 * after_next * (1.0 - after_next);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Mean-residual deviation: prefer bins near the mean to keep balance, smoothly.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity in tenths
    let tenth = bin_capacity as f64 / 10.0;
    let class = (post_residual as f64 / tenth).floor();

    // Penalize dead space classes: residuals that are hard to fill (small, awkward)
    match post_residual {
        0 => score -= 50.0,               // perfect fit is ideal
        1..=9 => score += 40.0,           // tiny unusable slivers
        10..=19 => score += 25.0,         // hard class
        20..=39 => score += 8.0,          // moderate
        40..=59 => score -= 5.0,          // good class (fits half-items)
        60..=79 => score -= 10.0,         // very reusable
        _ => score -= 12.0,               // large residual, very reusable
    }

    // Integer-division threshold: post_residual divisible classes
    if post_residual % 10 == 0 {
        score -= 6.0;                     // round residuals pair well
    }
    if post_residual > 0 && item_size % post_residual == 0 {
        score -= 4.0;                     // exact divisor fit
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // harmonic match: next item leaves a round residual too
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        score += 12.0;                    // next item won't fit here; dead end risk
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin leaves bad class
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 40.0;                // no open bin fits, must open
        }
        // late in stream, opening new bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer tighter bins relative to mean residual
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.15;
    } else {
        score += (resid_f - mean_residual) * 0.10;
    }

    // Mild preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large residuals.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Penalize gaps that are too small to fit typical future items (1..=100 range).
        // A gap <= 10 is essentially dead space; gaps just above common sizes are risky.
        if gap <= 10.0 {
            score += 60.0 * (1.0 - gap / 10.0);
        } else if gap <= 20.0 {
            score += 25.0 * (1.0 - (gap - 10.0) / 10.0);
        }
        // Risk of being unable to fit the next item in this bin's remainder
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 10.0 * (1.0 - tightness.min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open,
    // but allow new bins when few are open (empty-bin candidate has residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 * (open_bins_count as f64).sqrt();
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If the new bin would leave a large residual matching mean residual, slightly favor
        if (post_residual as f64) >= mean_residual {
            score -= 5.0;
        }
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: strongly favor this bin.
            let tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 40.0 + 30.0 * tightness;
        } else {
            // Next item won't fit here: penalize proportional to leftover dead space.
            score += 10.0 + 0.2 * (post_residual as f64);
        }
    }

    // Penalize creating small unusable fragments relative to the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are "fresh" bins;
    // discourage wasting them on small items unless the lookahead fits.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (high fitting pressure) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += 80.0 - pressure - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;

    // Penalize small dead space that becomes unusable: dead space < 10 is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual) especially late in the stream.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0 * (0.5 + t);

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit here, mild penalty so bins that chain well are preferred.
    else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless stream is early or
    // the item is huge and would leave large residual in any open bin.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_capacity - item_size) as f64;
        score += 30.0 * (0.3 + t);
        if item_size >= 60 && waste_elsewhere > 40.0 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If mean residual across open bins is large, new bin is wasteful.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    }

    // Mildly prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: favor low post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate residuals; later, penalize them more strongly
    let progress_coupling = 1.0 + 1.2 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward tight fits smoothly: quadratic bonus for small normalized post-residual
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Dead-space penalty: post-residual too small for plausible future items
    let dead_threshold = 0.1 * cap;
    if pr < dead_threshold && pr > 0.0 {
        score += 6.0 * (1.0 - pr / dead_threshold) * (1.0 - pr / dead_threshold);
    }

    // Lookahead: reward if next item fits the post-residual (chaining)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (1.0 - ni / cap);
        } else {
            score += 2.0 * ((ni - pr) / cap);
        }
    }

    // Mean-residual coupling: prefer bins near the mean residual (smooth quadratic)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild preference to keep bin count low (favor filling existing bins)
    score += 0.05 * (open_bins_count as f64).ln();

    // New-bin candidate: penalize opening a new bin, scaled by stream progress
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps divisible by common item
    // granularity (e.g. multiples of 10) are far more reusable.
    let gap = post_residual;
    if gap == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else {
        let gap_class = match gap {
            g if g % 10 == 0 => 0.0,
            g if g % 5 == 0 => 1.0,
            g if g % 2 == 0 => 2.0,
            _ => 3.0,
        };
        score += gap_class * 6.0;

        // Integer-division threshold: can next item land exactly in the gap?
        if next_item_size > 0 {
            if next_item_size == gap {
                score -= 35.0;
            } else if next_item_size <= gap {
                let q = gap / next_item_size.max(1);
                let r = gap % next_item_size.max(1);
                // reward divisible packing chains, penalize awkward remainders
                score -= (q.min(4) as f64) * 5.0;
                score += (r % 10) as f64 * 1.5;
            } else {
                // next item cannot fit here; gap becomes dead space candidate
                score += 8.0 + (gap as f64 / cap) * 10.0;
            }
        }

        // Penalize tiny unusable slivers relative to smallest plausible item
        if gap < 10 {
            score += 25.0;
        }

        // Capacity-fraction coupling: gap near half capacity is versatile
        let frac = gap as f64 / cap;
        let half_dist = (frac - 0.5).abs();
        score += half_dist * 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are very full/crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (mean_residual.max(1.0) / cap).max(0.1);
        score = cap * 0.55 + crowded * 0.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin guarantees room for lookahead
            score -= 5.0;
        }
    }

    // Mild preference to consolidate into bins tighter than the mean
    score += (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; dead space becomes final
            if post_residual > 0 && post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: penalize slightly so it's chosen only when open bins are bad fits,
    // but allow it when mean residual of open bins is too small for the item.
    if bin_residual == bin_capacity {
        let mean_ok = mean_residual >= item_size as f64 * 0.9;
        if mean_ok {
            score += 45.0; // an open bin likely fits fine; avoid opening new
        } else {
            score += 8.0; // mild preference to open fresh bin
        }
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter).
    score += ((post_residual as f64 - mean_residual) * 0.3).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the post residual: penalize proportionally.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize tiny dead space (<10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New empty bin candidate: only attractive when nothing fits well
    // (large item, no good residual match, or many open bins already fragmented).
    if bin_residual == bin_capacity {
        let stream_frac = step_index as f64 / (total_items.max(1) as f64);
        let mut newbin = 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            newbin -= 15.0;
        }
        if item_size >= 70 {
            newbin -= 10.0;
        }
        if open_bins_count > 4 {
            newbin += 10.0;
        }
        newbin += 10.0 * stream_frac;
        score += newbin;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: larger fraction of residual consumed -> lower score.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Lookahead (k=2): reward bins where the next item also fits,
    // with extra reward for a tight chained fit.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
        } else {
            // Next item won't fit here: penalize proportional to wasted residual
            // unless the leftover is tiny (near-perfect closure is good).
            if post_residual > 10 {
                score += post_residual as f64 * 0.12;
            } else {
                score -= 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Global state coupling: when open bins are collectively full
    // (low mean residual), consolidating into existing bins is valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= mean_residual * (0.05 + 0.15 * progress);

    // Many open bins: mild pressure to fill existing ones rather than scatter.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // existing bins are nearly exhausted (high mean residual) or the item is
    // large and would leave awkward slivers elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0
            - mean_residual * 0.5
            - post_residual as f64 * 0.35
            - (item_size as f64 / bin_capacity as f64) * 20.0
            + (1.0 - progress) * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: penalize large post_residual more as stream progresses.
    let pr = post_residual as f64;
    score += 2.0 * pr * pr / bin_capacity as f64 * (0.5 + progress);

    // Reward tight fits, especially when bins are scarce.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // Penalize opening new bins when plenty of bins are open.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 8.0 + open_f * (0.5 + progress);
    }

    // Dead-space penalty: residual that next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if nx > post_residual as f64 {
            score += 0.6 * (nx - post_residual as f64) * (0.5 + progress);
        } else {
            score -= 3.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating from mean (balance extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10,20,25,50) are more reusable than awkward residues.
    let residue_class_bonus = |r: u32| -> f64 {
        if r == 0 { return 60.0; }            // perfect fit
        if r % 50 == 0 { return 45.0; }
        if r % 25 == 0 { return 35.0; }
        if r % 20 == 0 { return 30.0; }
        if r % 10 == 0 { return 25.0; }
        if r % 5 == 0 { return 15.0; }
        0.0
    };
    score -= residue_class_bonus(post_residual);

    // Dead space penalty: tiny unusable remainders (1..=9) are near-worthless
    // unless next item can use them.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // lookahead rescues the small gap
        } else {
            score += 25.0; // stranded dead space
        }
    }

    // Lookahead coupling: strongly reward exact fit for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // fractional coverage of the next item by the post residual
            let cover = post_residual as f64 / (next_item_size as f64 + 1.0);
            score -= 10.0 * cover.min(1.5);
        } else {
            // next item cannot fit here; penalize proportionally to waste
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // penalize new bin when existing bins are roomy on average
        score += 30.0 + 10.0 * crowded;
        // allow new bin late in stream when large items may still come
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild bonus for tightening an already-small residual (best-fit flavor)
    if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual >= 10 {
        // Perfect fit potential: gap can host the smallest item class.
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would not fit in this bin's post residual, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins when fit is loose.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.4 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins deviating below the mean residual (tighter bins).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit_exists = post_residual == 0 || (next_item_size > 0 && next_item_size == post_residual);
        if tight_fit_exists && fitting_bins_count > 0 {
            score += 50.0; // keep using open bins on perfect fits
        } else {
            score -= 10.0; // fresh bin is reasonable for poor fits
        }
        // Slight penalty for hoarding bins early in the stream.
        score += (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - exact / bin_capacity as f64);
        if exact == 0.0 {
            score -= 30.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize proportionally to leftover dead space
        score += 0.35 * post_residual as f64;
    }

    // Compare post_residual against mean residual: prefer bins tightened toward the mean
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 20.0 - 18.0 * (1.0 - fit_quality);
    }

    // Late in stream: tighten packing, minimize residual harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good, but dead space below the
    // smallest plausible item (~10) is unusable — penalize it extra hard.
    if post_residual < 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 3.0;
    } else {
        score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // current bin's residual would become tiny dead space, or when open bins
    // are already very full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bin penalty grows with mean residual of existing bins (they still
        // have room) and shrinks when existing bins are nearly saturated.
        let mut new_bin_score = 35.0 + mean_residual * 0.4 - avg_fullness * 30.0;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += progress * 20.0;
        // If item is large, a fresh bin is a reasonable home.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        score = score.max(new_bin_score) * 0.5 + score.min(new_bin_score) * 0.5;
        // Blend: new bin competes via its own score.
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    // Mild global pressure: many open bins with slack → prefer filling them
    // rather than spreading.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * 2.0 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins with small post-residual (tight fit).
    let mut score = post;

    // Smooth non-linear polynomial coupling: normalized post-residual squared,
    // weighted by stream progress (dead space matters more later in the stream).
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits: interaction between item size and residual used.
    let fill_ratio = item / cap;
    score -= 20.0 * fill_ratio * (1.0 - post_norm) * (1.0 - progress);

    // Penalize post-residual that cannot fit the next item (wasted space),
    // with smooth coupling to progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * (0.5 + progress);
        } else {
            // Reward leaving room for the next item.
            score -= 4.0 * (post - nxt) / cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - post_norm);
    }

    // New-bin candidate: penalize opening a new bin, more so as the stream progresses,
    // unless the item fits very poorly in existing bins (small item in large residual).
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.75 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (consolidation).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (integer division thresholds) ---
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    // Class 1: tiny dead space (1..=10) -> nearly perfect, strong reward.
    // Class 2: medium (11..=30) -> mild penalty.
    // Class 3: large (31..=60) -> penalty.
    // Class 4: huge (>60) -> bin still very reusable, treat as neutral-ish.
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 30 {
        2
    } else if post_residual <= 60 {
        3
    } else {
        4
    };

    match post_class {
        0 => score -= 200.0,
        1 => score -= 120.0,
        2 => score += 15.0,
        3 => score += 40.0,
        _ => {}
    }

    // --- Modulo-arithmetic harmony: does post_residual land on a "nice" residue class? ---
    // Residues mod 10 that are commonly producible by item sizes (multiples of 5/10)
    // are more likely to be filled by future items.
    let residue = post_residual % 10;
    if residue == 0 {
        score -= 25.0; // exact multiple of 10 -> very fillable
    } else if residue == 5 {
        score -= 12.0; // multiple of 5 -> decent
    } else {
        score += (residue as f64) * 1.5; // awkward residues penalized
    }

    // --- Lookahead coupling: can the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward proportional to tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(40.0);
        } else {
            // Next item cannot use the leftover: penalize dead space more.
            score += 30.0;
        }
        // Harmonic threshold classes on next_item_size (integer division by 20)
        let nxt_class = next_item_size / 20; // 0..5
        match nxt_class {
            0 => score -= 5.0,  // tiny item -> almost anything fits
            1 => score -= 2.0,
            2 => {}
            3 => score += 5.0,
            _ => score += 10.0, // large next item -> prefer roomy bins
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: must beat only genuinely bad fits.
        score = 110.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // large current + large next: fresh bin attractive
        }
        if fitting_bins_count == 0 {
            score -= 150.0; // no alternative: must open
        }
    } else {
        // --- Last-chance bonus: sole fitting bin ---
        if fitting_bins_count == 1 {
            score -= 80.0;
            // But if the fit is terrible and a new bin is cheap relative to
            // stream position, soften the bonus.
            if post_class >= 3 && post_residual > 0 {
                score += 45.0;
            }
        }

        // --- Tightness reward: reward filling a bin snugly ---
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 30.0;

        // --- Prefer using bins with small residuals when they fit (waste-avoidance) ---
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.4;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.2;
        }

        // --- Stream progression: late in the stream, consolidation matters more ---
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0 * (post_class == 0 || post_class == 1) as u8 as f64;

        // --- Mild penalty for spreading across too many open bins ---
        score += (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small residuals are hard to fill later; penalize superlinearly.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // and make opening a new bin less attractive.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item nearly fills this bin perfectly
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 15.0; // dead space that even the next item cannot use
    }

    // Late in the stream, consolidate harder (fewer residual bins left behind).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Prefer bins below mean residual (balancing residuals keeps options open).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * next_item_size as f64;
        } else {
            // dead space penalty relative to next item
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Tightness reward: smaller post_residual relative to capacity
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Penalize bins far from mean residual (prefer typical bins unless last chance)
    if fitting_bins_count > 1 {
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New empty bin: penalize unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + 30.0 * (1.0 - progress)
            - if item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 5.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 20.0 + 10.0 * progress;
        // If mean residual is large, open bins have room; discourage new bin
        nb += (mean_residual / bin_capacity as f64) * 25.0;
        // Many open bins: discourage adding more
        nb += open_bins_count as f64 * 0.5;
        // Except: if this bin is last chance, new bin stays penalized
        score += nb;
    }

    // Mild preference for bins below mean residual (balance the pool)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) are heavily rewarded;
    // early on, we tolerate slack to keep bins flexible.
    let tightness = 1.0 - norm_pr * norm_pr; // high when post_residual small
    score -= tightness * (40.0 + 60.0 * progress * progress);

    // Penalize large dead space more aggressively as stream progresses.
    score += norm_pr * norm_pr * cap * (0.5 + 0.8 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    score += (open_bins_count as f64) * (mean_residual / cap).max(0.0) * 2.0;

    // Slight preference for fuller bins (small post_residual) relative to mean.
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead-space classes: harmonic buckets on post_residual
    let pr = post_residual;
    if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 15.0;
    } else if pr <= 30 {
        score -= 5.0;
    }

    // Modulo class: residual divisible by 10 pairs well with typical item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement
            let next_left = pr - next_item_size;
            score -= 10.0 + (next_left as f64).min(30.0) * 0.4;
            if next_left % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 12.0;
            if pr > 40 {
                score += (pr as f64 - 40.0) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening new bin is good if item is large and no tight fits exist
        if item_size >= 60 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Progress-based coupling: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual.min(50) as f64) * 0.5;

    // Mean residual coupling: if average residual is large, encourage consolidation
    score += (mean_residual - post_residual as f64) * 0.2;

    // Slight penalty per open bin to discourage sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.6 * open_bins_count as f64;

    // If the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item.
        score += 10.0;
    }

    // Compare against mean residual: bins with much less residual than average are tighter fits.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when residuals are fragmented / item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 10.0 || fitting_bins_count == 0 {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0; // exact match: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            score -= 100.0 / diff.max(1.0); // smooth reward for close matches
        } else {
            // next item cannot fit here: penalize wasted residual
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin still has lookahead potential
        }
        score += 0.1 * (open_bins_count as f64);
    }

    // Late in stream: be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize dead space non-linearly: small residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > bin_capacity {
            // next item needs a fresh bin anyway; slight bonus for using this bin now
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: usually undesirable; penalize more as stream progresses
    // and when the item fits reasonably in existing capacity.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mut nb = 25.0 + 20.0 * progress;
        // If item is huge, opening a fresh bin is fine (large items waste less).
        if fit_ratio > 0.6 {
            nb -= 15.0;
        }
        // If existing bins are very full on average, a new bin is more acceptable.
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        if mean_fill > 0.7 {
            nb -= 10.0;
        }
        score += nb;
    }

    // Mild preference for filling fuller bins (low residual) among candidates.
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Slight penalty for proliferating open bins early in the stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, non-linearly
    let mut score = norm_pr * norm_pr * cap + 0.5 * pr;

    // Smooth coupling: dead space matters more as stream progresses
    let coupling = norm_pr * (1.0 + progress * progress * 3.0);
    score += coupling * cap * 0.3;

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 20.0 * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - ((pr - nx) / cap));
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Prefer filling bins when many are open; discourage new bins early
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (mean_residual - pr) * 0.1;

    // Slight bias toward existing bins vs new bin (new bin has pr == cap)
    score -= 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // divisors are more reusable, so reward them (subtract score).
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // Tiny dead space (<=10) is nearly unusable for items >=10 originally,
        // but sizes can be as small as 1; still mildly penalize extremes.
        if pr <= 3 { score += 6.0; }
    } else {
        // Perfect fill: strongly reward.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is ideal for k=2 harmony.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 22.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 10.0;
        } else if next_item_size > pr {
            // Next item won't fit here anyway; slight penalty for wasting
            // a large residual that could have held the next item better.
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.15 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: penalize opening a fresh bin when decent open
    // bins exist, unless the stream is early and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        score += 25.0 + 40.0 * (1.0 - progress) * (1.0 - crowding);
        // Late in the stream with fragmented bins, opening new bins is ok.
        if progress > 0.8 && mean_residual < 30.0 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (tighter bins first),
    // keeping larger residuals for future larger items.
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
