    };

    let after = post_residual as f64;
    let next = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score;

    // Exact closure is strongly preferred: no dead space is created.
    if post_residual == 0 {
        score = -18.0 - 8.0 * progress;
    } else {
        score = after;

        if next_item_size > 0 {
            if after >= next {
                // This bin can also absorb the lookahead item; favor low two-step leftover.
                score = after - next - (3.0 + 5.0 * progress);
            } else {
                // The lookahead item cannot follow us here.
                score += 5.0 + 5.0 * progress;

                let new_bin_can_chain = item_size <= bin_capacity.saturating_sub(next_item_size);
                if new_bin_can_chain {
                    let new_left = bin_capacity
                        .saturating_sub(item_size)
                        .saturating_sub(next_item_size) as f64;

                    if after > new_left {
                        // Strict dead-space pressure: using this open bin would leave a worse
                        // remnant than letting current + next share a fresh bin.
                        let mut dead_penalty =
                            5.0 + 0.35 * (after - new_left) + 4.0 * progress;

                        // Extra pressure for very small positive remnants.
                        if after < 8.0 {
                            dead_penalty += 0.25 * (8.0 - after);
                        }

                        score += dead_penalty;
                    } else {
                        // Opening a new bin would not improve the two-step residual.
                        score += 0.5;
                    }
                }
            }
        }
    }

    let mean_frac = if cap_f > 0.0 && mean_residual.is_finite() {
        (mean_residual / cap_f).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let next_likely_fits_elsewhere = next_item_size > 0 && mean_residual >= next;

    if is_new_bin {
        if fitting_bins_count > 0 {
            let mut new_bin_pressure = 6.0
                + 0.45 * open_bins_count as f64
                + 1.20 * (fitting_bins_count as f64).min(10.0)
                + 6.0 * progress
                + 4.0 * mean_frac;

            if next_likely_fits_elsewhere {
                new_bin_pressure += 6.0;
            }

            if next_item_size == 0 {
                new_bin_pressure += 10.0;
            }

            score += new_bin_pressure;
        }
    } else if fitting_bins_count == 1 {
        // Last existing bin that can take the item: avoid opening a new bin unless
        // the dead-space penalty is genuinely large.
        score -= 5.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless residual is tight.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty for small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // bonus if next item then leaves a small residual too
            let second_residual = post_residual as u32 - next_item_size;
            if second_residual < 10 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize tight residuals that exclude it
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare residual to mean residual: prefer bins with below-average residual
    // (tighter bins), keeping loose bins for future items.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Early in stream, keep bins looser for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers are wasteful
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * ratio * (1.0 - ratio); // peaks when next item nearly fills leftover
        } else if post_residual > 0 {
            score += 10.0; // leftover won't serve next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // prefer existing bins unless they fit badly
            score += 55.0
                + (mean_residual - post_residual as f64).abs() * 0.5
                - (open_bins_count as f64 * 2.0);
        } else {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    // Many open bins with high mean residual: encourage consolidation into laggards
    if bin_residual < bin_capacity {
        let gap = bin_residual as f64 - mean_residual;
        score += gap * 0.6; // prefer bins tighter than average (consolidation)
    }

    // Time horizon: late in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    } else {
        score -= progress * 12.0;
    }

    // Mild penalty for very large open-bin count (fragmentation control)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling: post_residual vs stream progress
    let p_norm = post / cap;
    score += 18.0 * p_norm * p_norm * (1.0 + progress);
    score -= 12.0 * p_norm * (1.0 - progress) * (1.0 - progress);

    // Tight fit reward, amplified as stream progresses
    let tight = 1.0 - p_norm;
    score -= 10.0 * tight * tight * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 6.0 * (1.0 - ((post - nx) / cap));
        } else {
            score += 4.0 * (1.0 - post / nx);
        }
    }

    // Penalize divergence from mean residual (keep residuals balanced)
    score += 0.05 * (post - mean_residual).abs();

    // Mild pressure against spreading across many bins
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: make it moderately unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are "clean"
    // multiples of common item-size classes (mod 10), which future items can fill.
    let class = post_residual % 10;
    score -= match class {
        0 => 12.0,   // perfectly divisible residual, highly reusable
        5 => 6.0,    // half-class residual
        2 | 8 => 3.0,
        _ => 0.0,
    };

    // Integer-division thresholds: residual bands by quarter capacity.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 8.0; // dead space penalty: bin nearly sealed
    } else if post_residual <= 2 * quarter {
        score -= 2.0;
    } else if post_residual <= 3 * quarter {
        score -= 5.0; // sweet spot: half-to-three-quarter full
    } else {
        score -= 1.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fill
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= (gap <= 10) as i32 as f64 * 10.0; // near-perfect follow-up
            score += gap as f64 * 0.05; // small penalty for larger gaps
        } else {
            score += 4.0; // next item cannot follow here
        }
        // Harmonic compatibility: next item divisible into post residual classes
        if post_residual > 0 && (post_residual % next_item_size.max(1)) == 0 && next_item_size > 0 {
            score -= 6.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin only attractive when the item
    // is huge relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        score = 30.0 + pressure * 40.0 - (fitting_bins_count as f64) * 3.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Mild stream-phase modulation: late in the stream, be tighter.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * phase;

    // Tie-break toward consolidating open bins.
    score += (open_bins_count as f64) * 0.01 + (bin_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item
    // (items >= 1, but realistically small gaps < ~20 are hard to reuse).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Sharp penalty for tiny unusable gaps, decaying as gap becomes reusable.
        if gap < 20.0 {
            score += (20.0 - gap) * 3.0;
        } else {
            score += 5.0 / gap; // mild penalty for any leftover
        }
    }

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Fractional fill quality: tighter fill favored.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the gap: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate gets residual == capacity, so penalize it via count).
    if bin_residual == bin_capacity {
        // New bin candidate: base cost of a fresh bin plus count pressure.
        score += 45.0 + (open_bins_count as f64) * 4.0;
        // But allow new bin if existing bins would leave terrible dead space.
        if post_residual == bin_capacity && item_size <= 25 {
            score -= 20.0;
        }
    } else {
        // Slight preference for fuller bins when many bins are open.
        score += mean_residual * 0.05 - (bin_residual as f64) * 0.05;
    }

    // Late-stream consolidation: near the end, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover dead space after both placements
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - two_step_waste as f64;
        } else {
            // next item cannot use the remaining space: penalize tight leftovers
            let slack = (next_item_size - post_residual) as f64;
            score += slack * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space) relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Reward filling bins that are already below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if next item is large and current residuals are small, new bin is fine
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 90.0;
        }
    }

    // Late in stream: slightly favor compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative
    // to remaining stream or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let desperation = avg_fullness * (0.5 + 0.5 * progress);
        // Base penalty keeps new bins closed when decent fits exist.
        score += 55.0;
        // Relax penalty when open bins are crowded and stream is advanced.
        score -= 45.0 * desperation;
        // Very large items may justify fresh space early.
        if item_size >= 70 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Mild preference for filling fuller bins among many open bins.
    score -= (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 8.0;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early on, prefer tight fits less aggressively (keep bins flexible);
    // late in the stream, strongly prefer minimizing dead space.
    let mut score = pr * (1.0 + 2.0 * progress * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's post
    // residual, heavily reward this placement.
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving a residual too small for the next item (dead space).
        if (next_item_size as f64) > pr {
            score += 15.0 * ((next_item_size as f64 - pr) / cap);
        }
    }

    // Spread penalty: avoid bins far from the mean residual, scaled by openness.
    let dev = (pr - mean_residual).abs();
    score += 5.0 * (dev / cap) * (1.0 - 1.0 / (open_bins_count.max(1) as f64));

    // Mild penalty for opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue classes
    // mod 10 and by integer division thresholds (capacity quarters).
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward near-perfect fits: post_residual in low harmonic class (0..=10)
    if post <= 10 {
        score -= 40.0;
    } else if post <= 20 {
        score -= 15.0;
    } else if post <= 30 {
        score -= 5.0;
    }

    // Penalize dead space in the "awkward" class: post_residual that is too small
    // for typical items (min item assumed ~10) but nonzero -> wasted.
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 pair well
    // with typical item sizes (10..80 multiples of 10 class).
    let m = post % 10;
    if m == 0 {
        score -= 8.0; // aligned class: future items can slot in exactly
    } else {
        score += (m as f64) * 1.5; // misaligned residual is harder to fill
    }

    // Integer division thresholds: which harmonic band does post_residual fall in?
    if post > half {
        score -= 10.0; // still roomy bin, flexible
    } else if post > quarter {
        score += 3.0;
    } else if post > 0 {
        score += 12.0; // cramped bin, likely dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 50.0;
        } else if next_item_size < post {
            let leftover = post - next_item_size;
            if leftover <= 10 {
                score -= 25.0;
            } else {
                score += (leftover as f64) * 0.3;
            }
        } else {
            // next item cannot follow in this bin: penalize slightly more for
            // small post residual that blocks the lookahead item
            score += 6.0 + (next_item_size.saturating_sub(post) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // poor fits or the stream is early with room to consolidate.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins lose against decent fits.
        score += 55.0;
        // More open bins with high mean residual -> opening new bin is worse.
        score += open_bins_count as f64 * 2.0;
        // Early in stream, or mean residual low (open bins nearly full): new bin ok.
        score -= (1.0 - progress) * 20.0;
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size >= half {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Small tie-breaker on exactness of fill fraction.
    let fill_frac = (bin_capacity - post) as f64 / bin_capacity as f64;
    score -= fill_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is a tiny bit larger than the next item (near-miss trap).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Prefer bins with residual close to the item (tight fit) beyond raw post_residual.
    score += (bin_residual as f64 - item_size as f64 - post_residual as f64).abs() * 0.01;

    // Mean residual coupling: if this bin is far below mean residual, it's a poor fit candidate.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // New empty bin candidate: penalize mildly so it only wins when fits are bad,
    // but allow it when open bins are numerous and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin pairs well with a large follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large dead space.
        score += 0.5 * (post_residual as f64 - next_item_size as f64).abs().min(bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins that are already well-filled.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if next item is large and this item leaves a big gap, opening a new bin
        // keeps flexibility: reduce penalty.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Late in the stream: tighten packing further (avoid wasted space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good, but dead space
    // below the minimum item size (1) is pure waste. Penalize awkward gaps.
    let waste = post_residual as f64;
    score += waste * waste * 0.02; // superlinear penalty on unusable space

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item exactly fills the remaining space,
    // this bin becomes a perfect two-item chain — heavily reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mildly good, scaled by how much slack remains
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 - (slack_after_next as f64) * 0.15;
        } else {
            // next item cannot use this bin's remnant: penalize large remnants
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than
    // spreading; add pressure proportional to open bins when the fit is loose.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio) * 3.0;

    // Time horizon: early in the stream, be more conservative (keep bins
    // flexible); late in the stream, accept tight fits aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * fit_ratio;

    // Global residual state: if mean residual across bins is high, we have
    // slack overall — prefer the best local fit (low post_residual) even more.
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when the item fits poorly everywhere else. Give it a mild
    // baseline penalty so existing bins with decent fits win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large relative to capacity, opening a fresh bin
        // is often wise to avoid fragmentation.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, normalized and polynomially warped
    let mut score = x * (1.0 + 0.8 * x * x);

    // Non-linear coupling of post_residual with stream progress:
    // early: prefer tight fills (low post_residual); late: tolerate slack less
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * x * x;

    // Interaction: post_residual * progress (smooth cubic coupling)
    score += 0.6 * x * t * (1.0 - t) * 4.0;

    // Penalize post_residual close to next item size mismatch (smooth)
    if next_item_size > 0 {
        let n = next_item_size as f64 / cap;
        let diff = (x - n).abs();
        score += 0.4 * diff * diff * (1.0 - x);
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * x;

    // Mean residual deviation coupling
    score += 0.2 * (mean_residual - pr as f64).abs() / cap;

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * t;
    }

    // Reward near-perfect fits smoothly
    score -= 2.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space bands (integer division thresholds).
    if post_residual <= bin_capacity / 20 {
        score -= 40.0; // <=5% waste: excellent
    } else if post_residual <= bin_capacity / 10 {
        score -= 20.0; // <=10% waste
    } else if post_residual > bin_capacity / 2 {
        score += 15.0; // more than half empty: wasteful placement
    }

    // Modulo arithmetic on post_residual: residuals that match common item sizes
    // (multiples of 5) are more reusable.
    let mod5 = post_residual % 5;
    if mod5 == 0 {
        score -= 8.0;
    } else if mod5 == 1 {
        score += 3.0;
    } else {
        score += 2.0 * mod5 as f64;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0; // next item fills bin perfectly
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score -= (gap as f64).min(30.0) * 0.3;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: post_residual is potential dead space
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last chance: strongly favor using the only bin that fits (avoid new bin).
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open bins.
    if bin_residual == bin_capacity {
        // Prefer new bin only if item is large relative to mean residual (poor fits everywhere)
        let waste_if_open = mean_residual * open_bins_count as f64 * 0.05;
        score = cap - item_size as f64 + waste_if_open;
        if fitting_bins_count == 1 {
            score += 100.0; // never open when exactly one bin fits
        }
        if post_residual == 0 {
            score -= 500.0; // opening for a perfect-fit item is fine
        }
    }

    // Slight preference for fuller bins over time.
    score += (step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64 - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: bonus if the post residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        // Residual that blocks the next item while still being "usable" size.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: when many bins are open, discourage new-bin creation
    // and prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 30.0 + 10.0 * pressure + 20.0 * progress;
    } else {
        // Existing bin: slight reward scaled by pressure.
        score -= 5.0 * pressure;
    }

    // Prefer bins with residual close to the item (tight fits) relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect 2-step match:
    // post_residual exactly equals the next item size -> chain two items perfectly.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 4.0;
        } else {
            // penalize dead space that neither the next item nor anything small can use
            let dead = if post_residual < next_item_size { 0.0 } else { (post_residual - next_item_size) as f64 };
            score += dead * 0.4;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving more leftover than average wastes capacity.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // future perfect fit that no open bin provides.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 1e-9 {
            score -= 70.0;
        }
    }

    // Late in the stream, tighten packing: minimize leftover aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving medium dead space.
        score += 8.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: opening a bin is acceptable only when the fit here is poor
    // or the stream is early (room for future consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64); // = item/C
        // Opening early is cheap; opening late is expensive unless fit is very tight.
        let open_cost = 30.0 + 50.0 * progress;
        let open_benefit = 40.0 * (1.0 - fit_quality);
        score += open_cost - open_benefit;
    }

    // Mild preference for consolidating into fewer bins as bin count grows.
    score += 0.5 * open_bins_count as f64;

    // Slight time pressure: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with quadratic sharpening (dead space penalty)
    let mut score = norm_pr + 2.5 * norm_pr * norm_pr;

    // Cubic coupling with stream progress: dead space matters more late in the stream
    score += 4.0 * norm_pr.powi(3) * (0.3 + 0.7 * progress);

    // Interaction: large item filling a bin tightly is good (reward small post residual relative to item)
    score -= 0.8 * (it / cap) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Scarcity pressure: few fitting bins -> favor existing bins over opening new ones
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 1.5 * scarcity * (1.0 - norm_pr);

    // Lookahead: reward if next item can fit into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 1.2 * snug * (0.5 + 0.5 * progress);
        } else {
            // post residual too small for next item: penalize proportionally to wasted space
            score += 0.6 * (pr / cap) * (nx / cap);
        }
    }

    // Mean residual deviation: prefer bins whose residual is close to (or below) mean, avoiding fragmenting outlier bins
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev.abs();

    // Mild new-bin penalty that decays with progress (early stream: opening bins is cheaper)
    if bin_residual == bin_capacity {
        score += 0.9 * (1.0 - 0.6 * progress);
    }

    // Dampen proliferation of open bins mid-stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (eighths)
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // 1..8
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 8 + bin_capacity - 1) / bin_capacity };

    // Perfect fit: zero post residual is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: post residual too small for any item (min size 1... but
    // practically items >= ~10); penalize unusable slivers modulo class logic
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic pairing: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // chainability reward, stronger when classes are complementary
        score -= 12.0;
        let pair_sum = item_size + next_item_size;
        if pair_sum % 100 == 0 {
            score -= 30.0; // exact pair fill
        } else if pair_sum > 70 {
            score -= 8.0; // dense pair
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't chain here; mild penalty scaled by leftover waste
        score += (post_residual as f64) * 0.15;
    }

    // Class-complement bonus: bin residual class matches complement of item class
    let resid_class = (bin_residual * 8 + bin_capacity - 1) / bin_capacity;
    if resid_class == item_class {
        score -= 6.0; // item occupies roughly half the bin -> good split potential
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
        // unless it creates dead space
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Prefer fullest bins (low residual) when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or when open bins are collectively full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a new bin late in the stream with many bins open and full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if avg_fill > 0.75 {
            score -= 25.0 * avg_fill;
        }
        // big items relative to capacity justify fresh bins early
        if item_class >= 6 {
            score -= 10.0 * (1.0 - progress);
        }
        // avoid opening bins for tiny items
        if item_class <= 2 {
            score += 15.0;
        }
        // lookahead: if next item is large, a fresh bin is useful
        if next_class >= 6 {
            score -= 8.0;
        }
    }

    // Small tie-breaker toward bins whose post_residual is a "nice" harmonic class
    let pr_class = (post_residual * 8 + bin_capacity - 1) / bin_capacity;
    score -= (8 - pr_class) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap is almost certainly dead space
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0; // risky gap: only small items can use it
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0; // leftover too small for next item -> dead space risk
    }

    // New-bin candidate: prefer reusing bins unless residual is very fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
    }

    // Prefer placing into bins with below-average residual (tighter bins first).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but reward exact/waste-free fits more.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item fits; penalize leftover after the hypothetical next placement (dead space).
            let chain_residual = post_residual - next_item_size;
            score -= 20.0 - (chain_residual as f64) * 0.5;
        } else {
            // next item won't fit here; penalize bins that strand the next item.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" — placing here
    // consolidates space; bins far above mean are wasteful to fill only partially.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 25.0;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are already open (fragmentation).
        score += 15.0 + open_bins_count as f64 * 1.5;
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // But if the item is large and mean residual is small, a new bin may be the only clean fit.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 25.0;
        }
    }

    // Mild penalty for filling large residual with a tiny item (wasted capacity).
    if (item_size as u64) * 4 < (bin_residual as u64) && bin_residual != bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.86;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer low post-residual (tight fit), scaled non-linearly.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Quadratic penalty on large dead space (unusable残 capacity).
    let waste_frac = post / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Smooth coupling: as stream progresses, tighten preference for tight fits.
    score *= 1.0 + 0.8 * progress * (1.0 - waste_frac);

    // Perfect-fit reward (smooth, no hard cutoff).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score -= 50.0 * (-post as f64 / 8.0).exp();
    }

    // Lookahead: bonus if residual can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize mildly, more so early when consolidation matters,
    // less so if existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post).abs();
        score += 20.0 - 10.0 * progress + 0.1 * mean_gap;
    }

    // Slight penalty for residual far from mean residual (keeps bin pool homogeneous).
    score += 0.05 * ((post - mean_residual) * (post - mean_residual)) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (0..=10) are near-perfectly packed; reward them hard.
    let residual_class = post_residual % 25; // 4 harmonic classes: 0,1,2,3 mod 25
    let near_full = (post_residual <= 10) as f64;
    score -= 60.0 * near_full;

    // Reward post-residuals that pair well with typical small items (10..=30):
    // leftover in [10, 30] is reusable, leftover in (30, 60) is dead-ish space.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 15.0;
    } else if post_residual > 30 && post_residual <= 60 {
        score += 12.0 * (1.0 - (post_residual as f64 - 30.0) / 30.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this bin becomes a perfect pair — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize bins whose leftover is "almost"
            // fitting the next item (wasted potential), scaled by stream progress.
            let overflow = (next_item_size - post_residual) as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += overflow * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (huge post residual).
    if fitting_bins_count == 1 {
        score -= 25.0 - (post_residual as f64).min(25.0);
    }

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline penalty so a decent fit in an existing bin wins.
        score += 20.0;
        // But if no open bin fits at all (fitting_bins_count==0 handled by caller
        // calling only this candidate) or mean residual is tiny, opening is fine.
        if fitting_bins_count <= 1 && mean_residual < 15.0 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean-residual coupling: when open bins are collectively tight, squeeze
    // more out of them (penalize leaving large leftovers elsewhere).
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Harmonic class tiebreaker: prefer residuals that are multiples of 5 or 10
    // (more likely to match future integer item sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    let _ = residual_class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap zone: 1..=10).
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host typical future items.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: bonus if post_residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score += 15.0; // would create dead space after next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferating bins, but only mildly so
    // tight fits still win.
    score += 2.5 * open_bins_count as f64;

    // Slight preference for bins with larger residual (keep small gaps closed).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: prefer opening a new bin only if all open bins
    // would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Mild stream-progression tightening: as the stream advances, waste
    // matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.05;

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here later; mild reward proportional to how well it matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * over;
        }
    }

    // Compare residual against mean: prefer bins with below-mean residual (tighter bins).
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; the lookahead bonuses above can override.
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin always fits the next item too
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold the smallest
    // plausible item (size 1) is fine, but small unusable gaps are wasted.
    if post_residual > 0 {
        // Fragility: how likely is this leftover to be filled by the next item?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item can use the leftover: reward chaining.
                let chain_tight = (post_residual as f64 - next_item_size as f64).abs();
                score -= 25.0 / (1.0 + chain_tight);
            } else {
                // Next item cannot fit into the leftover: penalize.
                score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it unattractive unless the item
        // is large and no good fit exists among open bins.
        score += 30.0 + 0.3 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is actually good
        // (avoids fragmenting small leftovers elsewhere? no—fresh bin is the
        // natural home for big items): soften the penalty.
        if item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
        // If the item leaves a residual matching the next item exactly, a new
        // bin pairs them nicely.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system — prefer consolidating into existing bins
    // (penalize new bins implicitly via post_residual baseline already).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);

    // Late in the stream, waste matters more: amplify post_residual penalty.
    score += (post_residual as f64) * 0.5 * progress;

    // Prefer bins whose residual is close to item size (best-fit flavor,
    // scaled): smaller residual => tighter bin.
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);
    // Smooth coupling with stream progress: later in stream, penalize large residuals more
    score += 30.0 * progress * norm_pr * norm_pr;
    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);
    // Penalize bins whose residual deviates from mean residual (fragmentation)
    score += 0.3 * (mean_residual - pr).abs();
    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }
    // Lookahead: if next item fits in post residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 5.0 * (fits / cap);
        let miss = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += 0.2 * miss;
    }
    // Mild pressure against opening too many bins
    score += 0.5 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that form "clean" fractions of the
    // capacity (multiples of 10 / 25) are more reusable, reward them.
    let pr = post_residual;
    let clean = if pr == 0 { 3.0 }
        else if pr % 25 == 0 { 2.0 }
        else if pr % 10 == 0 { 1.0 }
        else { 0.0 };
    score -= clean * 6.0;

    // Integer-division threshold: classify post_residual into harmonic bands
    // (0..12, 12..25, 25..50, 50..100). Small leftovers are dead space; penalize.
    let band = pr / 12;
    let band_penalty = match band {
        0 => 18.0,             // tiny unusable sliver
        1 => 9.0,              // small
        2 => 3.0,              // medium
        _ => -2.0,             // large, very reusable
    };
    score += band_penalty;

    // Perfect fit is king.
    if pr == 0 {
        score -= 40.0;
    }

    // Coupling with the lookahead item: if the next item fits exactly into the
    // post-residual (harmonic match), strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let nxt_pr = post_residual - next_item_size;
            if nxt_pr % 10 == 0 || nxt_pr % 25 == 0 {
                score -= 10.0;
            }
            // modulo-class resonance between item and next item
            if item_size % 10 == next_item_size % 10 && item_size > next_item_size {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover would be stranded.
            let stranded = next_item_size - post_residual;
            score += (stranded as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item).
    // Only allow it when the item would leave a huge unusable sliver elsewhere,
    // i.e., when no open bin gives a good harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to item size (bigger item
        // means less waste in the fresh bin).
        score += 15.0 + 0.3 * (bin_capacity - item_size) as f64;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        // If the mean residual across open bins is large and the item is small,
        // an open bin likely suffices: penalize the new bin more.
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += 15.0 * progress;
        // If next item is huge and this item is small, saving residual space
        // in existing bins may pay off: soften new-bin penalty.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 18.0;
        }
    } else {
        // Reward placing into bins whose residual is close to the item
        // (tight fit), measured via harmonic distance.
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.2;
        // Prefer bins with below-average residual (fill the fullest bins first
        // keeps the pool of large residuals available).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Progress-based tie-breaking: early in the stream, keep residuals flexible
    // (penalize large consumption of big residuals); late, just pack tight.
    let progress = step_index as f64 / total_items as f64;
    if pr > 50 && progress < 0.5 {
        score += 5.0 * (1.0 - progress);
    }

    // Small deterministic tie-breaker to avoid oscillation between equal bins.
    score += ((bin_residual as usize).wrapping_mul(31)
        .wrapping_add(step_index)) % 7 as usize as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is excellent.
        score -= 60.0;
    } else {
        // Larger leftover space is somewhat reusable; mild reward.
        score -= 5.0;
    }

    // Tight fit bonus: reward placements that use most of the residual space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when
    // existing residuals are small relative to the item, or the item is huge.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 15.0 && post_residual >= 20 {
            score -= 35.0; // existing bins too fragmented; fresh bin better
        } else {
            score += 50.0; // discourage wasting a fresh bin
        }
        if item_size >= 80 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a mid-size orphan gap mildly.
        score += 3.0;
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward exact chain fit (item + next item fills bin).
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        if chain == 0 {
            score -= 60.0; // perfect two-item fill
        } else if chain > 0 && chain < 10 {
            score += 15.0; // leaves tiny dead space after next item
        } else if chain < 0 {
            // next item won't fit here after current placement
            score += (-(chain) as f64) * 0.3;
        } else {
            // post_residual still comfortably fits next item: mild reward
            score -= 8.0;
        }
        // Reward if next item fits exactly into current residual (item placed first elsewhere? no: residual now)
        if next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // relative to residual (poor fit elsewhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        let waste = bin_residual - item_size;
        let poor_fit = (item_size as f64) < 0.55 * (bin_residual as f64);
        score = waste as f64;
        if fitting_bins_count <= 1 || !poor_fit {
            score += 40.0; // prefer existing bins when fit is acceptable
        }
        if item_size >= 70 {
            score -= 10.0; // big items keep new bins useful
        }
        // late in stream, prefer closing out open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < 10 {
            score -= 15.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit in the post residual, mild penalty for wasting lookahead room.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 25.0 };
        score += pressure;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Few open bins relative to remaining items: opening new bins is fine early.
        if open_bins_count < 3 {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer bins with residual below mean (tighter bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Spread usage: with many open bins, prefer reusing existing ones.
    if open_bins_count > 5 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let base = pr_norm.powf(1.5 + 1.5 * progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = 0.6 * pr_norm * (1.0 - pr_norm) * (progress - 0.5) * 2.0;

    // Dead-space penalty: residual too small to likely fit future items
    let dead = if pr > 0.0 {
        let nxt = next_item_size as f64;
        if nxt > 0.0 {
            let gap = (nxt - pr).max(0.0) / cap;
            0.8 * gap * gap * (1.0 - progress)
        } else {
            0.0
        }
    } else {
        -0.5 // perfect fill reward
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 {
        -1.2 * (1.0 - pr_norm)
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins
    let spread = 0.02 * open_bins_count as f64 * pr_norm;

    // Mean residual deviation term (favor bins near mean to keep balance)
    let dev = 0.15 * ((pr - mean_residual) / cap).powi(2);

    base + coupling + dead + last_chance + spread + dev
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10, 25, 50
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    let class50 = (pr % 50) as f64;
    // Penalize residues that leave awkward slivers
    score += 0.8 * class10 + 0.6 * class25 + 0.5 * class50;

    // Integer-division thresholds: post_residual bucketed by size class
    let bucket = pr / 10; // 0..10
    match bucket {
        0 => score += 12.0,   // tiny dead space, nearly unusable
        1 => score += 6.0,
        2 => score += 2.0,
        3 | 4 => score -= 1.5, // sweet spot for mid-size items
        5 | 6 => score -= 2.5,
        _ => score -= 1.0,     // large residual, still flexible
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let diff = (pr - next_item_size) as f64;
            // Reward if next item leaves a clean harmonic residue too
            let next_res = pr - next_item_size;
            let harm = ((next_res % 10 == 0) as i32 * 4 + (next_res % 25 == 0) as i32 * 3 + (next_res % 50 == 0) as i32 * 2) as f64;
            score -= 3.0 + harm - 0.15 * diff;
        } else {
            // Next item won't fit here; penalize less if residual is still generally useful
            score += 4.0 + 0.05 * ((pr as f64) - cap * 0.1);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open bins are bad
    if bin_residual == bin_capacity {
        // Fresh bin baseline: attractive late in stream or when mean residual is fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.35 * cap + 0.3 * mean_residual - 6.0 * progress - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open
    score -= 0.15 * open_bins_count as f64;

    // Fraction-of-capacity coupling on tightness of fit
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac * (1.0 - fill_frac); // reward balanced fills

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps strongly (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item could use the post residual, reward it.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 8.0;
        } else if post_residual > 0 && (post_residual as f64) < nr {
            score += 5.0;
        }
    }

    // Mild phase pressure: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 5.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual stays near mean.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space, amplified for tiny dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // near-perfect fit bonus
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += diff * 1.2; // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 45.0; // exact two-item chain
        } else if post_residual > next_item_size {
            score -= 12.0; // next item still fits after this placement
        } else {
            score += 15.0; // next item won't fit here; dead space risk
        }
        // Penalize leaving residual smaller than the smallest plausible item
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: maximize fill aggressively
        score -= post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (mean_residual + 1.0);
        score += 55.0 - fragmentation * 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin can host the pair
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Slight stream-progression pressure: later in stream, waste less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.4 + 0.6 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize exact fills slightly less: zero post_residual is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it enables a much better future fit.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 55.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) {
            // next item can't fit residual anyway; new bin slightly more attractive
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 30.0;
        score += new_bin_penalty;
    }

    // Lookahead coupling: reward if post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a residual just below the next item (wasted dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Prefer bins with residual below mean (consolidate large gaps elsewhere).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference for fewer open bins when many are open.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.8 * progress) - 0.6 * norm_post * norm_post * (1.0 + progress);
    score += 2.0 * poly;

    // Reward tight fits more strongly as stream progresses (smooth quadratic in progress)
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit typical future items (smooth in post_residual)
    let dead = (post - 10.0).max(0.0) / cap;
    score += 3.0 * dead * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // Lookahead: favor bins whose post-residual still fits the next item
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 2.5 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 1.5 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: discourage unless current bin would leave very small residual
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" residue classes (still usable for big items) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward tight fits: post_residual near 0 is excellent (dead space minimized).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    } else if post_residual <= 40 {
        score -= 20.0;
    } else {
        // Large leftover: penalize unless it aligns with a "harmonic" class
        // that is likely reusable (multiples of 25 / 50).
        let harmonic = post_residual % 25 == 0 || post_residual % 50 == 0;
        if harmonic {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = next_item_size == post_residual;
        let near = (post_residual - next_item_size) <= 5;
        if exact {
            score -= 500.0;
        } else if near {
            score -= 150.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty, worse
        // if post_residual is a stranded small class.
        if post_residual < 10 {
            score += 60.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post residual with small fraction).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer filling bins with low residual relative to the mean (balance load).
    score -= (mean_residual - frac * 100.0) * 0.05;

    // Late in the stream, prefer tighter fits even more (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (cap - post) * 0.1;

    // New-bin candidate: empty bin has full residual; make it moderately
    // unattractive so we prefer reusing open bins with good fits,
    // but attractive when the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size as f64 > mean_residual {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Prefer bins whose residual tightly matches the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Pressure from number of open bins: favor filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0; // dead space for the known next item
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 35.0 / (1.0 + gap);

        // Perfect chain: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving residual that the next item cannot use at all.
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins that absorb slack
    // (residual above mean) rather than the already-lean bins.
    if (post_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit. Penalize it mildly by default; the
    // empty-bin call has post_residual == bin_capacity, so its raw score is
    // already high, and the lookahead bonus only applies if the whole next
    // stream could use a full bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight relief when the next item is large (new bin useful soon).
            score -= (next_item_size as f64) * 0.15;
        }
        // Late in the stream, discourage opening bins with little payoff.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward but scale by how well next item uses leftover space.
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 20.0 * next_fit;
        } else {
            // Next item cannot use this residual; penalize large wasted leftovers.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / (bin_capacity as f64);
        // If mean residual across open bins is large, prefer existing bins -> penalize new bin.
        score += 15.0 + 50.0 * crowding;
        // Early in the stream, opening bins is cheap-ish; later, reuse is precious.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If no bins exist yet, allow it.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across too many open bins relative to progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count as f64 > (progress * (total_items as f64) * 0.5 + 1.0) {
        score += 2.0;
    }

    // Slight preference for bins whose residual deviates favorably from mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 0.35 * pr_norm * pr_norm * (1.0 + t);
    score -= 0.25 * pr_norm * pr_norm * pr_norm * (1.0 - t);
    score += 0.15 * pr_norm * (t * t);

    // Penalize dead space that cannot fit the next item (smooth quadratic coupling)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 0.9 * gap * gap * (1.0 + 0.5 * t);
    }
    // Reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 0.4 * tight * tight;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - pr_norm) * (1.0 + t);
    }

    // Mild pressure toward consolidation as open bins grow
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Prefer bins tighter than average (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals that are "almost full" (tiny dead space) less,
    // and mid-range wasted space more, via integer-division classes.
    let cls = post_residual / 10; // class 0..=10
    match cls {
        0 => score -= 6.0,          // near-perfect fill
        1 | 2 => score -= 3.0,      // good fill
        3 | 4 => {}                 // neutral
        5 | 6 => score += 4.0,      // half-empty: risky
        7 | 8 => score += 8.0,
        _ => score += 14.0,         // mostly empty bin being consumed
    }

    // Modulo arithmetic: residuals congruent to small multiples of common
    // item sizes (10, 20, 25, 50) are more likely to be filled later.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 2.5;
    } else if mod10 <= 3 {
        score += 1.5; // awkward sliver
    }

    // Coupling with lookahead item (k=2): reward exact / compatible fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 6.0;
            } else if slack <= 25 {
                score -= 2.0;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            // next item won't fit here: bin becomes a dead-end candidate
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive if all open bins fit poorly
    // or the item is huge relative to open residuals.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        let mean_fit = mean_residual / cap;
        if fitting_bins_count == 0 || pressure > 0.8 {
            score -= 25.0;
        } else {
            // discourage opening a new bin when decent fits exist
            score += 15.0 + mean_fit * 10.0;
        }
    }

    // Late-stream consolidation: favor tight fits as stream nears completion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * (1.0 + progress * 2.0);

    // Mild penalty for fragmenting many open bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    let dead_threshold: u32 = 9; // smallest conceivable item size is 1, but tiny gaps are hard to fill
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) but could have fit larger things.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many bins open, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += pressure * 2.0;

    // New-bin candidate handling: only attractive when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, mitigated by how bad the best existing fit would be.
        let waste_here = post_residual as f64; // = capacity - item_size for the empty bin
        score = 55.0 + waste_here * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere; must open
        }
    } else {
        // Slight penalty when this bin's post-residual deviates far from mean residual
        // (prefer balanced residual profiles across open bins).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Mild stream-progression bias: later in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (waste-free placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // If next item fits into post residual at all, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
    }
    // If next item does NOT fit in post residual, penalize proportionally
    // (dead space the next item can't use), scaled by lookahead size.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize residuals too small to ever hold a meaningful future item
    // (dead space relative to capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins whose residual was already below-average before placement
    // (tight-packing: fill the emptiest usable bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and no good fit exists. Base penalty for opening new bins.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Large items leave little residual anyway; allow new bins for them.
        if item_size >= bin_capacity / 2 {
            score -= 150.0;
        }
        // Late in the stream, opening fresh bins is less harmful.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 100.0 * progress;
        }
        // If many bins are open, prefer consolidating into existing ones.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild reward for leaving post residual near common item sizes
    // (multiples of 10 are likely arrivals), improving future fit odds.
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64)
        } else {
            post_residual < 20
        };
        if dead {
            score += 12.0 + (post_residual as f64) * 0.15;
        } else {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        let fit_waste = (bin_residual - item_size) as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let poor_fit = (fit_waste / bin_capacity as f64) > 0.5;
        if poor_fit {
            score -= 6.0 * pressure;
        } else {
            score += 20.0 * (1.0 - pressure);
        }
    }

    // Global state: many open bins with high mean residual -> favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.05 * mean_residual * (0.5 + 0.5 * progress);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mild time-horizon shaping: early stream -> tighter packing emphasis.
    score -= 8.0 * tightness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += norm_pr * norm_pr * (40.0 + 60.0 * t) * (1.0 - norm_pr);

    // Reward tight fits, stronger later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 30.0 * t);

    // Penalize wasted residual relative to mean residual of open bins
    score += (pr - mean_residual).abs() * (0.15 + 0.25 * t);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 35.0 * t;
    }

    // Lookahead coupling: reward leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + t);
        } else {
            score += 8.0 * t;
        }
    }

    // Mild penalty for proliferating open bins early in the stream
    score += (open_bins_count as f64) * 0.5 * (1.0 - t);

    // New-bin candidate: make it unattractive unless residual is hopeless
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets (integer division)
    let item_class = item_size / 20;              // 0..=5
    let next_class = next_item_size / 20;         // 0..=5 (0 if lookahead absent)

    // Reward tight fits: post_residual small relative to capacity
    let tight = (post_residual as f64) / cap;
    score -= (1.0 - tight) * 20.0;

    // Penalize dead space that cannot fit even the smallest plausible next item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic coupling: if next item's class matches what this bin could host after placement
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly here -> strong reward scaled by how snugly
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 + 10.0 * snug;
    } else if next_item_size > 0 {
        // next item would NOT fit here -> penalize leaving a bin that strands the lookahead
        let waste = (post_residual as f64) / cap;
        score += 8.0 * waste;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 are "clean" splits
    let r = post_residual % 10;
    if r == 0 {
        score -= 5.0;
    } else if r >= 7 {
        score += 2.0;
    }

    // Fractional capacity logic: prefer bins whose post_residual is a small fraction of capacity
    if post_residual <= bin_capacity / 4 {
        score -= 6.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current bins are poor fits
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // baseline for a fresh bin: modest penalty, reduced when many bins already open & fragmented
        let fragmentation = if open_bins_count > 0 { (mean_residual / cap).clamp(0.0, 1.0) } else { 0.0 };
        score = 40.0 + 30.0 * fragmentation;
        // late in stream, avoid opening bins unnecessarily
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // if the next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open
    score += (open_bins_count as f64) * 0.05;

    // Mean-residual coupling: bins far below mean residual are more valuable to fill
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Small class-based nudge: big items prefer emptier bins
    if item_class >= 3 {
        score += (bin_residual as f64) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward residuals that can still host a future item (>=10), scaled by leftover size.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit and post_residual is small, penalize creating a trap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few bins, opening new is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate: only attractive when this bin would otherwise be a bad host
    // (i.e., residual is large but item leaves a large gap) or when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline neutral score for a fresh bin.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count > 3 {
            score += 5.0 * open_bins_count as f64;
        }
    }

    // Slight preference for bins with below-average residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize proportionally to leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to mean residual across open bins
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.6 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny dead space (waste) with a non-linear kick
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = 55.0 - 40.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.2 * next_item_size as f64;
        }
    }

    // Late-stream pressure: favor consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in the stream, be frugal with dead space;
    // late in the stream, closing bins tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * (0.5 + progress);

    // Lookahead: if the next item fits exactly or well into post_residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        let chain_quality = 1.0 - (chain_waste as f64 / bin_capacity as f64);
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize, scaled by how
        // dead it is relative to the smallest plausible item.
        let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 3.0 * (dead / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (huge post_residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0));
    }

    // New-bin candidate (empty bin): penalize opening a new bin when decent
    // alternatives exist; the penalty relaxes when many bins are open or the
    // mean residual is low (bins are nearly full anyway).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let mut penalty = 20.0 - 4.0 * openness - 15.0 * mean_tightness;
        // If the item is large relative to capacity, opening a fresh bin is safer.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            penalty -= 6.0;
        }
        // If the next item is large too, a fresh bin can host the pair better.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            penalty -= 4.0;
        }
        score += penalty.max(2.0);
    }

    // Mild penalty for leaving residuals that no typical item (>=1) can use,
    // i.e., tiny slivers, but only when other bins exist to absorb load.
    if post_residual > 0 && post_residual < 10 && open_bins_count > 1 {
        score += 4.0;
    }

    // Slight preference to balance load across bins: bins with residual far
    // below mean are "special" — using them is fine; bins far above mean should
    // be drained first.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
