    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit).
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, waste matters less (bins may still be filled later); late, waste is costly.
    let prn = pr / cap; // normalized residual 0..1
    let coupling = progress * (prn * prn) * cap * 0.6
                 + (1.0 - progress) * (prn * prn * prn) * cap * 0.4;
    score += coupling;

    // Reward excellent fits with a smooth (1 - prn)^2 kernel scaled by item size.
    let tightness = (1.0 - prn) * (1.0 - prn);
    score -= tightness * item * 0.8;

    // Penalize residuals that are too small to be useful later (dead space),
    // using a smooth sigmoid-like ramp around the smallest plausible item.
    let dead = 1.0 / (1.0 + (-(pr - 12.0) / 6.0).exp());
    score += dead * 25.0;

    // Lookahead: if next item fits the post-residual, reward this bin strongly (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let k = 1.0 - gap / cap;
            score -= k * k * nxt * 0.9;
        } else {
            // Next item won't fit here: mildly penalize leaving a large unusable gap.
            let g = (-gap) / cap;
            score += g * g * cap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    } else {
        // More competing bins -> slight penalty to keep bin count low.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual awareness: bins far below mean residual are less attractive
    // (save "loose" bins for awkward items); smooth quadratic divergence.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // with progress (late in the stream, prefer opening fresh bins over bad fits).
    if bin_residual == bin_capacity {
        score = cap + 40.0 - 25.0 * progress
              + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // If item perfectly fills a fresh bin, that's actually great.
        if pr == 0 { score -= 60.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: capacity fractions (1/2, 1/3, 1/4 of capacity)
    let cap = bin_capacity as f64;
    let half = cap / 2.0;
    let third = cap / 3.0;
    let quarter = cap / 4.0;

    // Reward near-exact fits: post_residual close to 0 is great
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown,
    // but small leftovers under ~10 are likely dead). Modulo-class the waste.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0; // tiny unusable slivers
    }

    // Integer-division thresholds on post_residual: waste that still fits half/third classes
    let pr = post_residual as f64;
    if pr > half {
        score -= 15.0; // bin still roomy after placement -> flexible
    } else if pr > third {
        score += 5.0; // mid-class residual, mildly wasteful
    } else if pr > quarter {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: leftover becomes dead space for the lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current residual is bad
    if bin_residual == bin_capacity {
        // opening a new bin costs one bin; only attractive when best existing residual is poor
        let pressure = (mean_residual - pr).max(0.0);
        score += 120.0 - pressure * 0.5;
        // if the item is large relative to capacity, opening fresh is more acceptable
        if item_size as f64 > half {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins)
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += t * 40.0;
        } else {
            score -= t * 10.0;
        }
    }

    // Many open bins: encourage filling existing ones rather than spreading
    score += open_bins_count as f64 * 0.5;
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.4;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100),
    // but practically we treat gaps < 25 as hard to reuse.
    if post_residual > 0 && post_residual < 25 {
        score += 60.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling: dead space penalty amplified when many bins are open (pressure to consolidate).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if post_residual > 0 && post_residual < 25 {
        score += 15.0 * pressure;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item does NOT fit post residual, mild penalty for wasting the lookahead slot.
    else if next_item_size > 0 && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading into new bins when few remain to place,
    // mild bonus for using already-open bins generally.
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New bin candidate: penalize unless current bins are quite full.
        score += 10.0 + 5.0 * pressure * (mean_residual / bin_capacity as f64);
    }

    // Progress: as stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: item + next item fill the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        score += 25.0 + waste_if_open * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small dead space is nearly unusable given min item size 1..100; mild penalty
        // to prefer either exact fills or leaving usable gaps.
        score += 6.0;
    }

    // Lookahead: reward if the next item can fit into the post residual (chaining).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post residual too small for next item: penalize proportionally to wasted space.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // New bins are penalized more when there are many open bins with slack,
        // and less early in the stream (exploration allowed early).
        score += 30.0 * pressure + 20.0 * (open_bins_count as f64).ln().max(0.0) / 3.0;
        score -= 15.0 * (1.0 - progress);
        // If item is large relative to typical residual, new bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild global slack coupling: prefer bins below mean residual (consolidate slack).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more; early, flexibility matters.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr * pr / cap * (0.25 + 1.25 * p2 + 0.75 * p3);
    score += coupling;

    // Reward high fill ratio smoothly (quartic saturation)
    let fr = fit_ratio.min(1.0);
    score -= 30.0 * fr * fr * fr * fr;

    // Penalize leaving residual that next item could use (synergy term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let synergy = (1.0 - gap / cap).max(0.0);
        score -= 8.0 * synergy * synergy * (1.0 - p2);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - p3);
    }

    // Smooth penalty when this bin is much emptier than average (scatter avoidance)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // Mild preference for consolidating into fewer bins
    score += 0.5 * (open_bins_count as f64).ln() * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is a small fraction of capacity.
    let fill_frac = 1.0 - post_residual as f64 / cap_f;
    score -= fill_frac.powi(3) * 40.0;

    // Lookahead coupling (k=2): reward if the next item can also fit in the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact class match: leftover exactly equals next item -> perfect chaining
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                score -= 12.0;
            }
        } else {
            // penalize leftover that strands the next item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Harmonic class logic: modulo-10 residue classes of post_residual.
    // Small nonzero residues (e.g. 1..9) are near-dead space for typical item classes.
    let r = post_residual % 10;
    if r > 0 {
        score += (r as f64) * 0.4;
    }
    // Integer-division thresholds: leftover in the awkward 11..19 band is often unusable.
    let q = post_residual / 20;
    if q == 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance urgency: if this is the only bin that can fit the item, prefer it strongly.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin recognized by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Default penalty: reusing open bins is usually better.
        score += 30.0 + mean_residual * 0.25;
        // If no open bin can fit the item, opening a new bin is mandatory/desirable.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 10.0;
        }
    }

    // Fragmentation guard: leftover below a quarter capacity is likely dead space
    // unless it exactly matches the next item (already rewarded above).
    if post_residual < bin_capacity / 4 && post_residual > 0 && post_residual != next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: small gaps (< 10) are unusable under the
    // classic regime; treat them as fully wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit bonus: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit bonus: reward leaving a gap small relative to the item.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 8.0 * tightness;

    // Penalize wasting a large residual on a tiny item (bad ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += 30.0 * (1.0 - fill_ratio).powi(2);

    // Open-bin pressure: discourage spreading across many bins when the
    // current bin's residual is still healthy.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give the empty bin a baseline penalty that
    // tight-fit placements can overcome.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item is large relative to capacity, opening fresh is
        // safer (avoids stranding big items later).
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Late in the stream, avoid opening bins that will end mostly empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // reserving this bin's leftover for it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If the next item would not fit the post-residual and is large, opening
    // a fresh bin now is less costly.
    if next_item_size > post_residual && next_item_size as f64 > 0.5 * bin_capacity as f64 && bin_residual != bin_capacity {
        score += 12.0;
    }

    // Mean-residual coupling: when the fleet average residual is already
    // large, be pickier about accepting loose fits.
    score += 0.15 * mean_residual * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end up (nearly) full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Two-step lookahead: if the next item exactly fills the post_residual,
    // this bin is a perfect 2-item match.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild bonus scaled by how well it uses leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item won't fit here: penalize dead space that is too small
            // to be useful for typical items.
            if post_residual < 10 {
                score += 150.0 * (10.0 - post_residual as f64);
            }
        }
    }

    // Relative-to-mean residual coupling: prefer bins with residuals below the
    // mean (tighter bins get closed out first).
    score -= (mean_residual - post_residual as f64) * 3.0;

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        score += pressure + 0.5 * open_bins_count as f64;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used to modulate risk appetite over time.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness preference: reward near-perfect fits super-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how well the next item will use the leftover space.
            let next_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - next_waste as f64 / cap);
        } else {
            // Next item cannot use the leftover: mild penalty scaled by leftover size.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Congestion term: when many bins are open, prefer consolidating into existing bins.
    let open_f = open_bins_count as f64;
    score += 0.15 * open_f * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual is far below the mean (it's already
    // fragmented), slightly penalize; if it's above mean, it's a good consolidation target.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.10 * dev;

    // New-bin candidate handling: an empty bin gets a baseline premium so we only open
    // a new bin when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base premium for opening a new bin.
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more room to consolidate later).
        score -= 10.0 * (1.0 - progress);
        // If many bins are open already, discourage spreading further.
        score += 0.5 * open_f;
        // If no existing bin can fit the item, this call is forced anyway; soften premium.
        if fitting_bins_count == 0 {
            score -= 18.0;
        }
        // Large items leave big residuals in a fresh bin; that residual is flexible, reward.
        score -= 0.05 * item_size as f64;
    }

    // Late-stream tightening: as the stream ends, avoid creating fresh residual capacity
    // that will never be used.
    score += 10.0 * progress * (post_residual as f64 / cap);

    // Small deterministic tie-breaker to avoid oscillation between equal candidates.
    score += 0.01 * ((bin_residual as f64 * 7.0 + item_size as f64 * 13.0) % 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear shaping (favor tight fits, penalize mid residuals)
    let mut score = pr - 18.0 * (1.0 - norm_pr) * norm_pr * cap;

    // Polynomial coupling with stream progress: tighter packing valued more later
    let tightness = 1.0 - norm_pr;
    score -= (14.0 + 22.0 * progress * progress) * tightness * tightness;

    // Smooth penalty on residual relative to next item lookahead
    if next_item_size > 0 {
        let fit_next = (pr >= next_item_size as f64) as f64;
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * fit_next * (1.0 - gap / cap);
        score += 6.0 * (1.0 - fit_next) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild regularization toward mean residual state
    score += 0.08 * (pr - mean_residual).abs();

    // Slight preference to fill existing bins over opening new ones
    score += 0.5 * (bin_residual as f64 - pr) * 0.0; // no-op guard
    score += 4.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity fractions (quarters of C=100).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let residual_class: u32 = if post_residual == 0 {
        0 // perfect fit — best possible outcome
    } else if post_residual < quarter {
        1 // small dead space, mostly unusable
    } else if post_residual < half {
        2 // medium leftover
    } else if post_residual < 3 * quarter {
        3 // large leftover, still useful
    } else {
        4 // nearly empty bin
    };

    // Reward tight fits: subtract bonuses proportional to class quality.
    match residual_class {
        0 => score -= 60.0,
        1 => score += 8.0,   // penalize tiny dead space (hard to fill)
        2 => score -= 5.0,
        3 => score -= 12.0,
        _ => score -= 20.0,
    }

    // Modulo arithmetic on post_residual: leftovers divisible by small
    // harmonic steps (10, 20, 25) are more likely to be exactly filled
    // by future items drawn from typical size lattices.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // guaranteed perfect follow-up fit
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; dead space becomes stranded longer.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual < quarter {
            score -= 10.0; // even a cramped fit is worth it
        }
    }

    // New-bin candidate handling: prefer keeping a fresh empty bin only
    // when no open bin offers a decent fit. A brand-new bin has large
    // residual; make it mildly unattractive so good fits win, but its
    // high base score already handles that. Add slight pressure against
    // bin proliferation when many bins are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    // Stream progression: early on, be more willing to spread items
    // (future flexibility); late, consolidate tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score *= 1.0 + 0.1 * progress;

    // Mean residual coupling: when open bins are generally slack,
    // prioritize filling the emptiest-feeling bins (deviation term).
    let dev = post_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // likely dead space for items >= 10... but items can be 1..100
        if (post_residual as f64) < mean_residual * 0.5 {
            score += 10.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize when this bin's residual barely fits the item (fragile fit).
    let slack = bin_residual - item_size;
    if slack > 0 && (slack as u64) < (item_size as u64) / 4 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0; // chain of tight fits
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space relative to lookahead
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score -= (open_bins_count as f64).sqrt() * 3.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and no existing bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > 80 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins that are already heavily loaded.
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= load_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: penalize wasted residual quadratically.
    let waste = post_residual as f64;
    score += 0.15 * waste * waste / bin_capacity as f64;

    // Exact-fit bonus: residual zero is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Small dead space that likely can never be reused (min item size 10 in classic case).
        score -= 10.0;
    }

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits here afterwards: good chaining, reward proportional to tightness.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: mild penalty scaled by overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.2 * overshoot;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end near the mean
    // (balanced packing) unless lookahead says otherwise.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // existing fits are poor (large post_residual elsewhere) or many items remain.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins are opened only when justified.
        score += 30.0;
        // Late in the stream, prefer consolidating into open bins more strongly.
        score += 20.0 * progress;
        // If the current item is large and would leave a big hole in any open bin,
        // a fresh bin is relatively better.
        score -= 0.1 * item_size as f64;
        // If lookahead item is large too, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins that are already quite full
    // (keeps open bin count low).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness;

    // Tie-breaker noise-free deterministic coupling with stream position.
    score += 0.001 * (step_index as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * 10.0;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty scaled by wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: fill as tightly as possible.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // fits are poor. Penalize the fresh bin mildly, more when many bins are open
    // with slack, less late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let slack_pressure = (mean_residual / bin_capacity as f64).min(1.0);
        score += 20.0 + 30.0 * slack_pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
    }

    // Fragmentation pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 3.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) nonlinearly.
    let gap = (bin_residual - item_size) as f64;
    score += (gap / bin_capacity as f64).powi(3) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, smoothed with non-linear terms
    let mut score = pr_norm * 100.0;

    // Non-linear coupling: residual^2 scaled by stream progress.
    // Late in the stream, dead space matters more (less time to fill it).
    score += 40.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Cubic damping: very large residuals are less bad than tiny ones
    // (a big residual can still host future items).
    score -= 15.0 * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (post_residual near zero) with a smooth trough
    let tight = (pr_norm - 0.05).abs();
    score -= 25.0 * (-tight * tight * 40.0).exp();

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let fit_bonus = (-gap * gap / 200.0).exp();
        score -= 20.0 * fit_bonus;
    } else {
        // Last item: minimize residual as hard as possible
        score += 30.0 * pr_norm;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately attractive only when existing
    // bins would leave large residuals and mean residual is low.
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - 10.0 * (mean_residual / cap);
        // discourage opening new bins if a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Mild penalty for proliferating open bins, smoothed
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a "reusable"
    // residue class (divisible by small item sizes) are more valuable.
    let pr = post_residual;
    let capacity = bin_capacity as f64;

    // Reward post_residuals that are exactly 0 (perfect fit) heavily.
    if pr == 0 {
        score -= 50.0;
    }

    // Harmonic divisibility bonus: leftover divisible by common small sizes
    // (10..=25) is reusable by many future items.
    let mut harmonic_bonus = 0.0;
    for d in [10u32, 20, 25, 50] {
        if pr > 0 && pr % d == 0 {
            harmonic_bonus += 1.0;
        }
    }
    score -= harmonic_bonus * 3.0;

    // Penalize small dead space (1..=9): nearly unusable.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Penalize leftovers in (50, 60) range: too big to waste, too small to fit
    // a mid item comfortably... actually reward 50..=90 usable windows.
    if pr >= 50 && pr < 100 {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to how much
            // of next item is wasted by choosing this bin.
            score += (next_item_size as f64 - pr as f64).max(0.0) * 0.2;
        }
        // Harmonic class match: post_residual mod next_item_size small => near-perfect chain
        if next_item_size <= pr {
            let m = pr % next_item_size;
            score -= (next_item_size as f64 - m as f64) * 0.1;
        }
    }

    // Fraction of capacity used by this placement: reward tight fills.
    let fill_ratio = item_size as f64 / capacity;
    score -= fill_ratio * 5.0;

    // Prefer filling already-open bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    // New-bin candidate guard: empty bin gets mild baseline penalty so it's
    // chosen only when open bins score worse.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But late in the stream with high mean residual, opening fresh is fine.
        score -= mean_residual * 0.05 * progress;
    }

    // Tie-break toward bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are "dead".
    // Items are 1..100, so treat residuals < 5 as fully dead (nothing fits later realistically).
    let dead_threshold: f64 = 5.0;
    let pr = post_residual as f64;
    if pr < dead_threshold {
        // Perfectly packed bin: strongly reward.
        score -= 60.0;
    } else {
        // Penalize residuals that are dead relative to typical item granularity.
        // If no plausible future item fits (post_residual < next_item_size and small), penalize.
        if pr < next_item_size as f64 {
            // Dead for the immediate next item: penalize proportionally to how dead it is,
            // scaled by stream progress (late in stream, waste matters more).
            let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 25.0 * (1.0 - pr / 100.0) * (0.5 + progress);
        }
        // Nonlinear coupling: penalize small-but-not-dead gaps that fall below common item sizes.
        if pr < 20.0 && pr >= dead_threshold {
            score += 12.0 * (1.0 - pr / 20.0);
        }
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 30.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0 * (fill_ratio - 0.7) / 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate and spread-out placements).
    let bin_pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so with more open bins and early in stream.
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + bin_pressure * (1.0 - progress * 0.5);
    } else {
        // Favor bins whose residual is close to the mean residual (balanced packing),
        // penalize outliers slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead synergy: if the next item exactly fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: tiny post residual is very desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item (>=1) could use anyway is moot,
    // but penalize post_residual too small to fit anything useful relative to lookahead.
    let lookahead = next_item_size as f64;
    if lookahead > 0.0 {
        // Two-step lookahead: prefer bins whose post_residual matches next item.
        if post_residual as f64 == lookahead {
            score -= 120.0;
        } else if post_residual as f64 >= lookahead {
            // residual large enough to host next item: good chaining
            let gap = post_residual as f64 - lookahead;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to waste
            let waste = lookahead - post_residual as f64;
            score += 0.8 * waste;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // unattractive unless no open bin fits well. Penalize opening new bins when
    // open bins exist and can fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_penalty = 150.0 + 100.0 * progress + 20.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if next item is huge and this item is small, keeping residual large
        // in an open bin may be fine; still keep new bin penalized.
    }

    // Early stream: slightly favor consolidation into fewer bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize leaving residuals that are too small to be useful for typical items,
    // but only mildly for very small dead space (near-perfect fits).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement;
    // if next item cannot use the post-residual, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * progress;
        }
    }

    // Prefer bins whose residual is already below average (consolidate fullness),
    // penalize dipping into large residual bins when others are tighter.
    let rel = bin_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Global state: when many bins are open, avoid spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual < bin_capacity {
        score -= 15.0 * open_pressure;
    }

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    // Only attractive when nothing fits well or item is large relative to capacity.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 45.0
            - 50.0 * desperation
            - 20.0 * large_item * large_item
            + 10.0 * progress;
        // If other bins fit but all leave bad residuals, allow new bin:
        if fitting_bins_count >= 1 {
            let avg_post = if fitting_bins_count > 0 {
                (mean_residual - item_size as f64).max(0.0)
            } else { 0.0 };
            if avg_post < 10.0 {
                score -= 30.0;
            }
        }
    }

    // Mild time-horizon coupling: late in the stream, be more aggressive about
    // closing bins tightly (minimize residual variance across open bins).
    score += 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p = progress;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * p) + norm_pr * (1.0 - p) * (1.0 - p);
    score += 30.0 * poly;

    // Reward tight fits (small post_residual), stronger early in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (1.0 + 0.5 * p);

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap * (0.5 + p);
        } else {
            // Reward leaving room exactly useful for the lookahead item.
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 - p);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0 * tightness * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + tightness);
    }

    // New empty bin candidate: penalize slightly unless open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 {
            (mean_residual / cap).max(0.0)
        } else {
            1.0
        };
        let penalty = 20.0 * (1.0 - congestion * congestion) + 10.0 * (1.0 - p);
        score += penalty.max(0.0);
    }

    // Mild penalty proportional to residual scaled by mean residual pressure.
    score += 3.0 * norm_pr * (mean_residual / cap.max(1.0)).clamp(0.0, 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic classes: classify post_residual into capacity fractions (1/8 buckets).
    // Dead space in low classes is less damaging; penalize mid-range wasted slabs.
    let eighth = (bin_capacity / 8).max(1);
    let class = post_residual / eighth;
    let class_penalty = match class {
        0 => -6.0,                      // near-perfect fill
        1 => 2.0,
        2 => 4.0,
        3 => 6.0,
        4 => 5.0,
        5 => 3.0,
        6 => 1.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= eighth {
            score -= 12.0;
        } else {
            // penalize leaving a gap that matches a "bad" harmonic class for next item
            score += 0.15 * slack as f64;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for next item -> dead space; penalize more when small
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or with many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        // If current bin would leave a big awkward residual, opening is competitive.
        if post_residual > bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Mild preference to spread load across many open bins (keeps options open).
    if bin_residual < bin_capacity {
        score += 0.02 * open_bins_count as f64;
        // reward using bins with residuals below mean (consolidate low-residual bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Small deterministic tie-break on exact modular structure of post_residual.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave a gap matching the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // gap cannot host next item: mild penalty scaled by wasted potential
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // prefer filling existing ones over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64;
    score += pressure * 0.4 * (1.0 - progress);

    // Penalize bins far below mean residual (fragmentation avoidance),
    // and slightly favor bins near mean for consolidation.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += (-dev) * 0.15;
    } else {
        score -= dev * 0.05;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + pressure * 0.5;
    }

    // Tight-fit bonus relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact two-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 60.0 / (1.0 + diff as f64);
        // mild bonus if next item fits with a decent leftover too
        if next_item_size <= post_residual as u32 {
            score -= 8.0;
        }
    }

    // Penalize dead space far from mean residual (unusual leftover)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin would leave tiny waste
    if bin_residual == bin_capacity {
        let waste = bin_capacity.saturating_sub(item_size) as f64;
        // good if item fills a fresh bin well
        score += 30.0 - 0.5 * (bin_capacity as f64 - waste);
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter bins generally (small residual before placement)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Penalize creating dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0;
            // Extra reward if next item exactly fills the remainder.
            if (post_residual as f64 - nxt).abs() < 1.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize wasting a tight bin on a bad chain.
            score += 6.0 * (nxt - post_residual as f64) / 100.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins below the mean residual (tighter bins).
    if open_bins_count > 1 {
        let diff = mean_residual - residual;
        score += 0.15 * diff;
    }

    // Time horizon: early in the stream, be more liberal opening bins (exploration);
    // late in the stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // open bins are scarce or very full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let mut new_bin_penalty = 25.0 + 0.5 * post_residual as f64;
        // If existing bins are mostly full and item is big, opening a bin is more acceptable.
        new_bin_penalty -= 30.0 * avg_fill * (item_size as f64 / 100.0);
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 35.0;
        }
        score += new_bin_penalty.max(-10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 - fit_norm) * (1.0 - fit_norm);
    score -= 30.0 * poly * (0.5 + progress);
    // Penalize dead space that next item cannot use
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * (0.4 + 0.6 * progress);
    }
    // Reward when this is the only fitting bin (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // Slight preference for tighter bins relative to mean residual
    score += 0.15 * (mean_residual - pr);
    // New-bin candidate: neutral baseline with mild progress-dependent penalty
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic classes: classify post_residual by integer division into
    // "usability buckets" relative to the smallest plausible item (<= 100).
    // Buckets: [0..10) tiny-dead, [10..25) narrow, [25..50) medium, [50..100) large.
    let bucket = post_residual / 25; // 0,1,2,3
    // Dead-space penalty grows super-linearly for small buckets.
    let dead_penalty = match bucket {
        0 => 120.0 - (post_residual as f64) * 4.0, // very small leftovers are nearly worthless
        1 => 30.0,
        2 => 8.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward if the lookahead item fits into the post_residual (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        // Deeper reward when post_residual is close to next_item_size (tight chain).
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally.
        score += (next_item_size as f64) * 0.25;
    }

    // Modulo / divisibility harmonic classes on capacity fractions:
    // leftovers that divide capacity evenly (e.g. 50, 25, 20, 10) are reusable
    // by common item classes; leftovers like 37, 63 are awkward.
    if post_residual > 0 && (bin_capacity % post_residual == 0 || post_residual % 10 == 0) {
        score -= 12.0;
    } else if post_residual > 5 && post_residual % 5 != 0 {
        score += 6.0; // awkward non-multiple-of-5 leftover
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        // Exception: if the leftover would be tiny-dead AND the next item is big,
        // a fresh bin may be better.
        if post_residual < 10 && next_item_size > 50 {
            score += 90.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge raw score (post_residual = 100),
    // but we may still open it when all fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // (amortization) or late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + 40.0 * (1.0 - progress) - (open_bins_count.min(20) as f64) * 1.5;
        // If no existing bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large and this item is small, better pack small items together.
        if next_item_size > 60 && item_size < 30 {
            score += 25.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is far below the mean
    // (concentrate fullness in fewer bins).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.15;
    } else {
        score += (resid_f - mean_residual) * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: small unusable gaps are costly.
