    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more early when bins few.
        score += 10.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next fits: small reward proportional to tightness
            score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize leaving space that is
            // unusable for the lookahead item (dead space risk)
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating tiny unusable slivers (below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins with residual already below mean
    // (tight bins get consumed first, keeping loose bins flexible)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no good fit exists (large item relative to residuals) or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        // base cost of opening a new bin
        score = 60.0 + 0.5 * waste;
        // cheaper to open a new bin early in the stream
        score -= 40.0 * (1.0 - progress);
        // very expensive to open new bin if it's a last-chance situation elsewhere
        if fitting_bins_count >= 1 {
            score += 150.0;
        }
        // if item nearly fills a fresh bin, opening is fine
        if item_size >= 80 {
            score -= 50.0;
        }
    }

    // mild penalty for very full bins that would be closed wastefully small
    if post_residual > 0 && post_residual < item_size.min(20) as u32 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

