    // Exact fit is golden.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (chaining),
    // penalize leftovers that are just barely too small (dead space trap).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size / 2 {
            score += 10.0; // awkward sliver relative to next item
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score -= 40.0 * (1.0 - tight);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when open bins are fragmented (high mean residual, many bins) or late in stream.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt()
        } else {
            0.0
        };
        new_bin_penalty -= 20.0 * fragmentation.min(2.0);
        let progress = if total_items > 1 {
            step_index as f64 / (total_items as f64)
        } else {
            0.0
        };
        new_bin_penalty -= 10.0 * progress;
        // If no other bin fits, opening is unavoidable; soften penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty = 5.0;
        }
        score += new_bin_penalty;
    }

    // Mild bonus for filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // Penalize choosing bins with residual far above the mean (keep an even spread
    // of residuals so future medium items still fit somewhere).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
