    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, with non-linear quadratic penalty on small residuals.
    let mut score = post;

    // Smooth quadratic coupling: residuals near zero are dead space -> extra penalty;
    // large residuals are reusable -> mild discount.
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm - 6.0 * post_norm;

    // Tight-fit reward: fraction of bin consumed by this item, cubed for smoothness.
    let fill_frac = item / cap;
    score -= 18.0 * fill_frac * fill_frac * fill_frac;

    // Stream-progress coupling: late in the stream, waste matters more (fewer chances to fix it).
    let urgency = progress * progress;
    score += 10.0 * urgency * post_norm;

    // Lookahead: if the next item fits exactly into post_residual, reward heavily;
    // if it cannot fit, mild penalty for leaving a gap the next item can't use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 14.0 * snug * snug;
        } else {
            let overshoot = (nxt - post) / cap;
            score += 6.0 * overshoot * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless open bins are crowded
    // or residuals are too fragmented to be useful.
    if bin_residual == bin_capacity {
        let crowdedness = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / cap);
        score += 25.0 - 8.0 * crowdedness.min(3.0);
        // Late in stream with a known next item, opening fresh is more acceptable.
        score -= 10.0 * urgency;
    }

    // Mild preference to balance load: bins far below mean residual are slightly favored.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by modulo-10 bucket
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Reward near-perfect fills (post_residual in small harmonic classes)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space in awkward residue classes (post_residual mod 10 in 1..=3)
    let pr_class = post_residual % 10;
    if pr_class >= 1 && pr_class <= 3 {
        score += 12.0;
    } else if pr_class >= 4 && pr_class <= 6 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
        // Harmonic match bonus: same modulo class chains well
        if next_class == item_class {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item smaller than current: penalize leaving large residues it can't exploit
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with lower residual relative to mean (best-fit tendency)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Fraction-of-capacity thresholds: penalize bins less than half full already
    if (bin_residual as f64) < bin_capacity as f64 * 0.5 {
        score += 10.0;
    }

    // Integer-division thresholds on post_residual
    let pr_div = post_residual / 20;
    score += match pr_div {
        0 => -10.0,
        1 => 0.0,
        2 => 5.0,
        _ => 10.0,
    };

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Many open bins: discourage spreading, favor filling existing ones
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // New-bin candidate bias: empty bin gets a mild penalty so real bins win ties,
    // but a large bonus when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    }

    // Reward perfect/near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bin mildly unattractive unless
    // no reasonable fit exists (post_residual would be large dead space anyway).
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if placing here leaves a good chunk usable, allow it as fallback.
        if post_residual >= 35 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_diff = post_residual as f64 - next_item_size as f64;
        if gap_diff < 10.0 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would NOT fit here but would fit if we had a fresh bin, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_capacity {
        score += 12.0;
    }

    // Slight preference for bins with below-mean residual (fill emptier bins first
    // keeps large residuals available for large items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Late in the stream, tighten up: prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual) non-linearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_quality * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer post_residual close to next_item_size from above.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Dead space relative to the lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer consuming bins with above-average residual (large residual bins
    // are easier to fill later), penalize draining below-average ones.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, tighten packing: penalize leaving any residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * progress * post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be tiny dead space elsewhere) or many bins open.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if next_item_size > 0 && post_residual == bin_capacity {
            0.0
        } else {
            0.0
        };
        let _ = poor_fit_elsewhere;
        // Base penalty keeps new bins from opening unless alternatives are bad.
        score += 65.0;
        // But if the item is large and would leave a big awkward residual in
        // any fitting bin, opening fresh is relatively better.
        score -= 0.4 * item_size as f64 * (fitting_bins_count == 0) as u8 as f64;
        // Fewer open bins -> cheaper to open a new one.
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight penalty for very small residual fragments (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within stream (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let tight = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += tight * 30.0;
    }

    // Penalize post-residual that is small-but-unusable relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // exact lookahead fit is extra valuable
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; few bins: encourage filling
    score += open_bins_count as f64 * 1.5;

    // Global residual pressure: if mean residual is high, prefer bins below mean (compact)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early in stream: be more willing to open new bins (exploration);
    // late in stream: squeeze into existing bins
    let new_bin_bias = 30.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less so early on
        score += 20.0 + new_bin_bias;
    }

    // Late stream: penalize opening new bins harder
    score += progress * 15.0 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit), non-linearly scaled.
    let mut score = post * (1.0 + 0.8 * progress);

    // Smooth quadratic coupling: strongly reward very tight fits (post near 0).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space: residual too small to fit typical future items.
    // Smooth decay of usefulness of post_residual.
    let usable = post / cap;
    score -= 6.0 * (usable * (1.0 - usable) * 4.0).min(1.0);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to remaining stream.
        score += 4.0 * (1.0 - progress) * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Crowding: many open bins -> favor consolidation into existing bins.
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
    score += 3.0 * crowd * (post / cap);

    // Relative to mean residual: prefer bins below mean residual (more packed).
    score += 2.0 * (post - mean_residual) / cap;

    // New empty bin candidate: make it attractive only when current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin has post_residual = cap - item; penalize so it's chosen only
        // when open bins would leave worse fragmentation.
        score += 8.0 + 6.0 * (1.0 - progress) - 4.0 * (item / cap);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 5.0; // fresh bin can serve next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward post-residuals that fall into
    // "usable" residue classes (multiples of common item sizes).
    let pr = post_residual;
    if pr > 0 {
        // Class 0: post_residual divisible by 10 -> very reusable
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Integer-division thresholds: small dead space is bad
        if pr < 10 {
            score += 25.0; // dead space below min item size
        } else if pr < 20 {
            score += 10.0;
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Fraction-of-capacity coupling: bins near full are good targets
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Lookahead harmony: if next item fits the post residual exactly or in-class
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if pr >= next_item_size {
            score -= 4.0;
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's residue anyway; mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins would leave huge waste
    if bin_residual == bin_capacity {
        let waste_if_forced = (mean_residual - item_size as f64).max(0.0);
        score += 10.0 + waste_if_forced * 0.5;
        // early in stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter bins fill first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for any
    // future item (minimum item size 1, but small gaps below ~10 are nearly
    // unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward strongly; if post_residual is too small for next_item_size,
    // penalize mildly (dead space for the immediate future).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins and favor filling existing ones (new-bin candidate has max residual).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: bins below mean residual are already tight;
    // prefer placing into bins with residual above the mean to balance.
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early stream: be slightly more tolerant of waste early on since
    // distribution is unknown; later, tighten dead-space penalties.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or near-exactly) accommodates the next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = pr - ni;
            // Reward ability to take the next item, scaled by tightness of fit.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if the next-next residual would be tiny (tight chain).
            if slack < 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here: penalize dead space that is too small
            // to be useful for typical items (wasted capacity).
            if post_residual < 10 {
                score += 40.0 * (1.0 - pr / 10.0);
            }
            // Mild penalty proportional to unusable gap relative to mean residual.
            score += 0.3 * (mean_residual - pr).abs();
        }
    }

    // Prefer filling existing bins when few alternatives exist.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0; // last-chance bin: strongly favor using it
    }

    // Discourage opening new bins early in the stream when open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost so it loses unless fits are terrible.
        score = bin_capacity as f64 + 10.0 * open_bins_count as f64;
        // Allow new bin only if no existing bin can chain with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
    } else {
        // Reward tight fits of the current item (low post residual already helps).
        if post_residual == 0 {
            score -= 50.0; // perfect fill
        }
        // Mild preference for bins below mean residual (consolidating space).
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness;

    // Penalize dead space quadratically, normalized by capacity.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * 100.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses leftover
            let use_frac = (next_item_size as f64) / (post_residual.max(1) as f64);
            score -= 25.0 * use_frac;
        } else {
            // next item won't fit here; mild penalty if post_residual too small to matter
            if post_residual < 10 {
                score += 15.0; // wasted but tiny, acceptable-ish? penalize leaving crumbs
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have large residuals (fragmented state) or few bins exist.
    if bin_residual == bin_capacity {
        // base cost of a new bin: capacity worth of space
        score += 60.0;
        // cheaper to open when many open bins already (spread load) or late in stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // if mean residual across open bins is large, opening fresh is less wasteful
        score -= 0.15 * mean_residual;
        // if few fitting bins and this item is big, new bin reasonable
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // Prefer reusing existing bins generally, more so when many bins open.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Time-horizon coupling: early in stream, be conservative (favor tight fits more);
    // late in stream, prioritize closing out bins (favor low post_residual even more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 0.5 * (bin_capacity - post_residual) as f64;
    score += (1.0 - progress) * 0.2 * pr;

    // Penalize bins whose residual is far from mean (outliers) unless it's a great fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness.min(1.0));

    // Small penalty if post_residual is a "crumb" that nothing (min size 1..10) can use well
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post_residual, but weight grows with stream progress
    let mut score = pr * (0.6 + 1.4 * progress * progress);

    // Smooth non-linear penalty for leaving awkward residual sizes
    // Residuals just below typical item sizes are "dead space"
    let awkward = (prn * std::f64::consts::PI).sin().abs();
    score += 18.0 * awkward * prn * (1.0 - prn) * (1.0 + progress);

    // Coupling with lookahead: reward if next item fits post_residual smoothly
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let fit_next = (pr - nx).max(0.0);
        let fit_quality = 1.0 - (fit_next / cap).powf(2.0);
        score -= 10.0 * fit_quality * (1.0 - is_new) * (0.5 + 0.5 * progress);
        // Penalize near-exact fills that waste perfect fit on wrong item
        score += 6.0 * ((prn - nx / cap).abs()) * (1.0 + progress);
    } else {
        // Last item: strongly prefer tightest fit
        score *= 0.5;
    }

    // Last-chance bin bonus (only fitting bin): smooth sigmoid urgency
    let urgency = 1.0 / (1.0 + (-(fitting_bins_count as f64 - 1.5)).exp());
    score -= 15.0 * urgency * (1.0 - is_new);

    // New-bin candidate: penalize opening bins early, allow late in stream
    // or when residuals are fragmented
    let fragmentation = (mean_residual / cap - prn).abs();
    score += is_new * (30.0 - 25.0 * progress - 10.0 * fragmentation.min(1.0));

    // Mild load-balancing coupling with open bins count
    score += 0.3 * open_bins_count as f64 * prn * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let item_class = item_size / 10;                 // 1..=10
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Reward tight fits: exact fill is ideal
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that is too small for typical future items
        let dead = post_residual;
        if dead < 10 {
            score += 25.0; // unusable sliver
        } else if dead < 20 {
            score += 12.0;
        } else if dead < 40 {
            score += 4.0;
        }
        // Harmonic bonus: residual that matches a coarse class boundary is reusable
        if dead % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        // Extra reward when residual class aligns with next item class
        let align = if post_residual % 10 == next_item_size % 10 { 8.0 } else { 0.0 };
        score -= 10.0 + align;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: mild penalty scaled by tightness
        score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Prefer filling bins with larger residuals among open bins (best-fit flavor)
    score -= bin_residual as f64 * 0.05;

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins are open or stream is late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + open_bins_count as f64 * 1.5 + progress * 10.0;
        // But if current item is huge and would leave a bad residual in any open bin,
        // the base post_residual comparison handles it; slight relief for huge items
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is "waste" to leave open
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.1;
        }
    }

    // Small tie-breaker on item class to stabilize harmonic selection
    score += item_class as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized
        if post_residual < 10 {
            score += 45.0; // gap too small for any plausible item
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
        // Lookahead coupling: gap unusable by the NEXT item is dead space
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // Gap exactly fits the next item: excellent
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 22.0;
        }
    }

    // Reward tight fits relative to bin fill (implicit via post_residual already),
    // small extra nudge proportional to item size
    score -= 0.08 * item_size as f64;

    // New-bin candidate (empty bin): penalize so we prefer decent existing fits
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 25.0; // an open bin can take it; don't open a new one
        }
        // early in stream, opening bins is cheaper; late, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones
    score -= 0.15 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (balance load)
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + chain_gap * 0.15);
        } else {
            // next item cannot fit here; penalize small dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.25;
        }
        // if next item also leaves a near-zero residual after chaining, extra reward
        if post_residual > next_item_size {
            let chain_post = post_residual - next_item_size;
            if chain_post <= 5 {
                score -= 25.0;
            }
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good fit relative to fleet)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: must use it or open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented / early stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_dead = (post_residual as f64 - mean_residual).max(0.0);
        let new_bin_bonus = 20.0 * progress + avg_dead * 0.4 + open_bins_count as f64 * 1.5;
        score += new_bin_bonus;
        // perfect two-item fill of a fresh bin
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 70.0;
        }
    }

    // Slight penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 45.0 * fill * fill;

    // Penalize dead space: small post_residual is good, but if post_residual
    // is nonzero and tiny relative to typical item sizes, penalize extra.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * dead * (1.0 - dead);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement; if next item would be blocked, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * (1.0 - slack);
        } else {
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Reward new bin when existing bins are crowded (low mean residual)
        // or when this placement would leave a lot of dead space elsewhere.
        score -= 20.0 * (1.0 - avg_open / bin_capacity as f64);
        score += 15.0 * fill; // slight bias against opening bins early
    }

    // Time horizon: late in the stream, consolidation matters more;
    // penalize fragmentation harder as progress advances.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 18.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins when mean residual is still large.
    if open_bins_count > 0 {
        score += 0.6 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let it = item_size as f64;
    let cap = bin_capacity as f64;
    let mut score = pr.powf(1.35 + 0.5 * progress);

    // Reward tight fits more strongly early in the stream (preserve flexibility later).
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness.powf(2.0) * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: if the next item still fits after placement, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Creating dead space the next item cannot use: penalize smoothly.
        let dead = pr / cap;
        score += 8.0 * dead.powf(1.5);
    }

    // Brand-new empty bin candidate: penalize mildly for small items,
    // but allow opening for large items that would fragment an existing bin.
    if bin_residual == bin_capacity {
        let large = it / cap;
        score += 25.0 * (1.0 - large).powf(2.0) - 10.0 * large;
        // Opening new bins is cheaper when many bins are already open and mean residual is high.
        score -= (open_bins_count as f64).sqrt() * 1.5 + mean_residual * 0.05;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor, smooth).
        let gap = (bin_residual as f64 - it) / cap;
        score += 10.0 * gap.powf(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.4;

    // Reward tight fits strongly (post_residual near zero is ideal)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this leftover: penalize proportionally to waste
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin costs ~cap of unused space; penalize baseline
        score += cap * 0.5;
        // More attractive late in stream or when mean residual is low (bins nearly full)
        score -= progress * 10.0;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can host pair
        }
    }

    // Fraction-of-capacity classes: reward bins whose fill is near harmonic fractions
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    let frac_score = (fill_frac * 4.0).round() / 4.0; // quarters of capacity
    score -= (fill_frac - frac_score).abs() * 8.0;

    // Mild pressure against hoarding many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible future item are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10.0f64; // smallest possible item size
        if (post_residual as f64) < dead_threshold {
            score += 60.0; // unusable sliver -> very bad
        }
        // Non-linear penalty growing as post_residual shrinks into the dead zone.
        let r = post_residual as f64;
        score += 25.0 * (1.0 - r / bin_capacity as f64).powi(3);
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0; // lookahead won't fit here afterward
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (the empty-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 30.0 + 8.0 * open_bins_count as f64 + mean_residual * 0.5;
        // Late in the stream, consolidating is even more valuable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    } else {
        // Filling existing bins is good when many bins are open.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is already below average (nearly-full bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus for near-perfect chaining
        if gap <= 2.0 {
            score -= 25.0;
        } else if gap <= 5.0 {
            score -= 12.0;
        }
        // Penalize post-residual that is too small to ever hold typical items
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
        // Bonus if post residual can still hold the next item with slack
        if post_residual >= next_item_size {
            score -= 3.0;
        }
        // Penalize wasting a large residual on a small item when lookahead doesn't match
        if post_residual > 0 && gap > 20.0 && post_residual < 30 {
            score += 6.0;
        }
    } else {
        // Last item: just minimize leftover
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residuals near the mean (balanced usage)
    let resid_f = bin_residual as f64;
    let dev = (resid_f - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer tight fits (small post residual) nonlinearly
    score += 40.0 / (1.0 + (post_residual as f64).powf(1.3));

    // Slight preference for filling already-open bins over opening new ones
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Late in stream: be more conservative, avoid creating dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins that end up with little leftover.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score -= 30.0 * (-post / 15.0).exp();

    // Penalize dead space that no typical item could use.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Lookahead: if the next item exactly or nearly fits the post-residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot use the leftover: mild penalty proportional to waste.
            score += 3.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins unless there are none that fit or the fit is bad.
        if fitting_bins_count > 0 {
            score += 15.0 + mean_residual * 0.1;
        }
        // Early in the stream, opening bins is cheap; late, be conservative.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * (mean_residual / cap) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize dead space more.
    let phase = 0.5 + 0.5 * progress;
    score += 12.0 * phase * (post / cap) * (post / cap) * cap * 0.1;

    // Reward tight fits with a cubic term (small post_residual strongly favored).
    let tight = 1.0 - post / cap;
    score -= 8.0 * tight * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Discard creating residual far from common useful sizes relative to mean residual.
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it moderately expensive so it wins only when
    // open bins would create very poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "nice" sizes
    // (multiples of 10 or exactly half capacity) are more reusable -> reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are multiples of 10 (harmonic classes)
    let class10 = (post_residual % 10) as f64;
    score -= 8.0 * (1.0 - class10 / 10.0);

    // Reward exact half-capacity leftovers strongly
    if post_residual * 2 == bin_capacity {
        score -= 20.0;
    }

    // Penalize tiny dead space (< 10) that likely cannot fit any future item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += cap * 0.6;
        // If many open bins have large mean residual, prefer packing into them
        score += (mean_residual / cap) * 40.0;
        // Early in the stream, opening bins is cheaper (build inventory)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 30.0;
        // Few open bins -> new bin more attractive
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // Prefer fuller bins generally: tighter fits rank lower score
    score -= (bin_residual as f64 / cap) * 5.0;

    // Mean-residual alignment: bins close to the mean residual are "typical" targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for future items (items are 1..100, but small gaps are hard to fill).
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits: small post_residual relative to the item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 2.0;
    }

    // Open bins pressure: with many open bins, prefer reusing existing bins
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose post residual is close to the
    // mean residual (keeps bin states balanced and usable).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.3;

    // Progress scaling: late in the stream, be slightly more conservative
    // about opening new bins (reuse pressure grows).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item exactly matches post_residual, big reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit: reward closeness of perfect chaining
            score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // post_residual too small for next item: penalize dead space unless tiny
            score += 10.0 * diff / (bin_capacity as f64);
        }
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below/at mean (well-filled bins)
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if this item would leave a large awkward residual in an existing bin,
        // opening a fresh bin becomes more attractive
        if fitting_bins_count > 0 && post_residual > 0 {
            score -= 25.0 * (post_residual as f64) / (bin_capacity as f64);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 80.0; // next item needs a fresh bin anyway
        }
    }

    // Early stream: be slightly more open to new bins (build good structure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize leaving very small unusable fragments
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 14.0 * tight * tight;

    // Penalize dead space: post residual too small to hold a typical item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 18.0;
    }

    // Lookahead: if the next item cannot fit into the post residual, penalize
    // proportionally to how close the fit currently is (blocking cost).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly placement: reward keeping room for the next item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (low mean residual) or many bins already open with fragmented space.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
        let openness = 1.0 - crowded.min(1.0);
        // Base cost of opening a new bin, discounted by fragmentation pressure.
        score += 30.0 - 20.0 * openness - 12.0 * pressure;
        // Early stream: prefer filling existing bins; late stream: open freely.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - t);
    }

    // Mild preference for bins with residual close to mean (balance load),
    // avoiding creation of extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight bonus for bins that will become perfectly full.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with growing urgency as stream progresses.
    let mut score = pr * (1.0 + progress * progress);

    // Smooth polynomial coupling: residual squared term penalizes large dead space
    // but the coupling softens when mean residual is high (bins are generally loose).
    let mean_norm = mean_residual / cap;
    score += 2.0 * norm_pr * norm_pr * cap * (1.0 - mean_norm);

    // Reward tight fits: near-zero post residual gets a strong discount.
    let tightness = 1.0 - norm_pr;
    score -= cap * tightness * tightness * tightness;

    // Interaction with next item: if next item fits exactly in post_residual,
    // strongly reward; if post_residual is awkwardly small for next item, penalize.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fit_gap = (pr - next).abs() / cap;
        score -= cap * (1.0 - fit_gap) * (1.0 - fit_gap);
        score += 1.5 * fit_gap * cap;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8 * cap;
    }

    // Mild penalty for spreading across too many open bins early in the stream.
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += cap * (1.0 + 2.0 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Dead-space penalty: leftover below smallest plausible item is nearly useless.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Modulo classes on post_residual (common item-size residues create good future fits).
    let r = post_residual % 10;
    if r == 0 {
        score -= 12.0; // residue 0 aligns with decimal item sizes
    } else if r <= 2 || r >= 8 {
        score += 8.0;  // awkward residue classes
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 + 25.0 * snug;
        } else if next_item_size <= bin_residual {
            // Next item would have fit before this placement but not after: penalize.
            score += 18.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fractional thresholds on post_residual.
    if post_frac > 0.5 {
        score += 5.0; // wasteful large leftover
    } else if post_frac <= 0.1 && post_residual > 0 {
        score -= 6.0; // tight fill is good
    }

    // Prefer filling existing bins over opening new ones as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // Only open a new bin if mean residual across open bins is very low.
        score += mean_residual * 0.5;
    } else {
        score -= 5.0 + 10.0 * progress;
    }

    // Mean residual anchoring: favor bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100
    // stream, but typical items are >=10) are nearly unusable; penalize hard.
    if post_residual < 10 {
        score += 60.0; // tiny gap = dead space, very bad
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual close to next item size (lookahead k=2).
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff <= 5.0 {
            score -= 20.0;
        } else {
            score += diff * 0.15;
        }
    }

    // Tight fits (item fills most of the bin) are preferred.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // a new empty bin candidate (residual == capacity) should be disfavored
    // unless existing bins fit poorly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (1.0 - progress * 0.5);

    if bin_residual == bin_capacity {
        // New-bin candidate: accept only as last resort.
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open new bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with residual above mean (keep a spread of usable sizes),
    // but slightly favor below-mean when bins are few.
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Exact-fit bonus: item leaves nothing or a very tiny gap.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post residual,
    // penalize if the leftover is "almost but not quite" usable by next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.5; // imperfect chain penalty
        } else {
            // next item can't use the leftover: leftover is dead space unless
            // a future item fits; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below average means we concentrated usage well.
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit. Make the empty bin expensive by default.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 70.0;
        // cheaper to open a new bin when many bins are open and mean residual is low
        // (existing bins are crowded), and when the item is large relative to capacity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score -= crowded * 25.0;
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        score -= progress * 10.0;
        // if the next item is large and would not fit leftovers, new bin is fine
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate aggressively: penalize spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Small penalty for very large post_residual leftovers (dead space).
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: residual after placement close to zero.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 200.0 * tightness * tightness;
    }

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small gap is nearly dead anyway; slight reward to consolidate
    }
    if post_residual > 50 {
        score += 30.0 * ((post_residual - 50) as f64 / 50.0);
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 100.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 40.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or the stream is early and future flexibility matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64; // == 1 - item/C for new bin
        let poor_alternatives = if fitting_bins_count == 0 { 300.0 } else { 0.0 };
        score -= poor_alternatives;
        // A fresh bin keeps mean residual high; more valuable early.
        score -= 250.0 * (1.0 - progress) * (1.0 - fit_quality);
        // Penalize opening new bins when many are already open with slack.
        score += 15.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Global pressure: when mean residual across bins is low, prefer
    // filling bins tightly rather than spreading items.
    let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += 25.0 * mean_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild late-stream consolidation: fewer open bins desired near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (open_bins_count as f64 / (open_bins_count + 2) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
