pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: fraction of capacity consumed by this item
    let frac = item_size as f64 / bin_capacity as f64;
    let eighth = (frac * 8.0).round() as i32; // harmonic class 0..8

    // Reward tight fits via integer-division thresholds on post_residual
    let pr = post_residual as i32;
    let band = pr / 10; // decile band of dead space
    match band {
        0 => score -= 30.0,             // post_residual < 10: near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        5 | 6 => score += 6.0,          // mid dead space: mildly bad
        7 | 8 | 9 => score += 14.0,     // large dead space: strongly bad
        _ => {}
    }

    // Modulo arithmetic on post_residual: residuals that pair with common
    // item classes (multiples of 10) are reusable, odd residuals are not.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;               // perfectly reusable residual
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;               // awkward residual
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave a bad residual
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (fill emptier-relative bins less,
    // concentrate on tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Harmonic class coupling: large items (high class) prefer fresh space,
    // small items prefer filling leftovers
    if eighth >= 6 {
        // large item: penalize placing into a nearly empty open bin when many
        // bins are open (save big residuals for... actually large items should
        // go into emptiest bins)
        score += 0.0;
    } else if eighth <= 2 {
        // small item: discourage opening new bins for tiny items
        if bin_residual == bin_capacity {
            score += 35.0;
        }
    }

    // New-bin candidate handling: base cost of opening a bin, reduced when
    // item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_bonus = frac * 40.0; // large items justify new bins
        score = score.max(0.0) + 55.0 - size_bonus - 15.0 * (1.0 - progress);
        // but if no open bin fits at all, opening is forced-ish: soften cost
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference to keep open-bin count low late in the stream
    score += open_bins_count as f64 * 0.02 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps disproportionately.
    if post_residual > 0 {
        // A residual is "dead" if it can't hold a plausible small item (<=10)
        // and is small relative to capacity.
        if post_residual < 10 {
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        }
        // Non-linear penalty on very tight fits: near-perfect fills are great,
        // but the last few units of waste hurt more than linear.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill * fill;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Dead space is worse if the leftover gap can't fit the next item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Bonus if post residual exactly accommodates next item (chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized implicitly since the
    // new-bin candidate has max post_residual.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 35.0 + 4.0 * pressure;
        // But if this bin is the only fitting option, opening a new bin
        // may be better than forcing a bad fit.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 30.0;
    }

    // Late in the stream, tighten up: dead space matters more since
    // fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step fit: place here
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.3 * post_residual as f64;
    }

    // Reward bins with residual below mean (densely packed bins)
    score += 0.6 * (mean_residual - post_residual as f64).max(0.0) * -1.0;
    score -= 0.4 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 10.0; // new bin would be emptier than average
        }
    }

    // Mild preference for bins that are already partially filled
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    // Small penalty for very small residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small dead space that is hard to reuse (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits into post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize slightly less if post residual is large
            score += 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with number of open bins.
        score += 60.0 + 2.0 * open_bins_count as f64;
        // But if current bin would leave very little usable space, new bin is attractive.
        if post_residual < 10 {
            score -= 70.0;
        }
    }

    // Time horizon: early in stream, be frugal with bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Global pressure: many open bins with large mean residual -> prefer filling existing bins.
    if mean_residual > 0.0 {
        score -= 5.0 * (bin_residual as f64 / mean_residual - 1.0).clamp(-1.0, 1.0);
    }

    // Prefer bins whose residual is close to item size (minimal waste).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    if fit_ratio <= 1.0 {
        score -= 20.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear penalty on dead space, amplified by stream progress
    let post_norm = post / cap;
    score += (post_norm * post_norm) * cap * (0.5 + 0.5 * progress);

    // Reward tight fits: cubic coupling of post_residual with item size
    let item_frac = item_size as f64 / cap;
    score -= item_frac * item_frac * (cap - post) * 0.8;

    // Penalize being the only fitting bin (last-chance bin should be used)
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 10.0 * (next / cap);
        } else {
            score += (next - post) * 0.3 * (1.0 - progress);
        }
    }

    // Slight preference to spread load when many bins are open and mean residual is high
    score += (mean_residual - post) * 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bin mildly unattractive unless residuals are very tight
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - post_norm) * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common
    // item classes (multiples of 10, and mid-range sizes) are rewarded.
    let post = post_residual;
    if post == 0 {
        // Perfect fit: maximal reward.
        score -= 1000.0;
    } else {
        let class = post % 10;
        // Residuals like 0 mod 10 are reusable by rounded items; odd tiny
        // slivers (1..5) are dead space -> penalize superlinearly.
        if post < 5 {
            score += 60.0 * (5 - post) as f64;
        } else if class == 0 {
            score -= 25.0;
        } else if class >= 5 {
            score -= 8.0;
        } else {
            score += 5.0 * class as f64;
        }
        // Diminishing value of residual space: waste ~ residual^1.3 scaled.
        score += (post as f64).powf(1.3) * 0.35;
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item still fits here: strong reward, scaled by how snug.
            let slack = (post - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0) * 0.4;
            if post % next_item_size == 0 && post > 0 {
                score -= 12.0; // exact harmonic division
            }
        } else {
            // Next item won't fit: this bin's leftover is likely stranded.
            let miss = (next_item_size - post) as f64;
            score += miss.min(50.0) * 0.6;
        }
    } else {
        // Last item: prefer zero waste absolutely.
        score = post as f64 * 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let crowded = (open_bins_count as f64).ln().max(0.0);
        // Base cost of a new bin; reduced when forced or many bins open.
        score += 120.0 - pressure * 90.0 - crowded * 6.0
            + (mean_residual / bin_capacity as f64) * 30.0;
        // Late in the stream, opening fresh bins wastes capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference for tighter existing fits relative to mean residual.
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (or for the smallest plausible item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        // Dead space: unusable sliver. Penalize quadratically, scaled by how
        // "wasted" it is relative to capacity.
        let waste = (min_useful - post_residual) as f64;
        score += 8.0 * waste * waste / bin_capacity as f64;
    }

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Leaves exactly the room the next item needs: strong reward.
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Room for the next item: mild reward proportional to slack.
        score -= 3.0;
    } else {
        // Post-residual smaller than next item but nonzero: likely dead space.
        score += 6.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; with few bins, allow spreading.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 20.0)).min(15.0);
    score += 0.35 * pressure;

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is poor (large post_residual) or it's a last-chance fit
    // that wastes space. Empty new bin gets residual == capacity, so its raw
    // score is high; give it a calibrated discount so it wins only when
    // existing fits are bad.
    if bin_residual == bin_capacity {
        let look = next_item_size as f64;
        // Discount grows with lookahead need and stream progress (fewer
        // wasted bins later), but shrinks when many bins are open.
        score -= 30.0 + 0.2 * look + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        score += 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it unless the fit is terrible (post_residual near capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual > 0 && post_residual < min_useful {
            score += 5.0; // but not if it creates dead space
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins),
    // penalize dipping into bins with large residuals reserved for big items.
    if (bin_residual as f64) > mean_residual + 10.0 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward scaled by how well it fills.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // Next item will not fit here: penalize leaving a near-miss gap.
            let miss = (next_item_size - post_residual) as f64;
            score += 1.5 * miss;
        }
    }

    // Penalize small unusable dead space (waste) more than large residual space.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when the bin is not the fresh new-bin candidate.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // New-bin candidate: score it as a fresh start with capacity residual,
    // slightly worse than a good existing fit but better than terrible fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 80.0
            - 0.2 * open_bins_count as f64
            - (step_index as f64 / total_items.max(1) as f64) * 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness;

    // Perfect fit: near-zero post residual gets a big discount.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space penalty: post residual that is too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Exact chain fit bonus.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize wasted capacity scaled by waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more acceptable late in the stream or when many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
        let mean_slack = mean_residual / cap;
        // Opening a new bin is penalized, less so when progress is high
        // or existing bins have large mean slack (fragmented state).
        let mut new_bin_penalty = 22.0 * (1.0 - progress) + 10.0 * pressure;
        if mean_slack > 0.35 {
            new_bin_penalty += 8.0 * mean_slack;
        }
        score += new_bin_penalty;
    }

    // Fragmentation guard: penalize bins whose residual is far below mean
    // (they are unusually full; using them may be fine) and reward bins
    // with residual close to item_size (good utilization).
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_gap;

    // Slight preference for filling bins with larger residual first,
    // keeping small residuals flexible.
    score += 0.08 * (bin_residual as f64);

    // Late-stream consolidation: as stream ends, prefer packing into
    // already-open bins to avoid leftover partial bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: residual's value decays as stream progresses
    let progress_weight = 1.0 + progress * progress * (cap / pr.max(1.0)).min(4.0);
    score *= progress_weight;

    // Penalize residual that cannot fit the lookahead item (quadratic coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            score += gap * gap / (cap * 0.5);
        } else {
            score -= 3.0 * (-gap) * progress;
        }
    }

    // Last-chance bin: strong reward to avoid wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly unless residual is tight-fitting
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap) - 0.5;
        score += 5.0 - 10.0 * tightness * tightness;
    }

    // Reward filling close to capacity (smooth cubic term)
    let fill = 1.0 - pr / cap;
    score -= 2.0 * fill * fill * fill;

    // Mean residual pressure: prefer bins deviating below mean when many bins open
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (multiples of small harmonics) are more valuable to keep.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &h in &[10u32, 20, 25, 50] {
            if pr % h == 0 {
                harmony += 8.0;
            }
        }
        // small-item friendly residuals
        if pr <= 10 { harmony += 5.0; }
        score -= harmony;
    } else {
        // perfect fill: strongly reward
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect-fit anticipation: does next item exactly consume post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let after = pr - next_item_size;
            score += (after as f64) * 0.3;
            if after == 0 { score -= 20.0; }
        } else {
            // next item won't fit here; slight penalty if we're the only option
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but allow it when open bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin now
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 15.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late-stream tightening: as stream progresses, avoid leaving large residuals
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit any future item
    // (items are >= 1, but tiny gaps < 10 are near-wasted) get a nonlinear penalty.
    if post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate more).
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Mean residual coupling: if this bin's residual is far below average, it is
    // a "lonely" nearly-full bin; deprioritize slightly to keep balance.
    let resid = post_residual as f64;
    if resid < mean_residual - 15.0 {
        score += 10.0;
    }

    // Early stream: keep bins open for flexibility; late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0 * (1.0 - tightness);

    // New-bin candidate (empty bin) should only win when the item fits poorly
    // everywhere else: give it a moderate baseline penalty.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: small post residual is already favored by base term.
    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely: strong reward scaled by tightness.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 30.0 * chain_tightness;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let dead = post_residual as f64;
            let next_rel = next_item_size as f64 / bin_capacity as f64;
            score += 20.0 * next_rel * (dead / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Penalize large post residuals relative to mean residual across open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap.max(0.0);
    score += 0.1 * mean_gap.min(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Early in the stream: be more willing to open bins for good structure;
    // late in the stream: consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large relative to capacity
        // or post_residual would chain with next item.
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * large_item_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in stream, discourage opening new bins unless nearly necessary.
        score += 20.0 * progress;
    }

    // Prefer bins that are already partially filled (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
