pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic penalty on wasted space, amplified by stream progress
    let mut score = post_norm * post_norm * (1.0 + 3.0 * progress) * cap;

    // Smooth cubic coupling: mid-range residuals are risky dead space
    let mid = (post_norm - 0.5).abs();
    score += 20.0 * mid * mid * (1.0 - post_norm) * (1.0 + progress);

    // Reward tight fits strongly (smooth in post_residual)
    score -= 60.0 * (1.0 - post_norm).powi(2) * (1.0 - is_new_bin);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 25.0 * snug * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize large leftovers
        score += 15.0 * post_norm * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 80.0;
    }

    // New-bin candidate: penalize mildly, more so early in the stream;
    // relax penalty late when open bins are fragmented
    score += is_new_bin * (30.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64 * (1.0 - progress));

    // Encourage balancing residuals toward the mean across open bins
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division on capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead space: residual too small for any item (min size 1 assumed, but
    // class-0 slivers under a quarter are hard to fill) -> penalize slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Class-based coupling: small classes (tight fits) are good, mid classes wasteful.
    score += class as f64 * 8.0;

    // Lookahead: reward if the next item still fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward for a "harmonic pair": next item nearly fills remainder.
        if post_residual.saturating_sub(next_item_size) < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how much it misses by.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: keep it unattractive unless existing bins are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a new bin is fine late in the stream when many bins are open
        // and mean residual is low (existing bins are nearly full).
        if open_bins_count > 2 && mean_residual < 25.0 {
            score -= 30.0;
        }
    }

    // Prefer denser packing early: penalize spreading across many bins.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure loss -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into
    // existing bins rather than opening more.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // next item won't fit here; gap likely wasted
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when no
    // decent fit exists; make the empty bin moderately unattractive by
    // default but not impossible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 45.0;
        nb -= 20.0 * progress; // late in stream, consolidation matters more
        if fitting_bins_count == 0 {
            nb -= 60.0; // forced new bin
        }
        if item_size >= 50 {
            nb += 10.0; // large items better placed in partially filled bins
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear pressure
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: strongly reward when next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            // next item fits, but with leftover; reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.8;
        } else {
            // next item cannot use this residual: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; using them well is good
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no good fit exists elsewhere
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish score; penalize when other bins can fit and stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count > 0 {
            score += 30.0 * (1.0 - progress);
        }
        // Slightly favor new bin late in stream when residuals are fragmented
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild penalty for very small unusable slivers (dead space < 10)
    if post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: square the post residual to punish wasted space harder.
    score += 0.5 * (post / cap) * post;

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (nxt / post.max(1.0));
        } else {
            // Next item won't fit here; penalize leaving awkward residuals.
            score += 6.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: open a new bin only when the best fit is poor or
    // early in the stream with many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / cap;
        let mut new_bin_score = 30.0 - 40.0 * (1.0 - fit_quality);
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 25.0 * progress;
        // Many open bins with high mean residual: prefer reusing them.
        new_bin_score += 0.3 * open_bins_count as f64 + 0.1 * mean_residual;
        // If item is huge, a fresh bin is fine.
        new_bin_score -= 15.0 * fit_quality;
        return new_bin_score;
    }

    // Mild bonus for bins whose residual is far below the mean (well-filled bins).
    score -= 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of post_residual.
    let x = post / cap;
    let mut score = post * (1.0 + x * x) - 0.35 * x * x * cap;

    // Smooth stream-progress coupling: later in the stream, tolerate less dead space.
    score *= 1.0 + 0.4 * progress * (1.0 - x);

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-misses smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 8.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 6.0 * ((nx - post) / cap).min(1.0);
        }
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let fitting = fitting_bins_count.max(1) as f64;
        score += 30.0 + 10.0 * (mean_residual / cap).clamp(0.0, 1.0) - 8.0 / fitting;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 group dead space into classes.
    let residue_class = (post_residual % 10) as f64;
    score -= 4.0 - 0.4 * residue_class; // small residues (tight fit) rewarded

    // Integer-division thresholds: how many size-10 slots remain after placement.
    let slots = (post_residual / 10) as f64;
    score += slots * slots; // quadratic penalty for many leftover slots (fragmentation)

    // Lookahead: strongly reward bins that can also host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot fit here; penalize proportionally to wasted capacity
            score += 0.5 * (post_residual as f64 - 5.0).max(0.0);
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that grows
    // with stream progress and how many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 6.0 * progress + 0.3 * open_bins_count as f64;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Fraction-of-capacity harmonic: reward placements filling capacity fractions
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 5.0 * (fill * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let after = post_residual as f64;
    let nxt = next_item_size as f64;

    let mut score = after;

    // Base fill reward: strongly prefer bins whose remaining space is consumed.
    score -= 1.35 * (item_size as f64 / capacity) * residual;

    // Strict dead-space avoidance: a small nonzero gap that the next item cannot
    // use is heavily penalized, especially when it is close to the item boundary.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            let tightness = 1.0 - (post_residual as f64 / nxt.max(1.0));
            score += 38.0 + 52.0 * tightness * tightness;
        }

        // Very small absolute gaps are treated as likely dead space.
        if post_residual <= 8 {
            score += 34.0 + (8 - post_residual) as f64 * 3.0;
        } else if post_residual <= 16 {
            score += 10.0 + (16 - post_residual) as f64 * 0.55;
        }
    }

    // Reward exact/near-exact closure.
    if post_residual == 0 {
        score -= 24.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 16.0;
    }

    // Open-bin pressure: when many bins are open, discourage creating another
    // fragmented residual and encourage consolidating into existing bins.
    let pressure = open_bins_count as f64;
    score += 0.028 * pressure * after;

    // If this is the only fitting bin, strongly favor using it rather than
    // opening a new bin and leaving this bin's residual stranded.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.10 * residual;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current fit would create substantial unusable dead space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };

        score = capacity - item_size as f64;
        score += 26.0 + 0.045 * pressure * capacity;

        // Slight early-stream allowance for new bins, since structure is still forming.
        score -= 7.0 * (1.0 - progress);

        // If the item exactly fills a fresh bin, opening can be excellent.
        if item_size == bin_capacity {
            score -= 70.0;
        }

        // If the next item also fits in the fresh residual, new-bin is less risky.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.06 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 30.0;
        }

        // If only this new-bin candidate can fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild alignment with mean residual: prefer placements that reduce the
    // average stranded capacity across open bins.
    score += 0.018 * (mean_residual - after).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score = (post_residual as f64).powf(1.3);

    // Reward when next item exactly matches post_residual (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward moderate slack; penalize leaving large unusable gaps.
            if slack <= 20.0 {
                score -= 30.0 * (1.0 - slack / 20.0);
            } else {
                score += slack * 0.8;
            }
        } else {
            // Next item cannot fit here after placement; dead space penalty.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (this call sees empty residual).
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_capacity as f64 - mean_residual).abs() < 1e-9 || false;
        // Penalize new bin mildly; lookahead: new bin wastes item_size now
        // but may chain with next item if next_item_size + item_size <= capacity.
        let chain_bonus = if next_item_size > 0
            && item_size + next_item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) as f64 <= 5.0
        {
            40.0
        } else {
            0.0
        };
        score += 35.0 - chain_bonus;
        if good_fit_exists {
            score += 10.0;
        }
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: small post_residual that cannot fit a typical next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus: this bin can also host the lookahead item.
            score -= 12.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how unusable the leftover is.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a decent fit, or when open bins are nearly full anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheaper to open bins early in the stream (amortize over many items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, prefer reusing them.
        score += 0.15 * open_bins_count as f64;
        score += 0.25 * mean_residual;
        // If the item is large relative to capacity, opening a fresh bin is fine.
        score -= 0.1 * item_size as f64;
        // If no open bin can fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reuse bonus: reward using existing bins, more so when many are open.
        score -= 4.0;
        // Prefer bins whose residual deviates below the mean (fill the emptier-tail bins
        // to close them out).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.08 * dev;
        } else {
            score += 0.05 * (-dev);
        }
    }

    // Mild global pressure: as stream progresses, discourage leaving scattered slivers.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 6.0 + 8.0 * progress; // tiny unusable sliver late in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual)
    let mut score = pr as f64;

    // Smooth non-linear coupling: post residual penalized more when residual
    // is awkwardly small relative to stream progress.
    let quad = x * x;
    let cube = quad * x;
    score += 40.0 * quad * (1.0 - progress) - 25.0 * cube * progress;

    // Interaction with mean residual: bins deviating from mean get smoothed preference
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bin: strongly reward using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        score -= 12.0 * fits_next * (1.0 - progress * 0.5);
        // penalize leaving residual that is just barely too small for next item
        let gap = (next_item_size as f64 - pr).abs();
        if pr < next_item_size as f64 {
            score += 6.0 * (1.0 - gap / cap) * (pr / cap);
        }
    }

    // Mild penalty for spreading across too many bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral-ish but slightly penalized so it's chosen
    // only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Dead space that cannot host typical small items (1..10) is waste.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals just above a small-item boundary are more usable.
        let usable = (class >= 1 && class <= 8) as i32;
        if usable == 1 {
            score -= 4.0;
        } else {
            score += 6.0; // class 0 or 9: awkward leftover
        }
    } else {
        // Perfect closure: excellent.
        score -= 40.0;
    }

    // Integer-division thresholds: post_residual bucketed by capacity fractions.
    let q = pr / (bin_capacity / 4); // 0..=4 buckets
    score += 8.0 * q as f64;

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // Extra reward if next item leaves another tidy class.
        if (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && pr > 0 {
        score += 5.0; // next item won't chain here
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin. Prefer it only when fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream, keep bins consolidated.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // If current fit is decent, definitely avoid new bin.
        if item_size >= 60 {
            score += 20.0;
        }
    }

    // Prefer bins with below-mean residual (fill fuller bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Many open bins: encourage closing bins down.
    score += 1.5 * open_bins_count as f64 * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable -> heavy penalty.
    // A gap is "dead" if it is smaller than the smallest plausible item (>=1) and
    // especially if it cannot host the lookahead item.
    if post_residual > 0 {
        if post_residual < next_item_size && next_item_size > 0 {
            // This gap cannot fit the next item: dead space.
            score += 40.0 + (item_size as f64) * 0.5;
        } else if post_residual <= 5 {
            // Tiny unusable sliver.
            score += 25.0;
        } else {
            // Usable gap: mild reward proportional to its utility for the lookahead.
            score -= 3.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (post_residual small relative to residual).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin option which has large residual).
    score += 0.35 * (open_bins_count as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead synergy: reward bins whose post-residual exactly accommodates the
    // next item (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin leaves large residual; make it
    // unattractive unless existing bins would create dead space (already penalized
    // above). Scale its base score with mean residual context.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    } else {
        // Slight preference for bins with below-average residual (more filled).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
