pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Reward perfect / near-perfect closure of a bin.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    }

    // Penalize large dead space after placement.
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual + 10 {
            score += 15.0; // next item just misses this bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual < 30 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins unless all fits are bad or stream is early with few bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Baseline penalty so open bins win when their fit is decent.
        score += 45.0;
        // Early in the stream with few bins, opening new bins is cheap insurance.
        if open_bins_count <= 2 && progress < 0.3 {
            score -= 30.0;
        }
        // If mean residual is small (open bins are full-ish), new bin is attractive.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 25.0;
        }
        // Late in stream, avoid spawning bins that will be nearly empty.
        if progress > 0.85 {
            score += 40.0 * (1.0 - progress);
        }
    } else {
        // Mildly favor bins whose residual is close to item (minimize waste).
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.15;
        // Prefer reusing bins with lower residual overall (fill fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Global load balancing: with many open bins, prefer consolidating into
    // fuller bins to enable closing them.
    if open_bins_count > 4 {
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // later in the stream, waste (post_residual) is penalized progressively harder.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress);
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead: if the next item exactly fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: mild penalty scaled by wasted space
        let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)) / bin_capacity as f64;
        score += 10.0 * waste * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize scattering across many open bins when residual is far above mean
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev * (1.0 + open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: make empty-bin score track mean residual pressure so it wins
    // only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact halves/quarters are reusable slots
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 30.0;
    } else if bin_capacity % pr == 0 {
        // residual divides capacity: a "harmonic" slot future equal items can reuse
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 15.0;
    } else {
        // penalize awkward dead space via modulo distance to nearest multiple of 10
        let m = (pr % 10).min(10 - pr % 10) as f64;
        score += m * 2.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0;
            // harmonic bonus: next item leaves another harmonic residual
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 40.0; // discourage opening when existing bins fit
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.5;

    // Prefer bins with below-mean residual (tighter packing)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

