    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual was large relative to the mean (good fit
    // into the emptiest bin keeps other bins flexible).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += 15.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
