        // late in the stream, unless it is a very tight placement.
        score += 12.0 + 0.35 * open_bins_count as f64 + 10.0 * progress;
        if post_residual == 0 { score -= 60.0; } // perfect fill justifies new bin
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit exactly into the post residual,
    // reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // Next item cannot fit in the gap -> gap is likely dead space.
            score += 6.0;
        }
    }

    // Mild tie-break toward bins with residual near mean (keeps balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
