    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default: opening a new bin is moderately costly so we only do it when
        // existing fits are poor. Escalate cost as more bins are open.
        score = bin_capacity as f64 * 0.55 + 4.0 * open_bins_count as f64;
        // If nothing else can even fit the item, opening is fine (handled via
        // fitting_bins_count == 0 on other candidates being absent).
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Late in stream with fragmented state, opening fresh bins is acceptable.
        if progress > 0.7 && mean_residual < 25.0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Smooth polynomial coupling: post_residual modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm) - 12.0 * fill * fill * (1.0 + progress);

    // Reward near-perfect fits smoothly (dead-space penalty grows quadratically)
    score += 0.05 * (pr_norm * cap - 0.0) * pr_norm;

    // Lookahead coupling: penalize residual that wastes space relative to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 + progress);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to prefer bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect-fit reward: post_residual exactly 0 is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize "dead zone" leftovers that few future items can use.
        // Items are 1..100; small residuals (< ~10) are near-useless, mid residuals are fine.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post) / 10.0;
        }
        // Harmonic classes: residuals in [50,100) are "half-class" — very reusable.
        // Residuals in [25,50) are "quarter-class" — moderately reusable.
        // Quantize with integer division thresholds.
        let cls = post_residual / 25; // 0,1,2,3
        match cls {
            3 => score -= 45.0, // >=75: half-or-more free, great
            2 => score -= 25.0, // 50..74
            1 => score -= 10.0, // 25..49
            _ => {}             // 10..24: mild dead space
        }
        // Modulo-style coupling: reward when residual aligns with common size bands
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement matters too
            let post2 = post_residual - next_item_size;
            score -= 30.0 - (post2 as f64).min(30.0) * 0.5;
        } else {
            // next item won't fit here; penalize less if residual still broadly reusable
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; offset by how many bins already open
        score += 150.0 - (open_bins_count as f64).min(50.0) * 2.0;
        // if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Reward tight fits relative to bin capacity fraction
        let tight = (item_size as f64) / (bin_residual as f64);
        score -= tight * 40.0;

        // Encourage consolidation when many bins are open
        score += (open_bins_count as f64) * 1.5;

        // Progress-aware: later in the stream, prefer tighter packing
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += frac * 20.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean
    score -= (mean_residual - post) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A gap that cannot fit the next item (or is very small) is "dead space".
    let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
    let tiny_gap = (post_residual < 10) as f64;

    // Dead space is heavily penalized, scaled by how close the gap is to being useless.
    if dead > 0.0 {
        let waste_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 60.0 + 40.0 * waste_ratio;
    }
    if tiny_gap > 0.0 && dead == 0.0 {
        // small but still potentially usable gap: moderate penalty
        score += 15.0;
    }

    // --- Reward tight fits (small post_residual relative to item) ---
    let fit_tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fit_tightness * fit_tightness;

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless every existing bin would create dead space.
        // Base penalty for proliferation, reduced when many bins are already open (pressure).
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
        score = bin_capacity as f64 - 30.0 * pressure;
        // If next item would fit into the fresh residual, opening is slightly more attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // If this is the last item, opening a new bin is only worth it for a perfect fit
        if next_item_size == 0 && item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // --- Open bins pressure: mild reward for filling existing bins as bins accumulate ---
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // --- Mean residual coupling: prefer bins below mean residual (fill emptier-targeted bins) ---
    score += 0.05 * (post_residual as f64 - mean_residual);

    // --- Lookahead synergy: perfect pairing bonus (item + next item exactly fill) ---
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill bin exactly
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportionally to how much of the gap is consumed
            let gap = post_residual as f64;
            let consumed = next_item_size as f64 / gap;
            score -= 40.0 * consumed * consumed;
        } else {
            // next item cannot fit here: penalize large dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Tightness reward: prefer bins where the current item fits snugly.
    let slack = (bin_residual - item_size) as f64;
    score += 0.3 * (slack as f64).powi(2) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual across open bins: prefer bins
    // whose post residual is below average (concentrating waste in fewer bins).
    score += 0.4 * (post_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when no open bin offers a good
    // lookahead chain. Penalize opening a new bin mildly, more when many bins open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // if lookahead fits perfectly elsewhere, new bin is unattractive already;
        // if nothing fits well, this penalty is small enough to allow opening.
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize dead space: residuals too small for any plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead: bonus if next item fits the post residual perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state: prefer filling bins when many bins are open
    let open_f = open_bins_count as f64;
    score -= (open_f / (open_f + 5.0)) * 10.0;

    // Time horizon: early in stream, be conservative (favor tight fits more); later, accept more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Mean residual coupling: penalize bins far from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let base_penalty = 55.0 - 20.0 * progress;
        score += base_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits smoothly
    let fit_tightness = 1.0 - norm_pr;
    score -= 25.0 * fit_tightness * fit_tightness;

    // Penalize wasted space relative to mean residual
    score += 0.3 * (pr as f64 - mean_residual).max(0.0);

    // Last-resort bin bonus
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap;
        if next_item_size as f64 <= pr {
            score -= 10.0;
        }
    }

    // Prefer consolidating into fewer bins as stream progresses
    score += 0.5 * (open_bins_count as f64) * progress;

    // New-bin candidate: keep neutral-to-slightly-high unless very late
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * (1.0 - progress) - 20.0 * (1.0 - fit_tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: residual in {0} -> perfect fit, big reward.
    // Class 1: residual divisible into small harmonic chunks (<= 10) -> very good.
    // Class 2: residual 11..=20 -> decent (most items fit again).
    // Class 3+: large awkward residual -> penalize mildly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual > 50 {
        score += 15.0;
    }

    // Modulo structure: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be filled exactly later.
    let harmonic_bonus: f64 = if post_residual % 10 == 0 {
        12.0
    } else if post_residual % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a chained perfect fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits; reward proportional to how snugly it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - nest / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: slight penalty for
            // leaving space that will strand.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when no open bin offers a tight fit. Base its score on mean residual
    // pressure: many open bins with slack -> discourage new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = bin_capacity as f64 * 0.75;
        score = base
            + 0.35 * mean_residual
            + 10.0 * open_bins_count as f64 * (1.0 - progress)
            - 45.0 * progress;
        if fitting_bins_count == 0 {
            score -= 150.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // roomy bin helps larger follow-up items
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Small global regularization toward mean residual: bins far from the
    // pack's average slack get nudged, balancing load across open bins.
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps super-linearly.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: the closer post_residual is to 0 (without dead space), the better.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // when few bins are open, opening a new one is relatively cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 12.0 + bin_pressure * 6.0 + progress * 10.0;
        // But reward opening a new bin if the item is large and wouldn't leave useful space elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space relative to next item: penalize.
            score += (next_item_size - post_residual).min(20) as f64 * 0.5;
        }
    }

    // Mild preference for bins below mean residual (keeps large gaps consolidated).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: this placement keeps the bin useful.
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0;
            if slack_after_next == 0 {
                score -= 25.0; // perfect 2-item chain
            } else {
                // penalize leftover that is too small to be useful later
                if slack_after_next < 10 {
                    score += 4.0;
                }
            }
        } else {
            // Next item won't fit here: mild penalty proportional to gap,
            // unless post residual is very small (dead space anyway).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual >= 10 {
                score += 0.15 * gap;
            } else {
                score -= 2.0; // bin effectively closed, fine
            }
        }
    }

    // Compare post residual to mean residual across open bins:
    // leaving less than average is good (efficient packing).
    score -= 0.5 * (mean_residual - post_residual as f64).max(-20.0).min(20.0);

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 - 0.5 * crowd - 5.0 * progress;
        // If the item is large and no good fit exists, new bin is more acceptable.
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer filling older/more crowded bins when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already the base).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: slight penalty to keep flexibility, prefer fullest bin.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let la_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - la_waste as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Prefer bins that are already more filled than average.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let mut penalty = 60.0;
        if fitting_bins_count == 0 {
            penalty = -5.0;
        } else if fitting_bins_count == 1 {
            penalty = 20.0;
        }
        // Later in the stream, be more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 30.0 * progress;
        score += penalty;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating.
    if open_bins_count > 2 {
        score -= 0.5 * mean_residual / open_bins_count as f64;
    }

    // Early stream: be slightly exploratory, allow opening bins for large items.
    if step_index < total_items / 10 && item_size > bin_capacity / 2 && bin_residual == bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let it_norm = it / cap;

    // Core: quadratic penalty on wasted space, sharpened late in the stream.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * pr_norm * pr_norm * (1.0 + progress);

    // Reward filling bins deeply (small post residual relative to item size).
    score -= 25.0 * (it_norm / (pr_norm + 0.05)) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Smoothly discourage leaving dead space that cannot fit the lookahead item,
    // as a smooth function of mismatch rather than a hard cutoff.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr_norm - nx).max(0.0);
        let fits_next = (pr >= next_item_size) as f64;
        score += 12.0 * gap * (1.0 - fits_next) * (1.0 - 0.5 * progress);
        // Reward leaving room exactly usable by the next item.
        score -= 8.0 * (1.0 - gap.min(1.0)) * fits_next;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    let mean_dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * mean_dev * (1.0 - progress);

    // New-bin candidate (empty bin) gets a mild inherent handicap so it only wins
    // when open bins would create very large dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) - 10.0 * it_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;

    // Perfect-fit classes (residuals that small items can exactly fill) get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Penalize awkward dead space: residuals in (20, 40) are hard to fill with
    // items of size 10..80 unless a small item exists; lookahead helps decide.
    if post_residual > 20 && post_residual < 40 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0; // lookahead item can use the gap
        } else {
            score += 12.0; // likely dead space
        }
    }

    // Large residuals are fine but slightly less attractive than tight fits.
    if post_residual > 50 {
        score += 4.0;
    }

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer filling open
    // bins unless the fit is terrible; reward it when the item is large.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score -= 6.0; // big items start fresh bins well
        } else {
            score += 10.0; // small items should go into existing bins
        }
    }

    // Modulo coupling: residuals that are multiples of 5 align with item-size
    // granularity and are easier to fill later.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Stream progression: late in the stream, prefer tighter packing
    // (smaller post-residuals weigh more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Prefer bins whose residual is below the mean residual (tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    // Crowding: many open bins -> favor consolidating into existing bins.
    if open_bins_count > 4 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste; residuals that cannot host the lookahead item are also waste.
    if post_residual < 10 {
        score += 40.0; // unusable gap
    }
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0; // cannot host the next item
    }

    // Reward perfect / near-perfect fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Reward residuals that exactly fit the lookahead item (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; discourage opening new bins when plenty are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * progress * (open_bins_count as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "ragged" bin — finishing it off is good (low post_residual already
    // favored), but leaving it ragged is bad.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate baseline: opening a new bin should only win when the
    // item fits terribly everywhere else. Give the empty bin a moderate default
    // score, penalized more when many bins are already open.
    if bin_residual == bin_capacity {
        score = 35.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        // If lookahead is small, a fresh bin keeps large residuals flexible.
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size).
    let tightness = post_residual as f64 / (bin_residual as f64).max(1.0);
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: next item seals this bin
        } else if next_item_size <= post_residual {
            // partial chaining: leftover after chaining
            let chain_left = post_residual - next_item_size;
            score -= 40.0 - chain_left as f64;
        } else {
            // next item cannot fit here: dead-space penalty grows with gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.8;
        }
    } else {
        // last item: prefer minimal post residual
        score -= 10.0;
    }

    // Compare post_residual against mean residual: avoid making this bin much
    // emptier than the fleet average (fragmentation control).
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bins are
    // nearly full on average or no good fit exists.
    if bin_residual == bin_capacity {
        let fleet_fullness = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0
            - fleet_fullness * 40.0
            - progress * 10.0
            - if fitting_bins_count == 0 { 70.0 } else { 0.0 };
        // lookahead: a fresh bin is great if next item pairs with this one
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let pair_left = bin_capacity - item_size - next_item_size;
            new_bin_score -= (30.0 - pair_left as f64).max(-30.0);
        }
        score = score.max(0.0) + new_bin_score.max(-80.0);
    }

    // Mild pressure to consolidate into fewer bins as open bins accumulate.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus (zero waste).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item (1..100 range, min 1).
    if post_residual > 0 && post_residual < 12 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 14.0 - 0.4 * chain_fit;
    }
    // If next item almost fits (small top-up needed), mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 15 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let avg_fit_waste = (mean_residual - item_size as f64).max(0.0);
        // Opening a new bin is cheap early (many items remain to fill it) or when
        // open bins have large residuals that would be badly fragmented.
        let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        let new_bin_value = 30.0 * (1.0 - horizon) + 0.35 * avg_fit_waste
            - 2.0 * (open_bins_count as f64);
        score = 60.0 - new_bin_value;
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if tightness > 0.85 && bin_residual != bin_capacity {
            score += 50.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than spreading.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Mild time preference: late in the stream, waste matters more (no future items
    // to fill leftover gaps), so tighten fitting further.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_curve = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0;
    let mut score = pr * progress_curve;

    // Penalize small dead space more aggressively as stream progresses
    let dead_penalty = (1.0 - norm_pr).powi(6);
    score += dead_penalty * (10.0 + 40.0 * progress);

    // Reward tight fits (small post_residual) with non-linear bonus
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Lookahead coupling: penalize wasting residual needed by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += waste * (5.0 + 10.0 * progress);
        // reward leaving exactly enough room for next item
        let exact = (pr - nx).abs() / cap;
        score -= (1.0 - exact).powi(4) * 6.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 15.0 - 20.0 * avg_tightness * avg_tightness;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" classes (small, or exactly matching common future item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if pr <= 30 {
        score += 5.0;
    }

    // Integer-division thresholds on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score += 15.0; // leaving more than half a bin is wasteful
    } else if pr > quarter {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 40.0;
        } else if slack <= 10.0 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        }
    }
    // If next item cannot use the leftover, penalize proportionally
    if next_item_size > pr && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 60.0;
        if fitting_bins_count == 0 {
            score -= 120.0; // must open a new bin
        } else if mean_residual > (item_size as f64) * 1.5 {
            score -= 30.0; // open bins are too full/fragmented anyway
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (10-class) are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Progress coupling: late in the stream, be more frugal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 5 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + pressure * 10.0;
    } else {
        score -= pressure * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (avoid leaving many bins in a hard-to-fill state).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, tighten up: prefer minimal waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit bonus
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score -= 20.0 / (1.0 + diff);
        }
        // Penalize if next item cannot fit after this placement
        if post_residual < next_item_size {
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just prefer tightest fit
        score -= 5.0;
    }

    // Tight fit reward relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize creating small unusable dead space (dead zone < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: prefer bins that are already fuller than average
    score -= 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current residuals are very poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin late in stream when open bins are fragmented
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Slight preference for fewer open bins early on
    score += 0.1 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item = item_size as f64;
    let post = post_residual as f64;

    // Reward tight fits: scale advantage for small post-residual (non-linear).
    score -= (bin_capacity as f64 - post).sqrt() * 0.8;

    // Lookahead (k=2): if the next item fits exactly into the leftover, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += post * 0.25;
            if post < 10.0 {
                score -= 3.0; // near-perfect closure is still great
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, decaying as the stream progresses
        // (late in the stream, consolidating is less valuable).
        score += 45.0 - 25.0 * progress;
        // If this item would leave a lot of dead space in a fresh bin anyway,
        // and few bins fit it, opening may be right.
        if fitting_bins_count <= 1 && post > 40.0 {
            score -= 20.0;
        }
        // Many open bins with large mean residual: avoid yet another bin.
        if open_bins_count > 3 && mean_residual > item {
            score += 15.0;
        }
    } else {
        // Mild preference for bins whose residual is close to the item (good fit
        // relative to the fleet), keeping large residuals for large future items.
        let fit_gap = (bin_residual as f64 - item).abs();
        score += fit_gap * 0.05;
    }

    // Small tie-breaker toward fewer open bins early on.
    score += open_bins_count as f64 * 0.01 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let t = progress;
    // Non-linear interaction: tight fits (small pr) are rewarded more as stream progresses.
    let tight = (1.0 - prn) * (1.0 - prn);
    score -= 18.0 * tight * (0.5 + t);
    // Penalize large wasted residual with a cubic term, stronger late in stream.
    score += 12.0 * prn * prn * prn * (0.4 + 0.6 * t);

    // Reward near-perfect fits smoothly (bell-like term).
    let exact = (prn * 4.0 - 0.5);
    score -= 6.0 * (-exact * exact).exp();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin when a decent fit exists,
    // but allow it late in the stream if residuals are large.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 >= mean_residual * 0.5;
        if decent_fit_exists {
            score += 10.0 + 8.0 * (1.0 - t);
        } else {
            score += 2.0 * (1.0 - t);
        }
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 5.0 * (-diff / 20.0 * diff / 20.0);
    }

    // Mild penalty for scattering across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "clean" leftovers
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 15 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    } else if pr > 50 {
        score += 8.0; // large dead space
    }

    // Modulo arithmetic: leftovers that divide capacity evenly are reusable
    let rem10 = (pr % 10) as f64;
    let rem25 = (pr % 25) as f64;
    score -= (10.0 - rem10) * 0.6;
    score -= (25.0 - rem25) * 0.25;
    if pr % 50 == 0 && pr > 0 {
        score -= 15.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 20.0 * (1.0 - nx / cap);
            // harmonic match: next item exactly divides leftover
            if pr % next_item_size == 0 {
                score -= 18.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward gap
            let overshoot = (nx - pr as f64) / cap;
            score += overshoot * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation onto existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += open_bins_count as f64 * 0.15 * (1.0 + progress);

    // Pull toward mean residual: avoid extreme fragmentation
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let base = 55.0 - 10.0 * progress;
        score = base + if fitting_bins_count == 0 { -100.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (below min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item if it could otherwise be used.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward using bins that are already fairly full (small residual before placement).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Tight-fit bonus: item occupies most of the residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.8 {
            score -= 15.0 * (tightness - 0.8);
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        // If item is large relative to capacity, opening fresh is more acceptable.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 35.0;
        }
        // If no open bin fits well, opening a new bin is reasonable.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Discourage placements that leave residuals far from any likely future item size.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals the next item's size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match: next item still fits tightly afterwards.
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 15.0;
    }
    // Next item cannot fit here afterwards: dead space penalty grows with wasted slack.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Penalize residual that is too small to ever be useful (min item size is 1, but tiny slivers are weak).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter packing bins first).
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins would leave very poor fits.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual < next_item_size { 10.0 } else { 0.0 };
        score += 5.0 + poor_fit_penalty;
    }

    // Late in the stream, be slightly more conservative with residual space.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let isz = item_size as f64;
    let mut score = post_residual as f64;

    // Reward near-exact fills (quadratic waste penalty inverted)
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= fill_ratio * fill_ratio * 12.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 8.0 + 0.12 * nx;
        } else if post_residual > 0 && (post_residual as f64) < 0.25 * nx {
            // dead space: leftover too small to ever be useful for typical items
            score += 6.0 + 0.1 * (25.0 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // unless it is the new-bin candidate itself.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    if open_bins_count > 1 && bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    // Time horizon: early on, slightly favor consolidation; late, accept waste
    score += t * 4.0;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: leftover space it will carry,
        // plus an opening tax that shrinks if existing residuals are poor.
        let new_leftover = cap - isz;
        let poor_existing = (mean_residual - isz).max(0.0); // existing bins can't absorb well
        score = new_leftover + 18.0 - 0.6 * poor_existing + 6.0 * (1.0 - t);
        // If no open bin exists at all, opening is mandatory-ish
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead item is large, opening fresh is more attractive
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, non-linearly (quadratic waste penalty).
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, dead space becomes more costly.
    let waste_norm = pr / cap;
    score += 30.0 * waste_norm * waste_norm * (0.5 + progress);

    // Perfect fit reward (smooth, non-piecewise).
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_frac * fit_frac * (1.0 - 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin, more so early and when
    // open bins have plenty of mean residual (poor utilization).
    let is_new = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new {
        let crowding = mean_residual / cap;
        score += 15.0 + 60.0 * (1.0 - progress) + 25.0 * crowding;
        // Reward a new bin if the next item is large relative to capacity.
        score -= 0.3 * next_item_size as f64;
    }

    // Lookahead coupling: if the next item fits the resulting residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to leftover.
        score += 5.0 * waste_norm;
    }

    // Mild preference to fill already-open bins when many are open.
    score += 0.5 * open_bins_count as f64 * waste_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 and capacity fractions
    let post = post_residual as u32;
    let class = post % 10;
    // Dead-space classes: residuals that are hard to fill (small residues)
    let dead_penalty: f64 = match class {
        0 => -6.0,                 // perfectly reusable slot
        1..=3 => 12.0,             // nearly unusable slivers
        4..=7 => 4.0,
        _ => -2.0,
    };
    score += dead_penalty;

    // Integer-division thresholds on post_residual (capacity fractions)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post == 0 {
        score -= 15.0; // perfect closure is excellent
    } else if post < quarter / 2 {
        score += 10.0; // tiny leftover, wasteful
    } else if post <= half {
        score -= 3.0;  // half-full or less leftover is good
    }

    // Tight fit reward: fraction of bin filled by this item
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if post >= next_item_size {
            // harmonic compatibility: next item lands exactly or with good class
            let next_post = post - next_item_size;
            score -= 4.0;
            if next_post % 10 == 0 { score -= 5.0; }
            if next_post < 4 { score += 5.0; }
        } else {
            // next item won't fit here: mild penalty scaled by gap
            let gap = (next_item_size - post) as f64;
            score += (gap / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // prefer bins whose residual is close to item (best fit among many)
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // base reluctance to open new bins
        let mut nb = 30.0 + 2.0 * open_f;
        // if item is large relative to capacity, new bin is fine
        if fill > 0.6 { nb -= 20.0; }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb -= 10.0 * (1.0 - progress);
        // if existing bins have high mean residual, they can absorb the item
        if mean_residual >= item_size as f64 { nb += 15.0; }
        score += nb;
    }

    // Mild preference to spread load when many bins open and mean residual high
    if open_bins_count > 2 && mean_residual > 50.0 && bin_residual < bin_capacity {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
