pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not wastefully small.
    score = post_residual as f64 * 0.7;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit (post_residual == next_item_size) is ideal.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize creating dead space the next item cannot use,
            // scaled by how much of the leftover is wasted.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Relative-to-mean term: prefer bins that are emptier than average
    // when the fit is loose, keeping tight bins for tight items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (huge dead space vs next item).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish score; only chosen when open bins score worse
    // (poor fits / lookahead dead space). Slight penalty so we consolidate when possible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * (next_item_size as f64);
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere, opening is required
        }
    }

    // Early in the stream, be more willing to spread (open bins) to build flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Penalize large unusable post-residual (dead space below typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 20.0;
        } else if diff > 0 && (diff as u32) < 10 {
            score -= 8.0;
        } else if diff < 0 && (diff.unsigned_abs() as u32) <= 10 {
            score += 4.0; // next item nearly fits; slight penalty for blocking
        }
        // If post_residual could hold next item combined with future small items
        if next_item_size > post_residual && post_residual < 10 {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // discourage opening new bins (new-bin candidate has mean_residual ~ bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_dev = mean_residual - post_residual as f64;
    score += mean_dev * 0.25;

    // Penalize opening new bins more as stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward consolidation when many bins are open.
        score -= (open_bins_count.min(20) as f64) * 0.3 * (1.0 - progress * 0.5);
    }

    // Mild time-horizon term: early on, keep residuals flexible; late, pack tight.
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, dead space
    // becomes less costly since bins are sunk anyway.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear penalty on very small residuals (dead space),
    // peaking via a smooth bump around tiny residuals.
    let bump = (-norm_pr * 12.0).exp() * (1.0 - norm_pr).max(0.0);
    score += 25.0 * bump * (1.0 - 0.5 * progress);

    // Reward using bins when they are scarce relative to mean residual.
    let mean_norm = mean_residual / cap;
    score -= 8.0 * mean_norm * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let room = if pr >= ni { 1.0 } else { 0.0 };
        let smooth = 1.0 / (1.0 + (-(pr - ni) / 10.0).exp());
        score -= 15.0 * room * smooth * (1.0 - progress);
        // Penalize wasting a large bin on a small item when next item is large.
        score += 5.0 * (1.0 - smooth) * (ni / cap);
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress * norm_pr;

    // New-bin candidate: make empty bins moderately attractive only when
    // existing fits are poor (large post_residual) or early stream.
    if bin_residual == bin_capacity {
        score = pr * 0.9 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod capacity/4
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..3 harmonic class
    // Penalize mid-range dead space classes (small but unusable slivers)
    match class {
        0 => score -= 6.0,                       // near-perfect fit
        1 => score += 8.0,                       // awkward sliver
        2 => score += 3.0,                       // half-ish, still useful
        _ => score -= 2.0,                       // large residual, reusable
    }

    // Exact-fill reward
    if post_residual == 0 { score -= 15.0; }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, stronger if next item nearly fills the remainder
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 20.0; } else if gap <= quarter { score -= 9.0; } else { score -= 4.0; }
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 { score -= 30.0; }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to item (tight fits)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 5.0 * tightness * tightness;

    // Slight preference to fill bins below mean residual (balance load)
    score += 0.05 * (mean_residual - post_residual as f64);

    // Prefer fewer open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are pure waste -> quadratically penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward residuals that can still host a mid-size item later.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // bad dead space or are heavily fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by open-bin pressure.
        score = 45.0 + (open_bins_count as f64).sqrt() * 4.0;
        if post_residual < 10 {
            score += 20.0; // shouldn't happen for empty bin, guard anyway
        }
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is natural and cheap.
        score -= mean_residual * 0.35;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Prefer bins whose residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // Fragmentation pressure: many open bins -> favor consolidating
        // into bins with larger residual (avoid spreading thin).
        if open_bins_count > 4 {
            score -= mean_residual * 0.05;
        }
        // Lookahead pairing: if this placement leaves room exactly for
        // the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // blocks the natural next fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-fit_ratio * 8.0).exp();

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-gap / 12.0).exp();
        // Exact match bonus: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: minimize leftover as hard as possible.
        score += 2.0 * post_residual as f64;
    }

    // Compare against mean residual: bins below mean residual are precious, prefer using them.
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Still allow a fresh bin if lookahead fit would be excellent there.
        if next_item_size > 0 {
            let gap_new = (item_size as i64 + next_item_size as i64 - bin_capacity as i64).abs() as f64;
            score -= 20.0 * (-gap_new / 10.0).exp();
        }
        // Later in the stream, be more conservative about opening bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no plausible item can fill.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.8 * unusable;
        } else {
            // Lookahead fits: reward reserving space for the next item.
            score -= 1.5 * (post_residual - next_item_size) as f64 / (1.0 + post_residual as f64);
        }
    } else {
        // Last item: minimize residual exactly.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item is huge and fit would be terrible.
    if bin_residual == bin_capacity {
        let base_penalty = if open_bins_count > 0 { 18.0 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        // Opening a new bin is attractive only if all fits elsewhere would waste a lot.
        score += base_penalty + 0.3 * waste;
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a below-mean-residual bin preserves larger spaces.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 2.0 * dev;

    // Mild pressure to fill nearly-full bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Small penalty for leaving residual in the awkward 1..=9 band.
    if post_residual >= 1 && post_residual <= 9 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // as the stream progresses, tight fits (small post_residual) become
    // increasingly valuable, and large post_residual is penalized super-linearly.
    let prn = pr / cap; // normalized post residual in [0,1]
    let tight = (1.0 - prn) * (1.0 - prn); // smooth tightness measure
    let prog2 = progress * progress;
    score -= 18.0 * tight * (0.5 + prog2);
    score += 12.0 * prn * prn * (0.3 + 0.7 * progress);

    // Reward near-perfect fits with a smooth cubic bonus.
    score -= 6.0 * (1.0 - prn).powi(3);

    // Lookahead coupling: if the next item fits the resulting residual,
    // reward this placement smoothly; otherwise penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gapn = gap / cap;
        score -= 8.0 * (-gapn * gapn * 20.0).exp() * (1.0 - progress);
        score += 3.0 * gapn * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }

    // Mild preference to fill bins when many bins are open relative to mean residual.
    if open_bins_count > 0 {
        score += 0.05 * mean_residual * (open_bins_count as f64).ln() * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity / 4 classes
    let quarter = bin_capacity / 4;
    let post_class = (post_residual / quarter) as f64;
    score += post_class * 6.0;

    // Dead space penalty: residuals that cannot host even the smallest item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead item: perfect chain reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // residual too small for next item: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / bin_capacity as f64) * 30.0;
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Integer-division threshold on next_item_size class
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size / 20) + 1 };
    match next_class {
        1 => score -= 4.0,   // tiny next item: residual is easy to reuse
        2 => score -= 1.0,
        3 => score += 2.0,
        _ => score += 5.0,   // large next item: want a roomy bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score = 100.0 - 40.0 * tightness
            + if next_item_size > 0 && next_item_size <= bin_capacity / 2 { 8.0 } else { 0.0 }
            + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 80.0; // forced new bin
        }
    }

    // Late-stream consolidation: prefer packing into fewer bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mild alignment with mean residual: prefer bins near the mean to keep balance
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything (min item size 1, but realistically small gaps) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 8.0;  // marginal gap
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // New-bin candidate: only attractive if current fit is poor or bin is fresh.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual >= 60 {
            score -= 4.0; // roomy new bin for future items
        }
        if fitting_bins_count > 0 {
            score += 12.0; // discourage opening when an open bin fits well
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean residual coupling: bins far below mean residual are good targets.
    score -= 0.05 * ((mean_residual - bin_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (chains placements perfectly).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + match_gap);
        // Perfect chain bonus: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large waste relative to capacity (dead space).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 0.8 * waste * waste * bin_capacity as f64;

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it moderately attractive only when no good fit
    // exists (post_residual large means poor fit into existing bins).
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins early in stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals that can't fit even the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover space
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fill;
        } else {
            // next item won't fit here: slight penalty proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins (avoid bin sprawl).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be more conservative — prefer filling
    // existing bins fully; early on, allow opening bins for better structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bin attractive only when item is large
    // (would leave awkward remainder in existing bins) or mean residual is low.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 40.0
            - 25.0 * large_item
            + 6.0 * (mean_residual / bin_capacity as f64)
            - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-nonzero residuals with a smooth quartic trough.
    let tight = (1.0 - pr_norm).clamp(0.0, 1.0);
    score -= 18.0 * tight * tight * tight * tight;

    // Reward bins whose residual matches the lookahead item smoothly.
    if next_item_size > 0 {
        let match_term = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 6.0 * match_term.max(0.0) * (1.0 - progress);
    }

    // Mild penalty when many bins fit; strong reward when this is the last chance.
    let last_chance = if fitting_bins_count <= 1 { -12.0 } else { 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0) };
    score += last_chance;

    // Discourage hoarding residual when mean residual is high (smooth coupling).
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless the fit is very tight (pr_norm term already rewards tight fits).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong penalty for leaving awkward dead space
    if post_residual > 0 {
        score += (post_residual as f64 / cap) * 30.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: post_residual in small classes is highly usable
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 20.0; // small residual still useful for tiny items
    } else if pr > 10 && pr <= 25 {
        score += 8.0;
    } else if pr > 25 && pr <= 50 {
        score += 18.0;
    } else if pr > 50 {
        score += 30.0; // half-empty bin: wasteful unless item is huge
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 70.0; // must open a new bin
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 50.0;
        } else if diff <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - diff as f64 / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; residual becomes dead space
        score += 15.0;
    }

    // Prefer filling already-open bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Slight preference for bins below mean residual (balance avoidance of many half-full bins)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers are unusable for future items (min item 1, but
    // practically gaps below ~12 rarely get filled). Penalize them super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Lookahead: if the next item fits the post residual, reward; otherwise penalize
    // leaving a residual that is "almost but not quite" the next item's size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(5) {
            score += 5.0; // near-miss gap: likely dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing
    // bins (penalize the new-bin candidate implicitly via its large residual, but add
    // mild pressure proportional to open bins for small residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it is a laggard
    // bin; filling it consolidates state.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate handling: empty bin has residual == capacity. Make it mildly
    // attractive only when no tight fit exists elsewhere, i.e. its raw residual keeps
    // it competitive, but add a fixed opening cost so tight fits always win.
    if bin_residual == bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact-fit bonus: item perfectly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward if the NEXT item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        // Extra reward for near-perfect two-item packing.
        if slack_after_next == 0 {
            score -= 45.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving post_residual that the next item cannot use (dead space risk).
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // Compare post_residual against mean residual: prefer bins whose leftover stays small.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 55.0;
        // If many bins fit, opening a new one is rarely useful.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If this is the only fitting option (no open bin fits), new bin is the fallback.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer closing out open bins rather than spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin may serve it better.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Mild penalty for accumulating many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that no future small item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot fit here; slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation into tightest bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > (item_size as f64) * 1.5 {
        score += 5.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, avoid opening new bins / leaving big residuals
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fits are all poor
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fill_ratio < 0.55);
        if poor_fits {
            score -= 15.0;
        } else {
            score += 40.0;
        }
    }

    // Mild preference for bins with smaller residual overall
    score += 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, small residuals are fine (bins fill gradually); late in the
    // stream, dead space becomes costly, so penalize quadratically.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits with a smooth saturating term of item_size.
    let fit_ratio = item_size as f64 / cap;
    score -= 25.0 * fit_ratio * (1.0 - fit_ratio);

    // Smooth last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward
    // this placement smoothly; otherwise add a mild smooth penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 10.0 * ((nxt - post) / cap) * (0.5 + progress);
        }
    }

    // Penalize bins whose residual deviates from the mean (fragmentation
    // smoothing), scaled smoothly by how many bins are open.
    let dev = (post - mean_residual).abs() / cap;
    score += 8.0 * dev * (1.0 + (open_bins_count as f64).ln());

    // Mild penalty for spreading across too many open bins early.
    score += 2.0 * (open_bins_count as f64 / (1.0 + total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: classify dead space quality
    // post_residual in 1..=9 is nearly dead space -> strong penalty
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }
    // Small but potentially useful residue classes (10..20) mild penalty
    else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Integer division thresholds: how many items of min size (1) or typical size fit
    let fits_small = post_residual / 10;
    let fits_mid = post_residual / 25;
    score -= 8.0 * fits_small as f64;
    score -= 4.0 * fits_mid as f64;

    // Capacity fraction coupling: residue as fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Modulo arithmetic on post_residual vs next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // exact lookahead fit
        } else if post_residual >= next_item_size {
            score -= 25.0; // lookahead can still use this bin
            let slack = post_residual - next_item_size;
            if slack <= 9 {
                score += 10.0; // leaves near-dead space after lookahead
            }
        } else {
            score += 30.0; // lookahead cannot use this bin's residue
        }

        // modular resonance: post_residual % next_item_size small => chain fits
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 5 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 120.0;
        // more attractive early in stream or when many bins are congested
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 30.0; // open bins are tight, new bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean residual coupling: penalize creating bins far below mean (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Progress-based tiebreak: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let residual_f = bin_residual as f64;
    let post_f = post_residual as f64;
    let next_f = next_item_size as f64;
    let open_f = open_bins_count as f64;
    let item_f = item_size as f64;
    let mean_res_f = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };
    let progress_f = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let lookahead_f = if next_f > 0.0 {
        (1.0 - progress_f).clamp(0.20, 1.0)
    } else {
        0.0
    };
    let is_new_candidate = bin_residual == bin_capacity;

    let mut score = post_f
        + 0.055 * post_f * post_f / capacity_f
        + 0.015 * post_f * (1.0 + 0.04 * open_f);

    if post_residual == 0 {
        score -= 10.0 + 8.0 * (1.0 - progress_f);
    }

    if next_f > 0.0 && post_f > 0.0 && post_f < next_f {
        let gap_f = next_f - post_f;
        let alternative_residual_f = residual_f.max(capacity_f - item_f);
        let alternative_advantage_f = (alternative_residual_f - post_f).max(0.0);

        let mut dead_penalty_f = 4.0
            + 0.55 * gap_f
            + 0.022 * gap_f * gap_f
            + 0.075 * alternative_advantage_f;

        dead_penalty_f *= lookahead_f;

        if is_new_candidate && fitting_bins_count == 0 {
            dead_penalty_f *= 0.30;
        }

        score += dead_penalty_f;
    } else if next_f > 0.0 && post_f == next_f {
        score -= 4.0 + 5.0 * lookahead_f;
    }

    if is_new_candidate {
        let mut new_bin_penalty_f = 3.0
            + 0.22 * open_f
            + 0.045 * mean_res_f
            + 7.0 * progress_f
            + 0.10 * fitting_bins_count as f64;

        if fitting_bins_count > 0 {
            new_bin_penalty_f += if fitting_bins_count == 1 { 7.0 } else { 1.5 };
        } else {
            new_bin_penalty_f -= 50.0;
        }

        score += new_bin_penalty_f;
    } else {
        score -= 0.03 * open_f * (0.5 + progress_f);
        score -= 0.02 * (mean_res_f - residual_f).max(0.0);

        if fitting_bins_count == 1 {
            score -= 5.0 + 5.0 * progress_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: strongly reward small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post_residual, this is a perfect chain -> big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 60.0; // exact 2-step chain
            } else {
                // reward proportional to how close next item fills remainder
                let fill = 1.0 - gap / post;
                score -= 25.0 * fill * fill;
            }
            // penalize leaving a remainder that nothing small could use
            if gap > 0.0 && gap < 10.0 {
                score += 15.0; // dead space trap
            }
        } else {
            // next item can't fit here regardless; mild penalty for hoarding space
            score += 5.0;
        }
    }

    // Compare against mean residual: bins with more free space than average
    // are better donors for large items; prefer filling below-average bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // (post_residual very small means good fit, so new bin should lose).
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead shows next item is huge and this fit is poor, opening
        // a fresh bin is attractive.
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 * 2.0 {
            score -= 25.0;
        }
    }

    // Late in stream, consolidation matters more: avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score += tightness * tightness * 120.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new-bin candidate mildly; escalate when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is attractive if lookahead item pairs with full empty space.
        if next_item_size > 0 && (next_item_size as f64 + post_residual as f64) <= bin_capacity as f64 {
            // empty bin has residual = capacity; check pairing with item itself
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 15.0; // fresh bin could host a clean pair
        }
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Prefer bins below mean residual (more packed bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = norm_post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: waste penalized more later
    let progress_coupling = norm_post * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward using existing bins vs opening new ones (smooth in open_bins_count)
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let openness = (open_bins_count as f64).sqrt() / (1.0 + (open_bins_count as f64) * 0.05);
    score += new_bin * (1.0 + openness) * (0.8 - 0.6 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && new_bin < 0.5 {
        score -= 3.0;
    }

    // Lookahead: penalize leaving residual that barely fails the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 0.5 * (1.0 - (nxt - post) / cap);
        } else {
            score -= 0.3 * (post / nxt - 1.0).min(1.0);
        }
    }

    // Mean residual alignment: prefer bins whose residual is near mean (smooth)
    let dev = (post - mean_residual).abs() / cap;
    score += 0.2 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
