pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward placements that leave room for a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasted gap that can't hold the lookahead item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, plus pessimism
        // about future consolidation as the stream progresses.
        score += 15.0 + open_pressure * 0.5 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
    } else {
        // Slight reward for choosing bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Mild pressure to consolidate into fewer bins when few are open.
        score -= open_pressure.min(10.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual exactly matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match gets a strong bonus.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize post_residual that is slightly larger than next item (dead space).
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 25.0;
        }
    } else {
        // Last item: simply minimize waste.
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tight" bins — prefer filling them to close them out.
    let tightness = mean_residual - post_residual as f64;
    score -= 0.35 * tightness;

    // Penalize leaving post_residual that nothing small could use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // tiny unusable sliver: good, we squeezed the bin
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the
    // current bins would leave a lot of fragmented dead space.
    if bin_residual == bin_capacity {
        // A new empty bin leaves post_residual = capacity: large residual is
        // penalized by the base term already. Add extra opening cost, reduced
        // late in the stream when consolidation matters less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 * (1.0 - 0.5 * progress);
        // But if no open bin fits well (fitting_bins_count is 0 for open bins),
        // the new bin is the only option — soften the penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for bins with larger pre-placement residual when
    // post_residuals tie (keeps small bins closable).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild stream-progress term: early on, spread items; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still fit here.
            score -= 4.0;
        } else {
            // Dead space relative to lookahead item.
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.35 * waste;
        }
        // Bonus if post_residual exactly accommodates the next item (perfect chain).
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If item is large relative to capacity, opening a fresh bin is more attractive.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // Early in the stream, be more willing to open bins (build diversity of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean residual (consolidate space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Slight penalty for very small unusable leftovers.
    if post_residual < 10 && post_residual > 0 {
        score -= 3.0; // small dead space is fine if bin is nearly full
    }

    // Mild preference for bins with larger residual when many bins are open (balance load).
    score -= 0.02 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Base: strongly reward tight fits (non-linear in post_residual)
    score += 40.0 * norm_pr * norm_pr;
    score -= 30.0 * norm_item * (1.0 - norm_item);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate slack, late in stream punish residual waste harder
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * norm_pr * norm_pr * prog_term;
    score += 15.0 * norm_pr * prog_term;

    // Lookahead coupling: post_residual polynomial vs next item size
    if next_item_size > 0 {
        let fit_next = (norm_pr - norm_next).max(0.0);
        let exact_next = 1.0 - (norm_pr - norm_next).abs().min(1.0);
        // reward residual that exactly fits next item (smooth)
        score -= 20.0 * exact_next * exact_next * (1.0 - prog_term);
        // penalize residual that is slightly larger than next item (dead space)
        score += 12.0 * fit_next * (1.0 - fit_next) * (1.0 - prog_term);
    } else {
        // last item: prefer fullest packing
        score += 50.0 * norm_pr;
    }

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr * norm_pr);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // penalize opening new bin mildly, more as stream progresses
        score += 30.0 + 20.0 * prog_term;
        // but if current item is large, new bin is attractive
        score -= 25.0 * norm_item * norm_item;
    }

    // Context: many open bins with high mean residual -> discourage adding slack
    let norm_mean = mean_residual / cap;
    score += 8.0 * norm_mean * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the post-residual modulo small divisors.
    let r10 = post_residual % 10;
    let r5 = post_residual % 5;

    // Reward residuals that fall into "usable" harmonic classes for
    // typical item sizes (multiples of 5/10 dominate many streams).
    if post_residual >= 10 {
        score -= 8.0;
        if r10 == 0 {
            score -= 6.0; // residue is a multiple of 10: very reusable
        } else if r5 == 0 {
            score -= 3.0; // multiple of 5: reusable
        }
    } else if post_residual >= 5 {
        score -= 2.0;
        if r5 == 0 {
            score -= 1.5;
        }
    } else {
        // tiny dead space: penalize
        score += 4.0;
    }

    // Integer-division thresholds: how many "average" items still fit?
    let avg_item = 45u32;
    let fits_avg = post_residual / avg_item;
    score -= fits_avg as f64 * 5.0;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
            // harmonic match of slack
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't fit here: mild penalty scaled by gap class
            let gap = next_item_size - post_residual;
            let gap_class = gap / 10; // integer division threshold
            score += 3.0 + gap_class as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // residuals are poor (large mean residual means open bins are empty-ish,
    // so reuse is fine; small mean residual means bins are nearly full).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 60.0;
        // if existing bins are nearly full (low mean residual), opening is OK
        score -= (100.0 - mean_residual).max(0.0) * 0.4;
        // late in the stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (< ~10) are nearly unusable
    // given typical item sizes; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Moderately small gaps are also risky dead space.
        score += 15.0;
    }

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact match with lookahead item: reserve this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement kills the lookahead's chance to reuse the bin.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many bins open, prefer tighter packing;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when it looks genuinely better
    // than squeezing into a poor residual. Make new bin mildly unattractive
    // by default, but attractive if the current bin would leave bad waste.
    if bin_residual == bin_capacity {
        score = 100.0 - 30.0 * pressure.min(1.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Progress-based mild tightening: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins that the item fills almost exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item can fit into the
    // post-residual of this bin, this placement chains nicely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Reward tight chaining: next item leaves little dead space too.
            let chain_waste = post - nxt;
            score -= 20.0 - chain_waste.min(20.0);
        } else {
            // Next item cannot follow into this bin: penalize leaving
            // residual that is too small to be useful later.
            if post < 10.0 {
                score += 15.0; // dead space penalty
            }
            // If this bin was the item's only chance, prefer using it anyway.
            if fitting_bins_count == 1 && bin_residual != bin_capacity {
                score -= 25.0;
            }
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is poor (large post_residual) and the item has other options.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin starts with a big residual; make it unattractive unless
        // no open bin fits or existing fits are wasteful.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if post_residual as f64 > mean_residual {
            // Item would leave more waste than average: consider new bin.
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Slight preference for tighter bins relative to the mean residual.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early in the stream, allow more freedom to open bins; later, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score -= 5.0 * (1.0 - post as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let tight = 1.0 - post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly (non-linear)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 8.0 + 3.0 * (1.0 - progress);
    } else if post_residual <= 20 {
        score -= 2.0;
    }

    // Penalize leaving dead space that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead zone below min item size
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with smaller residual among comparable fits (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Crowding: many open bins -> prefer filling existing ones
    score += 0.3 * open_bins_count as f64 * (1.0 - tight);

    // New-bin candidate handling: empty bin gets a penalty so we only open
    // a new bin when no open bin fits well (large item, poor alternatives)
    if bin_residual == bin_capacity {
        let base = 30.0;
        // If item is large, opening fresh may be fine; scale penalty down
        let large_relief = 20.0 * fill;
        // Late in stream, prefer closing out existing bins
        let late_extra = 15.0 * progress;
        // If few bins fit the item, opening new is less costly
        let scarcity_relief = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        score += base - large_relief - scarcity_relief + late_extra;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Class 0: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space classes: residuals 1..=9 are nearly unusable (min item = 1,
        // but statistically small slivers waste capacity). Penalize modulo classes.
        let r = post_residual;
        if r <= 9 {
            score += 25.0; // tiny sliver: unusable dead space
        } else if r <= 20 {
            score += 8.0;  // only fits small items
        }
        // Harmonic penalty: finer granularity near zero waste.
        // score += k / (r+1) shape rewards larger residuals mildly.
        score += 40.0 / (r as f64 + 1.0);
        // Integer-division thresholds: classify residual into deciles of capacity.
        let decile = (r * 10) / bin_capacity; // 0..9
        score += (decile as f64) * 0.5;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // residual exactly hosts the next item: excellent chaining
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 9 {
                score -= 20.0; // next item leaves a tiny-but-tolerable remainder chain
            } else {
                score -= 12.0 / (slack as f64); // harmonic decay of lookahead benefit
            }
        } else {
            // Next item cannot fit here: residual risk of stranded space.
            score += 6.0;
        }
    } else {
        // Last item of stream: only tightness matters.
        score -= 10.0;
    }

    // --- Last-chance bonus: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; slightly above a good fit,
        // below a bad fit. Scale mildly with stream progress and open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 15.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // If the item is small relative to capacity, new bin is less wasteful.
        score -= (bin_capacity - item_size) as f64 * 0.1;
    } else {
        // Mild preference for bins whose residual is close to the mean (balance).
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Slight preference for tighter fits generally (post_residual already does this).
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size (1..=10)
    // are effectively wasted, so add a nonlinear penalty there.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity,
    // the better the packing efficiency.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 40.0;

    // Dead-space penalty: post_residual that cannot fit the next item is worse
    // if a lookahead item exists.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 1 {
        score += 15.0;
    }

    // Reward a bin that can also fit the next item (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than fragmenting capacity; penalize new-bin tendency.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Allow opening a new bin only when the current fit would leave a lot of
    // dead space (poor fit) and there are already several open bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Good fits into existing bins should beat opening a new bin.
        if fit_ratio > 0.6 {
            score += 30.0;
        } else if fit_ratio < 0.35 {
            // Very small items: opening a fresh bin is wasteful, keep filling.
            score += 20.0;
        } else {
            // Moderate fit: mildly discourage new bins, existing-bin pressure
            // via open_bins_count term will dominate when many bins are open.
            score += 5.0;
        }
    }

    // Mean-residual coupling: if open bins already have plenty of residual space
    // on average, prefer placing into them (penalize new bin less if mean residual
    // is low, i.e. open bins are nearly full).
    score -= (mean_residual / bin_capacity as f64) * 8.0;

    // Slight preference for bins whose residual is close to the mean residual
    // (keeps bin states homogeneous, easier future packing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += gap * 0.6;
        }
        // If next item also fits after this placement, mild extra reward.
        if post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave large unusable waste.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        score -= 5.0 + waste_penalty * 0.4;
        // Discard new-bin option early in the stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny slivers are actually fine (near-perfect fit)
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // If next item cannot fit in the leftover, mildly penalize large leftovers.
    else if next_item_size > 0 {
        score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins over emptier ones (best-fit bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins / using fresh space.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 25.0 + 0.5 * open_bins_count as f64 + 0.2 * mean_residual;
        // Early in the stream, opening new bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin may be justified.
        if post_residual >= (bin_capacity - item_size) && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    } else {
        // Using an existing bin with residual above mean is slightly favored.
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = post * (1.0 + 0.02 * (post / cap) * (post / cap) * 100.0 / cap * 100.0);
    // Smooth polynomial coupling of post_residual with stream progress.
    score += 8.0 * (post / cap) * (post / cap) * (1.0 - progress);
    score -= 12.0 * (post / cap) * progress;

    // Dead-space penalty: residuals too small for any plausible future item.
    let dead = (post / cap).clamp(0.0, 1.0);
    score += 15.0 * dead * dead * dead;

    // Lookahead: reward if next item fits the post residual, penalize otherwise.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 10.0 * (1.0 - post / cap);
        } else {
            score += 6.0 + 4.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - post / cap);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - post) / cap;

    // New-bin candidate: penalize opening a new bin, more so early and when
    // decent fitting bins exist; relax late in the stream for consolidation.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = cap * (1.0 + fit_pressure) - 15.0 * progress * fit_pressure;
        if next_item_size > 0 && (next_item_size as f64) >= item {
            score -= 5.0; // new bin useful for upcoming larger item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    // Classes: 0 = perfect fill (residual 0), 1 = tiny gap (<=10), 2 = small (<=25),
    // 3 = medium (<=50), 4 = large (>50).
    let class = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    // Reward tight fits strongly per class.
    let class_bonus: f64 = match class {
        0 => 40.0,
        1 => 28.0,
        2 => 16.0,
        3 => 5.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // small item sizes (10, 20, 25, 50) remain "usable" by future items.
    let usable = post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0;
    if usable {
        score -= 6.0;
    }

    // If the next item fits exactly in the post residual, big reward (pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it packs.
        score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., the best open residual is small relative to the item) or the stream
    // is early and we want capacity buffer.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // A fresh bin has residual 100; its raw score is 100. Apply corrections:
        // penalize it when open bins exist that fit (encourage consolidation),
        // but discount that penalty late in the stream when fragmentation is high.
        if open_bins_count > 0 {
            let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score += 30.0 * (1.0 - 0.5 * fragmentation) * (1.0 - 0.4 * progress);
        }
        // Small bonus for a fresh bin when the item is large and next item is large too.
        if item_size >= 60 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference to spread load when many bins are open and mean residual
    // is high (balance residuals across bins).
    score -= 0.05 * open_bins_count as f64 * (post_residual as f64 - mean_residual).signum().max(0.0);

    // Small progress-based tie-breaker to keep determinism stable.
    score += 0.001 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that no plausible future item (1..=100) can use well.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward using bins that are already fairly full (small bin_residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 0.35;

    // Prefer bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize wasting this bin's space.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless all else is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
        // But if no open bin fits well, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: if mean residual is large, prefer consolidating.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Stream progression: mild tightening pressure late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    score = 0.6 * post_residual as f64 + 0.4 * (item_size as f64 / bin_capacity as f64) * post_residual as f64;

    // Dead-space penalty: post_residual too small to ever be useful (< 10 units assumed min item size).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining bonus: next item exactly consumes remaining space.
            let chain_gap = post_residual - next_item_size;
            score -= 30.0 - 0.8 * chain_gap as f64;
            if chain_gap == 0 {
                score -= 20.0; // perfect 2-item fill
            }
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Compare against mean residual: bins already much looser than average are better dumping grounds.
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if no open bin fits well
    // (i.e., the item is large relative to typical residuals) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let tight_fit_elsewhere = mean_residual > 0.0 && (item_size as f64) > mean_residual * 0.8;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // New bin can chain the next item too.
            score -= 10.0 + 20.0 * progress;
        } else if tight_fit_elsewhere {
            score += 30.0; // keep item in existing loose bins
        } else {
            score -= 5.0;
        }
        // Discourage hoarding many open bins late in the stream.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference to fill older/scarcer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: squared post-residual punishes wasted space nonlinearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item can still fit in the post-residual,
    // reward this placement (bin stays usable); otherwise penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item's demand.
            let dead = (post_residual as f64) / next_item_size.max(1) as f64;
            score += 6.0 * dead;
            // Extra penalty if post-residual is a tiny unusable sliver.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins with slack -> prefer filling existing bins.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 5.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: early in the stream, be more liberal about opening bins
    // (long future amortizes flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus a discount that decays over time.
        let mut new_bin_score = bin_capacity as f64 * 0.55 + 12.0;
        new_bin_score -= 18.0 * (1.0 - progress);
        // If nothing else fits well (high mean residual), opening a new bin is attractive.
        new_bin_score -= 10.0 * (mean_residual / bin_capacity as f64);
        // Never open a new bin when a perfect fit exists elsewhere is handled by
        // other bonuses; keep new-bin score moderate otherwise.
        score = new_bin_score;
    } else {
        // Late in the stream, tighten packing further.
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Reward large items going into bins with just enough room (harmonic pairing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * (fill_ratio - 0.85);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Penalize small-but-nonzero residuals more as stream progresses (dead space)
    let dead_weight = 1.0 + 3.0 * progress * progress;
    let small_penalty = (1.0 - norm_pr).powi(3) * (norm_pr * 10.0) * dead_weight;
    score += small_penalty * 6.0;

    // Reward near-zero residuals (perfect fit), amplified over time
    let perfect_reward = (1.0 - norm_pr).powi(12) * (1.0 + 2.0 * progress);
    score -= perfect_reward * 25.0;

    // Interaction: post_residual vs mean residual — prefer bins below mean residual (tighter packs)
    let mean_gap = mean_residual - pr;
    score -= mean_gap * (0.5 + progress) * 2.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(4.0) * (2.0 + 4.0 * progress);
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - (pr - nxt) / cap).powi(4) * (10.0 + 15.0 * progress);
        } else {
            score += 8.0 + 12.0 * progress;
        }
    }

    // New-bin candidate: make empty bins moderately attractive only early or when residuals are poor
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.6 + 0.4 * progress) - 20.0 * avg_tightness * (1.0 - progress);
    }

    // Mild open-bin pressure: discourage spreading across many bins late in stream
    score += open_bins_count as f64 * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on residual space
    let pr = post_residual as i64;
    let class = pr % 10;
    // Reward residuals in "harmonious" classes (multiples of common item sizes)
    let harmony: f64 = match class {
        0 => -14.0,
        5 => -8.0,
        2 | 4 | 6 | 8 => -4.0,
        _ => 3.0,
    };
    score += harmony;

    // Integer division thresholds: tiny dead space is great, mid-range waste is bad
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else if post_residual <= 25 {
        score += 6.0; // awkward dead zone
    } else {
        score -= (post_residual as f64 / cap) * 5.0;
    }

    // Next item lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here; bin likely closes
        }
        // modulo coupling: next item shares harmonic class with post residual
        if (next_item_size as i64) % 10 == class && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: only attractive when current fit is poor or few open bins
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        let pressure = mean_residual / cap;
        let penalty = 30.0
            - 10.0 * fit_quality
            - 12.0 * (1.0 - pressure)
            - if fitting_bins_count == 0 { 25.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size >= bin_residual && fitting_bins_count <= 1 { 10.0 } else { 0.0 };
        score += penalty;
        // early stream: opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer tighter fits generally: reward high fill ratio
    score -= (item_size as f64 / cap) * 6.0;

    // Slight preference to keep number of open bins bounded
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (waste fraction penalty).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item would be blocked by tiny leftover, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score = 55.0 + 2.0 * pressure + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing lookahead favors fresh bin
        }
    }

    // Mild stream-progression bias toward consolidation later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space that next item cannot use
            score += 40.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful bin)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current open bins have poor fits
    if bin_residual == bin_capacity {
        let base = 120.0;
        let pressure = if next_item_size > 0 && next_item_size > item_size { 40.0 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 150.0 };
        score += base + pressure + scarcity;
    }

    // Slight preference to fill earlier bins as stream progresses
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via smooth polynomial in post_residual
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate waste less; late, squeeze bins harder
    let coupling = (norm_pr - 0.5) * (norm_pr - 0.5) * (1.0 + 3.0 * progress);
    score += coupling * 30.0;

    // Cubic interaction: waste penalized more when many bins open
    let open_factor = (open_bins_count as f64).ln().max(0.0);
    score += norm_pr * norm_pr * norm_pr * 20.0 * (1.0 + open_factor * 0.5);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap)).abs().ln().max(-2.0);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mean-residual alignment: bins far from mean residual are less attractive
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: penalize opening a new bin smoothly,
    // unless current bins are nearly full on average
    if bin_residual == bin_capacity {
        let crowded = 1.0 - (mean_residual / cap).min(1.0);
        score = 60.0 + 50.0 * (1.0 - crowded) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter / eighth classes of capacity
    let item_class = item_size / (bin_capacity / 8).max(1);
    let post_class = post_residual / (bin_capacity / 8).max(1);

    // Reward tight fits strongly (post_residual near zero or in a "dead" class)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // penalize residuals that are unusable: small dead zones
        let dead = (post_residual as f64) / cap;
        score += dead * 40.0;
        // harmonic penalty: residuals in "awkward" classes (just above common item sizes)
        let awkward = post_residual > 10 && post_residual < 25;
        if awkward { score += 15.0; }
    }

    // Modulo coupling: item class vs post class harmony
    if item_class == post_class {
        score -= 5.0; // same harmonic class -> likely reusable chunk
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_waste = (post_residual - next_item_size) as f64;
            score += nxt_waste * 0.3;
        } else {
            // next item cannot fit here; mildly penalize consuming this bin
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score = 0.0; // forced open
        } else if fitting_bins_count == 1 {
            // last chance bin exists; only open new if item is large
            score = if item_size > bin_capacity / 2 { cap * 0.85 } else { cap * 1.2 };
        } else {
            // several bins fit; new bin should lose unless item is huge
            score = cap * (1.0 + (item_size as f64) / cap);
        }
    }

    // Stream progression: later in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
        // mild preference for bins below mean residual (balance load)
        score += ((bin_residual as f64) - mean_residual).abs() * 0.05;
    }

    // Many open bins: encourage filling existing ones rather than spreading
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the next
    // item (or any plausible item) are "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // unreachable, but guard
    }
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap cannot host the lookahead item: penalize proportionally
            // to how "wasted" the gap is relative to capacity.
            let gap = post_residual as f64;
            let waste = gap / bin_capacity as f64;
            score += 30.0 + 40.0 * waste;
        } else {
            // Gap can host the next item: reward a follow-on fit.
            score -= 10.0;
        }
    }

    // Tight-fit reward: exact or near-exact fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than fragmenting space further.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no existing bin offers a good fit (large
    // post_residual elsewhere), otherwise keep it slightly worse than a
    // decent existing placement.
    if bin_residual == bin_capacity {
        score += 12.0 + open_pressure;
        // If the item would leave a nice residual for the lookahead, soften.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
    }

    // Mild progress normalization: early in the stream, be a bit more
    // conservative about opening bins (fewer bins early is cheap).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if open bins are on average quite full
    // (small mean residual), opening a new bin becomes more reasonable.
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact-ish match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward
        if diff == 0.0 {
            score -= 50.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits after this placement: reward proportionally to tightness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted residual
            score += 5.0 + diff * 0.1;
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Tight fit reward: small post_residual is good
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 5.0;

    // Relative to mean residual: prefer bins that are already fairly full
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are poor fits
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let large_gap = if next_item_size > 0 && post_residual >= item_size && post_residual < next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * poor_fits + 4.0 * large_gap;
        // penalize opening new bins early in the stream
        score += 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
