pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space (quadratic coupling with progress)
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Strong penalty for large unusable dead space (post_residual can't fit typical items)
    let dead = (post / cap).powi(3);
    score += 40.0 * dead;

    // Reward tight fits (small post_residual) — subtract proportional to fullness
    let fullness = 1.0 - post / cap;
    score -= 12.0 * fullness * fullness * fullness;

    // Lookahead coupling: reward if post_residual can fit the next item exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = 0.5 * cap + 10.0 * progress + 15.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference to fill bins with small mean residual (consolidation)
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no future item (1..=100)
    // can ever fill is worthless; perfectly reusable residuals are valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: post_residual == 0 -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Class 2: post_residual < smallest plausible item -> dead space penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Class 3: post_residual in "awkward" harmonic band (just above half? no —
    // residuals in (50, 100) can hold anything; residuals in (0,10) hold nothing).
    // Penalize residuals that are large-but-odd via modulo classes.
    let m = post_residual % 10;
    if post_residual >= 10 {
        // residuals divisible by 10 align with a decimal-capacity world: reward
        if m == 0 {
            score -= 6.0;
        } else if m >= 5 {
            score += 2.0 + m as f64 * 0.3;
        } else {
            score += m as f64 * 0.2;
        }
    }

    // Integer-division thresholds: residual usable by next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits here: reward, scaled by how "tight" the pair is
        let tightness = 1.0 - (post_residual - next_item_size as f64) / cap;
        score -= 8.0 + 10.0 * tightness;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this bin's leftover: penalize proportionally
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default mild preference; open a fresh bin only when
    // existing bins would leave bad residuals or the item fits almost exactly
    // in a fresh bin (item_size near capacity fractions 100, 50, 33...).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // item near full or exactly half: fresh bin is great
        if (frac - 1.0).abs() < 0.05 || (frac - 0.5).abs() < 0.02 {
            score -= 12.0;
        } else {
            score += 10.0;
        }
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Many open bins with high mean residual: prefer filling existing ones.
    if open_bins_count > 2 && mean_residual > cap * 0.4 && bin_residual != bin_capacity {
        score -= mean_residual * 0.05;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64) * 40.0 + 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize wasteful use of a nearly empty bin when a good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no decent fit exists or item is large.
        let fit_quality = if fitting_bins_count == 0 { 1.0 } else {
            let best_gap = (mean_residual - item_size as f64).max(0.0);
            (best_gap / 40.0).min(1.0)
        };
        score += 55.0 - 45.0 * fit_quality - (item_size as f64 / 100.0) * 15.0;
    } else {
        // Mild reward for using existing bins, scaled by open-bin pressure.
        score -= 8.0 + (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for creating a blocking gap.
        score += 6.0;
    }

    // Late in the stream, consolidate harder into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Penalize post_residual far from mean residual (fragmentation pressure).
    score += ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // prefer chains leaving small leftovers
            score -= 40.0 * (1.0 - (leftover as f64) / (bin_capacity as f64));
        } else {
            // next item does not fit: penalize dead space that wastes capacity
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Coupling with mean residual: favor bins whose post_residual sits below mean
    // (concentrating waste in few bins), penalize above-mean residuals.
    score += 0.4 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // no open bin offers a good fit; otherwise discourage spreading load.
    if bin_residual == bin_capacity {
        let good_fit_available = fitting_bins_count > 0
            && (post_residual as f64) <= mean_residual * 0.5;
        if good_fit_available {
            score += 45.0; // keep item in an existing well-fitting bin
        } else {
            score -= 10.0; // allow opening a bin when fits are poor
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight penalty when many bins are open: encourage closing bins out.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (post residual that few items can use).
    if post_residual > 0 {
        let waste = if post_residual < 10 { 0.0 } else { (post_residual as f64).powf(1.4) };
        score += 0.25 * waste;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit: leftover is likely dead space.
        score += 6.0;
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate handling: opening a bin is attractive when open bins are
    // fragmented (high mean residual spread) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 18.0 * (1.0 - progress) + 0.05 * open_bins_count as f64 + fragmentation.max(0.0);
        // Never open a new bin for a perfect or near-perfect fit elsewhere is handled
        // by other bonuses; add mild fixed cost so tight fits win.
        score += 20.0;
    }

    // Mild preference for bins already below mean residual (consolidating space).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late-stream conservatism: squeeze existing bins harder as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; later, penalize wasted space more strongly.
    let progress_coupling = 1.0 + progress * progress * (pr / cap);
    score *= progress_coupling;

    // Penalize dead space that cannot plausibly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            // Reward leaving room exactly usable by the next item.
            score -= 2.0 * (1.0 - ((pr - nxt) / cap).powi(2));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when this bin is far above mean residual (keeps balance,
    // preserves many mid-size residuals across open bins).
    score += 0.3 * (pr as f64 - mean_residual).max(0.0) / cap;

    // New-bin candidate: make it unattractive unless it is genuinely better
    // than a very poor fit (score stays high for empty bin).
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Harmonic classes: post_residual divisible by small item sizes is reusable.
    // Residuals in "useful" classes (multiples of 10, or <= 20) are more likely refilled.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // classic harmonic class, easy to refill
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Dead space: residual too small for the smallest plausible item (1..100 range, min 1)
        if pr < 10 {
            score += 12.0; // nearly dead space, penalize
        } else if pr < 20 {
            score += 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64).min(30.0) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Empty new-bin candidate: only attractive when current bin is a bad fit
    // (large post_residual waste) or few open bins. Penalize default new bin.
    if bin_residual == bin_capacity {
        let waste = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        let _ = waste;
        let pressure = (open_bins_count as f64).max(1.0).ln();
        score += 18.0 + 4.0 * pressure;
        // If current bin would leave big unusable residue, new bin becomes viable.
        if pr > 0 && pr < 15 && bin_residual >= item_size {
            score -= 14.0;
        }
    }

    // Progression: later in stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Prefer bins below mean residual (fill the fullest bins first).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear dead-space penalty).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // cannot host next item: mild penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual < bin_capacity {
        score -= 2.0 + 4.0 * pressure.min(3.0);
    }

    // New-bin candidate handling: only attractive when the current item is
    // large (would leave little dead space) or existing fits are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 || (fitting_bins_count == 0) {
            score -= 10.0 + 20.0 * fill_ratio;
        } else {
            score += 15.0; // discourage opening a bin for small items
        }
    }

    // Mild preference for bins tighter than average (better packing).
    if bin_residual < bin_capacity {
        score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid dead space
    // that is too small to be useful for typical future items.

    // 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item consumes everything or nearly so
            if slack == 0.0 {
                score -= 40.0;
            } else if slack <= 10.0 {
                score -= 25.0;
            } else {
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here: post_residual becomes dead space
            // unless it is small enough to be negligible. Penalize proportionally.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // tiny remnant is fine, bin nearly full
            } else {
                score += 0.5 * dead;
            }
        }
    }

    // Coupling with mean residual: placing into a bin with above-average residual
    // spreads space more evenly; placing into a below-average bin risks stranding it.
    if (bin_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - bin_residual as f64);
    } else {
        score -= 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be badly wasted).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 15 {
            score -= 60.0;
        } else {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into any open bin would leave large unusable residue.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the lookahead term above already
        // rewards good chains into existing bins.
        score += 30.0;
        // But if next item is huge and would pair well with current item
        // in a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 55.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover; penalize dead space proportionally.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are mostly full
    // or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * avg_fill;
        score -= 10.0 * progress;
        // If many bins are open but residuals are fragmented, opening new is acceptable.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for consolidating into bins below mean residual (balance).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Encourage using existing bins as stream progresses (fewer total bins late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * progress) + pr_norm * (1.0 - progress) * 0.3;

    let mut score = pr + 12.0 * poly;

    // Penalize dead space more as stream progresses (fewer chances to reuse)
    score += 8.0 * pr_norm * pr_norm * progress * (open_bins_count as f64).sqrt();

    // Reward tight fits (small post_residual relative to item)
    let tight = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= 15.0 * tight * tight;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - pr / (next_item_size as f64)).min(1.0);
        }
    }

    // Slight bias toward filling existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    } else {
        score -= 2.0 * (mean_residual - pr).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fractional capacity classes of the post residual
    let pr = post_residual as f64;
    let frac = pr / cap;
    let quarter = post_residual / 25; // 0..4 harmonic class

    // Reward leaving residuals that fall into "usable" classes (multiples of common sizes)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: residuals below the smallest plausible item class
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Tight fit bonus: harmonic closeness of item to residual
    let ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * ratio * ratio;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // integer-division threshold: next item leaves another small class
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0;
        }
    } else {
        // last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer denser bin populations when many bins are open
    score -= (open_bins_count as f64).recip() * 5.0;

    // Progress-scaled conservatism: late in stream, avoid spreading residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;

    // Mean residual alignment: bins far from mean residual are slightly penalized
    score += (pr - mean_residual).abs() * 0.05;

    // Quarter-class modulation
    score -= match quarter {
        0 => 3.0,
        1 => 1.0,
        2 => 0.0,
        _ => -1.0,
    };

    // New-bin candidate handling: only attractive early or when no good fit exists
    if bin_residual == bin_capacity {
        let new_bin_bonus = if fitting_bins_count == 0 {
            -100.0
        } else if progress < 0.3 {
            -3.0
        } else {
            8.0 + 10.0 * progress
        };
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize leaving gaps that cannot fit a typical next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are plentiful.
    let bins_f = open_bins_count as f64;
    let pressure = bins_f / (bins_f + 8.0);
    score += 15.0 * pressure * (mean_residual / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress);

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u64 == next_item_size as u64 {
            score -= 120.0;
        } else if post_residual >= next_item_size && diff <= 10.0 {
            score -= 60.0 - diff * 2.0;
        } else if post_residual < next_item_size && post_residual <= 20 {
            // Dead space the next item cannot use: penalize proportionally.
            score += (post_residual as f64) * (nxt / 100.0) * 3.0;
        }
        // Prefer leaving residuals close to typical next-item sizes.
        score += diff * 0.3;
    } else {
        // Last item: minimize waste only.
        score += (post_residual as f64) * 0.5;
    }

    // Relative to mean residual: bins tighter than average are more precious.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + (bin_residual as f64) * 0.1;
    }

    // New-bin candidate: only attractive when open bins are fragmented or
    // the fit into open bins would be poor. Penalize opening new bins
    // increasingly as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 150.0 + progress * 100.0;
        // If open bins are highly fragmented (large mean residual spread vs
        // count), opening a fresh bin becomes less penalized.
        score -= fragmentation * 20.0;
        // Small items tolerate a fresh bin more.
        score -= (100 - item_size.min(100)) as f64 * 0.3;
    }

    // Mild preference for filling emptier bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space that nothing can use (min item ~1, so small waste ok).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Crowding pressure: when many bins open, prefer filling existing ones.
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Late in stream, consolidate aggressively: penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 50.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize large residuals more.
    score += 20.0 * norm_pr * progress * (1.0 - progress + progress);

    // Penalize residuals that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 15.0 * waste * (1.0 - progress);
        // Reward post-residual that exactly accommodates the next item.
        let fit_gap = (pr - nx).abs() / cap;
        score -= 10.0 * (1.0 - fit_gap) * (pr / cap).min(1.0);
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this one.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Crowd control: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: if this bin is far from mean residual, slight penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual space left behind: exact quarters are valuable
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % quarter == 0 {
        score -= 12.0; // harmonic residual, reusable by class-aligned items
    } else if pr < 10 {
        score -= 4.0; // tiny dead space, effectively sealed
    } else {
        // penalize awkward mid-class residuals
        let off = (pr % quarter) as f64;
        score += 0.25 * off;
    }

    // Prefer tight fits (small waste ratio)
    let waste = post_residual as f64 / cap;
    score += 25.0 * waste * waste;

    // Lookahead coupling: reward if next item exactly matches post_residual (chained fill)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let nrem = pr - next_item_size;
            if nrem % quarter == 0 {
                score -= 10.0;
            }
            score += 0.3 * nrem as f64;
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 2.0;
        }
    }

    // Last-chance bin before opening a new one: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score = 15.0 + 20.0 * (1.0 - progress) + 5.0 * congestion;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // new bin pairs well with upcoming mid-size item
        }
    }

    // Mild preference to spread load when many bins are open and mean residual is high
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize post_residual below typical small item sizes nonlinearly.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (near-zero post_residual is good).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual, strong bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize if post_residual is too small for the lookahead item (dead space guaranteed).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9 + fragmentation * 20.0 + pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening a bin when nothing else fits is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0; // big lookahead item benefits from fresh bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff <= 5.0 {
            // Perfect chain: item fits now, next item fills remainder exactly.
            score -= 60.0 * (1.0 - diff / 5.0);
        } else if post_residual >= next_item_size {
            // Next item still fits: mild bonus proportional to leftover after chain.
            let chain_left = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the residual: penalize wasted space relative to mean.
            score += 10.0 + 0.3 * (post_residual as f64 - next_item_size as f64).min(50.0);
        }
    }

    // Relative-to-mean residual shaping: prefer bins tighter than average.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the new-bin candidate unless current fit is very poor.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio < 0.85 {
            score -= 5.0; // opening fresh bin OK when fit is loose
        } else {
            score += 30.0; // discourage opening new bin on good fits
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post_residual is close to next item (good chain fit).
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or few bins fit and the stream is early (expect more items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.45 * bin_capacity as f64;
        let scarce = fitting_bins_count == 0;
        if poor_fit || scarce {
            score -= 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 45.0;
        }
        // Early stream: new bins are cheap since future items will fill them.
        score -= 15.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below mean residual (fill the emptiest bins first).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 3.0 * diff / bin_capacity as f64;
        } else {
            score += 2.0 * (-diff) / bin_capacity as f64;
        }
    }

    // Mild time horizon: late in the stream, avoid leaving scattered residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = (1.0 + progress) * norm_pr * norm_pr * cap;
    score += 0.35 * poly;

    // reward tight fits, stronger late in the stream
    let fit = (item_size as f64 / cap).powi(2);
    score -= (0.6 + 0.8 * progress) * 25.0 * fit;

    // penalize dead space when lookahead can't use it
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 12.0 + 18.0 * norm_pr;
    } else if next_item_size > 0 {
        score -= 8.0 * (1.0 - ((next_item_size as f64 - pr).abs() / cap));
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // mild new-bin penalty early, relief late
    score += is_new * (10.0 - 8.0 * progress);

    // spread-awareness: avoid fragmenting when many bins open
    score += 0.05 * open_bins_count as f64 * norm_pr;
    score -= 3.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean" fractions of capacity
    let post = post_residual as f64;
    let frac = post / cap;

    // Residuals that are exact multiples of small divisors are more reusable
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    for &d in &[5u32, 10, 20, 25, 50] {
        if pr % d == 0 && pr > 0 {
            harmony_bonus += 8.0;
        }
    }
    score -= harmony_bonus;

    // Penalize awkward residuals: small but nonzero (dead space)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Very tight fit is excellent
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Fraction-based penalty: residuals in (10,30) are hard to fill later
    if pr > 10 && pr < 30 {
        score += 12.0 * (1.0 - frac * 3.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot class
            let over = (next_item_size - pr) % 25;
            score += 4.0 + over as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in stream, prefer tightening existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (mean_residual / cap);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good dense fit
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // item (1..=MIN_USEFUL) are pure waste; penalize them hard.
    let min_useful: f64 = 12.0;
    if (post_residual as f64) < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual as f64);
    } else {
        // Gradually reward leaving a gap that can still serve a future item.
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.5));
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose current residual was already small (tight packing).
    score += 0.6 * (bin_residual as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few
    // are open, filling them well is fine.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; leftover gap likely dead space.
            score += 12.0;
        }
    }

    // New-bin candidate: attractive early / when open bins are poor fits,
    // unattractive when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        let pressure = 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        score = bin_capacity as f64 * 0.55 + pressure - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual,
    // penalize when next item cannot fit into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 40.0; // perfect pair packing
        } else if nxt <= pr {
            score -= 15.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here; dead space unless post_residual is tiny
            score += 10.0 * (1.0 - pr / bin_capacity as f64).min(1.0);
            if pr > 30.0 {
                score += (pr - 30.0) as f64 * 0.3;
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin if all open fits are terrible
    if bin_residual == bin_capacity {
        // default penalty so we prefer existing bins, unless lookahead perfect pairing exists there
        score += 60.0;
        // but if next item is large and current item small, a fresh bin can host both later
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64) >= 0.0 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins (build good structure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residuals (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny slivers are effectively full bins -> good
    }
    if post_residual >= 10 && post_residual < item_size.max(10) {
        score -= 8.0; // residual too small for even the smallest next item
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 6.0; // next item can't reuse this residual
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are crowded and item is large.
        let open_desirability = 60.0 * (1.0 - pressure) * (1.0 - progress * 0.5);
        score = 100.0 - open_desirability + item_size as f64 * 0.3;
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64).abs();
        score += 0.02 * open_bins_count as f64;
    }

    // Time horizon: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (low post_residual). Later, weight
    // post_residual more strongly to avoid fragmenting bins as stream matures.
    let mut score = post * (1.0 + 0.8 * progress * norm_post) + 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward excellent fits: quadratic discount when post_residual is tiny.
    if post <= 10.0 {
        score -= 12.0 * (1.0 - post / 10.0) * (1.0 - post / 10.0);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 15.0;
        } else if nxt < post {
            // smooth reward decaying with slack left after hypothetical next placement
            let slack = post - nxt;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; mild penalty if this leaves a stranded gap
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // open bins are heavily fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = cap * 0.9 - 20.0 * fragmentation - 8.0 * progress;
    }

    // Small tie-breaker coupling with mean residual state.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals that are multiples of
    // common item-size classes (mod 10 buckets), penalize "dead" residuals.
    let post = post_residual;
    if post > 0 {
        // Dead-space penalty grows superlinearly for small unusable residuals.
        if post < 10 {
            score += (10 - post) as f64 * 4.0;
        }
        // Harmonic bonus: residuals divisible by 10, 20, 25, 50 are reusable.
        let div_bonus = if post % 50 == 0 { 12.0 }
            else if post % 25 == 0 { 8.0 }
            else if post % 20 == 0 { 6.0 }
            else if post % 10 == 0 { 4.0 }
            else { 0.0 };
        score -= div_bonus;
    } else {
        // Perfect fill.
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / cap) * 10.0;
        } else {
            // post_residual cannot host next item: mild penalty scaled by waste.
            score += (next_item_size as f64 / cap) * 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many open bins still have room.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt() * 3.0;
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin fleet homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: as stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 20.0;
    } else if post_residual <= 25 {
        score += 8.0;
    } else if post_residual <= 40 {
        score += 2.0;
    } else {
        // Large usable residuals are valuable; reward tight-but-usable fits.
        score -= 4.0;
    }

    // Perfect / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this bin to enable a chain of tight placements.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 25.0;
        } else if gap <= 10.0 {
            score -= 12.0;
        } else if gap > 40.0 {
            score += 3.0; // leaves next item with lots of slack; mild penalty
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Bin becomes unusable for the lookahead item; penalize proportionally.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when the fit into open bins would be very wasteful.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin.
        score += 12.0 + 2.0 * open_bins_count as f64;
        // If no open bin fits, opening a new bin is necessary/cheap.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 5.0;
        }
    }

    // Mild preference for bins whose residual is below the mean (tighter bins),
    // keeping loose bins available for awkward future items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-chain fit
        } else if pr >= nxt {
            score -= 25.0 * (nxt / pr);
        } else {
            // next item won't fit here; penalize dead space proportionally
            score += 10.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let cap = bin_capacity as f64;
    let deviation = (post_residual as f64 - mean_residual) / cap;
    score += 8.0 * deviation;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_frac * fit_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below mean (fragmented bins),
    // unless this placement improves them.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item exactly consumes post_residual.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Mild penalty: this placement strands the lookahead item here.
            score += 5.0;
        }
        // Penalize leaving a residual just below the next item size (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // few bins fit the item or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let mut new_bin_score = 30.0;
        // Discourage opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= 20.0 * progress;
        // More attractive when many open bins but few can fit the item.
        new_bin_score -= 2.0 * (open_bins_count as f64 - fitting_bins_count as f64);
        // Discourage when mean residual is large (plenty of room exists).
        new_bin_score += 0.25 * mean_residual;
        // Large items justify new bins more.
        new_bin_score -= 0.2 * item_size as f64;
        score = score.max(new_bin_score.min(score)) ;
        score = new_bin_score + (score - new_bin_score) * 0.0 + 0.0;
        score = new_bin_score;
    }

    // Small tie-breaker toward bins with lower residual (fill emptier bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, softly scaled by capacity.
    let mut score = post / cap * 100.0;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tight fits matter less; later, waste is heavily punished.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    score -= tightness * (40.0 + 80.0 * p2 + 60.0 * p3);

    // Penalize leaving residuals that are unlikely to fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            let gap = (nx - post) / cap;
            score += 25.0 * gap * gap * (1.0 + progress);
        } else {
            // Reward leaving room for the next item, quadratically.
            let room = 1.0 - ((post - nx) / cap);
            score -= 15.0 * room * room * (1.0 - progress);
        }
    }

    // Reward using bins that are already open (fewer bins preferred),
    // stronger as the stream progresses.
    score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + p2);
    }

    // New-bin candidate: make it mildly unattractive unless post_residual
    // would be very large (i.e., the item barely fits anywhere else).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 20.0 + 2.0 * openness * (1.0 - progress);
        // But if this item is huge relative to capacity, opening fresh is fine.
        score -= (item_size as f64 / cap) * 35.0;
    }

    // Divergence from mean residual: prefer bins whose fill pattern
    // tracks the fleet average (smooth, non-linear coupling).
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of 10 are
    // more reusable by typical item sizes; deep "dead" zones get penalized.
    let res_mod = post_residual % 10;
    let residue_penalty = match res_mod {
        0 => -6.0,
        1 | 9 => 1.0,
        2 | 8 => 2.0,
        3 | 7 => 3.5,
        4 | 6 => 4.5,
        _ => 5.0,
    };
    score += residue_penalty;

    // Perfect fit bonus (harmonic class 0 at full tightness).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Integer-division threshold: post_residual in [10, 30] is a "danger zone"
    // that often becomes unusable dead space; penalize proportionally.
    if post_residual >= 10 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.6;
    }

    // Coupling with next item (k=2 lookahead): reward residuals that can
    // accommodate the upcoming item (harmonic compatibility).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item also fits snugly afterwards.
            let nn = post_residual - next_item_size;
            if nn <= 10 {
                score -= 6.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 4.0; // tiny leftover blocks the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // A fresh bin is more attractive if mean residual is small.
        score -= (mean_residual - 50.0).max(0.0) * 0.3;
    }

    // Mild preference for filling fuller bins (low residual) overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Many open bins: discourage spreading, favor tight packing.
    if open_bins_count > 4 {
        score += 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for any item (min size 1, but typical
    // stream items are >=10) are nearly unusable. Penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) proportionally stronger.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening/spreading when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if next item would not fit here (wasting lookahead potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin residuals balanced, avoids fragmentation).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // Early stream: be slightly conservative about opening new bins early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small dead zones mildly
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Tightness relative to mean residual across open bins
    let tightness = mean_residual - post_residual as f64;
    score -= 0.3 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (post_residual == 0 || (next_item_size > 0 && post_residual >= next_item_size));
        if good_fit_exists {
            score += 250.0;
        } else {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild pressure to keep open-bin count low
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // creates stranded space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residuals close to the mean (balanced packing),
    // scaled by how many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev / (open_bins_count.max(1) as f64).sqrt();

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor tight fits over reuse); late, prefer consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = (1.0 - t) * 15.0 - t * 10.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    }

    // Slight penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual, with smooth polynomial shaping.
    let mut score = post;

    // Non-linear penalty on wasted space that grows quadratically with post_residual,
    // amplified later in the stream (dead space is costlier as the stream progresses).
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect-fit reward: smooth bump near zero residual.
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward leaving residual that can host the next item
    // (smooth interaction between post_residual and next_item_size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        if slack >= 0.0 {
            let s = slack / cap;
            // mild reward proportional to remaining usefulness, decaying quadratically
            score -= 12.0 * (1.0 - s) * (1.0 - s);
        } else {
            // penalty for leaving residual that barely misses the next item
            let miss = (-slack) / cap;
            score += 15.0 * miss * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Slight penalty for using a bin when many bins fit (prefer the tightest,
    // handled via post_residual, but add mild dispersion pressure).
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: avoid bins whose residual deviates far below
    // the mean (keeps a balanced set of open capacities for future items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (smooth logistic-style gate).
    if bin_residual == bin_capacity {
        let size_ratio = item / cap;
        let gate = 1.0 / (1.0 + (-20.0 * (size_ratio - 0.55)).exp());
        score += 45.0 * (1.0 - gate) * (1.0 + 0.5 * progress);
        // but early stream, opening bins is cheap; late stream, prefer filling
        score -= 10.0 * (1.0 - progress) * gate;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "small"
    // classes are good (little waste); large residuals are penalized.
    let class = post_residual / 10; // integer-division threshold classes (0..=10)
    match class {
        0 => score -= 25.0,               // near-perfect fill
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 | 5 => score += 3.0,            // awkward middle zone
        6 | 7 => score += 8.0,
        _ => score += 15.0,               // mostly-empty bin, wasteful choice
    }

    // Modulo coupling: residual divisible by small item sizes is reusable.
    if next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 12.0; // next item can exactly fill this bin later
        }
        if next_item_size <= post_residual {
            score -= 6.0; // bin stays useful for the lookahead item
        } else {
            score += 9.0; // lookahead item cannot use leftover space
        }
        // Capacity-fraction thresholds on next item
        let nf = next_item_size as f64 / bin_capacity as f64;
        if nf > 0.5 && post_residual >= next_item_size {
            score -= 8.0; // pair big+small nicely
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 25.0 * (1.0 - progress) - 30.0 * frag;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
    }

    // Prefer tighter bins relative to current mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for compacting early, spreading late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use
    // are heavily penalized. Assume smallest item is 1, but typical items >= 10;
    // treat gaps < 10 as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (low slack fraction).
    let slack_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * slack_frac;

    // If the next item can also fit into the post residual, reward this bin
    // (chaining placements reduces bin count).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item would NOT fit here but would fit a fresher bin.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // i.e., penalize the new-bin candidate more when open_bins_count is high.
    if bin_residual == bin_capacity {
        // New bin candidate: base penalty plus pressure.
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow opening: handled by other terms.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host future items flexibly
        }
    }

    // Progress-aware tightening: later in the stream, be stricter about
    // consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Slight preference for bins with residual close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a small unusable gap
            score += 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist;
    // allow new bins more freely late when fragmentation dominates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 {
            score -= 500.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average future item.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Perfect pairing bonus
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }
    // Next item would fit better elsewhere: mild penalty for hogging space.
    if next_item_size > post_residual && next_item_size > item_size {
        score += 5.0;
    }

    // Early in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 6.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Late in stream: penalize opening new bins more strongly.
    score += progress * 15.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Many open bins: discourage new bins, encourage filling existing ones.
    if open_bins_count > 4 {
        score += 8.0 * (bin_residual == bin_capacity) as i32 as f64;
        score -= 3.0;
    }

    // Penalize leaving residuals that are awkward (just above common item sizes).
    for awkward in [10u32, 20, 30, 40, 50, 60, 70] {
        if post_residual > awkward && post_residual <= awkward + 3 {
            score += 4.0;
        }
    }

    // Prefer bins whose residual is closest to item_size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Slight penalty for new bin when a fitting bin exists with small residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && mean_residual < item_size as f64 * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let util = 1.0 - pr / c;
    let tightness = (pr / c).powi(3);
    let mut score = pr * (1.0 + 0.35 * progress) + 8.0 * tightness * (1.0 + progress);
    // reward high utilization smoothly
    score -= 6.0 * util * util * (1.0 - progress);
    // lookahead coupling: favor leaving room for the next item
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let fits_next = (pr - ni).max(0.0) / c;
        score -= 4.0 * fits_next * (1.0 - fits_next);
        if pr < ni {
            score += 3.0 * (ni - pr) / c;
        }
    }
    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // penalize opening new bins mildly, more later in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 + progress) + 0.5 * open_bins_count as f64;
    }
    score += 0.05 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo small integers
    let pr = post_residual;
    let mod3 = (pr % 3) as f64;
    let mod5 = (pr % 5) as f64;
    let mod7 = (pr % 7) as f64;
    // Harmonic penalty: dead space that is not a "nice" residue gets punished
    score += 0.7 * mod3 + 0.5 * mod5 + 0.4 * mod7;

    // Integer-division thresholds: post_residual bucketed by 10s
    let bucket = pr / 10;
    score += match bucket {
        0 => -8.0,   // nearly perfect fit
        1 => -4.0,
        2 => 0.0,
        3 => 3.0,
        _ => 6.0,    // large dead space
    };

    // Reward filling the bin completely (post_residual == 0)
    if pr == 0 {
        score -= 25.0;
    }

    // Coupling with next item: if post_residual can host next_item_size, reward
    if next_item_size > 0 && pr >= next_item_size {
        score -= 3.0 + 0.05 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // post_residual too small for next item: dead space likely
        score += 0.03 * pr as f64;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many bins can fit, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Slight preference for bins below mean residual (consolidating fuller bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Many open bins: prefer filling existing ones
    score += 0.2 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but realistically < 10 is near-unusable) get a heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Reward using a bin whose residual is well matched to the item.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_ratio * waste_ratio;

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading when bins are plentiful,
    // encourage consolidation.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 && nxt_left > 0 {
                score -= 12.0; // leaves tiny gap but serves next item
            } else if nxt_left == 0 {
                score -= 25.0; // perfect chain
            } else {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0; // dead space blocks the known next item
        }
    }

    // New-bin candidate handling: an empty bin is a fresh start; make it moderately
    // attractive only when existing bins would leave bad dead space, otherwise
    // discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * (open_bins_count as f64);
        // If this item is small relative to capacity, opening a new bin wastes space.
        score += (bin_capacity - item_size) as f64 * 0.15;
        // Late in the stream, avoid new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight bonus for bins with residual close to item (best-fit flavor).
    score -= 10.0 / (1.0 + (bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose residual matches the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            if gap == 0.0 {
                score -= 800.0; // chain: next item fills this bin exactly
            } else if gap <= 5.0 {
                score -= 300.0;
            } else {
                score -= 100.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item cannot fit here; residual is likely dead space
            score += 0.5 * (nr - pr);
        }
    }

    // Penalize residuals that are too small to ever be useful (min item ~1)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if lookahead chains well into a fresh bin, allow it
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the base, but amplify its effect
    // nonlinearly so near-perfect fits dominate.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize wasted space relative to the mean residual of open bins:
    // leaving residual far above the mean creates outlier dead space.
    let res_gap = post_residual as f64 - mean_residual;
    score += 0.8 * res_gap.max(0.0);
    score -= 0.3 * res_gap.min(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (which the new-bin candidate must beat).
    if fitting_bins_count <= 1 {
        score -= 60.0;
    } else {
        // Mild reward when many bins compete: prefer the bin that wastes least
        // among many options is already captured, add slight diversity bonus.
        score -= 4.0;
    }

    // Lookahead: if the next item would fit nicely in the resulting residual,
    // reward; if post_residual is a dead zone (too small for min item but >0),
    // penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_fit = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - pair_fit / bin_capacity as f64);
        }
        // Dead-space penalty: residual that nothing small can use
        if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 20.0;
        }
    }

    // New-bin candidate handling: opening a bin is penalized by its waste
    // (capacity - item) plus a fixed opening cost, softened late in the stream
    // or when open bins are numerous and fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 25.0 - 15.0 * progress;
        score += open_cost + (open_bins_count as f64).sqrt() * 3.0;
        // If no existing bin fits at all, new bin is the only option: remove penalty
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Large items should go into bins now rather than fragmenting
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * item_frac;
    }

    // Slight preference to fill older/more full bins first (implicit via
    // residual), plus tiny regularization to break ties deterministically.
    score += 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress;
    score += 8.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Penalize dead space that is too small for typical future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (0.4 + 0.6 * progress);
        } else {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 3.0 + 0.5 * crowd;
    }

    // Prefer bins whose residual is close to the mean (balance)
    score += 0.3 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 20
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;
    let q10 = post_residual / 10;

    // Dead space penalty: residuals that cannot host small items (1..10)
    // are pure waste; reward perfect closure.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual < 10 {
        // small but usable only by tiny items; mild penalty scaled by residue class
        score += (r10 as f64) * 0.4;
    } else {
        // larger residuals: reward divisibility (harmonic alignment)
        let div_bonus = match (post_residual % 20, post_residual % 25, post_residual % 50) {
            (0, _, _) => 8.0,
            (_, 0, _) => 5.0,
            (_, _, 0) => 3.0,
            _ => 0.0,
        };
        score -= div_bonus;
        // penalize awkward odd residues that rarely recombine
        if r20 != 0 && r10 != 0 && post_residual % 5 != 0 {
            score += 2.5;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: strong reward, scaled by tightness of the chain
            let tight = (post_residual - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - tight / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // next item fits here but not after this placement: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, decaying as stream matures
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 10.0 * progress;
        // if only one fitting bin and it's tight, opening a new bin may be fine
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
        // with many open bins and a large mean residual, prefer reusing
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 8.0;
        }
    }

    // Mild preference for tighter bins when many are open
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64);
    }

    // Integer-division threshold shaping on residual magnitude
    score += match q10 {
        0 => 0.0,
        1 => -1.0,
        2 => 0.5,
        3 => 1.0,
        _ => 1.5,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to be useful are heavily penalized.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(50) } else { 50 };
    if post_residual < dead_threshold && post_residual > 0 {
        score += (dead_threshold as f64 - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins,
    // but relax when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> favor packing into existing ones.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64) * 0.2;

    // If lookahead item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
