pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize dead space that is too small for typical items (1..100 unknown, but small gaps < next item are useless).
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // Reward bins that can also take the lookahead item afterwards (chained fit).
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer tightest fit, ignore new-bin option.
        if bin_residual == bin_capacity {
            score += 1e6;
        }
    }

    // Tightness ratio: relative fill of the bin.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 20.0;

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But if the only fitting bin would leave a bad gap, opening may be fine:
        if fitting_bins_count == 1 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 {
            score -= 45.0;
        }
    } else {
        // Slight preference for bins with residuals far below the mean (keep big gaps for big items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild global pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r = mean_residual;

    // Base: waste after placement, with smooth quadratic waste penalty.
    let mut score = pr + 0.035 * pr * pr / cap;

    // Tight-fit reward: smooth Gaussian-like coupling of item size to residual.
    let tightness = 1.0 - ((pr / cap - 0.5) * 2.0).powi(2);
    score -= 6.0 * tightness.max(0.0);

    // Non-linear interaction between waste and stream progress:
    // early on tolerate slack; late, penalize leftover space harder.
    let prog = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * prog * (pr / cap);

    // Reward using bins with large existing residual (consolidate slack).
    score -= 2.5 * (bin_residual as f64 / cap) * (pr / cap);

    // Lookahead: if next item fits in post_residual, bonus (smooth).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 4.0 * fit_frac * (1.0 - prog);
    } else if next_item_size > 0 {
        // penalize blocking the next item smoothly
        let over = (next_item_size as f64 - pr) / cap;
        score += 3.0 * over.max(0.0);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 6.0 * prog;
    }

    // Mild pressure to prefer already-open bins over opening new ones.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: residual == capacity -> add opening penalty so it
    // only wins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * prog + 0.05 * mean_r;
    }

    // Small smooth coupling with mean residual: prefer bins near the mean
    // (keeps residuals balanced for future items).
    score += 0.4 * (pr - mean_r).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (tiny dead space) -> strong reward.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Class B: post_residual in a "usable" harmonic band (multiples of 25 minus slack).
    // Residuals of 25/50/75 leave room for typical items.
    let quarter = post_residual / 25;
    let quarter_rem = post_residual % 25;
    if quarter >= 1 && quarter_rem <= 5 {
        score -= 12.0 + 4.0 * quarter as f64;
    }

    // Class C: dead-space penalty for unusable slivers (1..9) that aren't near-zero.
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0 * (9 - post_residual) as f64;
    }

    // Tightness ratio: reward filling a large fraction of the bin.
    let fill = (item_size as f64) / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: mild penalty proportional to waste potential.
            score += 3.0;
        }
        // Harmonic pair: item + next close to capacity.
        let pair = item_size as f64 + nxt;
        if pair <= cap && cap - pair <= 5.0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new one
    // by rewarding this bin strongly (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap - item_size as f64; // post_residual of fresh bin
        score += 18.0; // inherent opening cost
        if fitting_bins_count == 0 {
            score -= 40.0; // forced
        }
        // Open new bin when existing residuals are fragmented and item is large.
        let frag = mean_residual / (open_bins_count.max(1) as f64);
        if item_size as f64 > 0.6 * cap && frag < 0.35 * cap {
            score -= 20.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> favor bins below mean residual (consolidation).
    if open_bins_count > 1 {
        let dev = mean_residual - pr;
        score += 0.15 * dev;
    }

    // Small penalty scaling with number of alternatives (prefer scarce-fit bins).
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to the bin's free space (low waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 15.0 * waste_ratio;
    }

    // Lookahead coupling: penalize if the residual can't host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave badly fragmented space, or too many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * 1.5 + mean_residual * 0.3 + progress * 10.0;
        score = 50.0 + pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Open-bin count pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Small bonus for using a bin whose residual is close to the item (best-fit core).
    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 30.0;
        }
    }

    // Tightness relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong penalty if we skip it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great fit
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale benefit by how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < item_size {
        // dead space smaller than the smallest conceivable item chunk
        score += 5.0;
    } else if post_residual >= item_size {
        // leftover can still host another item of similar size: mildly good
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leaving big residual is wasteful
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual => fragmentation; prefer bins
    // below mean residual (consolidate emptier bins first).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time horizon: late in the stream, prefer tighter packing (less waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it unattractive unless current fits are terrible.
    if bin_residual == bin_capacity {
        score = 95.0 + 0.3 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear shaping (quadratic/cubic) coupled to progress
    let mut score = pr
        + 12.0 * norm_pr * norm_pr * (1.0 + progress)
        + 8.0 * norm_pr * norm_pr * norm_pr;

    // Tight fits rewarded more as stream progresses (waste less room early? no — tighten late)
    let fill_ratio = 1.0 - norm_pr;
    score -= 10.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 10.0 * progress;
    }
    // Reward residuals that exactly or nearly fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins deviating from mean in useful direction
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev - 4.0 * dev * (1.0 - progress);

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate handling: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let best_case = (bin_residual as f64 - item_size as f64).max(0.0);
        score = pr + 10.0 * norm_pr * norm_pr
            + 20.0 * (1.0 - best_case / cap)
            - 5.0 * progress;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional capacity position of the item
    let frac = item_size as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual lies in "useful"
    // residue classes (multiples of small item sizes) are worth keeping tidy.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect closure, strongly favored
    } else if pr <= 10 {
        -12.0 // tiny dead space is nearly a closure
    } else if pr % 10 == 0 {
        -6.0 // residual aligned to decimal harmonic grid
    } else if pr % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus as f64;

    // Penalize awkward mid-range residuals (hard to fill later)
    if pr > 10 && pr < 30 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // scale reward by how well next item fills the leftover
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
        } else {
            // next item won't fit here: slight penalty for leaving large residue
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin should only win when current
    // fit is terrible. Give the empty bin a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 45.0 + frac * 10.0;
        // early in stream, be more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // many open bins with high mean residual: discourage new bins
        score += open_bins_count as f64 * 1.5 + mean_residual * 0.1;
    } else {
        // Prefer fuller bins: reward low residual before placement
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Late-stream tightening: waste matters more as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * 0.15 * progress;

    // Mean-residual coupling: if this bin is far from mean residual, small nudge
    score += (post_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 15 {
        // Medium-small gaps: mild penalty scaled by tightness.
        score += 0.8 * (15 - post_residual) as f64;
    }

    // Tightness bonus: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across too many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if post_residual >= 20 && post_residual <= 45 {
            score -= 5.0; // leftover usable for medium items
        }
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // would create dead space immediately
        }
    }

    // Lookahead: prefer bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Mean-residual coupling: placing into a below-average residual bin
    // balances the pool of open bins.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
    score -= 12.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);

    // Extra reward for near-exact chain (small gap)
    if lookahead_gap <= 5.0 {
        score -= 8.0 + (5.0 - lookahead_gap) * 2.0;
    }

    // Penalize post_residual that is large but unusable by the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize dead space below minimum item size (1..10 unusable)
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Prefer bins whose residual deviates from the mean (tight fit vs loose fit)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage closing bins out (avoid sprawl)
    if open_bins_count > 4 {
        score -= open_bins_count as f64 * 0.3;
    }

    // Late in the stream: prefer tighter packing (minimize residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 6.0;
        if fitting_bins_count >= 1 && (bin_residual - item_size) >= next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize bins that would leave exactly-blocking residuals for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Opening a bin is more attractive when few bins fit and mean residual
        // across open bins is small (fragmented space).
        let frac_fit = if open_bins_count > 0 {
            fitting_bins_count as f64 / open_bins_count as f64
        } else {
            1.0
        };
        score -= 14.0 * (1.0 - frac_fit);
        score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);
        // Early in the stream, cheap to open bins; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the item is large, a fresh bin is a natural home.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: tight fits rewarded more strongly as stream progresses
    score -= 60.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);
    // Penalize large residuals with convex growth, modulated by progress
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);
    // Dead-space penalty if residual too small for typical future items, smoothed
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 - progress);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }
    // Mild crowding penalty relative to mean residual
    score += 5.0 * (mean_residual - pr) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    let frac = pr / cap; // 0.0 .. 1.0
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes: 0..=7

    // Penalize residuals that are too small to be useful (dead space).
    // Items range 1..100, so residual < ~10 is nearly unusable.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: residuals that align with common item
    // granularity (multiples of 10, 25, 50) are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is ideal (perfect pair).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > post_residual {
            // next item cannot use this leftover: mild penalty scaled by waste
            let waste = post_residual as f64 / cap;
            score += 8.0 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Harmonic class adjustment: mid-range residuals (classes 2-4, i.e. ~25-62)
    // are the most reusable; extremes less so.
    match class {
        0 => score += 5.0,           // 0-12% left: nearly full, fine but low reward
        1 => score -= 4.0,           // 12-25%
        2 => score -= 7.0,           // 25-37%
        3 => score -= 8.0,           // 37-50%
        4 => score -= 6.0,           // 50-62%
        5 => score -= 2.0,           // 62-75%
        6 => score += 2.0,           // 75-87%
        _ => score += 4.0,           // 87-100%: nearly empty, wasteful placement
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (keeps the count of open bins from exploding).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        let rel = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
        // bins with residual below the mean are good targets (consolidation)
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0);
        }
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (1..100 interface, but typical items >= 10) are dead weight. Penalize
    // the "unusable gap" region super-linearly.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit: strong reward
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Penalize leaving a residual that is awkwardly below the lookahead item
    // (dead space for the known future), but reward if lookahead fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good; encourage closing bins out when few remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure * (1.0 - fill);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "scraps" bin — using it up is good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * fill;
    }

    // New-bin candidate (empty bin): neutral baseline with slight penalty so we
    // only open when existing fits are poor; scale penalty down late in stream.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual already dominates).

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 1.0 {
            score -= 25.0; // perfect chain: item + next fill bin completely
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            score -= 0.35 * nr * (nr / post_residual as f64);
        } else {
            // next item won't fit here: penalize large dead space
            let dead = post_residual as f64;
            if dead < nr {
                score += 0.15 * (nr - dead).min(30.0);
            }
        }
        // penalize leftovers too small for typical items but too big to waste
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    } else {
        // last item: pure tightness, tiny bonus for zero waste
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev; // prefer bins with below-average leftover after placement

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good fit (i.e., when best existing placement would leave big dead space).
    if bin_residual == bin_capacity {
        // new bin starts with full residual; add opening cost that shrinks
        // as the stream progresses (late in stream, prefer consolidation)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * progress;
        // if the item + next item would fill a fresh bin nicely, discount opening
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity - 5 {
            score -= 55.0;
        }
        // with many open bins, opening new ones fragments capacity: extra penalty
        if open_bins_count > 4 {
            score += 5.0 * (open_bins_count as f64 - 4.0).min(10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth non-linear coupling: reward high fill with a cubic term scaled by progress
    score -= 12.0 * fill.powi(3) * (0.5 + progress);

    // Penalize dead space that is too small for typical future items (smooth trough around 0)
    let dead = pr / cap;
    score += 8.0 * (-20.0 * dead).exp() * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward residual that fits the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let match_quality = 1.0 - (pr - nx).abs() / cap;
        score -= 6.0 * match_quality * (1.0 - fits_next / cap);
        // Penalize residual just barely below next item size (near-miss dead space)
        if pr < nx {
            score += 4.0 * (1.0 - pr / nx) * (1.0 - progress);
        }
    }

    // Discourage spreading across many bins when mean residual is high
    score += (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() * 0.05;

    // Mild new-bin penalty early, weaker late (opening fresh bins is cheap early)
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "useful" for common
    // item sizes get a bonus (subtracted), awkward residues get penalized.
    let r = post_residual;
    if r > 0 {
        // Favor post_residuals divisible by common size classes (10, 20, 25, 50)
        if r % 50 == 0 {
            score -= 12.0;
        } else if r % 25 == 0 {
            score -= 8.0;
        } else if r % 10 == 0 {
            score -= 5.0;
        } else if r % 5 == 0 {
            score -= 2.0;
        } else {
            // awkward residue: dead space penalty grows with small residual
            score += (bin_capacity as f64 - r as f64).min(r as f64) * 0.05;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack % 10 == 0 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportional to wasted lookahead
        score += (next_item_size as f64) * 0.08;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let penalty = 25.0
            - 15.0 * crowding
            - 10.0 * (1.0 - fit_quality)
            - 5.0 * progress;
        score += penalty.max(2.0);
    }

    // Mild preference for tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Slight pull toward mean residual: avoid fragmenting outliers.
    score += (mean_residual - bin_residual as f64).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that is too small for the minimum plausible item (1) is only
    // dead if tiny; treat gaps < 10 as "dead space" and punish quadratically.
    let r = post_residual as f64;
    if r < 10.0 {
        score += (10.0 - r) * (10.0 - r) * 2.0;
    } else {
        // Reward leaving a residual that can still fit typical items:
        // prefer residuals that are either large (>= ~30) or exact-ish fits.
        score -= (r / 10.0).floor() * 1.5;
    }

    // Exact fit bonus: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage tighter packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += pressure * 5.0;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (it sets up a good follow-up fit); otherwise slight penalty
    // if it wastes a residual the next item could have used better.
    if next_item_size > 0 {
        if (next_item_size as f64) <= r {
            score -= 8.0;
        } else if (next_item_size as f64) <= bin_residual as f64 && r < 10.0 {
            // This placement created dead space that the next item could not use.
            score += 6.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tightly packed; finishing it off is good.
    let diff = mean_residual - r;
    if diff > 0.0 {
        score -= diff * 0.5;
    } else {
        score += (-diff) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match strongly rewarded; near-matches partially rewarded.
        if match_gap == 0.0 {
            score -= 60.0;
        } else {
            score += match_gap * 0.35;
        }
        // If next item fits in the post residual, mild bonus for chaining.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Penalize leaving dead space that nothing typical can use: post_residual far below mean residual
    // means this bin's leftover is unusually small (good), but a tiny unusable remainder is wasted.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // dead space penalty: unusable sliver
    }

    // Compare post residual against mean residual across open bins:
    // leaving this bin below the mean concentrates space elsewhere (good packing).
    score -= (mean_residual - pr) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer filling existing ones over opening new bins.
    score += open_bins_count as f64 * 0.5;

    // Slight time drift: later in stream, tighten packing (favor low post residual more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.15 * progress;

    // New-bin candidate: only attractive when it beats filling a bin poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + pr * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 18.0 + 0.25 * n;
            // bonus if next item exactly fills leftover
            if next_item_size as u32 == post_residual {
                score -= 20.0;
            }
        } else {
            // leftover unusable by next item: mild penalty scaled by gap
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 0.12 * gap.min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits (large mean residual) or item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // penalize new bins mildly, less so for large items and late in stream
        score += 30.0 - 25.0 * item_frac - 10.0 * progress;
        // if open bins are fragmented (high mean residual), new bin is more attractive
        score -= 0.15 * mean_residual;
        // many open bins already: discourage spreading
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer filling bins with lower residual among comparable fits (best-fit bias).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Slight pressure to close out bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) penalty
    let mut score = post + 60.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: as stream advances, tighten packing more aggressively
    let tighten = 1.0 + 0.8 * progress * progress;
    score *= tighten;

    // Dead-space penalty relative to mean residual: bins far below mean residual are wasteful
    let mean_gap = (mean_residual - post) / cap;
    score += 25.0 * mean_gap * mean_gap - 8.0 * mean_gap;

    // Lookahead coupling: reward leaving room for the next item (smooth interaction)
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_next = post - next;
        if fit_next >= 0.0 {
            // smooth reward decaying with slack after next item fits
            score -= 12.0 * (1.0 - fit_next / cap);
        } else {
            // penalize residual that cannot host next item, scaled by gap size
            score += 6.0 * (-fit_next / cap).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when good fits exist
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 15.0 + 55.0 * scarcity * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins early
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo capacity fractions.
    // Small post-residuals in "tight" classes (0..10, or near 50) are valuable.
    let pr = post_residual;
    let class: i64 = match pr {
        0 => -3,
        x if x <= 10 => -2,
        x if x <= 20 => -1,
        x if x <= 30 => 0,
        x if x <= 50 => 1,
        x if x <= 70 => 2,
        _ => 3,
    };
    score += class as f64 * 4.0;

    // Perfect/tight fits: strongly reward leaving near-zero dead space.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // harmonic class match on integer division thresholds
            let q_next = (pr / next_item_size.max(1)).min(4);
            score -= q_next as f64 * 6.0;
            if pr - next_item_size <= 10 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize large leftover slightly
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): neutral-ish baseline; only attractive
    // when existing bins are fragmented (high mean residual relative to item).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling already-open bins when many are open.
    score += (open_bins_count as f64) * 0.2;

    // Penalize creating dead space far from mean residual (fragmentation).
    let dev = (pr as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    // Anything below a "useful threshold" gets a super-linear penalty.
    let pr = post_residual as f64;
    let dead_threshold = 20.0;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 0.6;
    }
    if pr == 0.0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement is excellent; penalize if it nearly fits but not quite.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few,
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress) * 2.0;
    score += pressure * 0.5;

    // Mean residual coupling: prefer bins with residual near the mean
    // (keeps the pool homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // New-bin candidate handling: an empty bin is only attractive when
    // no open bin offers a decent fit (post_residual large means poor fit here).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened if many bins already open
        // or the current fit is terrible (large post_residual on alternatives
        // is already penalized, so make new bin moderately expensive).
        score += 55.0 + 8.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // fresh bin can host future mid-size items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            if gap == 0.0 {
                score -= 60.0; // perfect two-item pairing
            } else {
                score -= 25.0 * (1.0 / (1.0 + gap / 10.0));
            }
            // penalize leaving a residual too small for the next item (dead space)
        } else if pr > 0.0 {
            score += 15.0 + pr * 0.3;
        }
    }

    // Tight fits preferred: small post residual is good overall.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead suggests waste.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
            score += 10.0; // fresh bin can serve next item too
        }
    }

    // Late in the stream, consolidate: prefer reusing bins over spreading.
    let progress = step_index as f64 / total_items as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large wasted space, with a non-linear (squared) coupling.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Reward tight fits (small post-residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: mild penalty to keep fragmentation spread out.
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let lookahead_fit = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - lookahead_fit / cap);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            score += 5.0;
        }
    } else {
        // Last item: prefer fullest possible packing.
        score -= 10.0;
    }

    // Global state: when many bins are open relative to progress, discourage
    // keeping many half-empty bins; encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bins_pressure = open_bins_count as f64 / (1.0 + progress * 20.0);
    score += 0.4 * bins_pressure;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier small bin — favor closing it out by filling it.
    let residual_diff = mean_residual - pr;
    if residual_diff > 0.0 {
        score -= 0.15 * residual_diff;
    } else {
        score += 0.05 * (-residual_diff);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a moderate baseline penalty.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    score -= 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor small post_residual, non-linearly.
    let tight = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - tight).powi(4);

    // Penalize dead space relative to mean residual: bins with residual far below
    // mean are precious; wasting them is costly late in the stream.
    let mean_gap = (mean_residual - post_residual as f64) / cap;
    score += 15.0 * mean_gap.max(0.0) * (1.0 + 3.0 * progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: reward leaving a gap that fits the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nx = next_item_size as f64;
        if gap >= nx {
            score -= 12.0 * (gap / cap) * (1.0 - (gap - nx) / cap);
        } else {
            score += 6.0 * (nx - gap) / cap;
        }
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But late in stream, consolidation pressure: new bins less attractive.
        score += 20.0 * progress;
        // If no open bin can fit and item is large, opening is necessary: soften.
        if fitting_bins_count == 0 && item_size as f64 > 0.5 * cap {
            score -= 55.0;
        }
    }

    // Mild stream-progress polynomial coupling: encourage tighter packing later.
    score *= 1.0 + 0.5 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Post-residuals that are "nice" (divisible by 5/10/25) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 6.0; }
        // Very small dead space is bad unless it is zero
        if pr < 10 { score += 15.0 + (10 - pr) as f64; }
        // Mid-range residuals (30..50) are the most reusable for unknown items
        if (30..=50).contains(&pr) { score -= 6.0; }
        else if (51..=70).contains(&pr) { score -= 2.0; }
    } else {
        score -= 20.0; // perfect fit
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 && pr >= next_item_size {
        let nxt_post = pr - next_item_size;
        if nxt_post == 0 { score -= 12.0; }
        else if nxt_post % 10 == 0 { score -= 5.0; }
        score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's leftover; penalize proportionally
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets baseline; discourage opening
    // a new bin when decent fits exist, encourage when current fit is terrible.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items into fresh bins is fine
        }
        if item_size > 70 { score -= 10.0; }
    }

    // Progress: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / bin_capacity as f64);

    // Tight fit reward (item fills most of the bin)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness reward: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized instead.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If no other bin fits well, allow new bin when open bins are crowded.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: favor leaving residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // Mild phase bias: later in stream, consolidate more.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * phase;
    }

    // Prefer bins with below-average residual (tighter bins) to keep loose bins flexible.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills this bin afterwards.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits snugly into the post-residual (small leftover chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * snug;
    }
    // Next item would NOT fit here: leftover becomes dead space risk.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead;
        // Extra penalty for tiny unusable slivers (< 10).
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below the mean residual (tighter, more fragmented bins)
    // to consolidate space into larger residuals for future items.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate (empty bin): only attractive when this is the last item
    // or no good fit exists; penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * (1.0 - progress);
        // If next item is large and current bin fit is terrible, allow new bin.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > (post_residual as f64) + 20.0 {
            score -= 30.0;
        }
    }

    // Mild reward for high fill ratio.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that nothing (min size 1..) can use well:
        // reward residual >= 50 (still reusable), penalize tiny residuals.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr);
        } else if pr >= 50.0 {
            score -= 5.0;
        }
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.5 * open_bins_count as f64;
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 10.0 } else { 0.0 };
        score = base + pressure + post_residual as f64 * 0.3;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when an open bin is the only fit
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * (0.5 + progress);
        if (bin_residual as f64) > mean_residual + 20.0 {
            score -= 4.0; // prefer filling emptier bins to reduce mean residual spread
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer minimal post-residual, with non-linear (quadratic) emphasis.
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Dead-space penalty: if the lookahead item cannot use the post-residual,
    // the leftover is likely wasted — penalize smoothly with squared coupling.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 25.0 * gap * gap * cap;
    }

    // Smooth stream-progress coupling: as the stream advances, tighten the
    // preference for tight fits (cubic interaction with post_residual).
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_term * pr_norm * cap * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // to avoid opening a new bin (subtract smoothly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * prog_term;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit; relax slightly late in the stream.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + open_pressure * 10.0 * (1.0 - prog_term) - 15.0 * prog_term;
    }

    // Mild reward for bins tighter than the mean residual (compactness preference).
    score -= 5.0 * ((mean_residual - pr) / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that end up fuller (small post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 15.0; // extra pressure toward near-full placements

    // Dead-space penalty: residuals below 10 are hard to fill later
    // (min item size historically ~10, but be conservative for 1..100).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic class logic: quantize post_residual into modulo classes.
    // Residuals that are exact multiples of 10 pair well with typical sizes.
    let m = post_residual % 10;
    score += m as f64 * 0.8;

    // Lookahead synergy: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Perfect chaining: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins are already open or mean residual is still large.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        if mean_residual > 25.0 {
            score += (mean_residual - 25.0) * 0.5;
        }
    }

    // Prefer bins already below mean residual (consolidate emptier space).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Mild late-stream conservatism: late in the stream, tighten fits
    // since fewer items remain to fill leftover gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0;

    // Fitting scarcity: when few bins can host this item, favor this one.
    if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // next item can't reuse the gap: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Open-bin pressure: prefer fewer open bins, but not at the cost of dead space.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless it wins otherwise.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is more attractive early (more future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Mild deviation from mean residual: prefer bins with less room (tighter packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    // Reward bins whose post_residual can EXACTLY host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item completion: this bin becomes exactly full after the next item.
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how tight the match is.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 400.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize leaving a residual that is too small
            // to be useful for the lookahead item (dead-space risk).
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    } else {
        // Last item in stream: pure tightness packing.
        score -= 200.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins that are already well-filled (below-mean residual) to avoid
    // scattering small residuals across many bins.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 1.5 * mean_gap;

    // Penalize bins far above mean residual (poorly filled) mildly.
    if mean_gap < 0.0 {
        score += 0.5 * (-mean_gap);
    }

    // --- Last-chance bonus ---
    // If this is the only fitting bin, strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin gets a neutral-ish baseline: good for large items or
    // when no open bin offers a good fit, but discouraged when a tight fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as stream progresses (fewer
        // opportunities left to fill new bins).
        score += 250.0 * (1.0 - 0.5 * progress);
        // Opening a new bin is attractive when the item is large relative to capacity.
        score -= 1.2 * item_size as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 120.0;
        }
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > item_size {
            score -= 60.0;
        }
    }

    // Small tie-breaker: tighter fits (smaller post_residual) always preferred.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), but only if the leftover is still usable.
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if next > 0.0 {
        if post >= next {
            // leftover can host the next item: strong reward
            score -= 12.0 + 0.25 * next;
        } else if post > 0.0 {
            // dead space relative to lookahead: penalize
            score += 6.0 + (next - post) * 0.15;
        }
    } else {
        // last item: prefer fullest packing
        score -= 20.0;
    }

    // Prefer bins whose residual is close to item_size (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // penalize new bin when existing bins have plenty of room
        score += 10.0 + avg_open * 0.2;
        // late in the stream, opening new bins is more wasteful
        score += 15.0 * progress;
    } else {
        // slightly reward using existing bins as stream progresses
        score -= 3.0 * progress;
    }

    // Mild penalty for too many open bins (fragmentation control)
    score += open_bins_count as f64 * 0.05;

    // Non-linear coupling: bins with very small unusable leftovers are bad targets
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: prefer tight fits, with a non-linear (quartic) penalty on wasted space.
    let mut score = pr * (1.0 + 2.0 * fit * fit * fit);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized.
    score += pr * pr / cap * progress * 1.5;

    // Reward using bins when many are open (consolidation pressure), smoothly.
    let open_f = open_bins_count as f64;
    score -= (open_f / (open_f + 4.0)) * (cap - pr) * 0.5;

    // Lookahead: if next item fits the post-residual exactly or well, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= (cap - gap) * 0.3;
        } else {
            score += gap * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a poor-fit outlier bin; penalize smoothly.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.4;

    // New-bin candidate: discourage opening a new bin unless the current item
    // would leave a very awkward residual elsewhere. Smooth ramp.
    if bin_residual == bin_capacity {
        let awkward = (pr - cap * 0.5).abs() / (cap * 0.5);
        score += cap * (0.6 + 0.5 * awkward * awkward) - progress * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste quality depends on residue mod 10
    let r = post_residual;
    let class = r % 10;
    // Residues near 0 are "clean" (item sizes often multiples of 10); penalize less
    score -= match class {
        0 => 6.0,
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        _ => 0.0,
    };

    // Penalize small-but-unusable residuals (dead space)
    if r > 0 && r < 10 {
        score += 8.0;
    }

    // Perfect fit bonus
    if r == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad residuals
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.05 * open_bins_count as f64;
        // If this bin (new) leaves a cleaner residual than typical open bins, allow it
        let open_clean = mean_residual < (post_residual as f64) + 5.0;
        score += if open_clean { base * 0.4 } else { base };
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Harmonic pairing: post_residual and next item share a divisor class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Tightness reward: filling a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Mean residual coupling: prefer bins whose residual is near the mean (typical fit),
    // penalize outliers
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 6.0;
    } else if dead >= 10.0 && dead < 20.0 {
        score += (20.0 - dead) * 2.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity as f64 as u32 - item_size;
    if new_bin {
        score += open_bins_count as f64 * 3.0 + 10.0;
    } else {
        // Favor bins tighter than the mean residual (better packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual == 0 as u32 as u32) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with diminishing returns for tiny residuals
    let pr = post_residual as f64;
    score = pr + 0.15 * (pr * pr) / bin_capacity as f64;

    // Exact / near fit with the NEXT item (2-step lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // next item can fit here: reward tight chaining
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 15.0; // perfect chain: post_residual == next_item_size
            }
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += 0.4 * (gap / 100.0) * pr;
        }
    } else {
        // Last item: pure tight-fit preference
        score -= 5.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Relative to mean residual across open bins: prefer bins tighter than average
    score += 0.5 * (mean_residual - pr) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating unusably small residuals (dead space < typical min item)
    if pr > 0.0 && pr < 10.0 {
        score += 25.0;
    }

    // New-bin candidate handling: attractive early, discouraged when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // allow opening a new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // discourage opening a new bin when the item would leave a huge gap elsewhere anyway
        if next_item_size > 0 && next_item_size >= item_size && pr as u32 == 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize if the next item no longer fits after placement,
    // but only mildly if this fit is good.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }
    // Reward if next item fits exactly in the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }

    // Penalize opening a new bin more when many bins are already open
    // and their mean residual could still absorb items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
        // But if open bins have large residuals (poor fits), new bin is less bad.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    } else {
        // Slight preference for bins with residuals close to item needs
        // (best-fit coupling with global state).
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Late in the stream, consolidate: prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 8.0 * poly;

    // Penalize tight fits that leave dead space when lookahead can't use it
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        let fit_penalty = if next_item_size as f64 > pr {
            (next_item_size as f64 - pr) / cap
        } else {
            0.0
        };
        score -= 3.0 * waste / cap;
        score += 6.0 * fit_penalty * (1.0 - progress);
    } else {
        score += 2.0 * norm_pr * norm_pr;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * (1.0 - progress);
    }

    // Compare against mean residual: penalize bins that deviate badly
    score += 0.5 * (pr - mean_residual).abs();

    // Mild preference for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3 * (1.0 - norm_pr);

    // New-bin candidate: keep it neutral-to-slightly-poor unless residuals are large
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modulo arithmetic) ---
    let pr = post_residual as i64;
    let class = pr % 10; // residue class mod 10
    // Reward residuals that land in "harmonic" classes: multiples of 5 or 10,
    // and small residuals that future small items (10..80 originally, but 1..100 here) can fill.
    match class {
        0 => score -= 18.0,          // perfect alignment
        5 => score -= 12.0,          // half-harmonic
        2 | 4 | 6 | 8 => score -= 4.0, // even classes pair with even items
        _ => score += 3.0,           // odd residues are harder to fill exactly
    }

    // Integer-division threshold: residual buckets by division into capacity fractions
    let quarter = (bin_capacity / 4) as i64;          // 25
    let half = (bin_capacity / 2) as i64;             // 50
    if pr == 0 {
        score -= 30.0; // perfect fit is always best
    } else if pr <= quarter {
        score -= 8.0;  // small dead space, easy to leave
    } else if pr <= half {
        score += 2.0;  // medium residual
    } else {
        score += 10.0; // large residual wasted in an already-open bin
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx <= pr {
            // next item fits: reward proportional to how well it fills
            let fill = (pr - nx) as f64;
            score -= 14.0 - 0.15 * fill;
            // harmonic bonus if the pair (pr, next) is class-aligned
            if (pr - nx) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize bins that would strand the lookahead
            score += 5.0 + 0.1 * (nx - pr) as f64;
        }
    } else {
        // last item: any bin that fits is fine, prefer tightest
        score -= 10.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, keep the competitive tightness pressure
        score -= 2.0 * (fitting_bins_count as f64).ln();
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only good late in the stream or when current bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = mean_residual < (item_size as f64) * 0.6;
        if crowded && progress > 0.15 {
            score -= 20.0; // open a fresh bin rather than fragmenting
        } else {
            score += 40.0; // prefer existing bins early / when they fit well
        }
    }

    // --- Global pressure: with many open bins, discourage spreading ---
    score += 0.35 * open_bins_count as f64;

    // --- Mean-residual alignment: prefer bins whose residual tracks the fleet mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Stream phase modulation: tighten selection as stream progresses ---
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 40.0 * dead;

    // Mid-range residual waste penalty (non-linear coupling on post_residual).
    let pr = post_residual as f64;
    score += 0.15 * (pr * pr) / bin_capacity as f64;

    // Reward tight fits: exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score -= 0.4 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit and post residual is small, slightly penalize.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins are open
    // or when current bin fit would be very poor.
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - open_bins_count as f64 / 10.0);
        score += 0.5 * mean_residual;
    }

    // Slight preference for keeping mean residual balanced.
    score += 0.2 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Tightness ratio: reward near-perfect fills.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // 2-step lookahead: reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            // reward proportional fit of the lookahead item
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space
            score += 15.0 + (post_residual as f64 - mean_residual).abs();
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving more than average waste is penalized.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 + open_bins_count as f64 * 0.5;
    }

    // Early in the stream, be more willing to open fresh bins for good fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 {
        score += 5.0 * (1.0 - progress * 5.0);
    }

    // Brand-new bin candidate: prefer it when the item is large and current
    // open-bin fits would leave big dead space.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 20.0; // large items start fresh bins
        } else if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room for a companion item
        } else {
            score += 10.0; // otherwise discourage wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be used by typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into fuller bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more exploratory (slightly prefer new bins for big items);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        if progress < 0.3 {
            score -= 5.0; // exploratory: allow opening bins early
        } else {
            score += 0.3 * waste / 10.0 * (0.5 + progress); // late: discourage new bins
        }
    }

    // Mean residual coupling: when mean residual is high, prefer bins below mean (fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear tight-fit reward: quadratic in post_residual fraction.
    let pf = post_residual as f64 / cap;
    score += 8.0 * pf * pf * cap;

    // Reward bins whose residual is well below mean (consolidating space).
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Reward if next item fits exactly into post-residual (perfect lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residual too small for the next item (dead space).
        let dead = post_residual as f64 / next_item_size as f64;
        score += 4.0 * (1.0 - dead) * (1.0 - dead);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly early, more when many bins open.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = cap + 3.0 * crowd + 10.0 * progress;
        // Allow opening a new bin if no open bin gives a good fit.
        if post_residual == 0 && fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "awkward"
    // small classes (1..=9) are near-perfect fits; reward them strongly.
    let pr = post_residual;
    let awkward = pr > 0 && pr <= 9;
    let mid_class = pr > 9 && pr <= 25;

    if awkward {
        score -= 40.0;
    } else if mid_class {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nr = post_residual - next_item_size;
        score -= 25.0;
        if nr == 0 {
            score -= 35.0;
        } else if nr <= 9 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover; leftover is likely dead space.
        // Penalize proportionally to how small and unusable it is.
        if pr > 0 && pr < 10 {
            score += 12.0;
        }
        // If next item is large, prefer bins where post_residual still
        // accommodates big future items: penalize small post_residual.
        let frac = pr as f64 / cap;
        score += (1.0 - frac) * 6.0;
    }

    // Harmonic class of next_item_size modulo capacity quarters: if next item
    // is in the "large" class (> cap/2), tighten selection (add pressure).
    if next_item_size > bin_capacity / 2 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full (mean residual small) or this item is large relative to
    // typical residuals.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // Opening fresh is attractive when open bins are mostly full.
        score = 60.0 + mean_frac * 40.0;
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // Late in stream, avoid proliferation of bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If only one bin fits and it's tight, still prefer it over new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Mild preference for fuller bins overall (tie-break toward high fill).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 5.0;

    // Small noise-free harmonic jitter based on modulo classes to break ties
    // deterministically.
    let tiebreak = ((post_residual as usize * 31 + next_item_size as usize * 17) % 7) as f64;
    score += tiebreak * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fits (small absolute gap, weighted non-linearly).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap it almost fits.
        score += 5.0;
    }

    // New-bin candidate: opening a fresh bin is costly unless current fit is bad
    // or no real open bin exists; make empty-bin baseline moderately high.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If current best-fit would leave tiny dead space, opening new bin is fine.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual is already the base).
    let tightness = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if tightness < 0.10 {
        score -= 50.0 * (0.10 - tightness);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 120.0; // next item fits perfectly afterwards
        } else {
            let gap_f = gap as f64;
            // decaying reward: small gaps are valuable, large gaps useless
            score -= 80.0 * (-gap_f / 20.0).exp();
        }
        // penalize leaving residual that no plausible item (>=1) can use
        if post_residual < 10 {
            score += 30.0; // dead space too small for any item
        }
    } else {
        // last item: only perfect fits matter
        if post_residual > 0 {
            score += 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins that keep residual spread balanced,
    // unless this is a last-chance bin (fitting_bins_count == 1).
    let dev = post_residual as f64 - mean_residual;
    if fitting_bins_count > 1 {
        score += 0.5 * dev.abs();
    } else {
        // last chance: heavily reward using this bin instead of opening a new one
        score -= 60.0;
        score += 0.1 * dev.abs();
    }

    // New-bin candidate handling: opening a bin is only attractive when current
    // bins fit poorly or the stream is early and we want many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fitting_bins_count <= 1;
        let big_item = item_size >= 50;
        if poor_fits && (big_item || progress < 0.3) {
            score -= 40.0; // open a fresh bin for a big item or early stream
        } else {
            score += 80.0; // discourage needless bin proliferation
        }
        // lookahead: opening a new bin leaves residual 100-item, great for next item
        if next_item_size > 0 && (next_item_size as f64 / bin_capacity as f64) > 0.5 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize creating a residual that just barely blocks the next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 10.0 { score += 18.0 - gap; }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Reward tight fits (item consumes most of the bin's current residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Penalize leaving small, likely-dead residuals (1..=9 unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Mild pressure toward consolidating residual mass as the stream progresses.
    score += 0.04 * (1.0 - t) * mean_residual;

    // Penalize spreading across many open bins when residuals are plentiful.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual >= item_size {
        score -= 3.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless nothing fits
    // or all existing fits would be catastrophically wasteful.
    if bin_residual == bin_capacity {
        score = 200.0; // default: never open a new bin when alternatives exist
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        } else if item_size as f64 > mean_residual + 15.0 {
            // existing fits are very loose; opening may still be preferable
            score = 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.6 * t * t + 0.9 * t * t * t;
    score += norm_pr * norm_pr * cap * (poly - 1.0);

    // Penalize large dead space more as stream progresses (less time to reuse it)
    score += norm_pr * norm_pr * norm_pr * cap * (0.5 + t);

    // Reward tight fits (small post_residual) with smooth exponential-like term
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.6;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= g * (1.0 - g) * ns * (0.4 + 0.6 * t);
        } else {
            score += (-gap) * (0.3 + 0.5 * t);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * t;
    } else if fitting_bins_count > 1 {
        // Prefer bins with more competition (better relative fit)
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize mildly, more so early when consolidation is cheap
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * t;
    }

    // Slight preference toward bins with residuals near the item (smooth coupling)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += diff * diff * cap * 0.25;

    // Mild regularization toward mean residual to balance load
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but avoid tiny dead space (waste) and huge residuals.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is gold
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Harmonic class of post_residual: residual in {0,10,20,...} are reusable slots
    // for common small items; odd/awkward residuals are dead space.
    let r = post_residual;
    if r >= 10 && r % 10 == 0 {
        score -= 6.0;
    } else if r > 0 && r < 10 {
        score += 12.0; // sub-10 residual is nearly unusable dead space
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            if post_residual - next_item_size <= 10 {
                score -= 8.0; // leaves another near-perfect fit
            }
        } else {
            score += 5.0; // cannot host next item
        }
    } else {
        // Last item: minimize waste aggressively.
        score = post_residual as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are fragmented / high. Use mean_residual as fragmentation proxy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + mean_residual * 0.6 - progress * 10.0;
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size <= post_residual {
            // a fresh bin could serve the next item well; soften penalty slightly
            score -= 5.0;
        }
    }

    // Many open bins with low mean residual: discourage spreading, encourage
    // filling existing bins densely.
    if open_bins_count > 4 && mean_residual < 25.0 {
        score += 4.0;
    }

    // Modulo threshold on item size: large items (>= 50) should go into
    // bins where they leave harmonically useful residuals.
    if item_size >= 50 && post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps are only usable by tiny items; penalize proportionally.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 {
            score -= 18.0 * fill_ratio;
        } else if fill_ratio > 0.5 {
            score -= 8.0 * fill_ratio;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // placing here sets up a perfect follow-up placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new/partially-filled bins; encourage consolidation.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 4.0
            + mean_residual * 0.5
            + (fitting_bins_count as f64) * 10.0;
        // Base cost of a fresh bin; large items waste less of it.
        score = 55.0 - 0.25 * (item_size as f64 - 50.0) + pressure;
    }

    // Mild progression term: later in the stream, waste matters more
    // (less opportunity to recover).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins with lower residual than average (tighter bins).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.5;
        // extra bonus if the pair nearly fills the bin
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if pair_fill > 0.9 {
            score -= 50.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Prefer tight fits relative to mean residual
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // baseline penalty so open bins usually win unless they leave large waste
        score += 60.0;
        // more attractive early in the stream when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
        // if current bin would leave unusable small residual, new bin is fine
        if post_residual < 10 {
            score -= 70.0;
        }
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize waste relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward leaving residual that matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        let fragmentation = mean_residual < bin_capacity as f64 * 0.35 && open_bins_count > 2;
        if poor_fit || fragmentation || next_item_size == 0 {
            score -= 10.0 + progress * 5.0;
        } else {
            score += 20.0; // discourage opening bins when a decent fit exists
        }
    }

    // Mild time decay: early on, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Slight penalty for too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer tight fits (low post_residual), non-linearly damped
    let mut score = pr;

    // Quadratic dead-space penalty: small residuals are disproportionately bad
    score += 0.35 * (pr * pr) / cap;

    // Smooth stream-progress coupling: later in stream, tolerate larger residuals less
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score *= progress_coupling;

    // Reward good fit relative to mean residual across open bins
    score -= 0.5 * (mean_residual - pr).max(0.0);

    // Lookahead: bonus if residual after placement can still fit next item
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        score -= 6.0 * fits_next;
        // Penalize leaving residual that almost-but-not-quite fits next item
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.15 * gap.min(20.0) * (1.0 - fits_next);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // More open bins: mild penalty for spreading items too thin
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: heavy penalty so we only open when all fits are poor
    score += is_new_bin * (cap * 0.6 + 20.0 * progress);

    // Slight reward for using a large fraction of the bin now
    score -= 0.4 * (item_size as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" integer-division classes (multiples of small block sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is king
    } else {
        // class by post_residual / 10 : low classes are more reusable
        let class = pr / 10;
        score -= (class as f64) * 2.0;

        // modulo arithmetic: residuals divisible by 5 or 10 are friendlier
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0; // odd-sized dead space penalty
        }

        // dead-space cliff: tiny unusable slivers
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match classes between next item and post residual
            let diff = pr - next_item_size;
            if diff == 0 {
                score -= 40.0; // chains perfectly
            } else if diff <= 10 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0; // divisibility harmony
            }
        } else {
            // next item won't fit here regardless
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening fresh should only win when the
    // current fit is terrible or this bin would be left with slivers.
    if bin_residual == bin_capacity {
        // baseline competitiveness of a fresh bin
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        // avoid opening new bins when plenty of bins fit fine
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Stream progression: early on, be greedy about tight packing;
    // late, prefer closing bins out (favor near-full bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: penalize spreading, encourage consolidating into
    // bins whose residual is near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (open_bins_count.min(20) as f64 / 20.0);

    // Waste ratio term: relative leftover
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any realistic future item are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 8 {
        score += 40.0; // tiny unusable gap
    } else if post_residual > 0 && post_residual <= 12 {
        score += 18.0;
    } else if post_residual > 0 && post_residual < item_size {
        score += 6.0; // gap smaller than current item: likely dead space
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item exactly matches the resulting
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // residual too small for next item: dead space risk
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if mean_gap > 15.0 {
            score -= 5.0; // open bins are loose; new bin acceptable
        } else {
            score += 35.0 + 10.0 * (1.0 - progress); // prefer filling open bins
        }
        // Slight decay of new-bin cost over the stream.
        score -= 5.0 * progress;
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus: squash residual aggressively near zero.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        score += (pr / cap) * 20.0; // penalize larger dead space nonlinearly
        score += (pr * pr) / cap;   // quadratic waste penalty
    }

    // 2-step lookahead: reward bins whose post_residual exactly fits next item,
    // penalize when next item cannot use the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 40.0; // chain fit: perfect two-item packing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // next item fits, but leaves more slack
        } else {
            // next item won't fit in leftover; penalize proportionally to waste
            score += (nxt - post_residual as f64) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical";
    // prefer consuming bins that are already far below mean (nearly full).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it only
    // wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (cap - item_size as f64) * 0.4;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // slightly prefer fresh bin if next item is bigger
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;

    // --- Reward tight fits (small post_residual) ---
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // --- Lookahead: bonus if the next item fits exactly in the post-residual ---
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 12.0 * (1.0 + progress);
    }
    // Penalize placements that leave a residual that the next item almost fits
    if next_item_size > post_residual && next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 10.0 {
            score += gap * 0.4;
        }
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (1.0 + progress);
    }

    // --- Penalize scattering residual across many open bins ---
    if open_bins_count > 1 && !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is attractive when few bins fit the item or open bins
        // have poor (large) residuals relative to the item.
        let poor_fit_penalty = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        // Early in the stream: keep bins open; late: prefer compacting.
        score += 18.0 + poor_fit_penalty * 0.6 - progress * 10.0
                 - (fitting_bins_count as f64).min(4.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Smooth polynomial coupling: wasted space is increasingly costly later in the stream
    score += 40.0 * norm_post.powi(2) * (0.5 + progress);
    score -= 25.0 * norm_post * (1.0 - norm_post) * (1.0 - progress);

    // Lookahead: reward leaving exactly the next item's size (perfect pairing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_closeness = 1.0 - ((post - nxt) / cap).abs();
        score -= 30.0 * match_closeness.max(0.0).powi(3);
        // Penalize residual that cannot fit next item but is too big to be dead space
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer reuse, but allow if open bins are fragmented
    if is_new_bin {
        score += 35.0 * (1.0 - progress);
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Fragmentation: if mean residual is small, opening fresh bin is attractive
        score -= 20.0 * (mean_residual / cap).max(0.0).min(1.0);
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - ((bin_residual as f64) - (item_size as f64)) / cap;
        score -= 10.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Harmonic class: classify post_residual into capacity-fraction bands.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score -= 25.0; // nearly full bin, great outcome
        } else if frac < 0.25 {
            score -= 10.0;
        } else if frac < 0.50 {
            score += 5.0;
        } else {
            score += 15.0; // lots of dead space created
        }

        // Integer-division thresholds: small dead space that a small item could use.
        if post_residual <= 10 {
            score -= 12.0; // unusable sliver is fine (effectively full)
        } else if post_residual >= 10 && post_residual < 20 {
            score += 4.0; // awkward zone
        }
    }

    // Lookahead: favor bins whose leftover can host the next item (mod-style matching).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if leftover is a "harmonic" multiple band of next item.
        if post_residual % next_item_size.max(1) <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0; // leftover too small for next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Opening fresh is attractive when few bins fit the item or item is large.
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if pressure > 0.0 && !big_item && fitting_bins_count > 1 {
            score += 45.0; // discourage new bin when good alternatives exist
        } else {
            score -= 8.0; // reasonable to open a fresh bin
        }
    }

    // Mildly prefer consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.5 * (0.5 + progress);

    // Prefer bins with below-average residual (denser bins) for tight packing.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 * (-tightness).exp();

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or mean residual is tiny.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64) * 0.2;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: favor bins leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Mild stream progression coupling: prefer consolidation early, allow new bins late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less waste after placement is primary signal.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * waste * waste * (bin_capacity as f64);

    // 2-step lookahead: reward if next item exactly fills post_residual (perfect chain).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Prefer bins whose leftover matches the next item size.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 80.0; // perfect chain bonus
            }
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += 0.5 * (next - pr);
        }
    }

    // Relative fill vs mean residual: filling below-average-residual bins is efficient.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 45.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 40.0 + 60.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64 - item_size as f64) {
            score += 10.0; // opening a new bin rarely better when lookahead could chain
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Dead-space penalty: small but nonzero leftovers are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // residual still useful for next item: mild reward proportional to left-over after next
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here: penalize wasted residual relative to next item
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from the mean residual are less attractive targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, keep bins flexible (prefer larger post residual slightly less);
    // late in the stream, be greedy about tight fits.
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin gets a mild fixed cost so it's chosen only when
    // existing fits are poor (its raw post_residual is already large).
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (item_size as f64 / 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic in post residual (mild waste aversion)
    let mut score = pr * (1.0 + 0.5 * norm_pr);

    // Smooth polynomial coupling of waste with stream progress:
    // late in the stream, tight fits matter more (waste penalized quadratically harder)
    let tightness = 1.0 - norm_pr;
    score += 30.0 * progress * (norm_pr * norm_pr) * (1.0 - tightness * tightness);

    // Reward near-perfect fills smoothly (small post_residual bonus, stronger later)
    let fill_bonus = (-norm_pr * norm_pr * 40.0).exp();
    score -= fill_bonus * (10.0 + 20.0 * progress);

    // Last-chance bin: reward strongly, scaled by smooth progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - (fits_next / cap);
        score -= 12.0 * fit_quality * fit_quality;
        score += 6.0 * (nxt / cap) * (1.0 - fit_quality);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / cap);
    score += 20.0 * crowd * (1.0 - progress);

    // New-bin candidate: penalize mildly unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let poor_fit = (norm_item - 1.0).abs(); // ~0 for full-capacity-like items (rare)
        let waste_if_used = cap - item_size as f64;
        score += 8.0 - 6.0 * (1.0 - waste_if_used / cap) - 5.0 * progress * (1.0 - fit_alignment(norm_item));
    }

    score
}

#[inline]
fn fit_alignment(norm_item: f64) -> f64 {
    // smooth measure of how "large" the item is (larger items favor new bins less)
    let x = norm_item.clamp(0.0, 1.0);
    x * x * (3.0 - 2.0 * x)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "useful" small-remainder classes are rewarded for tight fits.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for the smallest item (size 1
        // interface, but practically items >= 10 in classic setting): treat
        // residual < 10 as nearly useless.
        if post_residual < 10 {
            score += 50.0;
        }
        // Harmonic classes of post_residual: leftover in [0, quarter) is a
        // "small class" (mostly dead), leftover in [quarter, half) can host
        // medium items, leftover >= half is flexible.
        if post_residual < quarter {
            score += (quarter - post_residual) as f64 * 0.5;
        } else if post_residual < half {
            score -= (half - post_residual) as f64 * 0.3;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a two-item harmonic chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here; mildly penalize wasting large residuals.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item
    // is large and no open bin offers a good fit. Otherwise discourage it
    // so we prefer filling existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = bin_capacity as f64 - item_size as f64;
        score = waste * (1.0 + 0.5 * progress);
        if fitting_bins_count > 0 {
            score += 300.0; // some open bin fits: prefer it over a new bin
        }
        if item_size >= half {
            score -= 120.0; // large items are fine to start fresh bins
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (tighter bins) to keep many bins near-full.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Modular harmonic nudge: bins whose residual is a multiple of 10 keep
    // clean class boundaries for typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to be
    // useful for future items are heavily penalized (unusable gaps).
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Penalize wasting a large residual on a small item when many bins are open.
    if (item_size as f64) < 0.35 * bin_residual as f64 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin is only attractive when existing residuals
    // are poor fits (item barely fits or dead space would be created) or when
    // open-bin pressure is low.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (bin_residual as f64 - item_size as f64) < dead_threshold
            || (bin_residual as f64 - item_size as f64) > 0.7 * bin_capacity as f64;
        if poor_fit || open_bins_count == 0 {
            score -= 30.0 + 10.0 * (1.0 - progress);
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Lookahead: if next item fits snugly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual as f64 - next_item_size as f64) < dead_threshold;
        if snug {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in the leftover: leftover is likely dead space.
        score += 6.0;
    }

    // Mild open-bins pressure: discourage scattering across many bins.
    score += 0.15 * open_bins_count as f64;

    // Slight preference to deviate from the mean residual (balance bin loads).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead space penalty: small positive residuals are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: mild reward.
            score -= (next_item_size as f64).min(40.0);
        } else {
            // Next item won't fit: penalize proportionally to leftover waste.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New empty bin candidate: penalize unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 50.0 + open_bins_count as f64 * 2.0;
        // If item is large and would leave little residual, opening may be fine.
        let large_item_relief = if item_size >= 60 { 40.0 } else { 0.0 };
        score += base_penalty - large_item_relief;
        // If this is the last chance, soften the penalty.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
    }

    // Early stream: be slightly more willing to open bins (build structure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual is good).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            score -= 20.0 + 0.3 * nr;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += 0.15 * (nr - post_residual as f64).min(nr);
        }
    }

    // Last-chance bonus: only one bin can fit this item — use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) among many options.
    if fitting_bins_count > 1 {
        score += 0.05 * (bin_residual as f64 - item_size as f64);
    }

    // Time horizon: early in stream, encourage filling open bins to keep bin count low;
    // later, be more tolerant of opening new bins for good fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin gets base cost that shrinks over time
    // and grows with number of open bins (avoid bin explosion).
    if bin_residual == bin_capacity {
        score = cap - post_residual as f64; // baseline = 100
        score += 15.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        // If no open bin fits well, opening is more attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // last chance open bin: discourage new bin
            score += 50.0;
        }
        // If mean residual across bins is small, new bin is reasonable.
        score -= 0.2 * mean_residual;
    }

    // Global pressure: many open bins with large mean residual -> push to fill them.
    if open_bins_count > 2 {
        score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early on, keep bins flexible
    let coupling = prn * (1.0 - prn) * (1.0 - prn); // peaks at moderate fill
    score -= 40.0 * coupling * (0.3 + 0.7 * progress);

    // Penalize dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 12.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - ns) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Encourage bins near mean residual (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: which quarter of the bin remains.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    let class_penalty: f64 = match quarter {
        0 => -25.0, // nearly perfect fit (residual < 25)
        1 => -10.0, // residual 25..49
        2 => 5.0,   // residual 50..74
        _ => 12.0,  // large residual 75..99
    };
    score += class_penalty;

    // Fine harmonic class: multiples of 10 (common item size quantum).
    let residue10 = post_residual % 10;
    score += residue10 as f64 * 0.6; // prefer residuals aligned to the size grid

    // Lookahead: reward if next item fits exactly into post residual, penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            } else {
                score += (slack as f64) * 0.15;
            }
        } else {
            score += 15.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * 20.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins below mean (fuller than average).
    score += (mean_residual - post) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { -60.0 } else { 45.0 };
        score += desperation;
        // Late in the stream, opening new bins is fine (no future to plan for).
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.9 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post_residual scaled (dead space avoidance).
    let mut score = post_residual as f64 * 1.0;

    // Strict dead-space penalty: post_residual in (0, 10) is nearly unusable
    // since item sizes are >= 1 and typically larger; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly accommodates the item (small waste ratio).
    if bin_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 15.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly penalize bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item_size,
    // which is large; add a fixed opening cost so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Progress: late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // Aggressive 2-step lookahead: reward post_residual that exactly matches
    // the next item size (perfect chain), reward close matches.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = (post_residual as f64 - nxt).abs();
            score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit here; post_residual becomes dead space risk
            score += 8.0 + 0.15 * post_residual as f64;
        }
    } else {
        // Last item: any placement is fine; prefer tightest fit
        score -= 20.0;
    }

    // Penalize creating unusable dead space (residual below minimum item size 1..small)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open-bin fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; add penalty proportional to how many bins already fit
        // the item (discourage wasteful new bins when fits exist).
        if fitting_bins_count > 0 {
            score += 35.0 + 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If next item is large and current item is small, opening a fresh bin
        // may preserve flexibility — mild bonus.
        if next_item_size > 0 && next_item_size > item_size && item_size <= 40 {
            score -= 15.0;
        }
    } else {
        // Existing bin: bonus for keeping mean residual balanced (avoid fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.10 * dev;
    }

    // Late-stream: consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins with larger residual among equals (use emptier bins for big items)
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: check if next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item chains into this bin.
            score -= 20.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
        } else {
            // Dead space risk: residual too small for the next item.
            let waste = post_residual as f64;
            score += waste * 0.5;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Mild penalty so tight fits in existing bins win; relaxed when many bins are open.
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Global state: if mean residual is high, prefer consolidating into bins with low residual.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Time horizon: as stream progresses, be more conservative (favor existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Fragmentation penalty relative to mean residual.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap; // how full the bin becomes

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    let mut score = pr * (1.0 + 0.8 * prog2 + 0.6 * prog3);

    // Reward tight fits increasingly over the stream (smooth non-linear)
    score -= tightness * tightness * (30.0 + 60.0 * prog2);

    // Penalize near-mean residuals slightly (avoid clustering waste)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Last-chance bin: reward strongly with smooth ramp
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * prog2;
    }

    // Lookahead: bonus if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            let k = fit_gap / cap;
            score -= 15.0 * (1.0 - k) * (1.0 - k) * (1.0 + progress);
        } else {
            score += 8.0 * (-fit_gap / cap) * (1.0 + prog2);
        }
    }

    // Mild penalty for proliferating bins late in stream
    score += 0.3 * (open_bins_count as f64).ln() * (0.5 + prog3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls into
    let item_class = (item_size * 4) / bin_capacity; // 0..3 harmonic class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward placements whose post-residual lands on a useful harmonic class
    // (small residuals that can still host small items, or exact zero)
    match post_residual {
        0 => score -= 25.0,                       // perfect fit
        p if p < 10 => score += 18.0,             // dead space (< min item)
        p if p <= 25 => score -= 8.0,             // hosts quarter-class items
        p if p <= 50 => score -= 3.0,             // hosts half-class items
        _ => score += 2.0,
    }

    // Modulo arithmetic on residual: residuals divisible by common item sizes
    // are "harmonic" and likely to be filled later.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 5.0; }
        else if r % 5 == 0 { score -= 2.5; }
        else { score += 1.5; }
        // residual in a good gcd class with next item
        if next_item_size > 0 && r % next_item_size == 0 {
            score -= 12.0;
        }
    }

    // Coupling with next item: can this bin hold both? (harmonic pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64 / cap) * 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = cap * (1.0 + 0.4 * (open_bins_count as f64 / (step_index.max(1) as f64 + 1.0)));
        if pressure < 0.35 { score -= 20.0 * (0.35 - pressure); }
    }

    // Prefer fuller bins overall (tightness coupling)
    score -= (1.0 - (bin_residual as f64 / cap)) * 4.0;

    // Late in stream: consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= ~10) are nearly worthless; punish them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger usable leftovers are mildly desirable.
        score -= 4.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement; if post residual is awkward for the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 45.0;
            } else if gap <= 10.0 {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: when many bins are already open, discourage creating
    // more; when few are open, allow slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(1.3) * (0.4 + 0.6 * progress);

    // Mild alignment with mean residual: bins tighter than average are preferred targets.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for already-opened (non-empty) bins vs. the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 2.0 * next_item_size as f64;
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // perfect chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 300.0;
        }
    }

    // Penalize tiny unusable residuals (dead space < min plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 { (next_item_size as f64 - post_residual as f64).abs() } else { 0.0 };
        score += 80.0
            + open_bins_count as f64 * 2.0
            - if fitting_bins_count == 0 { 150.0 } else { 0.0 };
        let _ = poor_fit;
    }

    // Slight late-stream tightening: keep bins compact as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 150.0;

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize when the next item would be stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            score += 25.0;
        }
        // Chain fit: exact chain completion is excellent.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // Last item: minimize residual as hard as possible.
        score += dead_frac * 400.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 + 0.3 * item_size as f64;
        if dead_frac < 0.3 {
            score -= 50.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits or the stream is early with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alternatives = (mean_residual - item_size as f64).abs() > 30.0;
        if poor_alternatives && open_bins_count > 0 && progress < 0.7 {
            score -= 80.0;
        } else {
            // Default: mildly discourage opening new bins.
            score += 70.0 + 2.0 * open_bins_count as f64;
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        // Prefer fuller bins: tighter current residual is better.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= tightness * 60.0;
        // Mild bonus for keeping bin count from exploding.
        score += 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: tight fit reward (small post_residual is good), softened non-linearly.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // wasted space matters more as the stream advances (endgame packing quality).
    let x = pr / cap; // normalized post residual in [0,1]
    let w = 0.5 + 1.5 * progress; // weight grows smoothly with progress
    score += w * x * x * cap; // quadratic dead-space penalty, scaled by capacity

    // Perfect fit bonus (smooth, non-piecewise): strong reward as post_residual -> 0.
    score -= (1.0 - x).powi(6) * 12.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (penalize new-bin opening implicitly).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate (bin_residual == bin_capacity): discourage unless the item
    // barely fits anywhere else. Penalize mildly; grow penalty with open bins count
    // and mean residual (existing bins have slack to absorb the item).
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 6.0 + 0.3 * open_bins_count as f64 + 10.0 * slack * (1.0 - progress);
        // If next item is large and this bin would be empty for it, ease opening.
        if next_item_size > 0 {
            let nx = next_item_size as f64 / cap;
            score -= 6.0 * nx * nx;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward
    // (smooth interaction between post_residual and next_item_size).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= (1.0 - gap).powi(4) * 5.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Post residual can't host next item: mildly penalize small leftover.
        score += 2.0 * (1.0 - pr / (next_item_size as f64 + 1.0)).max(0.0);
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // when the item fits well (diversity of bin states aids future packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.5 * dev * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "dead" class (small but not tiny) are penalized; reusable classes rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds: 0..10 classes
    match class {
        0 => score -= 40.0,                          // near-perfect fill
        1 => score += 25.0,                          // 10..19: classic dead space
        2 => score += 12.0,
        3 | 4 => score -= 8.0,                       // 30..49: fits mid items
        5 | 6 => score -= 15.0,                      // 50..69: very reusable
        _ => score -= 5.0,                           // large residual, flexible
    }

    // Modulo coupling: residuals divisible into common item sizes are gold.
    if pr > 0 {
        if pr % 10 == 0 { score -= 10.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 5.0; }
    }

    // Lookahead: does next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        let next_class = slack / 10;
        score -= 20.0 - 2.0 * next_class as f64;     // reward chains that stay tight
        if slack % 10 == 0 { score -= 6.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; penalize less if this bin is nearly full anyway.
        let fill_frac = (bin_residual as f64) / cap;
        score += 15.0 * (1.0 - fill_frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let prog = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (pr as f64)).abs();
        score = cap * (1.0 - 0.35 * prog) + 0.15 * fragmentation;
        if open_bins_count == 0 { score -= 100.0; }
        if fitting_bins_count == 0 { score -= 50.0; }
    }

    // Mild preference for tighter bins overall.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // Treat gaps below the smallest plausible item (<= 8) as pure dead space.
    if post_residual > 0 && post_residual < 8 {
        score += 40.0;
    }
    // Gaps in the awkward range (8..20) are partially wasted; penalize quadratically.
    if post_residual >= 8 && post_residual < 20 {
        let g = post_residual as f64;
        score += 0.05 * (20.0 - g) * (20.0 - g);
    }

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading items across many bins early;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Prefer bins with residual below the mean (pack tighter bins first),
    // unless this is the empty new-bin candidate.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 8 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in post-residual, mild penalty for fragmenting future options.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit. Make the empty bin moderately expensive so tight fits win,
    // but cheap enough to beat badly fragmenting placements.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.4 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (waste pocket).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits perfectly into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0; // perfect chain fit
            } else if gap < 10 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; slightly penalize leaving large residual.
            score += 0.02 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate logic: opening a new bin is attractive only if the item
    // is large relative to capacity (better to start fresh than fragment a bin)
    // and we are early enough in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin, discounted for large items and low congestion.
        let congestion = open_bins_count as f64;
        score = 25.0 - 20.0 * size_ratio - 3.0 * (1.0 - progress) + 1.5 * congestion;
        // If existing bins fit but are poor hosts (high mean residual mismatch),
        // opening a new bin can still win; keep score competitive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin also chains the next item
        }
    }

    // Mild penalty for scattering across many open bins; encourage consolidation.
    score += 0.01 * open_bins_count as f64;

    // Slight nudge toward bins with residuals close to the item size (min waste).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.05 * (fit_gap - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: prefer small post_residual, with polynomial shaping
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits, amplified as stream progresses
    score -= 8.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 3.0 * (pr - mean_residual) / cap;

    // Last-chance bin: reward using it, especially early/mid stream
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let next_norm = next / cap;
            score -= 6.0 * next_norm * (1.0 - (pr - next) / cap);
        } else {
            score += 2.0 * (next / cap);
        }
    }

    // Mild penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - progress) + (fitting_bins_count as f64);
    }

    // Interaction: reward large item into bin whose residual is just above item size
    let slack = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * slack * slack * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are gold; small residuals
    // (1..10) are dead space; residuals that can host the lookahead item are great.
    if post_residual == 0 {
        score -= 1000.0; // perfect packing
    } else if post_residual <= 10 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0; // tiny unusable slivers
    }

    // Lookahead fit classes: does next item fit exactly / partially in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0) * 0.5;
        } else {
            // next item won't fit here: penalize by overflow gap class
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish score anchored at capacity fraction.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // fresh bin can also take lookahead
        }
        if fitting_bins_count > 0 {
            score += 15.0; // mild bias toward reusing existing bins
        }
    }

    // Modulo-10 harmonic classes of post_residual: prefer residuals that are
    // multiples of common item granularities.
    let class = post_residual % 10;
    if class == 0 && post_residual > 0 {
        score -= 15.0;
    } else if class >= 5 {
        score += 5.0;
    }

    // Fraction-of-capacity thresholds on post_residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 10.0; // roomy bin still useful
    } else if frac < 0.2 && post_residual > 10 {
        score += 10.0; // low-utility remainder
    }

    // Stream progression: early on, be conservative; late, squeeze bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: discourage spreading.
    if open_bins_count > 3 && mean_residual > 20.0 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small for the smallest plausible item (1..100 range, min item 1).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1) as u32) {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual exactly or well, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if post_residual as f64 >= nxt {
            score -= 5.0;
        } else {
            score += 6.0; // next item can't use leftover: dead space likely
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress);

    // Mild attraction to bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish but penalize opening bins early.
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward minimal waste strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for any item (min size 1,
    // but tiny residuals are hard to reuse) are penalized super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves waste; mild reward proportional to tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * tightness;
        } else {
            // Next item will NOT fit here: penalize bins that block the lookahead.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from the mean residual (tighter-than-average bins get priority).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (residual_f - mean_residual) / mean_residual;
        score += 20.0 * dev;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as the stream
    // progresses and open bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 150.0 + 100.0 * progress + 10.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if the item is huge and no tight fit is possible elsewhere,
        // opening a fresh bin is fine (the lookahead term already handles it).
        if item_size >= 80 {
            score -= 120.0;
        }
    }

    // Slight preference for bins with larger residual generally (keeps
    // small residuals from accumulating unusable space).
    score -= 0.1 * residual_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
