pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize wasted post-residual, with non-linear (quadratic) coupling to stream progress.
    let mut score = pr * (1.0 + 1.5 * progress * pr_norm);

    // Smooth dead-space penalty: residuals too small to be useful later get extra quadratic cost.
    let dead_threshold = 0.15 * cap;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / cap;
        score += 30.0 * d * d;
    }

    // Reward tight fits (small post residual relative to item) with smooth inverse coupling.
    score -= 20.0 * item_norm * (1.0 - pr_norm);

    // Lookahead: reward if next item fits the post residual (smooth sigmoid-like term).
    if next_item_size > 0 {
        let fit_next = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (fit_next / (1.0 + (-8.0 * fit_next.abs()).exp()));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins open
    // and their mean residual could still absorb items; smooth in open_bins_count.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln1p();
        score += 12.0 + 3.0 * crowd + 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mild penalty for bin proliferation relative to progress.
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (hard to fill later) are penalized.
    let pr = post_residual;
    if pr > 0 {
        // Modulo classes on capacity fractions
        let quarter = bin_capacity / 4;
        let eighth = bin_capacity / 8;
        if pr < eighth {
            // Dead space: nearly unusable
            score += 40.0;
        } else if pr < quarter {
            score += 10.0;
        } else if pr % 10 == 0 {
            // Perfectly harmonically aligned leftover (likely to pair with future items)
            score -= 15.0;
        } else if pr % 5 == 0 {
            score -= 8.0;
        }
    } else {
        // Perfect fit: excellent
        score -= 100.0;
    }

    // Lookahead coupling: does the leftover harmonically fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 60.0; // chain: perfect two-item fill
            } else if gap % 10 == 0 {
                score -= 25.0;
            } else if gap < 10 {
                score += 20.0; // leaves tiny dead space after next item
            }
        } else {
            // Next item cannot use this bin's leftover; leftover is terminal
            score += 25.0;
        }
    } else {
        // Last item: minimize leftover strictly
        score += pr as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer reusing bins unless residual is large
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score scaled by stream position
        score = 60.0 + (step_index as f64 / total_items.max(1) as f64) * 30.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a harmonic pair
        }
        // In late stream, opening new bins is cheap relative to fragmentation
        if open_bins_count > 8 && mean_residual > 40.0 {
            score -= 15.0;
        }
    }

    // Mild preference to consolidate across many open bins
    score += (open_bins_count as f64) * 0.5;

    // Mean-residual coupling: penalize making residuals deviate from mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
