    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        if post_residual as i64 == next_item_size as i64 && next_item_size > 0 {
            score -= 40.0; // still allow fresh bin if it chains perfectly
        }
    }

    // Small bonus for very tight fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize dead space: post_residual that cannot hold a typical future item.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += (1.0 - usable) * (post_residual as f64) * 0.8;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (post_residual - next_item_size) as f64;
        score -= 10.0 - chain * 0.05;
    } else if next_item_size > 0 {
        // Next item won't chain here; slight penalty proportional to how much it misses.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's already tight; use it.
    let dev = mean_residual - bin_residual as f64;
    score += dev.max(0.0) * 0.4;
    score -= (-dev).max(0.0) * 0.2;

    // Time horizon: early in the stream, be conservative (keep bins flexible); later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // New-bin candidate: only attractive when current fit is very poor or residual is huge but item tiny.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.35;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 40.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows with progress and residual size.
    let waste = pr / cap;
    score += waste * waste * (1.0 + 6.0 * progress) * cap * 0.35;

    // Reward tight fits (small post_residual) increasingly over time.
    score -= (1.0 - waste) * (1.0 - waste) * (2.0 + 4.0 * progress);

    // Lookahead: bonus if next item exactly fits the post-residual (perfect chain).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let match_term = 1.0 / (1.0 + diff * diff * 0.05);
        score -= match_term * 6.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize bins far from mean residual (imbalance), scaled by open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * (open_bins_count as f64).min(10.0) * 1.5;

    // New-bin candidate: keep it moderately attractive only when stream is early
    // or the fit here is terrible; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score = cap * (0.9 - 0.45 * early) + waste * cap * 0.2;
        if fitting_bins_count > 1 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted after placement

    // Hard penalty on tiny unusable residuals (dead space classes)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits (post_residual in the smallest harmonic band)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Modulo-class coupling: residuals that are multiples of common item granularities
    // (10, 20, 25) are more likely reusable by future items -> reward them.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds on next_item_size: does the next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits after this placement: strong chain bonus.
            score -= 10.0;
            // Extra bonus if next item exactly fills the bin (perfect chain).
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // Next item won't fit: this residual becomes dead unless a later small item comes.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += frac * 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (contain fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * (open_bins_count as f64).ln().max(0.0) * 2.5 * (0.5 + progress);

    // Mild pull toward the mean residual: avoid extreme outliers in bin fullness.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate penalty: only open a new bin if residual spread is bad.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.2;
        // Allow opening fresh bin early in the stream when mean residual is high.
        if mean_residual > 40.0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // conceivable future item are worthless "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // unreachable in practice, but guards logic
    }
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(min_item)) {
        // gap smaller than the current or next item: likely unusable
        score += 40.0 + 0.5 * post_residual as f64;
    }
    // Perfect fit is golden
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, tiny sliver
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight
    // placements in existing bins; few open bins -> new bins are cheap.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 10.0 + 2.5 * open_pressure;
        // If item is huge relative to capacity and nothing fits well, new bin ok
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Late in stream with many bins, avoid opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Reward using existing bins more when many are open
        score -= 1.5 * open_pressure;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — using it consolidates fragmentation.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // dead space relative to known next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // penalize leftover that doesn't serve the next item proportionally
            let waste = (post_residual - next_item_size) as f64;
            score += 0.35 * waste;
            // reward if next item leaves a tiny residual too (chained fits)
            let post2 = post_residual as f64 - nxt;
            if post2 < 10.0 {
                score -= 12.0 * (10.0 - post2);
            }
        } else {
            // next item cannot use this bin's remainder: dead-space risk
            score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize very small unusable residuals (dead space), unless it's a perfect fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfectly closed bin is excellent
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        let poor_fit = post_residual as f64 > mean_residual * 1.5;
        if crowded || poor_fit || open_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 40.0; // discourage spreading items across fresh bins
        }
    }

    // Early in stream: slightly favor consolidation; late: avoid tiny leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fit: reward small post residual relative to capacity
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 0.6 * tightness;

    // Penalize dead space: post residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to how far off
        score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate waste)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be pickier about dead space; late, fill anything
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    // Crowding: many open bins -> prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = post + 0.6 * (post * post) / cap;

    // Normalized fill quality: reward bins that end up well filled.
    let fill = item / cap;
    score -= 12.0 * fill * (1.0 - progress);

    // Dead-space penalty grows smoothly with how close post_residual is to unusable sizes.
    let dead = (post / cap).powi(3);
    score += 25.0 * dead;

    // Interaction: post_residual vs stream progress — late in stream, waste matters more.
    score += 8.0 * (post / cap) * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 10.0 * progress;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual deviates favorably from the mean residual.
        score -= 0.15 * (mean_residual - resid);
    }

    // Lookahead coupling: if the next item could use the post_residual, reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 6.0 * (nxt / cap) * (1.0 + progress);
        } else {
            // Next item can't use leftover space: penalize proportionally.
            score += 4.0 * ((nxt - post) / cap).max(0.0);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.4 * open_bins_count as f64 * progress * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "compatible" with the 10..80 item scale, others create dead space.
    let harmonic = post_residual % 10;
    score += harmonic as f64 * 2.5;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize mid-range dead space (10..30) that few items can use.
    if post_residual > 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Next item cannot fit here: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.3 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive if no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win when they fit decently.
        score += 55.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If the next item is also large, opening a fresh bin preserves order.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Many open bins with high mean residual -> better to spread load.
        if open_bins_count > 3 && mean_residual < (bin_capacity as f64) * 0.35 {
            score -= 30.0;
        }
    }

    // Slight preference to fill bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Progress term: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Dead-space penalty: small unusable gaps (< smallest plausible item ~ 10% cap)
    let dead_threshold = 0.10 * cap;
    if post > 0.0 && post < dead_threshold {
        score += 40.0 * (dead_threshold - post) / dead_threshold;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating gaps that the lookahead item cannot use
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as f64;
        if n > post {
            score += 12.0 * (1.0 - post / n);
        } else {
            // lookahead fits: reward proportionally
            score -= 10.0 * (post / n).min(1.5);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline with pressure from open bins count
    if bin_residual == bin_capacity {
        // Opening new bin is attractive when few open bins or mean residual is fragmented
        score = 0.35 * cap - 2.0 * open_bins_count as f64;
        if mean_residual > 0.5 * cap {
            score += 15.0; // existing bins have plenty of room; avoid spreading
        }
        if next_item_size > 0 && next_item_size as f64 > post {
            // empty bin always fits lookahead: slight bonus
            score -= 5.0;
        }
    }

    // Mild fragmentation pressure: prefer bins below mean residual (consolidate fullness)
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev;
    }

    // Stream progression: late in stream, be slightly more conservative (pack tighter)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the remainder
            let second_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * second_fit;
        } else {
            // next item cannot fit here: penalize leaving awkward space
            let gap = (post_residual as f64 - 0.0).max(0.0);
            if next_item_size - post_residual <= 10 {
                score += 8.0;
            }
            score += 0.05 * gap;
        }
    } else {
        // last item: prefer fullest packing
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual are more precious
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item
    if item_size < 20 && bin_residual <= 30 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Slight preference to spread across bins when many are open with slack
    if open_bins_count > 5 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small to hold a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 {
        // Nonlinear penalty: residuals just below typical item sizes are wasteful.
        let r = post_residual as f64;
        score += 12.0 * (1.0 - (r / 100.0)).powi(3);
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    } else {
        // Last item: maximize packing density aggressively.
        score -= 25.0 * fill;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller ones.
    if open_bins_count > 2 {
        score -= 2.5 * (open_bins_count as f64).ln() * fill;
    }

    // Global state: if mean residual is high, encourage using existing space.
    if mean_residual > item_size as f64 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Time horizon: early in the stream, be picky (keep bins flexible);
    // late in the stream, just pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * t * fill;

    // New-bin candidate: only attractive when item is large or nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if post_residual > 0 && post_residual < 20 {
            score += 15.0; // new bin would leave tiny dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual with smooth polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0 * x * (1.0 - x));

    // Penalize large dead space quadratically, damped early in the stream
    score += 12.0 * (1.0 - progress) * x * x * cap;

    // Reward tight fits: small post-residual gets a smooth bonus
    score -= 8.0 * (-pr / 20.0).exp() * (1.0 + progress);

    // Last-chance bin: strong smooth reward to use it rather than open new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64 / cap;
        score -= 6.0 * nx * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate: smooth penalty scaled by how many bins are open
    if bin_residual == bin_capacity {
        score += 4.0 + (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);
    }

    // Mild penalty for deviating from mean residual (balance preservation)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in the "hard to fill" band
    // (small leftovers < 10) is nearly worthless; heavily penalize.
    let dead = post_residual < 10;
    if dead {
        score -= 25.0; // filling a bin to near-exactness is great
    } else {
        // Penalize unusable-class leftovers via modulo classes of 10
        let cls = post_residual % 10;
        score += (cls as f64) * 0.6;
    }

    // Reward tight fits (small post residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64).max(1.0);
    score -= 12.0 / (1.0 + tightness);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            // prefer leftovers that keep usable harmonic classes for next item
            score -= 10.0 * frac;
            let cls = post_residual % 10;
            if (next_item_size % 10) == cls {
                score -= 4.0;
            }
        } else {
            // leftover can't host next item: penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless current residuals
    // are fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base penalty so open bins win unless they are poor fits
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits: must open new bin
        } else if mean_residual > 60.0 && item_size <= 30 {
            score -= 10.0; // big residual fragmentation, small item: new bin ok
        }
        let _ = fragmentation;
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Slight exploration term via step harmonic class
    score += ((step_index % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for future items (min item size 1, but realistically small gaps < 12)
    // are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 12.0 {
            // Unusable sliver: strong penalty proportional to how "wasted" it is.
            score += (12.0 - gap) * 4.0;
        } else if gap < 25.0 {
            // Marginal gap: moderate penalty.
            score += (25.0 - gap) * 1.5;
        }
    }

    // Reward near-perfect fills (post_residual very small but nonzero handled
    // above; exact fill is ideal).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // (penalize new-bin candidate implicitly by subtracting from open bins).
    let bin_pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        // Existing bin: reward reuse more when many bins are open.
        score -= bin_pressure * 0.8;
    } else {
        // New-bin candidate: penalize proportional to open bin count.
        score += bin_pressure * 1.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid wasting this bin's remaining space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward;
    // if next item cannot fit, penalize leaving a gap that won't help.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space: mild reward scaled
            // by how well it uses the gap.
            let gap_use = next_item_size as f64 / post_residual as f64;
            score -= gap_use * 10.0;
        } else {
            // Next item won't fit here: the gap is dead space for lookahead.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the
    // mean (tighter bins get priority, homogenizing residuals).
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    // Stream progression: later in the stream, waste matters more (fewer
    // chances to recover), so tighten dead-space penalties.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0 * fill_ratio;
        if post_residual > 0 && post_residual < 12 {
            score += progress * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Aggressive 2-step lookahead: reward exact/excellent match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly reusable
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how well the next item fits the leftover
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space relative to next item
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    } else {
        // last item: only tightness matters
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving tiny unusable slivers (dead space traps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual near the mean are "normal"
    // candidates; very large residuals are precious, keep them for big items.
    let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
    if !big_item && bin_residual as f64 > 1.5 * mean_residual.max(1.0) {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate calibration: only open a new bin when the item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let tightness_elsewhere = (fitting_bins_count.max(1) as f64).recip();
        score = 45.0
            + 0.55 * (item_size as f64)
            + 2.0 * open_pressure
            - 35.0 * (1.0 - tightness_elsewhere);
        if next_item_size > 0 && (next_item_size as i64 - post_residual as i64).abs() <= 5 {
            score -= 20.0; // fresh bin chains perfectly with next item
        }
    }

    // Mild stream-progression pressure: consolidate more as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space is the enemy).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving small, hard-to-use residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin could host the next item directly instead.
            score += 6.0;
        }
    }

    // New-bin candidate logic: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when nothing fits well.
        score += 15.0;
        // More open bins => prefer consolidating into existing ones.
        score += 2.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // Late in the stream, avoid leaving many open bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 10.0 * progress;
        // If mean residual is large, existing bins have room; discourage new bin.
        score += mean_residual * 0.3;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // Lookahead: a fresh bin can surely host the next item.
        if next_item_size > 0 {
            score -= 5.0;
        }
    } else {
        // Mild bonus for keeping mean residual balanced (avoid fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer division thresholds.
    let post = post_residual as f64;
    let residue = post_residual % 10;
    let decade = post_residual / 10;

    // Reward small, "clean" post residuals (low dead space), especially residues near 0.
    score -= 12.0 * (1.0 - residue as f64 / 10.0).powi(2);

    // Penalize mid-range dead space decades (11..40) which are hard to fill later.
    if decade >= 1 && decade <= 3 {
        score += 6.0 * (4.0 - decade as f64);
    }

    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if residue <= 2 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size as u32 <= post_residual {
            // Harmonic class of next item relative to post residual.
            let nres = post_residual % next_item_size.max(1);
            score -= 20.0 - (nres as f64) * 0.5;
        } else {
            // Next item won't fit here: penalize leaving a residual it can't use.
            score += 8.0;
            // But a residual that is a multiple-class of next_item_size is still useful later.
            if post_residual % 10 == 0 {
                score -= 4.0;
            }
        }
    }

    // New-bin candidate: only attractive when current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap * 0.55 + 40.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild stream-phase modulation: later in the stream, prefer consolidation.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * (1.0 - (post_residual as f64 / cap));

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.15 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful later are heavily penalized.
    // Anything below the minimum plausible item size leaves a "dead gap".
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Perfectly tight fit is great; a 1-9 gap is dead space. Distinguish via item size.
        if post_residual == 0 {
            score -= 40.0; // exact fit: excellent
        } else {
            score += 25.0; // unusable sliver: strong penalty
        }
    }

    // Mid-range gaps (10..30) are partially usable: mild penalty scaled by waste ratio.
    if post_residual >= 10 && post_residual < 30 {
        score += 0.35 * (30 - post_residual) as f64;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // bin becomes perfectly sized for next item
        } else if slack < 10 {
            score -= 10.0; // near-perfect lookahead fit
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; make the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open.
        score += 8.0 + 2.5 * open_bins_count as f64;
    } else {
        // Fitting into an existing bin relieves pressure.
        score -= 1.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if the fleet average residual is large, prefer the bin
    // whose post_residual brings it closest to (or below) the average, tightening the fleet.
    if bin_residual != bin_capacity {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * deviation;
    }

    // Early in the stream, be slightly more willing to open bins (build a spread of
    // residual sizes); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect two-step chain: post_residual exactly fits next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: minimize post residual as much as possible.
        score -= 4.0;
    }

    // Compare post_residual against mean residual: prefer bins that absorb slack
    // (post_residual below mean means this bin became tighter than average).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 1.5 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 0.8 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Penalize very small post-residuals only mildly (small fragments are usually
    // unusable, but exact-fit lookahead above already handles good cases).
    if post_residual > 0 && post_residual < 10 {
        score += 2.5;
    }

    // Prefer filling bins that are already partially used over near-empty ones,
    // unless a new bin is genuinely better (empty-bin candidate gets a mild handicap
    // so lookahead matching must overcome it).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (diversification);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (open_bins_count as f64).recip().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / cap;
    score -= 40.0 * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // next item fits here afterwards: bonus scaled by how snug
            score -= 15.0 * (1.0 - ((post_residual as f64 - nxt) / cap).abs());
        } else if post_residual as f64 > 0.0 {
            // next item won't fit: mild penalty proportional to leftover
            score += 6.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: when many bins are open relative to stream progress,
    // discourage opening new bins (penalize the empty-bin candidate implicitly
    // via mean_residual comparison).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are plentiful and residual mean is high.
        score += 10.0 + 20.0 * progress + 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    } else {
        // Existing bins get a mild preference, stronger when mean residual is low (bins are full).
        score -= 5.0 * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));
    }

    // Prefer bins with residual closest to item (best-fit sharpening).
    let gap = (bin_residual - item_size) as f64;
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: waste weight grows super-linearly
    // with residual, modulated by stream progress (late waste hurts more).
    let waste_poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    score += 0.5 * waste_poly;

    // Reward tight fits (near-zero post residual) more as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness * (0.5 + progress);

    // Lookahead synergy: bonus if the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 2.0 * fill * fill;
        } else {
            // penalize residuals that cannot host the lookahead item
            score += 0.5 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a brand-new bin when open bins exist and mean
    // residual suggests space is available; allow it late via progress.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let scarcity = (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 + 10.0 * (1.0 - progress) * (1.0 - scarcity);
    }

    // Mild preference for bins with larger residuals when many bins open.
    score -= 0.01 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap;

    // Dead-space penalty: residuals that cannot plausibly host typical items
    // are quadratic in how "orphaned" the residual is.
    let orphan = (frac - (frac * 4.0).floor() / 4.0) / 0.25; // 0..1 within quarter-class
    score += 3.0 * orphan * orphan * (1.0 - frac);

    // Reward tight fits: exact or near-exact residual closure
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Modulo-class bonus: residual divisible by common item granularities
    // (items often come in multiples of 5/10) keeps future pairing feasible.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can follow into this bin: strong reward, scaled by
            // how snugly the pair closes the bin.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 + 10.0 * snug;
        } else {
            // next item won't fit here; penalize residuals just below the
            // next item size (worst dead space).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 2.0 * (15.0 - gap);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when existing fits are poor or no bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (grows mildly with stream progress
        // and number of open bins to encourage consolidation).
        score = cap + 0.05 * (open_bins_count as f64)
            + 5.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item would leave a nicely usable residual in a fresh bin,
        // slightly discount the new-bin cost.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        // If nothing else fits (fitting_bins_count counts only open bins),
        // new bin is forced anyway; neutralize cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If a lookahead item matches the fresh-bin residual class, discount.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Mild pressure to prefer bins with below-mean residual (consolidate
    // fragmented bins first, keep large-residual bins flexible).
    score += 0.3 * (mean_residual - post_f).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (size 1..=100 interface) are nearly worthless. Penalize gaps in the
    // "dead zone" — small but nonzero post_residual.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // The smaller the leftover, the worse: quadratic blow-up near zero.
        score += (dead_threshold - post_residual as f64).powi(2) * 2.0;
    }
    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits: fraction of bin used by this item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 30.0;
        }
        // Late in the stream with few bins, consolidation matters less.
        if step_index as f64 / total_items.max(1) as f64 > 0.8 && open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // keep this bin attractive; if the next item needs more space than the
    // residual, this bin risks becoming dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            score -= 3.0;
        }
    }

    // Slight preference for bins whose residual deviates favorably from the mean.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space, amplified for small dead zones.
        let waste = post_residual as f64;
        score += (waste * waste) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (next_item_size as f64);
        // Perfect chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual just below the next item (blocking dead space).
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += 25.0 * (10.0 - gap);
        }
    }

    // Compare against mean residual: prefer bins tighter than the average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it neutral-ish but discourage when a good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large, opening a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 55.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference to fill bins with fewer alternatives available.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins relative to progress -> prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * 6.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (fill fuller bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic coupling of post_residual with item share of capacity.
    let item_frac = item_size as f64 / bin_capacity as f64;
    score -= (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64 * (0.5 + 0.5 * item_frac);

    // Penalize small dead space that nothing can use (smooth non-linear coupling).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead.powi(3) * bin_capacity as f64 * 0.8 * (1.0 - progress);

    // Lookahead: reward if next item fits exactly into post_residual; penalize near-miss.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64).powi(2);
        } else {
            score += 6.0 * (diff.abs() / bin_capacity as f64).powi(2) * 10.0;
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate handling: make empty bin costly unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // Allow new bin if it would give a perfect fit for the next item too.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Mild pressure toward balancing residuals against the mean.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Smooth stream-progress coupling: prefer filling existing bins later in the stream.
    score -= 5.0 * progress * (1.0 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "useful"
    // classes (small dead space, divisible-friendly slots for typical items).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: near-perfect fit (residual < 10% of capacity) -> strong reward.
    if frac <= 0.10 {
        score -= 60.0 * (0.10 - frac);
    }
    // Class B: residual in [10%, 30%] is a "dead zone" unless it exactly
    // matches a plausible next-item slot -> mild penalty scaled by modulo class.
    else if frac <= 0.30 {
        let cls = post_residual % 10;
        let match_bonus = if next_item_size > 0 && (next_item_size as u32) >= post_residual {
            0.0
        } else {
            (10 - cls) as f64 * 0.8
        };
        score += 6.0 + match_bonus;
    }
    // Class C: residual in (30%, 70%] is versatile; reward proportionally
    // with a harmonic (1/k) style bonus on the integer division class.
    else if frac <= 0.70 {
        let k = (post_residual / 25).max(1) as f64;
        score -= 8.0 / k;
    }
    // Class D: large residual (>70%) after placement means item was tiny
    // relative to bin; slight penalty to avoid wasting big bins on small items.
    else {
        score += 4.0 * (frac - 0.70);
    }

    // Exact modular fit: reward when post_residual is a multiple of 10
    // (common item sizes align with such slots).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bins are crowded or the item is large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / cap;
        score += 30.0 - 25.0 * crowding - 12.0 * big_item - 8.0 * progress;
        // If lookahead item is large and this item is small, opening a fresh
        // bin preserves a big slot elsewhere -> soften new-bin penalty.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual matches the next item when possible.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
            } else {
                score += 3.0;
            }
        }
        // Slight preference for tighter existing bins (smaller residual before).
        score += (bin_residual as f64 - item_size as f64) * 0.02;
    }

    // Mean-residual coupling: if open bins are already loose on average,
    // discourage fragmenting further; if tight, reward filling existing bins.
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: penalize tiny unusable gaps.
    if post_residual < 10 {
        score += 250.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward leaving gaps that the lookahead item can still use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Bonus if gap is tight around the next item (small slack left over).
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Gap cannot host the next item: mild penalty scaled by dead space.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure.
        score += 60.0 + 8.0 * pressure;
        // Opening a fresh bin is more attractive if existing residuals are large/fragmented.
        if mean_residual > item_size as f64 * 2.0 {
            score -= 20.0;
        }
    } else {
        // Filling an existing bin relieves pressure.
        score -= 0.3 * pressure;
        // Prefer bins tighter than the mean residual (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large residual it can't use.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If next item is large and current fit is bad, opening new bin may be worthwhile.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 90.0;
        }
    }

    // Late in stream: be more conservative, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with more open bins already (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how well item fills the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space creation (post residual in 1..10 is wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Slight penalty if next item cannot follow into this bin.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins are roomy
    // or few bins are open (early stream consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 + 20.0 * (1.0 - progress) + 15.0 * consolidation;

        // If many bins fit the item, opening a new bin is rarely good.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    } else {
        // Slight preference for bins with smaller residuals (best-fit bias),
        // modulated by global mean residual.
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Mild bonus for reusing bins when many bins are already open (limit spread).
    if open_bins_count > 8 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, smoothly modulated by stream progress.
    let mut score = pr * (0.5 + 0.5 * progress);

    // Non-linear coupling: quadratic waste penalty grows as stream progresses.
    score += cap * norm_pr * norm_pr * (0.5 + 2.0 * progress);

    // Lookahead synergy: reward residual that can host the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        let gap = ((pr - ns).abs()) / cap;
        score -= fits_next * ns * (0.6 + 0.4 * progress) * (1.0 - gap);
        score += (1.0 - fits_next) * gap * cap * 0.3;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= item_size as f64 * 1.5;
    } else {
        // Mild penalty for spreading across many fitting bins.
        score += (fitting_bins_count as f64 - 1.0).min(3.0) * 2.0;
    }

    // Prefer bins tighter than the mean residual (good packing density).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.4;
    score -= dev * cap * 0.2 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the fit is very tight,
    // more so late in the stream when consolidation matters.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += cap * (0.6 + 0.8 * progress) - item_size as f64 * 0.2;
    }

    // Reward dense fills with a smooth saturating term.
    let fill = item_size as f64 / cap;
    score -= fill * fill * cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (divisible into common chunk sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is best possible outcome
    } else if pr % 10 == 0 {
        score -= 8.0;  // leftover aligns with decile classes -> highly reusable
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0;  // awkward leftover
    }

    // Penalize tiny dead space (unusable slivers)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Integer-division threshold: leftover big enough for a typical next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 5.0 + (pr - next_item_size) as f64 / cap_f;
            // exact-class match: next item fills leftover perfectly
            if pr == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= (cap_f - post_f) * 0.5;
    }

    // Capacity fraction coupling: reward tight fills relative to capacity
    score -= (item_size as f64 / cap_f) * 6.0;

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins with small residuals
    if open_bins_count > 3 {
        score += (post_f - mean_residual) * 0.15;
    }

    // Stream progression: early on, be picky; late, accept decent fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate: make it moderately unattractive unless residual logic favors it
    if bin_residual == bin_capacity {
        score += 18.0;
        // but if item is large and no bin would be left reusable, opening is fine
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in [1, 9] is nearly worthless)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving gaps that can still fit typical items (>= 10)
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, avoid opening new ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 3.0;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate slightly when other bins fit
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact or near-exact match for the next item is highly desirable
        score -= 40.0 / (1.0 + diff);
        // Penalize post-residuals that are too small to fit the next item (dead space)
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a needless new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it is chosen only for genuinely poor fits
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * item_size as f64;
        // If nothing else fits well, allow new bin: reduce penalty when few fitting bins
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild preference for filling later in the stream with tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward placements that leave exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Reward tight fits (small post residual) with diminishing returns.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 6.0;

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize using a bin whose residual is far from the mean (fragmentation risk),
    // unless it is the last chance.
    if fitting_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when no good fit exists. Penalize the empty-bin call moderately,
    // but discount that penalty as the stream progresses (fewer future chances to
    // consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - 0.5 * progress);
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    // Mild reward for consolidating into bins with large residual (keeps small bins
    // available for small future items).
    score -= (bin_residual as f64 / bin_capacity as f64) * 1.5;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pre = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Smooth non-linear waste penalty: quadratic coupling of post_residual with capacity.
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * cap;

    // Reward tight fits: cubic decay of bonus as post_residual grows.
    let tight = 1.0 - norm_post;
    score -= 4.0 * tight * tight * tight * item;

    // Dead-space penalty if neither current item nor lookahead can use leftover space.
    if next > 0.0 {
        let usable_gap = (post - next).max(0.0);
        let waste_frac = usable_gap / cap;
        score += 10.0 * waste_frac * waste_frac * cap;
        // Reward bins whose leftover exactly anticipates the next item.
        let gap = (post - next).abs();
        score -= 3.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Stream progress coupling: as stream matures, prefer filling existing bins tighter.
    let progress_coupling = progress * progress;
    score -= 5.0 * progress_coupling * (pre / cap) * item / cap;

    // Penalize opening a new empty bin, more strongly later in the stream,
    // but relax when few bins fit (last-chance scenario).
    let is_new_bin = (bin_residual as u32 == bin_capacity) && post_residual == 0;
    if is_new_bin {
        let fitting = fitting_bins_count as f64;
        let relief = 1.0 / (1.0 + fitting);
        score += 12.0 + 18.0 * progress - 8.0 * relief;
        // New bin more attractive if item is large relative to capacity.
        score -= 6.0 * (item / cap) * (item / cap);
    }

    // Last-fitting-bin bonus: smooth sigmoid-like reward scaled by open bins count.
    if fitting_bins_count == 1 {
        score -= 7.0 / (1.0 + (open_bins_count as f64).ln().max(0.0));
    }

    // Mild penalty for deviating from mean residual state (keeps bin profile balanced).
    score += 0.05 * (post - mean_residual).abs();

    // Small penalty for spreading across many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..8 harmonic class

    // Reward tight fits (low post_residual) super-linearly within the lowest classes.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if class == 0 {
        score -= 18.0;
    } else if class == 1 {
        score -= 6.0;
    } else if class == 2 {
        score += 4.0;
    } else if class == 3 {
        score += 10.0;
    } else {
        score += 16.0; // large dead space
    }

    // Modulo arithmetic: residuals that are multiples of common item-size blocks are reusable.
    let rem5 = post_residual % 5;
    let rem10 = post_residual % 10;
    if rem5 == 0 {
        score -= 3.0;
    }
    if rem10 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain fit: perfect follow-up
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= quarter {
                score -= 8.0 + (quarter as f64 - slack as f64) * 0.1;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and mean residual across open bins is small (i.e., open bins are nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // New bin attractive only if open bins are crowded and item is big.
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if mean_frac < 0.2 && big_item {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 30.0 + 20.0 * mean_frac;
        }
    }

    // Mild preference to spread load when many bins are open and mean residual is high.
    if open_bins_count > 2 && mean_residual > 0.5 * bin_capacity as f64 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < 10 {
            score += 40.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < min_item as f64 as u32 + 5 {
            score += 18.0;
        }
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (1.0 - progress * 0.5);

    // Mean residual coupling: prefer bins below mean residual (filler bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else {
            score += 12.0 + 3.0 * (open_bins_count as f64).sqrt().recip();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - slack.min(60.0) * 1.5;
    }

    // Dead space: post_residual too small for any plausible next item (min size 1).
    if next_item_size > 0 && post_residual < next_item_size {
        // Waste is post_residual itself; penalize proportionally to how much is stranded.
        score += (post_residual as f64) * 1.2;
    }

    // Tight fit reward: item fills most of the bin now.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Compare residual against mean residual: prefer using bins with below-average
    // residual (denser bins) to keep large-capacity bins available.
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    } else {
        score -= 10.0;
    }

    // Last chance: only this bin can fit the item; strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream or when
    // open bins exist that could still absorb future items.
    if bin_residual == bin_capacity {
        score += 80.0;
        if open_bins_count > 0 && next_item_size > 0 {
            score += 30.0;
        }
        // Late in the stream, a fresh bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    }

    // Slight preference for keeping few open bins (reduces fragmentation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin consumed by placing the item here
    let tightness = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward very tight fits (small post_residual relative to bin), stronger early
    score -= 40.0 * (1.0 - post_frac) * (1.2 - 0.6 * progress);

    // Penalize dead space: small unusable post_residual (< 10, minimum item size)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 - 15.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer concentrating into fewer, better-fitting bins
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0 * (1.0 - post_frac);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    let mean_res_frac = mean_residual / bin_capacity as f64;
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0 * mean_res_frac;
    }

    // Prefer using nearly-full bins as time advances
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin should only win when fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * (1.0 - tightness) - 25.0 * progress * mean_res_frac;
        // opening a new bin is attractive if no open bin fits (fitting_bins_count would be 0 open fits)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear penalty on unusable dead space (post_residual too small to be useful later).
    let dead_zone = (norm_pr * std::f64::consts::PI).sin();
    score += 15.0 * (1.0 - dead_zone) * norm_pr * (1.0 - progress);

    // Tight-fit reward: strongly reward small post-residual via quadratic coupling.
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.3 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits well in the post-residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; slight penalty scaled by overflow.
            score += 4.0 * ((ns - pr) / cap);
        }
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's
    // chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = cap * (0.9 + 0.2 * progress) - 30.0 * scarcity - 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is below average (tighter bins).
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Harmonic class: classify post_residual by integer division thresholds.
    let class = post_residual / 10; // 0..10 classes of dead space
    score += match class {
        0 => -60.0,                 // near-perfect fill (residual < 10 unusable)
        1 => 5.0,
        2 => 12.0,
        3 => 20.0,
        4 => 30.0,
        5 => 35.0,                  // mid-range dead space (50-59) is bad
        6 => 28.0,
        7 => 22.0,
        8 => 14.0,
        9 => 6.0,
        _ => 0.0,                   // mostly empty bin
    };

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-slack / 15.0).exp();
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: only attractive when current fit is poor
    // or nothing else fits.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = (open_bins_count as f64).ln() * 6.0;
        // New bin good when post_residual would be large (item small relative
        // to empty bin) and few alternatives exist.
        score = 100.0 - fit_quality * 55.0 + open_penalty
            - pressure * 70.0 * (1.0 - progress * 0.4);
        // Discourage opening a new bin for a small item late in the stream.
        if item_size < 30 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && next_item_size > post_residual && next_item_size > 0 {
        // This bin's leftover cannot fit the next item -> dead space likely.
        score += 8.0 + (post_residual as f64) * 0.5;
    }
    // Reward if leftover exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open / late stream.
        score += 18.0 + 0.8 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (fill the fullest bins first).
    score -= (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits: dead space is the main waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to how well the leftover matches the next item,
            // penalize large leftover slack beyond the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0);
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better hosts.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin (new bin would have residual == capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when reasonable alternatives exist,
    // but allow it when the item is large and fits would be very loose.
    if bin_residual == bin_capacity {
        let loose_elsewhere = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 80.0 * loose_elsewhere;
        // Early in the stream, opening bins is cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // A new bin is attractive if the item is huge (few future fits anyway).
        if item_size >= 70 {
            score -= 90.0;
        }
    }

    // Mild preference for keeping many bins busy: spreading load reduces
    // future overflow pressure when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding: with many open bins, prefer consolidating into tight bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.5 * crowding;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more conservative (penalize wasteful bins);
    // late in stream, pack aggressively anywhere.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += 8.0 * (1.0 - progress);

    // New-bin candidate handling: an empty bin is only attractive when no open bin
    // is a good home (large item relative to residuals) or we have few bins.
    if bin_residual == bin_capacity {
        let tight_open = mean_residual < item_size as f64;
        if open_bins_count > 0 && !tight_open && fitting_bins_count > 1 {
            score += 25.0; // discourage needless new bins
        } else if tight_open {
            score -= 15.0; // allow escape hatch
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can serve the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: prefer small post_residual, with a non-linear (quadratic) coupling
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Normalized post residual polynomial coupling with stream progress:
    // early on, tight packing matters slightly less; later, squeeze harder.
    let norm_post = post / cap;
    score += norm_post * norm_post * cap * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (smooth logistic gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (post - nxt).max(0.0) / cap;
        let gate = 1.0 / (1.0 + (-(post - nxt).abs() / 15.0).exp());
        score += waste * cap * 0.6 * gate;
        // Reward if post_residual still accommodates the next item
        if post >= nxt {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // mild penalty when many bins fit (spread usage)
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Reward bins with residual close to mean (keep bins homogeneous)
    let dev = (resid - mean_residual).abs();
    score += dev * 0.05;

    // Smooth pressure against opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    } else {
        score -= 2.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins
    score += (open_bins_count as f64) * 0.3;

    // Non-linear item-size coupling: large items prefer large-residual bins
    let item = item_size as f64;
    score += 0.02 * item * (resid / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (integer division thresholds)
    let class = post_residual / 10; // 0..10 harmonic classes
    // Reward small post_residual strongly (tight fits), non-linearly
    score -= (10 - class as f64) * (10 - class as f64) * 2.5;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for typical future items (< 10 min size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize bins that strand too-large leftovers
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 150.0 - 100.0 * crowding;
        // late in stream, prefer filling existing bins even more
        let progress = step_index as f64 / total_items as f64;
        score += 50.0 * progress;
    }

    // Mild preference for bins below mean residual (balance residual mass)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer fewer open bins: penalize when many bins already open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward tightness relative to bin capacity.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // If this bin is the only one that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement is excellent; if next item would not fit anywhere
    // else after this placement, avoid wasting the residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual <= 10 {
            score += 15.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for bins tighter than average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Prefer bins tighter than the mean residual (dense packing).
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless the current item barely fits anywhere.
    if bin_residual == bin_capacity {
        let tight_fit = fitting_bins_count <= 1 || item_size as f64 > mean_residual * 0.9;
        score += if tight_fit { 15.0 } else { 120.0 };
        // New bin is more attractive early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // If next item fits exactly into the post residual, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate small spaces).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty for spreading across many open bins when the stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.5 {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: penalize moderately so it is chosen only when
    // open bins give poor fits, but allow it late in the stream.
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * progress;
        // If next item is large and current item is small, a fresh bin is fine.
        if next_item_size > 50 && item_size < 40 {
            score -= 15.0;
        }
    }

    // Slight preference for filling larger bins first when item is big.
    if item_size > 60 {
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate slack
    // slightly more but still reward tight fits via convex penalty.
    let base = norm_pr * norm_pr * (1.0 + 0.8 * progress) + norm_pr * (1.2 - 0.5 * progress);

    // Dead-space penalty: residuals too small to fit typical items (<=10) are wasted.
    let dead = if pr < 10.0 { 4.0 + 6.0 * (1.0 - norm_pr) } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Mild penalty proportional to number of open bins to encourage consolidation.
    let spread = 0.02 * open_bins_count as f64;

    // Lookahead: if next item fits in post_residual, reward this placement.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -1.5 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        0.5
    } else {
        0.0
    };

    // New-bin candidate: neutral-ish baseline so it's chosen only when open bins
    // have poor fits; add slight bias against opening bins early in the stream.
    let new_bin_bias = if bin_residual == bin_capacity {
        0.8 + 1.2 * progress
    } else {
        0.0
    };

    // Coupling with mean residual: bins far from the mean get slight regularization.
    let reg = 0.1 * (pr - mean_residual).abs() / cap;

    let mut score = base * 10.0 + dead + last_chance + spread + lookahead + new_bin_bias + reg;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it live in?
    let item_class = (item_size * 4 / bin_capacity) as i64; // 0..3 (quarters)
    let next_class = if next_item_size == 0 { -1 } else { (next_item_size * 4 / bin_capacity) as i64 };

    // Perfect / near-perfect fits are heavily rewarded, scaled by harmonic class.
    let perfect = post_residual == 0;
    let near = post_residual > 0 && post_residual <= bin_capacity / 10;
    if perfect {
        score -= 1000.0 + cap * 0.5;
    } else if near {
        score -= 300.0;
    }

    // Dead-space penalty: residual that no future harmonic class can use.
    // Residuals in (0, 10) are dead; residuals matching common small classes are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Harmonic complementarity: if the next item's class complements post_residual
    // (i.e., next item fits exactly or near-exactly), reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let complement = post_residual - next_item_size;
        if complement == 0 {
            score -= 600.0;
        } else if complement <= bin_capacity / 10 {
            score -= 250.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot follow into this bin: penalize mildly unless post_residual
        // is a dead class anyway.
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer bins with below-mean residual (tighter packing) via mean coupling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus late-stream penalty.
        score += 50.0 + progress * 150.0;
        // Opening a new bin is attractive if item is large and would leave big
        // unusable slivers elsewhere (large class items pair well with fresh bins).
        if item_class >= 3 {
            score -= 120.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 30.0;
        }
    }

    // Slight preference for bins whose post_residual lands on a "friendly"
    // harmonic residue (multiples of 10 or 25 are commonly reusable).
    let pr = post_residual;
    if pr % 10 == 0 || pr % 25 == 0 {
        score -= 25.0;
    } else {
        score += 15.0;
    }

    // Tie-break: prefer fewer open bins overall (mild consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover gap.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure to reuse existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / 20.0) * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins whose residual deviates usefully.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly fits the post residual, heavily reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize proportionally to waste
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
        // Perfect two-item packing bonus
        if post_residual + next_item_size as f64 == 0.0 {
            score -= 20.0;
        }
        if (post_residual as f64) == next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // last item: just minimize post residual
        score -= 10.0 * tightness;
    }

    // Relative to mean residual: prefer bins that deviate appropriately
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist that fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // allow new bin if current item is large relative to capacity
        score -= 0.15 * item_size as f64;
    }

    // Slight penalty for leaving dead space that nothing (min size 1..100) can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Prefer tight fits: reward small post_residual nonlinearly.
    score -= 30.0 * (1.0 - post / cap).powi(6);

    // Penalize large dead space that can only host tiny items.
    if post > 0.0 && post < 10.0 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post - nxt;
        if diff >= 0.0 {
            score -= 25.0 * (1.0 - diff / cap).powi(4);
        } else {
            score += 0.15 * (-diff);
        }
        // Penalize leaving residual that is awkwardly just below next item.
        if diff < 0.0 && -diff <= 10.0 {
            score += 12.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.05 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer emptier bins slightly to consolidate.
        score += 0.02 * (fitting_bins_count as f64);
    }

    // Global state: if mean residual is high, encourage using open bins rather than new ones.
    score -= 0.1 * mean_residual;

    // New-bin candidate handling: opening a bin is penalized more early, less late,
    // and more when many bins are already open with slack.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * (1.0 - 0.5 * progress);
        score += 2.0 * (open_bins_count as f64);
        if mean_residual > 0.5 * cap {
            score += 20.0;
        }
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early in the stream, prefer tight fills less aggressively (bins can be reused);
    // later, dead space becomes permanent, so weight post_residual more.
    let mut score = pr * (1.0 + 0.9 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits smoothly (post_residual near 0).
    score -= 30.0 * (1.0 - norm_pr).powi(6) * (0.5 + progress);

    // Penalize leaving a residual that is too small to be useful for typical items,
    // via a smooth bump around small-but-nonzero residuals.
    let dead_zone = ((norm_pr - 0.12) / 0.12).powi(2);
    score += 25.0 * (-dead_zone).exp() * norm_pr * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * snug * (0.4 + 0.6 * progress);
    } else if next_item_size > post_residual {
        // Penalize creating residual that blocks the lookahead item, scaled by how badly.
        score += 10.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.5 + progress);
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about imperfect fits.
        score += 8.0 * norm_pr * (fitting_bins_count.min(10) as f64 / 10.0);
    }

    // Mean-residual context: when open bins are already loose, avoid scattering space;
    // tighten preference for bins below the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * (0.3 + 0.7 * progress);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * (open_bins_count.min(20) as f64);
        // But allow new bins early or when existing fits are terrible.
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual by capacity fraction bands.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize dead space in "hard to fill" bands: (0, 10] and (10, 20]
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual > 60 {
        // Large leftover is fine; reward it slightly
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are reusable -> reward.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 {
        score -= 4.0;
    }
    // Odd/awkward residuals (prime-ish, not divisible by 5) are dead space
    if pr % 5 != 0 && pr > 0 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // Next fits, but how cleanly? Integer-division harmonic class.
            let k = pr / next_item_size.max(1);
            if k >= 2 {
                score -= 8.0; // multiple future items fit
            } else {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's remainder -> penalize leftover
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so that
    // decent fits into open bins win, but a good new-bin score beats bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening fresh is attractive late in stream or when open bins are fragmented
        if open_bins_count > 0 {
            score -= (open_bins_count as f64) * 0.5;
        }
        if post_frac > 0.5 {
            score -= 10.0;
        }
    }

    // Stream progression: as stream advances, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual / cap);

    // Slight preference for bins below mean residual (balance fragmentation)
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

