    // If next item would be blocked by this placement, penalize
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins below mean residual (fill emptier bins less; keep balanced bins)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Early stream: slightly prefer opening/using fresh capacity less aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
