    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be used later (min item size assumed small,
    // but dead space below ~next item size is risky).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 6.0 * (nxt - post_residual as f64) / nxt;
        }
        // Reward bins whose post residual exactly accommodates the lookahead item.
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual > next_item_size {
            score -= 2.0 * (next_item_size as f64) / (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score -= 0.8 * pressure;

    // Deviation from mean residual: prefer bins that are already well filled.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a moderate penalty unless the item
    // fits poorly everywhere (large item or no good residual match).
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        // In early phase, opening bins is fine; later, discourage.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += base_penalty * (0.5 + 0.5 * progress);
        // Large items justify fresh bins more readily.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
        // If the lookahead item is large and the new bin would keep room for it, bonus.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild time-horizon modulation: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack.
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Cubic smoothing term: penalize very small dead space asymmetrically.
    score += 0.35 * norm_post * norm_post * (1.0 - norm_post) * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 0.6 * cap * (0.5 + 0.5 * progress);
    }

    // Crowd penalty: many open bins -> discourage fragmenting further unless fit is tight.
    let crowd = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
    score += 6.0 * crowd * norm_post;

    // Mean-residual coupling: if this bin's post-residual deviates from mean,
    // reward homogenizing residuals (helps future items fit somewhere).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - ((post - nxt) / cap);
            score -= 0.5 * cap * tightness * tightness;
        } else {
            score += 0.25 * (nxt - post);
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // make it attractive only when no open bin gives a tight fit is handled
    // implicitly, but add a mild progress-dependent penalty so we prefer
    // filling existing bins as the stream matures.
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual in {0} is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that no plausible item (>=1) can pair with well.
    // Classify post_residual by integer division thresholds on capacity quarters.
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual < item_size.min(quarter) {
        // Residual smaller than smallest useful slot -> dead space.
        score += 18.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair naturally
    // with the common item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd/awkward classes (mod 10 in {1,3,7,9}) are harder to fill.
    let m = post_residual % 10;
    if m == 1 || m == 3 || m == 7 || m == 9 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0);
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by gap.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has neutral-to-moderate score so it
    // only wins when open bins are genuinely bad (large post_residual / dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + 0.25 * (mean_residual - pr);
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are already open, discourage yet another one.
        score += (open_bins_count as f64) * 0.5;
    }

    // Mild preference for filling bins that are already relatively full
    // (small residual before placement), scaled against mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Tie-break: prefer bins whose post_residual is close to a harmonic fraction
    // of capacity (half or quarter), which future items can complement.
    if post_residual == bin_capacity / 2 || post_residual == bin_capacity / 4 || post_residual == 3 * bin_capacity / 4 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Dead-space penalty: residuals too small for the minimum item size (1) are fine,
    // but gaps that are small yet nonzero waste capacity. Penalize unusable-ish gaps
    // (post_residual in 1..=item_size range relative to typical items) quadratically.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * (10.0 - pr) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Exact match with next item lookahead: leaving room for the next item is great.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        // leaving usable space for the known next item is mildly good
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for the known next item -> dead space risk
        score += pr * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // unless the fit is excellent; with few bins, consolidation is cheaper anyway.
    let bin_pressure = open_bins_count as f64 * 0.3;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current fit is bad or no open bins fit.
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += bin_pressure + 20.0; // default: prefer existing bins
            // but allow opening when the best alternative would leave big dead space
            if post_residual == bin_capacity as u32 {
                score -= item_size as f64 * 0.2;
            }
        }
    }

    // Mean-residual coupling: when mean residual is small, existing bins are nearly
    // full; slightly prefer placing into them (tight packing achieved).
    score -= mean_residual * 0.1;

    // Late in the stream, minimize bin count aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: bin closed, ideal
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post_residual, this placement is a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: mildly reward, scaled by slack.
        score -= 0.5 * (next_item_size as f64 / post_residual as f64) * 100.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        score += (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling a large-residual bin with a big item is good.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        score += 120.0 + 10.0 * open_pressure;
        // But allow a new bin if current item is large and would leave tiny
        // unusable slivers in every existing bin — handled via post_residual
        // already; soften penalty when item is large.
        if item_size >= 60 {
            score -= 60.0;
        }
    }

    // Slight preference to keep large residual bins flexible early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical items (1..100 unknown, so scale by mean item proxy).
    let dead_threshold = 10.0_f64.min(mean_residual * 0.5).max(1.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward; if it would waste, penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for flexibility);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fit_ratio;

    // Many open bins: discourage opening more, favor consolidation.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far below mean residual are less attractive unless tight fit.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate adjustment: prefer new bin only when current fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = 1.0 - fit_ratio;
        score += 12.0 - 10.0 * bad_fit;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight fits via smooth polynomial decay of post_residual.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = 4.0 * x * x - 4.0 * x; // negative valley at x=0 (perfect fit), rises toward x=1

    // Non-linear coupling with stream progress: waste matters more later in the stream.
    score += 2.0 * x * x * progress;

    // Penalize bins whose post residual deviates from the mean residual (dead-space dispersion).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Smooth interaction: post residual vs next item size fit (lookahead coupling).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (post - nxt) / cap;
        score -= 2.0 * (-(gap * gap * 40.0)).exp(); // reward post residual close to next item size
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 * (1.0 - x) * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic class of the leftover: classify post_residual by capacity fraction.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f; // fraction of capacity left over
    // Dead-space penalty grows superlinearly for mid-size leftovers,
    // but small leftovers (< 1/8 of capacity) are acceptable.
    if frac < 0.125 {
        score -= 40.0 * (0.125 - frac);
    } else {
        // penalize unusable middles; classes around 1/3, 1/2 are worst for future items
        let class_penalty = match post_residual {
            30..=39 => 60.0,
            40..=54 => 45.0,
            20..=29 => 30.0,
            _ => 0.0,
        };
        score += class_penalty * frac;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 150.0 / (1.0 + slack as f64);
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large relative to capacity or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / cap_f
        } else {
            0.0
        };
        // Prefer new bin when item is big (little would remain) or fragmentation high.
        let new_bin_bonus = (item_size as f64 / cap_f) * 120.0 + fragmentation * 80.0 + progress * 30.0;
        score -= new_bin_bonus;
        // But discourage opening a new bin when a decent fit exists elsewhere:
        if post_residual == 0 { score += 50.0; } // item fills it exactly, fine
        else if post_residual > 60 { score += 40.0; } // would leave huge empty-ish bin? no, it's new; neutralize over-reward
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (fills fuller bins first, keeps large holes available).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Prefer using more-open-bins state slightly less: encourage closing out bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are unusable by any item
    // (min size 1, but realistically tiny gaps are wasted) -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Penalize leaving a gap that can't fit the known next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving a gap exactly usable by the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current placement is terrible
    // or open-bin pressure is extreme.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Pressure: many open bins -> prefer packing into existing bins.
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late in stream, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If item fits poorly everywhere (large dead space anyway), new bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Mild pressure to prefer emptier bins when many are open.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (dead space eliminated).
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: exact match between leftover space and the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: chain bonus proportional to tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * tightness;
        } else {
            // Next item cannot use this leftover: penalize small dead leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare residual against the mean residual of open bins.
    let res = post_residual as f64;
    if res < mean_residual - 10.0 {
        // Tighter than average: good consolidation.
        score -= 20.0;
    } else if res > mean_residual + 10.0 {
        // Looser than average: discourages fragmenting well-packed bins.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    // Slight late-stream tightening: pack harder as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - res / bin_capacity as f64);

    // Penalize very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but heavily reward near-zero waste.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 5.0; // consumes space the next item would need
        }
    }

    // New-bin candidate handling: penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open a new bin only when no other bin fits, or late in the stream with tight fits unavailable.
        let penalty = if scarcity > 0.0 { 5.0 } else { 60.0 };
        score += penalty;
        score -= 10.0 * progress * scarcity;
        // If mean residual is large, existing bins are roomy: avoid new bin.
        score += mean_residual * 0.15 * (1.0 - scarcity);
    }

    // Mild preference for filling bins that are already partially used when many bins are open.
    if bin_residual < bin_capacity {
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 4.0 * fullness;
    }

    // Encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (waste minimization).
    let mut score = post * post / cap;

    // Smooth non-linear coupling: leftover weight grows with stream progress
    // (late in the stream, tight fits matter more; dead space is less forgivable).
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Reward near-perfect fits: subtract a smooth bell-shaped bonus around post_residual == 0.
    let perfect = (-norm_post * 6.0).exp();
    score -= 30.0 * perfect * (1.0 + progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        let fit_next = (-gap / cap * 5.0).exp();
        score -= 12.0 * fit_next;
        // Penalize leaving a residual that is awkwardly larger than next item.
        if post > nx {
            score += 0.15 * (post - nx);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins get priority).
    let dev = mean_residual - post;
    score += 0.10 * dev;

    // New empty bin candidate: penalize opening a new bin, more so when
    // other bins fit and the stream is advanced.
    let is_new_bin = (bin_residual == bin_capacity);
    if is_new_bin {
        score += 40.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        // But soften if item is large (poor fit everywhere is likely).
        score -= 0.3 * item_size as f64;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of capacity does the leftover fall in?
    let q = post_residual / (bin_capacity / 4).max(1); // 0..4 class
    match q {
        0 => { score -= 45.0; }              // near-perfect fit: strong reward
        1 => { score -= 15.0; }              // good leftover
        2 => { score += 5.0; }               // mediocre leftover
        _ => { score += 20.0; }              // wasteful leftover
    }

    // Dead space: leftover that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover is reusable by the lookahead item
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / cap) * 10.0;
        } else {
            // dead space: penalize proportionally to how unusable it is
            let unusable = (next_item_size - post_residual) as f64;
            score += 8.0 + (unusable / cap) * 30.0;
        }
    }

    // Integer-division thresholds on post_residual: small residues are golden.
    if post_residual <= 10 { score -= 25.0; }
    else if post_residual <= 20 { score -= 10.0; }
    else if post_residual > 50 { score += 15.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap < 0.25 && open_bins_count > 0;
        let poor_fit = (item_size as f64 / cap) < 0.35 && post_residual > 60;
        if crowded || poor_fit {
            score -= 18.0;
        } else {
            score += 35.0; // prefer filling existing bins
        }
    }

    // Modulo coupling: residue divisible by common item sizes is more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
        score -= 6.0;
    }

    // Mild stream-progression term: tighten packing late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 - progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (new-bin candidate has bin_residual == bin_capacity, so its tightness
    // reward is weakest; add explicit pressure scaled by open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (20.0 + open_bins_count as f64 * 3.0 + progress * 20.0);

    // Lookahead coupling: if the next item could use the post_residual well,
    // slightly reward leaving that much space; penalize blocking it.
    if next_item_size > 0 {
        if next_item_size <= post_residual && post_residual > 0 {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 15 {
            score += 20.0; // dead space that even the next item cannot use
        }
    }

    // Mild preference for bins already below mean residual (balancing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that no plausible item (1..=100) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small unusable sliver
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            if next_leftover <= 2 {
                score -= 30.0;
            } else {
                score -= 12.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins first),
    // leaving roomier bins for harder items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (penalize opening bins when many are open and mean residual is large).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Early-stream exploration: keep bins open, discourage proliferation early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Penalize dead space that is too small to be useful later (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            score -= 8.0 - (next_waste as f64 * 0.15);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge or state is crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let penalty = 35.0 + 40.0 * (1.0 - progress) - crowd.min(20.0);
        score += penalty.max(0.0);
    }

    // Prefer bins with residual below mean (consolidate emptier space elsewhere).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Reward tight fits (fill ratio) with smooth non-linear coupling to stream progress.
    let tightness = (fit_ratio * fit_ratio) * (cap * 0.35);
    score -= tightness * (0.7 + 0.6 * progress);

    // Penalize dead space: small post_residual that cannot fit typical future items.
    let dead = if pr < 10.0 { 0.0 } else { ((10.0 - pr).max(0.0) * -1.0) };
    let _ = dead;
    let small_leftover_penalty = (pr / cap) * (1.0 - pr / cap) * cap * 0.25;
    score += small_leftover_penalty;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.5;
    }

    // New-bin candidate: penalize unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += cap * (0.30 + 0.35 * (1.0 - size_frac * size_frac));
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= cap * 0.15;
    } else if next_item_size > 0 {
        score += cap * 0.08 * (1.0 - progress);
    }

    // Mild coupling to mean residual / open bins pressure.
    score += (mean_residual - pr) * 0.05 + open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes.
    // Class bins by post_residual / (bin_capacity / 8) octile.
    let oct = (bin_capacity / 8) as f64; // 12.5 typical
    let post_f = post_residual as f64;
    let class = (post_f / oct).floor().min(8.0);

    // Reward small post_residual (tight fit) with non-linear bonus
    score -= 30.0 * (1.0 - post_f / bin_capacity as f64).powi(3);

    // Penalize dead space: residuals that are too small for likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are good
    let common = [10u32, 20, 25, 30, 40, 50];
    let mut mult_bonus = 0.0;
    for &c in &common {
        if post_residual % c == 0 && post_residual > 0 {
            mult_bonus += 8.0;
        }
    }
    score -= mult_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if post_residual == next_item_size {
            score -= 25.0; // perfect pairing
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mildly penalize wasting the residual
        score += 5.0 * (1.0 - post_f / oct.max(1.0) / 8.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);

    // New-bin candidate (empty bin): penalize unless current bin leaves bad residual
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is attractive if mean residual is small (all bins nearly full)
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    }

    // Harmonic class tiebreak: mid-class residuals (class 2-4) are most reusable
    if class >= 2.0 && class <= 4.0 {
        score -= 6.0;
    } else if class >= 6.0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (post_f - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // possible item (1..100 unknown, use a conservative small-gap threshold)
    // are pure waste; penalize them heavily.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin size (low waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Open-bin pressure: penalize placements when many bins are open to
    // discourage bin sprawl; reward consolidating into few bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline; only prefer it when
    // the item would leave a very poor fit in every existing bin, or when
    // no bins exist yet.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // Prefer a fresh bin if the item fits poorly everywhere
            // (post_residual here equals capacity - item_size).
            let fresh_waste = post_residual as f64;
            score += 15.0; // default penalty: prefer reusing open bins
            if fitting_bins_count == 0 || fresh_waste < 0.25 * base {
                score -= 45.0;
            }
            // If next item is large and this bin would be nearly full,
            // fresh bin keeps lookahead flexibility.
            if next_item_size > 0 && (next_item_size as f64) > 0.6 * base {
                score -= 10.0;
            }
        }
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward; otherwise slight penalty for stranding the lookahead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 5.0;
        }
    }

    // Mild stream-progress term: early on, be slightly more conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress);

    // Nudge toward bins with residuals close to the mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect chaining reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chain: next item fills this bin completely
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0); // next item fits, reward decays with slack
            if post_residual - next_item_size <= 10 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item cannot use the post residual: dead-space penalty
            let waste = post_residual as f64;
            score += waste * 0.5;
        }
    }

    // Penalize residuals that are too small to ever be useful (min item size 1..100 unknown, assume small)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny unusable sliver
    }

    // Relative to mean residual: prefer bins that are tighter than average (best-fit flavor)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good chain exists
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 35.0 - 25.0 * chain_bonus;
        // late in the stream, discourage opening new bins slightly more
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Mild pressure to fill bins heavily as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // Crowding: with many open bins, prefer consolidation into existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual > 60 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    }
    // Penalize if next item won't fit in post_residual but would fit elsewhere
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // New-bin candidate handling: penalize opening new bins when good fits exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 30.0; // discourage opening when decent fit exists
        }
        // open new bin more readily early in stream
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing
    if mean_residual > 0.0 {
        let spread = mean_residual - post_residual as f64;
        score += 0.15 * spread;
    }
    if open_bins_count > 8 {
        score -= 3.0; // encourage consolidation of many open bins
    }

    // Prefer bins whose residual is close to item size (near-perfect packing)
    let closeness = (bin_residual - item_size) as f64;
    score += 0.1 * closeness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth non-linear coupling: post_residual polynomial in stream progress
    let poly = 1.0 + progress * prn + (progress * progress) * prn * prn;
    score *= poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * (1.0 + 2.0 * progress) * 8.0;

    // Penalize dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress) + 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins below mean residual (denser)
    score += (pr - mean_residual) * (0.3 + 0.5 * progress);

    // Prefer leaving residuals that are small or exactly reusable
    if pr == 0.0 {
        score -= 20.0;
    } else if pr <= 10.0 {
        score -= 5.0;
    }

    // New-bin candidate: make it unattractive unless residuals everywhere are bad
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but modulate by harmonic classes.
    if post_residual == 0 {
        score -= 200.0; // perfect fit is always best
    } else {
        // Class of post_residual by integer division thresholds (dead-space classes).
        let pr = post_residual as f64;
        let pr_class = post_residual / 10; // 0..=9 harmonic class
        // Penalize dead space non-linearly: residuals in "unusable" ranges
        // (too small for typical items 1..100) are worse.
        if post_residual < 10 {
            score -= 60.0; // dead space, unusable
        } else if post_residual < 25 {
            score -= 25.0;
        } else if post_residual < 50 {
            score += 5.0;
        } else {
            score -= 10.0; // roomy residual still useful
        }
        // Modulo coupling: residuals divisible by common item sizes pair well
        // with a lookahead item of matching residue.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 150.0; // sets up a perfect fit next step
            } else if next_item_size <= post_residual {
                score -= 10.0;
                // harmonic alignment: post_residual % next_item_size small
                let m = post_residual % next_item_size;
                if m < 10 {
                    score -= (10 - m) as f64;
                }
            } else {
                score += 15.0; // next item won't fit here either; residual likely wasted
            }
        }
        // Fraction-of-capacity classes for the item itself.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.8 {
            score -= 20.0; // large items: place them, close bins fast
        } else if frac < 0.2 {
            score += 10.0 * (1.0 - frac); // tiny items: prefer bins with little room
        }
        // Last-chance bin: strongly reward using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        } else {
            // spread across bins: prefer bins with residual below mean (consolidation)
            score += (mean_residual - pr) * 0.3;
        }
        // Late in stream: consolidate harder, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins: favor filling existing ones over new-bin candidate.
        score += open_bins_count as f64 * 2.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only attractive if item is large or no good existing fit exists.
        score = 100.0
            - (item_size as f64) * 0.5
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1..11) are wasted.
    if post_residual > 0 && post_residual < 11 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 20 {
        score -= 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 11 {
        score -= 45.0;
    }
    // Penalize if next item cannot fit into post residual but fits elsewhere.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += pressure * 0.8;

    // New-bin candidate: make it attractive only when existing fits are bad (large post_residual).
    if bin_residual == bin_capacity {
        score -= 30.0;
        score += mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Discourage leaving residuals far below mean (fragmentation).
    if (post_residual as f64) < mean_residual * 0.3 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits into post residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in leftover: penalize proportionally to wasted capacity.
        score += 1.5 * (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
    }

    // Prefer bins whose residual deviates below mean (tighter bins get filled first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when it enables a perfect lookahead fit.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 900.0;
        } else {
            score += 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Late in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual penalty, stronger for small leftover space.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item can't use this leftover: penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (post residual too small to be useful) or many bins already open.
    if bin_residual == bin_capacity {
        let useful = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        let poor_fit = (post_residual as f64) < 10.0 * (1.0 + useful);
        if poor_fit {
            score -= 12.0;
        } else {
            score += 30.0 + 2.0 * post_residual as f64 * 0.1;
        }
        // More open bins -> new bin less attractive (prefer consolidating).
        score += 1.5 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins with residual near the mean (balanced packing),
    // unless it's the last chance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if fitting_bins_count > 1 {
        score += 0.08 * dev;
    }

    // Time horizon: early in the stream, be pickier about dead space; late, just fill.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fills (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.5 * (post / cap) * (post / cap));

    // Smooth coupling of post_residual with stream progress: early on tolerate slack,
    // later penalize waste more strongly.
    score += 12.0 * (post / cap) * progress * progress;

    // Dead-space penalty: residual too small to be useful later (non-linear falloff).
    let useless = (1.0 - post / cap) * (1.0 - post / cap);
    score += 6.0 * useless * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth kernel).
    if next > 0.0 {
        let fits = 1.0 - ((post - next).abs() / cap);
        score -= 10.0 * fits.max(0.0) * (1.0 - (post / cap));
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // (smooth ramp with item size) or no real alternative exists.
    if bin_residual == bin_capacity {
        let large = (item / cap) * (item / cap);
        score += 30.0 * (1.0 - large) + 8.0 * (1.0 - progress);
    }

    // Mild dispersion penalty: avoid leaving a bin far from mean residual.
    score += 2.0 * ((post - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste in multiples of capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Modulo classes on post_residual: residual that is "harmonically awkward"
    // (not near a quarter/half/three-quarter of capacity) gets penalized.
    let frac = pr / cap;
    let nearest_quarter = (frac * 4.0).round() / 4.0;
    score += (frac - nearest_quarter).abs() * 40.0;

    // Perfect-fit harmonic classes: residuals that divide capacity exactly are golden.
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: reward residual that can host next item (with harmonic slack).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 0.3 * slack;
            // Integer-division threshold: if bin can host next item twice, extra reward.
            if post_residual >= 2 * next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize slightly more if gap is small (near-miss waste).
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.2 * gap.min(30.0);
        }
    } else {
        // Last item: minimize post residual strictly.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins are crowded or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64;
        let desperation = (mean_residual / cap - 0.5).abs();
        score += 25.0 + 10.0 * progress + 3.0 * crowding * desperation;
        // Big items prefer fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild spread penalty: prefer bins below mean residual (tighter packing).
    score += 0.1 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are effectively wasted. Penalize unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is worthless
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // barely usable gap
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // next item cannot use the leftover; dead space likely
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; but soften
    // when this bin is the last chance (avoid opening a new bin unnecessarily).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.4 + 0.4 * progress);
    score += pressure;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0; // last chance: strongly prefer using this bin
    }

    // Mean residual coupling: penalize bins far below the mean residual
    // (they will be closed soon anyway); slightly favor bins near mean.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.15 * diff;

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin offers a decent fit (large residual
    // waste in open bins). Base cost for opening a new bin:
    if bin_residual == bin_capacity {
        score += 20.0;
        // If many bins can fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in stream with few fitting bins, new bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Reward small gaps around the lookahead size
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // can also host next item: mild reward proportional to how tight the fit is
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * tightness;
        } else {
            // post_residual too small for next item: penalize dead space
            score += 8.0 + 0.1 * post_residual as f64;
        }
    }

    // Penalize creating residuals that are likely unusable (below minimum item size 1..small)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: leaving less than mean is good (tight packing)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer filling already-open bins over opening new ones when fit is decent
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so only clearly good openings win
        score += 30.0;
        // If no open bin fits (this call is the only candidate), allow opening
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // Late in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Reward using existing bins, more so when many bins are open
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for larger items placed into larger residuals
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets an extra big bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly or well into the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - next_tight / bin_capacity as f64);
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; mildly penalize leaving large awkward gaps
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // More open bins with high mean residual => prefer packing into existing bins
        score += open_bins_count as f64 * 4.0;
        score += mean_residual * 0.8;
        // Early in the stream, packing tightly matters more; late stream, cheaper to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If item is large, opening a fresh bin is more reasonable
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    } else {
        // Existing bin: prefer bins whose residual is close to item_size (minimal waste)
        let waste = (bin_residual - item_size) as f64;
        score += 0.15 * waste;
        // Prefer bins with lower residual among equally good fits (fill fuller bins first)
        score += 0.1 * (bin_residual as f64);
    }

    // Penalize creating dead space that nothing (min size 1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // small unusable slivers are ok-ish since next items can be tiny
    }

    // Slight global pressure: when many bins are open, consolidate
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, quadratically coupled with stream progress
    let mut score = pr * (1.0 + 1.5 * progress) + 60.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly early on
    score -= 40.0 * (1.0 - x) * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host the next item
        score += 8.0 * (1.0 - (pr / cap)) * progress;
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean (balanced usage)
    score += 0.3 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    // Penalize opening new bins when good fits exist, scaled by number of open bins
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes w.r.t. common item sizes
    let pr = post_residual;
    // Reward residuals that are "harmonious" with typical item sizes (multiples of 10/20/25/50)
    let harmony = if pr == 0 {
        60.0
    } else if pr % 50 == 0 || pr % 25 == 0 {
        40.0
    } else if pr % 10 == 0 {
        25.0
    } else if pr % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmony;

    // Penalize small dead space (unusable slivers below min item size 1..=10 threshold)
    if pr > 0 && pr < 10 {
        score += 35.0 + 3.0 * pr as f64;
    }

    // Perfect fit bonus scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr == 0 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            // reward proportional to how well next item fills post_residual
            let fill = next_item_size as f64 / pr as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: slight penalty proportional to excess
            score += 5.0 * ((next_item_size - pr) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, prefer tight fits
    if open_bins_count > 3 {
        let tightness = (item_size as f64 / bin_residual as f64).min(1.0);
        score -= 12.0 * tightness;
    }

    // Prefer bins whose residual is below mean residual (denser bins)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // but if item is large relative to capacity, new bin is fine
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
        // if existing bins fit poorly (post_residual small sliver), reduce penalty
        if post_residual > 0 && post_residual < 10 && bin_residual != bin_capacity {
            score -= 40.0;
        }
    }

    // Integer-division threshold on post_residual: bucket rewards
    let bucket = pr / 20; // 0..5
    score -= match bucket {
        0 => 20.0, // very tight residual after placement
        1 => 14.0,
        2 => 8.0,
        3 => 4.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer reusing existing bins
    // when many bins are already open; opening new bins is costly.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it less attractive unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the next item is large, opening a fresh bin early may help.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual as u32 > next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: bins far below mean residual are good targets
    // (consolidating space), bins far above are wasteful to use.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, be more conservative about spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small slack
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here: dead-space penalty grows with wasted space
        score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual
    let tightness = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 10.0 * open_bins_count as f64;
        let escape = if fitting_bins_count == 0 {
            40.0
        } else {
            // only escape if item nearly fills a bin exactly elsewhere? keep modest
            0.0
        };
        score += base_penalty - escape;
        // small item in fresh bin wastes capacity
        score += 0.3 * (bin_capacity - item_size) as f64;
    }

    // Mild preference to fill bins with high fill ratio early
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins where the item fills a large share of the residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        // Reward tight fits strongly (non-linear coupling).
        score -= 30.0 * fill_ratio * fill_ratio;
    }

    // Penalize large dead space left behind, with a twist: dead space that
    // could still host the lookahead item is less bad.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // this bin can also serve the next item
        } else {
            // Dead space too small for the next item: penalize proportionally.
            score += 0.15 * post_residual as f64;
        }
    }

    // Perfect-fit bonus: leaving exactly nothing behind.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item
    // is large relative to capacity or few bins are open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 35.0;
        // Early in the stream, opening bins is cheaper (build a pool).
        new_bin_penalty *= 1.0 - 0.5 * t;
        // Many open bins with slack mean we should use them instead.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 0.3 * (mean_residual - item_size as f64);
        }
        // A big item justifies a fresh bin.
        new_bin_penalty -= 0.2 * item_size as f64;
        score += new_bin_penalty;
    }

    // Slight preference for bins whose residual is below the mean residual
    // (consolidate the fullest bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild time-decay pressure: late in the stream, close bins tightly.
    score -= 8.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, larger post_residual is mildly tolerable; late in the stream,
    // wasted space is punished quadratically.
    let waste_weight = 1.0 + 3.0 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * cap * 0.05;

    // Reward tight fits: post_residual near zero gets a strong discount.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: bonus if the next item fits exactly into the post_residual,
    // quadratic decay as slack mismatch grows.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = post - nx;
            score -= 6.0 * (1.0 - slack / cap).powi(3);
        } else {
            // next item cannot fit here; penalize proportionally to overflow
            score += 0.02 * (nx - post);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * progress;
    }

    // New-bin candidate (empty bin): penalize opening new bins when many
    // bins are open or mean residual is large; allow it early or when
    // existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 2.0 + 6.0 * fragmentation + 0.15 * open_bins_count as f64;
        if progress > 0.8 {
            score += 5.0 * (progress - 0.8);
        }
    }

    // Mild penalty for bins deviating from the mean residual (balance pressure).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4 harmonic class

    // Reward small post_residual strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_class == 0 {
        score -= 25.0; // post_residual < 25: tight fit, little dead space
    } else if post_class == 1 {
        score -= 10.0;
    } else if post_class == 3 {
        score += 8.0; // post_residual in [75,100): wasteful unless new bin
    }

    // Dead-space penalty: residuals that no typical item (1..=100) can pair with.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack as f64) * 0.3; // prefer next item snugly fitting here
    }
    // Penalize if next item would leave another dead sliver.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nslack = post_residual - next_item_size;
        if nslack > 0 && nslack < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post_residual would be large dead space and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin baseline: its post_residual equals capacity - item_size.
        let new_post = bin_capacity - item_size;
        if new_post < quarter && post_residual > quarter {
            score -= 12.0 * (1.0 - progress); // early stream: fresh bin can absorb future items
        } else {
            score += 25.0 + 20.0 * progress; // generally discourage proliferation
        }
    }

    // Mild pressure against too many open bins when residuals are large.
    if open_bins_count > 3 && (post_residual as f64) > mean_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }
    // Zero residual is a perfect fit — strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize wasting a large bin on a small item when residual was large.
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * 12.0;

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 && post_residual < 10 {
        score += 5.0; // stranded gap that can't fit next item
    }

    // Mild preference to fill bins evenly early, tightly late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.05 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted space that next item
            // cannot use, scaled by how dead the space is.
            let dead = next_item_size - post_residual;
            score += 0.35 * dead as f64;
        }
    }

    // Relative-to-mean matching: prefer bins whose post residual is near the
    // mean residual (keeps open bins balanced, preserves flexibility).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and existing residuals are small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins when existing bins have room and item is small.
        score += 45.0 * (1.0 - large_item) * (1.0 - pressure);
        // But reward new bin if no good chain is possible (next item large).
        if next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate harder (fewer bins matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit bonus
    }
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // awkward gap zone
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 4.0 * ((next_item_size - post_residual) as f64 / (bin_capacity as f64));
        }
    } else {
        // Last item: prefer filling a bin as fully as possible.
        score -= 20.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are open or many items remain; make the empty bin less attractive.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 6.0 * open_pressure + 20.0 * (1.0 - progress);
        // If the item perfectly fills a fresh bin, opening is fine.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 30.0;
        }
    }

    // Global residual pressure: when mean residual across open bins is low,
    // conserve remaining space (penalize wasteful placements more).
    let mean_res_norm = mean_residual / (bin_capacity as f64);
    score += 10.0 * (1.0 - mean_res_norm) * (post_residual as f64 / bin_capacity as f64);

    // Mild time-horizon term: early in the stream, keep bins flexible
    // (avoid creating large awkward residuals); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: wasted space, superlinearly penalized
    let mut score = post * post / cap;

    // Tight fit reward: smooth quadratic coupling of item fill ratio
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 - fill) * 4.0;

    // Non-linear stream progress coupling: early on tolerate slack, later punish it
    let prog_term = progress * progress * (1.0 - progress);
    score += 40.0 * prog_term * post / cap;
    score -= 20.0 * progress * fill;

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let snug = 1.0 - ((post - nxt) / cap).abs();
            score -= 15.0 * snug * snug * (0.5 + 0.5 * progress);
        } else {
            // residual too small to be useful: dead space penalty grows with progress
            score += 10.0 * progress * (1.0 - post / cap);
        }
    } else {
        // last item: pure tightness
        score -= fill * 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze target
    score += 0.3 * (post - mean_residual);

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity-fraction buckets.
    // Perfect fits (post_residual in {0, small}) heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Dead-space penalty grows for residuals that few item sizes can reuse.
        // Modulo-style classes: residuals near half capacity are re-usable by many sizes.
        let half = bin_capacity / 2;
        let class = if post_residual >= half { 0 } else if post_residual % 10 <= 2 { 1 } else { 2 };
        match class {
            0 => score -= 10.0,        // large residual: flexible
            1 => score -= 5.0,         // near-decade boundary: still reusable
            _ => { score += (post_residual as f64 - 10.0) * 0.35; } // awkward dead space
        }
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else if next_item_size == post_residual {
            score -= 30.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 4.0;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residual
    // or item is huge relative to residual. Penalize default new-bin otherwise.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if post_residual <= 10 {
            score += 80.0; // an open bin fits nearly perfectly; don't open new
        } else if tightness > 0.8 {
            score -= 20.0; // huge item: fresh bin is fine
        } else {
            score += 25.0 + mean_residual * 0.1;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Stream progression: later in stream, slightly favor filling existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual < bin_capacity {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits proportionally to fill ratio.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * fill * fill;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residuals that can host the next item (keeps bins reusable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer packing into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // but allow opening when mean residual across bins is small (all full-ish).
        score = bin_capacity as f64 - 15.0 + pressure * 3.0 - mean_residual * 0.3;
    } else {
        score += pressure * 0.15;
        // Slight preference for bins below mean residual (emptier bins absorb variety).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/very tight fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 800.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 120.0 - (slack as f64) * 2.5; // better chaining for tight follow-ups
        } else {
            // Next item won't fit here: penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 1.5;
        }
        // Bonus if next item could pair with current item leaving near-zero waste
        if item_size + next_item_size <= bin_capacity && (bin_capacity - item_size - next_item_size) == bin_residual - item_size - next_item_size {
            score -= 50.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (concentrate filling) unless it's the last-chance bin.
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64;
        if tightness > 40.0 {
            score -= 80.0; // poor fit elsewhere -> open new bin
        } else {
            score += 120.0; // good fit available -> keep filling existing bins
        }
    }

    // Slight preference to fill older/more crowded bin sets as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit quality: reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize creating "dead space" that likely cannot fit a future item.
    // Typical items are 10..80; residuals below ~10 are excellent (near-perfect fill).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score += 6.0; // awkward gap zone
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.15 * slack;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // residual too small for anything useful anyway; mild bonus
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 10.0 * pressure * (1.0 - fit_ratio);

    // Global residual balance: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous), unless it's a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream: keep options open, mildly penalize extreme tight packing
    // so we don't strand bins; late in stream: pack aggressively.
    score += (1.0 - progress) * 4.0 * fit_ratio;
    score -= progress * 8.0 * (1.0 - fit_ratio);

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    // Base cost of opening a new bin, reduced when current fit is poor
    // or when few bins are open (plenty of room to spread early).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.55;
        let base_cost = 15.0 + 25.0 * (1.0 - pressure);
        let penalty = if poor_fit { 20.0 } else { 0.0 };
        score += base_cost - penalty - 10.0 * progress;
        // If next item is large and won't fit anywhere typical, new bin is fine.
        if next_item_size > 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Non-linear polynomial coupling of post_residual with stream progress
    let progress_pressure = t * t * (3.0 - 2.0 * t);
    score += 40.0 * x * x * (1.0 - progress_pressure) * (1.0 - progress_pressure);
    score -= 30.0 * (1.0 - x) * (1.0 - x) * progress_pressure;
    // Smooth interaction: penalize large residuals late, small residuals early
    score += 15.0 * (x - 0.5) * (x - 0.5) * (0.5 + t);
    // Dead-space penalty when residual cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = if pr < next_item_size as f64 { pr / cap } else { 0.0 };
        score += 25.0 * unusable * (0.3 + 0.7 * progress_pressure);
        score -= 10.0 * (1.0 - (pr - nx).abs()) * progress_pressure * (1.0 - x);
    }
    // Last-chance bin reward (smooth, via fitting_bins_count)
    let fcount = fitting_bins_count as f64;
    score -= 20.0 / (1.0 + fcount * fcount);
    // Encourage balancing against mean residual (smooth quadratic)
    score += 5.0 * (pr - mean_residual) * (pr - mean_residual) / (cap * cap);
    // Mild penalty for opening many bins
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - x);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction bands.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that fall into "dead zones" (too small for typical items 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Reward residuals that can host the lookahead item exactly (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // lookahead won't fit: penalize proportionally to wasted capacity
            score += (next_item_size as f64 - pr).min(80.0) * 0.35;
        }
    }

    // Modulo-arithmetic harmony: residuals that are multiples of common item classes (10, 20, 25, 50)
    // are more reusable, reward them.
    if post_residual % 10 == 0 { score -= 5.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Integer-division thresholds: residual in the top quartile of capacity is very reusable.
    if post_residual >= bin_capacity / 4 { score -= 6.0; }
    if post_residual >= bin_capacity / 2 { score -= 4.0; }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap_f;
    if fill_ratio > 0.8 { score -= 12.0; }
    else if fill_ratio > 0.6 { score -= 6.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when this bin is already below-mean residual.
    if pr < mean_residual {
        score += 4.0;
    }

    // Early in stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap_f * 0.5 + 15.0;
        if fitting_bins_count == 0 {
            // No open bin fits: opening is mandatory; make it clearly best.
            score -= 100.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin pairs with lookahead: mild discount.
            score -= 10.0;
        }
        // If an existing bin gives a near-perfect fit (small post_residual), it beats a new bin.
        if fitting_bins_count > 0 && pr < cap_f * 0.2 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are worthless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // perfect fill, heavily reward
    } else if post_residual < 10 {
        score += 60.0; // unusable gap below typical item floor
    } else if post_residual < item_size {
        // gap smaller than current item: likely dead unless future item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 35.0;
        } else {
            score -= 15.0; // lookahead item fits the gap exactly-ish
        }
    }

    // Reward tight fits (small relative slack)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Lookahead coupling: bonus if next item fits the post_residual well
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // gap truly dead for lookahead
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += 0.8 * pressure * (mean_residual / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let waste_threshold = 0.45 * bin_capacity as f64;
        if fitting_bins_count > 0 {
            // compare best existing residual to item
            if mean_residual >= item_size as f64 * 0.8 {
                score += 80.0; // existing bins are decent, don't open new
            } else {
                score += 20.0;
            }
        }
        if post_residual as f64 > waste_threshold {
            score += 15.0; // opening bin that will stay mostly empty early on
        }
        score -= 5.0 * progress; // late in stream, consolidation matters more
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact fit for the next item
        } else if post_residual > next_item_size {
            // next item fits too: reward proportional to how small the leftover remains
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * two_step_left;
        } else {
            // next item won't fit in the remainder: penalize wasted lookahead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let pr = post_residual as f64;
    score += 0.6 * (pr - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 * (1.0 - frac) + 15.0 * (1.0 - progress);
        // allow opening a new bin if the item is huge (few good fits expected)
        if frac > 0.8 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is excellent.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: residuals too small for the smallest future item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // strongly reward this placement; otherwise penalize a bit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make a fresh bin moderately attractive
    // only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer opening new bins early, less so late (consolidate at the end).
        score += 10.0 + 20.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // If mean residual is high, open bins have plenty of room; avoid new bin.
        if mean_residual > item_size as f64 * 1.5 {
            score += 12.0;
        } else {
            score -= 5.0;
        }
    }

    // Favor bins with residual close to item size (best-fit flavor),
    // scaled by global congestion.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness * (1.0 + open_bins_count as f64 / 20.0);

    // Slight preference to fill bins with lower residuals (smaller bins first)
    // to keep larger residuals available for bigger items.
    score += 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mild congestion term: many open bins -> encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Quadratic penalty on wasted residual, amplified as stream progresses
    let norm_post = post_residual as f64 / cap;
    score += (norm_post * norm_post) * cap * (0.5 + progress);

    // Reward near-perfect fits (small post_residual) with a smooth cubic bonus
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * tightness * 10.0;

    // Coupling with lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_quality = 1.0 - gap / cap;
        score -= fit_quality.max(0.0) * fit_quality * 8.0;
        // Penalize if next item cannot fit in post_residual (dead space risk)
        if (next_item_size as f64) > post_residual as f64 {
            score += next_item_size as f64 * 0.05 * (0.5 + progress);
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    let dev = post_residual as f64 - mean_residual;
    score += dev * dev * 0.002;

    // New-bin candidate: encourage opening a fresh bin only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if next_item_size > 0 {
            // fresh bin keeps room for the next item
            score -= (cap - next_item_size as f64) * 0.02;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead space by harmonic class: tiny residuals are worthless
    if post_residual > 0 {
        let class = (post_residual / 10).min(10); // decile class of residual
        let class_waste = match class {
            0 => 25.0,            // 1..9 residual: nearly unusable
            1 => 15.0,            // 10..19
            2 => 9.0,             // 20..29
            3 => 5.0,             // 30..39
            4 => 2.5,             // 40..49
            _ => 0.0,             // >=50: still flexible
        };
        score += class_waste;
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to item size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Harmonic compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible
            score -= 18.0;
            // Extra reward if next item exactly matches harmonic class of residual
            let r_class = post_residual / 10;
            let n_class = next_item_size / 10;
            if r_class == n_class {
                score -= 8.0;
            }
            // Reward if next item leaves a "nice" residual (multiple of 10)
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_capacity && post_residual > 0 {
            // Next item cannot use this residual: penalize proportionally
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: make it unattractive unless residual landscape is bad
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Open a new bin if current item is large and fits poorly anywhere
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 50 && fitting_bins_count <= 1 {
            score -= 60.0; // prefer fresh bin for large awkward items
        }
        // Early stream: slightly prefer consolidation into open bins
        if progress < 0.3 && fitting_bins_count > 0 {
            score += 10.0;
        }
        // If mean residual is large, open bins are roomy: discourage new bin
        if mean_residual > item_size as f64 + 15.0 {
            score += 15.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    // Penalize post_residual that is a bad harmonic residue (prime-ish, non-round)
    if post_residual % 10 != 0 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are "dead". Penalize them hard.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, opening new ones is cheaper.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score -= pressure * (item_size as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped"; finishing it off is good.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    }

    // Slight late-stream preference for closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate baseline: keep it competitive but only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (waste-free placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the leftover space,
    // this placement is excellent — reward it heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover can still host the next item: mild reward proportional to slack.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: leftover too small for the next item — penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare against mean residual of open bins: bins with residual far below
    // mean are "tight" — placing there is efficient.
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.6;
    } else {
        score += (post_residual as f64 - mean_r) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity (poor fit everywhere else likely) or
    // when no real bin offers a decent fit.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly so tight fits in existing bins win...
        score += 60.0;
        // ...but discount the penalty for large items (they deserve fresh space).
        score -= fill_ratio * 80.0;
        // If many bins are open, consolidation is preferable to spreading.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight late-stream pressure to consolidate as the stream nears its end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize bins whose residual is much larger than needed (wasteful).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * 10.0;

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - next_tightness);
    } else if next_item_size > 0 {
        // Next item won't fit after this placement: mild penalty.
        score += 5.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many bins fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // Global state: prefer filling bins when many are open with high mean residual.
    if bin_residual != bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 3.0;
        score += open_bins_count as f64 * 0.3;
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Small residuals are dead space; penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic dead-space penalty, sharpened by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * x);

    // Smooth cubic coupling: dead space hurts more as stream advances
    score += 30.0 * x * x * (1.0 - x) * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly over time
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * progress);

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // penalize leaving residual too small to be useful
        score += 5.0 * (1.0 - pr / (next_item_size as f64 + 1.0)).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when residuals are high
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * progress;

    // New-bin candidate: make it moderately attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let q = (post_residual * 4 / bin_capacity) as i64; // 0..3 quarter classes
    // Penalize mid-range residuals (hard to fill), reward near-zero or large chunks.
    score += match q {
        0 => -30.0,                              // near-perfect fit
        1 => 25.0,                               // 25..50 dead space: worst class
        2 => 10.0,                               // 50..75: moderately usable
        _ => -5.0,                               // 75+: still fairly usable
    };

    // Exact-fill bonus.
    if post_residual == 0 { score -= 60.0; }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, stronger when it nearly fills remaining space
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 + 25.0 * chain_fill;
        } else {
            // post_residual too small for next item: dead-space penalty scaled
            score += 15.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (consolidate emptiness).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for opening new bins early in stream vs late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: baseline near full capacity, discounted when few bins open.
        score = cap - 10.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        if post_residual == bin_capacity { score += 5.0; } // keep new-bin identity
    }

    // Small harmonic tie-breaker on item class (integer division of item size).
    score += ((item_size / 10) as f64) * 0.5 - ((bin_residual / item_size.max(1)) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a typical item (min size 1, but practically small gaps waste
    // capacity) are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            // Tiny unusable slivers: strong penalty.
            score += 60.0 * (10.0 - pr) / 10.0;
        } else if pr < 20.0 {
            // Small gaps likely to become dead space: moderate penalty.
            score += 25.0 * (20.0 - pr) / 10.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Open-bin pressure: discourage spreading across too many bins,
    // but allow opening a new bin when existing bins would create dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    // to keep a pool of large residuals available.
    score += 0.2 * (mean_residual - pr);

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless it would create dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score += 45.0; // cancel bonus if it creates a sliver
        }
    }

    // Lookahead: if the next item fits into this bin's post_residual,
    // reward the placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // post_residual can't host next item: mild penalty
    }

    // New-bin candidate handling: an empty bin should only win when
    // no existing bin gives a reasonable fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more items to come
        // to fill them); late in the stream, consolidation matters more.
        score -= 35.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize wasted space relative to the lookahead item.
            score += 0.35 * diff;
            // If lookahead cannot fit the residual, dead space is likely.
            if post_residual < next_item_size {
                score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
            }
        }
    }

    // Reward tight fits of the current item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Penalize small unusable residuals (dead space), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 25.0 * (0.5 + 0.5 * progress);
    } else if post_residual < 20 {
        score += 8.0 * (0.5 + 0.5 * progress);
    }

    // Compare against mean residual across open bins: prefer bins that use
    // their space more aggressively than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and the item is large (then a fresh bin may be better).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * fit_ratio;
        // If lookahead is large and this bin is empty, opening is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual small relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(8);

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: slight penalty for tight fills that strand the bin
            score += 4.0 * (1.0 - (bin_residual - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill * (1.0 + 0.5 * progress);
        // prefer bins whose residual is below mean (already fuller than average)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base penalty for opening a new bin, reduced for large items
        score += 30.0 * scarcity + 15.0 * progress;
        score -= 45.0 * large_item * large_item;
        if next_item_size > item_size && next_item_size > 0 {
            score -= 8.0; // new bin may host the bigger next item too
        }
    }

    // Mild exploration noise-free tie-breaker: prefer earlier-created bins (stable count).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits, more strongly late in the stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * ((n - pr) / cap);
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Penalize opening new bins when many bins are open with large mean residual.
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score += 8.0 + 0.3 * open_bins_count as f64 + 0.1 * mean_residual;
    }

    // Mild pull toward bins with residual near the mean (balanced packing).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual below the smallest plausible item is nearly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let q = (post_residual * 4) / bin_capacity; // 0..=3 quartile class
    match q {
        0 => score -= 40.0,          // residual < 25% : tight packing, good
        1 => score += 0.0,           // 25-50% : neutral
        2 => score -= 15.0,          // 50-75% : still very usable
        _ => {}                       // >75% : nearly empty, keep base score
    }

    // Modulo-class coupling with next item: reward residuals that can host
    // the lookahead item exactly or leave a small harmonic remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            score -= 50.0; // next item divides residual perfectly
        } else if rem < 10 {
            score -= 20.0; // leaves tiny waste after next item
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for lookahead: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Integer-division threshold on item size classes (harmonic size bands).
    let item_class = item_size / 20; // 0..=4
    let post_class = post_residual / 20;
    if item_class == post_class {
        score -= 10.0; // item and leftover in same band -> balanced split
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    // or this is a large item that would fragment a bin badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 25.0 && open_bins_count > 0;
        let big_item = item_size > 60;
        if !crowded && !big_item {
            score += 120.0;
        } else if crowded {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score -= (open_bins_count as f64).recip() * 5.0;

    // Slight preference for bins below mean residual (fill the emptier ones less,
    // keep tight bins tight): filling a tighter-than-mean bin is good.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A residual that is too small for the smallest plausible item (1..100 range,
    // but small items are rare) is effectively dead space.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else if post_residual == 0 {
        // Perfect fit is the best possible outcome: reward strongly.
        score -= 80.0;
    }

    // Non-linear coupling: penalize wasted capacity fraction quadratically.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading; a new bin should be penalized.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins,
        // relaxed early in the stream when few bins exist.
        score += 15.0 + 30.0 * pressure;
    } else {
        // Reward placing into already-open bins proportionally to pressure.
        score -= 10.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement
    // (keeps a usable gap sized for the upcoming item).
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            // This placement creates a gap that cannot host the next item:
            // mild penalty proportional to the shortfall.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Slight preference for tighter fits across the fleet: bins below mean
    // residual are "fuller" and should be prioritized.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer items left to consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if next item fits perfectly into post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward if next item leaves small residual again.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin; penalize wasted residual.
            let waste = (post_residual - next_item_size) as f64; // negative
            score += 0.3 * waste.abs() * (1.0 - waste.abs() / bin_capacity as f64);
        }
        // Perfect pair fill: item + next == residual
        if (item_size + next_item_size) == bin_residual {
            score -= 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size as u32 && post_residual > 0);
        if big_item || poor_fit {
            score -= 10.0;
        } else {
            score += 45.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream: prefer tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        score += 6.0 * (post_residual as f64 - 50.0) / 50.0;
    }

    // Lookahead: if next item fits the post-residual, strongly reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // next item will need another bin anyway; mild penalty for wasting space
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline preference only when
    // open bins fit poorly, otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Time horizon: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    // Prefer bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * (1.0 + 3.0 * p2 + 5.0 * p3) * 10.0;
    score -= norm_pr * norm_pr * (2.0 + 6.0 * progress) * 20.0;
    score += norm_pr * norm_pr * norm_pr * (1.0 + 4.0 * p2) * 15.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Lookahead coupling: reward residuals that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * (5.0 + 25.0 * progress);
        } else {
            score += (nx - pr) / cap * (10.0 + 30.0 * progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 50.0 * progress;
    }

    // Penalize spreading across many open bins mildly
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Mean residual deviation penalty (smooth)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are gold; small dead space is bad.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score += 8.0; // dead space penalty: unusable sliver
    } else if post_residual <= 20 {
        score += 3.0;
    }

    // Quotient classes: how many items of average size could still fit.
    let q = post_residual / 20; // class 0..5
    score += q as f64 * 1.5;    // prefer bins that will be left "well-packed", i.e. small residual

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; residual becomes dead space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += cap_f * 0.35; // default deterrent
        if post_residual > 30 || fitting_bins_count == 0 {
            score -= cap_f * 0.5; // poor fits justify a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 5.0; // reserving for a chain still OK
        }
    }

    // Mild phase scaling: later in stream, tighten packing (avoid many half-full bins).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * phase;

    // Prefer keeping mean residual balanced: avoid bins far from mean residual.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (or the lookahead item) are "dead space".
    let min_useful = next_item_size.max(1);
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }
    // Also penalize gaps too small for anything (below the global floor of 1..=100 items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (perfect fills strongly favored)
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it
    // attractive only when the current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
    }

    // Pressure from number of open bins: discourage scattering items across
    // many bins when a reasonable fit exists here.
    score += open_bins_count as f64 * 0.3;

    // Lookahead coupling: if the next item would fit in this bin's post
    // residual, reward it; otherwise penalize leaving a near-miss gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild phase adaptation: early in the stream be more conservative about
    // creating small residuals; later, accept them more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: next item fills this bin perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Partial lookahead fit: reward proportionally to tightness.
            let tight = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 25.0 * tight;
        } else {
            // Next item cannot use this residual: penalize dead space.
            score += 8.0;
        }
    }

    // Prefer bins whose residual is below average (densely packed bins).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so existing bins are preferred,
    // but relax the penalty when the item is large (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += 15.0 - large_item_bonus;
        // Reward opening a fresh bin early in the stream when it stays usable.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Slight late-stream tightening: waste less as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}
